    private sealed class RuntimeColorWheelInput : MonoBehaviour, IPointerDownHandler, IDragHandler
    {
        public RectTransform wheelRect;
        public System.Action<Vector2> onPointerLocal;

        public void OnPointerDown(PointerEventData eventData)
        {
            Handle(eventData);
        }

        public void OnDrag(PointerEventData eventData)
        {
            Handle(eventData);
        }

        private void Handle(PointerEventData eventData)
        {
            if (wheelRect == null || onPointerLocal == null)
            {
                return;
            }

            if (!RectTransformUtility.ScreenPointToLocalPointInRectangle(
                    wheelRect,
                    eventData.position,
                    eventData.pressEventCamera,
                    out Vector2 localPoint))
            {
                return;
            }

            onPointerLocal(localPoint);
        }
    }

    private sealed class RuntimeShadowPressButtonBridge : MonoBehaviour, IPointerDownHandler, IPointerUpHandler
    {
        public MinimoCustomizationUIController owner;
        public Button button;

        public void OnPointerDown(PointerEventData eventData)
        {
            owner?.HandleShadowButtonPointerDown(button);
        }

        public void OnPointerUp(PointerEventData eventData)
        {
            owner?.HandleShadowButtonPointerUp(button);
        }
    }

    private sealed class RuntimeCategoryDropdownClickBridge : MonoBehaviour, IPointerClickHandler, ISubmitHandler
    {
        public MinimoCustomizationUIController owner;

        public void OnPointerClick(PointerEventData eventData)
        {
            owner?.HandleSceneCategoryDropdownButtonClicked();
            eventData?.Use();
        }

        public void OnSubmit(BaseEventData eventData)
        {
            owner?.HandleSceneCategoryDropdownButtonClicked();
            eventData?.Use();
        }
    }

