    private void Reset()
    {
        focusCameraToSelectedRegion = false;
        NormalizeSerializedPalettes();
        AutoWireReferences();
        BuildRows(true);
        BuildRegionButtons(true);
        RebuildVariantButtons(true);
        RefreshSavedPrefabCategoryDropdownOptions();
        RebuildSavedPrefabButtons(true);
        RefreshFromCustomizer();
    }

    private void OnValidate()
    {
        NormalizeSerializedPalettes();
        EnsureFixedVariantPreviewResolution();
        NormalizePartPreviewMeshSizeSettings();
        TryAutoAssignEmptyVariantIconSprite();
#if UNITY_EDITOR
        if (!Application.isPlaying)
        {
            EditorApplication.delayCall -= EnsureEditorPersistentDropdownOptions;
            EditorApplication.delayCall += EnsureEditorPersistentDropdownOptions;
        }
#endif
    }

    private void Awake()
    {
        MinimoUiInputCompatibility.EnsureSceneUiInput();
        NormalizeSerializedPalettes();
        EnsureFixedVariantPreviewResolution();
        NormalizePartPreviewMeshSizeSettings();
        hairRendererUnlockedByUserSelection = false;
        returningFromPlaygroundLoad = HasPendingTransferredCharacterVisual();
        deferSavedPrefabPreviewGeneration = returningFromPlaygroundLoad;
        focusCameraToSelectedRegion = false;
        enableWorldPartHoverSelection = true;
        ignoreWorldPartHoverWhenPointerOnUI = false;
        showPanelsAsTabs = true;
        enableGamepadUiControl = false;
        enableCustomColorPicker = true;
        livePreviewCustomColor = true;
        preserveSceneLayoutDuringPlay = true;
        hasExplicitPartSelection = false;
        AutoWireReferences();
        RebindGlobalEvents();
        BuildRows();
        BuildRegionButtons(true);
        SelectHairRegionByDefault();
        RefreshCategoryDropdownOptions();
        SelectEverythingCategoryByDefault();
        PrepareStartupPreviewWarmup();
        RebuildVariantButtons(true);
        RefreshSavedPrefabCategoryDropdownOptions();
        RebuildSavedPrefabButtons(true);
        RefreshFromCustomizer();
        EnsureWorldPartColliders();
        InitializePersistentCustomizationState();
        ApplyCustomizationScreenMetarigState();
    }

    private void Start()
    {
        MinimoUiInputCompatibility.EnsureSceneUiInput();
        ApplyInitialHairRendererDefaultState();
        ApplyCustomizationScreenMetarigState();
    }

    private static bool HasPendingTransferredCharacterVisual()
    {
        if (MinimoPlaygroundCharacterTransfer.HasPendingCustomizationReturn())
        {
            return true;
        }

        Scene activeScene = SceneManager.GetActiveScene();
        MinimoCharacterCustomizer[] customizers =
            MinimoUnityCompatibility.FindObjectsByType<MinimoCharacterCustomizer>(true);

        for (int i = 0; i < customizers.Length; i++)
        {
            MinimoCharacterCustomizer candidate = customizers[i];
            if (candidate == null || candidate.gameObject == null)
            {
                continue;
            }

            if (!string.Equals(candidate.gameObject.name, "CharacterVisual", StringComparison.OrdinalIgnoreCase))
            {
                continue;
            }

            if (candidate.gameObject.scene.handle != activeScene.handle)
            {
                return true;
            }
        }

        return false;
    }

    private void EnsureFixedVariantPreviewResolution()
    {
        variantPreviewTextureSize = FixedVariantPreviewTextureResolution;
        propPreviewDefaultResolution = FixedVariantPreviewTextureResolution;
        variantPreviewBackground = PreviewBackgroundColor;
    }

    private void NormalizePartPreviewMeshSizeSettings()
    {
        variantPreviewGlobalMeshSize = Mathf.Max(0.05f, variantPreviewGlobalMeshSize);
        variantPreviewCameraPaddingScale = Mathf.Clamp(variantPreviewCameraPaddingScale, 0.35f, 2.5f);
        variantPreviewButtonImageScale = Mathf.Clamp(variantPreviewButtonImageScale, 0.05f, 4f);
        if (partPreviewMeshSizeOverrides == null)
        {
            return;
        }

        for (int i = 0; i < partPreviewMeshSizeOverrides.Length; i++)
        {
            PartPreviewMeshSizeOverride entry = partPreviewMeshSizeOverrides[i];
            if (entry == null)
            {
                continue;
            }

            entry.meshSize = Mathf.Max(0.05f, entry.meshSize);
        }
    }

    private void TryAutoAssignEmptyVariantIconSprite()
    {
#if UNITY_EDITOR
        if (emptyVariantIconSprite != null)
        {
            return;
        }

        emptyVariantIconSprite = AssetDatabase.LoadAssetAtPath<Sprite>(EmptyVariantIconAssetPath);
#endif
    }

#if UNITY_EDITOR
    private void EnsureEditorPersistentDropdownOptions()
    {
        EditorApplication.delayCall -= EnsureEditorPersistentDropdownOptions;
        if (this == null || Application.isPlaying)
        {
            return;
        }

        bool changed = false;
        categoryDropdown ??= FindChildByName<TMP_Dropdown>("Dropdown");
        RectTransform categoryRoot = categoryDropdown != null ? categoryDropdown.transform as RectTransform : null;
        RectTransform categoryOptionsRoot = null;
        changed |= EnsureDropdownOptionsRoot(
            categoryRoot,
            runtimeDropdownPopupBackgroundColor,
            out categoryOptionsRoot);
        changed |= EnsureEditorDropdownOptionPreview(categoryOptionsRoot, CategoryAllOptionLabel);
        changed |= ApplyDropdownOptionColorsInRoot(categoryOptionsRoot);

        RectTransform savedRoot = savedPrefabsCategoryDropdown != null
            ? savedPrefabsCategoryDropdown.transform as RectTransform
            : null;
        RectTransform savedOptionsRoot = null;
        changed |= EnsureDropdownOptionsRoot(
            savedRoot,
            runtimeDropdownPopupBackgroundColor,
            out savedOptionsRoot);
        changed |= EnsureEditorDropdownOptionPreview(savedOptionsRoot, SavedAllOptionLabel);
        changed |= ApplyDropdownOptionColorsInRoot(savedOptionsRoot);

        if (!changed)
        {
            return;
        }

        EditorUtility.SetDirty(this);
        if (gameObject != null && gameObject.scene.IsValid())
        {
            EditorSceneManager.MarkSceneDirty(gameObject.scene);
        }
    }
#endif

    private void ApplyInitialHairRendererDefaultState()
    {
        if (customizer == null)
        {
            return;
        }

        if (returningFromPlaygroundLoad)
        {
            bool returningHairRendererEnabled = false;
            if (customizer.TryGetPartRenderer(MinimoCharacterCustomizer.PartSlot.Hair, out SkinnedMeshRenderer returningHairRenderer)
                && returningHairRenderer != null)
            {
                returningHairRendererEnabled = returningHairRenderer.enabled;
            }

            hairRendererUnlockedByUserSelection = returningHairRendererEnabled;
            UpdateVariantButtonVisuals();
            UpdateShadowStickyButtonStates();
            return;
        }

        customizer.PreserveHairDefaultOffOnStart();

        bool hairRendererEnabled = false;
        if (customizer.TryGetPartRenderer(MinimoCharacterCustomizer.PartSlot.Hair, out SkinnedMeshRenderer hairRenderer)
            && hairRenderer != null)
        {
            hairRendererEnabled = hairRenderer.enabled;
        }

        hairRendererUnlockedByUserSelection = hairRendererEnabled;
        UpdateVariantButtonVisuals();
        UpdateShadowStickyButtonStates();
    }

    private void NormalizeSerializedPalettes()
    {
        if (isNormalizingSerializedPalettes)
        {
            return;
        }

        isNormalizingSerializedPalettes = true;
        try
        {
            paletteColors = NormalizeSerializedPalette(paletteColors, DefaultGarmentTonePalette, PaletteSwatchCount);
            skinTonePalette = NormalizeSerializedPalette(skinTonePalette, DefaultSkinTonePalette, PaletteSwatchCount);
            hairTonePalette = NormalizeSerializedPalette(hairTonePalette, DefaultHairTonePalette, PaletteSwatchCount);
            garmentTonePalette = NormalizeSerializedPalette(garmentTonePalette, DefaultGarmentTonePalette, PaletteSwatchCount);
            eyesTonePalette = NormalizeSerializedPalette(eyesTonePalette, DefaultEyesTonePalette, PaletteSwatchCount);
            eyebrowsTonePalette = NormalizeSerializedPalette(eyebrowsTonePalette, DefaultEyebrowsTonePalette, PaletteSwatchCount);
            makeupTonePalette = NormalizeSerializedPalette(makeupTonePalette, DefaultMakeupTonePalette, PaletteSwatchCount);
        }
        finally
        {
            isNormalizingSerializedPalettes = false;
        }
    }

    private static Color[] NormalizeSerializedPalette(Color[] primary, Color[] fallback, int targetCount)
    {
        int count = Mathf.Max(1, targetCount);
        List<Color> merged = new List<Color>(count);
        AppendDistinctColors(merged, primary, count);
        AppendDistinctColors(merged, fallback, count);

        if (merged.Count == 0)
        {
            merged.Add(Color.white);
        }

        return SortPaletteByHueGroups(merged);
    }

    private static Color[] SortPaletteByHueGroups(List<Color> source)
    {
        if (source == null || source.Count == 0)
        {
            return Array.Empty<Color>();
        }

        const float neutralSaturationThreshold = 0.08f;
        const float hueGroupingStepDegrees = 22.5f;
        List<PaletteSortEntry> entries = new List<PaletteSortEntry>(source.Count);
        for (int i = 0; i < source.Count; i++)
        {
            Color color = source[i];
            color.a = 1f;

            Color.RGBToHSV(color, out float hue, out float saturation, out float value);
            float hueDegrees = Mathf.Repeat(hue * 360f, 360f);
            bool isNeutral = saturation <= neutralSaturationThreshold;
            int hueBucket = isNeutral
                ? -1
                : Mathf.RoundToInt(hueDegrees / hueGroupingStepDegrees);

            entries.Add(new PaletteSortEntry
            {
                color = color,
                isNeutral = isNeutral,
                hueBucket = hueBucket,
                hueDegrees = hueDegrees,
                saturation = saturation,
                value = value,
                sourceIndex = i
            });
        }

        entries.Sort((left, right) =>
        {
            if (left.isNeutral != right.isNeutral)
            {
                return left.isNeutral ? -1 : 1;
            }

            int byBucket = left.hueBucket.CompareTo(right.hueBucket);
            if (byBucket != 0)
            {
                return byBucket;
            }

            int byValue = right.value.CompareTo(left.value);
            if (byValue != 0)
            {
                return byValue;
            }

            int bySaturation = left.saturation.CompareTo(right.saturation);
            if (bySaturation != 0)
            {
                return bySaturation;
            }

            int byHue = left.hueDegrees.CompareTo(right.hueDegrees);
            if (byHue != 0)
            {
                return byHue;
            }

            return left.sourceIndex.CompareTo(right.sourceIndex);
        });

        Color[] sorted = new Color[entries.Count];
        for (int i = 0; i < entries.Count; i++)
        {
            sorted[i] = entries[i].color;
        }

        return sorted;
    }

    private void Update()
    {
        if (enableGamepadUiControl)
        {
            HandleGamepadUiInput();
        }
        else if (focusedGamepadOutlineFallback != null || gamepadFocusedStickyButton != null)
        {
            ClearGamepadFocusedOutlineFallback();
            gamepadFocusedStickyButton = null;
        }

        HandleOutsideClickCloseForTransientPanels();
        UpdateWorldPartInteraction();
        UpdateCameraFocus();
        UpdateReadyCharacterArrowLayout();
        UpdateShadowPressButtonAnimations();
        FlushPendingPersistentCustomizationSave();
    }

    private void HandleOutsideClickCloseForTransientPanels()
    {
        if (!MinimoInputBridge.GetMouseButtonDown(0))
        {
            return;
        }

        Vector2 screenPoint = MinimoInputBridge.MousePosition;

        if (customCategoryDropdownExpanded)
        {
            bool clickedDropdownToggle = IsScreenPointWithinRectTransform(customCategoryDropdownRoot, screenPoint);
            bool clickedDropdownOptions = IsScreenPointWithinRectTransform(customCategoryDropdownOptionsRoot, screenPoint);
            if (!clickedDropdownToggle && !clickedDropdownOptions)
            {
                SetCustomCategoryDropdownOpen(false);
            }
        }

        if (customSavedPrefabDropdownExpanded)
        {
            bool clickedDropdownToggle = IsScreenPointWithinRectTransform(customSavedPrefabDropdownRoot, screenPoint);
            bool clickedDropdownOptions = IsScreenPointWithinRectTransform(customSavedPrefabDropdownOptionsRoot, screenPoint);
            if (!clickedDropdownToggle && !clickedDropdownOptions)
            {
                SetCustomSavedPrefabDropdownOpen(false);
            }
        }

        if (runtimeColorPickerRoot != null && runtimeColorPickerRoot.gameObject.activeSelf)
        {
            bool clickedColorPicker = IsScreenPointWithinRectTransform(runtimeColorPickerRoot, screenPoint);
            bool clickedColorChartButton = IsScreenPointWithinRectTransform(
                colorChartButton != null ? colorChartButton.transform as RectTransform : null,
                screenPoint);
            bool clickedColorPickerCloseButton = IsScreenPointWithinRectTransform(
                runtimeColorPickerCloseButton != null ? runtimeColorPickerCloseButton.transform as RectTransform : null,
                screenPoint);

            if (!clickedColorPicker && !clickedColorChartButton && !clickedColorPickerCloseButton)
            {
                SetCustomColorPickerVisible(false);
            }
        }
    }

    private static bool IsScreenPointWithinRectTransform(RectTransform rect, Vector2 screenPoint)
    {
        if (rect == null || !rect.gameObject.activeInHierarchy)
        {
            return false;
        }

        Canvas canvas = rect.GetComponentInParent<Canvas>();
        Camera uiCamera = canvas != null && canvas.renderMode != RenderMode.ScreenSpaceOverlay
            ? canvas.worldCamera
            : null;
        return RectTransformUtility.RectangleContainsScreenPoint(rect, screenPoint, uiCamera);
    }

    private void HandleGamepadUiInput()
    {
        if (!enableGamepadUiControl)
        {
            ClearGamepadFocusedOutlineFallback();
            gamepadFocusedStickyButton = null;
            ResetGamepadDirectionalAxisState();
            return;
        }

        EventSystem eventSystem = EventSystem.current;
        if (eventSystem == null)
        {
            ClearGamepadFocusedOutlineFallback();
            return;
        }

        eventSystem.sendNavigationEvents = false;
        bool receivedShortcutInput = false;
        bool navigationBlocked = IsAnyGamepadBlockingPopupOpen();

        if (IsGamepadButtonDown(gamepadUiCancelButton))
        {
            receivedShortcutInput = true;
            if (TryHandleGamepadCancelAction())
            {
                MarkGamepadUiInteraction();
                EnsureGamepadUiSelection(eventSystem, forceReselect: true);
                UpdateGamepadFocusedVisualState(eventSystem, allowFocusVisual: true);
                return;
            }
        }

        if (!navigationBlocked)
        {
            if (IsGamepadButtonDown(gamepadUiPanelToggleButton))
            {
                receivedShortcutInput = true;
                HandleAutoRotationButton();
            }

            if (IsGamepadButtonDown(gamepadUiSaveButton))
            {
                receivedShortcutInput = true;
                HandleSavePrefab();
            }

            if (IsSavedPanelActive())
            {
                if (IsGamepadButtonDown(gamepadUiPrevButton))
                {
                    receivedShortcutInput = true;
                    SelectSavedPrefabByStep(-1);
                }

                if (IsGamepadButtonDown(gamepadUiNextButton))
                {
                    receivedShortcutInput = true;
                    SelectSavedPrefabByStep(1);
                }
            }
            else
            {
                if (IsGamepadButtonDown(gamepadUiPrevButton))
                {
                    receivedShortcutInput = true;
                    HandlePreviousSet();
                }

                if (IsGamepadButtonDown(gamepadUiNextButton))
                {
                    receivedShortcutInput = true;
                    HandleNextSet();
                }

                if (IsGamepadButtonDown(gamepadUiRandomizeButton))
                {
                    receivedShortcutInput = true;
                    HandleRandomize();
                }
            }

            if (IsGamepadButtonDown(gamepadUiSubmitButton))
            {
                receivedShortcutInput = TryHandleGamepadSubmitAction(eventSystem) || receivedShortcutInput;
            }

            ReadGamepadDirectionalPresses(out int horizontalMove, out int verticalMove);
            if ((horizontalMove != 0 || verticalMove != 0)
                && TryHandleGamepadDirectionalNavigation(eventSystem, horizontalMove, verticalMove))
            {
                receivedShortcutInput = true;
            }

            if (HandleGamepadColorPickerAnalogInput())
            {
                receivedShortcutInput = true;
            }

            if (HandleGamepadCharacterRotateInput())
            {
                receivedShortcutInput = true;
            }
        }
        else
        {
            ResetGamepadDirectionalAxisState();
        }

        if (receivedShortcutInput)
        {
            MarkGamepadUiInteraction();
        }

        bool shouldMaintainFocus = gamepadUiSelectionRefreshPending
                                   || receivedShortcutInput
                                   || IsGamepadNavigationRecentlyActive();
        if (!shouldMaintainFocus && HasConnectedGamepad())
        {
            Selectable current = ResolveSelectableFromGameObject(eventSystem.currentSelectedGameObject);
            shouldMaintainFocus = !IsSelectableInteractable(current);
        }

        if (shouldMaintainFocus)
        {
            EnsureGamepadUiSelection(eventSystem, forceReselect: false);
        }

        if (IsCustomizePanelActiveForGamepadNavigation()
            && EnsureGamepadDefaultVariantFocus(eventSystem))
        {
            receivedShortcutInput = true;
            shouldMaintainFocus = true;
            MarkGamepadUiInteraction();
        }

        bool allowGamepadFocusVisual = receivedShortcutInput || IsGamepadNavigationRecentlyActive();
        UpdateGamepadFocusedVisualState(
            eventSystem,
            allowFocusVisual: allowGamepadFocusVisual);
    }

    private bool TryHandleGamepadCancelAction()
    {
        if (IsSaveModePopupOpen())
        {
            HideSaveModePopup();
            gamepadUiSelectionRefreshPending = true;
            return true;
        }

        if (IsDeleteSavedPrefabPopupOpen())
        {
            HideDeleteSavedPrefabPopup();
            gamepadUiSelectionRefreshPending = true;
            return true;
        }

        if (customCategoryDropdownExpanded)
        {
            SetCustomCategoryDropdownOpen(false);
            if (EventSystem.current != null
                && customCategoryDropdownToggleButton != null
                && customCategoryDropdownToggleButton.gameObject.activeInHierarchy)
            {
                EventSystem.current.SetSelectedGameObject(customCategoryDropdownToggleButton.gameObject);
            }
            gamepadUiSelectionRefreshPending = true;
            return true;
        }

        if (customSavedPrefabDropdownExpanded)
        {
            SetCustomSavedPrefabDropdownOpen(false);
            if (EventSystem.current != null
                && customSavedPrefabDropdownToggleButton != null
                && customSavedPrefabDropdownToggleButton.gameObject.activeInHierarchy)
            {
                EventSystem.current.SetSelectedGameObject(customSavedPrefabDropdownToggleButton.gameObject);
            }
            gamepadUiSelectionRefreshPending = true;
            return true;
        }

        if (runtimeColorPickerRoot != null && runtimeColorPickerRoot.gameObject.activeSelf)
        {
            SetCustomColorPickerVisible(false);
            gamepadColorPickerWheelAxis = Vector2.zero;
            if (EventSystem.current != null && IsSelectableInteractable(colorChartButton))
            {
                EventSystem.current.SetSelectedGameObject(colorChartButton.gameObject);
            }
            gamepadUiSelectionRefreshPending = true;
            return true;
        }

        if (showPanelsAsTabs && IsSavedPanelActive())
        {
            SetCustomizationPanelVisible(true);
            gamepadUiSelectionRefreshPending = true;
            return true;
        }

        return false;
    }

    private bool IsAnyGamepadBlockingPopupOpen()
    {
        return IsSaveModePopupOpen() || IsDeleteSavedPrefabPopupOpen();
    }

    private bool IsSaveModePopupOpen()
    {
        return saveModePopupRoot != null && saveModePopupRoot.gameObject.activeSelf;
    }

    private bool IsDeleteSavedPrefabPopupOpen()
    {
        return deleteSavedPrefabPopupRoot != null && deleteSavedPrefabPopupRoot.gameObject.activeSelf;
    }

    private void ToggleGamepadPanelMode()
    {
        if (showPanelsAsTabs && partsPanelRoot != null && savePrefabsPanelRoot != null)
        {
            SetCustomizationPanelVisible(IsSavedPanelActive());
            gamepadUiSelectionRefreshPending = true;
            return;
        }

        ToggleSavePrefabsPanel();
        gamepadUiSelectionRefreshPending = true;
    }

    private void ResetGamepadDirectionalAxisState()
    {
        gamepadUiLeftStickUpHeld = false;
        gamepadUiLastDpadX = 0f;
        gamepadUiLastDpadY = 0f;
        gamepadUiLastMoveX = 0f;
        gamepadUiLastMoveY = 0f;
    }

    private bool IsCustomColorPickerVisible()
    {
        return runtimeColorPickerRoot != null && runtimeColorPickerRoot.gameObject.activeSelf;
    }

    private bool EnsureGamepadDefaultVariantFocus(EventSystem eventSystem)
    {
        if (eventSystem == null || IsSavedPanelActive() || customCategoryDropdownExpanded)
        {
            return false;
        }

        Selectable current = ResolveSelectableFromGameObject(eventSystem.currentSelectedGameObject);
        if (IsSelectableInteractable(current))
        {
            return false;
        }

        if (TrySelectFirstVariantButton(eventSystem))
        {
            return true;
        }

        return TrySelectFirstColorButton(eventSystem);
    }

    private void ReadGamepadDirectionalPresses(out int horizontal, out int vertical)
    {
        horizontal = 0;
        vertical = 0;

        float moveThreshold = Mathf.Clamp(gamepadUiMovePressThreshold, 0.1f, 1f);
        float dpadThreshold = Mathf.Clamp(gamepadUiDpadPressThreshold, 0.1f, 1f);
        float stickX = ReadGamepadUiAxisSafe(gamepadUiMoveXAxis, useDpadFallback: false);
        float stickY = ReadGamepadUiAxisSafe(gamepadUiMoveYAxis, useDpadFallback: false);
        float dpadX = ReadGamepadUiAxisSafe(gamepadUiDpadXAxis, useDpadFallback: true);
        float dpadY = ReadGamepadUiAxisSafe(gamepadUiDpadYAxis, useDpadFallback: true);

        int stickHorizontal = 0;
        if (stickX >= moveThreshold && gamepadUiLastMoveX < moveThreshold)
        {
            stickHorizontal = 1;
        }
        else if (stickX <= -moveThreshold && gamepadUiLastMoveX > -moveThreshold)
        {
            stickHorizontal = -1;
        }

        int dpadHorizontal = 0;
        if (dpadX >= dpadThreshold && gamepadUiLastDpadX < dpadThreshold)
        {
            dpadHorizontal = 1;
        }
        else if (dpadX <= -dpadThreshold && gamepadUiLastDpadX > -dpadThreshold)
        {
            dpadHorizontal = -1;
        }

        int stickVertical = 0;
        if (stickY >= moveThreshold && gamepadUiLastMoveY < moveThreshold)
        {
            stickVertical = 1;
        }
        else if (stickY <= -moveThreshold && gamepadUiLastMoveY > -moveThreshold)
        {
            stickVertical = -1;
        }

        int dpadVertical = 0;
        if (dpadY >= dpadThreshold && gamepadUiLastDpadY < dpadThreshold)
        {
            dpadVertical = 1;
        }
        else if (dpadY <= -dpadThreshold && gamepadUiLastDpadY > -dpadThreshold)
        {
            dpadVertical = -1;
        }

        horizontal = stickHorizontal != 0 ? stickHorizontal : dpadHorizontal;
        vertical = stickVertical != 0 ? stickVertical : dpadVertical;

        gamepadUiLastMoveX = stickX;
        gamepadUiLastMoveY = stickY;
        gamepadUiLastDpadX = dpadX;
        gamepadUiLastDpadY = dpadY;
    }

    private bool TryHandleGamepadSubmitAction(EventSystem eventSystem)
    {
        if (IsCustomColorPickerVisible())
        {
            if (runtimeHueSlider == null || runtimeSaturationSlider == null || runtimeValueSlider == null)
            {
                return false;
            }

            Color pickedColor = Color.HSVToRGB(
                runtimeHueSlider.value,
                runtimeSaturationSlider.value,
                runtimeValueSlider.value);
            ApplyColorToSelectedRegion(pickedColor);
            return true;
        }

        if (customCategoryDropdownExpanded)
        {
            if (customCategoryDropdownOptionButtons.Count <= 0)
            {
                return false;
            }

            int optionIndex = Mathf.Clamp(selectedCategoryDropdownIndex, 0, customCategoryDropdownOptionButtons.Count - 1);
            HandleCustomCategoryOptionSelected(optionIndex);
            SetCustomCategoryDropdownOpen(false);
            if (customCategoryDropdownToggleButton != null && customCategoryDropdownToggleButton.gameObject.activeInHierarchy)
            {
                eventSystem?.SetSelectedGameObject(customCategoryDropdownToggleButton.gameObject);
            }

            return true;
        }

        if (customSavedPrefabDropdownExpanded)
        {
            if (customSavedPrefabDropdownOptionButtons.Count <= 0)
            {
                return false;
            }

            int optionIndex = Mathf.Clamp(
                selectedSavedPrefabCategoryDropdownIndex,
                0,
                customSavedPrefabDropdownOptionButtons.Count - 1);
            HandleCustomSavedPrefabOptionSelected(optionIndex);
            return true;
        }

        if (eventSystem == null || eventSystem.currentSelectedGameObject == null)
        {
            return false;
        }

        Selectable currentSelection = ResolveSelectableFromGameObject(eventSystem.currentSelectedGameObject);
        Button selectedButton = ResolveButtonFromSelectable(currentSelection);
        if (TryFindRegionButtonIndex(selectedButton, out _))
        {
            return true;
        }

        bool wasDropdownOpen = customCategoryDropdownExpanded;
        bool wasSavedDropdownOpen = customSavedPrefabDropdownExpanded;
        bool wasColorPickerVisible = IsCustomColorPickerVisible();
        BaseEventData baseEvent = new BaseEventData(eventSystem);
        ExecuteEvents.Execute(eventSystem.currentSelectedGameObject, baseEvent, ExecuteEvents.submitHandler);
        if (!wasColorPickerVisible && IsCustomColorPickerVisible())
        {
            gamepadColorPickerWheelAxis = Vector2.zero;
        }

        if (!wasDropdownOpen && customCategoryDropdownExpanded)
        {
            TryNavigateCategoryDropdownOptions(eventSystem, 0);
        }

        if (!wasSavedDropdownOpen && customSavedPrefabDropdownExpanded)
        {
            TryNavigateSavedPrefabDropdownOptions(eventSystem, 0);
        }

        return true;
    }

    private bool HandleGamepadColorPickerAnalogInput()
    {
        if (!IsCustomColorPickerVisible()
            || runtimeHueSlider == null
            || runtimeSaturationSlider == null
            || runtimeValueSlider == null)
        {
            return false;
        }

        float axisX = ReadGamepadUiAxisSafe(gamepadUiMoveXAxis, useDpadFallback: false);
        float axisY = ReadGamepadUiAxisSafe(gamepadUiMoveYAxis, useDpadFallback: false);
        float dpadX = ReadGamepadUiAxisSafe(gamepadUiDpadXAxis, useDpadFallback: true);
        float dpadY = ReadGamepadUiAxisSafe(gamepadUiDpadYAxis, useDpadFallback: true);
        if (Mathf.Abs(axisX) < Mathf.Abs(dpadX))
        {
            axisX = dpadX;
        }

        if (Mathf.Abs(axisY) < Mathf.Abs(dpadY))
        {
            axisY = dpadY;
        }

        Vector2 axis = new Vector2(axisX, axisY);
        if (axis.sqrMagnitude < 0.03f)
        {
            return false;
        }

        if (gamepadColorPickerWheelAxis.sqrMagnitude < 0.0001f)
        {
            float hueAngle = runtimeHueSlider.value * Mathf.PI * 2f;
            float saturation = runtimeSaturationSlider.value;
            gamepadColorPickerWheelAxis = new Vector2(Mathf.Cos(hueAngle), Mathf.Sin(hueAngle))
                                          * Mathf.Clamp01(saturation);
        }

        float delta = Mathf.Max(0.0001f, Time.unscaledDeltaTime) * Mathf.Max(0.1f, gamepadColorPickerStickSpeed);
        gamepadColorPickerWheelAxis += axis * delta;
        if (gamepadColorPickerWheelAxis.sqrMagnitude > 1f)
        {
            gamepadColorPickerWheelAxis = gamepadColorPickerWheelAxis.normalized;
        }

        float saturationValue = Mathf.Clamp01(gamepadColorPickerWheelAxis.magnitude);
        float hueValue = Mathf.Atan2(gamepadColorPickerWheelAxis.y, gamepadColorPickerWheelAxis.x) / (Mathf.PI * 2f);
        if (hueValue < 0f)
        {
            hueValue += 1f;
        }

        float nextValue = runtimeValueSlider.value + axisY * gamepadColorPickerValueStep * delta * 10f;
        SetCustomColorFromHSV(hueValue, saturationValue, Mathf.Clamp01(nextValue), false);
        return true;
    }

    private bool HandleGamepadCharacterRotateInput()
    {
        if (!gamepadLeftStickRotateCharacter
            || customizer == null
            || IsSavedPanelActive()
            || IsAnyGamepadBlockingPopupOpen()
            || IsCustomColorPickerVisible()
            || customCategoryDropdownExpanded
            || autoRotationEnabled)
        {
            return false;
        }

        float axisX = ReadGamepadUiAxisSafe(gamepadUiRotateXAxis, useDpadFallback: false);
        if (Mathf.Abs(axisX) < Mathf.Clamp01(gamepadCharacterRotateDeadzone))
        {
            return false;
        }

        float clamped = Mathf.Sign(axisX)
                        * Mathf.InverseLerp(
                            Mathf.Clamp01(gamepadCharacterRotateDeadzone),
                            1f,
                            Mathf.Abs(axisX));
        float yawDegrees = -clamped * Mathf.Max(0f, gamepadCharacterRotateDegreesPerSecond) * Time.unscaledDeltaTime;
        customizer.transform.Rotate(Vector3.up, yawDegrees, Space.World);
        return true;
    }

    private bool TryHandleGamepadDirectionalNavigation(EventSystem eventSystem, int horizontalMove, int verticalMove)
    {
        if (eventSystem == null || (horizontalMove == 0 && verticalMove == 0))
        {
            return false;
        }

        if (IsCustomColorPickerVisible())
        {
            return false;
        }

        if (customCategoryDropdownExpanded)
        {
            return TryNavigateCategoryDropdownOptions(eventSystem, verticalMove);
        }

        if (customSavedPrefabDropdownExpanded)
        {
            return TryNavigateSavedPrefabDropdownOptions(eventSystem, verticalMove);
        }

        Selectable current = ResolveSelectableFromGameObject(eventSystem.currentSelectedGameObject);
        if (!IsSelectableInteractable(current))
        {
            return EnsureGamepadDefaultVariantFocus(eventSystem);
        }

        Vector2 direction = new Vector2(horizontalMove, verticalMove);
        Button currentButton = ResolveButtonFromSelectable(current);
        GamepadFocusZone zone = ResolveGamepadFocusZone(current);
        switch (zone)
        {
            case GamepadFocusZone.Variant:
                {
                    List<Button> buttons = CollectVariantButtonsForGamepad();
                    if (TryMoveFocusInButtonGroup(eventSystem, buttons, currentButton, direction, out _))
                    {
                        return true;
                    }

                    if (verticalMove > 0)
                    {
                        return TrySelectFirstColorButton(eventSystem);
                    }

                    if (horizontalMove < 0)
                    {
                        return TrySelectFirstMaterialButton(eventSystem);
                    }

                    return false;
                }

            case GamepadFocusZone.Color:
                {
                    List<Button> buttons = CollectColorButtonsForGamepad();
                    if (TryMoveFocusInButtonGroup(eventSystem, buttons, currentButton, direction, out _))
                    {
                        return true;
                    }

                    if (horizontalMove < 0)
                    {
                        return TrySelectFirstMaterialButton(eventSystem);
                    }

                    if (verticalMove > 0)
                    {
                        return TrySelectCategoryDropdownToggle(eventSystem);
                    }

                    if (verticalMove < 0)
                    {
                        return TrySelectFirstVariantButton(eventSystem);
                    }

                    return false;
                }

            case GamepadFocusZone.CategoryDropdown:
                {
                    if (horizontalMove < 0)
                    {
                        return TrySelectFirstMaterialButton(eventSystem);
                    }

                    if (verticalMove > 0)
                    {
                        return TrySelectFirstRegionButton(eventSystem, autoApply: true);
                    }

                    if (verticalMove < 0)
                    {
                        return TrySelectFirstColorButton(eventSystem);
                    }

                    return false;
                }

            case GamepadFocusZone.MaterialChannel:
                {
                    List<Button> buttons = CollectMaterialButtonsForGamepad();
                    if (TryMoveFocusInButtonGroup(eventSystem, buttons, currentButton, new Vector2(horizontalMove, 0f), out _))
                    {
                        return true;
                    }

                    if (horizontalMove > 0)
                    {
                        return TrySelectFirstColorButton(eventSystem);
                    }

                    if (verticalMove > 0)
                    {
                        return TrySelectFirstRegionButton(eventSystem, autoApply: true);
                    }

                    if (verticalMove < 0)
                    {
                        return TrySelectFirstColorButton(eventSystem);
                    }

                    return false;
                }

            case GamepadFocusZone.Region:
                {
                    List<Button> buttons = CollectRegionButtonsForGamepad();
                    if (horizontalMove != 0
                        && TryMoveFocusInButtonGroup(eventSystem, buttons, currentButton, new Vector2(horizontalMove, 0f), out Button movedRegion))
                    {
                        ApplyFocusedRegionByButton(movedRegion);
                        return true;
                    }

                    if (verticalMove > 0)
                    {
                        return TrySelectFirstPageButton(eventSystem);
                    }

                    if (verticalMove < 0)
                    {
                        return TrySelectCategoryDropdownToggle(eventSystem);
                    }

                    return false;
                }

            case GamepadFocusZone.Page:
                {
                    List<Button> buttons = CollectPageButtonsForGamepad();
                    if (horizontalMove != 0
                        && TryMoveFocusInButtonGroup(eventSystem, buttons, currentButton, new Vector2(horizontalMove, 0f), out _))
                    {
                        return true;
                    }

                    if (verticalMove < 0)
                    {
                        if (IsSavedPanelActive())
                        {
                            return TrySelectFirstSavedButton(eventSystem);
                        }

                        return TrySelectFirstRegionButton(eventSystem, autoApply: false);
                    }

                    return false;
                }

            case GamepadFocusZone.Saved:
                {
                    return TryHandleSavedPanelNavigation(eventSystem, currentButton, horizontalMove, verticalMove);
                }
        }

        if (verticalMove > 0)
        {
            return TrySelectFirstColorButton(eventSystem);
        }

        return false;
    }

    private bool TryNavigateCategoryDropdownOptions(EventSystem eventSystem, int verticalMove)
    {
        if (eventSystem == null || !customCategoryDropdownExpanded || customCategoryDropdownOptionButtons.Count == 0)
        {
            return false;
        }

        if (verticalMove == 0)
        {
            int initialIndex = Mathf.Clamp(selectedCategoryDropdownIndex, 0, customCategoryDropdownOptionButtons.Count - 1);
            Button initial = customCategoryDropdownOptionButtons[initialIndex];
            return IsSelectableInteractable(initial) && TrySelectGamepadSelectable(eventSystem, initial);
        }

        int nextIndex = selectedCategoryDropdownIndex + (verticalMove > 0 ? -1 : 1);
        if (nextIndex < 0)
        {
            nextIndex = customCategoryDropdownOptionButtons.Count - 1;
        }
        else if (nextIndex >= customCategoryDropdownOptionButtons.Count)
        {
            nextIndex = 0;
        }

        selectedCategoryDropdownIndex = Mathf.Clamp(nextIndex, 0, customCategoryDropdownOptionButtons.Count - 1);
        Button button = customCategoryDropdownOptionButtons[selectedCategoryDropdownIndex];
        return IsSelectableInteractable(button) && TrySelectGamepadSelectable(eventSystem, button);
    }

    private bool TryNavigateSavedPrefabDropdownOptions(EventSystem eventSystem, int verticalMove)
    {
        if (eventSystem == null || !customSavedPrefabDropdownExpanded || customSavedPrefabDropdownOptionButtons.Count == 0)
        {
            return false;
        }

        if (verticalMove == 0)
        {
            int initialIndex = Mathf.Clamp(
                selectedSavedPrefabCategoryDropdownIndex,
                0,
                customSavedPrefabDropdownOptionButtons.Count - 1);
            Button initial = customSavedPrefabDropdownOptionButtons[initialIndex];
            return IsSelectableInteractable(initial) && TrySelectGamepadSelectable(eventSystem, initial);
        }

        int nextIndex = selectedSavedPrefabCategoryDropdownIndex + (verticalMove > 0 ? -1 : 1);
        if (nextIndex < 0)
        {
            nextIndex = customSavedPrefabDropdownOptionButtons.Count - 1;
        }
        else if (nextIndex >= customSavedPrefabDropdownOptionButtons.Count)
        {
            nextIndex = 0;
        }

        selectedSavedPrefabCategoryDropdownIndex = Mathf.Clamp(
            nextIndex,
            0,
            customSavedPrefabDropdownOptionButtons.Count - 1);
        Button button = customSavedPrefabDropdownOptionButtons[selectedSavedPrefabCategoryDropdownIndex];
        return IsSelectableInteractable(button) && TrySelectGamepadSelectable(eventSystem, button);
    }

    private GamepadFocusZone ResolveGamepadFocusZone(Selectable selectable)
    {
        if (selectable == null)
        {
            return GamepadFocusZone.Unknown;
        }

        if (customCategoryDropdownExpanded
            && TryFindCategoryDropdownOptionIndex(ResolveButtonFromSelectable(selectable), out _))
        {
            return GamepadFocusZone.CategoryDropdownOption;
        }

        Button button = ResolveButtonFromSelectable(selectable);
        if (TryFindVariantButtonIndex(button, out _))
        {
            return GamepadFocusZone.Variant;
        }

        if (TryFindColorButtonIndex(button, out _))
        {
            return GamepadFocusZone.Color;
        }

        if (TryFindMaterialButtonIndex(button, out _))
        {
            return GamepadFocusZone.MaterialChannel;
        }

        if (TryFindRegionButtonIndex(button, out _))
        {
            return GamepadFocusZone.Region;
        }

        if (TryFindPageButtonIndex(button, out _))
        {
            return GamepadFocusZone.Page;
        }

        if (button == customCategoryDropdownToggleButton || selectable == categoryDropdown)
        {
            return GamepadFocusZone.CategoryDropdown;
        }

        if (TryFindSavedButtonIndex(button, out _))
        {
            return GamepadFocusZone.Saved;
        }

        return GamepadFocusZone.Unknown;
    }

    private static Button ResolveButtonFromSelectable(Selectable selectable)
    {
        if (selectable == null)
        {
            return null;
        }

        if (selectable is Button button)
        {
            return button;
        }

        return selectable.GetComponent<Button>();
    }

    private bool TryMoveFocusInButtonGroup(
        EventSystem eventSystem,
        List<Button> buttons,
        Button current,
        Vector2 direction,
        out Button movedButton)
    {
        movedButton = null;
        if (eventSystem == null || buttons == null || buttons.Count == 0)
        {
            return false;
        }

        List<Button> interactables = new List<Button>();
        for (int i = 0; i < buttons.Count; i++)
        {
            if (IsSelectableInteractable(buttons[i]))
            {
                interactables.Add(buttons[i]);
            }
        }

        if (interactables.Count == 0)
        {
            return false;
        }

        if (current == null || !interactables.Contains(current))
        {
            movedButton = interactables[0];
            return TrySelectGamepadSelectable(eventSystem, movedButton);
        }

        Vector2 normalizedDirection = direction.sqrMagnitude > 0.0001f
            ? direction.normalized
            : Vector2.up;
        Vector2 currentCenter = GetSelectableWorldCenter2D(current);

        float bestScore = float.MaxValue;
        Button best = null;
        for (int i = 0; i < interactables.Count; i++)
        {
            Button candidate = interactables[i];
            if (candidate == null || candidate == current)
            {
                continue;
            }

            Vector2 candidateCenter = GetSelectableWorldCenter2D(candidate);
            Vector2 delta = candidateCenter - currentCenter;
            if (delta.sqrMagnitude <= 0.0001f)
            {
                continue;
            }

            float dot = Vector2.Dot(delta.normalized, normalizedDirection);
            if (dot <= 0.18f)
            {
                continue;
            }

            float score = (1f - dot) * 8000f + delta.sqrMagnitude;
            if (score < bestScore)
            {
                bestScore = score;
                best = candidate;
            }
        }

        if (best == null)
        {
            return false;
        }

        movedButton = best;
        return TrySelectGamepadSelectable(eventSystem, best);
    }

    private static Vector2 GetSelectableWorldCenter2D(Selectable selectable)
    {
        RectTransform rect = selectable != null ? selectable.transform as RectTransform : null;
        if (rect == null)
        {
            return Vector2.zero;
        }

        Vector3 center = rect.TransformPoint(rect.rect.center);
        return new Vector2(center.x, center.y);
    }

    private bool TrySelectFirstVariantButton(EventSystem eventSystem)
    {
        List<Button> variants = CollectVariantButtonsForGamepad();
        for (int i = 0; i < variants.Count; i++)
        {
            if (IsSelectableInteractable(variants[i]) && TrySelectGamepadSelectable(eventSystem, variants[i]))
            {
                return true;
            }
        }

        return false;
    }

    private bool TrySelectFirstColorButton(EventSystem eventSystem)
    {
        List<Button> colors = CollectColorButtonsForGamepad();
        for (int i = 0; i < colors.Count; i++)
        {
            if (IsSelectableInteractable(colors[i]) && TrySelectGamepadSelectable(eventSystem, colors[i]))
            {
                return true;
            }
        }

        return false;
    }

    private bool TrySelectCategoryDropdownToggle(EventSystem eventSystem)
    {
        if (customCategoryDropdownToggleButton != null
            && IsSelectableInteractable(customCategoryDropdownToggleButton)
            && TrySelectGamepadSelectable(eventSystem, customCategoryDropdownToggleButton))
        {
            return true;
        }

        if (categoryDropdown != null
            && IsSelectableInteractable(categoryDropdown)
            && TrySelectGamepadSelectable(eventSystem, categoryDropdown))
        {
            return true;
        }

        return false;
    }

    private bool TrySelectFirstMaterialButton(EventSystem eventSystem)
    {
        List<Button> materials = CollectMaterialButtonsForGamepad();
        for (int i = 0; i < materials.Count; i++)
        {
            if (IsSelectableInteractable(materials[i]) && TrySelectGamepadSelectable(eventSystem, materials[i]))
            {
                return true;
            }
        }

        return false;
    }

    private bool TrySelectFirstRegionButton(EventSystem eventSystem, bool autoApply)
    {
        List<Button> regionsForGamepad = CollectRegionButtonsForGamepad();
        for (int i = 0; i < regionsForGamepad.Count; i++)
        {
            Button button = regionsForGamepad[i];
            if (!IsSelectableInteractable(button))
            {
                continue;
            }

            bool moved = TrySelectGamepadSelectable(eventSystem, button);
            if (autoApply)
            {
                ApplyFocusedRegionByButton(button);
            }

            return moved;
        }

        return false;
    }

    private bool TrySelectFirstPageButton(EventSystem eventSystem)
    {
        if (!Application.isPlaying)
        {
            return false;
        }

        List<Button> pages = CollectPageButtonsForGamepad();
        for (int i = 0; i < pages.Count; i++)
        {
            if (IsSelectableInteractable(pages[i]) && TrySelectGamepadSelectable(eventSystem, pages[i]))
            {
                return true;
            }
        }

        return false;
    }

    private bool TrySelectFirstSavedButton(EventSystem eventSystem)
    {
        if (selectedSavedPrefabIndex >= 0 && selectedSavedPrefabIndex < savedPrefabButtons.Count)
        {
            SavedPrefabButtonEntry selectedEntry = savedPrefabButtons[selectedSavedPrefabIndex];
            if (selectedEntry != null
                && IsSelectableInteractable(selectedEntry.button)
                && TrySelectGamepadSelectable(eventSystem, selectedEntry.button))
            {
                return true;
            }
        }

        for (int i = 0; i < savedPrefabButtons.Count; i++)
        {
            SavedPrefabButtonEntry entry = savedPrefabButtons[i];
            if (entry != null
                && IsSelectableInteractable(entry.button)
                && TrySelectGamepadSelectable(eventSystem, entry.button))
            {
                return true;
            }
        }

        List<Button> savedButtons = CollectSavedButtonsForGamepad();
        for (int i = 0; i < savedButtons.Count; i++)
        {
            if (IsSelectableInteractable(savedButtons[i]) && TrySelectGamepadSelectable(eventSystem, savedButtons[i]))
            {
                return true;
            }
        }

        return false;
    }

    private bool TryHandleSavedPanelNavigation(EventSystem eventSystem, Button currentButton, int horizontalMove, int verticalMove)
    {
        List<Button> buttons = CollectSavedButtonsForGamepad();
        Vector2 direction = new Vector2(horizontalMove, verticalMove);
        if (TryMoveFocusInButtonGroup(eventSystem, buttons, currentButton, direction, out _))
        {
            return true;
        }

        if (eventSystem == null)
        {
            return false;
        }

        if (verticalMove > 0)
        {
            return TrySelectFirstPageButton(eventSystem);
        }

        if (savedPrefabButtons.Count == 0)
        {
            return false;
        }

        int step = 0;
        if (verticalMove < 0 || horizontalMove > 0)
        {
            step = 1;
        }
        else if (horizontalMove < 0)
        {
            step = -1;
        }

        if (step == 0)
        {
            return false;
        }

        int currentIndex = selectedSavedPrefabIndex;
        if (TryFindSavedButtonIndex(currentButton, out int focusedSavedIndex))
        {
            currentIndex = focusedSavedIndex;
        }

        if (currentIndex < 0 || currentIndex >= savedPrefabButtons.Count)
        {
            currentIndex = step > 0 ? 0 : savedPrefabButtons.Count - 1;
        }

        int nextIndex = Mathf.Clamp(currentIndex + step, 0, savedPrefabButtons.Count - 1);
        if (nextIndex == currentIndex)
        {
            return false;
        }

        SavedPrefabButtonEntry nextEntry = savedPrefabButtons[nextIndex];
        return nextEntry != null
               && IsSelectableInteractable(nextEntry.button)
               && TrySelectGamepadSelectable(eventSystem, nextEntry.button);
    }

    private bool TrySelectGamepadSelectable(EventSystem eventSystem, Selectable selectable)
    {
        if (eventSystem == null || !IsSelectableInteractable(selectable))
        {
            return false;
        }

        eventSystem.SetSelectedGameObject(selectable.gameObject);
        EnsureGamepadSelectableVisible(selectable);
        return true;
    }

    private void EnsureGamepadSelectableVisible(Selectable selectable)
    {
        if (selectable == null)
        {
            return;
        }

        RectTransform targetRect = selectable.transform as RectTransform;
        if (targetRect == null)
        {
            return;
        }

        if (bodyPartsScroll != null
            && bodyPartsContent != null
            && targetRect.IsChildOf(bodyPartsContent))
        {
            EnsureRectVisibleInScrollRect(bodyPartsScroll, targetRect, 10f);
            return;
        }

        if (savePrefabsScroll != null
            && savePrefabsContent != null
            && targetRect.IsChildOf(savePrefabsContent))
        {
            EnsureRectVisibleInScrollRect(savePrefabsScroll, targetRect, 10f);
        }
    }

    private static void EnsureRectVisibleInScrollRect(ScrollRect scrollRect, RectTransform target, float padding)
    {
        if (scrollRect == null || target == null || !target.gameObject.activeInHierarchy)
        {
            return;
        }

        RectTransform viewport = scrollRect.viewport != null
            ? scrollRect.viewport
            : scrollRect.GetComponent<RectTransform>();
        RectTransform content = scrollRect.content;
        if (viewport == null || content == null || !target.IsChildOf(content))
        {
            return;
        }

        Canvas.ForceUpdateCanvases();

        Vector3[] corners = new Vector3[4];
        target.GetWorldCorners(corners);
        float minY = float.MaxValue;
        float maxY = float.MinValue;
        for (int i = 0; i < corners.Length; i++)
        {
            Vector3 viewportLocal = viewport.InverseTransformPoint(corners[i]);
            minY = Mathf.Min(minY, viewportLocal.y);
            maxY = Mathf.Max(maxY, viewportLocal.y);
        }

        Vector2 anchored = content.anchoredPosition;

        Rect viewportRect = viewport.rect;
        float paddingValue = Mathf.Max(0f, padding);
        if (scrollRect.vertical)
        {
            float paddedMinY = viewportRect.yMin + paddingValue;
            float paddedMaxY = viewportRect.yMax - paddingValue;
            float offsetY = 0f;
            if (maxY > paddedMaxY)
            {
                offsetY = paddedMaxY - maxY;
            }
            else if (minY < paddedMinY)
            {
                offsetY = paddedMinY - minY;
            }

            if (Mathf.Abs(offsetY) > 0.01f)
            {
                anchored.y += offsetY;
                float maxScrollY = Mathf.Max(0f, content.rect.height - viewport.rect.height);
                anchored.y = Mathf.Clamp(anchored.y, 0f, maxScrollY);
            }
        }

        if (scrollRect.horizontal)
        {
            float minX = float.MaxValue;
            float maxX = float.MinValue;
            for (int i = 0; i < corners.Length; i++)
            {
                Vector3 viewportLocal = viewport.InverseTransformPoint(corners[i]);
                minX = Mathf.Min(minX, viewportLocal.x);
                maxX = Mathf.Max(maxX, viewportLocal.x);
            }

            float paddedMinX = viewportRect.xMin + paddingValue;
            float paddedMaxX = viewportRect.xMax - paddingValue;
            float offsetX = 0f;
            if (maxX > paddedMaxX)
            {
                offsetX = paddedMaxX - maxX;
            }
            else if (minX < paddedMinX)
            {
                offsetX = paddedMinX - minX;
            }

            if (Mathf.Abs(offsetX) > 0.01f)
            {
                anchored.x += offsetX;
                float minScrollX = Mathf.Min(0f, viewport.rect.width - content.rect.width);
                anchored.x = Mathf.Clamp(anchored.x, minScrollX, 0f);
            }
        }

        content.anchoredPosition = anchored;
        scrollRect.StopMovement();
    }

    private void ApplyFocusedRegionByButton(Button button)
    {
        if (!TryFindRegionButtonIndex(button, out int regionIndex))
        {
            return;
        }

        if (regionIndex == selectedRegionIndex)
        {
            return;
        }

        button?.onClick?.Invoke();
    }

    private bool TryFindVariantButtonIndex(Button button, out int index)
    {
        index = -1;
        if (button == null)
        {
            return false;
        }

        for (int i = 0; i < variantButtons.Count; i++)
        {
            VariantButtonEntry entry = variantButtons[i];
            if (entry?.button == button)
            {
                index = i;
                return true;
            }
        }

        return false;
    }

    private bool TryFindColorButtonIndex(Button button, out int index)
    {
        index = -1;
        if (button == null)
        {
            return false;
        }

        for (int i = 0; i < colorButtons.Count; i++)
        {
            ColorButtonEntry entry = colorButtons[i];
            if (entry?.button == button)
            {
                index = i;
                return true;
            }
        }

        if (button == colorChartButton)
        {
            index = colorButtons.Count;
            return true;
        }

        if (button == randomColorButton)
        {
            index = colorButtons.Count + (colorChartButton != null ? 1 : 0);
            return true;
        }

        return false;
    }

