    private List<Button> CollectVariantButtonsForGamepad()
    {
        List<Button> buttons = new List<Button>();
        for (int i = 0; i < variantButtons.Count; i++)
        {
            VariantButtonEntry entry = variantButtons[i];
            if (entry?.button == null)
            {
                continue;
            }

            if (!entry.isRandomButton)
            {
                buttons.Add(entry.button);
            }
        }

        if (buttons.Count == 0)
        {
            for (int i = 0; i < variantButtons.Count; i++)
            {
                if (variantButtons[i]?.button != null)
                {
                    buttons.Add(variantButtons[i].button);
                }
            }
        }

        return buttons;
    }

