    private bool ReadGamepadLeftStickUpPressed()
    {
        float axis = ReadGamepadUiAxisSafe(gamepadUiMoveYAxis, useDpadFallback: false);
        float threshold = Mathf.Clamp(gamepadUiMovePressThreshold, 0.1f, 1f);
        bool isHeld = axis >= threshold;
        bool pressedThisFrame = isHeld && !gamepadUiLeftStickUpHeld;
        gamepadUiLeftStickUpHeld = isHeld;
        return pressedThisFrame;
    }

    private int ReadGamepadDpadHorizontalPress()
    {
        float axis = ReadGamepadUiAxisSafe(gamepadUiDpadXAxis, useDpadFallback: true);
        float threshold = Mathf.Clamp(gamepadUiDpadPressThreshold, 0.1f, 1f);
        int press = 0;
        if (axis >= threshold && gamepadUiLastDpadX < threshold)
        {
            press = 1;
        }
        else if (axis <= -threshold && gamepadUiLastDpadX > -threshold)
        {
            press = -1;
        }

        gamepadUiLastDpadX = axis;
        return press;
    }

    private float ReadGamepadUiAxisSafe(string axisName, bool useDpadFallback)
    {
        if (!string.IsNullOrWhiteSpace(axisName) && !missingGamepadUiAxisNames.Contains(axisName))
        {
            try
            {
                return Mathf.Clamp(MinimoInputBridge.GetAxisRaw(axisName), -1f, 1f);
            }
            catch (Exception)
            {
                missingGamepadUiAxisNames.Add(axisName);
            }
        }

#if ENABLE_INPUT_SYSTEM
        Gamepad gamepad = Gamepad.current;
        if (gamepad != null)
        {
            bool preferRightStickHorizontal = !string.IsNullOrWhiteSpace(axisName)
                                              && string.Equals(axisName, gamepadUiRotateXAxis, StringComparison.OrdinalIgnoreCase);
            bool preferHorizontal = !string.IsNullOrWhiteSpace(axisName)
                                    && (string.Equals(axisName, gamepadUiMoveXAxis, StringComparison.OrdinalIgnoreCase)
                                        || string.Equals(axisName, gamepadUiDpadXAxis, StringComparison.OrdinalIgnoreCase)
                                        || axisName.IndexOf("x", StringComparison.OrdinalIgnoreCase) >= 0);
            if (useDpadFallback)
            {
                return Mathf.Clamp(preferHorizontal ? gamepad.dpad.x.ReadValue() : gamepad.dpad.y.ReadValue(), -1f, 1f);
            }

            if (preferRightStickHorizontal)
            {
                return Mathf.Clamp(gamepad.rightStick.x.ReadValue(), -1f, 1f);
            }

            return Mathf.Clamp(preferHorizontal ? gamepad.leftStick.x.ReadValue() : gamepad.leftStick.y.ReadValue(), -1f, 1f);
        }
#endif
        return 0f;
    }

    private bool TryMoveGamepadSelectionToUpperPanels(EventSystem eventSystem)
    {
        if (eventSystem == null || !IsCustomizePanelActiveForGamepadNavigation())
        {
            return false;
        }

        Selectable current = ResolveSelectableFromGameObject(eventSystem.currentSelectedGameObject);
        if (!IsSelectableInteractable(current))
        {
            return false;
        }

        RebuildGamepadUpperPanelSequence();
        if (gamepadUpperPanelSequence.Count == 0)
        {
            return false;
        }

        int currentUpperIndex = gamepadUpperPanelSequence.IndexOf(current);
        if (currentUpperIndex >= 0)
        {
            int nextIndex = currentUpperIndex - 1;
            if (nextIndex < 0)
            {
                return false;
            }

            Selectable nextUpper = gamepadUpperPanelSequence[nextIndex];
            if (!IsSelectableInteractable(nextUpper))
            {
                return false;
            }

            eventSystem.SetSelectedGameObject(nextUpper.gameObject);
            return true;
        }

        if (!IsTopMostPartsSelectable(current))
        {
            return false;
        }

        Selectable firstUpper = gamepadUpperPanelSequence[gamepadUpperPanelSequence.Count - 1];
        if (!IsSelectableInteractable(firstUpper))
        {
            return false;
        }

        eventSystem.SetSelectedGameObject(firstUpper.gameObject);
        return true;
    }

    private bool IsCustomizePanelActiveForGamepadNavigation()
    {
        if (IsSavedPanelActive())
        {
            return false;
        }

        if (partsPanelRoot == null)
        {
            return true;
        }

        return partsPanelRoot.gameObject.activeInHierarchy;
    }

    private bool IsTopMostPartsSelectable(Selectable selectable)
    {
        if (selectable == null || bodyPartsContent == null)
        {
            return false;
        }

        RectTransform currentRect = selectable.transform as RectTransform;
        if (currentRect == null || !currentRect.IsChildOf(bodyPartsContent))
        {
            return false;
        }

        if (!TryGetBodyPartsTopCenterY(out float topCenterY))
        {
            return false;
        }

        float currentCenterY = GetRectTransformWorldCenterY(currentRect);
        return currentCenterY >= topCenterY - 0.5f;
    }

    private void RebuildGamepadUpperPanelSequence()
    {
        gamepadUpperPanelSequence.Clear();

        float bodyPartsTopCenterY = float.NegativeInfinity;
        bool hasBodyPartsTop = TryGetBodyPartsTopCenterY(out bodyPartsTopCenterY);

        AddGamepadUpperPanelCandidate(customCategoryDropdownToggleButton, hasBodyPartsTop, bodyPartsTopCenterY);
        AddGamepadUpperPanelCandidate(categoryDropdown, hasBodyPartsTop, bodyPartsTopCenterY);
        AddGamepadUpperPanelCandidate(partsPanelToggleButton, hasBodyPartsTop, bodyPartsTopCenterY);
        AddGamepadUpperPanelCandidate(savePrefabsPanelToggleButton, hasBodyPartsTop, bodyPartsTopCenterY);
        AddGamepadUpperPanelCandidate(playSceneButton, hasBodyPartsTop, bodyPartsTopCenterY);
        AddGamepadUpperPanelCandidate(dualPartToggle, hasBodyPartsTop, bodyPartsTopCenterY);
        AddGamepadUpperPanelCandidate(upperBodyGroupToggle, hasBodyPartsTop, bodyPartsTopCenterY);
        AddGamepadUpperPanelCandidate(lowerBodyGroupToggle, hasBodyPartsTop, bodyPartsTopCenterY);
        AddGamepadUpperPanelCandidate(randomColorButton, hasBodyPartsTop, bodyPartsTopCenterY);
        AddGamepadUpperPanelCandidate(colorChartButton, hasBodyPartsTop, bodyPartsTopCenterY);
        AddGamepadUpperPanelCandidate(autoRotationButton, hasBodyPartsTop, bodyPartsTopCenterY);
        AddGamepadUpperPanelCandidate(resetDefaultButton, hasBodyPartsTop, bodyPartsTopCenterY);
        AddGamepadUpperPanelCandidate(randomizeButton, hasBodyPartsTop, bodyPartsTopCenterY);
        AddGamepadUpperPanelCandidate(backButton, hasBodyPartsTop, bodyPartsTopCenterY);
        AddGamepadUpperPanelCandidate(setPrevButton, hasBodyPartsTop, bodyPartsTopCenterY);
        AddGamepadUpperPanelCandidate(setNextButton, hasBodyPartsTop, bodyPartsTopCenterY);
        AddGamepadUpperPanelCandidate(saveButton, hasBodyPartsTop, bodyPartsTopCenterY);

        gamepadUpperPanelSequence.Sort((left, right) =>
        {
            float leftY = GetSelectableWorldCenterY(left);
            float rightY = GetSelectableWorldCenterY(right);
            int yCompare = rightY.CompareTo(leftY);
            if (yCompare != 0)
            {
                return yCompare;
            }

            float leftX = GetSelectableWorldCenterX(left);
            float rightX = GetSelectableWorldCenterX(right);
            return leftX.CompareTo(rightX);
        });
    }

    private void AddGamepadUpperPanelCandidate(Selectable selectable, bool hasBodyPartsTop, float bodyPartsTopCenterY)
    {
        if (!IsSelectableInteractable(selectable) || gamepadUpperPanelSequence.Contains(selectable))
        {
            return;
        }

        RectTransform rect = selectable.transform as RectTransform;
        if (rect == null)
        {
            return;
        }

        if (bodyPartsContent != null && rect.IsChildOf(bodyPartsContent))
        {
            return;
        }

        if (hasBodyPartsTop && GetRectTransformWorldCenterY(rect) < bodyPartsTopCenterY - 0.5f)
        {
            return;
        }

        gamepadUpperPanelSequence.Add(selectable);
    }

    private bool TryGetBodyPartsTopCenterY(out float topCenterY)
    {
        topCenterY = float.NegativeInfinity;
        if (bodyPartsContent == null)
        {
            return false;
        }

        Selectable[] selectables = bodyPartsContent.GetComponentsInChildren<Selectable>(includeInactive: false);
        bool found = false;
        for (int i = 0; i < selectables.Length; i++)
        {
            Selectable selectable = selectables[i];
            if (!IsSelectableInteractable(selectable))
            {
                continue;
            }

            RectTransform rect = selectable.transform as RectTransform;
            if (rect == null)
            {
                continue;
            }

            float centerY = GetRectTransformWorldCenterY(rect);
            if (!found || centerY > topCenterY)
            {
                topCenterY = centerY;
                found = true;
            }
        }

        return found;
    }

    private static float GetSelectableWorldCenterY(Selectable selectable)
    {
        RectTransform rect = selectable != null ? selectable.transform as RectTransform : null;
        return GetRectTransformWorldCenterY(rect);
    }

    private static float GetSelectableWorldCenterX(Selectable selectable)
    {
        RectTransform rect = selectable != null ? selectable.transform as RectTransform : null;
        if (rect == null)
        {
            return 0f;
        }

        Vector3 center = rect.TransformPoint(rect.rect.center);
        return center.x;
    }

    private static float GetRectTransformWorldCenterY(RectTransform rect)
    {
        if (rect == null)
        {
            return float.NegativeInfinity;
        }

        Vector3 center = rect.TransformPoint(rect.rect.center);
        return center.y;
    }

    private void UpdateGamepadFocusedVisualState(EventSystem eventSystem, bool allowFocusVisual)
    {
        if (!allowFocusVisual || eventSystem == null || !HasConnectedGamepad())
        {
            gamepadFocusedStickyButton = null;
            ClearGamepadFocusedOutlineFallback();
            return;
        }

        Selectable current = ResolveSelectableFromGameObject(eventSystem.currentSelectedGameObject);
        if (!IsSelectableInteractable(current))
        {
            gamepadFocusedStickyButton = null;
            ClearGamepadFocusedOutlineFallback();
            return;
        }

        Button focusedButton = ResolveButtonFromSelectable(current);
        Image background = null;
        if (focusedButton != null)
        {
            background = focusedButton.targetGraphic as Image;
            background ??= focusedButton.GetComponent<Image>();
        }
        else
        {
            background = current.targetGraphic as Image;
            background ??= current.GetComponent<Image>();
        }

        if (background == null)
        {
            gamepadFocusedStickyButton = null;
            ClearGamepadFocusedOutlineFallback();
            return;
        }

        bool hasShadowPressVisual = focusedButton != null && TryResolveShadowPressTarget(focusedButton, out _);
        gamepadFocusedStickyButton = hasShadowPressVisual ? focusedButton : null;

        Outline outline = background.GetComponent<Outline>();
        if (focusedButton != null
            && outline != null
            && IsGamepadFocusUsingActiveOutline(focusedButton))
        {
            ClearGamepadFocusedOutlineFallback();
            gamepadFocusedStickyButton = hasShadowPressVisual ? focusedButton : null;
            outline.enabled = true;
            return;
        }

        if (hasShadowPressVisual && outline != null)
        {
            if (focusedGamepadOutlineFallback != outline)
            {
                ClearGamepadFocusedOutlineFallback();
                focusedGamepadOutlineFallback = outline;
                focusedGamepadOutlineFallbackColor = outline.effectColor;
                focusedGamepadOutlineFallbackWasCreated = false;
                focusedGamepadOutlineFallbackWasEnabled = outline.enabled;
                focusedGamepadOutlineFallbackEffectDistance = outline.effectDistance;
                focusedGamepadOutlineFallbackUseGraphicAlpha = outline.useGraphicAlpha;
            }

            gamepadFocusedStickyButton = focusedButton;
            outline.enabled = true;
            return;
        }

        bool createdNow = false;
        if (outline == null)
        {
            outline = background.gameObject.AddComponent<Outline>();
            createdNow = true;
        }

        if (focusedGamepadOutlineFallback != outline)
        {
            ClearGamepadFocusedOutlineFallback();
            focusedGamepadOutlineFallback = outline;
            focusedGamepadOutlineFallbackColor = outline.effectColor;
            focusedGamepadOutlineFallbackWasCreated = createdNow;
            focusedGamepadOutlineFallbackWasEnabled = outline.enabled;
            focusedGamepadOutlineFallbackEffectDistance = outline.effectDistance;
            focusedGamepadOutlineFallbackUseGraphicAlpha = outline.useGraphicAlpha;
        }

        if (hasShadowPressVisual)
        {
            gamepadFocusedStickyButton = focusedButton;
        }

        // Use a black focus outline only for non-active items.
        outline.effectColor = Color.black;
        outline.effectDistance = new Vector2(1.6f, 1.6f);
        outline.useGraphicAlpha = false;
        outline.enabled = true;
    }

    private bool IsGamepadFocusUsingActiveOutline(Button focusedButton)
    {
        if (focusedButton == null)
        {
            return false;
        }

        if (TryFindVariantButtonIndex(focusedButton, out int variantIndex))
        {
            if (customizer == null || selectedRegionIndex < 0 || selectedRegionIndex >= regions.Count)
            {
                return false;
            }

            bool propsMode = IsPropsRegionSelectionMode();
            MinimoCharacterCustomizer.PartSlot[] selectedSlots = propsMode
                ? GetTargetSlotsForSelectedRegion()
                : GetTargetSlotsForVariantButtonPanel();
            int? selectedRegionVariant = ResolveSelectedRegionVariantForVariantButtons(selectedSlots);
            bool defaultHairSelectionActive = IsDefaultHairButtonSelectionActive(selectedSlots);
            VariantButtonEntry entry = variantIndex >= 0 && variantIndex < variantButtons.Count
                ? variantButtons[variantIndex]
                : null;
            return IsVariantButtonEntryCurrentlySelected(
                entry,
                selectedSlots,
                selectedRegionVariant,
                defaultHairSelectionActive,
                propsMode);
        }

        if (TryFindSavedButtonIndex(focusedButton, out int savedIndex))
        {
            return savedIndex == selectedSavedPrefabIndex;
        }

        if (TryFindMaterialButtonIndex(focusedButton, out int materialIndex))
        {
            ColorChannelButtonEntry entry = materialIndex >= 0 && materialIndex < colorChannelButtons.Count
                ? colorChannelButtons[materialIndex]
                : null;
            return IsColorChannelEntrySelected(entry);
        }

        if (TryFindColorButtonIndex(focusedButton, out int colorIndex))
        {
            Color selectedPaletteColor = Color.clear;
            bool hasSelectedPaletteColor = selectedColorChannelTarget != ColorChannelTargetType.Material
                ? TryGetSelectedFaceChannelColor(out selectedPaletteColor)
                : TryGetCurrentSelectionAnchorColor(out selectedPaletteColor);
            int selectedColorButtonIndex = ResolveActiveColorButtonIndex(hasSelectedPaletteColor, selectedPaletteColor);
            return colorIndex == selectedColorButtonIndex;
        }

        return false;
    }

    private void ClearGamepadFocusedOutlineFallback()
    {
        if (focusedGamepadOutlineFallback != null)
        {
            if (focusedGamepadOutlineFallbackWasCreated)
            {
                focusedGamepadOutlineFallback.enabled = false;
            }
            else
            {
                focusedGamepadOutlineFallback.effectColor = focusedGamepadOutlineFallbackColor;
                focusedGamepadOutlineFallback.effectDistance = focusedGamepadOutlineFallbackEffectDistance;
                focusedGamepadOutlineFallback.useGraphicAlpha = focusedGamepadOutlineFallbackUseGraphicAlpha;
                focusedGamepadOutlineFallback.enabled = focusedGamepadOutlineFallbackWasEnabled;
            }
        }

        focusedGamepadOutlineFallback = null;
        focusedGamepadOutlineFallbackColor = Color.clear;
        focusedGamepadOutlineFallbackWasCreated = false;
        focusedGamepadOutlineFallbackWasEnabled = false;
        focusedGamepadOutlineFallbackEffectDistance = Vector2.zero;
        focusedGamepadOutlineFallbackUseGraphicAlpha = false;
        gamepadFocusedStickyButton = null;
    }

    private void EnsureGamepadUiSelection(EventSystem eventSystem, bool forceReselect)
    {
        if (eventSystem == null)
        {
            return;
        }

        Selectable current = ResolveSelectableFromGameObject(eventSystem.currentSelectedGameObject);
        if (!forceReselect && IsSelectableInteractable(current))
        {
            gamepadUiSelectionRefreshPending = false;
            return;
        }

        Selectable preferred = ResolvePreferredGamepadSelectable();
        if (!IsSelectableInteractable(preferred))
        {
            return;
        }

        if (current != preferred)
        {
            eventSystem.SetSelectedGameObject(preferred.gameObject);
            EnsureGamepadSelectableVisible(preferred);
        }

        gamepadUiSelectionRefreshPending = false;
    }

    private Selectable ResolvePreferredGamepadSelectable()
    {
        if (IsSaveModePopupOpen())
        {
            return FirstInteractableSelectable(
                saveModePopupOverwriteButton,
                saveModePopupSaveAsNewButton,
                saveModePopupCancelButton);
        }

        if (IsDeleteSavedPrefabPopupOpen())
        {
            return FirstInteractableSelectable(
                deleteSavedPrefabPopupNoButton,
                deleteSavedPrefabPopupYesButton);
        }

        if (customCategoryDropdownExpanded && customCategoryDropdownOptionButtons.Count > 0)
        {
            int clampedIndex = Mathf.Clamp(selectedCategoryDropdownIndex, 0, customCategoryDropdownOptionButtons.Count - 1);
            Button focusedOption = customCategoryDropdownOptionButtons[clampedIndex];
            if (IsSelectableInteractable(focusedOption))
            {
                return focusedOption;
            }

            for (int i = 0; i < customCategoryDropdownOptionButtons.Count; i++)
            {
                Button optionButton = customCategoryDropdownOptionButtons[i];
                if (IsSelectableInteractable(optionButton))
                {
                    return optionButton;
                }
            }
        }

        if (customSavedPrefabDropdownExpanded && customSavedPrefabDropdownOptionButtons.Count > 0)
        {
            int clampedIndex = Mathf.Clamp(
                selectedSavedPrefabCategoryDropdownIndex,
                0,
                customSavedPrefabDropdownOptionButtons.Count - 1);
            Button focusedOption = customSavedPrefabDropdownOptionButtons[clampedIndex];
            if (IsSelectableInteractable(focusedOption))
            {
                return focusedOption;
            }

            for (int i = 0; i < customSavedPrefabDropdownOptionButtons.Count; i++)
            {
                Button optionButton = customSavedPrefabDropdownOptionButtons[i];
                if (IsSelectableInteractable(optionButton))
                {
                    return optionButton;
                }
            }
        }

        if (IsSavedPanelActive())
        {
            if (IsSelectableInteractable(customSavedPrefabDropdownToggleButton))
            {
                return customSavedPrefabDropdownToggleButton;
            }

            if (selectedSavedPrefabIndex >= 0 && selectedSavedPrefabIndex < savedPrefabButtons.Count)
            {
                SavedPrefabButtonEntry selectedEntry = savedPrefabButtons[selectedSavedPrefabIndex];
                if (selectedEntry != null && IsSelectableInteractable(selectedEntry.button))
                {
                    return selectedEntry.button;
                }
            }

            for (int i = 0; i < savedPrefabButtons.Count; i++)
            {
                SavedPrefabButtonEntry entry = savedPrefabButtons[i];
                if (entry != null && IsSelectableInteractable(entry.button))
                {
                    return entry.button;
                }
            }

            return FirstInteractableSelectable(
                savedPrefabsLeftArrowButton,
                savedPrefabsRightArrowButton,
                savePrefabsPanelToggleButton,
                partsPanelToggleButton);
        }

        if (IsCategoryInfoPanelVisible() && IsSelectableInteractable(categoryInfoBuyButton))
        {
            return categoryInfoBuyButton;
        }

        for (int i = 0; i < variantButtons.Count; i++)
        {
            VariantButtonEntry entry = variantButtons[i];
            if (entry != null
                && !entry.isRandomButton
                && IsSelectableInteractable(entry.button))
            {
                return entry.button;
            }
        }

        if (selectedRegionIndex >= 0 && selectedRegionIndex < regions.Count)
        {
            RegionEntry region = regions[selectedRegionIndex];
            if (region != null && IsSelectableInteractable(region.button))
            {
                return region.button;
            }
        }

        for (int i = 0; i < regions.Count; i++)
        {
            RegionEntry region = regions[i];
            if (region != null && IsSelectableInteractable(region.button))
            {
                return region.button;
            }
        }

        for (int i = 0; i < variantButtons.Count; i++)
        {
            VariantButtonEntry entry = variantButtons[i];
            if (entry != null && IsSelectableInteractable(entry.button))
            {
                return entry.button;
            }
        }

        return FirstInteractableSelectable(
            randomizeButton,
            backButton,
            setPrevButton,
            setNextButton,
            saveButton,
            customCategoryDropdownToggleButton,
            savePrefabsPanelToggleButton,
            partsPanelToggleButton);
    }

    private void MarkGamepadUiInteraction()
    {
        lastGamepadUiInputTime = Time.unscaledTime;
        gamepadUiSelectionRefreshPending = true;
    }

    private bool IsGamepadNavigationRecentlyActive()
    {
        if (!HasConnectedGamepad())
        {
            return false;
        }

        return Time.unscaledTime - lastGamepadUiInputTime <= Mathf.Max(0f, gamepadUiFocusRetentionSeconds);
    }

    private static Selectable FirstInteractableSelectable(params Selectable[] candidates)
    {
        if (candidates == null || candidates.Length == 0)
        {
            return null;
        }

        for (int i = 0; i < candidates.Length; i++)
        {
            Selectable selectable = candidates[i];
            if (IsSelectableInteractable(selectable))
            {
                return selectable;
            }
        }

        return null;
    }

    private static Selectable ResolveSelectableFromGameObject(GameObject obj)
    {
        if (obj == null)
        {
            return null;
        }

        Selectable selectable = obj.GetComponent<Selectable>();
        if (selectable != null)
        {
            return selectable;
        }

        return obj.GetComponentInParent<Selectable>();
    }

    private static bool IsSelectableInteractable(Selectable selectable)
    {
        return selectable != null
               && selectable.gameObject.activeInHierarchy
               && selectable.IsActive()
               && selectable.IsInteractable();
    }

    private bool IsGamepadButtonDown(KeyCode buttonKey)
    {
        if (!enableGamepadUiControl || buttonKey == KeyCode.None)
        {
            return false;
        }

        if (MinimoInputBridge.GetKeyDown(buttonKey))
        {
            return true;
        }

#if ENABLE_INPUT_SYSTEM
        return ReadInputSystemGamepadButtonDown(buttonKey);
#else
        return false;
#endif
    }

    private static bool HasConnectedGamepad()
    {
#if ENABLE_INPUT_SYSTEM
        if (Gamepad.current != null)
        {
            return true;
        }
#endif
        string[] joystickNames = MinimoInputBridge.GetJoystickNames();
        for (int i = 0; i < joystickNames.Length; i++)
        {
            if (!string.IsNullOrWhiteSpace(joystickNames[i]))
            {
                return true;
            }
        }

        return false;
    }

#if ENABLE_INPUT_SYSTEM
    private static bool ReadInputSystemGamepadButtonDown(KeyCode buttonKey)
    {
        Gamepad gamepad = Gamepad.current;
        if (gamepad == null)
        {
            return false;
        }

        ButtonControl button = buttonKey switch
        {
            KeyCode.JoystickButton0 => gamepad.buttonSouth,
            KeyCode.JoystickButton1 => gamepad.buttonEast,
            KeyCode.JoystickButton2 => gamepad.buttonWest,
            KeyCode.JoystickButton3 => gamepad.buttonNorth,
            KeyCode.JoystickButton4 => gamepad.leftShoulder,
            KeyCode.JoystickButton5 => gamepad.rightShoulder,
            KeyCode.JoystickButton6 => gamepad.selectButton,
            KeyCode.JoystickButton7 => gamepad.startButton,
            KeyCode.JoystickButton8 => gamepad.leftStickButton,
            KeyCode.JoystickButton9 => gamepad.rightStickButton,
            _ => null
        };

        return button != null && button.wasPressedThisFrame;
    }
#endif

    private void OnDestroy()
    {
        TrySavePersistentCustomizationState(flushToDisk: true);
        if (previewWarmupCoroutine != null)
        {
            StopCoroutine(previewWarmupCoroutine);
            previewWarmupCoroutine = null;
        }

        if (savedPrefabPreviewWarmupCoroutine != null)
        {
            StopCoroutine(savedPrefabPreviewWarmupCoroutine);
            savedPrefabPreviewWarmupCoroutine = null;
        }

        deferPreviewGeneration = false;
        deferSavedPrefabPreviewGeneration = false;

        if (runtimeColorWheelTexture != null)
        {
            if (Application.isPlaying)
            {
                Destroy(runtimeColorWheelTexture);
            }
            else
            {
                DestroyImmediate(runtimeColorWheelTexture);
            }
        }

        if (runtimeMaterialChannelCircleSprite != null)
        {
            if (Application.isPlaying)
            {
                Destroy(runtimeMaterialChannelCircleSprite);
            }
            else
            {
                DestroyImmediate(runtimeMaterialChannelCircleSprite);
            }
        }

        if (runtimeMaterialChannelCircleTexture != null)
        {
            if (Application.isPlaying)
            {
                Destroy(runtimeMaterialChannelCircleTexture);
            }
            else
            {
                DestroyImmediate(runtimeMaterialChannelCircleTexture);
            }
        }

        if (runtimeColorPickerRoot != null && runtimeColorPickerCreatedByScript)
        {
            DestroyGameObjectSafely(runtimeColorPickerRoot.gameObject);
        }

        runtimeColorPickerRoot = null;
        runtimeColorPickerCloseButton = null;
        runtimeColorWheelIndicatorImage = null;
        runtimeColorPickerCreatedByScript = false;

        if (categoryInfoPanelRoot != null && categoryInfoPanelCreatedByScript)
        {
            DestroyGameObjectSafely(categoryInfoPanelRoot.gameObject);
        }

        categoryInfoPanelRoot = null;
        categoryInfoTitleLabel = null;
        categoryInfoTitleTmpLabel = null;
        categoryInfoSubHeaderLabel = null;
        categoryInfoSubHeaderTmpLabel = null;
        categoryInfoPreviewImage = null;
        categoryInfoContentLabel = null;
        categoryInfoContentTmpLabel = null;
        categoryInfoBuyButton = null;
        categoryInfoBuyButtonLabel = null;
        categoryInfoBuyButtonTmpLabel = null;
        categoryInfoPanelCreatedByScript = false;
        activeLockedCategoryTheme = string.Empty;
        activeCategoryInfo = null;

        ResetWorldPartHoverVisuals();
        ClearVariantPreviewTextures();
        ClearPreviewTextureCache();
        ClearSavedPrefabPreviewTextures();
        DisposeVariantPreviewRenderer();
        UnbindGlobalEvents();
        RestoreSceneCategoryDropdownBehaviour();
        RestoreSceneSavedPrefabDropdownBehaviour();
        UnbindDualToggleEvent();
        UnbindRowEvents();
        UnbindRegionEvents();
        UnbindVariantEvents();
        UnbindColorChannelEvents();
        UnbindColorEvents();
        UnbindSavedPrefabEvents();
        shadowPressButtonStates.Clear();
        ClearUndoStateHistory();

        if (readyCharacterArrowRoot != null)
        {
            DestroyGameObjectSafely(readyCharacterArrowRoot.gameObject);

            readyCharacterArrowRoot = null;
            readyCharacterPrevArrowButton = null;
            readyCharacterNextArrowButton = null;
            readyCharacterPrevArrowRect = null;
            readyCharacterNextArrowRect = null;
        }
    }

