    [ContextMenu("Customization UI/Refresh")]
    public void RefreshFromCustomizer()
    {
        AutoWireReferences();
        RebindGlobalEvents();
        BuildRows();
        BuildRegionButtons();
        ApplyMinimalHudTheme();
        EnsurePanelModeState();
        RefreshCategoryDropdownOptions();

        if (customizer == null)
        {
            hasExplicitPartSelection = false;
            if (titleLabel != null)
            {
                titleLabel.text = "Minimo Character Customization";
            }

            if (setNameLabel != null)
            {
                setNameLabel.text = "Set: None";
            }

            if (helperLabel != null)
            {
                helperLabel.text = "Customizer not found.";
            }

            UpdateColorPanelHeader(0);
            UpdateWorldLinkedSelectionUi();
            UpdateCategoryInfoPanel(string.Empty, null);
            UpdateInfoPanel();
            hasCameraTarget = false;
            SetInteractable(false);
            SetCustomColorPickerVisible(false);
            return;
        }

        if (titleLabel != null)
        {
            titleLabel.text = "Minimo Character Customization";
        }

        if (!persistenceInitialized)
        {
            InitializePersistentCustomizationState();
        }

        int variantCount = customizer.GetVariantCount();
        if (variantCount <= 0)
        {
            currentSetIndex = -1;
        }
        else if (currentSetIndex >= variantCount)
        {
            currentSetIndex = variantCount - 1;
        }

        EnforceHairRendererDefaultVariantState();

        if (UsesBodySelectionUI())
        {
            RebuildVariantButtons();
            // Keep material channel strip synchronized even when variant list rebuild
            // is skipped by cache checks or panel content is scene-authored.
            BuildColorChannelButtons(ResolveFont());
            UpdateRegionButtonVisuals();
            UpdateVariantButtonVisuals();
            UpdateColorButtonVisuals();
            UpdateWorldLinkedSelectionUi();
            RefreshCategoryDropdownOptions();
        }
        else
        {
            for (int i = 0; i < rows.Count; i++)
            {
                UpdateRow(rows[i]);
            }

            UpdateWorldLinkedSelectionUi();
            UpdateCategoryInfoPanel(string.Empty, null);
        }

        RefreshSavedPrefabCategoryDropdownOptions();
        RebuildSavedPrefabButtons();
        ConfigureSavedPrefabsLayout();
        UpdateSavedPanelPresentation();

        if (IsFaceTextureSelectionMode())
        {
            ReapplySelectedFaceTextureSetIfNeeded();
        }

        if (setNameLabel != null)
        {
            setNameLabel.text = currentSetIndex >= 0
                ? $"Set: {customizer.GetVariantDisplayName(currentSetIndex)}"
                : "Set: Default";
        }

        UpdateHelperLabelText();

        UpdateInfoPanel();
        UpdateColorPanelHeader(GetSelectedRegionColorChannelCount());
        HideButtonLabel(colorChartButton);
        HideButtonLabel(autoRotationButton);
        UpdateAutoRotationButtonVisual();
        if (runtimeColorPickerRoot != null && runtimeColorPickerRoot.gameObject.activeSelf)
        {
            SyncCustomColorPickerFromSelection();
        }

        RefreshCameraFocusTarget();
        SetInteractable(true);
        RefreshGamepadButtonNavigation();
        EnsureCharacterDragRotate();
        ApplyAutoRotationStateToDragRotate();
        EnsureWorldPartColliders();
        gamepadUiSelectionRefreshPending = true;
        TrySavePersistentCustomizationState();
    }

