    {
        RefreshAfterCustomizationApplication(changedSlots, refreshWorldPartColliders: true, savePersistentState: true);
    }

    private void RefreshAfterPropApplication()
    {
        RefreshAfterCustomizationApplication(null, refreshWorldPartColliders: false, savePersistentState: true);
    }

    private void RefreshAfterCustomizationApplication(
        MinimoCharacterCustomizer.PartSlot[] changedSlots,
        bool refreshWorldPartColliders,
        bool savePersistentState)
    {
        if (customizer == null)
        {
            return;
        }

        EnforceHairRendererDefaultVariantState();

        if (UsesBodySelectionUI())
        {
            RefreshColorChannelButtonsAfterCustomization(ResolveFont());
            UpdateRegionButtonVisuals();
            UpdateVariantButtonVisuals();
            UpdateColorButtonVisuals();
            UpdateWorldLinkedSelectionUi();
        }
        else
        {
            for (int i = 0; i < rows.Count; i++)
            {
                UpdateRow(rows[i]);
            }

            UpdateWorldLinkedSelectionUi();
        }

        if (changedSlots != null && SlotArrayContains(changedSlots, MinimoCharacterCustomizer.PartSlot.Face))
        {
            if (IsFaceTextureSelectionMode())
            {
                ReapplySelectedFaceTextureSetIfNeeded();
            }
            else
            {
                selectedFaceTextureSetKey = string.Empty;
            }
        }

        if (setNameLabel != null)
        {
            setNameLabel.text = currentSetIndex >= 0
                ? $"Set: {customizer.GetVariantDisplayName(currentSetIndex)}"
                : "Set: Default";
        }

        UpdateHelperLabelText();
        UpdateInfoPanel();
        UpdateColorPanelHeader(GetSelectedRegionColorChannelCount());
        HideButtonLabel(colorChartButton);
        HideButtonLabel(autoRotationButton);
        UpdateAutoRotationButtonVisual();
        UpdateShadowStickyButtonStates();
        if (runtimeColorPickerRoot != null && runtimeColorPickerRoot.gameObject.activeSelf)
        {
            SyncCustomColorPickerFromSelection();
        }

        if (refreshWorldPartColliders)
        {
            EnsureWorldPartCollidersForSlots(changedSlots);
        }

        gamepadUiSelectionRefreshPending = true;
        if (savePersistentState)
        {
            TrySavePersistentCustomizationState();
        }
    }

    private void RefreshColorChannelButtonsAfterCustomization(Font font)
    {
        int expectedColorChannelButtonCount = GetSelectedRegionColorChannelCount();
        if (expectedColorChannelButtonCount <= 0 || colorChannelButtons.Count != expectedColorChannelButtonCount)
        {
            BuildColorChannelButtons(font);
            return;
        }

        UpdateMaterialChannelSelectionVisuals();
    }

    private void UpdateHelperLabelText()
    {
        if (helperLabel == null)
        {
            return;
        }

        string baseMessage = UsesBodySelectionUI()
            ? "Click a part to select it. Drag to rotate the character."
            : "Drag to rotate the character.";
        string gamepadHint = enableGamepadUiControl
            ? "\nGamepad: Select with left stick/D-Pad, press A to apply, B to go back, Y for auto rotate, LB/RB to switch, Start to save. Right stick horizontal rotates the character."
            : string.Empty;

        helperLabel.text = string.IsNullOrWhiteSpace(helperOverrideMessage)
            ? $"{baseMessage}{gamepadHint}"
            : $"{baseMessage}{gamepadHint}\n{helperOverrideMessage}";
    }

    private void EnforceHairRendererDefaultVariantState()
    {
        if (customizer == null)
        {
            return;
        }

        int hairVariant = customizer.GetPartVariant(MinimoCharacterCustomizer.PartSlot.Hair);
        if (hairVariant >= 0)
        {
            SetHairRendererEnabled(hairRendererUnlockedByUserSelection);
            return;
        }

        if (hairRendererUnlockedByUserSelection && HairRendererHasMesh())
        {
            SetHairRendererEnabled(true);
            return;
        }

        hairRendererUnlockedByUserSelection = false;
        SetHairRendererEnabled(false);
    }

    private void SyncHairRendererUnlockFromCurrentRenderer()
    {
        if (customizer == null)
        {
            return;
        }

        bool hairRendererEnabled = false;
        if (customizer.TryGetPartRenderer(MinimoCharacterCustomizer.PartSlot.Hair, out SkinnedMeshRenderer hairRenderer)
            && hairRenderer != null)
        {
            hairRendererEnabled = hairRenderer.enabled;
        }

        hairRendererUnlockedByUserSelection = hairRendererEnabled;
    }

    private void InitializePersistentCustomizationState()
    {
        if (persistenceInitialized)
        {
            return;
        }

        if (!persistAcrossSessions)
        {
            persistenceInitialized = true;
            return;
        }

        if (customizer == null)
        {
            return;
        }

        persistenceInitialized = true;
    }

    private void TrySavePersistentCustomizationState(bool flushToDisk = false)
    {
        if (!persistAcrossSessions || !persistenceInitialized || isApplyingPersistentState || customizer == null)
        {
            return;
        }

        if (!flushToDisk && Application.isPlaying)
        {
            pendingPersistentCustomizationSave = true;
            pendingPersistentCustomizationSaveFrame = Time.frameCount;
            return;
        }

        SavePersistentCustomizationStateNow(flushToDisk);
    }

    private void FlushPendingPersistentCustomizationSave()
    {
        if (!pendingPersistentCustomizationSave)
        {
            return;
        }

        if (Time.frameCount <= pendingPersistentCustomizationSaveFrame)
        {
            return;
        }

        SavePersistentCustomizationStateNow(false);
    }

    private void SavePersistentCustomizationStateNow(bool flushToDisk)
    {
        if (!persistAcrossSessions || !persistenceInitialized || isApplyingPersistentState || customizer == null)
        {
            pendingPersistentCustomizationSave = false;
            return;
        }

        pendingPersistentCustomizationSave = false;
        PersistentCustomizationState state = CapturePersistentCustomizationState();
        if (state == null)
        {
            return;
        }

        string json = JsonUtility.ToJson(state);
        if (string.IsNullOrWhiteSpace(json))
        {
            return;
        }

        PlayerPrefs.SetString(BuildPersistenceKey(), json);
        if (flushToDisk)
        {
            PlayerPrefs.Save();
        }
    }

    private bool TryLoadPersistentCustomizationState()
    {
        string key = BuildPersistenceKey();
        if (!PlayerPrefs.HasKey(key))
        {
            return false;
        }

        string json = PlayerPrefs.GetString(key, string.Empty);
        if (string.IsNullOrWhiteSpace(json))
        {
            return false;
        }

        PersistentCustomizationState state = null;
        try
        {
            state = JsonUtility.FromJson<PersistentCustomizationState>(json);
        }
        catch
        {
            return false;
        }

        if (state == null)
        {
            return false;
        }

        ApplyPersistentCustomizationState(state);
        return true;
    }

    private string BuildPersistenceKey()
    {
        if (!string.IsNullOrWhiteSpace(persistenceKey))
        {
            return persistenceKey.Trim();
        }

        return "Minimo.Customization.State.v1";
    }

    private PersistentCustomizationState CapturePersistentCustomizationState()
    {
        if (customizer == null)
        {
            return null;
        }

        PersistentCustomizationState state = new PersistentCustomizationState();
        IReadOnlyList<MinimoCharacterCustomizer.PartSlot> slots = MinimoCharacterCustomizer.Slots;
        for (int i = 0; i < slots.Count; i++)
        {
            MinimoCharacterCustomizer.PartSlot slot = slots[i];
            state.partVariants.Add(new PersistentSlotVariant
            {
                slot = (int)slot,
                variantIndex = customizer.GetPartVariant(slot)
            });

            if (customizer.TryGetPartColor(slot, -1, out Color fallbackColor))
            {
                state.partColors.Add(new PersistentPartColor
                {
                    slot = (int)slot,
                    materialIndex = -1,
                    color = fallbackColor
                });
            }

            if (!customizer.TryGetPartRenderer(slot, out SkinnedMeshRenderer renderer) || renderer == null)
            {
                continue;
            }

            Material[] materials = renderer.sharedMaterials;
            if (materials == null || materials.Length == 0)
            {
                continue;
            }

            for (int materialIndex = 0; materialIndex < materials.Length; materialIndex++)
            {
                if (!customizer.TryGetPartColor(slot, materialIndex, out Color materialColor))
                {
                    continue;
                }

                state.partColors.Add(new PersistentPartColor
                {
                    slot = (int)slot,
                    materialIndex = materialIndex,
                    color = materialColor
                });
            }
        }

        if (IsFaceTextureSelectionMode() && string.IsNullOrWhiteSpace(selectedFaceTextureSetKey))
        {
            SyncSelectedFaceTextureSetKeyFromCurrentMaterial();
        }

        state.faceTextureSetKey = IsFaceTextureSelectionMode() ? selectedFaceTextureSetKey : string.Empty;
        if (customizer.TryGetPartRenderer(MinimoCharacterCustomizer.PartSlot.Face, out SkinnedMeshRenderer faceRenderer)
            && faceRenderer != null)
        {
            SaveFaceChannelColorFromRendererIfAvailable(state.faceChannelColors, faceRenderer, FaceEyesPropertyName, FaceEyesShaderProperty);
            SaveFaceChannelColorFromRendererIfAvailable(state.faceChannelColors, faceRenderer, FaceEyebrowsPropertyName, FaceEyebrowsShaderProperty);
            SaveFaceChannelColorFromRendererIfAvailable(state.faceChannelColors, faceRenderer, FaceMakeupPropertyName, FaceMakeupShaderProperty);
        }

        CapturePersistentPropState(state);
        return state;
    }

    private void ApplyPersistentCustomizationState(PersistentCustomizationState state)
    {
        if (customizer == null || state == null)
        {
            return;
        }

        isApplyingPersistentState = true;
        try
        {
            Dictionary<int, int> variantBySlot = new Dictionary<int, int>();
            if (state.partVariants != null)
            {
                for (int i = 0; i < state.partVariants.Count; i++)
                {
                    PersistentSlotVariant entry = state.partVariants[i];
                    if (entry == null)
                    {
                        continue;
                    }

                    variantBySlot[entry.slot] = entry.variantIndex;
                }
            }

            IReadOnlyList<MinimoCharacterCustomizer.PartSlot> slots = MinimoCharacterCustomizer.Slots;
            for (int i = 0; i < slots.Count; i++)
            {
                MinimoCharacterCustomizer.PartSlot slot = slots[i];
                int variant = -1;
                if (variantBySlot.TryGetValue((int)slot, out int savedVariant))
                {
                    variant = savedVariant;
                }

                customizer.SetPartVariant(slot, variant);
            }

            customizer.ApplyCurrentSelection();
            ClearAllRuntimePartColorOverrides();

            if (state.partColors != null)
            {
                for (int i = 0; i < state.partColors.Count; i++)
                {
                    PersistentPartColor entry = state.partColors[i];
                    if (entry == null || !Enum.IsDefined(typeof(MinimoCharacterCustomizer.PartSlot), entry.slot))
                    {
                        continue;
                    }

                    MinimoCharacterCustomizer.PartSlot slot = (MinimoCharacterCustomizer.PartSlot)entry.slot;
                    if (entry.materialIndex >= 0)
                    {
                        customizer.SetPartColor(slot, entry.materialIndex, entry.color);
                    }
                    else
                    {
                        customizer.SetPartColor(slot, entry.color);
                    }
                }
            }

            if (IsFaceTextureSelectionMode() && !string.IsNullOrWhiteSpace(state.faceTextureSetKey))
            {
                TryApplyPersistentFaceTextureSet(state.faceTextureSetKey);
            }
            else if (!IsFaceTextureSelectionMode())
            {
                selectedFaceTextureSetKey = string.Empty;
            }

            if (state.faceChannelColors != null)
            {
                for (int i = 0; i < state.faceChannelColors.Count; i++)
                {
                    PersistentFaceChannelColor entry = state.faceChannelColors[i];
                    if (entry == null)
                    {
                        continue;
                    }

                    TryApplyPersistentFaceChannelColor(entry.propertyName, entry.color);
                }
            }

            ApplyPersistentPropState(state);
        }
        finally
        {
            isApplyingPersistentState = false;
        }
    }

    private void CapturePersistentPropState(PersistentCustomizationState state)
    {
        if (state == null || customizer == null)
        {
            return;
        }

        state.selectedPropRigName = selectedPropRigName ?? string.Empty;
        state.equippedProps ??= new List<PersistentPropSelection>();
        state.equippedProps.Clear();

        Transform[] transforms = customizer.GetComponentsInChildren<Transform>(true);
        for (int i = 0; i < transforms.Length; i++)
        {
            Transform rigTransform = transforms[i];
            if (rigTransform == null)
            {
                continue;
            }

            for (int childIndex = 0; childIndex < rigTransform.childCount; childIndex++)
            {
                Transform propRoot = rigTransform.GetChild(childIndex);
                if (propRoot == null || !IsPropInstanceName(propRoot.name))
                {
                    continue;
                }

                string assetPath = string.Empty;
                if (TryGetPropSourceAssetPath(propRoot.gameObject, out string sourceAssetPath))
                {
                    assetPath = sourceAssetPath;
                }

                state.equippedProps.Add(new PersistentPropSelection
                {
                    rigName = rigTransform.name,
                    prefabName = propRoot.name,
                    assetPath = assetPath,
                    localPosition = propRoot.localPosition,
                    localEulerAngles = propRoot.localEulerAngles,
                    localScale = propRoot.localScale,
                    activeSelf = propRoot.gameObject.activeSelf,
                    materialColors = CapturePersistentPropMaterialColors(propRoot)
                });
            }
        }
    }

    private void ApplyPersistentPropState(PersistentCustomizationState state)
    {
        if (customizer == null)
        {
            return;
        }

        selectedPropRigName = string.Empty;
        ClearAllPropsFromCharacter();
        if (state == null || state.equippedProps == null || state.equippedProps.Count == 0)
        {
            return;
        }

        List<PropVariantEntry> propEntries = BuildAllPropVariantEntries();
        for (int i = 0; i < state.equippedProps.Count; i++)
        {
            PersistentPropSelection propState = state.equippedProps[i];
            if (propState == null
                || string.IsNullOrWhiteSpace(propState.rigName)
                || !TryFindPropRigTransform(propState.rigName, out Transform rigTransform)
                || rigTransform == null
                || !TryResolvePersistentPropPrefab(propState, propEntries, out GameObject sourcePrefab)
                || sourcePrefab == null)
            {
                continue;
            }

            GameObject instance = Instantiate(sourcePrefab, rigTransform, false);
            if (instance == null)
            {
                continue;
            }

            instance.name = !string.IsNullOrWhiteSpace(propState.prefabName)
                ? StripUnityCloneSuffix(propState.prefabName)
                : StripUnityCloneSuffix(sourcePrefab.name);
            StripUnityCloneSuffixesRecursively(instance.transform);
            SetPropSourceAssetPath(instance, propState.assetPath);

            Transform instanceTransform = instance.transform;
            instanceTransform.localPosition = propState.localPosition;
            instanceTransform.localRotation = Quaternion.Euler(propState.localEulerAngles);
            instanceTransform.localScale = propState.localScale;
            instance.SetActive(propState.activeSelf);
            ApplyPersistentPropMaterialColors(instance.transform, propState.materialColors);

            if (string.IsNullOrWhiteSpace(selectedPropRigName))
            {
                selectedPropRigName = rigTransform.name;
            }
        }

        if (!string.IsNullOrWhiteSpace(state.selectedPropRigName) && HasEquippedPropForRig(state.selectedPropRigName))
        {
            selectedPropRigName = state.selectedPropRigName;
        }
    }

    private static List<PersistentPropMaterialColor> CapturePersistentPropMaterialColors(Transform propRoot)
    {
        List<PersistentPropMaterialColor> colors = new List<PersistentPropMaterialColor>();
        if (propRoot == null)
        {
            return colors;
        }

        Transform visualRoot = ResolvePropVisualStateRoot(propRoot);
        if (visualRoot == null)
        {
            return colors;
        }

        Renderer[] renderers = visualRoot.GetComponentsInChildren<Renderer>(true);
        for (int rendererIndex = 0; rendererIndex < renderers.Length; rendererIndex++)
        {
            Renderer renderer = renderers[rendererIndex];
            if (renderer == null)
            {
                continue;
            }

            Material[] materials = renderer.materials;
            if (materials == null || materials.Length == 0)
            {
                materials = renderer.sharedMaterials;
            }

            if (materials == null || materials.Length == 0)
            {
                continue;
            }

            int materialCount = GetEffectiveRendererMaterialSlotCount(renderer, materials);
            string rendererPath = BuildRelativeTransformPath(propRoot, renderer.transform);
            int rendererComponentIndex = GetRendererComponentIndex(renderer);
            for (int materialIndex = 0; materialIndex < materialCount; materialIndex++)
            {
                Material material = materials[materialIndex];
                if (!TryGetMaterialDisplayColor(material, out Color color))
                {
                    continue;
                }

                colors.Add(new PersistentPropMaterialColor
                {
                    rendererPath = rendererPath,
                    rendererComponentIndex = rendererComponentIndex,
                    materialIndex = materialIndex,
                    color = color
                });
            }
        }

        return colors;
    }

    private static void ApplyPersistentPropMaterialColors(
        Transform propRoot,
        List<PersistentPropMaterialColor> colors)
    {
        if (propRoot == null || colors == null || colors.Count == 0)
        {
            return;
        }

        for (int i = 0; i < colors.Count; i++)
        {
            PersistentPropMaterialColor entry = colors[i];
            if (entry == null || entry.materialIndex < 0)
            {
                continue;
            }

            Renderer renderer = ResolvePersistentPropRenderer(
                propRoot,
                entry.rendererPath,
                entry.rendererComponentIndex);
            if (renderer == null)
            {
                continue;
            }

            Material[] materials = renderer.materials;
            bool assignToShared = false;
            if (materials == null || entry.materialIndex >= materials.Length)
            {
                materials = renderer.sharedMaterials;
                assignToShared = true;
            }

            if (materials == null || entry.materialIndex >= materials.Length)
            {
                continue;
            }

            Material material = materials[entry.materialIndex];
            if (!SetMaterialDisplayColor(material, entry.color))
            {
                continue;
            }

            if (assignToShared)
            {
                renderer.sharedMaterials = materials;
            }
            else
            {
                renderer.materials = materials;
            }

            renderer.SetPropertyBlock(null, entry.materialIndex);
        }
    }

    private static Renderer ResolvePersistentPropRenderer(
        Transform propRoot,
        string rendererPath,
        int rendererComponentIndex)
    {
        Transform rendererTransform = FindRelativeTransformByPath(propRoot, rendererPath);
        if (rendererTransform == null)
        {
            return null;
        }

        Component[] components = rendererTransform.GetComponents<Component>();
        int rendererIndex = 0;
        for (int i = 0; i < components.Length; i++)
        {
            if (!(components[i] is Renderer renderer))
            {
                continue;
            }

            if (rendererIndex == Mathf.Max(0, rendererComponentIndex))
            {
                return renderer;
            }

            rendererIndex++;
        }

        return rendererTransform.GetComponent<Renderer>();
    }

    private static Transform FindRelativeTransformByPath(Transform root, string relativePath)
    {
        if (root == null)
        {
            return null;
        }

        if (string.IsNullOrWhiteSpace(relativePath) || string.Equals(relativePath, ".", StringComparison.Ordinal))
        {
            return root;
        }

        Transform current = root;
        string[] segments = relativePath.Split('/');
        for (int segmentIndex = 0; segmentIndex < segments.Length; segmentIndex++)
        {
            string segment = segments[segmentIndex];
            if (string.IsNullOrWhiteSpace(segment))
            {
                continue;
            }

            ParseRelativeTransformPathSegment(segment, out string childName, out int siblingIndex);
            Transform next = null;
            if (siblingIndex >= 0 && siblingIndex < current.childCount)
            {
                Transform indexedChild = current.GetChild(siblingIndex);
                if (indexedChild != null
                    && (string.IsNullOrWhiteSpace(childName)
                        || string.Equals(indexedChild.name, childName, StringComparison.Ordinal)))
                {
                    next = indexedChild;
                }
            }

            if (next == null)
            {
                for (int i = 0; i < current.childCount; i++)
                {
                    Transform child = current.GetChild(i);
                    if (child != null && string.Equals(child.name, childName, StringComparison.Ordinal))
                    {
                        next = child;
                        break;
                    }
                }
            }

            if (next == null)
            {
                return null;
            }

            current = next;
        }

        return current;
    }

    private static void ParseRelativeTransformPathSegment(string segment, out string childName, out int siblingIndex)
    {
        childName = segment ?? string.Empty;
        siblingIndex = -1;
        if (string.IsNullOrWhiteSpace(segment))
        {
            return;
        }

        int hashIndex = segment.LastIndexOf('#');
        if (hashIndex < 0 || hashIndex >= segment.Length - 1)
        {
            return;
        }

        string suffix = segment.Substring(hashIndex + 1);
        if (!int.TryParse(suffix, out int parsedIndex) || parsedIndex < 0)
        {
            return;
        }

        childName = segment.Substring(0, hashIndex);
        siblingIndex = parsedIndex;
    }

    private static bool TryResolvePersistentPropPrefab(
        PersistentPropSelection propState,
        List<PropVariantEntry> propEntries,
        out GameObject sourcePrefab)
    {
        sourcePrefab = null;
        if (propState == null)
        {
            return false;
        }

        string normalizedAssetPath = NormalizeCategoryAssetPath(propState.assetPath);
        if (!string.IsNullOrWhiteSpace(normalizedAssetPath) && propEntries != null)
        {
            for (int i = 0; i < propEntries.Count; i++)
            {
                PropVariantEntry entry = propEntries[i];
                if (entry?.sourcePrefab == null)
                {
                    continue;
                }

                if (string.Equals(
                        NormalizeCategoryAssetPath(entry.assetPath),
                        normalizedAssetPath,
                        StringComparison.OrdinalIgnoreCase))
                {
                    sourcePrefab = entry.sourcePrefab;
                    return true;
                }
            }
        }

        if (propEntries != null)
        {
            for (int i = 0; i < propEntries.Count; i++)
            {
                PropVariantEntry entry = propEntries[i];
                if (entry?.sourcePrefab == null)
                {
                    continue;
                }

                if (string.Equals(entry.rigName, propState.rigName, StringComparison.OrdinalIgnoreCase)
                    && string.Equals(entry.prefabName, propState.prefabName, StringComparison.OrdinalIgnoreCase))
                {
                    sourcePrefab = entry.sourcePrefab;
                    return true;
                }
            }
        }

#if UNITY_EDITOR
        if (!string.IsNullOrWhiteSpace(normalizedAssetPath))
        {
            sourcePrefab = AssetDatabase.LoadAssetAtPath<GameObject>(normalizedAssetPath);
            return sourcePrefab != null;
        }
#endif

        return false;
    }

    private void RecordUndoSnapshotIfNeeded()
    {
        if (customizer == null || isApplyingPersistentState || isRestoringUndoState)
        {
            return;
        }

        PersistentCustomizationState state = CapturePersistentCustomizationState();
        if (state == null)
        {
            return;
        }

        string signature = JsonUtility.ToJson(state) ?? string.Empty;

        if (undoStateSignatures.Count > 0
            && string.Equals(undoStateSignatures[undoStateSignatures.Count - 1], signature, StringComparison.Ordinal))
        {
            return;
        }

        undoStateHistory.Add(state);
        undoStateSignatures.Add(signature);
        TrimUndoStateHistoryIfNeeded();
        UpdateBackButtonUndoInteractivity();
    }

    private void TrimUndoStateHistoryIfNeeded()
    {
        while (undoStateHistory.Count > MaxUndoStateHistory)
        {
            undoStateHistory.RemoveAt(0);
            if (undoStateSignatures.Count > 0)
            {
                undoStateSignatures.RemoveAt(0);
            }
        }
    }

    private void ClearUndoStateHistory()
    {
        undoStateHistory.Clear();
        undoStateSignatures.Clear();
        UpdateBackButtonUndoInteractivity();
    }

    private void UpdateBackButtonUndoInteractivity()
    {
        if (backButton == null)
        {
            return;
        }

        bool canUndo = controlsInteractable && customizer != null && undoStateHistory.Count > 0;
        backButton.SetEnabled(canUndo);
    }

    private void HandleBackButton()
    {
        if (customizer == null || undoStateHistory.Count <= 0)
        {
            UpdateBackButtonUndoInteractivity();
            return;
        }

        int lastIndex = undoStateHistory.Count - 1;
        PersistentCustomizationState undoState = undoStateHistory[lastIndex];
        undoStateHistory.RemoveAt(lastIndex);
        if (lastIndex >= 0 && lastIndex < undoStateSignatures.Count)
        {
            undoStateSignatures.RemoveAt(lastIndex);
        }
        else if (undoStateSignatures.Count > 0)
        {
            undoStateSignatures.RemoveAt(undoStateSignatures.Count - 1);
        }

        if (undoState == null)
        {
            UpdateBackButtonUndoInteractivity();
            return;
        }

        isRestoringUndoState = true;
        try
        {
            ApplyPersistentCustomizationState(undoState);
            RestoreHairRendererStateFromCurrentVariant();
            currentSetIndex = -1;
            helperOverrideMessage = "Undo applied.";
            RefreshFromCustomizer();
        }
        finally
        {
            isRestoringUndoState = false;
            UpdateBackButtonUndoInteractivity();
        }
    }

    private void RestoreHairRendererStateFromCurrentVariant()
    {
        if (customizer == null)
        {
            return;
        }

        bool hasHairVariant = customizer.GetPartVariant(MinimoCharacterCustomizer.PartSlot.Hair) >= 0;
        hairRendererUnlockedByUserSelection = hasHairVariant;
        SetHairRendererEnabled(hasHairVariant);
    }

    private void ClearAllRuntimePartColorOverrides()
    {
        if (customizer == null)
        {
            return;
        }

        IReadOnlyList<MinimoCharacterCustomizer.PartSlot> slots = MinimoCharacterCustomizer.Slots;
        for (int i = 0; i < slots.Count; i++)
        {
            MinimoCharacterCustomizer.PartSlot slot = slots[i];
            customizer.ClearPartColor(slot);
            if (!customizer.TryGetPartRenderer(slot, out SkinnedMeshRenderer renderer) || renderer == null)
            {
                continue;
            }

            Material[] materials = renderer.sharedMaterials;
            int materialCount = materials != null ? materials.Length : 0;
            for (int materialIndex = 0; materialIndex < materialCount; materialIndex++)
            {
                customizer.ClearPartColor(slot, materialIndex);
            }
        }
    }

    private static void SaveFaceChannelColorIfAvailable(
        List<PersistentFaceChannelColor> destination,
        Material[] materials,
        string propertyName,
        int propertyId)
    {
        if (destination == null || materials == null || string.IsNullOrWhiteSpace(propertyName))
        {
            return;
        }

        for (int i = 0; i < materials.Length; i++)
        {
            Material material = materials[i];
            if (material == null || !material.HasProperty(propertyId))
            {
                continue;
            }

            destination.Add(new PersistentFaceChannelColor
            {
                propertyName = propertyName,
                color = material.GetColor(propertyId)
            });
            return;
        }
    }

    private void TryApplyPersistentFaceTextureSet(string faceTextureSetKey)
    {
        if (customizer == null || string.IsNullOrWhiteSpace(faceTextureSetKey))
        {
            return;
        }

        RefreshFaceTextureSetCache();
        FaceTextureSet selectedSet = null;
        for (int i = 0; i < cachedFaceTextureSets.Count; i++)
        {
            FaceTextureSet candidate = cachedFaceTextureSets[i];
            if (candidate != null && string.Equals(candidate.key, faceTextureSetKey, StringComparison.Ordinal))
            {
                selectedSet = candidate;
                break;
            }
        }

        if (selectedSet == null
            || !customizer.TryGetPartRenderer(MinimoCharacterCustomizer.PartSlot.Face, out SkinnedMeshRenderer faceRenderer)
            || faceRenderer == null)
        {
            return;
        }

        Material[] materials = faceRenderer.materials;
        if (materials == null || materials.Length == 0)
        {
            return;
        }

        for (int materialIndex = 0; materialIndex < materials.Length; materialIndex++)
        {
            Material material = materials[materialIndex];
            if (material == null || !material.HasProperty(FaceTextureShaderProperty))
            {
                continue;
            }

            material.SetTexture(FaceTextureShaderProperty, selectedSet.albedo);
            if (material.HasProperty(FaceColorMaskShaderProperty))
            {
                material.SetTexture(FaceColorMaskShaderProperty, selectedSet.colorMask);
            }

            if (material.HasProperty(FaceMaskShaderProperty))
            {
                material.SetTexture(FaceMaskShaderProperty, selectedSet.faceMask);
            }
        }

        faceRenderer.materials = materials;
        selectedFaceTextureSetKey = selectedSet.key;
    }

    private void TryApplyPersistentFaceChannelColor(string propertyName, Color color)
    {
        if (customizer == null || string.IsNullOrWhiteSpace(propertyName))
        {
            return;
        }

        int propertyId = -1;
        switch (propertyName)
        {
            case FaceEyesPropertyName:
                propertyId = FaceEyesShaderProperty;
                break;
            case FaceEyebrowsPropertyName:
                propertyId = FaceEyebrowsShaderProperty;
                break;
            case FaceMakeupPropertyName:
                propertyId = FaceMakeupShaderProperty;
                break;
        }

        if (propertyId < 0
            || !customizer.TryGetPartRenderer(MinimoCharacterCustomizer.PartSlot.Face, out SkinnedMeshRenderer faceRenderer)
            || faceRenderer == null)
        {
            return;
        }

        Material[] materials = faceRenderer.materials;
        if (materials == null || materials.Length == 0)
        {
            return;
        }

        bool changed = false;
        for (int i = 0; i < materials.Length; i++)
        {
            Material material = materials[i];
            if (material == null || !material.HasProperty(propertyId))
            {
                continue;
            }

            material.SetColor(propertyId, color);
            changed = true;
        }

        if (changed)
        {
            faceRenderer.materials = materials;
        }
    }

#if UNITY_EDITOR
    private void EnsureCustomizeSourcesLoadedForStartup()
    {
        if (customizer == null)
        {
            return;
        }

        if (Application.isPlaying && customizer.UsesCustomizeFolderSource)
        {
            if (runtimeCustomizeSourcesLoadedCustomizer != customizer)
            {
                customizer.EditorLoadVariantsFromCustomizeFolder(applyAfterLoad: false);
                runtimeCustomizeSourcesLoadedCustomizer = customizer;
            }

            if (customizer.GetVariantCount() == 0)
            {
                customizer.EditorLoadVariantsFromCasualFolder(applyAfterLoad: false);
            }

            return;
        }

        if (customizer.GetVariantCount() == 0)
        {
            bool applyLoadedVariants = !Application.isPlaying;
            customizer.EditorLoadVariantsFromCustomizeFolder(applyLoadedVariants);
            if (customizer.GetVariantCount() == 0)
            {
                customizer.EditorLoadVariantsFromCasualFolder(applyLoadedVariants);
            }
        }
    }
#endif

