                customizationCamera = MinimoUnityCompatibility.FindFirstObjectByType<Camera>();
            }
        }

        ResolveSaveModePopupSceneReferences();
        ResolveDeleteSavedPrefabPopupSceneReferences();
        ResolveRuntimeColorPickerSceneReferences();
        ResolveCategoryInfoPanelSceneReferences();
        ResolveRuntimeTemplateReferences();
#if UNITY_EDITOR
        RefreshCategoryInfoAssetsFromProject();
#endif
        EnsureDeleteSavedPrefabPopup();
        EnsureCustomCategoryDropdown();
        EnsureCustomSavedPrefabDropdown();
        EnsureShadowPressTracking(setPrevButton);
        EnsureShadowPressTracking(setNextButton);
        EnsureShadowPressTracking(resetDefaultButton);
        EnsureShadowPressTracking(randomizeButton);
        EnsureShadowPressTracking(saveButton);
        EnsureShadowPressTracking(partsPanelToggleButton, allowWithoutShadowTarget: true);
        EnsureShadowPressTracking(savePrefabsPanelToggleButton, allowWithoutShadowTarget: true);
        EnsureShadowPressTracking(playSceneButton, allowWithoutShadowTarget: true);
        EnsureShadowPressTracking(randomColorButton);
        EnsureShadowPressTracking(colorChartButton);
        EnsureShadowPressTracking(autoRotationButton);
        EnsureShadowPressTracking(backButton);
        EnsureShadowPressTracking(savedPrefabsLeftArrowButton);
        EnsureShadowPressTracking(savedPrefabsRightArrowButton);
        EnsureShadowPressTracking(customCategoryDropdownToggleButton);
        EnsureShadowPressTracking(customSavedPrefabDropdownToggleButton);
        EnsureShadowPressTracking(savedPrefabsCategoryDropdown != null ? savedPrefabsCategoryDropdown.GetComponent<Button>() : null);
        EnsureShadowPressTracking(saveModePopupOverwriteButton);
        EnsureShadowPressTracking(saveModePopupSaveAsNewButton);
        EnsureShadowPressTracking(saveModePopupCancelButton);
        EnsureShadowPressTracking(deleteSavedPrefabPopupYesButton);
        EnsureShadowPressTracking(deleteSavedPrefabPopupNoButton);
        EnsureShadowPressTracking(runtimeColorPickerCloseButton, allowWithoutShadowTarget: true);
        EnsureShadowPressTracking(categoryInfoBuyButton, allowWithoutShadowTarget: true);
        UpdateBackButtonUndoInteractivity();
        RebindDualToggleEvent();
    }

    private void ResolveRuntimeTemplateReferences()
    {
        partCardTemplate = ResolveSceneTemplateButton(partCardTemplate, "PartCard");
        partRandomButtonTemplate = ResolveSceneTemplateButton(partRandomButtonTemplate, "Part_Random");
        partEmptyButtonTemplate = ResolveSceneTemplateButton(partEmptyButtonTemplate, "Part_Empty");
        partEmptyButtonTemplate = ResolveSceneTemplateButton(partEmptyButtonTemplate, "Part_Default");
        colorButtonTemplate = ResolveSceneTemplateButton(colorButtonTemplate, "ColorButton");
        worldLinkedPartSlotTemplate = ResolveSceneTemplateButton(worldLinkedPartSlotTemplate, "PartSlot");

        if (worldLinkedSelectionPopupTemplate == null)
        {
            worldLinkedSelectionPopupTemplate = FindChildByName<RectTransform>("SelectedPartsGroupPopup");
        }

#if UNITY_EDITOR
        if (partCardTemplate == null)
        {
            partCardTemplate = LoadPrefabTemplateButtonAtPath(PartCardTemplateAssetPath, "PartCard");
        }

        if (partRandomButtonTemplate == null)
        {
            partRandomButtonTemplate = LoadPrefabTemplateButtonAtPath(PartsGroupPanelTemplateAssetPath, "Part_Random");
        }

        if (partEmptyButtonTemplate == null)
        {
            partEmptyButtonTemplate = LoadPrefabTemplateButtonAtPath(PartsGroupPanelTemplateAssetPath, "Part_Empty");
            partEmptyButtonTemplate ??= LoadPrefabTemplateButtonAtPath(PartsGroupPanelTemplateAssetPath, "Part_Default");
        }

        if (colorButtonTemplate == null)
        {
            colorButtonTemplate = LoadPrefabTemplateButtonAtPath(ColorButtonTemplateAssetPath, "ColorButton");
        }

        if (worldLinkedPartSlotTemplate == null)
        {
            worldLinkedPartSlotTemplate = LoadPrefabTemplateButtonAtPath(WorldLinkedPartSlotTemplateAssetPath, "PartSlot");
        }

        if (worldLinkedSelectionPopupTemplate == null)
        {
            worldLinkedSelectionPopupTemplate = LoadPrefabTemplateRectAtPath(
                SelectedPartsGroupPopupTemplateAssetPath,
                "SelectedPartsGroupPopup");
        }
#endif
    }

    private static Button ResolveSceneTemplateButton(Button current, string objectName)
    {
        if (current != null)
        {
            return current;
        }

        Button direct = FindChildByName<Button>(objectName);
        if (direct != null)
        {
            return direct;
        }

        return FindButtonByNameOrChild(objectName);
    }

#if UNITY_EDITOR
    private static Button LoadPrefabTemplateButtonAtPath(string assetPath, string objectName)
    {
        if (string.IsNullOrWhiteSpace(assetPath))
        {
            return null;
        }

        GameObject prefab = AssetDatabase.LoadAssetAtPath<GameObject>(assetPath);
        if (prefab == null)
        {
            return null;
        }

        if (!string.IsNullOrWhiteSpace(objectName))
        {
            if (string.Equals(prefab.name, objectName, StringComparison.OrdinalIgnoreCase))
            {
                Button selfButton = prefab.GetComponent<Button>();
                if (selfButton != null)
                {
                    return selfButton;
                }
            }

            Button namedButton = FindChildByNameIn<Button>(prefab.transform, objectName);
            if (namedButton != null)
            {
                return namedButton;
            }
        }

        return prefab.GetComponent<Button>() ?? prefab.GetComponentInChildren<Button>(true);
    }

    private static RectTransform LoadPrefabTemplateRectAtPath(string assetPath, string objectName)
    {
        if (string.IsNullOrWhiteSpace(assetPath))
        {
            return null;
        }

        GameObject prefab = AssetDatabase.LoadAssetAtPath<GameObject>(assetPath);
        if (prefab == null)
        {
            return null;
        }

        if (!string.IsNullOrWhiteSpace(objectName))
        {
            if (string.Equals(prefab.name, objectName, StringComparison.OrdinalIgnoreCase)
                && prefab.transform is RectTransform prefabRect)
            {
                return prefabRect;
            }

            RectTransform namedRect = FindChildByNameIn<RectTransform>(prefab.transform, objectName);
            if (namedRect != null)
            {
                return namedRect;
            }
        }

        return prefab.transform as RectTransform;
    }
#endif

    private Button ResolvePartButtonTemplate(RuntimePartButtonTemplateKind kind)
    {
        ResolveRuntimeTemplateReferences();
        if (kind == RuntimePartButtonTemplateKind.Random && partRandomButtonTemplate != null)
        {
            return partRandomButtonTemplate;
        }

        if (kind == RuntimePartButtonTemplateKind.Empty && partEmptyButtonTemplate != null)
        {
            return partEmptyButtonTemplate;
        }

        return partCardTemplate != null ? partCardTemplate : partRandomButtonTemplate;
    }

