    {
        ResolveRuntimeTemplateReferences();
        return colorButtonTemplate;
    }

    private Button ResolveWorldLinkedPartSlotTemplateButton()
    {
        ResolveRuntimeTemplateReferences();
        return worldLinkedPartSlotTemplate;
    }

    private RectTransform ResolveWorldLinkedSelectionPopupTemplate()
    {
        ResolveRuntimeTemplateReferences();
        return worldLinkedSelectionPopupTemplate;
    }

    private bool IsBodyPartRuntimeTemplateTransform(Transform child)
    {
        if (child == null)
        {
            return false;
        }

        return (partCardTemplate != null && child == partCardTemplate.transform)
               || (partRandomButtonTemplate != null && child == partRandomButtonTemplate.transform)
               || (partEmptyButtonTemplate != null && child == partEmptyButtonTemplate.transform);
    }

    private bool IsColorRuntimeTemplateTransform(Transform child)
    {
        if (child == null)
        {
            return false;
        }

        return colorButtonTemplate != null
               && child == colorButtonTemplate.transform
               && !IsColorPaletteButtonTransform(child);
    }

    private void ResolvePagePanelRootReferences()
    {
        RectTransform customizePagePanel = FindChildByName<RectTransform>("CustomizePagePanel");
        RectTransform savePrefabsPagePanel = FindChildByName<RectTransform>("SavePrefabsPagePanel");
        savePrefabsPagePanel ??= FindChildByName<RectTransform>("SavedPrefabsPagePanel");

        if (customizePagePanel == null && partsPanelRoot != null)
        {
            customizePagePanel = FindAncestorRectTransformByName(partsPanelRoot, "CustomizePagePanel");
        }

        if (savePrefabsPagePanel == null && savePrefabsPanelRoot != null)
        {
            savePrefabsPagePanel = FindAncestorRectTransformByName(savePrefabsPanelRoot, "SavePrefabsPagePanel");
            savePrefabsPagePanel ??= FindAncestorRectTransformByName(savePrefabsPanelRoot, "SavedPrefabsPagePanel");
        }

        partsPanelRoot = customizePagePanel != null
            ? customizePagePanel
            : partsPanelRoot != null
                ? partsPanelRoot
                : FindChildByName<RectTransform>("PartsPanel");

        savePrefabsPanelRoot = savePrefabsPagePanel != null
            ? savePrefabsPagePanel
            : savePrefabsPanelRoot != null
                ? savePrefabsPanelRoot
                : FindChildByName<RectTransform>("SavePrefabsPanel");

        NormalizeSavePrefabsPanelHierarchyReferences();
    }

    private void NormalizeSavePrefabsPanelHierarchyReferences()
    {
        if (savePrefabsPanelRoot == null)
        {
            return;
        }

        ScrollRect scrollOnCurrentRoot = savePrefabsPanelRoot.GetComponent<ScrollRect>();
        if (savePrefabsScroll == null && scrollOnCurrentRoot != null)
        {
            savePrefabsScroll = scrollOnCurrentRoot;
        }

        RectTransform savePageRoot = FindAncestorRectTransformByName(savePrefabsPanelRoot, "SavePrefabsPagePanel");
        savePageRoot ??= FindAncestorRectTransformByName(savePrefabsPanelRoot, "SavedPrefabsPagePanel");
        if (savePageRoot != null)
        {
            savePrefabsPanelRoot = savePageRoot;
            return;
        }

        RectTransform savePanelRoot = FindAncestorRectTransformByName(savePrefabsPanelRoot, "SavePrefabsPanel");
        if (savePanelRoot != null)
        {
            savePrefabsPanelRoot = savePanelRoot;
        }
    }

    private static RectTransform FindAncestorRectTransformByName(Transform start, string objectName)
    {
        if (start == null || string.IsNullOrWhiteSpace(objectName))
        {
            return null;
        }

        Transform current = start;
        while (current != null)
        {
            if (string.Equals(current.name, objectName, StringComparison.Ordinal))
            {
                return current as RectTransform;
            }

            current = current.parent;
        }

        return null;
    }

    private static ScrollRect ResolveSavePrefabsScrollIn(Transform root)
    {
        if (root == null)
        {
            return null;
        }

        ScrollRect namedScroll = FindChildByNameIn<ScrollRect>(root, "SavePrefabsList");
        if (namedScroll != null)
        {
            return namedScroll;
        }

        namedScroll = FindChildByNameIn<ScrollRect>(root, "SavePanel");
        if (namedScroll != null)
        {
            return namedScroll;
        }

        return root.GetComponentInChildren<ScrollRect>(true);
    }

    private TMP_Dropdown ResolveSavedPrefabsCategoryDropdown()
    {
        TMP_Dropdown dropdown = FindSavedPrefabsCategoryDropdownIn(savePrefabsPanelRoot);
        if (dropdown != null)
        {
            return dropdown;
        }

        if (savePrefabsPanelRoot != null && savePrefabsPanelRoot.parent != null)
        {
            dropdown = FindSavedPrefabsCategoryDropdownIn(savePrefabsPanelRoot.parent);
            if (dropdown != null)
            {
                return dropdown;
            }
        }

        TMP_Dropdown[] dropdowns = MinimoUnityCompatibility.FindObjectsByType<TMP_Dropdown>(true);
        for (int i = 0; i < dropdowns.Length; i++)
        {
            TMP_Dropdown candidate = dropdowns[i];
            if (candidate == null || candidate == categoryDropdown)
            {
                continue;
            }

            if (HasAncestorContainingName(candidate.transform, "SavePrefabs")
                || HasAncestorContainingName(candidate.transform, "SavePanel")
                || HasAncestorContainingName(candidate.transform, "Saved"))
            {
                return candidate;
            }
        }

        return null;
    }

    private TMP_Dropdown FindSavedPrefabsCategoryDropdownIn(Component root)
    {
        if (root == null)
        {
            return null;
        }

        TMP_Dropdown[] dropdowns = root.GetComponentsInChildren<TMP_Dropdown>(true);
        for (int i = 0; i < dropdowns.Length; i++)
        {
            TMP_Dropdown candidate = dropdowns[i];
            if (candidate != null && candidate != categoryDropdown)
            {
                return candidate;
            }
        }

        return null;
    }

    private static void CopyDropdownButtonVisualChildren(RectTransform sourceRoot, RectTransform targetRoot)
    {
        if (sourceRoot == null || targetRoot == null)
        {
            return;
        }

        CopyDropdownButtonVisualChild(sourceRoot, targetRoot, "Label");
        CopyDropdownButtonVisualChild(sourceRoot, targetRoot, "Arrow");
    }

    private static void CopyDropdownButtonVisualChild(RectTransform sourceRoot, RectTransform targetRoot, string childName)
    {
        if (sourceRoot == null
            || targetRoot == null
            || string.IsNullOrWhiteSpace(childName)
            || FindChildByNameIn<RectTransform>(targetRoot, childName) != null)
        {
            return;
        }

        RectTransform sourceChild = FindChildByNameIn<RectTransform>(sourceRoot, childName);
        if (sourceChild == null || sourceChild == sourceRoot)
        {
            return;
        }

        GameObject clone = Instantiate(sourceChild.gameObject, targetRoot, false);
        clone.name = StripUnityCloneSuffix(sourceChild.gameObject.name);
        clone.SetActive(sourceChild.gameObject.activeSelf);
    }

    private static void ConfigureRuntimeDropdownLabel(
        RectTransform labelRect,
        TMP_Dropdown sourceDropdown,
        Font fallbackFont,
        bool createdLabel,
        out Text textLabel,
        out TMP_Text tmpLabel,
        Color? tmpTextColorOverride = null)
    {
        textLabel = null;
        tmpLabel = null;
        if (labelRect == null)
        {
            return;
        }

        tmpLabel = labelRect.GetComponent<TMP_Text>();
        textLabel = labelRect.GetComponent<Text>();
        TMP_Text sourceTmp = sourceDropdown != null ? sourceDropdown.captionText : null;
        Text sourceText = ResolveDropdownOptionTextStyle(sourceDropdown);

        if (tmpLabel != null)
        {
            return;
        }

        if (textLabel == null)
        {
            textLabel = labelRect.gameObject.AddComponent<Text>();
        }

        CopyTextStyle(sourceText, sourceTmp, textLabel, fallbackFont);
        if (createdLabel)
        {
            textLabel.horizontalOverflow = HorizontalWrapMode.Wrap;
            textLabel.verticalOverflow = VerticalWrapMode.Truncate;
        }

        textLabel.raycastTarget = false;
    }

    private static void ApplyDropdownButtonTmpTextColor(TMP_Text tmpLabel)
    {
        ApplyDropdownButtonTmpTextColor(tmpLabel, DropdownButtonTmpTextColor);
    }

    private static void ApplyDropdownButtonTmpTextColor(TMP_Text tmpLabel, Color color)
    {
        if (tmpLabel != null)
        {
            tmpLabel.color = color;
        }
    }

    private static void ConfigureRuntimeDropdownArrow(
        RectTransform arrowRect,
        TMP_Dropdown sourceDropdown,
        Font fallbackFont,
        bool createdArrow)
    {
        if (arrowRect == null)
        {
            return;
        }

        SetGraphicRaycastTargets(arrowRect, false);
        if (!createdArrow && HasDropdownArrowVisual(arrowRect))
        {
            return;
        }

        Text arrowText = arrowRect.GetComponent<Text>();
        if (arrowText == null)
        {
            arrowText = arrowRect.gameObject.AddComponent<Text>();
        }

        TMP_Text sourceTmp = sourceDropdown != null ? sourceDropdown.captionText : null;
        CopyTextStyle(null, sourceTmp, arrowText, fallbackFont);
        arrowText.alignment = TextAnchor.MiddleCenter;
        arrowText.text = "v";
        arrowText.raycastTarget = false;
    }

    private static bool HasDropdownArrowVisual(RectTransform arrowRect)
    {
        if (arrowRect == null)
        {
            return false;
        }

        if (arrowRect.GetComponent<TMP_Text>() != null || arrowRect.GetComponent<Text>() != null)
        {
            return true;
        }

        Image image = arrowRect.GetComponent<Image>();
        return image != null && (image.sprite != null || image.color.a > 0.0001f);
    }

    private static void SetGraphicRaycastTargets(Transform root, bool raycastTarget)
    {
        if (root == null)
        {
            return;
        }

        Graphic[] graphics = root.GetComponentsInChildren<Graphic>(true);
        for (int i = 0; i < graphics.Length; i++)
        {
            if (graphics[i] != null)
            {
                graphics[i].raycastTarget = raycastTarget;
            }
        }
    }

    private static TMP_Text ResolveDropdownOptionTmpTextStyle(TMP_Dropdown dropdown)
    {
        return dropdown != null ? dropdown.itemText ?? dropdown.captionText : null;
    }

    private static void ApplyDropdownOptionFallbackFont(TMP_Dropdown dropdown)
    {
        if (dropdown == null
            || dropdown.itemText == null
            || dropdown.itemText == dropdown.captionText)
        {
            return;
        }

        TMP_FontAsset optionFont = ResolveDropdownOptionFallbackFont(dropdown.itemText);
        if (optionFont != null)
        {
            dropdown.itemText.font = optionFont;
        }
    }

    private static Text ResolveDropdownOptionTextStyle(TMP_Dropdown dropdown)
    {
        if (dropdown == null)
        {
            return null;
        }

        Text[] labels = dropdown.GetComponentsInChildren<Text>(true);
        for (int i = 0; i < labels.Length; i++)
        {
            Text label = labels[i];
            if (label == null)
            {
                continue;
            }

            if (dropdown.template != null && label.transform.IsChildOf(dropdown.template))
            {
                return label;
            }

            if (string.Equals(label.gameObject.name, "Label", StringComparison.OrdinalIgnoreCase)
                || string.Equals(label.gameObject.name, "Text", StringComparison.OrdinalIgnoreCase))
            {
                return label;
            }
        }

        return labels.Length > 0 ? labels[0] : null;
    }

    private static void CopyTmpTextStyle(TMP_Text source, TMP_Text target)
    {
        if (source == null || target == null)
        {
            return;
        }

        target.font = source.font;
        target.fontSharedMaterial = source.fontSharedMaterial;
        target.fontSize = source.fontSize;
        target.fontStyle = source.fontStyle;
        target.color = source.color;
        target.alignment = source.alignment;
        CopyTmpWrapping(source, target);
        target.overflowMode = source.overflowMode;
    }

    private static void CopyTextStyle(Text sourceText, TMP_Text sourceTmp, Text target, Font fallbackFont)
    {
        if (target == null)
        {
            return;
        }

        if (sourceText != null)
        {
            target.font = sourceText.font != null ? sourceText.font : fallbackFont;
            target.fontSize = sourceText.fontSize;
            target.fontStyle = sourceText.fontStyle;
            target.color = sourceText.color;
            target.alignment = sourceText.alignment;
            target.horizontalOverflow = sourceText.horizontalOverflow;
            target.verticalOverflow = sourceText.verticalOverflow;
            return;
        }

        target.font = fallbackFont;
        if (sourceTmp != null)
        {
            target.fontSize = Mathf.Max(1, Mathf.RoundToInt(sourceTmp.fontSize));
            target.color = sourceTmp.color;
            target.alignment = ConvertTmpAlignmentToTextAnchor(sourceTmp.alignment);
            target.horizontalOverflow = IsTmpNoWrap(sourceTmp)
                ? HorizontalWrapMode.Overflow
                : HorizontalWrapMode.Wrap;
            target.verticalOverflow = sourceTmp.overflowMode == TextOverflowModes.Overflow
                ? VerticalWrapMode.Overflow
                : VerticalWrapMode.Truncate;
            return;
        }

        target.fontSize = 13;
        target.alignment = TextAnchor.MiddleLeft;
        target.color = new Color(0.95f, 0.97f, 1f, 1f);
        target.horizontalOverflow = HorizontalWrapMode.Wrap;
        target.verticalOverflow = VerticalWrapMode.Truncate;
    }

    private static void CopyTmpWrapping(TMP_Text source, TMP_Text target)
    {
        if (source == null || target == null)
        {
            return;
        }

#if UNITY_6000_0_OR_NEWER
        target.textWrappingMode = source.textWrappingMode;
#else
#pragma warning disable 0618
        target.enableWordWrapping = source.enableWordWrapping;
#pragma warning restore 0618
#endif
    }

    private static bool IsTmpNoWrap(TMP_Text text)
    {
        if (text == null)
        {
            return false;
        }

#if UNITY_6000_0_OR_NEWER
        return text.textWrappingMode == TextWrappingModes.NoWrap;
#else
#pragma warning disable 0618
        return !text.enableWordWrapping;
#pragma warning restore 0618
#endif
    }

    private static void SetTmpWrapping(TMP_Text text, bool enabled)
    {
        if (text == null)
        {
            return;
        }

#if UNITY_6000_0_OR_NEWER
        text.textWrappingMode = enabled ? TextWrappingModes.Normal : TextWrappingModes.NoWrap;
#else
#pragma warning disable 0618
        text.enableWordWrapping = enabled;
#pragma warning restore 0618
#endif
    }

    private static TextAnchor ConvertTmpAlignmentToTextAnchor(TextAlignmentOptions alignment)
    {
        if ((alignment & TextAlignmentOptions.Center) != 0)
        {
            return TextAnchor.MiddleCenter;
        }

        if ((alignment & TextAlignmentOptions.Right) != 0)
        {
            return TextAnchor.MiddleRight;
        }

        return TextAnchor.MiddleLeft;
    }

    private static bool EnsureDropdownOptionsRoot(
        RectTransform dropdownRoot,
        Color backgroundColor,
        out RectTransform optionsRoot)
    {
        optionsRoot = null;
        if (dropdownRoot == null)
        {
            return false;
        }

        optionsRoot = FindChildByNameIn<RectTransform>(dropdownRoot, "Options");
        bool created = false;
        if (optionsRoot == null)
        {
            optionsRoot = CreateRect(
                "Options",
                dropdownRoot,
                new Vector2(0f, 0f),
                new Vector2(1f, 0f),
                new Vector2(0.5f, 1f),
                new Vector2(0f, 0f),
                new Vector2(0f, -4f));
            created = true;
        }
        else
        {
            optionsRoot.anchorMin = new Vector2(0f, 0f);
            optionsRoot.anchorMax = new Vector2(1f, 0f);
            optionsRoot.pivot = new Vector2(0.5f, 1f);
            optionsRoot.sizeDelta = Vector2.zero;
            optionsRoot.anchoredPosition = new Vector2(0f, -4f);
        }

        Image optionsBackground = optionsRoot.GetComponent<Image>();
        if (optionsBackground == null)
        {
            optionsBackground = optionsRoot.gameObject.AddComponent<Image>();
        }

        optionsBackground.color = DropdownOptionsPanelImageColor;
        optionsBackground.raycastTarget = true;

        Mask popupMask = optionsRoot.GetComponent<Mask>();
        if (popupMask == null)
        {
            popupMask = optionsRoot.gameObject.AddComponent<Mask>();
        }

        popupMask.showMaskGraphic = true;

        VerticalLayoutGroup layoutGroup = optionsRoot.GetComponent<VerticalLayoutGroup>();
        if (layoutGroup == null)
        {
            layoutGroup = optionsRoot.gameObject.AddComponent<VerticalLayoutGroup>();
        }

        layoutGroup.padding = new RectOffset(4, 4, 4, 4);
        layoutGroup.spacing = 4f;
        layoutGroup.childControlWidth = true;
        layoutGroup.childControlHeight = true;
        layoutGroup.childForceExpandWidth = true;
        layoutGroup.childForceExpandHeight = false;

        ContentSizeFitter fitter = optionsRoot.GetComponent<ContentSizeFitter>();
        if (fitter == null)
        {
            fitter = optionsRoot.gameObject.AddComponent<ContentSizeFitter>();
        }

        fitter.horizontalFit = ContentSizeFitter.FitMode.Unconstrained;
        fitter.verticalFit = ContentSizeFitter.FitMode.PreferredSize;
        return created;
    }

    private static bool ApplyDropdownOptionsPanelColor(RectTransform optionsRoot)
    {
        if (optionsRoot == null)
        {
            return false;
        }

        Image optionsBackground = optionsRoot.GetComponent<Image>();
        if (optionsBackground == null)
        {
            optionsBackground = optionsRoot.gameObject.AddComponent<Image>();
        }

        if (optionsBackground.color == DropdownOptionsPanelImageColor)
        {
            return false;
        }

        optionsBackground.color = DropdownOptionsPanelImageColor;
        return true;
    }

    private bool EnsureEditorDropdownOptionPreview(RectTransform optionsRoot, string label)
    {
        if (optionsRoot == null || string.IsNullOrWhiteSpace(label))
        {
            return false;
        }

        Button existing = FindDropdownOptionButtonByText(optionsRoot, label);
        if (existing != null)
        {
            bool changed = false;
            string targetName = BuildDropdownOptionObjectName(label);
            if (!string.Equals(existing.gameObject.name, targetName, StringComparison.Ordinal))
            {
                existing.gameObject.name = targetName;
                changed = true;
            }

            changed |= ApplyDropdownOptionButtonColors(existing);
            return changed;
        }

        Button optionButton = CreateCategoryDropdownOptionButton(
            optionsRoot,
            ResolveFont(),
            label,
            null,
            null);
        if (optionButton != null)
        {
            optionButton.onClick.RemoveAllListeners();
            optionButton.gameObject.name = BuildDropdownOptionObjectName(label);
            ApplyDropdownOptionButtonColors(optionButton);
        }

        return optionButton != null;
    }

    private bool ApplyDropdownOptionColorsInRoot(RectTransform optionsRoot)
    {
        if (optionsRoot == null)
        {
            return false;
        }

        bool changed = ApplyDropdownOptionsPanelColor(optionsRoot);
        Button[] buttons = optionsRoot.GetComponentsInChildren<Button>(true);
        for (int i = 0; i < buttons.Length; i++)
        {
            Button button = buttons[i];
            if (button == null)
            {
                continue;
            }

            changed |= ApplyDropdownOptionButtonColors(button);
        }

        return changed;
    }

    private bool ApplyDropdownOptionButtonColors(Button optionButton)
    {
        if (optionButton == null)
        {
            return false;
        }

        bool changed = false;
        Image background = optionButton.targetGraphic as Image;
        background ??= optionButton.GetComponent<Image>();
        if (background != null && background.color != DropdownOptionButtonImageColor)
        {
            background.color = DropdownOptionButtonImageColor;
            changed = true;
        }

        changed |= ApplyDropdownOptionButtonTintColors(optionButton);
        return changed;
    }

    private static bool ApplyDropdownOptionButtonTintColors(Button optionButton)
    {
        if (optionButton == null)
        {
            return false;
        }

        ColorBlock colors = optionButton.colors;
        bool changed = colors.normalColor != DropdownOptionButtonTintColor
                       || colors.highlightedColor != DropdownOptionButtonTintColor
                       || colors.pressedColor != DropdownOptionButtonTintColor
                       || colors.selectedColor != DropdownOptionButtonTintColor
                       || colors.disabledColor != DropdownOptionButtonTintColor
                       || !Mathf.Approximately(colors.colorMultiplier, 1f);
        if (!changed)
        {
            return false;
        }

        colors.normalColor = DropdownOptionButtonTintColor;
        colors.highlightedColor = DropdownOptionButtonTintColor;
        colors.pressedColor = DropdownOptionButtonTintColor;
        colors.selectedColor = DropdownOptionButtonTintColor;
        colors.disabledColor = DropdownOptionButtonTintColor;
        colors.colorMultiplier = 1f;
        optionButton.colors = colors;
        return true;
    }

    private static Button FindDropdownOptionButtonByText(RectTransform optionsRoot, string label)
    {
        if (optionsRoot == null || string.IsNullOrWhiteSpace(label))
        {
            return null;
        }

        string normalizedLabel = NormalizeDropdownOptionObjectToken(label);
        Button[] buttons = optionsRoot.GetComponentsInChildren<Button>(true);
        for (int i = 0; i < buttons.Length; i++)
        {
            Button button = buttons[i];
            if (button == null)
            {
                continue;
            }

            TMP_Text tmpLabel = FindChildByNameIn<TMP_Text>(button.transform, "Label");
            if (tmpLabel != null
                && string.Equals(NormalizeDropdownOptionObjectToken(tmpLabel.text), normalizedLabel, StringComparison.OrdinalIgnoreCase))
            {
                return button;
            }

            Text textLabel = FindChildByNameIn<Text>(button.transform, "Label");
            if (textLabel != null
                && string.Equals(NormalizeDropdownOptionObjectToken(textLabel.text), normalizedLabel, StringComparison.OrdinalIgnoreCase))
            {
                return button;
            }
        }

        return null;
    }

    private static string BuildDropdownOptionObjectName(string label)
    {
        string token = NormalizeDropdownOptionObjectToken(label);
        return string.IsNullOrWhiteSpace(token)
            ? "CategoryOption"
            : $"CategoryOption_{token}";
    }

    private static string NormalizeDropdownOptionObjectToken(string label)
    {
        if (string.IsNullOrWhiteSpace(label))
        {
            return string.Empty;
        }

        string value = label.Trim();
        if (value.StartsWith(DropdownSelectedOptionPrefix, StringComparison.Ordinal))
        {
            value = value.Substring(DropdownSelectedOptionPrefix.Length).Trim();
        }

        StringBuilder builder = new StringBuilder();
        for (int i = 0; i < value.Length; i++)
        {
            char c = value[i];
            if (char.IsLetterOrDigit(c))
            {
                builder.Append(c);
            }
            else if (builder.Length > 0 && builder[builder.Length - 1] != '_')
            {
                builder.Append('_');
            }
        }

        return builder.ToString().Trim('_');
    }

    private void EnsureCustomCategoryDropdown()
    {
        bool hasCategoryDropdownClickTarget = customCategoryDropdownToggleButton != null || UsesSceneCategoryDropdownButton();
        if (customCategoryDropdownRoot != null
            && hasCategoryDropdownClickTarget
            && (customCategoryDropdownLabel != null || customCategoryDropdownTmpLabel != null)
            && customCategoryDropdownOptionsRoot != null)
        {
            return;
        }

        RectTransform templateRect = categoryDropdown != null ? categoryDropdown.transform as RectTransform : null;
        RectTransform parent = templateRect != null
            ? templateRect.parent as RectTransform
            : categoryControlsRowRoot;
        parent ??= partsPanelRoot;
        parent ??= transform as RectTransform;
        if (parent == null)
        {
            return;
        }

        bool useSceneDropdownButton = templateRect != null;
        if (useSceneDropdownButton)
        {
            customCategoryDropdownRoot = templateRect;
            DisableSceneCategoryDropdownBehaviourForCustomButton();
        }
        else
        {
            customCategoryDropdownRoot = CreateRect(
                "RuntimeCategoryDropdown",
                parent,
                new Vector2(0f, 1f),
                new Vector2(0f, 1f),
                new Vector2(0f, 1f),
                new Vector2(220f, 34f),
                Vector2.zero);
        }

        Image templateImage = templateRect != null ? templateRect.GetComponent<Image>() : null;
        Image rootImage = customCategoryDropdownRoot.GetComponent<Image>();
        if (!useSceneDropdownButton)
        {
            if (rootImage == null)
            {
                rootImage = customCategoryDropdownRoot.gameObject.AddComponent<Image>();
            }

            if (templateImage != null)
            {
                CopyImageStyle(templateImage, rootImage, copyColor: true);
            }
            else
            {
                rootImage.color = UiSurfaceSecondaryColor;
            }

            rootImage.raycastTarget = true;
        }

        customCategoryDropdownToggleButton = customCategoryDropdownRoot.GetComponent<Button>();
        if (customCategoryDropdownToggleButton == null)
        {
            customCategoryDropdownToggleButton = useSceneDropdownButton
                ? null
                : customCategoryDropdownRoot.gameObject.AddComponent<Button>();
        }

        if (useSceneDropdownButton)
        {
            EnsureSceneCategoryDropdownClickBridge();
        }

        if (customCategoryDropdownToggleButton != null)
        {
            customCategoryDropdownToggleButton.onClick.RemoveListener(ToggleCustomCategoryDropdown);
            customCategoryDropdownToggleButton.onClick.AddListener(ToggleCustomCategoryDropdown);
            if (!useSceneDropdownButton && rootImage != null)
            {
                customCategoryDropdownToggleButton.targetGraphic = rootImage;
                ApplyButtonInteractionStyle(customCategoryDropdownToggleButton, rootImage.color);
                ConfigureDropdownColorTint(customCategoryDropdownToggleButton, categoryDropdown);
            }
        }

        Font font = ResolveFont();
        TMP_Text sceneButtonTmpLabel = useSceneDropdownButton ? ResolveCategoryDropdownButtonTmpLabel() : null;
        RectTransform labelRect = sceneButtonTmpLabel != null
            ? sceneButtonTmpLabel.transform as RectTransform
            : FindChildByNameIn<RectTransform>(customCategoryDropdownRoot, "Label");
        bool createdLabel = false;
        if (labelRect == null && !useSceneDropdownButton)
        {
            createdLabel = true;
            labelRect = CreateRect(
                "Label",
                customCategoryDropdownRoot,
                new Vector2(0f, 0f),
                new Vector2(1f, 1f),
                new Vector2(0.5f, 0.5f),
                Vector2.zero,
                Vector2.zero);
            labelRect.offsetMin = new Vector2(10f, 0f);
            labelRect.offsetMax = new Vector2(-24f, 0f);
        }

        if (labelRect != null)
        {
            ConfigureRuntimeDropdownLabel(
                labelRect,
                categoryDropdown,
                font,
                createdLabel,
                out customCategoryDropdownLabel,
                out customCategoryDropdownTmpLabel);
        }

        if (!useSceneDropdownButton)
        {
            RectTransform arrowRect = FindChildByNameIn<RectTransform>(customCategoryDropdownRoot, "Arrow");
            bool createdArrow = false;
            if (arrowRect == null)
            {
                createdArrow = true;
                arrowRect = CreateRect(
                    "Arrow",
                    customCategoryDropdownRoot,
                    new Vector2(1f, 0f),
                    new Vector2(1f, 1f),
                    new Vector2(1f, 0.5f),
                    new Vector2(18f, 0f),
                    new Vector2(-6f, 0f));
            }

            ConfigureRuntimeDropdownArrow(arrowRect, categoryDropdown, font, createdArrow);
        }

        EnsureDropdownOptionsRoot(
            customCategoryDropdownRoot,
            runtimeDropdownPopupBackgroundColor,
            out customCategoryDropdownOptionsRoot);
        if (customCategoryDropdownOptionsRoot == null)
        {
            return;
        }

        Image optionsBackground = customCategoryDropdownOptionsRoot.GetComponent<Image>();
        Image popupStyleSource = rootImage != null ? rootImage : ResolveCategoryDropdownListStyleSource();
        if (popupStyleSource != null)
        {
            CopyImageStyle(popupStyleSource, optionsBackground, copyColor: true);
        }
        else
        {
            optionsBackground.color = UiSurfaceSecondaryColor;
        }

        customCategoryDropdownOptionsRoot.gameObject.SetActive(false);
        customCategoryDropdownOptionsOriginalParent = customCategoryDropdownOptionsRoot.parent;
        customCategoryDropdownOptionsOriginalSiblingIndex = customCategoryDropdownOptionsRoot.GetSiblingIndex();
    }

    private bool UsesSceneCategoryDropdownButton()
    {
        RectTransform categoryDropdownRect = categoryDropdown != null ? categoryDropdown.transform as RectTransform : null;
        return categoryDropdown != null
            && customCategoryDropdownRoot != null
            && customCategoryDropdownRoot == categoryDropdownRect;
    }

    private void DisableSceneCategoryDropdownBehaviourForCustomButton()
    {
        if (categoryDropdown == null)
        {
            return;
        }

        if (!categoryDropdownOriginalEnabledCaptured)
        {
            categoryDropdownOriginalEnabled = categoryDropdown.enabled;
            categoryDropdownOriginalEnabledCaptured = true;
        }

        categoryDropdown.enabled = false;
    }

    private void RestoreSceneCategoryDropdownBehaviour()
    {
        if (!categoryDropdownOriginalEnabledCaptured || categoryDropdown == null)
        {
            return;
        }

        categoryDropdown.enabled = categoryDropdownOriginalEnabled;
        categoryDropdownOriginalEnabledCaptured = false;
    }

    private void EnsureSceneCategoryDropdownClickBridge()
    {
        if (categoryDropdown == null)
        {
            return;
        }

        RuntimeCategoryDropdownClickBridge bridge = categoryDropdown.GetComponent<RuntimeCategoryDropdownClickBridge>();
        if (bridge == null)
        {
            bridge = categoryDropdown.gameObject.AddComponent<RuntimeCategoryDropdownClickBridge>();
        }

        bridge.owner = this;
    }

    private void HandleSceneCategoryDropdownButtonClicked()
    {
        if (!controlsInteractable || categoryDropdownOptions.Count <= 1)
        {
            return;
        }

        ToggleCustomCategoryDropdown();
    }

    private TMP_Text ResolveCategoryDropdownButtonTmpLabel()
    {
        if (categoryDropdown == null)
        {
            return customCategoryDropdownTmpLabel;
        }

        if (IsCategoryDropdownButtonTmpLabel(categoryDropdown.captionText))
        {
            return categoryDropdown.captionText;
        }

        TMP_Text namedLabel = FindCategoryDropdownButtonTmpLabelByName("Text (TMP)");
        if (namedLabel != null)
        {
            return namedLabel;
        }

        namedLabel = FindCategoryDropdownButtonTmpLabelByName("Label");
        if (namedLabel != null)
        {
            return namedLabel;
        }

        TMP_Text[] labels = categoryDropdown.GetComponentsInChildren<TMP_Text>(true);
        for (int i = 0; i < labels.Length; i++)
        {
            if (IsCategoryDropdownButtonTmpLabel(labels[i]))
            {
                return labels[i];
            }
        }

        return null;
    }

    private TMP_Text FindCategoryDropdownButtonTmpLabelByName(string objectName)
    {
        if (categoryDropdown == null || string.IsNullOrWhiteSpace(objectName))
        {
            return null;
        }

        TMP_Text[] labels = categoryDropdown.GetComponentsInChildren<TMP_Text>(true);
        for (int i = 0; i < labels.Length; i++)
        {
            TMP_Text label = labels[i];
            if (label != null
                && string.Equals(label.gameObject.name, objectName, StringComparison.Ordinal)
                && IsCategoryDropdownButtonTmpLabel(label))
            {
                return label;
            }
        }

        return null;
    }

    private bool IsCategoryDropdownButtonTmpLabel(TMP_Text label)
    {
        if (label == null || categoryDropdown == null)
        {
            return false;
        }

        Transform labelTransform = label.transform;
        if (!labelTransform.IsChildOf(categoryDropdown.transform))
        {
            return false;
        }

        if (categoryDropdown.template != null && labelTransform.IsChildOf(categoryDropdown.template))
        {
            return false;
        }

        if (customCategoryDropdownOptionsRoot != null
            && labelTransform.IsChildOf(customCategoryDropdownOptionsRoot))
        {
            return false;
        }

        return true;
    }

    private void ToggleCustomCategoryDropdown()
    {
        SetCustomCategoryDropdownOpen(!customCategoryDropdownExpanded);
    }

    private void SetCustomCategoryDropdownOpen(bool isOpen)
    {
        customCategoryDropdownExpanded = isOpen && categoryDropdownOptions.Count > 0;
        if (customCategoryDropdownExpanded)
        {
            SetCustomSavedPrefabDropdownOpen(false);
        }

        if (customCategoryDropdownExpanded && customCategoryDropdownRoot != null)
        {
            if (!UsesSceneCategoryDropdownButton())
            {
                customCategoryDropdownRoot.SetAsLastSibling();
            }

            BringCustomCategoryDropdownPopupToFront();
        }
        else
        {
            RestoreCustomCategoryDropdownPopupParent();
        }

        if (customCategoryDropdownOptionsRoot != null)
        {
            customCategoryDropdownOptionsRoot.gameObject.SetActive(customCategoryDropdownExpanded);
        }

        UpdateShadowStickyButtonStates();
    }

    private void BringCustomCategoryDropdownPopupToFront()
    {
        if (customCategoryDropdownOptionsRoot == null)
        {
            return;
        }

        Canvas canvas = customCategoryDropdownRoot != null
            ? customCategoryDropdownRoot.GetComponentInParent<Canvas>()
            : customCategoryDropdownOptionsRoot.GetComponentInParent<Canvas>();
        RectTransform canvasRect = canvas != null ? canvas.transform as RectTransform : null;
        if (canvasRect == null)
        {
            return;
        }

        customCategoryDropdownOptionsOriginalParent ??= customCategoryDropdownOptionsRoot.parent;
        if (customCategoryDropdownOptionsOriginalSiblingIndex < 0)
        {
            customCategoryDropdownOptionsOriginalSiblingIndex = customCategoryDropdownOptionsRoot.GetSiblingIndex();
        }

        if (customCategoryDropdownOptionsRoot.parent != canvasRect)
        {
            customCategoryDropdownOptionsRoot.SetParent(canvasRect, true);
        }

        customCategoryDropdownOptionsRoot.SetAsLastSibling();
    }

    private void RestoreCustomCategoryDropdownPopupParent()
    {
        if (customCategoryDropdownOptionsRoot == null || customCategoryDropdownOptionsOriginalParent == null)
        {
            return;
        }

        if (customCategoryDropdownOptionsRoot.parent != customCategoryDropdownOptionsOriginalParent)
        {
            customCategoryDropdownOptionsRoot.SetParent(customCategoryDropdownOptionsOriginalParent, true);
        }

        int maxSibling = Mathf.Max(0, customCategoryDropdownOptionsRoot.parent.childCount - 1);
        int siblingIndex = customCategoryDropdownOptionsOriginalSiblingIndex >= 0
            ? Mathf.Clamp(customCategoryDropdownOptionsOriginalSiblingIndex, 0, maxSibling)
            : maxSibling;
        customCategoryDropdownOptionsRoot.SetSiblingIndex(siblingIndex);
    }

    private void RebuildCustomCategoryDropdownOptions()
    {
        customCategoryDropdownOptionButtons.Clear();
        if (customCategoryDropdownOptionsRoot == null)
        {
            if (categoryDropdown != null)
            {
                List<TMP_Dropdown.OptionData> options = new List<TMP_Dropdown.OptionData>();
                for (int i = 0; i < categoryDropdownOptions.Count; i++)
                {
                    options.Add(new TMP_Dropdown.OptionData(BuildCategoryToggleOptionText(categoryDropdownOptions[i])));
                }

                categoryDropdown.ClearOptions();
                categoryDropdown.AddOptions(options);
                selectedCategoryDropdownIndex = Mathf.Clamp(
                    selectedCategoryDropdownIndex,
                    0,
                    Mathf.Max(0, categoryDropdownOptions.Count - 1));
                categoryDropdown.SetValueWithoutNotify(selectedCategoryDropdownIndex);
                categoryDropdown.RefreshShownValue();
                categoryDropdown.interactable = categoryDropdownOptions.Count > 1;
                UpdateCustomCategoryDropdownLabel();
            }

            return;
        }

        bool keepOpen = customCategoryDropdownExpanded;
        List<Button> existingOptionButtons = CollectDirectDropdownOptionButtons(customCategoryDropdownOptionsRoot);

        Font font = ResolveFont();
        TMP_Text optionTmpTextStyle = ResolveDropdownOptionTmpTextStyle(categoryDropdown);
        Image optionStyleSource = ResolveDropdownOptionImageStyleSource(
            existingOptionButtons,
            ResolveCategoryDropdownPopupStyleSource());
        for (int i = 0; i < categoryDropdownOptions.Count; i++)
        {
            int capturedIndex = i;
            string optionLabel = BuildCategoryToggleOptionText(categoryDropdownOptions[i]);
            Button optionButton = i < existingOptionButtons.Count
                ? existingOptionButtons[i]
                : CreateCategoryDropdownOptionButton(
                    customCategoryDropdownOptionsRoot,
                    font,
                    optionLabel,
                    optionStyleSource,
                    optionTmpTextStyle);
            if (optionButton == null)
            {
                continue;
            }

            optionButton.gameObject.SetActive(true);
            SetDropdownOptionButtonText(optionButton, optionLabel);
            EnsureShadowPressTracking(optionButton);
            optionButton.onClick.RemoveAllListeners();
            optionButton.onClick.AddListener(() => HandleCustomCategoryOptionSelected(capturedIndex));
            customCategoryDropdownOptionButtons.Add(optionButton);
        }

        for (int i = categoryDropdownOptions.Count; i < existingOptionButtons.Count; i++)
        {
            HideUnusedDropdownOptionButton(existingOptionButtons[i]);
        }

        selectedCategoryDropdownIndex = Mathf.Clamp(
            selectedCategoryDropdownIndex,
            0,
            Mathf.Max(0, categoryDropdownOptions.Count - 1));
        SetCustomCategoryDropdownOpen(keepOpen);
        UpdateCustomCategoryDropdownLabel();
        if (categoryDropdown != null && !UsesSceneCategoryDropdownButton())
        {
            categoryDropdown.gameObject.SetActive(false);
        }
    }

    private void RefreshCustomCategoryDropdownOptionTexts()
    {
        for (int i = 0; i < customCategoryDropdownOptionButtons.Count && i < categoryDropdownOptions.Count; i++)
        {
            SetDropdownOptionButtonText(
                customCategoryDropdownOptionButtons[i],
                BuildCategoryToggleOptionText(categoryDropdownOptions[i]));
        }
    }

    private void HandleCustomCategoryOptionSelected(int optionIndex)
    {
        HandleCategoryDropdownChanged(optionIndex);
    }

    private void UpdateCustomCategoryDropdownLabel()
    {
        string caption = CategoryAllOptionLabel;
        if (categoryDropdownOptions.Count == 0)
        {
            caption = CategoryAllOptionLabel;
        }
        else if (IsCategorySelectionActive(CategoryAllOptionLabel))
        {
            caption = CategoryAllOptionLabel;
        }
        else
        {
            List<string> activeCategories = new List<string>();
            for (int i = 0; i < categoryDropdownOptions.Count; i++)
            {
                string categoryName = NormalizeCategoryName(categoryDropdownOptions[i]);
                if (IsAllCategoryName(categoryName) || !IsCategorySelectionActive(categoryName))
                {
                    continue;
                }

                activeCategories.Add(categoryName);
            }

            caption = activeCategories.Count > 0
                ? string.Join(" + ", activeCategories)
                : CategoryAllOptionLabel;
        }

        if (customCategoryDropdownLabel != null)
        {
            customCategoryDropdownLabel.text = caption;
        }

        TMP_Text categoryButtonTmpLabel = UsesSceneCategoryDropdownButton()
            ? ResolveCategoryDropdownButtonTmpLabel()
            : customCategoryDropdownTmpLabel;
        if (categoryButtonTmpLabel != null)
        {
            categoryButtonTmpLabel.text = caption;
            customCategoryDropdownTmpLabel = categoryButtonTmpLabel;
        }

        if (categoryDropdown != null && categoryDropdown.captionText != null)
        {
            categoryDropdown.captionText.text = caption;
        }

        RefreshCustomCategoryDropdownOptionTexts();
    }

    private void EnsureCustomSavedPrefabDropdown()
    {
        bool hasSavedPrefabDropdownClickTarget = customSavedPrefabDropdownToggleButton != null || UsesSceneSavedPrefabDropdownButton();
        if (customSavedPrefabDropdownRoot != null
            && hasSavedPrefabDropdownClickTarget
            && (customSavedPrefabDropdownLabel != null || customSavedPrefabDropdownTmpLabel != null)
            && customSavedPrefabDropdownOptionsRoot != null)
        {
            if (savedPrefabsCategoryDropdown != null && !UsesSceneSavedPrefabDropdownButton())
            {
                savedPrefabsCategoryDropdown.gameObject.SetActive(false);
            }

            return;
        }

        RectTransform templateRect = savedPrefabsCategoryDropdown != null
            ? savedPrefabsCategoryDropdown.transform as RectTransform
            : null;
        RectTransform parent = templateRect != null
            ? templateRect.parent as RectTransform
            : savePrefabsPanelRoot;
        parent ??= transform as RectTransform;
        if (parent == null)
        {
            return;
        }

        bool useSceneDropdownButton = templateRect != null;
        if (useSceneDropdownButton)
        {
            customSavedPrefabDropdownRoot = templateRect;
            DisableSceneSavedPrefabDropdownBehaviourForCustomButton();
        }
        else
        {
            customSavedPrefabDropdownRoot = CreateRect(
                "RuntimeSavedPrefabDropdown",
                parent,
                new Vector2(0f, 1f),
                new Vector2(1f, 1f),
                new Vector2(0f, 1f),
                new Vector2(-32f, 36f),
                new Vector2(16f, -100f));
        }

        Image templateImage = templateRect != null ? templateRect.GetComponent<Image>() : null;
        Image rootImage = customSavedPrefabDropdownRoot.GetComponent<Image>();
        if (!useSceneDropdownButton)
        {
            if (rootImage == null)
            {
                rootImage = customSavedPrefabDropdownRoot.gameObject.AddComponent<Image>();
            }

            if (templateImage != null)
            {
                CopyImageStyle(templateImage, rootImage, copyColor: true);
            }
            else
            {
                rootImage.color = DropdownThemeColor;
            }

            rootImage.raycastTarget = true;
        }

        customSavedPrefabDropdownToggleButton = customSavedPrefabDropdownRoot.GetComponent<Button>();
        if (customSavedPrefabDropdownToggleButton == null)
        {
            customSavedPrefabDropdownToggleButton = useSceneDropdownButton
                ? null
                : customSavedPrefabDropdownRoot.gameObject.AddComponent<Button>();
        }

        if (useSceneDropdownButton)
        {
            EnsureSceneSavedPrefabDropdownClickBridge();
        }

        if (customSavedPrefabDropdownToggleButton != null)
        {
            customSavedPrefabDropdownToggleButton.onClick.RemoveListener(ToggleCustomSavedPrefabDropdown);
            customSavedPrefabDropdownToggleButton.onClick.AddListener(ToggleCustomSavedPrefabDropdown);
            if (!useSceneDropdownButton && rootImage != null)
            {
                customSavedPrefabDropdownToggleButton.targetGraphic = rootImage;
                ApplyButtonInteractionStyle(customSavedPrefabDropdownToggleButton, rootImage.color);
                ConfigureDropdownColorTint(customSavedPrefabDropdownToggleButton, savedPrefabsCategoryDropdown);
            }
        }

        Font font = ResolveFont();
        TMP_Text sceneButtonTmpLabel = useSceneDropdownButton ? ResolveSavedPrefabDropdownButtonTmpLabel() : null;
        RectTransform labelRect = sceneButtonTmpLabel != null
            ? sceneButtonTmpLabel.transform as RectTransform
            : FindChildByNameIn<RectTransform>(customSavedPrefabDropdownRoot, "Label");
        bool createdLabel = false;
        if (labelRect == null && !useSceneDropdownButton)
        {
            createdLabel = true;
            labelRect = CreateRect(
                "Label",
                customSavedPrefabDropdownRoot,
                new Vector2(0f, 0f),
                new Vector2(1f, 1f),
                new Vector2(0.5f, 0.5f),
                Vector2.zero,
                Vector2.zero);
            labelRect.offsetMin = new Vector2(10f, 0f);
            labelRect.offsetMax = new Vector2(-24f, 0f);
        }

        if (labelRect != null)
        {
            ConfigureRuntimeDropdownLabel(
                labelRect,
                savedPrefabsCategoryDropdown,
                font,
                createdLabel,
                out customSavedPrefabDropdownLabel,
                out customSavedPrefabDropdownTmpLabel);
        }

        if (!useSceneDropdownButton)
        {
            RectTransform arrowRect = FindChildByNameIn<RectTransform>(customSavedPrefabDropdownRoot, "Arrow");
            bool createdArrow = false;
            if (arrowRect == null)
            {
                createdArrow = true;
                arrowRect = CreateRect(
                    "Arrow",
                    customSavedPrefabDropdownRoot,
                    new Vector2(1f, 0f),
                    new Vector2(1f, 1f),
                    new Vector2(1f, 0.5f),
                    new Vector2(18f, 0f),
                    new Vector2(-6f, 0f));
            }

            ConfigureRuntimeDropdownArrow(arrowRect, savedPrefabsCategoryDropdown, font, createdArrow);
        }

        EnsureDropdownOptionsRoot(
            customSavedPrefabDropdownRoot,
            runtimeDropdownPopupBackgroundColor,
            out customSavedPrefabDropdownOptionsRoot);
        if (customSavedPrefabDropdownOptionsRoot == null)
        {
            return;
        }

        Image optionsBackground = customSavedPrefabDropdownOptionsRoot.GetComponent<Image>();
        Image popupStyleSource = rootImage != null ? rootImage : ResolveSavedPrefabDropdownListStyleSource();
        if (popupStyleSource != null)
        {
            CopyImageStyle(popupStyleSource, optionsBackground, copyColor: true);
        }
        else
        {
            optionsBackground.color = DropdownOptionsPanelImageColor;
        }

        if (!useSceneDropdownButton && templateImage == null)
        {
            optionsBackground.color = DropdownOptionsPanelImageColor;
        }
        customSavedPrefabDropdownOptionsRoot.gameObject.SetActive(false);
        customSavedPrefabDropdownOptionsOriginalParent = customSavedPrefabDropdownOptionsRoot.parent;
        customSavedPrefabDropdownOptionsOriginalSiblingIndex = customSavedPrefabDropdownOptionsRoot.GetSiblingIndex();

        if (savedPrefabsCategoryDropdown != null && !useSceneDropdownButton)
        {
            savedPrefabsCategoryDropdown.gameObject.SetActive(false);
        }
    }

