    private TMP_Text ResolveSavedPrefabDropdownButtonTmpLabel()
    {
        if (savedPrefabsCategoryDropdown == null)
        {
            return customSavedPrefabDropdownTmpLabel;
        }

        if (IsSavedPrefabDropdownButtonTmpLabel(savedPrefabsCategoryDropdown.captionText))
        {
            return savedPrefabsCategoryDropdown.captionText;
        }

        TMP_Text namedLabel = FindSavedPrefabDropdownButtonTmpLabelByName("Text (TMP)");
        if (namedLabel != null)
        {
            return namedLabel;
        }

        namedLabel = FindSavedPrefabDropdownButtonTmpLabelByName("Label");
        if (namedLabel != null)
        {
            return namedLabel;
        }

        TMP_Text[] labels = savedPrefabsCategoryDropdown.GetComponentsInChildren<TMP_Text>(true);
        for (int i = 0; i < labels.Length; i++)
        {
            if (IsSavedPrefabDropdownButtonTmpLabel(labels[i]))
            {
                return labels[i];
            }
        }

        return null;
    }

    private TMP_Text FindSavedPrefabDropdownButtonTmpLabelByName(string objectName)
    {
        if (savedPrefabsCategoryDropdown == null || string.IsNullOrWhiteSpace(objectName))
        {
            return null;
        }

        TMP_Text[] labels = savedPrefabsCategoryDropdown.GetComponentsInChildren<TMP_Text>(true);
        for (int i = 0; i < labels.Length; i++)
        {
            TMP_Text label = labels[i];
            if (label != null
                && string.Equals(label.gameObject.name, objectName, StringComparison.Ordinal)
                && IsSavedPrefabDropdownButtonTmpLabel(label))
            {
                return label;
            }
        }

        return null;
    }

    private bool IsSavedPrefabDropdownButtonTmpLabel(TMP_Text label)
    {
        if (label == null || savedPrefabsCategoryDropdown == null)
        {
            return false;
        }

        Transform labelTransform = label.transform;
        if (!labelTransform.IsChildOf(savedPrefabsCategoryDropdown.transform))
        {
            return false;
        }

        if (savedPrefabsCategoryDropdown.template != null
            && labelTransform.IsChildOf(savedPrefabsCategoryDropdown.template))
        {
            return false;
        }

        if (customSavedPrefabDropdownOptionsRoot != null
            && labelTransform.IsChildOf(customSavedPrefabDropdownOptionsRoot))
        {
            return false;
        }

        return true;
    }

    private void ToggleCustomSavedPrefabDropdown()
    {
        SetCustomSavedPrefabDropdownOpen(!customSavedPrefabDropdownExpanded);
    }

    private void SetCustomSavedPrefabDropdownOpen(bool isOpen)
    {
        customSavedPrefabDropdownExpanded = isOpen && savedPrefabCategoryDropdownOptions.Count > 0;
        if (customSavedPrefabDropdownExpanded)
        {
            SetCustomCategoryDropdownOpen(false);
        }

        if (customSavedPrefabDropdownExpanded && customSavedPrefabDropdownRoot != null)
        {
            if (!UsesSceneSavedPrefabDropdownButton())
            {
                customSavedPrefabDropdownRoot.SetAsLastSibling();
            }

            BringCustomSavedPrefabDropdownPopupToFront();
        }
        else
        {
            RestoreCustomSavedPrefabDropdownPopupParent();
        }

        if (customSavedPrefabDropdownOptionsRoot != null)
        {
            customSavedPrefabDropdownOptionsRoot.gameObject.SetActive(customSavedPrefabDropdownExpanded);
        }

        UpdateShadowStickyButtonStates();
    }

    private void BringCustomSavedPrefabDropdownPopupToFront()
    {
        if (customSavedPrefabDropdownOptionsRoot == null)
        {
            return;
        }

        Canvas canvas = customSavedPrefabDropdownRoot != null
            ? customSavedPrefabDropdownRoot.GetComponentInParent<Canvas>()
            : customSavedPrefabDropdownOptionsRoot.GetComponentInParent<Canvas>();
        RectTransform canvasRect = canvas != null ? canvas.transform as RectTransform : null;
        if (canvasRect == null)
        {
            return;
        }

        customSavedPrefabDropdownOptionsOriginalParent ??= customSavedPrefabDropdownOptionsRoot.parent;
        if (customSavedPrefabDropdownOptionsOriginalSiblingIndex < 0)
        {
            customSavedPrefabDropdownOptionsOriginalSiblingIndex = customSavedPrefabDropdownOptionsRoot.GetSiblingIndex();
        }

        if (customSavedPrefabDropdownOptionsRoot.parent != canvasRect)
        {
            customSavedPrefabDropdownOptionsRoot.SetParent(canvasRect, true);
        }

        customSavedPrefabDropdownOptionsRoot.SetAsLastSibling();
    }

    private void RestoreCustomSavedPrefabDropdownPopupParent()
    {
        if (customSavedPrefabDropdownOptionsRoot == null || customSavedPrefabDropdownOptionsOriginalParent == null)
        {
            return;
        }

        if (customSavedPrefabDropdownOptionsRoot.parent != customSavedPrefabDropdownOptionsOriginalParent)
        {
            customSavedPrefabDropdownOptionsRoot.SetParent(customSavedPrefabDropdownOptionsOriginalParent, true);
        }

        int maxSibling = Mathf.Max(0, customSavedPrefabDropdownOptionsRoot.parent.childCount - 1);
        int siblingIndex = customSavedPrefabDropdownOptionsOriginalSiblingIndex >= 0
            ? Mathf.Clamp(customSavedPrefabDropdownOptionsOriginalSiblingIndex, 0, maxSibling)
            : maxSibling;
        customSavedPrefabDropdownOptionsRoot.SetSiblingIndex(siblingIndex);
    }

    private void RebuildCustomSavedPrefabDropdownOptions()
    {
        customSavedPrefabDropdownOptionButtons.Clear();
        if (customSavedPrefabDropdownOptionsRoot == null)
        {
            return;
        }

        bool keepOpen = customSavedPrefabDropdownExpanded;
        List<Button> existingOptionButtons = CollectDirectDropdownOptionButtons(customSavedPrefabDropdownOptionsRoot);

        Font font = ResolveFont();
        TMP_Text optionTmpTextStyle = ResolveDropdownOptionTmpTextStyle(savedPrefabsCategoryDropdown);
        Image optionStyleSource = ResolveDropdownOptionImageStyleSource(
            existingOptionButtons,
            ResolveSavedPrefabDropdownPopupStyleSource());
        for (int i = 0; i < savedPrefabCategoryDropdownOptions.Count; i++)
        {
            int capturedIndex = i;
            string optionLabel = BuildSavedPrefabDropdownOptionText(i);
            Button optionButton = i < existingOptionButtons.Count
                ? existingOptionButtons[i]
                : CreateCategoryDropdownOptionButton(
                    customSavedPrefabDropdownOptionsRoot,
                    font,
                    optionLabel,
                    optionStyleSource,
                    optionTmpTextStyle,
                    useStyleSourceColor: true);
            if (optionButton == null)
            {
                continue;
            }

            optionButton.gameObject.SetActive(true);
            SetDropdownOptionButtonText(optionButton, optionLabel);
            EnsureShadowPressTracking(optionButton);
            optionButton.onClick.RemoveAllListeners();
            optionButton.onClick.AddListener(() => HandleCustomSavedPrefabOptionSelected(capturedIndex));
            customSavedPrefabDropdownOptionButtons.Add(optionButton);
        }

        for (int i = savedPrefabCategoryDropdownOptions.Count; i < existingOptionButtons.Count; i++)
        {
            HideUnusedDropdownOptionButton(existingOptionButtons[i]);
        }

        selectedSavedPrefabCategoryDropdownIndex = Mathf.Clamp(
            selectedSavedPrefabCategoryDropdownIndex,
            0,
            Mathf.Max(0, savedPrefabCategoryDropdownOptions.Count - 1));
        SetCustomSavedPrefabDropdownOpen(keepOpen);
        UpdateSavedPrefabCategoryDropdownLabel();
    }

    private void RefreshCustomSavedPrefabDropdownOptionTexts()
    {
        for (int i = 0; i < customSavedPrefabDropdownOptionButtons.Count && i < savedPrefabCategoryDropdownOptions.Count; i++)
        {
            SetDropdownOptionButtonText(
                customSavedPrefabDropdownOptionButtons[i],
                BuildSavedPrefabDropdownOptionText(i));
        }
    }

    private void HandleCustomSavedPrefabOptionSelected(int optionIndex)
    {
        HandleSavedPrefabCategoryDropdownChanged(optionIndex);
        SetCustomSavedPrefabDropdownOpen(false);
        if (EventSystem.current != null
            && customSavedPrefabDropdownToggleButton != null
            && customSavedPrefabDropdownToggleButton.gameObject.activeInHierarchy)
        {
            EventSystem.current.SetSelectedGameObject(customSavedPrefabDropdownToggleButton.gameObject);
        }
    }

