    private Image ResolveSavedPrefabDropdownOptionStyleSource()
    {
        if (savedPrefabsCategoryDropdown != null && savedPrefabsCategoryDropdown.template != null)
        {
            Toggle templateToggle = savedPrefabsCategoryDropdown.template.GetComponentInChildren<Toggle>(true);
            if (templateToggle != null)
            {
                Image optionImage = templateToggle.targetGraphic as Image;
                optionImage ??= templateToggle.GetComponent<Image>();
                if (optionImage != null)
                {
                    return optionImage;
                }
            }

            Image[] images = savedPrefabsCategoryDropdown.template.GetComponentsInChildren<Image>(true);
            for (int i = 0; i < images.Length; i++)
            {
                if (images[i] != null)
                {
                    return images[i];
                }
            }
        }

        return savedPrefabsCategoryDropdown != null
            ? savedPrefabsCategoryDropdown.GetComponent<Image>()
            : ResolveCategoryDropdownOptionStyleSource();
    }

