    private static void CopyImageStyle(Image source, Image target, bool copyColor)
    {
        if (source == null || target == null)
        {
            return;
        }

        target.sprite = source.sprite;
        target.overrideSprite = source.overrideSprite;
        target.type = source.type;
        target.fillCenter = source.fillCenter;
        target.fillMethod = source.fillMethod;
        target.fillAmount = source.fillAmount;
        target.fillClockwise = source.fillClockwise;
        target.fillOrigin = source.fillOrigin;
        target.preserveAspect = source.preserveAspect;
        target.pixelsPerUnitMultiplier = source.pixelsPerUnitMultiplier;
        target.material = source.material;
        target.maskable = source.maskable;
        target.raycastTarget = source.raycastTarget;
        if (copyColor)
        {
            target.color = source.color;
        }
    }

    private static void CopyRectTransformValues(RectTransform source, RectTransform target)
    {
        if (source == null || target == null)
        {
            return;
        }

        target.anchorMin = source.anchorMin;
        target.anchorMax = source.anchorMax;
        target.pivot = source.pivot;
        target.sizeDelta = source.sizeDelta;
        target.anchoredPosition = source.anchoredPosition;
        target.localScale = source.localScale;
        target.localRotation = source.localRotation;
    }

    private static void DestroyGameObjectSafely(GameObject target)
    {
        if (target == null)
        {
            return;
        }

#if UNITY_EDITOR
        ClearEditorSelectionIfContains(target.transform);
#endif

        if (Application.isPlaying)
        {
            UnityEngine.Object.Destroy(target);
        }
        else
        {
            UnityEngine.Object.DestroyImmediate(target);
        }
    }

#if UNITY_EDITOR
    private static void ClearEditorSelectionIfContains(Transform target)
    {
        if (target == null)
        {
            return;
        }

        UnityEngine.Object[] selectedObjects = Selection.objects;
        if (selectedObjects == null || selectedObjects.Length == 0)
        {
            return;
        }

        for (int i = 0; i < selectedObjects.Length; i++)
        {
            UnityEngine.Object selectedObject = selectedObjects[i];
            Transform selectedTransform = selectedObject switch
            {
                GameObject selectedGameObject => selectedGameObject.transform,
                Component selectedComponent => selectedComponent.transform,
                _ => null
            };

            if (selectedTransform == null)
            {
                continue;
            }

            if (selectedTransform == target || selectedTransform.IsChildOf(target))
            {
                Selection.activeObject = null;
                Selection.objects = Array.Empty<UnityEngine.Object>();
                return;
            }
        }
    }
#endif

