    private void BindGlobalEvents()
    {
        if (globalEventsBound)
        {
            return;
        }

        setPrevButton?.onClick.AddListener(HandlePreviousSet);
        setNextButton?.onClick.AddListener(HandleNextSet);
        resetDefaultButton?.onClick.AddListener(HandleResetDefault);
        randomizeButton?.onClick.AddListener(HandleRandomize);
        backButton?.onClick.AddListener(HandleBackButton);
        saveButton?.onClick.AddListener(HandleSavePrefab);
        partsPanelToggleButton?.onClick.AddListener(TogglePartsPanel);
        savePrefabsPanelToggleButton?.onClick.AddListener(ToggleSavePrefabsPanel);
        playSceneButton?.onClick.AddListener(HandlePlaySceneButton);
        randomColorButton?.onClick.AddListener(HandleRandomColorButton);
        colorChartButton?.onClick.AddListener(HandleColorChartButton);
        autoRotationButton?.onClick.AddListener(HandleAutoRotationButton);
        savedPrefabsLeftArrowButton?.onClick.AddListener(HandleSavedPrefabsLeftArrow);
        savedPrefabsRightArrowButton?.onClick.AddListener(HandleSavedPrefabsRightArrow);
        if (savedPrefabsCategoryDropdown != null && !UsesSceneSavedPrefabDropdownButton())
        {
            savedPrefabsCategoryDropdown.onValueChanged.AddListener(HandleSavedPrefabCategoryDropdownChanged);
        }

        categoryInfoBuyButton?.onClick.AddListener(HandleCategoryInfoBuyButtonClicked);
        if (customCategoryDropdownToggleButton != null)
        {
            customCategoryDropdownToggleButton.onClick.RemoveListener(ToggleCustomCategoryDropdown);
            customCategoryDropdownToggleButton.onClick.AddListener(ToggleCustomCategoryDropdown);
        }
        else if (categoryDropdown != null && !UsesSceneCategoryDropdownButton())
        {
            categoryDropdown.onValueChanged.AddListener(HandleSceneCategoryDropdownChanged);
        }
        if (customSavedPrefabDropdownToggleButton != null)
        {
            customSavedPrefabDropdownToggleButton.onClick.RemoveListener(ToggleCustomSavedPrefabDropdown);
            customSavedPrefabDropdownToggleButton.onClick.AddListener(ToggleCustomSavedPrefabDropdown);
        }
        globalEventsBound = true;
    }

    private void RebindGlobalEvents()
    {
        UnbindGlobalEvents();
        BindGlobalEvents();
    }

    private void UnbindGlobalEvents()
    {
        if (!globalEventsBound)
        {
            return;
        }

        setPrevButton?.onClick.RemoveListener(HandlePreviousSet);
        setNextButton?.onClick.RemoveListener(HandleNextSet);
        resetDefaultButton?.onClick.RemoveListener(HandleResetDefault);
        randomizeButton?.onClick.RemoveListener(HandleRandomize);
        backButton?.onClick.RemoveListener(HandleBackButton);
        saveButton?.onClick.RemoveListener(HandleSavePrefab);
        partsPanelToggleButton?.onClick.RemoveListener(TogglePartsPanel);
        savePrefabsPanelToggleButton?.onClick.RemoveListener(ToggleSavePrefabsPanel);
        playSceneButton?.onClick.RemoveListener(HandlePlaySceneButton);
        randomColorButton?.onClick.RemoveListener(HandleRandomColorButton);
        colorChartButton?.onClick.RemoveListener(HandleColorChartButton);
        autoRotationButton?.onClick.RemoveListener(HandleAutoRotationButton);
        savedPrefabsLeftArrowButton?.onClick.RemoveListener(HandleSavedPrefabsLeftArrow);
        savedPrefabsRightArrowButton?.onClick.RemoveListener(HandleSavedPrefabsRightArrow);
        if (savedPrefabsCategoryDropdown != null)
        {
            savedPrefabsCategoryDropdown.onValueChanged.RemoveListener(HandleSavedPrefabCategoryDropdownChanged);
        }

        categoryInfoBuyButton?.onClick.RemoveListener(HandleCategoryInfoBuyButtonClicked);
        if (customCategoryDropdownToggleButton != null)
        {
            customCategoryDropdownToggleButton.onClick.RemoveListener(ToggleCustomCategoryDropdown);
        }

        if (customSavedPrefabDropdownToggleButton != null)
        {
            customSavedPrefabDropdownToggleButton.onClick.RemoveListener(ToggleCustomSavedPrefabDropdown);
        }

        if (categoryDropdown != null)
        {
            categoryDropdown.onValueChanged.RemoveListener(HandleSceneCategoryDropdownChanged);
        }
        globalEventsBound = false;
    }

