    private void HandleResetDefault()
    {
        if (customizer == null)
        {
            return;
        }

        RecordUndoSnapshotIfNeeded();
        ResetCurrentCharacterToDefault(savePersistentState: true);
    }

    private void ResetCurrentCharacterToDefault(bool savePersistentState)
    {
        if (customizer == null)
        {
            return;
        }

        hairRendererUnlockedByUserSelection = false;
        customizer.ResetToDefaultCharacter();
        selectedPropRigName = string.Empty;
        ClearAllPropsFromCharacter();
        currentSetIndex = -1;
        RefreshAfterCustomizationApplication(null, refreshWorldPartColliders: true, savePersistentState: savePersistentState);
    }

    private void HandleRandomize()
    {
        if (customizer == null)
        {
            return;
        }

        RecordUndoSnapshotIfNeeded();
        int variantCount = customizer.GetVariantCount();
        if (variantCount <= 0)
        {
            hairRendererUnlockedByUserSelection = false;
            customizer.ResetToDefaultCharacter();
            RefreshAfterCustomizationApplication(null, refreshWorldPartColliders: true, savePersistentState: true);
            return;
        }

        IReadOnlyList<MinimoCharacterCustomizer.PartSlot> slots = MinimoCharacterCustomizer.Slots;
        Dictionary<MinimoCharacterCustomizer.PartSlot, int> randomized = new Dictionary<MinimoCharacterCustomizer.PartSlot, int>();
        Dictionary<MinimoCharacterCustomizer.PartSlot, List<int>> availableBySlot = new Dictionary<MinimoCharacterCustomizer.PartSlot, List<int>>();
        for (int i = 0; i < slots.Count; i++)
        {
            MinimoCharacterCustomizer.PartSlot slot = slots[i];
            List<int> availableVariantIndices = GetAvailableVariantIndicesForSlot(slot, variantCount);
            availableBySlot[slot] = availableVariantIndices;
            randomized[slot] = PickRandomVariantFromBag(
                $"global-slot:{slot}",
                availableVariantIndices,
                customizer.GetPartVariant(slot));
        }

        SetCategoryMatchedGroupRandom(
            randomized,
            availableBySlot,
            UpperBodyGroupSlots,
            MinimoCharacterCustomizer.PartSlot.Torso,
            "global-upper");
        SetCategoryMatchedGroupRandom(
            randomized,
            availableBySlot,
            LowerBodyGroupSlots,
            MinimoCharacterCustomizer.PartSlot.Hips,
            "global-lower");

        for (int i = 0; i < slots.Count; i++)
        {
            MinimoCharacterCustomizer.PartSlot slot = slots[i];
            if (randomized.TryGetValue(slot, out int variantIndex))
            {
                customizer.SetPartVariant(slot, variantIndex);
            }
        }

        customizer.ApplyCurrentSelection();
        int randomizedHairVariant = customizer.GetPartVariant(MinimoCharacterCustomizer.PartSlot.Hair);
        if (randomizedHairVariant >= 0)
        {
            hairRendererUnlockedByUserSelection = true;
            SetHairRendererEnabled(true);
        }
        else
        {
            hairRendererUnlockedByUserSelection = false;
            SetHairRendererEnabled(false);
        }

        SynchronizeMirroredPairColorsForAllSlots();
        customizer.ApplyCurrentSelection();
        ApplyRandomSingleProp();
        currentSetIndex = -1;
        RefreshAfterCustomizationApplication(null, refreshWorldPartColliders: true, savePersistentState: true);
    }

    private List<int> GetAvailableVariantIndicesForSlot(
        MinimoCharacterCustomizer.PartSlot slot,
        int variantCount)
    {
        List<int> indices = new List<int>();
        if (customizer == null || variantCount <= 0)
        {
            return indices;
        }

        for (int variantIndex = 0; variantIndex < variantCount; variantIndex++)
        {
            if (DoesVariantExistForSlot(variantIndex, slot))
            {
                indices.Add(variantIndex);
            }
        }

        return indices;
    }

    private static int PickRandomVariantOrDefault(List<int> availableVariantIndices, int avoidVariantIndex = -1)
    {
        if (availableVariantIndices == null || availableVariantIndices.Count == 0)
        {
            return -1;
        }

        int avoidListIndex = availableVariantIndices.IndexOf(avoidVariantIndex);
        if (avoidListIndex >= 0 && availableVariantIndices.Count > 1)
        {
            int randomIndex = UnityEngine.Random.Range(0, availableVariantIndices.Count - 1);
            if (randomIndex >= avoidListIndex)
            {
                randomIndex++;
            }

            return availableVariantIndices[randomIndex];
        }

        return availableVariantIndices[UnityEngine.Random.Range(0, availableVariantIndices.Count)];
    }

    private int PickRandomVariantFromBag(string bagKey, List<int> availableVariantIndices, int avoidVariantIndex = -1)
    {
        if (availableVariantIndices == null || availableVariantIndices.Count == 0)
        {
            return -1;
        }

        if (string.IsNullOrWhiteSpace(bagKey))
        {
            return PickRandomVariantOrDefault(availableVariantIndices, avoidVariantIndex);
        }

        if (!randomVariantBagsByKey.TryGetValue(bagKey, out List<int> bag))
        {
            bag = new List<int>();
            randomVariantBagsByKey[bagKey] = bag;
        }

        bag.RemoveAll(variantIndex => !availableVariantIndices.Contains(variantIndex));
        if (bag.Count == 0)
        {
            for (int i = 0; i < availableVariantIndices.Count; i++)
            {
                int variantIndex = availableVariantIndices[i];
                if (availableVariantIndices.Count > 1 && variantIndex == avoidVariantIndex)
                {
                    continue;
                }

                bag.Add(variantIndex);
            }

            if (bag.Count == 0)
            {
                bag.AddRange(availableVariantIndices);
            }
        }

        int randomIndex = UnityEngine.Random.Range(0, bag.Count);
        int selectedVariant = bag[randomIndex];
        bag.RemoveAt(randomIndex);
        return selectedVariant;
    }

    private string PickRandomStringFromBag(string bagKey, List<string> candidates, string avoidValue = null)
    {
        if (candidates == null || candidates.Count == 0)
        {
            return string.Empty;
        }

        if (string.IsNullOrWhiteSpace(bagKey))
        {
            return candidates[UnityEngine.Random.Range(0, candidates.Count)];
        }

        if (!randomStringBagsByKey.TryGetValue(bagKey, out List<string> bag))
        {
            bag = new List<string>();
            randomStringBagsByKey[bagKey] = bag;
        }

        bag.RemoveAll(value => !StringListContains(candidates, value));
        if (bag.Count == 0)
        {
            for (int i = 0; i < candidates.Count; i++)
            {
                string candidate = candidates[i];
                if (candidates.Count > 1
                    && !string.IsNullOrWhiteSpace(avoidValue)
                    && string.Equals(candidate, avoidValue, StringComparison.OrdinalIgnoreCase))
                {
                    continue;
                }

                bag.Add(candidate);
            }

            if (bag.Count == 0)
            {
                bag.AddRange(candidates);
            }
        }

        int randomIndex = UnityEngine.Random.Range(0, bag.Count);
        string selectedValue = bag[randomIndex];
        bag.RemoveAt(randomIndex);
        return selectedValue;
    }

    private static bool StringListContains(List<string> values, string target)
    {
        if (values == null)
        {
            return false;
        }

        for (int i = 0; i < values.Count; i++)
        {
            if (string.Equals(values[i], target, StringComparison.OrdinalIgnoreCase))
            {
                return true;
            }
        }

        return false;
    }

    private int PickRandomVariantByCategory(
        List<int> availableVariantIndices,
        MinimoCharacterCustomizer.PartSlot[] categorySlots,
        int avoidVariantIndex = -1)
    {
        if (availableVariantIndices == null || availableVariantIndices.Count == 0)
        {
            return -1;
        }

        List<int> candidates = availableVariantIndices;
        if (avoidVariantIndex >= 0 && availableVariantIndices.Count > 1 && availableVariantIndices.Contains(avoidVariantIndex))
        {
            candidates = new List<int>(availableVariantIndices.Count - 1);
            for (int i = 0; i < availableVariantIndices.Count; i++)
            {
                int variantIndex = availableVariantIndices[i];
                if (variantIndex != avoidVariantIndex)
                {
                    candidates.Add(variantIndex);
                }
            }
        }

        Dictionary<string, List<int>> byCategory = new Dictionary<string, List<int>>(StringComparer.OrdinalIgnoreCase);
        for (int i = 0; i < candidates.Count; i++)
        {
            int variantIndex = candidates[i];
            string categoryName = NormalizeCategoryName(ResolveVariantCategoryNameForSlots(variantIndex, categorySlots));
            if (string.IsNullOrWhiteSpace(categoryName) || IsNonSelectableCategoryName(categoryName))
            {
                categoryName = CategoryDefaultOptionLabel;
            }

            if (!byCategory.TryGetValue(categoryName, out List<int> categoryVariants))
            {
                categoryVariants = new List<int>();
                byCategory[categoryName] = categoryVariants;
            }

            categoryVariants.Add(variantIndex);
        }

        if (byCategory.Count == 0)
        {
            return PickRandomVariantOrDefault(availableVariantIndices, avoidVariantIndex);
        }

        List<string> categories = new List<string>(byCategory.Keys);
        string selectedCategory = categories[UnityEngine.Random.Range(0, categories.Count)];
        List<int> selectedVariants = byCategory[selectedCategory];
        return selectedVariants[UnityEngine.Random.Range(0, selectedVariants.Count)];
    }

    private void SynchronizeMirroredPairColorsForAllSlots()
    {
        SynchronizeMirroredPairColor(
            MinimoCharacterCustomizer.PartSlot.ShoulderLeft,
            MinimoCharacterCustomizer.PartSlot.ShoulderRight);
        SynchronizeMirroredPairColor(
            MinimoCharacterCustomizer.PartSlot.ArmLeft,
            MinimoCharacterCustomizer.PartSlot.ArmRight);
        SynchronizeMirroredPairColor(
            MinimoCharacterCustomizer.PartSlot.HandLeft,
            MinimoCharacterCustomizer.PartSlot.HandRight);
        SynchronizeMirroredPairColor(
            MinimoCharacterCustomizer.PartSlot.LegUpperLeft,
            MinimoCharacterCustomizer.PartSlot.LegUpperRight);
        SynchronizeMirroredPairColor(
            MinimoCharacterCustomizer.PartSlot.BootsLeft,
            MinimoCharacterCustomizer.PartSlot.BootsRight);
    }

    private void SynchronizeMirroredPairColorsForRegionSlots(MinimoCharacterCustomizer.PartSlot[] slots)
    {
        if (slots == null || slots.Length == 0)
        {
            return;
        }

        if (ContainsLeftAndRightSlotPair(
                slots,
                MinimoCharacterCustomizer.PartSlot.ShoulderLeft,
                MinimoCharacterCustomizer.PartSlot.ShoulderRight))
        {
            SynchronizeMirroredPairColor(
                MinimoCharacterCustomizer.PartSlot.ShoulderLeft,
                MinimoCharacterCustomizer.PartSlot.ShoulderRight);
        }

        if (ContainsLeftAndRightSlotPair(
                slots,
                MinimoCharacterCustomizer.PartSlot.ArmLeft,
                MinimoCharacterCustomizer.PartSlot.ArmRight))
        {
            SynchronizeMirroredPairColor(
                MinimoCharacterCustomizer.PartSlot.ArmLeft,
                MinimoCharacterCustomizer.PartSlot.ArmRight);
        }

        if (ContainsLeftAndRightSlotPair(
                slots,
                MinimoCharacterCustomizer.PartSlot.HandLeft,
                MinimoCharacterCustomizer.PartSlot.HandRight))
        {
            SynchronizeMirroredPairColor(
                MinimoCharacterCustomizer.PartSlot.HandLeft,
                MinimoCharacterCustomizer.PartSlot.HandRight);
        }

        if (ContainsLeftAndRightSlotPair(
                slots,
                MinimoCharacterCustomizer.PartSlot.LegUpperLeft,
                MinimoCharacterCustomizer.PartSlot.LegUpperRight))
        {
            SynchronizeMirroredPairColor(
                MinimoCharacterCustomizer.PartSlot.LegUpperLeft,
                MinimoCharacterCustomizer.PartSlot.LegUpperRight);
        }

        if (ContainsLeftAndRightSlotPair(
                slots,
                MinimoCharacterCustomizer.PartSlot.BootsLeft,
                MinimoCharacterCustomizer.PartSlot.BootsRight))
        {
            SynchronizeMirroredPairColor(
                MinimoCharacterCustomizer.PartSlot.BootsLeft,
                MinimoCharacterCustomizer.PartSlot.BootsRight);
        }
    }

    private void SynchronizeMirroredPairColor(
        MinimoCharacterCustomizer.PartSlot leftSlot,
        MinimoCharacterCustomizer.PartSlot rightSlot)
    {
        if (customizer == null)
        {
            return;
        }

        int rightVariant = customizer.GetPartVariant(rightSlot);
        int leftVariant = customizer.GetPartVariant(leftSlot);

        MinimoCharacterCustomizer.PartSlot sourceSlot = rightVariant >= 0 || leftVariant < 0
            ? rightSlot
            : leftSlot;
        MinimoCharacterCustomizer.PartSlot targetSlot = sourceSlot == rightSlot
            ? leftSlot
            : rightSlot;

        CopyPartColors(sourceSlot, targetSlot);
    }

    private void CopyPartColors(
        MinimoCharacterCustomizer.PartSlot sourceSlot,
        MinimoCharacterCustomizer.PartSlot targetSlot)
    {
        if (customizer == null)
        {
            return;
        }

        List<(MinimoCharacterCustomizer.PartSlot slot, int materialIndex, Color color)> colorAssignments =
            new List<(MinimoCharacterCustomizer.PartSlot slot, int materialIndex, Color color)>();
        if (customizer.TryGetPartColor(sourceSlot, -1, out Color fallbackColor))
        {
            colorAssignments.Add((targetSlot, -1, fallbackColor));
        }

        List<int> sourceMaterialIndices = GetEditableColorMaterialIndicesForSlot(sourceSlot);
        for (int channelIndex = 0; channelIndex < sourceMaterialIndices.Count; channelIndex++)
        {
            int sourceMaterialIndex = sourceMaterialIndices[channelIndex];
            if (!customizer.TryGetPartColor(sourceSlot, sourceMaterialIndex, out Color sourceColor))
            {
                continue;
            }

            int targetMaterialIndex = ResolveColorMaterialIndexForSlot(targetSlot, channelIndex);
            if (targetMaterialIndex >= 0)
            {
                colorAssignments.Add((targetSlot, targetMaterialIndex, sourceColor));
            }
        }

        customizer.SetPartColors(colorAssignments);
    }

    public void TogglePartsPanel()
    {
        if (showPanelsAsTabs && partsPanelRoot != null && savePrefabsPanelRoot != null)
        {
            if (IsRequestedPanelModeAlreadyApplied(true))
            {
                UpdateShadowStickyButtonStates();
                return;
            }

            SetCustomizationPanelVisible(true);
            gamepadUiSelectionRefreshPending = true;
            return;
        }

        if (partsPanelRoot == null)
        {
            return;
        }

        bool nextState = !partsPanelRoot.gameObject.activeSelf;
        partsPanelRoot.gameObject.SetActive(nextState);
        if (materialChannelStripRoot != null)
        {
            materialChannelStripRoot.gameObject.SetActive(nextState && colorChannelButtons.Count > 0);
        }

        ConfigureSavedPrefabsLayout();
        UpdateSavedPanelPresentation();
        gamepadUiSelectionRefreshPending = true;
    }

    public void ToggleSavePrefabsPanel()
    {
        if (showPanelsAsTabs && partsPanelRoot != null && savePrefabsPanelRoot != null)
        {
            if (IsRequestedPanelModeAlreadyApplied(false))
            {
                UpdateShadowStickyButtonStates();
                return;
            }

            SetCustomizationPanelVisible(false);
            gamepadUiSelectionRefreshPending = true;
            return;
        }

        if (savePrefabsPanelRoot == null)
        {
            return;
        }

        bool nextState = !savePrefabsPanelRoot.gameObject.activeSelf;
        savePrefabsPanelRoot.gameObject.SetActive(nextState);
        if (materialChannelStripRoot != null && nextState)
        {
            materialChannelStripRoot.gameObject.SetActive(false);
        }
        if (nextState)
        {
            EnsureSavedPrefabButtonsInitialized();
        }

        ConfigureSavedPrefabsLayout();
        UpdateSavedPanelPresentation();
        gamepadUiSelectionRefreshPending = true;
    }

    private void SetCustomizationPanelVisible(bool showCustomizePanel)
    {
        if (partsPanelRoot == null && savePrefabsPanelRoot == null)
        {
            return;
        }

        if (IsRequestedPanelModeAlreadyApplied(showCustomizePanel))
        {
            UpdateShadowStickyButtonStates();
            return;
        }

        isCustomizePanelMode = showCustomizePanel;

        if (partsPanelRoot != null)
        {
            bool keepPartsRootVisible = showPanelsAsTabs
                                        && savedPanelShowsReadyCharactersOnly
                                        && !UsesPagePanelRoots();
            partsPanelRoot.gameObject.SetActive(keepPartsRootVisible || showCustomizePanel);
        }

        if (savePrefabsPanelRoot != null)
        {
            savePrefabsPanelRoot.gameObject.SetActive(!showCustomizePanel);
        }

        if (materialChannelStripRoot != null)
        {
            materialChannelStripRoot.gameObject.SetActive(showCustomizePanel && colorChannelButtons.Count > 0);
        }

        if (!showCustomizePanel)
        {
            EnsureSavedPrefabButtonsInitialized();
            SetCustomColorPickerVisible(false);
        }

        ConfigureSavedPrefabsLayout();
        UpdateSavedPanelPresentation();

        UpdatePanelModeButtonVisuals(showCustomizePanel);
        gamepadUiSelectionRefreshPending = true;
    }

    private bool IsRequestedPanelModeAlreadyApplied(bool showCustomizePanel)
    {
        if (!showPanelsAsTabs || partsPanelRoot == null || savePrefabsPanelRoot == null)
        {
            return false;
        }

        bool expectedPartsActive = (showPanelsAsTabs && savedPanelShowsReadyCharactersOnly && !UsesPagePanelRoots())
                                   || showCustomizePanel;
        bool expectedSavedActive = !showCustomizePanel;
        bool partsAlready = partsPanelRoot.gameObject.activeSelf == expectedPartsActive;
        bool savedAlready = savePrefabsPanelRoot.gameObject.activeSelf == expectedSavedActive;
        bool modeAlready = isCustomizePanelMode == showCustomizePanel;

        if (!partsAlready || !savedAlready || !modeAlready)
        {
            return false;
        }

        if (materialChannelStripRoot == null)
        {
            return true;
        }

        bool expectedStripActive = showCustomizePanel && colorChannelButtons.Count > 0;
        return materialChannelStripRoot.gameObject.activeSelf == expectedStripActive;
    }

    private void EnsurePanelModeState()
    {
        if (!showPanelsAsTabs || partsPanelRoot == null || savePrefabsPanelRoot == null)
        {
            return;
        }

        if (savedPanelShowsReadyCharactersOnly && !UsesPagePanelRoots())
        {
            bool currentPartsActive = partsPanelRoot.gameObject.activeSelf;
            bool currentSavedActive = savePrefabsPanelRoot.gameObject.activeSelf;
            if (currentSavedActive)
            {
                isCustomizePanelMode = false;
            }
            else if (!currentPartsActive)
            {
                isCustomizePanelMode = true;
            }

            partsPanelRoot.gameObject.SetActive(true);
            savePrefabsPanelRoot.gameObject.SetActive(!isCustomizePanelMode);

            if (materialChannelStripRoot != null)
            {
                materialChannelStripRoot.gameObject.SetActive(isCustomizePanelMode && colorChannelButtons.Count > 0);
            }

            ConfigureSavedPrefabsLayout();
            UpdateSavedPanelPresentation();
            UpdatePanelModeButtonVisuals(isCustomizePanelMode);
            return;
        }

        bool partsActive = partsPanelRoot.gameObject.activeSelf;
        bool savedActive = savePrefabsPanelRoot.gameObject.activeSelf;
        if (!partsActive && !savedActive)
        {
            partsActive = true;
        }

        if (partsActive == savedActive)
        {
            savedActive = !partsActive;
            savePrefabsPanelRoot.gameObject.SetActive(savedActive);
            partsPanelRoot.gameObject.SetActive(partsActive);
        }

        if (materialChannelStripRoot != null)
        {
            materialChannelStripRoot.gameObject.SetActive(partsActive && colorChannelButtons.Count > 0);
        }

        ConfigureSavedPrefabsLayout();
        UpdateSavedPanelPresentation();
        UpdatePanelModeButtonVisuals(partsActive);
    }

    private bool UsesPagePanelRoots()
    {
        return IsPagePanelRoot(partsPanelRoot) || IsPagePanelRoot(savePrefabsPanelRoot);
    }

    private static bool IsPagePanelRoot(RectTransform root)
    {
        if (root == null)
        {
            return false;
        }

        string rootName = root.gameObject.name;
        return string.Equals(rootName, "CustomizePagePanel", StringComparison.OrdinalIgnoreCase)
               || string.Equals(rootName, "SavePrefabsPagePanel", StringComparison.OrdinalIgnoreCase)
               || string.Equals(rootName, "SavedPrefabsPagePanel", StringComparison.OrdinalIgnoreCase);
    }

