    private static void SetButtonTint(Button button, Color color)
    {
        if (button == null)
        {
            return;
        }

        Image image = button.targetGraphic as Image;
        if (image == null)
        {
            image = button.GetComponent<Image>();
            if (image == null)
            {
                return;
            }
        }

        image.color = color;
        ApplyButtonInteractionStyle(button, color);
    }

    private static void SetButtonLabel(Button button, string value)
    {
        if (button == null || string.IsNullOrWhiteSpace(value))
        {
            return;
        }

        TMP_Text tmp = button.GetComponentInChildren<TMP_Text>(true);
        if (tmp != null)
        {
            tmp.text = value;
            return;
        }

        Text txt = button.GetComponentInChildren<Text>(true);
        if (txt != null)
        {
            txt.text = value;
        }
    }

    private void HandleSavePrefab()
    {
#if UNITY_EDITOR
        if (TryShowSaveModePopupIfNeeded())
