        }

        SaveCurrentCharacterAsPrefab();
#else
        helperOverrideMessage = "Prefab saving is only supported in Editor mode.";
        RefreshFromCustomizer();
#endif
    }

    private bool TryShowSaveModePopupIfNeeded()
    {
#if !UNITY_EDITOR
        return false;
#else
        if (customizer == null
            || string.IsNullOrWhiteSpace(loadedSavedPrefabPath)
            || !CanDeleteSavedPrefab(loadedSavedPrefabPath))
        {
            return false;
        }

        string currentSignature = BuildCurrentCustomizerStateSignature();
        if (string.IsNullOrWhiteSpace(currentSignature))
        {
            return false;
        }

        if (string.Equals(currentSignature, loadedSavedPrefabStateSignature, StringComparison.Ordinal))
        {
            return false;
        }

        return ShowSaveModePopup(loadedSavedPrefabPath);
#endif
    }

    private bool IsLoadedSavedPrefabCurrentlySelected()
    {
        if (selectedSavedPrefabIndex < 0 || selectedSavedPrefabIndex >= savedPrefabButtons.Count)
        {
            return false;
        }

        SavedPrefabButtonEntry entry = savedPrefabButtons[selectedSavedPrefabIndex];
        return entry != null
               && !string.IsNullOrWhiteSpace(entry.assetPath)
               && string.Equals(entry.assetPath, loadedSavedPrefabPath, StringComparison.OrdinalIgnoreCase);
    }

