    private static Button FindFirstButtonByNamesIn(Transform root, params string[] names)
    {
        if (root == null || names == null || names.Length == 0)
        {
            return null;
        }

        for (int i = 0; i < names.Length; i++)
        {
            string name = names[i];
            if (string.IsNullOrWhiteSpace(name))
            {
                continue;
            }

            Button match = FindChildByNameIn<Button>(root, name);
            if (match != null)
            {
                return match;
            }
        }

        return null;
    }

    private void ApplySetStep(int step)
    {
        if (customizer == null)
        {
            return;
        }

        if (!categoryDropdownSelectsRegions)
        {
            List<int> filteredVariantIndices = GetFilteredVariantIndicesForCurrentCategory();
            if (filteredVariantIndices.Count == 0)
            {
                return;
            }

            RecordUndoSnapshotIfNeeded();
            int currentFilteredIndex = filteredVariantIndices.IndexOf(currentSetIndex);
            if (currentFilteredIndex < 0)
            {
                currentFilteredIndex = step >= 0 ? 0 : filteredVariantIndices.Count - 1;
            }

            int nextFilteredIndex = NextWrappedIndex(currentFilteredIndex, step, filteredVariantIndices.Count);
            currentSetIndex = filteredVariantIndices[nextFilteredIndex];
            customizer.SetAllPartsToVariant(currentSetIndex);
            customizer.ApplyCurrentSelection();
            RefreshAfterCustomizationApplication(null, refreshWorldPartColliders: true, savePersistentState: true);
            return;
        }

        int count = customizer.GetVariantCount();
        if (count <= 0)
        {
            return;
        }

        RecordUndoSnapshotIfNeeded();
        if (currentSetIndex < 0)
        {
            currentSetIndex = 0;
        }

        currentSetIndex = NextWrappedIndex(currentSetIndex, step, count);
        customizer.SetAllPartsToVariant(currentSetIndex);
        customizer.ApplyCurrentSelection();
        RefreshAfterCustomizationApplication(null, refreshWorldPartColliders: true, savePersistentState: true);
    }

    private void BuildRows(bool forceRebuild = false)
    {
        if (UsesBodySelectionUI())
        {
            return;
        }

        if (regionListRoot == null)
        {
            return;
        }

        IReadOnlyList<MinimoCharacterCustomizer.PartSlot> slots = MinimoCharacterCustomizer.Slots;
        if (!forceRebuild && rows.Count == slots.Count)
        {
            return;
        }

        ClearRows();
        Font font = ResolveFont();

        for (int i = 0; i < slots.Count; i++)
        {
            rows.Add(CreateRow(slots[i], i, font));
        }
    }

    private void ClearRows()
    {
        UnbindRowEvents();
        rows.Clear();

        if (regionListRoot == null)
        {
            return;
        }

        for (int i = regionListRoot.childCount - 1; i >= 0; i--)
        {
            Transform child = regionListRoot.GetChild(i);
            DestroyGameObjectSafely(child.gameObject);
        }
    }

    private void UnbindRowEvents()
    {
        for (int i = 0; i < rows.Count; i++)
        {
            SlotRow row = rows[i];
            if (row == null)
            {
                continue;
            }

            row.prevButton?.onClick.RemoveAllListeners();
            row.nextButton?.onClick.RemoveAllListeners();
        }
    }

    private SlotRow CreateRow(MinimoCharacterCustomizer.PartSlot slot, int index, Font font)
    {
        RectTransform rowRoot = CreateRect($"Row_{slot}", regionListRoot, new Vector2(0f, 1f), new Vector2(1f, 1f), new Vector2(0.5f, 1f), new Vector2(0f, 56f), Vector2.zero);
        Image rowBackground = rowRoot.gameObject.AddComponent<Image>();
        rowBackground.color = index % 2 == 0
            ? new Color(0.11f, 0.17f, 0.26f, 0.94f)
            : new Color(0.09f, 0.14f, 0.22f, 0.94f);
        ApplyRoundedImage(rowBackground);
        EnsureFixedOutline(rowBackground);

        LayoutElement rowLayout = rowRoot.gameObject.AddComponent<LayoutElement>();
        rowLayout.preferredHeight = 56f;
        rowLayout.minHeight = 56f;

        Text slotLabel = CreateRowText("TxtSlot", rowRoot, font, 17, TextAnchor.MiddleLeft, new Color(0.90f, 0.96f, 1f, 1f));
        slotLabel.rectTransform.anchorMin = new Vector2(0f, 0f);
        slotLabel.rectTransform.anchorMax = new Vector2(0f, 1f);
        slotLabel.rectTransform.pivot = new Vector2(0f, 0.5f);
        slotLabel.rectTransform.sizeDelta = new Vector2(180f, 0f);
        slotLabel.rectTransform.anchoredPosition = new Vector2(12f, 0f);

        Button prevButton = CreateRowButton("BtnPrev", rowRoot, "<", font);
        RectTransform prevRect = prevButton.GetComponent<RectTransform>();
        prevRect.anchorMin = new Vector2(0f, 0.5f);
        prevRect.anchorMax = new Vector2(0f, 0.5f);
        prevRect.pivot = new Vector2(0f, 0.5f);
        prevRect.sizeDelta = new Vector2(48f, 38f);
        prevRect.anchoredPosition = new Vector2(196f, 0f);

        Button nextButton = CreateRowButton("BtnNext", rowRoot, ">", font);
        RectTransform nextRect = nextButton.GetComponent<RectTransform>();
        nextRect.anchorMin = new Vector2(1f, 0.5f);
        nextRect.anchorMax = new Vector2(1f, 0.5f);
        nextRect.pivot = new Vector2(1f, 0.5f);
        nextRect.sizeDelta = new Vector2(48f, 38f);
        nextRect.anchoredPosition = new Vector2(-10f, 0f);

        Text variantLabel = CreateRowText("TxtVariant", rowRoot, font, 17, TextAnchor.MiddleCenter, new Color(0.96f, 0.99f, 1f, 1f));
        variantLabel.rectTransform.anchorMin = new Vector2(0f, 0f);
        variantLabel.rectTransform.anchorMax = new Vector2(1f, 1f);
        variantLabel.rectTransform.offsetMin = new Vector2(252f, 0f);
        variantLabel.rectTransform.offsetMax = new Vector2(-64f, 0f);

        SlotRow row = new SlotRow()
        {
            slot = slot,
            root = rowRoot,
            slotLabel = slotLabel,
            variantLabel = variantLabel,
            prevButton = prevButton,
            nextButton = nextButton
        };

        MinimoCharacterCustomizer.PartSlot captured = slot;
        prevButton.onClick.AddListener(() => ChangeSlotVariant(captured, -1));
        nextButton.onClick.AddListener(() => ChangeSlotVariant(captured, 1));
        return row;
    }

    private void BuildRegionButtons(bool forceRebuild = false)
    {
        if (!UsesBodySelectionUI())
        {
            return;
        }

        if (bodySelectRoot == null)
        {
            return;
        }

        List<RectTransform> regionAnchors = new List<RectTransform>();
        for (int i = 0; i < bodySelectRoot.childCount; i++)
        {
            if (bodySelectRoot.GetChild(i) is RectTransform rectChild && rectChild.gameObject.activeSelf)
            {
                regionAnchors.Add(rectChild);
            }
        }

        int expectedRegionCount = regionAnchors.Count;
        if (!forceRebuild && regions.Count == expectedRegionCount && expectedRegionCount > 0)
        {
            return;
        }

        UnbindRegionEvents();
        regions.Clear();

        for (int i = 0; i < regionAnchors.Count; i++)
        {
            RectTransform anchor = regionAnchors[i];
            if (anchor == null)
            {
                continue;
            }

            Button button = ResolveBodyRegionButton(anchor);
            if (button == null)
            {
                continue;
            }

            EnsureShadowPressTracking(button);
            button.onClick.RemoveAllListeners();

            Image background = button.targetGraphic as Image;
            if (background == null)
            {
                background = anchor.GetComponent<Image>();
            }

            RectTransform buttonRect = button.transform as RectTransform;
            string regionName = ResolveRegionAnchorLabel(anchor);
            if ((string.IsNullOrWhiteSpace(regionName) || IsShadowContainerLabel(regionName)) && buttonRect != null)
            {
                string buttonRegionName = ResolveRegionAnchorLabel(buttonRect);
                if (!string.IsNullOrWhiteSpace(buttonRegionName) && !IsShadowContainerLabel(buttonRegionName))
                {
                    regionName = buttonRegionName;
                }
                else if (string.IsNullOrWhiteSpace(regionName))
                {
                    regionName = buttonRect.name?.Trim() ?? string.Empty;
                }
            }

            if (string.IsNullOrWhiteSpace(regionName) && i < HudRegionPresets.Length)
            {
                regionName = HudRegionPresets[i].displayName;
            }

            MinimoCharacterCustomizer.PartSlot[] slots = ResolveSlotsForBodyRegionAnchor(anchor, regionName, i);
            if ((slots == null || slots.Length == 0) && buttonRect != null && buttonRect != anchor)
            {
                string buttonObjectName = buttonRect.name;
                if (TryGetSlotsForBodyRegion(buttonObjectName, out MinimoCharacterCustomizer.PartSlot[] slotsByButtonName))
                {
                    slots = slotsByButtonName;
                }
                else if (buttonRect.parent != null)
                {
                    string buttonHierarchyName = $"{buttonRect.parent.name}_{buttonRect.name}";
                    if (TryGetSlotsForBodyRegion(buttonHierarchyName, out MinimoCharacterCustomizer.PartSlot[] slotsByButtonHierarchy))
                    {
                        slots = slotsByButtonHierarchy;
                    }
                }
            }

            int capturedIndex = regions.Count;
            button.onClick.AddListener(() => HandleRegionSelected(capturedIndex));
            regions.Add(new RegionEntry
            {
                name = regionName,
                slots = slots,
                button = button,
                background = background
            });
        }

        if (selectedRegionIndex < 0 || selectedRegionIndex >= regions.Count)
        {
            selectedRegionIndex = regions.Count > 0 ? 0 : -1;
        }
    }

    private static Button ResolveBodyRegionButton(RectTransform anchor)
    {
        if (anchor == null)
        {
            return null;
        }

        Button anchorButton = anchor.GetComponent<Button>();
        if (anchorButton != null)
        {
            return anchorButton;
        }

        for (int i = 0; i < anchor.childCount; i++)
        {
            Transform child = anchor.GetChild(i);
            if (child == null || !child.gameObject.activeSelf)
            {
                continue;
            }

            Button directChildButton = child.GetComponent<Button>();
            if (directChildButton != null)
            {
                return directChildButton;
            }
        }

        Button nestedButton = anchor.GetComponentInChildren<Button>(true);
        if (nestedButton != null)
        {
            return nestedButton;
        }

        return EnsureBodySelectButton(anchor.gameObject);
    }

    private static bool IsShadowContainerLabel(string value)
    {
        return !string.IsNullOrWhiteSpace(value)
               && value.IndexOf("shadow", StringComparison.OrdinalIgnoreCase) >= 0;
    }

    private static string ResolveRegionAnchorLabel(RectTransform anchor)
    {
        if (anchor == null)
        {
            return string.Empty;
        }

        TMP_Text tmp = anchor.GetComponentInChildren<TMP_Text>(true);
        if (tmp != null && !string.IsNullOrWhiteSpace(tmp.text))
        {
            return tmp.text.Trim();
        }

        Text txt = anchor.GetComponentInChildren<Text>(true);
        if (txt != null && !string.IsNullOrWhiteSpace(txt.text))
        {
            return txt.text.Trim();
        }

        return anchor.name?.Trim() ?? string.Empty;
    }

    private static MinimoCharacterCustomizer.PartSlot[] ResolveSlotsForBodyRegionAnchor(
        RectTransform anchor,
        string regionName,
        int anchorIndex)
    {
        if (TryGetSlotsForBodyRegion(regionName, out MinimoCharacterCustomizer.PartSlot[] slotsByLabel))
        {
            return slotsByLabel;
        }

        string anchorObjectName = anchor != null ? anchor.name : string.Empty;
        if (TryGetSlotsForBodyRegion(anchorObjectName, out MinimoCharacterCustomizer.PartSlot[] slotsByObjectName))
        {
            return slotsByObjectName;
        }

        if (anchor != null && anchor.parent != null)
        {
            string hierarchicalName = $"{anchor.parent.name}_{anchor.name}";
            if (TryGetSlotsForBodyRegion(hierarchicalName, out MinimoCharacterCustomizer.PartSlot[] slotsByHierarchy))
            {
                return slotsByHierarchy;
            }
        }

        if (anchorIndex >= 0 && anchorIndex < HudRegionPresets.Length && HudRegionPresets[anchorIndex] != null)
        {
            MinimoCharacterCustomizer.PartSlot[] presetSlots = HudRegionPresets[anchorIndex].slots;
            return presetSlots ?? Array.Empty<MinimoCharacterCustomizer.PartSlot>();
        }

        return Array.Empty<MinimoCharacterCustomizer.PartSlot>();
    }
    private void EnsureRegionAnchors(List<RectTransform> regionAnchors, int requiredCount, Font font)
    {
        if (bodySelectRoot == null || regionAnchors == null || requiredCount <= regionAnchors.Count)
        {
            return;
        }

        for (int i = regionAnchors.Count; i < requiredCount; i++)
        {
            RectTransform anchor = CreateRect(
                $"Region_{i + 1:00}",
                bodySelectRoot,
                new Vector2(0.5f, 0.5f),
                new Vector2(0.5f, 0.5f),
                new Vector2(0.5f, 0.5f),
                new Vector2(96f, 42f),
                Vector2.zero);

            EnsureBodySelectButton(anchor.gameObject);
            if (anchor.GetComponentInChildren<TMP_Text>(true) == null
                && anchor.GetComponentInChildren<Text>(true) == null)
            {
                Text label = CreateRowText("Label", anchor, font, 13, TextAnchor.MiddleCenter, new Color(0.92f, 0.92f, 0.92f, 1f));
                label.horizontalOverflow = HorizontalWrapMode.Wrap;
                label.verticalOverflow = VerticalWrapMode.Truncate;
                label.rectTransform.offsetMin = new Vector2(4f, 4f);
                label.rectTransform.offsetMax = new Vector2(-4f, -4f);
            }

            regionAnchors.Add(anchor);
        }
    }

    private void ConfigureRegionBarLayout(List<RectTransform> regionAnchors)
    {
        if (bodySelectRoot == null || regionAnchors == null)
        {
            return;
        }

        bool preserveLayout = Application.isPlaying && preserveSceneLayoutDuringPlay;
        if (preserveLayout && HudRegionPresets.Length <= 9)
        {
            return;
        }

        RectTransform regionRoot = bodySelectRoot;

        GridLayoutGroup gridLayout = regionRoot.GetComponent<GridLayoutGroup>();
        HorizontalLayoutGroup horizontalLayout = regionRoot.GetComponent<HorizontalLayoutGroup>();

        if (gridLayout != null)
        {
            gridLayout.padding = new RectOffset(8, 8, 6, 6);
            gridLayout.spacing = new Vector2(8f, HudRegionPresets.Length > 9 ? 6f : 8f);
            gridLayout.startAxis = GridLayoutGroup.Axis.Horizontal;
            gridLayout.startCorner = GridLayoutGroup.Corner.UpperLeft;
            gridLayout.childAlignment = TextAnchor.MiddleLeft;
            gridLayout.constraint = GridLayoutGroup.Constraint.FixedColumnCount;

            if (HudRegionPresets.Length <= 9)
            {
                gridLayout.constraintCount = Mathf.Max(1, HudRegionPresets.Length);
                gridLayout.cellSize = new Vector2(94f, 42f);
            }
            else
            {
                int rowCount = 2;
                int columnCount = Mathf.Max(1, Mathf.CeilToInt(HudRegionPresets.Length / (float)rowCount));
                float availableWidth = Mathf.Max(240f, regionRoot.rect.width - gridLayout.padding.left - gridLayout.padding.right - (columnCount - 1) * gridLayout.spacing.x);
                float cellWidth = Mathf.Clamp(availableWidth / columnCount, 62f, 140f);
                gridLayout.constraintCount = columnCount;
                gridLayout.cellSize = new Vector2(cellWidth, 30f);
            }
        }
        else
        {
            if (horizontalLayout == null)
            {
                LayoutGroup anyLayoutGroup = regionRoot.GetComponent<LayoutGroup>();
                if (anyLayoutGroup == null)
                {
                    horizontalLayout = regionRoot.gameObject.AddComponent<HorizontalLayoutGroup>();
                }
            }

            if (horizontalLayout != null)
            {
                horizontalLayout.padding = new RectOffset(8, 8, 4, 4);
                horizontalLayout.spacing = 6f;
                horizontalLayout.childControlWidth = true;
                horizontalLayout.childControlHeight = true;
                horizontalLayout.childForceExpandWidth = true;
                horizontalLayout.childForceExpandHeight = true;
            }
        }

        ContentSizeFitter fitter = regionRoot.GetComponent<ContentSizeFitter>();
        if (fitter != null)
        {
            fitter.horizontalFit = ContentSizeFitter.FitMode.Unconstrained;
            fitter.verticalFit = ContentSizeFitter.FitMode.Unconstrained;
        }

        for (int i = 0; i < regionAnchors.Count; i++)
        {
            RectTransform anchor = regionAnchors[i];
            if (anchor == null || !anchor.gameObject.activeSelf)
            {
                continue;
            }

            LayoutElement element = anchor.GetComponent<LayoutElement>();
            if (element == null)
            {
                element = anchor.gameObject.AddComponent<LayoutElement>();
            }

            element.minWidth = 80f;
            element.preferredWidth = 96f;
            element.flexibleWidth = 1f;
            element.minHeight = 42f;
            element.preferredHeight = 42f;

            anchor.anchorMin = new Vector2(0.5f, 0.5f);
            anchor.anchorMax = new Vector2(0.5f, 0.5f);
            anchor.pivot = new Vector2(0.5f, 0.5f);
            anchor.anchoredPosition = Vector2.zero;
        }
    }

    private static void SetRegionAnchorLabel(Transform anchor, string label)
    {
        if (anchor == null || string.IsNullOrWhiteSpace(label))
        {
            return;
        }

        TMP_Text tmp = anchor.GetComponentInChildren<TMP_Text>(true);
        if (tmp != null)
        {
            tmp.text = label;
            return;
        }

        Text txt = anchor.GetComponentInChildren<Text>(true);
        if (txt != null)
        {
            txt.text = label;
        }
    }

    private void UnbindRegionEvents()
    {
        for (int i = 0; i < regions.Count; i++)
        {
            regions[i]?.button?.onClick.RemoveAllListeners();
        }
    }

    private void HandleRegionSelected(int regionIndex)
    {
        if (regions.Count == 0)
        {
            return;
        }

        int clampedRegionIndex = Mathf.Clamp(regionIndex, 0, regions.Count - 1);
        if (clampedRegionIndex == selectedRegionIndex)
        {
            UpdateRegionButtonVisuals();
            UpdateVariantButtonVisuals();
            UpdateColorButtonVisuals();
            UpdateWorldLinkedSelectionUi();
            UpdateShadowStickyButtonStates();
            return;
        }

        ResetWorldLinkedMaterialSelectionState();
        selectedWorldVariantTargetSlots = Array.Empty<MinimoCharacterCustomizer.PartSlot>();

        selectedRegionIndex = clampedRegionIndex;

        MinimoCharacterCustomizer.PartSlot[] regionSlots = GetSelectedRegionSlotsRaw();
        if (TryResolveMirroredSlotsForRegion(
                regionSlots,
                out MinimoCharacterCustomizer.PartSlot leftSlot,
                out MinimoCharacterCustomizer.PartSlot rightSlot))
        {
            selectedWorldColorTargetSlot = rightSlot;
            selectedWorldPreviewTargetSlot = rightSlot;
        }
        else
        {
            selectedWorldColorTargetSlot = null;
            selectedWorldPreviewTargetSlot = null;
        }

        selectedColorChannelTarget = ColorChannelTargetType.Material;
        selectedFaceColorPropertyId = -1;
        selectedColorMaterialIndex = 0;
        selectedPaletteButtonIndex = -1;
        hasExplicitPartSelection = true;
        RebuildVariantButtons(true);
        RefreshAfterCustomizationApplication(null, refreshWorldPartColliders: false, savePersistentState: false);
    }

    private void SelectHairRegionByDefault()
    {
        ResetWorldLinkedMaterialSelectionState();

        if (regions.Count == 0)
        {
            return;
        }

        for (int i = 0; i < regions.Count; i++)
        {
            RegionEntry region = regions[i];
            if (region == null || !SlotArrayContains(region.slots, MinimoCharacterCustomizer.PartSlot.Hair))
            {
                continue;
            }

            selectedRegionIndex = i;
            selectedWorldColorTargetSlot = MinimoCharacterCustomizer.PartSlot.Hair;
            selectedWorldPreviewTargetSlot = MinimoCharacterCustomizer.PartSlot.Hair;
            selectedWorldVariantTargetSlots = Array.Empty<MinimoCharacterCustomizer.PartSlot>();
            selectedColorChannelTarget = ColorChannelTargetType.Material;
            selectedFaceColorPropertyId = -1;
            selectedColorMaterialIndex = 0;
            selectedPaletteButtonIndex = -1;
            hasExplicitPartSelection = true;
            return;
        }
    }

    private void SelectEverythingCategoryByDefault()
    {
        if (categoryDropdownSelectsRegions)
        {
            return;
        }

        selectedVariantCategories.Clear();
        selectedVariantCategories.Add(CategoryAllOptionLabel);
        selectedCategoryDropdownIndex = IndexOfCategoryOption(CategoryAllOptionLabel);
        RebuildCustomCategoryDropdownOptions();
        UpdateCustomCategoryDropdownLabel();
    }

    private static void SaveFaceChannelColorFromRendererIfAvailable(
        List<PersistentFaceChannelColor> destination,
        SkinnedMeshRenderer renderer,
        string propertyName,
        int propertyId)
    {
        if (renderer == null)
        {
            return;
        }

        SaveFaceChannelColorIfAvailable(destination, renderer.materials, propertyName, propertyId);
        if (ContainsFaceChannelColorEntry(destination, propertyName))
        {
            return;
        }

        SaveFaceChannelColorIfAvailable(destination, renderer.sharedMaterials, propertyName, propertyId);
    }

    private static bool ContainsFaceChannelColorEntry(
        List<PersistentFaceChannelColor> colors,
        string propertyName)
    {
        if (colors == null || string.IsNullOrWhiteSpace(propertyName))
        {
            return false;
        }

        for (int i = 0; i < colors.Count; i++)
        {
            PersistentFaceChannelColor entry = colors[i];
            if (entry != null && string.Equals(entry.propertyName, propertyName, StringComparison.Ordinal))
            {
                return true;
            }
        }

        return false;
    }

    private void RebuildVariantButtons(bool force = false)
    {
        BodyPartsScrollSnapshot previousBodyPartsScroll = CaptureBodyPartsScrollPosition();

        if (!UsesBodySelectionUI())
        {
            ClearVariantPreviewTextures();
            RestoreBodyPartsScrollPosition(previousBodyPartsScroll);
            return;
        }

        bool faceTextureMode = IsFaceTextureSelectionMode();
        bool propsMode = IsPropsRegionSelectionMode();
        bool bodyVariantMode = !faceTextureMode && !propsMode;
        MinimoCharacterCustomizer.PartSlot[] variantButtonSlots = bodyVariantMode
            ? GetTargetSlotsForVariantButtonPanel()
            : null;
        List<int> filteredVariantIndices = null;
        List<PropVariantEntry> filteredPropEntries = null;
        int expectedButtonCount;
        if (customizer == null)
        {
            expectedButtonCount = 0;
        }
        else if (faceTextureMode)
        {
            expectedButtonCount = GetFaceTextureSetCount() + 1;
        }
        else if (propsMode)
        {
            filteredPropEntries = GetFilteredPropVariantEntriesForCurrentCategory();
            expectedButtonCount = filteredPropEntries.Count + 2;
        }
        else
        {
            filteredVariantIndices = GetFilteredVariantIndicesForCurrentCategory(variantButtonSlots);
            expectedButtonCount = filteredVariantIndices.Count + 1;
        }
        Color[] expectedPalette = GetActivePaletteColors();
        int expectedColorButtonCount = GetExpectedColorButtonCount(expectedPalette);
        int expectedColorChannelButtonCount = GetSelectedRegionColorChannelCount();

        // If the selected category has no part for the current region and shows CategoryInfoPanel,
        // keep existing part buttons exactly as they are (including previews/colors).
        if (TryGetLockedCategorySelection(out string lockedCategoryTheme, out MinimoCategoryInfo lockedCategoryInfo))
        {
            UpdateCategoryInfoPanel(lockedCategoryTheme, lockedCategoryInfo);
            RestoreBodyPartsScrollPosition(previousBodyPartsScroll);
            return;
        }

        UpdateCategoryInfoPanel(string.Empty, null);

        if (!force
            && !bodyVariantMode
            && !propsMode
            && variantButtons.Count > 0
            && customizer != null
            && variantButtons.Count == expectedButtonCount
            && colorButtons.Count == expectedColorButtonCount
            && colorChannelButtons.Count == expectedColorChannelButtonCount
            && IsColorPaletteVisualUpToDate(expectedPalette))
        {
            EnsureVisibleColorButtonsSelectable();
            RestoreBodyPartsScrollPosition(previousBodyPartsScroll);
            return;
        }

        UnbindColorChannelEvents();
        UnbindVariantEvents();
        UnbindColorEvents();
        ClearVariantPreviewTextures();
        colorChannelButtons.Clear();
        variantButtons.Clear();
        colorButtons.Clear();
        UpdateCategoryInfoPanel(string.Empty, null);

        if (bodyPartsContent == null)
        {
            RestoreBodyPartsScrollPosition(previousBodyPartsScroll);
            return;
        }

        ResolveRuntimeTemplateReferences();
        CacheVariantButtonVisualStyle();
        CacheRandomVariantIconStyle();
        for (int i = bodyPartsContent.childCount - 1; i >= 0; i--)
        {
            Transform child = bodyPartsContent.GetChild(i);
            if (IsBodyPartRuntimeTemplateTransform(child))
            {
                child.gameObject.SetActive(false);
                continue;
            }

            child.SetParent(null, false);
            DestroyGameObjectSafely(child.gameObject);
        }

        if (colorPanelContent != null)
        {
            Transform protectedHeaderTransform = colorPanelHeaderLabel != null ? colorPanelHeaderLabel.transform : null;
            for (int i = colorPanelContent.childCount - 1; i >= 0; i--)
            {
                Transform child = colorPanelContent.GetChild(i);
                if (protectedHeaderTransform != null && (child == protectedHeaderTransform || child.IsChildOf(protectedHeaderTransform)))
                {
                    continue;
                }

                if (IsColorRuntimeTemplateTransform(child))
                {
                    child.gameObject.SetActive(false);
                    continue;
                }

                // Keep scene-authored swatch objects (ColorPanel children) and only clear
                // runtime-generated entries from previous rebuilds.
                if (!IsRuntimeGeneratedColorPanelEntry(child))
                {
                    continue;
                }

                DestroyGameObjectSafely(child.gameObject);
            }
        }

        if (customizer == null || selectedRegionIndex < 0 || selectedRegionIndex >= regions.Count)
        {
            RestoreBodyPartsScrollPosition(previousBodyPartsScroll);
            return;
        }

        if (!faceTextureMode && !propsMode && filteredVariantIndices == null)
        {
            RestoreBodyPartsScrollPosition(previousBodyPartsScroll);
            return;
        }

        Font font = ResolveFont();
        BuildColorChannelButtons(font);
        BuildColorPaletteButtons();

        if (faceTextureMode)
        {
            AddRandomVariantButton(font, faceTextureMode: true, propsMode: false);
            BuildFaceTextureButtons(font);
            RestoreBodyPartsScrollPosition(previousBodyPartsScroll);
            return;
        }

        if (propsMode)
        {
            filteredPropEntries ??= GetFilteredPropVariantEntriesForCurrentCategory();
            AddRandomVariantButton(font, faceTextureMode: false, propsMode: true);
            AddEmptyPropButton(font);
            BuildPropButtons(font, filteredPropEntries);
            RestoreBodyPartsScrollPosition(previousBodyPartsScroll);
            QueueVisiblePreviewWarmupIfNeeded();
            return;
        }

        MinimoCharacterCustomizer.PartSlot[] selectedSlots = variantButtonSlots ?? GetTargetSlotsForVariantButtonPanel();
        MinimoCharacterCustomizer.PartSlot? preferredPreviewSlot = ResolvePreferredPreviewSlotForVariantButtons(selectedSlots);
        bool isFaceOnlySelection = selectedSlots != null
                                   && selectedSlots.Length == 1
                                   && selectedSlots[0] == MinimoCharacterCustomizer.PartSlot.Face;
        AddRandomVariantButton(font, faceTextureMode: false, propsMode: false);
        if (IsSingleHairSlotSelection(selectedSlots))
        {
            AddDefaultVariantButton(font);
        }

        List<VariantBuildEntry> entries = new List<VariantBuildEntry>();
        for (int i = 0; i < filteredVariantIndices.Count; i++)
        {
            int variantIndex = filteredVariantIndices[i];
            MinimoCharacterCustomizer.PartSlot[] entryTargetSlots = GetVariantTargetSlotsForSelectedSlots(
                variantIndex,
                selectedSlots);
            if (entryTargetSlots.Length == 0)
            {
                continue;
            }

            string fallbackDisplayName = customizer.GetVariantDisplayName(variantIndex);
            string displayName = ResolveVariantDisplayNameForSlots(variantIndex, entryTargetSlots, fallbackDisplayName);
            string categoryName = ResolveVariantCategoryNameForSlots(variantIndex, entryTargetSlots);
            entries.Add(new VariantBuildEntry
            {
                variantIndex = variantIndex,
                displayName = displayName,
                categoryName = categoryName,
                targetSlots = entryTargetSlots
            });
        }

        entries.Sort((left, right) =>
        {
            string leftCategory = NormalizeCategoryName(left?.categoryName);
            string rightCategory = NormalizeCategoryName(right?.categoryName);

            int leftCategoryPriority = isFaceOnlySelection
                ? GetFaceVariantCategorySortPriority(leftCategory)
                : GetVariantCategorySortPriority(leftCategory);
            int rightCategoryPriority = isFaceOnlySelection
                ? GetFaceVariantCategorySortPriority(rightCategory)
                : GetVariantCategorySortPriority(rightCategory);
            if (leftCategoryPriority != rightCategoryPriority)
            {
                return leftCategoryPriority.CompareTo(rightCategoryPriority);
            }

            int byCategory = CompareAlphabeticNatural(leftCategory, rightCategory);
            if (byCategory != 0)
            {
                return byCategory;
            }

            int byName = CompareAlphabeticNatural(left?.displayName, right?.displayName);
            if (byName != 0)
            {
                return byName;
            }

            int leftIndex = left != null ? left.variantIndex : -1;
            int rightIndex = right != null ? right.variantIndex : -1;
            return leftIndex.CompareTo(rightIndex);
        });
        CollapseDuplicateVariantEntriesByMeshAndMaterials(entries);

        for (int i = 0; i < entries.Count; i++)
        {
            VariantBuildEntry entry = entries[i];
            if (entry == null)
            {
                continue;
            }

            Button button = CreateVariantButton(bodyPartsContent, font, entry.displayName, entry.variantIndex);
            ApplyVariantButtonVisualStyle(button);
            EnsureShadowPressTracking(button);
            MinimoCharacterCustomizer.PartSlot? entryPreviewSlot =
                ResolvePreferredPreviewSlotForVariantButtons(entry.targetSlots);
            TryApplyVariantButtonPreview(button, entry.variantIndex, entry.displayName, entryPreviewSlot ?? preferredPreviewSlot);
            ApplyVariantCategoryBorder(button, entry.categoryName, isRandom: false);
            int capturedVariantIndex = entry.variantIndex;
            MinimoCharacterCustomizer.PartSlot[] capturedTargetSlots = CopyPartSlotArray(entry.targetSlots);
            button.onClick.AddListener(() => ApplyRegionVariant(capturedVariantIndex, capturedTargetSlots));

            variantButtons.Add(new VariantButtonEntry
            {
                variantIndex = entry.variantIndex,
                isRandomButton = false,
                isFaceTextureButton = false,
                targetSlots = CopyPartSlotArray(entry.targetSlots),
                button = button,
                background = button.targetGraphic as Image
            });
        }

        RestoreBodyPartsScrollPosition(previousBodyPartsScroll);
        QueueVisiblePreviewWarmupIfNeeded();
    }

    private void CollapseDuplicateVariantEntriesByMeshAndMaterials(List<VariantBuildEntry> entries)
    {
        if (entries == null || entries.Count <= 1 || customizer == null)
        {
            return;
        }

        Dictionary<string, bool> visibleSignatures = new Dictionary<string, bool>(StringComparer.Ordinal);
        for (int i = 0; i < entries.Count;)
        {
            VariantBuildEntry entry = entries[i];
            MinimoCharacterCustomizer.PartSlot[] targetSlots = entry?.targetSlots;
            if (entry == null
                || targetSlots == null
                || targetSlots.Length == 0
                || !TryBuildVariantMeshMaterialSignature(entry.variantIndex, targetSlots, out string signature)
                || string.IsNullOrWhiteSpace(signature))
            {
                i++;
                continue;
            }

            if (visibleSignatures.ContainsKey(signature))
            {
                entries.RemoveAt(i);
                continue;
            }

            visibleSignatures[signature] = true;
            i++;
        }
    }

    private bool TryBuildVariantMeshMaterialSignature(
        int variantIndex,
        MinimoCharacterCustomizer.PartSlot[] selectedSlots,
        out string signature)
    {
        signature = string.Empty;
        if (variantIndex < 0 || selectedSlots == null || selectedSlots.Length == 0 || customizer == null)
        {
            return false;
        }

        StringBuilder builder = new StringBuilder();
        bool wroteAnySlot = false;
        for (int i = 0; i < selectedSlots.Length; i++)
        {
            MinimoCharacterCustomizer.PartSlot slot = selectedSlots[i];
            if (!customizer.TryGetVariantPartPreviewData(
                    variantIndex,
                    slot,
                    out Mesh mesh,
                    out Material[] materials,
                    out _,
                    out _)
                || mesh == null)
            {
                return false;
            }

            AppendMeshVisualSignature(builder, mesh);
            builder.Append(":mat=");
            AppendMaterialVisualSignature(builder, materials);
            builder.Append(';');
            wroteAnySlot = true;
        }

        signature = builder.ToString();
        return wroteAnySlot && !string.IsNullOrWhiteSpace(signature);
    }

    private static void CollapseDuplicatePropVariantEntriesByMeshAndMaterials(List<PropVariantEntry> entries)
    {
        if (entries == null || entries.Count <= 1)
        {
            return;
        }

        Dictionary<string, bool> visibleSignatures = new Dictionary<string, bool>(StringComparer.Ordinal);
        for (int i = 0; i < entries.Count;)
        {
            PropVariantEntry entry = entries[i];
            if (entry == null
                || !TryBuildPropVariantMeshMaterialSignature(entry, out string signature)
                || string.IsNullOrWhiteSpace(signature))
            {
                i++;
                continue;
            }

            if (visibleSignatures.ContainsKey(signature))
            {
                entries.RemoveAt(i);
                continue;
            }

            visibleSignatures[signature] = true;
            i++;
        }
    }

    private static bool TryBuildPropVariantMeshMaterialSignature(PropVariantEntry entry, out string signature)
    {
        signature = string.Empty;
        if (entry?.sourcePrefab == null)
        {
            return false;
        }

        Renderer[] sourceRenderers = entry.sourcePrefab.GetComponentsInChildren<Renderer>(true);
        if (sourceRenderers == null || sourceRenderers.Length == 0)
        {
            return false;
        }

        List<Renderer> renderers = new List<Renderer>();
        for (int i = 0; i < sourceRenderers.Length; i++)
        {
            Renderer renderer = sourceRenderers[i];
            if (renderer == null)
            {
                continue;
            }

            if (TryGetRendererSignatureMesh(renderer, out _))
            {
                renderers.Add(renderer);
            }
        }

        if (renderers.Count == 0)
        {
            return false;
        }

        List<string> rendererSignatures = new List<string>();
        for (int i = 0; i < renderers.Count; i++)
        {
            Renderer renderer = renderers[i];
            if (renderer == null || !TryGetRendererSignatureMesh(renderer, out Mesh mesh) || mesh == null)
            {
                continue;
            }

            StringBuilder rendererBuilder = new StringBuilder();
            AppendMeshVisualSignature(rendererBuilder, mesh);
            rendererBuilder.Append(":mat=");
            AppendMaterialVisualSignature(rendererBuilder, renderer.sharedMaterials);
            rendererSignatures.Add(rendererBuilder.ToString());
        }

        rendererSignatures.Sort(StringComparer.Ordinal);
        StringBuilder builder = new StringBuilder();
        for (int i = 0; i < rendererSignatures.Count; i++)
        {
            builder.Append(rendererSignatures[i]);
            builder.Append(';');
        }

        signature = builder.ToString();
        return !string.IsNullOrWhiteSpace(signature);
    }

    private static bool TryGetRendererSignatureMesh(Renderer renderer, out Mesh mesh)
    {
        mesh = null;
        if (renderer is SkinnedMeshRenderer skinnedRenderer)
        {
            mesh = skinnedRenderer.sharedMesh;
            return mesh != null;
        }

        if (renderer is MeshRenderer && renderer.TryGetComponent(out MeshFilter meshFilter) && meshFilter != null)
        {
            mesh = meshFilter.sharedMesh;
            return mesh != null;
        }

        return false;
    }

    private static void AppendMeshVisualSignature(StringBuilder builder, Mesh mesh)
    {
        if (builder == null)
        {
            return;
        }

        if (mesh == null)
        {
            builder.Append("none");
            return;
        }

        int cacheKey = Application.isPlaying ? mesh.GetInstanceID() : 0;
        if (cacheKey != 0 && RuntimeMeshVisualSignatureCache.TryGetValue(cacheKey, out string cachedSignature))
        {
            builder.Append(cachedSignature);
            return;
        }

        int signatureStart = builder.Length;
        unchecked
        {
            uint hash = 2166136261u;
            AppendHash(ref hash, mesh.vertexCount);
            AppendHash(ref hash, mesh.subMeshCount);
            AppendHash(ref hash, mesh.blendShapeCount);
            Bounds bounds = mesh.bounds;
            AppendHash(ref hash, QuantizeSignatureFloat(bounds.center.x));
            AppendHash(ref hash, QuantizeSignatureFloat(bounds.center.y));
            AppendHash(ref hash, QuantizeSignatureFloat(bounds.center.z));
            AppendHash(ref hash, QuantizeSignatureFloat(bounds.size.x));
            AppendHash(ref hash, QuantizeSignatureFloat(bounds.size.y));
            AppendHash(ref hash, QuantizeSignatureFloat(bounds.size.z));

            for (int subMeshIndex = 0; subMeshIndex < mesh.subMeshCount; subMeshIndex++)
            {
                AppendHash(ref hash, (int)mesh.GetTopology(subMeshIndex));
                AppendHash(ref hash, mesh.GetIndexCount(subMeshIndex));
            }

            builder.Append(mesh.vertexCount);
            builder.Append('/');
            builder.Append(mesh.subMeshCount);
            builder.Append('/');
            builder.Append(hash.ToString("X8", CultureInfo.InvariantCulture));
            AppendMeshVertexShapeSignature(builder, mesh);
        }

        if (cacheKey != 0)
        {
            RuntimeMeshVisualSignatureCache[cacheKey] = builder.ToString(signatureStart, builder.Length - signatureStart);
        }
    }

    private static void AppendMeshVertexShapeSignature(StringBuilder builder, Mesh mesh)
    {
        if (builder == null || mesh == null)
        {
            return;
        }

        try
        {
            unchecked
            {
                uint hash = 2166136261u;
                List<Vector3> vertices = new List<Vector3>(mesh.vertexCount);
                mesh.GetVertices(vertices);
                for (int i = 0; i < vertices.Count; i++)
                {
                    Vector3 vertex = vertices[i];
                    AppendHash(ref hash, QuantizeSignatureFloat(vertex.x));
                    AppendHash(ref hash, QuantizeSignatureFloat(vertex.y));
                    AppendHash(ref hash, QuantizeSignatureFloat(vertex.z));
                }

                for (int subMeshIndex = 0; subMeshIndex < mesh.subMeshCount; subMeshIndex++)
                {
                    int[] indices = mesh.GetIndices(subMeshIndex);
                    if (indices == null)
                    {
                        continue;
                    }

                    for (int i = 0; i < indices.Length; i++)
                    {
                        AppendHash(ref hash, indices[i]);
                    }
                }

                builder.Append("/shape=");
                builder.Append(hash.ToString("X8", CultureInfo.InvariantCulture));
            }
        }
        catch (Exception)
        {
            builder.Append("/shape=unreadable");
        }
    }

    private static int QuantizeSignatureFloat(float value)
    {
        return Mathf.RoundToInt(value * 10000f);
    }

    private static void AppendHash(ref uint hash, int value)
    {
        unchecked
        {
            hash ^= (uint)value;
            hash *= 16777619u;
        }
    }

    private static void AppendHash(ref uint hash, uint value)
    {
        unchecked
        {
            hash ^= value;
            hash *= 16777619u;
        }
    }

    private static void AppendMaterialVisualSignature(StringBuilder builder, Material[] materials)
    {
        if (builder == null)
        {
            return;
        }

        int materialCount = materials != null ? materials.Length : 0;
        List<string> materialTokens = new List<string>();
        for (int i = 0; i < materialCount; i++)
        {
            materialTokens.Add(BuildMaterialVisualSignatureToken(materials[i]));
        }

        if (materialTokens.Count == 0)
        {
            builder.Append("none");
            return;
        }

        materialTokens.Sort(StringComparer.Ordinal);
        for (int i = 0; i < materialTokens.Count; i++)
        {
            builder.Append(materialTokens[i]);
            builder.Append("||");
        }
    }

    private static string BuildMaterialVisualSignatureToken(Material material)
    {
        if (material == null)
        {
            return "null";
        }

        List<string> colorTokens = new List<string>();
        List<string> textureTokens = new List<string>();
        AppendMaterialColorTokens(material, colorTokens);
        AppendMaterialTextureTokens(material, textureTokens);

        StringBuilder builder = new StringBuilder();

        builder.Append("shader=");
        builder.Append(material.shader != null ? NormalizeVisualSignatureToken(material.shader.name) : "none");
        builder.Append(';');
        builder.Append("colors=");
        if (colorTokens.Count == 0)
        {
            builder.Append("none");
        }
        else
        {
            colorTokens.Sort(StringComparer.Ordinal);
            for (int i = 0; i < colorTokens.Count; i++)
            {
                builder.Append(colorTokens[i]);
                builder.Append('|');
            }
        }

        builder.Append(";textures=");
        if (textureTokens.Count == 0)
        {
            builder.Append("none");
            return builder.ToString();
        }

        textureTokens.Sort(StringComparer.Ordinal);
        for (int i = 0; i < textureTokens.Count; i++)
        {
            builder.Append(textureTokens[i]);
            builder.Append('|');
        }

        return builder.ToString();
    }

    private static void AppendMaterialColorTokens(Material material, List<string> colorTokens)
    {
        if (material == null || colorTokens == null)
        {
            return;
        }

        for (int propertyIndex = 0; propertyIndex < VisualColorPropertyIds.Length; propertyIndex++)
        {
            int propertyId = VisualColorPropertyIds[propertyIndex];
            if (!material.HasProperty(propertyId))
            {
                continue;
            }

            Color32 color = material.GetColor(propertyId);
            string token = $"{propertyId}:{color.r},{color.g},{color.b},{color.a}";
            if (!StringListContains(colorTokens, token))
            {
                colorTokens.Add(token);
            }
        }
    }

    private static void AppendMaterialTextureTokens(Material material, List<string> textureTokens)
    {
        if (material == null || textureTokens == null)
        {
            return;
        }

        int[] texturePropertyIds = material.GetTexturePropertyNameIDs();
        if (texturePropertyIds != null)
        {
            for (int i = 0; i < texturePropertyIds.Length; i++)
            {
                AppendMaterialTextureToken(material, texturePropertyIds[i], textureTokens);
            }
        }

        for (int i = 0; i < VisualTexturePropertyIds.Length; i++)
        {
            AppendMaterialTextureToken(material, VisualTexturePropertyIds[i], textureTokens);
        }
    }

    private static void AppendMaterialTextureToken(Material material, int propertyId, List<string> textureTokens)
    {
        if (material == null
            || textureTokens == null
            || !material.HasProperty(propertyId))
        {
            return;
        }

        Texture texture = material.GetTexture(propertyId);
        if (texture == null)
        {
            return;
        }

        string token = BuildTextureVisualSignatureToken(texture);
        if (!string.IsNullOrWhiteSpace(token) && !StringListContains(textureTokens, token))
        {
            textureTokens.Add(token);
        }
    }

    private static string BuildTextureVisualSignatureToken(Texture texture)
    {
        if (texture == null)
        {
            return string.Empty;
        }

#if UNITY_EDITOR
        string texturePath = AssetDatabase.GetAssetPath(texture);
        if (!string.IsNullOrWhiteSpace(texturePath))
        {
            return $"path:{NormalizeVisualSignatureToken(NormalizeCategoryAssetPath(texturePath))}";
        }
#endif

        return $"{NormalizeVisualSignatureToken(texture.name)}#{texture.width}x{texture.height}#{texture.GetInstanceID()}";
    }

    private static void AppendMaterialColorSignature(StringBuilder builder, Material[] materials)
    {
        AppendMaterialVisualSignature(builder, materials);
    }

    private static string NormalizeVisualSignatureToken(string value)
    {
        return string.IsNullOrWhiteSpace(value)
            ? string.Empty
            : value.Trim().ToUpperInvariant();
    }

    private string ResolveVariantDisplayNameForSlots(
        int variantIndex,
        MinimoCharacterCustomizer.PartSlot[] selectedSlots,
        string fallbackDisplayName)
    {
        if (customizer == null || selectedSlots == null || selectedSlots.Length == 0 || variantIndex < 0)
        {
            return fallbackDisplayName;
        }

        for (int i = 0; i < selectedSlots.Length; i++)
        {
            MinimoCharacterCustomizer.PartSlot slot = selectedSlots[i];
            if (!customizer.TryGetVariantSourcePrefabForSlot(slot, variantIndex, out GameObject sourcePrefab)
                || sourcePrefab == null
                || string.IsNullOrWhiteSpace(sourcePrefab.name))
            {
                continue;
            }

            return sourcePrefab.name.Trim();
        }

        return fallbackDisplayName;
    }

    private bool IsPropsRegionSelectionMode()
    {
        if (selectedRegionIndex < 0 || selectedRegionIndex >= regions.Count)
        {
            return false;
        }

        RegionEntry region = regions[selectedRegionIndex];
        if (region == null)
        {
            return false;
        }

        string regionName = NormalizeBodyRegionKey(region.name);
        if (RegionNameContainsToken(regionName, "PROP"))
        {
            return true;
        }

        if (region.button != null)
        {
            string buttonName = NormalizeBodyRegionKey(region.button.name);
            if (RegionNameContainsToken(buttonName, "PROP"))
            {
                return true;
            }
        }

        return false;
    }

    private void BuildPropButtons(Font font, List<PropVariantEntry> propEntries)
    {
        if (bodyPartsContent == null || propEntries == null || propEntries.Count == 0)
        {
            return;
        }

        for (int i = 0; i < propEntries.Count; i++)
        {
            PropVariantEntry entry = propEntries[i];
            if (entry == null)
            {
                continue;
            }

            Button button = CreateVariantButton(bodyPartsContent, font, entry.displayName, i);
            ApplyVariantButtonVisualStyle(button);
            EnsureShadowPressTracking(button);
            button.gameObject.name = $"Part_Prop_{entry.rigName}_{entry.propIndex:00}";
            TryApplyPropButtonPreview(button, entry);
            ApplyVariantCategoryBorder(button, entry.categoryName, isRandom: false);

            PropVariantEntry capturedEntry = entry;
            button.onClick.AddListener(() => ApplyPropVariantSelection(capturedEntry));

            variantButtons.Add(new VariantButtonEntry
            {
                variantIndex = -1,
                isRandomButton = false,
                isFaceTextureButton = false,
                isPropButton = true,
                isPropEmptyButton = false,
                propCategoryName = entry.categoryName,
                propRigName = entry.rigName,
                propPrefabName = entry.prefabName,
                propAssetPath = entry.assetPath,
                propPreviewEntry = entry,
                button = button,
                background = button.targetGraphic as Image
            });
        }
    }

    private List<PropVariantEntry> GetFilteredPropVariantEntriesForCurrentCategory()
    {
        List<PropVariantEntry> allEntries = BuildAllPropVariantEntries();
        if (allEntries.Count == 0)
        {
            return allEntries;
        }

        HashSet<string> selectedCategories = GetActiveSpecificCategoryFilters();
        if (selectedCategories == null || selectedCategories.Count == 0)
        {
            CollapseDuplicatePropVariantEntriesByMeshAndMaterials(allEntries);
            return allEntries;
        }

        List<PropVariantEntry> filtered = new List<PropVariantEntry>();
        for (int i = 0; i < allEntries.Count; i++)
        {
            PropVariantEntry entry = allEntries[i];
            if (entry == null)
            {
                continue;
            }

            string categoryName = NormalizeCategoryName(entry.categoryName);
            if (selectedCategories.Contains(categoryName))
            {
                filtered.Add(entry);
            }
        }

        CollapseDuplicatePropVariantEntriesByMeshAndMaterials(filtered);
        return filtered;
    }

    private List<PropVariantEntry> BuildAllPropVariantEntries()
    {
        List<PropVariantEntry> entries = new List<PropVariantEntry>();
#if UNITY_EDITOR
        string[] prefabGuids = AssetDatabase.FindAssets("t:Prefab", new[] { CustomizeRootFolder });
        for (int i = 0; i < prefabGuids.Length; i++)
        {
            string assetPath = AssetDatabase.GUIDToAssetPath(prefabGuids[i]);
            string normalizedPath = NormalizeCategoryAssetPath(assetPath);
            if (string.IsNullOrWhiteSpace(normalizedPath)
                || normalizedPath.IndexOf(PropsFolderToken, StringComparison.OrdinalIgnoreCase) < 0)
            {
                continue;
            }

            string prefabName = Path.GetFileNameWithoutExtension(assetPath);
            if (!TryParsePropPrefabName(prefabName, out string rigName, out int propIndex))
            {
                continue;
            }

            GameObject sourcePrefab = AssetDatabase.LoadAssetAtPath<GameObject>(assetPath);
            if (sourcePrefab == null)
            {
                continue;
            }

            string categoryName = ResolvePropCategoryNameFromAssetPath(assetPath);
            entries.Add(new PropVariantEntry
            {
                displayName = prefabName,
                categoryName = categoryName,
                rigName = rigName,
                prefabName = prefabName,
                assetPath = assetPath,
                propIndex = propIndex,
                previewSlot = ResolvePreviewSlotForPropRigName(rigName),
                sourcePrefab = sourcePrefab
            });
        }
#endif

        entries.Sort((left, right) =>
        {
            string leftCategory = NormalizeCategoryName(left?.categoryName);
            string rightCategory = NormalizeCategoryName(right?.categoryName);

            int leftCategoryPriority = GetVariantCategorySortPriority(leftCategory);
            int rightCategoryPriority = GetVariantCategorySortPriority(rightCategory);
            if (leftCategoryPriority != rightCategoryPriority)
            {
                return leftCategoryPriority.CompareTo(rightCategoryPriority);
            }

            int byCategory = CompareAlphabeticNatural(leftCategory, rightCategory);
            if (byCategory != 0)
            {
                return byCategory;
            }

            int byRig = CompareAlphabeticNatural(left?.rigName, right?.rigName);
            if (byRig != 0)
            {
                return byRig;
            }

            int byIndex = (left?.propIndex ?? int.MaxValue).CompareTo(right?.propIndex ?? int.MaxValue);
            if (byIndex != 0)
            {
                return byIndex;
            }

            return CompareAlphabeticNatural(left?.displayName, right?.displayName);
        });

        return entries;
    }

    private static bool TryParsePropPrefabName(string prefabName, out string rigName, out int propIndex)
    {
        rigName = string.Empty;
        propIndex = int.MaxValue;
        if (string.IsNullOrWhiteSpace(prefabName))
        {
            return false;
        }

        const string token = "_PROP-";
        int tokenIndex = prefabName.IndexOf(token, StringComparison.OrdinalIgnoreCase);
        if (tokenIndex <= 0)
        {
            return false;
        }

        rigName = prefabName.Substring(0, tokenIndex).Trim();
        if (string.IsNullOrWhiteSpace(rigName))
        {
            return false;
        }

        string suffix = prefabName.Substring(tokenIndex + token.Length).Trim();
        if (int.TryParse(suffix, out int parsedIndex))
        {
            propIndex = parsedIndex;
            return true;
        }

        int leadingDigits = 0;
        while (leadingDigits < suffix.Length && char.IsDigit(suffix[leadingDigits]))
        {
            leadingDigits++;
        }

        if (leadingDigits > 0 && int.TryParse(suffix.Substring(0, leadingDigits), out parsedIndex))
        {
            propIndex = parsedIndex;
        }

        return true;
    }

    private static string ResolvePropCategoryNameFromAssetPath(string assetPath)
    {
        string normalizedPath = NormalizeCategoryAssetPath(assetPath);
        if (string.IsNullOrWhiteSpace(normalizedPath))
        {
            return CategoryDefaultOptionLabel;
        }

        int customizeIndex = normalizedPath.IndexOf("/Customize/", StringComparison.OrdinalIgnoreCase);
        int propsIndex = normalizedPath.LastIndexOf(PropsFolderToken, StringComparison.OrdinalIgnoreCase);
        if (customizeIndex < 0 || propsIndex <= customizeIndex)
        {
            return CategoryDefaultOptionLabel;
        }

        int categoryStart = customizeIndex + "/Customize/".Length;
        int categoryLength = propsIndex - categoryStart;
        if (categoryLength <= 0)
        {
            return CategoryDefaultOptionLabel;
        }

        string rawCategory = normalizedPath.Substring(categoryStart, categoryLength).Trim('/');
        return string.IsNullOrWhiteSpace(rawCategory)
            ? CategoryDefaultOptionLabel
            : NormalizeCategoryName(rawCategory);
    }

    private static MinimoCharacterCustomizer.PartSlot ResolvePreviewSlotForPropRigName(string _rigName)
    {
        return MinimoCharacterCustomizer.PartSlot.Props;
    }

    private void TryApplyPropButtonPreview(
        Button button,
        PropVariantEntry entry,
        bool allowRuntimeCacheMissRender = false)
    {
        if (!showVariantPreviewInHud
            || button == null
            || entry == null
            || entry.sourcePrefab == null)
        {
            return;
        }

        if (TryGetCachedPropPreviewCacheEntry(entry, out PreviewTextureCacheEntry cachedEntry))
        {
            ApplyCachedPreviewTextureToButton(button, cachedEntry);
            return;
        }

        if (deferPreviewGeneration)
        {
            return;
        }

        if (Application.isPlaying && !allowRuntimeCacheMissRender)
        {
            return;
        }

        if (TryGetOrCreatePropPreviewCacheEntry(entry, out PreviewTextureCacheEntry cacheEntry))
        {
            ApplyCachedPreviewTextureToButton(button, cacheEntry);
        }
    }

    private bool TryGetCachedPropPreviewCacheEntry(
        PropVariantEntry entry,
        out PreviewTextureCacheEntry cacheEntry)
    {
        cacheEntry = null;
        if (entry == null || entry.sourcePrefab == null)
        {
            return false;
        }

        string cacheKey = BuildPropPreviewCacheKey(entry);
        if (!propPreviewTextureCache.TryGetValue(cacheKey, out cacheEntry))
        {
            return false;
        }

        if (cacheEntry != null && cacheEntry.texture != null)
        {
            return true;
        }

        propPreviewTextureCache.Remove(cacheKey);
        cacheEntry = null;
        return false;
    }

    private bool TryGetOrCreatePropPreviewCacheEntry(PropVariantEntry entry, out PreviewTextureCacheEntry cacheEntry)
    {
        cacheEntry = null;
        if (entry == null || entry.sourcePrefab == null)
        {
            return false;
        }

        if (TryGetCachedPropPreviewCacheEntry(entry, out cacheEntry))
        {
            return true;
        }

        string cacheKey = BuildPropPreviewCacheKey(entry);
        MinimoCharacterCustomizer.PartSlot previewSlot = ResolvePreviewSlotForPropRigName(entry.rigName);
        if (!TryRenderPropSourcePrefabPreviewTexture(
                entry.sourcePrefab,
                entry.rigName,
                entry.prefabName,
                out Texture2D previewTexture)
            || !TryCreatePreviewCacheEntry(previewTexture, previewSlot, out cacheEntry))
        {
            return false;
        }

        propPreviewTextureCache[cacheKey] = cacheEntry;
        return true;
    }

    private static string BuildPropPreviewCacheKey(PropVariantEntry entry)
    {
        if (entry == null)
        {
            return string.Empty;
        }

        string assetKey = !string.IsNullOrWhiteSpace(entry.assetPath)
            ? entry.assetPath
            : entry.sourcePrefab != null
                ? entry.sourcePrefab.GetInstanceID().ToString()
                : entry.prefabName;
        return $"preview:{PreviewRenderSettingsVersion}|prop:{assetKey}|rig:{entry.rigName}|prefab:{entry.prefabName}";
    }

    private bool TryRenderPropSourcePrefabPreviewTexture(
        GameObject sourcePrefab,
        string rigName,
        string prefabName,
        out Texture2D previewTexture)
    {
        previewTexture = null;
        if (sourcePrefab == null || !EnsureVariantPreviewRenderer())
        {
            return false;
        }

        variantPreviewMeshFilter.sharedMesh = null;
        variantPreviewMeshRenderer.sharedMaterial = null;

        GameObject instance = null;
        try
        {
            PartPreviewProfile previewProfile = ResolvePropPreviewProfile(rigName, prefabName);
            if (!EnsureVariantPreviewRenderTexture(previewProfile.previewResolution))
            {
                return false;
            }

            instance = Instantiate(sourcePrefab);
            if (instance == null)
            {
                return false;
            }

            instance.name = StripUnityCloneSuffix(sourcePrefab.name);
            instance.hideFlags = HideFlags.HideAndDontSave;
            instance.transform.SetParent(variantPreviewPrefabRoot, false);
            instance.transform.localPosition = Vector3.zero;
            instance.transform.localRotation = Quaternion.identity;
            instance.transform.localScale = Vector3.one;
            StripUnityCloneSuffixesRecursively(instance.transform);
            SetHideFlagsRecursively(instance.transform, HideFlags.HideAndDontSave);
            ApplyPreviewMaterialBoostsToRenderers(instance);

            Transform previewTarget = ResolvePropPreviewTargetTransform(instance.transform);
            if (previewTarget == null)
            {
                return false;
            }

            if (!TryGetWorldPreviewBoundsAndCenter(previewTarget.gameObject, out Bounds worldBounds, out Vector3 worldCenter))
            {
                return false;
            }

            Vector3 localCenter = variantPreviewRoot.transform.InverseTransformPoint(worldCenter);
            instance.transform.localPosition -= localCenter;
            instance.transform.localRotation = previewProfile.rotation;

            if (!TryGetWorldPreviewBoundsAndCenter(previewTarget.gameObject, out worldBounds, out worldCenter))
            {
                return false;
            }

            localCenter = variantPreviewRoot.transform.InverseTransformPoint(worldCenter);
            instance.transform.localPosition -= localCenter;

            Vector3 screenNudge = ResolvePreviewScreenNudgeWorld(previewProfile.positionOffsetNormalized, worldBounds.extents);
            if (screenNudge.sqrMagnitude > 0.0000001f)
            {
                instance.transform.localPosition += screenNudge;
                if (!TryGetWorldPreviewBoundsAndCenter(previewTarget.gameObject, out worldBounds, out worldCenter))
                {
                    return false;
                }
            }

            float aspect = variantPreviewRenderTexture != null && variantPreviewRenderTexture.height > 0
                ? variantPreviewRenderTexture.width / (float)variantPreviewRenderTexture.height
                : 1f;
            float halfWidth = Mathf.Max(0.05f, worldBounds.extents.x);
            float halfHeight = Mathf.Max(0.05f, worldBounds.extents.y);
            float orthoSizeFromWidth = aspect > 0.0001f ? halfWidth / aspect : halfWidth;
            float meshScale = Mathf.Max(0.01f, previewProfile.meshScale);
            float orthoSize = Mathf.Max(halfHeight, orthoSizeFromWidth)
                              * previewProfile.orthoPadding
                              * Mathf.Max(0.01f, previewProfile.sizeMultiplier)
                              * (1f / meshScale);
            float depth = Mathf.Max(0.15f, worldBounds.extents.z * 2f);
            float cameraDistance = Mathf.Max(1.6f, depth * 1.6f);

            variantPreviewCamera.transform.localPosition = new Vector3(0f, 0f, -cameraDistance);
            variantPreviewCamera.transform.localRotation = Quaternion.identity;
            variantPreviewCamera.orthographic = true;
            variantPreviewCamera.orthographicSize = orthoSize;
            variantPreviewCamera.nearClipPlane = 0.01f;
            variantPreviewCamera.farClipPlane = cameraDistance + depth * 4f + 2f;
            variantPreviewCamera.backgroundColor = PreviewBackgroundColor;
            ConfigureBrightPreviewLighting();

            previewTexture = RenderVariantPreviewToTexture2D();
            if (previewTexture == null)
            {
                return false;
            }

            return true;
        }
        finally
        {
            if (instance != null)
            {
                DestroyPreviewTempObject(instance);
            }
        }
    }

    private static Transform ResolvePropPreviewTargetTransform(Transform propRoot)
    {
        if (propRoot == null)
        {
            return null;
        }

        for (int i = 0; i < propRoot.childCount; i++)
        {
            Transform child = propRoot.GetChild(i);
            if (HasRenderableDescendants(child))
            {
                return child;
            }
        }

        return HasRenderableDescendants(propRoot) ? propRoot : (propRoot.childCount > 0 ? propRoot.GetChild(0) : propRoot);
    }

    private static bool HasRenderableDescendants(Transform root)
    {
        if (root == null)
        {
            return false;
        }

        Renderer[] renderers = root.GetComponentsInChildren<Renderer>(true);
        for (int i = 0; i < renderers.Length; i++)
        {
            Renderer renderer = renderers[i];
            if (renderer is SkinnedMeshRenderer || renderer is MeshRenderer)
            {
                return true;
            }
        }

        return false;
    }

    private void ApplyRandomPropForSelectedRegion()
    {
        if (!IsPropsRegionSelectionMode())
        {
            ApplyRandomToSelectedRegion();
            return;
        }

        List<PropVariantEntry> availableProps = GetFilteredPropVariantEntriesForCurrentCategory();
        if (availableProps.Count == 0)
        {
            ApplyNoPropSelection();
            return;
        }

        PropVariantEntry selectedEntry = PickRandomPropVariant(availableProps);
        if (selectedEntry == null)
        {
            ApplyNoPropSelection();
            return;
        }

        ApplyPropVariantSelection(selectedEntry);
    }

    private void ApplyRandomSingleProp()
    {
        if (customizer == null)
        {
            return;
        }

        List<PropVariantEntry> availableProps = GetFilteredPropVariantEntriesForCurrentCategory();
        if (availableProps == null || availableProps.Count == 0)
        {
            selectedPropRigName = string.Empty;
            ClearAllPropsFromCharacter();
            return;
        }

        PropVariantEntry selectedEntry = PickRandomPropVariant(availableProps);
        if (selectedEntry == null
            || !TryFindPropRigTransform(selectedEntry.rigName, out Transform rigTransform)
            || rigTransform == null)
        {
            selectedPropRigName = string.Empty;
            ClearAllPropsFromCharacter();
            return;
        }

        ClearAllPropsFromCharacter();

        GameObject instance = Instantiate(selectedEntry.sourcePrefab, rigTransform, false);
        if (instance != null)
        {
            instance.name = StripUnityCloneSuffix(selectedEntry.sourcePrefab.name);
            StripUnityCloneSuffixesRecursively(instance.transform);
            SetPropSourceAssetPath(instance, selectedEntry.assetPath);
        }

        selectedPropRigName = rigTransform.name;
    }

    private PropVariantEntry PickRandomPropVariant(List<PropVariantEntry> availableProps)
    {
        if (availableProps == null || availableProps.Count == 0)
        {
            return null;
        }

        List<PropVariantEntry> validEntries = new List<PropVariantEntry>();
        List<PropVariantEntry> alternateEntries = new List<PropVariantEntry>();
        for (int i = 0; i < availableProps.Count; i++)
        {
            PropVariantEntry entry = availableProps[i];
            if (entry == null
                || entry.sourcePrefab == null
                || string.IsNullOrWhiteSpace(entry.rigName)
                || !TryFindPropRigTransform(entry.rigName, out Transform rigTransform)
                || rigTransform == null)
            {
                continue;
            }

            validEntries.Add(entry);
            if (!IsPropSelectedForRig(entry.rigName, entry.prefabName, entry.assetPath))
            {
                alternateEntries.Add(entry);
            }
        }

        List<PropVariantEntry> candidates = alternateEntries.Count > 0 ? alternateEntries : validEntries;
        if (candidates.Count == 0)
        {
            return null;
        }

        Dictionary<string, List<PropVariantEntry>> byRig = new Dictionary<string, List<PropVariantEntry>>(StringComparer.OrdinalIgnoreCase);
        for (int i = 0; i < candidates.Count; i++)
        {
            PropVariantEntry entry = candidates[i];
            string rigName = NormalizeCategoryName(entry.rigName);
            if (string.IsNullOrWhiteSpace(rigName))
            {
                continue;
            }

            if (!byRig.TryGetValue(rigName, out List<PropVariantEntry> rigEntries))
            {
                rigEntries = new List<PropVariantEntry>();
                byRig[rigName] = rigEntries;
            }

            rigEntries.Add(entry);
        }

        if (byRig.Count == 0)
        {
            return candidates[UnityEngine.Random.Range(0, candidates.Count)];
        }

        List<string> rigNames = new List<string>(byRig.Keys);
        string avoidRigName = !string.IsNullOrWhiteSpace(selectedPropRigName) && HasEquippedPropForRig(selectedPropRigName)
            ? NormalizeCategoryName(selectedPropRigName)
            : string.Empty;
        string selectedRigName = PickRandomStringFromBag("prop-rig", rigNames, avoidRigName);
        List<PropVariantEntry> selectedRigEntries = byRig[selectedRigName];

        Dictionary<string, List<PropVariantEntry>> byCategory = new Dictionary<string, List<PropVariantEntry>>(StringComparer.OrdinalIgnoreCase);
        for (int i = 0; i < selectedRigEntries.Count; i++)
        {
            PropVariantEntry entry = selectedRigEntries[i];
            string categoryName = NormalizeCategoryName(entry.categoryName);
            if (string.IsNullOrWhiteSpace(categoryName) || IsNonSelectableCategoryName(categoryName))
            {
                categoryName = CategoryDefaultOptionLabel;
            }

            if (!byCategory.TryGetValue(categoryName, out List<PropVariantEntry> categoryEntries))
            {
                categoryEntries = new List<PropVariantEntry>();
                byCategory[categoryName] = categoryEntries;
            }

            categoryEntries.Add(entry);
        }

        if (byCategory.Count == 0)
        {
            return selectedRigEntries[UnityEngine.Random.Range(0, selectedRigEntries.Count)];
        }

        List<string> categoryNames = new List<string>(byCategory.Keys);
        string selectedCategoryName = PickRandomStringFromBag($"prop-category:{selectedRigName}", categoryNames);
        List<PropVariantEntry> selectedCategoryEntries = byCategory[selectedCategoryName];
        List<string> entryIds = new List<string>();
        for (int i = 0; i < selectedCategoryEntries.Count; i++)
        {
            string id = GetPropVariantRandomId(selectedCategoryEntries[i]);
            if (!string.IsNullOrWhiteSpace(id) && !StringListContains(entryIds, id))
            {
                entryIds.Add(id);
            }
        }

        if (entryIds.Count == 0)
        {
            return selectedCategoryEntries[UnityEngine.Random.Range(0, selectedCategoryEntries.Count)];
        }

        string selectedEntryId = PickRandomStringFromBag($"prop-entry:{selectedRigName}:{selectedCategoryName}", entryIds);
        return FindPropVariantByRandomId(selectedCategoryEntries, selectedEntryId)
               ?? selectedCategoryEntries[UnityEngine.Random.Range(0, selectedCategoryEntries.Count)];
    }

    private static string GetPropVariantRandomId(PropVariantEntry entry)
    {
        if (entry == null)
        {
            return string.Empty;
        }

        string assetPath = NormalizeCategoryAssetPath(entry.assetPath);
        if (!string.IsNullOrWhiteSpace(assetPath))
        {
            return assetPath;
        }

        return $"{NormalizeCategoryName(entry.categoryName)}|{entry.rigName}|{entry.prefabName}|{entry.propIndex}";
    }

    private static PropVariantEntry FindPropVariantByRandomId(List<PropVariantEntry> entries, string id)
    {
        if (entries == null || string.IsNullOrWhiteSpace(id))
        {
            return null;
        }

        for (int i = 0; i < entries.Count; i++)
        {
            PropVariantEntry entry = entries[i];
            if (string.Equals(GetPropVariantRandomId(entry), id, StringComparison.OrdinalIgnoreCase))
            {
                return entry;
            }
        }

        return null;
    }

    private void ApplyNoPropSelection()
    {
        if (customizer == null)
        {
            return;
        }

        RecordUndoSnapshotIfNeeded();
        selectedPropRigName = string.Empty;
        ClearAllPropsFromCharacter();
        RefreshAfterPropApplication();
    }

    private void ApplyPropVariantSelection(PropVariantEntry entry)
    {
        if (customizer == null || entry == null || entry.sourcePrefab == null || string.IsNullOrWhiteSpace(entry.rigName))
        {
            return;
        }

        if (!TryFindPropRigTransform(entry.rigName, out Transform rigTransform) || rigTransform == null)
        {
            return;
        }

        RecordUndoSnapshotIfNeeded();
        // Clicking an already-selected prop toggles it off.
        bool togglingOffCurrentProp = IsPropSelectedForRig(entry.rigName, entry.prefabName, entry.assetPath);
        if (togglingOffCurrentProp)
        {
            selectedPropRigName = string.Empty;
            ClearAllPropsFromCharacter();
            RefreshAfterPropApplication();
            return;
        }

        selectedPropRigName = entry.rigName;
        ClearAllPropsFromCharacter();
        GameObject instance = Instantiate(entry.sourcePrefab, rigTransform, false);
        if (instance != null)
        {
            instance.name = StripUnityCloneSuffix(entry.sourcePrefab.name);
            StripUnityCloneSuffixesRecursively(instance.transform);
            SetPropSourceAssetPath(instance, entry.assetPath);
        }

        RefreshAfterPropApplication();
    }

    private void ClearAllPropsFromCharacter()
    {
        if (customizer == null)
        {
            return;
        }

        Transform[] transforms = customizer.GetComponentsInChildren<Transform>(true);
        List<GameObject> toDestroy = new List<GameObject>();
        for (int i = 0; i < transforms.Length; i++)
        {
            Transform current = transforms[i];
            if (current == null)
            {
                continue;
            }

            for (int childIndex = 0; childIndex < current.childCount; childIndex++)
            {
                Transform child = current.GetChild(childIndex);
                if (child != null && IsPropInstanceName(child.name))
                {
                    toDestroy.Add(child.gameObject);
                }
            }
        }

        for (int i = 0; i < toDestroy.Count; i++)
        {
            GameObject target = toDestroy[i];
            if (target == null)
            {
                continue;
            }

            if (target.activeSelf)
            {
                target.SetActive(false);
            }

            if (Application.isPlaying)
            {
                Destroy(target);
            }
            else
            {
                DestroyImmediate(target);
            }
        }
    }

    private static string CopyPropInstancesBetweenCustomizers(
        MinimoCharacterCustomizer sourceCustomizer,
        MinimoCharacterCustomizer targetCustomizer)
    {
        if (sourceCustomizer == null || targetCustomizer == null)
        {
            return string.Empty;
        }

        return CopyPropInstancesFromRoot(sourceCustomizer.transform, targetCustomizer);
    }

    private static string CopyPropInstancesFromRoot(
        Transform sourceRoot,
        MinimoCharacterCustomizer targetCustomizer)
    {
        if (sourceRoot == null || targetCustomizer == null)
        {
            return string.Empty;
        }

        ClearAllPropsFromCharacter(targetCustomizer);

        Transform targetRoot = targetCustomizer.transform;
        if (targetRoot == null)
        {
            return string.Empty;
        }

        string firstRigName = string.Empty;
        Transform[] sourceTransforms = sourceRoot.GetComponentsInChildren<Transform>(true);
        for (int i = 0; i < sourceTransforms.Length; i++)
        {
            Transform sourceRig = sourceTransforms[i];
            if (sourceRig == null)
            {
                continue;
            }

            bool hasPropChild = false;
            for (int childIndex = 0; childIndex < sourceRig.childCount; childIndex++)
            {
                Transform sourceChild = sourceRig.GetChild(childIndex);
                if (sourceChild != null && IsPropInstanceName(sourceChild.name))
                {
                    hasPropChild = true;
                    break;
                }
            }

            if (!hasPropChild)
            {
                continue;
            }

            Transform targetRig = FindDescendantTransformByName(targetRoot, sourceRig.name);
            if (targetRig == null)
            {
                string normalizedRigName = NormalizeBodyRegionKey(sourceRig.name);
                targetRig = FindDescendantTransformByNormalizedName(targetRoot, normalizedRigName);
            }

            if (targetRig == null)
            {
                continue;
            }

            if (string.IsNullOrWhiteSpace(firstRigName))
            {
                firstRigName = targetRig.name;
            }

            for (int childIndex = 0; childIndex < sourceRig.childCount; childIndex++)
            {
                Transform sourcePropRoot = sourceRig.GetChild(childIndex);
                if (sourcePropRoot == null || !IsPropInstanceName(sourcePropRoot.name))
                {
                    continue;
                }

                GameObject propClone = Instantiate(sourcePropRoot.gameObject, targetRig, false);
                if (propClone == null)
                {
                    continue;
                }

                propClone.name = StripUnityCloneSuffix(sourcePropRoot.name);
                StripUnityCloneSuffixesRecursively(propClone.transform);
                CopyPropSourceAssetPath(sourcePropRoot.gameObject, propClone);
                Transform propCloneTransform = propClone.transform;
                propCloneTransform.localPosition = sourcePropRoot.localPosition;
                propCloneTransform.localRotation = sourcePropRoot.localRotation;
                propCloneTransform.localScale = sourcePropRoot.localScale;
                propClone.SetActive(sourcePropRoot.gameObject.activeSelf);

                // Root only determines which prop is equipped and where it sits on rig.
                // Visual tuning data (child transform/material state) is copied separately.
                CopyPropChildHierarchyState(sourcePropRoot, propCloneTransform);
                CopyRendererStateBetweenPropInstances(sourcePropRoot, propCloneTransform);
            }
        }

        return firstRigName;
    }

    private static void ClearAllPropsFromCharacter(MinimoCharacterCustomizer targetCustomizer)
    {
        if (targetCustomizer == null)
        {
            return;
        }

        Transform[] transforms = targetCustomizer.GetComponentsInChildren<Transform>(true);
        List<GameObject> toDestroy = new List<GameObject>();
        for (int i = 0; i < transforms.Length; i++)
        {
            Transform current = transforms[i];
            if (current == null)
            {
                continue;
            }

            for (int childIndex = 0; childIndex < current.childCount; childIndex++)
            {
                Transform child = current.GetChild(childIndex);
                if (child != null && IsPropInstanceName(child.name))
                {
                    toDestroy.Add(child.gameObject);
                }
            }
        }

        for (int i = 0; i < toDestroy.Count; i++)
        {
            GameObject target = toDestroy[i];
            if (target == null)
            {
                continue;
            }

            if (target.activeSelf)
            {
                target.SetActive(false);
            }

            if (Application.isPlaying)
            {
                target.transform.SetParent(null, false);
                Destroy(target);
            }
            else
            {
                DestroyImmediate(target);
            }
        }
    }

    private static void CopyRendererStateBetweenPropInstances(Transform sourceRoot, Transform targetRoot)
    {
        if (sourceRoot == null || targetRoot == null)
        {
            return;
        }

        Transform sourceVisualRoot = ResolvePropVisualStateRoot(sourceRoot);
        Transform targetVisualRoot = ResolvePropVisualStateRoot(targetRoot);
        if (sourceVisualRoot == null || targetVisualRoot == null)
        {
            return;
        }

        Renderer[] sourceRenderers = sourceVisualRoot.GetComponentsInChildren<Renderer>(true);
        Renderer[] targetRenderers = targetVisualRoot.GetComponentsInChildren<Renderer>(true);
        int rendererCount = Mathf.Min(sourceRenderers.Length, targetRenderers.Length);
        if (rendererCount <= 0)
        {
            return;
        }

        MaterialPropertyBlock block = new MaterialPropertyBlock();
        for (int rendererIndex = 0; rendererIndex < rendererCount; rendererIndex++)
        {
            Renderer sourceRenderer = sourceRenderers[rendererIndex];
            Renderer targetRenderer = targetRenderers[rendererIndex];
            if (sourceRenderer == null || targetRenderer == null)
            {
                continue;
            }

            targetRenderer.enabled = sourceRenderer.enabled;
            targetRenderer.shadowCastingMode = sourceRenderer.shadowCastingMode;
            targetRenderer.receiveShadows = sourceRenderer.receiveShadows;

            Material[] sourceSharedMaterials = sourceRenderer.sharedMaterials;
            Material[] sourceRuntimeMaterials = GetSafeSourceRuntimeMaterials(sourceRenderer);

            if (sourceSharedMaterials != null)
            {
                Material[] targetSharedMaterials = new Material[sourceSharedMaterials.Length];
                for (int materialIndex = 0; materialIndex < sourceSharedMaterials.Length; materialIndex++)
                {
                    targetSharedMaterials[materialIndex] = sourceSharedMaterials[materialIndex];
                }

                targetRenderer.sharedMaterials = targetSharedMaterials;
            }

            int runtimeCount = sourceRuntimeMaterials != null ? sourceRuntimeMaterials.Length : 0;
            int sharedCount = sourceSharedMaterials != null ? sourceSharedMaterials.Length : 0;
            int materialCount = Mathf.Max(runtimeCount, sharedCount);
            if (materialCount > 0)
            {
                Material[] targetRuntimeMaterials = new Material[materialCount];
                for (int materialIndex = 0; materialIndex < materialCount; materialIndex++)
                {
                    Material authoredMaterial = materialIndex < sharedCount
                        ? sourceSharedMaterials[materialIndex]
                        : null;
                    Material runtimeMaterial = materialIndex < runtimeCount
                        ? sourceRuntimeMaterials[materialIndex]
                        : null;
                    Material baseMaterial = authoredMaterial != null ? authoredMaterial : runtimeMaterial;
                    if (baseMaterial == null)
                    {
                        targetRuntimeMaterials[materialIndex] = null;
                        continue;
                    }

                    Material clonedMaterial = new Material(baseMaterial);
                    if (runtimeMaterial != null)
                    {
                        clonedMaterial.CopyPropertiesFromMaterial(runtimeMaterial);
                    }

                    targetRuntimeMaterials[materialIndex] = clonedMaterial;
                }

                targetRenderer.materials = targetRuntimeMaterials;
            }

            int sourceSharedCount = sourceRenderer.sharedMaterials != null ? sourceRenderer.sharedMaterials.Length : 0;
            for (int materialIndex = 0; materialIndex < sourceSharedCount; materialIndex++)
            {
                block.Clear();
                sourceRenderer.GetPropertyBlock(block, materialIndex);
                if (block.isEmpty)
                {
                    targetRenderer.SetPropertyBlock(null, materialIndex);
                }
                else
                {
                    targetRenderer.SetPropertyBlock(block, materialIndex);
                }
            }
        }
    }

    private static Transform ResolvePropVisualStateRoot(Transform propRoot)
    {
        if (propRoot == null)
        {
            return null;
        }

        return propRoot.childCount > 0 ? propRoot.GetChild(0) : propRoot;
    }

    private static void CopyPropChildHierarchyState(Transform sourcePropRoot, Transform targetPropRoot)
    {
        if (sourcePropRoot == null || targetPropRoot == null)
        {
            return;
        }

        int childCount = Math.Min(sourcePropRoot.childCount, targetPropRoot.childCount);
        for (int i = 0; i < childCount; i++)
        {
            Transform sourceChild = sourcePropRoot.GetChild(i);
            Transform targetChild = targetPropRoot.GetChild(i);
            CopyTransformHierarchyStateRecursive(sourceChild, targetChild);
        }
    }

    private static void CopyTransformHierarchyStateRecursive(Transform source, Transform target)
    {
        if (source == null || target == null)
        {
            return;
        }

        target.localPosition = source.localPosition;
        target.localRotation = source.localRotation;
        target.localScale = source.localScale;
        target.gameObject.SetActive(source.gameObject.activeSelf);

        int childCount = Math.Min(source.childCount, target.childCount);
        for (int i = 0; i < childCount; i++)
        {
            CopyTransformHierarchyStateRecursive(source.GetChild(i), target.GetChild(i));
        }
    }

    private static Material[] GetSafeSourceRuntimeMaterials(Renderer renderer)
    {
        if (renderer == null)
        {
            return Array.Empty<Material>();
        }

        GameObject rendererObject = renderer.gameObject;
        bool canAccessInstanceMaterials = rendererObject != null
            && rendererObject.scene.IsValid()
            && rendererObject.scene.isLoaded;
        if (canAccessInstanceMaterials)
        {
            try
            {
                Material[] runtimeMaterials = renderer.materials;
                if (runtimeMaterials != null)
                {
                    return runtimeMaterials;
                }
            }
            catch
            {
                // Accessing .materials on prefab assets throws in editor.
            }
        }

        return renderer.sharedMaterials ?? Array.Empty<Material>();
    }

    private bool TryFindPropRigTransform(string rigName, out Transform rigTransform)
    {
        rigTransform = null;
        if (customizer == null || string.IsNullOrWhiteSpace(rigName))
        {
            return false;
        }

        rigTransform = FindDescendantTransformByName(customizer.transform, rigName);
        if (rigTransform != null)
        {
            return true;
        }

        string normalizedRigName = NormalizeBodyRegionKey(rigName);
        rigTransform = FindDescendantTransformByNormalizedName(customizer.transform, normalizedRigName);
        return rigTransform != null;
    }

    private static Transform FindDescendantTransformByName(Transform root, string name)
    {
        if (root == null || string.IsNullOrWhiteSpace(name))
        {
            return null;
        }

        Transform[] descendants = root.GetComponentsInChildren<Transform>(true);
        for (int i = 0; i < descendants.Length; i++)
        {
            Transform candidate = descendants[i];
            if (candidate != null && string.Equals(candidate.name, name, StringComparison.OrdinalIgnoreCase))
            {
                return candidate;
            }
        }

        return null;
    }

    private static Transform FindDescendantTransformByNormalizedName(Transform root, string normalizedName)
    {
        if (root == null || string.IsNullOrWhiteSpace(normalizedName))
        {
            return null;
        }

        Transform[] descendants = root.GetComponentsInChildren<Transform>(true);
        for (int i = 0; i < descendants.Length; i++)
        {
            Transform candidate = descendants[i];
            if (candidate == null)
            {
                continue;
            }

            string candidateName = NormalizeBodyRegionKey(candidate.name);
            if (string.Equals(candidateName, normalizedName, StringComparison.OrdinalIgnoreCase))
            {
                return candidate;
            }
        }

        return null;
    }

    private static bool IsPropInstanceName(string objectName)
    {
        return !string.IsNullOrWhiteSpace(objectName)
               && objectName.IndexOf("_prop-", StringComparison.OrdinalIgnoreCase) >= 0;
    }

    private static void SetPropSourceAssetPath(GameObject propRoot, string assetPath)
    {
        if (propRoot == null)
        {
            return;
        }

        string normalizedAssetPath = NormalizeCategoryAssetPath(assetPath);
        if (string.IsNullOrWhiteSpace(normalizedAssetPath))
        {
            return;
        }

        MinimoPropSourceAssetPath sourcePath = propRoot.GetComponent<MinimoPropSourceAssetPath>();
        if (sourcePath == null)
        {
            sourcePath = propRoot.AddComponent<MinimoPropSourceAssetPath>();
        }

        sourcePath.AssetPath = normalizedAssetPath;
    }

    private static void CopyPropSourceAssetPath(GameObject sourcePropRoot, GameObject targetPropRoot)
    {
        if (targetPropRoot == null)
        {
            return;
        }

        if (sourcePropRoot != null && TryGetPropSourceAssetPath(sourcePropRoot, out string sourceAssetPath))
        {
            SetPropSourceAssetPath(targetPropRoot, sourceAssetPath);
        }
    }

    private static bool TryGetPropSourceAssetPath(GameObject propRoot, out string assetPath)
    {
        assetPath = string.Empty;
        if (propRoot == null)
        {
            return false;
        }

        MinimoPropSourceAssetPath sourcePath = propRoot.GetComponent<MinimoPropSourceAssetPath>();
        if (sourcePath != null && !string.IsNullOrWhiteSpace(sourcePath.AssetPath))
        {
            assetPath = NormalizeCategoryAssetPath(sourcePath.AssetPath);
            return !string.IsNullOrWhiteSpace(assetPath);
        }

#if UNITY_EDITOR
        UnityEngine.Object sourceObject = PrefabUtility.GetCorrespondingObjectFromSource(propRoot);
        string sourceAssetPath = AssetDatabase.GetAssetPath(sourceObject);
        if (!string.IsNullOrWhiteSpace(sourceAssetPath))
        {
            assetPath = NormalizeCategoryAssetPath(sourceAssetPath);
            return !string.IsNullOrWhiteSpace(assetPath);
        }
#endif

        return false;
    }

    private bool IsPropButtonSelected(VariantButtonEntry entry)
    {
        if (entry == null || !entry.isPropButton)
        {
            return false;
        }

        if (entry.isPropEmptyButton)
        {
            return !HasAnyEquippedProps();
        }

        if (string.IsNullOrWhiteSpace(entry.propRigName) || string.IsNullOrWhiteSpace(entry.propPrefabName))
        {
            return false;
        }

        if (!IsPropEquippedForRig(entry.propRigName, entry.propPrefabName, entry.propAssetPath))
        {
            return false;
        }

        string outlineGroupKey = ResolvePropOutlineGroupKey(entry.propRigName);
        string preferredRigName = ResolvePreferredPropRigNameForOutlineGroup(outlineGroupKey);
        if (!string.IsNullOrWhiteSpace(preferredRigName))
        {
            return string.Equals(preferredRigName, entry.propRigName, StringComparison.OrdinalIgnoreCase);
        }

        return IsFirstEquippedPropButtonInOutlineGroup(entry, outlineGroupKey);
    }

    private string ResolvePreferredPropRigNameForOutlineGroup(string outlineGroupKey)
    {
        if (string.IsNullOrWhiteSpace(selectedPropRigName)
            || string.IsNullOrWhiteSpace(outlineGroupKey)
            || !string.Equals(
                ResolvePropOutlineGroupKey(selectedPropRigName),
                outlineGroupKey,
                StringComparison.OrdinalIgnoreCase)
            || !HasEquippedPropForRig(selectedPropRigName))
        {
            return string.Empty;
        }

        return selectedPropRigName;
    }

    private bool IsFirstEquippedPropButtonInOutlineGroup(VariantButtonEntry targetEntry, string outlineGroupKey)
    {
        if (targetEntry == null || string.IsNullOrWhiteSpace(outlineGroupKey))
        {
            return false;
        }

        for (int i = 0; i < variantButtons.Count; i++)
        {
            VariantButtonEntry entry = variantButtons[i];
            if (entry == null
                || !entry.isPropButton
                || entry.isPropEmptyButton
                || string.IsNullOrWhiteSpace(entry.propRigName)
                || string.IsNullOrWhiteSpace(entry.propPrefabName)
                || !string.Equals(
                    ResolvePropOutlineGroupKey(entry.propRigName),
                    outlineGroupKey,
                    StringComparison.OrdinalIgnoreCase)
                || !IsPropEquippedForRig(entry.propRigName, entry.propPrefabName, entry.propAssetPath))
            {
                continue;
            }

            return ReferenceEquals(entry, targetEntry);
        }

        return false;
    }

    private static string ResolvePropOutlineGroupKey(string rigName)
    {
        string normalized = NormalizeVisualSignatureToken(rigName);
        if (string.IsNullOrWhiteSpace(normalized))
        {
            return string.Empty;
        }

        if (normalized.IndexOf("HEAD", StringComparison.OrdinalIgnoreCase) >= 0
            || normalized.IndexOf("FACE", StringComparison.OrdinalIgnoreCase) >= 0
            || normalized.IndexOf("EYE", StringComparison.OrdinalIgnoreCase) >= 0)
        {
            return PropOutlineFaceGroupKey;
        }

        if (normalized.IndexOf("HAND", StringComparison.OrdinalIgnoreCase) >= 0
            || normalized.IndexOf("ARM", StringComparison.OrdinalIgnoreCase) >= 0)
        {
            return PropOutlineHandGroupKey;
        }

        return normalized;
    }

    private bool TryEnsureSelectedPropRigName()
    {
        if (!string.IsNullOrWhiteSpace(selectedPropRigName)
            && TryFindPropRigTransform(selectedPropRigName, out Transform selectedRig)
            && selectedRig != null
            && FindFirstPropChild(selectedRig) != null)
        {
            return true;
        }

        selectedPropRigName = string.Empty;
        return TryGetSelectedPropInstance(out _);
    }

    private bool IsPropSelectedForRig(string rigName, string prefabName, string assetPath = null)
    {
        if (string.IsNullOrWhiteSpace(rigName) || string.IsNullOrWhiteSpace(prefabName))
        {
            return false;
        }

        if (string.IsNullOrWhiteSpace(rigName)
            || !TryFindPropRigTransform(rigName, out Transform rigTransform)
            || rigTransform == null)
        {
            return false;
        }

        Transform selectedProp = FindFirstPropChild(rigTransform);
        return IsPropInstanceMatch(selectedProp, prefabName, assetPath);
    }

    private bool TryGetSelectedPropPrefabNameForRig(string rigName, out string prefabName)
    {
        prefabName = string.Empty;
        if (string.IsNullOrWhiteSpace(rigName)
            || !TryFindPropRigTransform(rigName, out Transform rigTransform)
            || rigTransform == null)
        {
            return false;
        }

        Transform selectedProp = FindFirstPropChild(rigTransform);
        if (selectedProp == null || string.IsNullOrWhiteSpace(selectedProp.name))
        {
            return false;
        }

        prefabName = selectedProp.name.Trim();
        return !string.IsNullOrWhiteSpace(prefabName);
    }

    private bool HasAnyEquippedProps()
    {
        if (customizer == null)
        {
            return false;
        }

        Transform[] transforms = customizer.GetComponentsInChildren<Transform>(true);
        for (int i = 0; i < transforms.Length; i++)
        {
            Transform current = transforms[i];
            if (current == null)
            {
                continue;
            }

            for (int childIndex = 0; childIndex < current.childCount; childIndex++)
            {
                Transform child = current.GetChild(childIndex);
                if (child != null
                    && child.gameObject.activeInHierarchy
                    && IsPropInstanceName(child.name))
                {
                    return true;
                }
            }
        }

        return false;
    }

    private bool HasEquippedPropForRig(string rigName)
    {
        if (string.IsNullOrWhiteSpace(rigName)
            || !TryFindPropRigTransform(rigName, out Transform rigTransform)
            || rigTransform == null)
        {
            return false;
        }

        return FindFirstPropChild(rigTransform) != null;
    }

    private bool IsPropEquippedForRig(string rigName, string prefabName, string assetPath = null)
    {
        if (string.IsNullOrWhiteSpace(rigName)
            || string.IsNullOrWhiteSpace(prefabName)
            || !TryFindPropRigTransform(rigName, out Transform rigTransform)
            || rigTransform == null)
        {
            return false;
        }

        for (int i = 0; i < rigTransform.childCount; i++)
        {
            Transform child = rigTransform.GetChild(i);
            if (IsPropInstanceMatch(child, prefabName, assetPath))
            {
                return true;
            }
        }

        return false;
    }

    private static bool IsPropInstanceMatch(Transform propRoot, string prefabName, string assetPath)
    {
        if (propRoot == null
            || !propRoot.gameObject.activeInHierarchy
            || string.IsNullOrWhiteSpace(prefabName)
            || !IsPropInstanceName(propRoot.name)
            || !string.Equals(propRoot.name, prefabName, StringComparison.OrdinalIgnoreCase))
        {
            return false;
        }

        string expectedAssetPath = NormalizeCategoryAssetPath(assetPath);
        if (!string.IsNullOrWhiteSpace(expectedAssetPath)
            && TryGetPropSourceAssetPath(propRoot.gameObject, out string actualAssetPath))
        {
            return string.Equals(
                NormalizeCategoryAssetPath(actualAssetPath),
                expectedAssetPath,
                StringComparison.OrdinalIgnoreCase);
        }

        return true;
    }

    private List<PropMaterialChannel> BuildColorChannelDescriptorsForSelectedProp()
    {
        List<PropMaterialChannel> channels = new List<PropMaterialChannel>();
        if (!TryGetSelectedPropInstance(out Transform propInstance) || propInstance == null)
        {
            return channels;
        }

        return BuildColorChannelDescriptorsForPropInstance(propInstance);
    }

    private static List<PropMaterialChannel> BuildColorChannelDescriptorsForPropInstance(Transform propInstance)
    {
        List<PropMaterialChannel> channels = new List<PropMaterialChannel>();
        if (propInstance == null)
        {
            return channels;
        }

        Transform visualRoot = ResolvePropVisualStateRoot(propInstance);
        if (visualRoot == null)
        {
            return channels;
        }

        Renderer[] renderers = visualRoot.GetComponentsInChildren<Renderer>(true);
        for (int rendererIndex = 0; rendererIndex < renderers.Length; rendererIndex++)
        {
            Renderer renderer = renderers[rendererIndex];
            if (renderer == null || (!(renderer is MeshRenderer) && !(renderer is SkinnedMeshRenderer)))
            {
                continue;
            }

            Material[] materials = renderer.sharedMaterials;
            if (materials == null || materials.Length == 0)
            {
                continue;
            }

            int materialCount = GetEffectiveRendererMaterialSlotCount(renderer, materials);
            for (int materialIndex = 0; materialIndex < materialCount; materialIndex++)
            {
                Material material = materials[materialIndex];
                if (!MaterialSupportsColor(material))
                {
                    continue;
                }

                string label = BuildPropMaterialChannelLabel(renderer, material, channels.Count);
                channels.Add(new PropMaterialChannel
                {
                    renderer = renderer,
                    materialIndex = materialIndex,
                    label = label
                });
            }
        }

        return channels;
    }

    private bool TryResolvePropColorChannelIndex(
        string rigName,
        Renderer renderer,
        int materialIndex,
        out int colorChannelIndex)
    {
        colorChannelIndex = 0;
        if (customizer == null
            || string.IsNullOrWhiteSpace(rigName)
            || renderer == null
            || materialIndex < 0
            || !TryFindPropRigTransform(rigName, out Transform rigTransform)
            || rigTransform == null)
        {
            return false;
        }

        Transform propRoot = FindFirstPropChild(rigTransform);
        if (propRoot == null)
        {
            return false;
        }

        List<PropMaterialChannel> channels = BuildColorChannelDescriptorsForPropInstance(propRoot);
        for (int i = 0; i < channels.Count; i++)
        {
            PropMaterialChannel channel = channels[i];
            if (channel == null || channel.renderer == null)
            {
                continue;
            }

            if (ReferenceEquals(channel.renderer, renderer) && channel.materialIndex == materialIndex)
            {
                colorChannelIndex = i;
                return true;
            }
        }

        return false;
    }

    private static string BuildPropMaterialChannelLabel(Renderer renderer, Material material, int channelIndex)
    {
        string materialName = material != null
            ? material.name.Replace(" (Instance)", string.Empty).Trim()
            : string.Empty;
        if (string.IsNullOrWhiteSpace(materialName))
        {
            materialName = $"Mat {channelIndex + 1}";
        }

        string rendererName = renderer != null ? renderer.name : string.Empty;
        if (string.IsNullOrWhiteSpace(rendererName))
        {
            return materialName;
        }

        return $"{rendererName} / {materialName}";
    }

    private bool TryGetSelectedPropInstance(out Transform propInstance)
    {
        propInstance = null;
        if (customizer == null)
        {
            return false;
        }

        if (!string.IsNullOrWhiteSpace(selectedPropRigName)
            && TryFindPropRigTransform(selectedPropRigName, out Transform selectedRig)
            && selectedRig != null)
        {
            Transform selectedRigProp = FindFirstPropChild(selectedRig);
            if (selectedRigProp != null)
            {
                propInstance = selectedRigProp;
                return true;
            }
        }

        Transform[] allRigCandidates = customizer.GetComponentsInChildren<Transform>(true);
        for (int i = 0; i < allRigCandidates.Length; i++)
        {
            Transform rig = allRigCandidates[i];
            if (rig == null)
            {
                continue;
            }

            Transform propChild = FindFirstPropChild(rig);
            if (propChild == null)
            {
                continue;
            }

            selectedPropRigName = rig.name;
            propInstance = propChild;
            return true;
        }

        return false;
    }

    private static Transform FindFirstPropChild(Transform rigTransform)
    {
        if (rigTransform == null)
        {
            return null;
        }

        for (int i = rigTransform.childCount - 1; i >= 0; i--)
        {
            Transform child = rigTransform.GetChild(i);
            if (child != null
                && child.gameObject.activeInHierarchy
                && IsPropInstanceName(child.name))
            {
                return child;
            }
        }

        return null;
    }

    private bool TryResolveSelectedPropMaterialChannel(
        int channelIndex,
        out Renderer renderer,
        out int materialIndex)
    {
        renderer = null;
        materialIndex = -1;
        List<PropMaterialChannel> channels = BuildColorChannelDescriptorsForSelectedProp();
        if (channels.Count == 0)
        {
            return false;
        }

        int resolvedChannelIndex = Mathf.Clamp(channelIndex, 0, channels.Count - 1);
        PropMaterialChannel channel = channels[resolvedChannelIndex];
        if (channel == null || channel.renderer == null || channel.materialIndex < 0)
        {
            return false;
        }

        renderer = channel.renderer;
        materialIndex = channel.materialIndex;
        return true;
    }

    private bool TryGetEffectivePropColor(int channelIndex, out Color color)
    {
        color = Color.white;
        if (!TryResolveSelectedPropMaterialChannel(channelIndex, out Renderer renderer, out int materialIndex)
            || renderer == null)
        {
            return false;
        }

        Material[] materials = renderer.materials;
        if (materials == null || materialIndex < 0 || materialIndex >= materials.Length)
        {
            materials = renderer.sharedMaterials;
        }

        if (materials == null || materialIndex < 0 || materialIndex >= materials.Length)
        {
            return false;
        }

        return TryGetMaterialDisplayColor(materials[materialIndex], out color);
    }

    private bool ApplyColorToSelectedPropChannel(Color color)
    {
        if (!TryResolveSelectedPropMaterialChannel(selectedColorMaterialIndex, out Renderer renderer, out int materialIndex)
            || renderer == null)
        {
            return false;
        }

        Material[] materials = renderer.materials;
        bool assignToShared = false;
        if (materials == null || materialIndex < 0 || materialIndex >= materials.Length)
        {
            materials = renderer.sharedMaterials;
            assignToShared = true;
        }

        if (materials == null || materialIndex < 0 || materialIndex >= materials.Length)
        {
            return false;
        }

        Material material = materials[materialIndex];
        if (material == null)
        {
            return false;
        }

        if (!material.HasProperty(ColorShaderProperty)
            && !material.HasProperty(BaseColorShaderProperty)
            && !material.HasProperty(HighlightShaderProperty)
            && !material.HasProperty(ShadowShaderProperty))
        {
            return false;
        }

        RecordUndoSnapshotIfNeeded();
        if (!SetMaterialDisplayColor(material, color))
        {
            return false;
        }

        if (assignToShared)
        {
            renderer.sharedMaterials = materials;
        }
        else
        {
            renderer.materials = materials;
        }

        renderer.SetPropertyBlock(null, materialIndex);
        if (worldPropHoverColorSnapshots.TryGetValue(renderer, out Dictionary<int, HoverMaterialColorSnapshot> snapshots))
        {
            snapshots.Remove(materialIndex);
            if (snapshots.Count == 0)
            {
                worldPropHoverColorSnapshots.Remove(renderer);
            }
        }

        return true;
    }

    private static bool TryGetMaterialDisplayColor(Material material, out Color color)
    {
        color = Color.white;
        if (material == null)
        {
            return false;
        }

        if (material.HasProperty(ColorShaderProperty))
        {
            color = material.GetColor(ColorShaderProperty);
            return true;
        }

        if (material.HasProperty(BaseColorShaderProperty))
        {
            color = material.GetColor(BaseColorShaderProperty);
            return true;
        }

        return false;
    }

    private static bool SetMaterialDisplayColor(Material material, Color color)
    {
        if (material == null)
        {
            return false;
        }

        ResolveMaterialToneRampColors(material, color, out Color highlightColor, out Color shadowColor);

        bool applied = false;
        if (material.HasProperty(ColorShaderProperty))
        {
            material.SetColor(ColorShaderProperty, color);
            applied = true;
        }

        if (material.HasProperty(BaseColorShaderProperty))
        {
            material.SetColor(BaseColorShaderProperty, color);
            applied = true;
        }

        if (material.HasProperty(HighlightShaderProperty))
        {
            material.SetColor(HighlightShaderProperty, highlightColor);
            applied = true;
        }

        if (material.HasProperty(ShadowShaderProperty))
        {
            material.SetColor(ShadowShaderProperty, shadowColor);
            applied = true;
        }

        return applied;
    }

    private static void ResolveMaterialToneRampColors(
        Material material,
        Color targetBaseColor,
        out Color highlightColor,
        out Color shadowColor)
    {
        if (TryResolveToneRampFromMaterialOriginal(material, targetBaseColor, out highlightColor, out shadowColor))
        {
            return;
        }

        highlightColor = DeriveToneColorFromReference(
            targetBaseColor,
            PreviewOtherReferenceBaseColor,
            PreviewOtherReferenceHighlightColor);
        shadowColor = DeriveToneColorFromReference(
            targetBaseColor,
            PreviewOtherReferenceBaseColor,
            PreviewOtherReferenceShadowColor);
    }

    private static bool TryResolveToneRampFromMaterialOriginal(
        Material material,
        Color targetBaseColor,
        out Color highlightColor,
        out Color shadowColor)
    {
        highlightColor = targetBaseColor;
        shadowColor = targetBaseColor;
        if (material == null || !TryGetMaterialBaseColor(material, out Color originalBaseColor))
        {
            return false;
        }

        bool hasOriginalHighlight = TryGetMaterialColor(material, HighlightShaderProperty, out Color originalHighlightColor);
        bool hasOriginalShadow = TryGetMaterialColor(material, ShadowShaderProperty, out Color originalShadowColor);
        if (!hasOriginalHighlight && !hasOriginalShadow)
        {
            return false;
        }

        if (hasOriginalHighlight)
        {
            highlightColor = DeriveToneColorFromReference(
                targetBaseColor,
                originalBaseColor,
                originalHighlightColor,
                preserveToneAlpha: true);
        }

        if (hasOriginalShadow)
        {
            shadowColor = DeriveToneColorFromReference(
                targetBaseColor,
                originalBaseColor,
                originalShadowColor,
                preserveToneAlpha: true);
        }

        return true;
    }

    private static bool TryGetMaterialBaseColor(Material material, out Color baseColor)
    {
        baseColor = Color.white;
        if (material == null)
        {
            return false;
        }

        if (material.HasProperty(ColorShaderProperty))
        {
            baseColor = material.GetColor(ColorShaderProperty);
            return true;
        }

        if (material.HasProperty(BaseColorShaderProperty))
        {
            baseColor = material.GetColor(BaseColorShaderProperty);
            return true;
        }

        return false;
    }

    private static bool TryGetMaterialColor(Material material, int propertyId, out Color color)
    {
        color = Color.white;
        if (material == null || !material.HasProperty(propertyId))
        {
            return false;
        }

        color = material.GetColor(propertyId);
        return true;
    }

    private MinimoCharacterCustomizer.PartSlot? ResolvePreferredPreviewSlotForVariantButtons(
        MinimoCharacterCustomizer.PartSlot[] selectedSlots)
    {
        if (selectedSlots == null || selectedSlots.Length == 0)
        {
            return null;
        }

        if (selectedWorldPreviewTargetSlot.HasValue
            && SlotArrayContains(selectedSlots, selectedWorldPreviewTargetSlot.Value))
        {
            return selectedWorldPreviewTargetSlot.Value;
        }

        if (selectedWorldColorTargetSlot.HasValue
            && SlotArrayContains(selectedSlots, selectedWorldColorTargetSlot.Value))
        {
            return selectedWorldColorTargetSlot.Value;
        }

        if (TryResolveRightSlotForMirroredRegion(selectedSlots, out MinimoCharacterCustomizer.PartSlot mirroredRightSlot))
        {
            return mirroredRightSlot;
        }

        return selectedSlots[0];
    }

    private bool TryResolveMirroredSlotsForRegion(
        MinimoCharacterCustomizer.PartSlot[] slots,
        out MinimoCharacterCustomizer.PartSlot leftSlot,
        out MinimoCharacterCustomizer.PartSlot rightSlot)
    {
        leftSlot = default;
        rightSlot = default;
        if (slots == null || slots.Length == 0)
        {
            return false;
        }

        if (ContainsLeftAndRightSlotPair(
                slots,
                MinimoCharacterCustomizer.PartSlot.ShoulderLeft,
                MinimoCharacterCustomizer.PartSlot.ShoulderRight))
        {
            leftSlot = MinimoCharacterCustomizer.PartSlot.ShoulderLeft;
            rightSlot = MinimoCharacterCustomizer.PartSlot.ShoulderRight;
            return true;
        }

        if (ContainsLeftAndRightSlotPair(
                slots,
                MinimoCharacterCustomizer.PartSlot.ArmLeft,
                MinimoCharacterCustomizer.PartSlot.ArmRight))
        {
            leftSlot = MinimoCharacterCustomizer.PartSlot.ArmLeft;
            rightSlot = MinimoCharacterCustomizer.PartSlot.ArmRight;
            return true;
        }

        if (ContainsLeftAndRightSlotPair(
                slots,
                MinimoCharacterCustomizer.PartSlot.HandLeft,
                MinimoCharacterCustomizer.PartSlot.HandRight))
        {
            leftSlot = MinimoCharacterCustomizer.PartSlot.HandLeft;
            rightSlot = MinimoCharacterCustomizer.PartSlot.HandRight;
            return true;
        }

        if (ContainsLeftAndRightSlotPair(
                slots,
                MinimoCharacterCustomizer.PartSlot.LegUpperLeft,
                MinimoCharacterCustomizer.PartSlot.LegUpperRight))
        {
            leftSlot = MinimoCharacterCustomizer.PartSlot.LegUpperLeft;
            rightSlot = MinimoCharacterCustomizer.PartSlot.LegUpperRight;
            return true;
        }

        if (ContainsLeftAndRightSlotPair(
                slots,
                MinimoCharacterCustomizer.PartSlot.BootsLeft,
                MinimoCharacterCustomizer.PartSlot.BootsRight))
        {
            leftSlot = MinimoCharacterCustomizer.PartSlot.BootsLeft;
            rightSlot = MinimoCharacterCustomizer.PartSlot.BootsRight;
            return true;
        }

        return false;
    }

    private void AddRandomVariantButton(Font font, bool faceTextureMode, bool propsMode)
    {
        if (bodyPartsContent == null)
        {
            return;
        }

        Button randomButton = CreateVariantButton(
            bodyPartsContent,
            font,
            string.Empty,
            -1,
            RuntimePartButtonTemplateKind.Random);
        ApplyVariantButtonVisualStyle(randomButton);
        EnsureShadowPressTracking(randomButton);
        randomButton.gameObject.name = "Part_Random";
        ApplyRandomVariantButtonIcon(randomButton);

        ApplyVariantCategoryBorder(randomButton, string.Empty, isRandom: true);
        if (faceTextureMode)
        {
            randomButton.onClick.AddListener(ApplyRandomFaceTextureSet);
        }
        else if (propsMode)
        {
            randomButton.onClick.AddListener(ApplyRandomPropForSelectedRegion);
        }
        else
        {
            randomButton.onClick.AddListener(ApplyRandomToSelectedRegion);
        }

        variantButtons.Add(new VariantButtonEntry
        {
            variantIndex = -1,
            isRandomButton = true,
            isFaceTextureButton = false,
            isPropButton = false,
            isPropEmptyButton = false,
            propCategoryName = string.Empty,
            propRigName = string.Empty,
            propPrefabName = string.Empty,
            propAssetPath = string.Empty,
            button = randomButton,
            background = randomButton.targetGraphic as Image
        });
    }

    private void AddEmptyPropButton(Font font)
    {
        if (bodyPartsContent == null)
        {
            return;
        }

        Button emptyButton = CreateVariantButton(
            bodyPartsContent,
            font,
            string.Empty,
            -1,
            RuntimePartButtonTemplateKind.Empty);
        EnsureShadowPressTracking(emptyButton);
        emptyButton.gameObject.name = "Part_Prop_Empty";
        HideButtonLabel(emptyButton);
        HideAllButtonLabels(emptyButton);
        ApplyVariantCategoryBorder(emptyButton, string.Empty, isRandom: false);
        ApplyEmptyVariantButtonIcon(emptyButton);
        emptyButton.onClick.AddListener(ApplyNoPropSelection);

        variantButtons.Add(new VariantButtonEntry
        {
            variantIndex = -1,
            isRandomButton = false,
            isFaceTextureButton = false,
            isPropButton = true,
            isPropEmptyButton = true,
            propCategoryName = string.Empty,
            propRigName = string.Empty,
            propPrefabName = string.Empty,
            propAssetPath = string.Empty,
            button = emptyButton,
            background = emptyButton.targetGraphic as Image
        });
    }

    private void CacheRandomVariantIconStyle()
    {
        hasCachedVariantRandomIconStyle = false;
        cachedVariantRandomIconSprite = null;
        cachedVariantRandomIconColor = Color.white;
        cachedVariantRandomIconOffsetMin = new Vector2(12f, 12f);
        cachedVariantRandomIconOffsetMax = new Vector2(-12f, -12f);

        if (bodyPartsContent != null)
        {
            for (int i = 0; i < bodyPartsContent.childCount; i++)
            {
                Transform child = bodyPartsContent.GetChild(i);
                if (child == null)
                {
                    continue;
                }

                Image[] images = child.GetComponentsInChildren<Image>(true);
                for (int imageIndex = 0; imageIndex < images.Length; imageIndex++)
                {
                    Image image = images[imageIndex];
                    if (image == null || image.sprite == null || image.transform == child)
                    {
                        continue;
                    }

                    string name = image.gameObject.name ?? string.Empty;
                    if (name.IndexOf("random", StringComparison.OrdinalIgnoreCase) < 0
                        && !HasAncestorContainingName(image.transform, "random"))
                    {
                        continue;
                    }

                    CacheRandomVariantIconStyleFromImage(image);
                    return;
                }
            }
        }

        Image fallbackIcon = FindChildByName<Image>("RandomIcon");
        if (fallbackIcon != null && fallbackIcon.sprite != null)
        {
            CacheRandomVariantIconStyleFromImage(fallbackIcon);
        }
    }

    private void ApplyRandomVariantButtonIcon(Button randomButton)
    {
        if (randomButton == null)
        {
            return;
        }

        HideButtonLabel(randomButton);
        HideAllButtonLabels(randomButton);

        Image existingIcon = ResolveButtonIconImage(randomButton, "RandomIcon", "Icon");
        if (existingIcon != null)
        {
            if (hasCachedVariantRandomIconStyle && cachedVariantRandomIconSprite != null)
            {
                RectTransform existingRect = existingIcon.transform as RectTransform;
                if (existingRect != null)
                {
                    existingRect.offsetMin = cachedVariantRandomIconOffsetMin;
                    existingRect.offsetMax = cachedVariantRandomIconOffsetMax;
                }

                existingIcon.sprite = cachedVariantRandomIconSprite;
                existingIcon.color = cachedVariantRandomIconColor;
            }

            existingIcon.preserveAspect = true;
            existingIcon.raycastTarget = false;
            existingIcon.gameObject.SetActive(true);
            return;
        }

        if (!hasCachedVariantRandomIconStyle || cachedVariantRandomIconSprite == null)
        {
            return;
        }

        RectTransform iconRect = CreateRect(
            "RandomIcon",
            randomButton.transform,
            new Vector2(0f, 0f),
            new Vector2(1f, 1f),
            new Vector2(0.5f, 0.5f),
            Vector2.zero,
            Vector2.zero);
        iconRect.offsetMin = cachedVariantRandomIconOffsetMin;
        iconRect.offsetMax = cachedVariantRandomIconOffsetMax;

        Image iconImage = iconRect.gameObject.AddComponent<Image>();
        iconImage.sprite = cachedVariantRandomIconSprite;
        iconImage.color = cachedVariantRandomIconColor;
        iconImage.preserveAspect = true;
        iconImage.raycastTarget = false;
    }

    private void ApplyEmptyVariantButtonIcon(Button targetButton)
    {
        if (targetButton == null)
        {
            return;
        }

        HideButtonLabel(targetButton);
        HideAllButtonLabels(targetButton);

        TryAutoAssignEmptyVariantIconSprite();
        Image existingIcon = ResolveButtonIconImage(targetButton, EmptyVariantIconObjectName, "Icon");
        if (existingIcon != null)
        {
            if (emptyVariantIconSprite != null)
            {
                RectTransform existingRect = existingIcon.transform as RectTransform;
                if (existingRect != null)
                {
                    existingRect.offsetMin = new Vector2(EmptyVariantIconPadding, EmptyVariantIconPadding);
                    existingRect.offsetMax = new Vector2(-EmptyVariantIconPadding, -EmptyVariantIconPadding);
                }

                existingIcon.sprite = emptyVariantIconSprite;
                existingIcon.color = ResolveButtonOutlineColor(targetButton, Color.white);
            }

            existingIcon.preserveAspect = true;
            existingIcon.raycastTarget = false;
            existingIcon.gameObject.SetActive(true);
            return;
        }

        if (emptyVariantIconSprite == null)
        {
            return;
        }

        RectTransform iconRect = CreateRect(
            EmptyVariantIconObjectName,
            targetButton.transform,
            new Vector2(0f, 0f),
            new Vector2(1f, 1f),
            new Vector2(0.5f, 0.5f),
            Vector2.zero,
            Vector2.zero);
        iconRect.offsetMin = new Vector2(EmptyVariantIconPadding, EmptyVariantIconPadding);
        iconRect.offsetMax = new Vector2(-EmptyVariantIconPadding, -EmptyVariantIconPadding);

        Image iconImage = iconRect.gameObject.AddComponent<Image>();
        iconImage.sprite = emptyVariantIconSprite;
        iconImage.preserveAspect = true;
        iconImage.raycastTarget = false;
        iconImage.color = ResolveButtonOutlineColor(targetButton, Color.white);
    }

    private static Image ResolveButtonIconImage(Button button, params string[] preferredNames)
    {
        if (button == null)
        {
            return null;
        }

        if (preferredNames != null)
        {
            for (int i = 0; i < preferredNames.Length; i++)
            {
                string preferredName = preferredNames[i];
                if (string.IsNullOrWhiteSpace(preferredName))
                {
                    continue;
                }

                Image namedIcon = FindChildByNameIn<Image>(button.transform, preferredName);
                if (namedIcon != null && namedIcon.transform != button.transform)
                {
                    return namedIcon;
                }
            }
        }

        Image[] images = button.GetComponentsInChildren<Image>(true);
        for (int i = 0; i < images.Length; i++)
        {
            Image image = images[i];
            if (image == null || image.transform == button.transform)
            {
                continue;
            }

            string imageName = image.gameObject.name ?? string.Empty;
            if (imageName.IndexOf("icon", StringComparison.OrdinalIgnoreCase) >= 0
                || imageName.IndexOf("random", StringComparison.OrdinalIgnoreCase) >= 0
                || imageName.IndexOf("empty", StringComparison.OrdinalIgnoreCase) >= 0)
            {
                return image;
            }
        }

        return null;
    }

    private static Color ResolveButtonOutlineColor(Button button, Color fallback)
    {
        if (button == null)
        {
            return fallback;
        }

        Image background = button.targetGraphic as Image;
        background ??= button.GetComponent<Image>();
        if (background == null)
        {
            return fallback;
        }

        Outline outline = background.GetComponent<Outline>();
        return outline != null ? outline.effectColor : fallback;
    }

    private static void SyncEmptyVariantIconColor(Button button, Color color)
    {
        if (button == null)
        {
            return;
        }

        Image iconImage = ResolveButtonIconImage(button, EmptyVariantIconObjectName, "Icon");
        if (iconImage == null)
        {
            return;
        }

        iconImage.color = color;
    }

    private void CacheVariantButtonVisualStyle()
    {
        hasCachedVariantButtonVisualStyle = false;

        Image fallbackImage = null;
        Button fallbackButton = null;

        if (bodyPartsContent != null)
        {
            for (int i = 0; i < bodyPartsContent.childCount; i++)
            {
                Transform child = bodyPartsContent.GetChild(i);
                if (child == null)
                {
                    continue;
                }

                Image image = child.GetComponent<Image>();
                if (image == null || image.sprite == null)
                {
                    continue;
                }

                Button button = child.GetComponent<Button>();
                bool isButtonZero = string.Equals(image.sprite.name, "Button_0", StringComparison.OrdinalIgnoreCase);
                if (isButtonZero)
                {
                    CacheVariantButtonVisualStyleFromSource(image, button);
                    return;
                }

                if (fallbackImage == null)
                {
                    fallbackImage = image;
                    fallbackButton = button;
                }
            }
        }

        if (fallbackImage != null)
        {
            CacheVariantButtonVisualStyleFromSource(fallbackImage, fallbackButton);
            return;
        }

        Image[] sceneImages = MinimoUnityCompatibility.FindObjectsByType<Image>(true);
        for (int i = 0; i < sceneImages.Length; i++)
        {
            Image image = sceneImages[i];
            if (image == null || image.sprite == null)
            {
                continue;
            }

            if (!string.Equals(image.sprite.name, "Button_0", StringComparison.OrdinalIgnoreCase))
            {
                continue;
            }

            CacheVariantButtonVisualStyleFromSource(image, image.GetComponent<Button>());
            return;
        }
    }

    private void CacheVariantButtonVisualStyleFromSource(Image source, Button sourceButton)
    {
        if (source == null || source.sprite == null)
        {
            return;
        }

        cachedVariantButtonVisualStyle.sprite = source.sprite;
        cachedVariantButtonVisualStyle.overrideSprite = source.overrideSprite;
        cachedVariantButtonVisualStyle.type = source.type;
        cachedVariantButtonVisualStyle.fillCenter = source.fillCenter;
        cachedVariantButtonVisualStyle.fillMethod = source.fillMethod;
        cachedVariantButtonVisualStyle.fillAmount = source.fillAmount;
        cachedVariantButtonVisualStyle.fillClockwise = source.fillClockwise;
        cachedVariantButtonVisualStyle.fillOrigin = source.fillOrigin;
        cachedVariantButtonVisualStyle.preserveAspect = source.preserveAspect;
        cachedVariantButtonVisualStyle.pixelsPerUnitMultiplier = source.pixelsPerUnitMultiplier;
        cachedVariantButtonVisualStyle.material = source.material;
        cachedVariantButtonVisualStyle.maskable = source.maskable;
        cachedVariantButtonVisualStyle.raycastTarget = source.raycastTarget;
        cachedVariantButtonVisualStyle.color = source.color;

        if (sourceButton != null)
        {
            cachedVariantButtonVisualStyle.transition = sourceButton.transition;
            cachedVariantButtonVisualStyle.colors = sourceButton.colors;
        }
        else
        {
            cachedVariantButtonVisualStyle.transition = Selectable.Transition.ColorTint;
            cachedVariantButtonVisualStyle.colors = ColorBlock.defaultColorBlock;
        }

        hasCachedVariantButtonVisualStyle = true;
    }

    private void ApplyVariantButtonVisualStyle(Button button)
    {
        if (button == null || !hasCachedVariantButtonVisualStyle)
        {
            return;
        }

        Image image = button.targetGraphic as Image;
        image ??= button.GetComponent<Image>();
        if (image == null)
        {
            return;
        }

        image.sprite = cachedVariantButtonVisualStyle.sprite;
        image.overrideSprite = cachedVariantButtonVisualStyle.overrideSprite;
        image.type = cachedVariantButtonVisualStyle.type;
        image.fillCenter = cachedVariantButtonVisualStyle.fillCenter;
        image.fillMethod = cachedVariantButtonVisualStyle.fillMethod;
        image.fillAmount = cachedVariantButtonVisualStyle.fillAmount;
        image.fillClockwise = cachedVariantButtonVisualStyle.fillClockwise;
        image.fillOrigin = cachedVariantButtonVisualStyle.fillOrigin;
        image.preserveAspect = cachedVariantButtonVisualStyle.preserveAspect;
        image.pixelsPerUnitMultiplier = cachedVariantButtonVisualStyle.pixelsPerUnitMultiplier;
        image.material = cachedVariantButtonVisualStyle.material;
        image.maskable = cachedVariantButtonVisualStyle.maskable;
        image.raycastTarget = cachedVariantButtonVisualStyle.raycastTarget;
        image.color = cachedVariantButtonVisualStyle.color;

        button.targetGraphic = image;
        button.transition = cachedVariantButtonVisualStyle.transition;
        button.colors = cachedVariantButtonVisualStyle.colors;
    }

    private void CacheRandomVariantIconStyleFromImage(Image source)
    {
        if (source == null || source.sprite == null)
        {
            return;
        }

        cachedVariantRandomIconSprite = source.sprite;
        cachedVariantRandomIconColor = source.color;

        RectTransform sourceRect = source.rectTransform;
        if (sourceRect != null)
        {
            cachedVariantRandomIconOffsetMin = sourceRect.offsetMin;
            cachedVariantRandomIconOffsetMax = sourceRect.offsetMax;
        }

        hasCachedVariantRandomIconStyle = true;
    }

    private static bool HasAncestorContainingName(Transform node, string token)
    {
        if (node == null || string.IsNullOrWhiteSpace(token))
        {
            return false;
        }

        Transform current = node;
        while (current != null)
        {
            string name = current.name ?? string.Empty;
            if (name.IndexOf(token, StringComparison.OrdinalIgnoreCase) >= 0)
            {
                return true;
            }

            current = current.parent;
        }

        return false;
    }

    private static bool IsSingleHairSlotSelection(MinimoCharacterCustomizer.PartSlot[] slots)
    {
        return slots != null
               && slots.Length == 1
               && slots[0] == MinimoCharacterCustomizer.PartSlot.Hair;
    }

    private void AddDefaultVariantButton(Font font)
    {
        if (bodyPartsContent == null)
        {
            return;
        }

        Button defaultButton = CreateVariantButton(
            bodyPartsContent,
            font,
            "Default",
            -1,
            RuntimePartButtonTemplateKind.Empty);
        EnsureShadowPressTracking(defaultButton);
        defaultButton.gameObject.name = "Part_Default";
        HideButtonLabel(defaultButton);
        HideAllButtonLabels(defaultButton);
        ApplyVariantCategoryBorder(defaultButton, CategoryDefaultOptionLabel, isRandom: false);
        ApplyEmptyVariantButtonIcon(defaultButton);
        if (IsSingleHairSlotSelection(GetTargetSlotsForVariantButtonPanel()))
        {
            defaultButton.onClick.AddListener(ToggleHairRendererVisibilityFromDefaultButton);
        }
        else
        {
            defaultButton.onClick.AddListener(() => ApplyRegionVariant(-1));
        }
        variantButtons.Add(new VariantButtonEntry
        {
            variantIndex = -1,
            isRandomButton = false,
            isFaceTextureButton = false,
            button = defaultButton,
            background = defaultButton.targetGraphic as Image
        });
    }

    private void ToggleHairRendererVisibilityFromDefaultButton()
    {
        if (customizer == null)
        {
            return;
        }

        RecordUndoSnapshotIfNeeded();
        hairRendererUnlockedByUserSelection = false;
        MinimoCharacterCustomizer.PartSlot[] targetSlots = { MinimoCharacterCustomizer.PartSlot.Hair };
        List<RendererStateSnapshot> protectedRendererState = CaptureRendererStateForFaceHairIsolation(targetSlots);
        customizer.SetPartVariant(MinimoCharacterCustomizer.PartSlot.Hair, -1);
        customizer.ApplyPartSelections(targetSlots);
        SetHairRendererEnabled(false);
        RestoreRendererStateSnapshots(protectedRendererState);

        currentSetIndex = -1;
        RefreshAfterVariantApplication(targetSlots);
    }

    private void SetHairRendererEnabled(bool enabled)
    {
        if (customizer == null)
        {
            return;
        }

        if (enabled
            && customizer.GetPartVariant(MinimoCharacterCustomizer.PartSlot.Hair) < 0
            && !hairRendererUnlockedByUserSelection)
        {
            enabled = false;
        }

        if (customizer.TryGetPartRenderer(MinimoCharacterCustomizer.PartSlot.Hair, out SkinnedMeshRenderer hairRenderer)
            && hairRenderer != null)
        {
            hairRenderer.enabled = enabled;
        }
    }

    private bool HairRendererHasMesh()
    {
        return customizer != null
               && customizer.TryGetPartRenderer(
                   MinimoCharacterCustomizer.PartSlot.Hair,
                   out SkinnedMeshRenderer hairRenderer)
               && hairRenderer != null
               && hairRenderer.sharedMesh != null;
    }

    private string ResolveVariantCategoryNameForSlots(int variantIndex, MinimoCharacterCustomizer.PartSlot[] slots)
    {
        if (variantIndex < 0 || customizer == null || slots == null || slots.Length == 0)
        {
            return string.Empty;
        }

        for (int i = 0; i < slots.Length; i++)
        {
            if (customizer.TryGetCustomizeVariantCategory(slots[i], variantIndex, out string categoryName)
                && !string.IsNullOrWhiteSpace(categoryName))
            {
                return NormalizeCategoryName(categoryName);
            }
        }

        if (TryResolveVariantCategoryFromSourcePrefabs(variantIndex, slots, out string fallbackCategoryName))
        {
            return NormalizeCategoryName(fallbackCategoryName);
        }

        return string.Empty;
    }

    private bool TryResolveVariantCategoryFromSourcePrefabs(
        int variantIndex,
        MinimoCharacterCustomizer.PartSlot[] slots,
        out string categoryName)
    {
        categoryName = string.Empty;
        if (customizer == null || variantIndex < 0 || slots == null || slots.Length == 0)
        {
            return false;
        }

        for (int i = 0; i < slots.Length; i++)
        {
            MinimoCharacterCustomizer.PartSlot slot = slots[i];
            if (!customizer.TryGetVariantSourcePrefabForSlot(slot, variantIndex, out GameObject sourcePrefab)
                || sourcePrefab == null)
            {
                continue;
            }

#if UNITY_EDITOR
            string assetPath = AssetDatabase.GetAssetPath(sourcePrefab);
            if (TryResolveCategoryNameFromAssetPath(assetPath, out string resolvedCategory)
                && !string.IsNullOrWhiteSpace(resolvedCategory))
            {
                categoryName = resolvedCategory;
                return true;
            }
#endif

            if (TryResolveCategoryNameFromPrefabName(sourcePrefab.name, out string resolvedFromName))
            {
                categoryName = resolvedFromName;
                return true;
            }
        }

        return false;
    }

    private static bool TryResolveCategoryNameFromPrefabName(string prefabName, out string categoryName)
    {
        categoryName = string.Empty;
        if (string.IsNullOrWhiteSpace(prefabName))
        {
            return false;
        }

        if (prefabName.IndexOf("Default", StringComparison.OrdinalIgnoreCase) >= 0)
        {
            categoryName = CategoryDefaultOptionLabel;
            return true;
        }

        if (prefabName.IndexOf("Casual", StringComparison.OrdinalIgnoreCase) >= 0)
        {
            categoryName = CategoryCasualOptionLabel;
            return true;
        }

        return false;
    }

    private static bool TryResolveCategoryNameFromAssetPath(string assetPath, out string categoryName)
    {
        categoryName = string.Empty;
        string normalized = NormalizeCategoryAssetPath(assetPath);
        if (string.IsNullOrWhiteSpace(normalized))
        {
            return false;
        }

        string slotFolder = GetParentCategoryAssetFolder(normalized);
        if (string.IsNullOrWhiteSpace(slotFolder))
        {
            return false;
        }

        string categoryFolder = GetParentCategoryAssetFolder(slotFolder);
        if (string.IsNullOrWhiteSpace(categoryFolder))
        {
            return false;
        }

        string leafName = GetCategoryAssetLeafName(categoryFolder);
        if (string.IsNullOrWhiteSpace(leafName))
        {
            return false;
        }

        categoryName = leafName;
        return true;
    }

    private static string NormalizeCategoryAssetPath(string path)
    {
        if (string.IsNullOrWhiteSpace(path))
        {
            return string.Empty;
        }

        return path.Replace('\\', '/').TrimEnd('/');
    }

    private static string GetParentCategoryAssetFolder(string path)
    {
        string normalized = NormalizeCategoryAssetPath(path);
        if (string.IsNullOrWhiteSpace(normalized))
        {
            return string.Empty;
        }

        int slashIndex = normalized.LastIndexOf('/');
        if (slashIndex <= 0)
        {
            return string.Empty;
        }

        return normalized.Substring(0, slashIndex);
    }

    private static string GetCategoryAssetLeafName(string path)
    {
        string normalized = NormalizeCategoryAssetPath(path);
        if (string.IsNullOrWhiteSpace(normalized))
        {
            return string.Empty;
        }

        int slashIndex = normalized.LastIndexOf('/');
        return slashIndex < 0
            ? normalized
            : normalized.Substring(slashIndex + 1);
    }

    private void ApplyVariantCategoryBorder(Button button, string categoryName, bool isRandom)
    {
        if (button == null)
        {
            return;
        }

        _ = isRandom;
        _ = categoryName;
        Color borderColor = ResolveSavedCharacterDefaultOutlineColor();
        RemoveLegacyVariantCategoryBorder(button.transform);

        Image background = button.targetGraphic as Image;
        background ??= button.GetComponent<Image>();
        if (background == null)
        {
            return;
        }

        Outline outline = background.GetComponent<Outline>();
        if (outline == null)
        {
            outline = background.gameObject.AddComponent<Outline>();
        }

        outline.effectColor = borderColor;
        outline.useGraphicAlpha = false;
        outline.enabled = true;
    }

    private static void RemoveLegacyVariantCategoryBorder(Transform buttonTransform)
    {
        if (buttonTransform == null)
        {
            return;
        }

        Transform legacyBorder = buttonTransform.Find("CategoryBorder");
        if (legacyBorder == null)
        {
            return;
        }

        DestroyGameObjectSafely(legacyBorder.gameObject);
    }

    private bool IsFaceTextureSelectionMode()
    {
        // Face texture-set mode is disabled: Head now uses normal model variants.
        return false;
    }

    private int GetFaceTextureSetCount()
    {
        RefreshFaceTextureSetCache();
        return cachedFaceTextureSets.Count;
    }

    private void BuildFaceTextureButtons(Font font)
    {
        RefreshFaceTextureSetCache();
        for (int i = 0; i < cachedFaceTextureSets.Count; i++)
        {
            FaceTextureSet set = cachedFaceTextureSets[i];
            if (set == null)
            {
                continue;
            }

            Button button = CreateVariantButton(bodyPartsContent, font, set.displayName, i);
            ApplyVariantButtonVisualStyle(button);
            EnsureShadowPressTracking(button);
            FaceTextureSet capturedSet = set;
            button.onClick.AddListener(() => ApplyFaceTextureSet(capturedSet, true));

            Text label = FindChildByNameIn<Text>(button.transform, "Label");
            if (label != null)
            {
                label.fontSize = 12;
                label.alignment = TextAnchor.LowerCenter;
                label.rectTransform.offsetMin = new Vector2(4f, 2f);
                label.rectTransform.offsetMax = new Vector2(-4f, -2f);
            }

            if (set.albedo != null)
            {
                CreateRoundedPreviewImage(button, set.albedo, RuntimePreviewRectInset);
            }

            variantButtons.Add(new VariantButtonEntry
            {
                variantIndex = -1,
                isRandomButton = false,
                isFaceTextureButton = true,
                faceTextureKey = set.key,
                button = button,
                background = button.targetGraphic as Image
            });
        }
    }

    private void ApplyRandomFaceTextureSet()
    {
        RefreshFaceTextureSetCache();
        if (cachedFaceTextureSets.Count == 0)
        {
            return;
        }

        int randomIndex = UnityEngine.Random.Range(0, cachedFaceTextureSets.Count);
        FaceTextureSet set = cachedFaceTextureSets[randomIndex];
        ApplyFaceTextureSet(set, true);
    }

    private bool ApplyFaceTextureSet(FaceTextureSet set, bool refreshUi)
    {
        if (set == null || customizer == null || !customizer.TryGetPartRenderer(MinimoCharacterCustomizer.PartSlot.Face, out SkinnedMeshRenderer faceRenderer) || faceRenderer == null)
        {
            return false;
        }

        Material[] materials = faceRenderer.materials;
        if (materials == null || materials.Length == 0)
        {
            return false;
        }

        int materialIndex = ResolveColorMaterialIndexForSlot(MinimoCharacterCustomizer.PartSlot.Face, selectedColorMaterialIndex);
        materialIndex = Mathf.Clamp(materialIndex >= 0 ? materialIndex : 0, 0, materials.Length - 1);

        Material faceMaterial = materials[materialIndex];
        if (faceMaterial == null)
        {
            return false;
        }

        if (refreshUi)
        {
            RecordUndoSnapshotIfNeeded();
        }

        if (faceMaterial.HasProperty(FaceTextureShaderProperty))
        {
            faceMaterial.SetTexture(FaceTextureShaderProperty, set.albedo);
        }

        if (faceMaterial.HasProperty(FaceColorMaskShaderProperty))
        {
            faceMaterial.SetTexture(FaceColorMaskShaderProperty, set.colorMask);
        }

        if (faceMaterial.HasProperty(FaceMaskShaderProperty))
        {
            faceMaterial.SetTexture(FaceMaskShaderProperty, set.faceMask);
        }

        faceRenderer.materials = materials;
        selectedFaceTextureSetKey = set.key;
        helperOverrideMessage = $"Face selected: {set.displayName}";
        if (refreshUi)
        {
            RefreshAfterVariantApplication(new[] { MinimoCharacterCustomizer.PartSlot.Face });
        }

        return true;
    }

    private void ReapplySelectedFaceTextureSetIfNeeded()
    {
        if (customizer == null)
        {
            return;
        }

        RefreshFaceTextureSetCache();
        if (string.IsNullOrWhiteSpace(selectedFaceTextureSetKey))
        {
            SyncSelectedFaceTextureSetKeyFromCurrentMaterial();
            return;
        }

        for (int i = 0; i < cachedFaceTextureSets.Count; i++)
        {
            FaceTextureSet set = cachedFaceTextureSets[i];
            if (set == null || !string.Equals(set.key, selectedFaceTextureSetKey, StringComparison.Ordinal))
            {
                continue;
            }

            if (IsCurrentFaceTextureSet(set))
            {
                return;
            }

            ApplyFaceTextureSet(set, false);
            return;
        }
    }

    private bool IsCurrentFaceTextureSet(FaceTextureSet set)
    {
        if (set == null
            || customizer == null
            || !customizer.TryGetPartRenderer(MinimoCharacterCustomizer.PartSlot.Face, out SkinnedMeshRenderer faceRenderer)
            || faceRenderer == null)
        {
            return false;
        }

        Material[] materials = faceRenderer.sharedMaterials;
        if (materials == null || materials.Length == 0)
        {
            return false;
        }

        int materialIndex = ResolveColorMaterialIndexForSlot(MinimoCharacterCustomizer.PartSlot.Face, selectedColorMaterialIndex);
        materialIndex = Mathf.Clamp(materialIndex >= 0 ? materialIndex : 0, 0, materials.Length - 1);
        Material material = materials[materialIndex];
        if (material == null || !material.HasProperty(FaceTextureShaderProperty))
        {
            return false;
        }

        Texture currentFaceTexture = material.GetTexture(FaceTextureShaderProperty);
        return currentFaceTexture != null && currentFaceTexture == set.albedo;
    }

    private void SyncSelectedFaceTextureSetKeyFromCurrentMaterial()
    {
        selectedFaceTextureSetKey = string.Empty;
        if (customizer == null
            || !customizer.TryGetPartRenderer(MinimoCharacterCustomizer.PartSlot.Face, out SkinnedMeshRenderer faceRenderer)
            || faceRenderer == null)
        {
            return;
        }

        RefreshFaceTextureSetCache();
        Material[] materials = faceRenderer.sharedMaterials;
        if (materials == null || materials.Length == 0)
        {
            return;
        }

        int materialIndex = ResolveColorMaterialIndexForSlot(MinimoCharacterCustomizer.PartSlot.Face, selectedColorMaterialIndex);
        materialIndex = Mathf.Clamp(materialIndex >= 0 ? materialIndex : 0, 0, materials.Length - 1);

        Material material = materials[materialIndex];
        if (material == null || !material.HasProperty(FaceTextureShaderProperty))
        {
            return;
        }

        Texture currentFaceTexture = material.GetTexture(FaceTextureShaderProperty);
        if (currentFaceTexture == null)
        {
            return;
        }

        for (int i = 0; i < cachedFaceTextureSets.Count; i++)
        {
            FaceTextureSet set = cachedFaceTextureSets[i];
            if (set?.albedo == null)
            {
                continue;
            }

            if (set.albedo == currentFaceTexture)
            {
                selectedFaceTextureSetKey = set.key;
                return;
            }
        }
    }

    private void RefreshFaceTextureSetCache()
    {
        cachedFaceTextureSets.Clear();
#if UNITY_EDITOR
        if (customizer == null || !customizer.TryGetPartRenderer(MinimoCharacterCustomizer.PartSlot.Face, out SkinnedMeshRenderer faceRenderer) || faceRenderer == null)
        {
            return;
        }

        string preferredFolderPath = ResolveFaceTextureFolderPath(faceRenderer);
        List<string> searchFolders = ResolveFaceTextureSearchFolders(preferredFolderPath);
        for (int i = 0; i < searchFolders.Count; i++)
        {
            string folderPath = searchFolders[i];
            if (string.IsNullOrWhiteSpace(folderPath) || !AssetDatabase.IsValidFolder(folderPath))
            {
                continue;
            }

            string folderName = Path.GetFileName(folderPath);
            string prefix = string.Empty;
            if (string.Equals(folderName, "Male", StringComparison.OrdinalIgnoreCase))
            {
                prefix = "Male";
            }
            else if (string.Equals(folderName, "Female", StringComparison.OrdinalIgnoreCase))
            {
                prefix = "Female";
            }

            AppendFaceTextureSetsFromFolder(folderPath, prefix);
        }

        PrioritizeDefaultFaceTextureSet();
#endif
    }

    private void PrioritizeDefaultFaceTextureSet()
    {
        if (cachedFaceTextureSets == null || cachedFaceTextureSets.Count <= 1)
        {
            return;
        }

        int defaultIndex = -1;
        for (int i = 0; i < cachedFaceTextureSets.Count; i++)
        {
            FaceTextureSet set = cachedFaceTextureSets[i];
            if (set == null || string.IsNullOrWhiteSpace(set.key))
            {
                continue;
            }

            if (set.key.IndexOf(DefaultFaceSetMarker, StringComparison.OrdinalIgnoreCase) >= 0)
            {
                defaultIndex = i;
                break;
            }
        }

        if (defaultIndex <= 0)
        {
            return;
        }

        FaceTextureSet defaultSet = cachedFaceTextureSets[defaultIndex];
        cachedFaceTextureSets.RemoveAt(defaultIndex);
        cachedFaceTextureSets.Insert(0, defaultSet);
    }

    private void TryApplyDefaultFaceTextureSetIfAvailable()
    {
        if (customizer == null)
        {
            return;
        }

        RefreshFaceTextureSetCache();
        if (cachedFaceTextureSets.Count == 0)
        {
            return;
        }

        FaceTextureSet defaultSet = cachedFaceTextureSets[0];
        if (defaultSet == null
            || string.IsNullOrWhiteSpace(defaultSet.key)
            || defaultSet.key.IndexOf(DefaultFaceSetMarker, StringComparison.OrdinalIgnoreCase) < 0)
        {
            return;
        }

        ApplyFaceTextureSet(defaultSet, false);
    }

#if UNITY_EDITOR
    private List<string> ResolveFaceTextureSearchFolders(string preferredFolderPath)
    {
        const string defaultRoot = "Assets/Minimo/Character/Categories/Folders/Casual/Materials/Faces";
        List<string> folders = new List<string>();

        string normalizedPreferred = NormalizeAssetPath(preferredFolderPath);
        if (string.IsNullOrWhiteSpace(normalizedPreferred))
        {
            normalizedPreferred = defaultRoot;
        }

        string root = normalizedPreferred;
        string preferredLeaf = Path.GetFileName(normalizedPreferred);
        if (string.Equals(preferredLeaf, "Male", StringComparison.OrdinalIgnoreCase)
            || string.Equals(preferredLeaf, "Female", StringComparison.OrdinalIgnoreCase))
        {
            root = NormalizeAssetPath(Path.GetDirectoryName(normalizedPreferred));
        }

        if (string.IsNullOrWhiteSpace(root) || !AssetDatabase.IsValidFolder(root))
        {
            root = defaultRoot;
        }

        string maleFolder = $"{root}/Male";
        string femaleFolder = $"{root}/Female";
        bool hasMale = AssetDatabase.IsValidFolder(maleFolder);
        bool hasFemale = AssetDatabase.IsValidFolder(femaleFolder);

        if (hasMale || hasFemale)
        {
            if (hasMale)
            {
                folders.Add(maleFolder);
            }

            if (hasFemale)
            {
                folders.Add(femaleFolder);
            }

            return folders;
        }

        if (AssetDatabase.IsValidFolder(normalizedPreferred))
        {
            folders.Add(normalizedPreferred);
            return folders;
        }

        if (AssetDatabase.IsValidFolder(defaultRoot))
        {
            folders.Add(defaultRoot);
        }

        return folders;
    }

    private void AppendFaceTextureSetsFromFolder(string folderPath, string displayPrefix)
    {
        string[] textureGuids = AssetDatabase.FindAssets("t:Texture2D", new[] { folderPath });
        Dictionary<string, string> texturePathByName = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
        for (int i = 0; i < textureGuids.Length; i++)
        {
            string path = AssetDatabase.GUIDToAssetPath(textureGuids[i]);
            if (string.IsNullOrWhiteSpace(path))
            {
                continue;
            }

            string fileNameNoExt = Path.GetFileNameWithoutExtension(path);
            if (string.IsNullOrWhiteSpace(fileNameNoExt))
            {
                continue;
            }

            texturePathByName[fileNameNoExt] = path;
        }

        List<string> baseNames = new List<string>();
        foreach (KeyValuePair<string, string> pair in texturePathByName)
        {
            string fileName = pair.Key;
            if (!fileName.EndsWith("-Albedo", StringComparison.OrdinalIgnoreCase))
            {
                continue;
            }

            string baseName = fileName.Substring(0, fileName.Length - "-Albedo".Length);
            baseNames.Add(baseName);
        }

        baseNames.Sort(StringComparer.OrdinalIgnoreCase);
        for (int i = 0; i < baseNames.Count; i++)
        {
            string baseName = baseNames[i];
            string albedoKey = FindMatchingFaceTexturePath(texturePathByName, baseName, "-Albedo");
            if (string.IsNullOrWhiteSpace(albedoKey))
            {
                continue;
            }

            string colorMaskPath = FindMatchingFaceTexturePath(texturePathByName, baseName, "-ColorMask");
            string faceMaskPath = FindMatchingFaceTexturePath(texturePathByName, baseName, "-Mask");

            string displayName = string.IsNullOrWhiteSpace(displayPrefix)
                ? baseName
                : $"{displayPrefix} - {baseName}";
            FaceTextureSet set = new FaceTextureSet()
            {
                key = $"{folderPath}/{baseName}".ToLowerInvariant(),
                displayName = displayName,
                albedo = AssetDatabase.LoadAssetAtPath<Texture2D>(albedoKey),
                colorMask = !string.IsNullOrWhiteSpace(colorMaskPath) ? AssetDatabase.LoadAssetAtPath<Texture2D>(colorMaskPath) : null,
                faceMask = !string.IsNullOrWhiteSpace(faceMaskPath) ? AssetDatabase.LoadAssetAtPath<Texture2D>(faceMaskPath) : null
            };

            if (set.albedo != null)
            {
                cachedFaceTextureSets.Add(set);
            }
        }
    }

    private static string NormalizeAssetPath(string path)
    {
        if (string.IsNullOrWhiteSpace(path))
        {
            return string.Empty;
        }

        return path.Replace('\\', '/').TrimEnd('/');
    }

    private static string ResolveFaceTextureFolderPath(SkinnedMeshRenderer faceRenderer)
    {
        if (faceRenderer == null)
        {
            return null;
        }

        Material[] materials = faceRenderer.sharedMaterials;
        if (materials == null || materials.Length == 0)
        {
            return null;
        }

        for (int i = 0; i < materials.Length; i++)
        {
            Material material = materials[i];
            if (material == null)
            {
                continue;
            }

            Texture mainFace = material.HasProperty(FaceTextureShaderProperty)
                ? material.GetTexture(FaceTextureShaderProperty)
                : null;
            if (mainFace == null)
            {
                continue;
            }

            string facePath = AssetDatabase.GetAssetPath(mainFace);
            if (string.IsNullOrWhiteSpace(facePath))
            {
                continue;
            }

            return Path.GetDirectoryName(facePath)?.Replace('\\', '/');
        }

        return null;
    }

    private static string FindMatchingFaceTexturePath(
        Dictionary<string, string> texturePathByName,
        string baseName,
        string suffix)
    {
        if (texturePathByName == null || string.IsNullOrWhiteSpace(baseName) || string.IsNullOrWhiteSpace(suffix))
        {
            return null;
        }

        string exactKey = $"{baseName}{suffix}";
        if (texturePathByName.TryGetValue(exactKey, out string exactPath))
        {
            return exactPath;
        }

        foreach (KeyValuePair<string, string> pair in texturePathByName)
        {
            if (pair.Key.StartsWith(exactKey, StringComparison.OrdinalIgnoreCase))
            {
                return pair.Value;
            }
        }

        return null;
    }
#endif

    private void UnbindVariantEvents()
    {
        for (int i = 0; i < variantButtons.Count; i++)
        {
            variantButtons[i]?.button?.onClick.RemoveAllListeners();
        }
    }

    private void PrepareStartupPreviewWarmup()
    {
        if (!Application.isPlaying)
        {
            PrewarmPreviewCacheIfNeeded();
            return;
        }

        if (!showVariantPreviewInHud)
        {
            return;
        }

        deferPreviewGeneration = true;
        StartPreviewWarmup(includeFullCacheWarmup: !returningFromPlaygroundLoad);
    }

    private void QueueVisiblePreviewWarmupIfNeeded()
    {
        if (!Application.isPlaying
            || deferPreviewGeneration
            || !showVariantPreviewInHud
            || customizer == null
            || variantButtons.Count == 0)
        {
            return;
        }

        StartPreviewWarmup(includeFullCacheWarmup: false);
    }

    private void StartPreviewWarmup(bool includeFullCacheWarmup)
    {
        if (previewWarmupCoroutine != null)
        {
            StopCoroutine(previewWarmupCoroutine);
        }

        previewWarmupCoroutine = StartCoroutine(WarmPreviewCacheDeferred(includeFullCacheWarmup));
    }

    private IEnumerator WarmPreviewCacheDeferred(bool includeFullCacheWarmup)
    {
        yield return null;
        yield return null;

        deferPreviewGeneration = false;
        yield return WarmVisibleVariantButtonPreviewsIncremental();
        if (includeFullCacheWarmup)
        {
            yield return PrewarmPreviewCacheIncremental();
        }

        previewWarmupCoroutine = null;
    }

    private IEnumerator WarmVisibleVariantButtonPreviewsIncremental()
    {
        if (!showVariantPreviewInHud || customizer == null || variantButtons.Count == 0)
        {
            yield break;
        }

        float frameStart = Time.realtimeSinceStartup;
        List<PropVariantEntry> propEntries = null;
        for (int i = 0; i < variantButtons.Count; i++)
        {
            VariantButtonEntry entry = variantButtons[i];
            if (entry?.button == null
                || entry.isRandomButton
                || entry.isFaceTextureButton
                || entry.isPropEmptyButton)
            {
                continue;
            }

            if (entry.isPropButton)
            {
                PropVariantEntry propEntry = entry.propPreviewEntry;
                if (propEntry == null)
                {
                    propEntries ??= GetFilteredPropVariantEntriesForCurrentCategory();
                    propEntry = FindMatchingPropVariantEntry(entry, propEntries);
                }

                TryApplyPropButtonPreview(entry.button, propEntry, allowRuntimeCacheMissRender: true);
            }
            else if (entry.variantIndex >= 0)
            {
                MinimoCharacterCustomizer.PartSlot? preferredPreviewSlot =
                    ResolvePreferredPreviewSlotForVariantButtons(entry.targetSlots);
                TryApplyVariantButtonPreview(
                    entry.button,
                    entry.variantIndex,
                    string.Empty,
                    preferredPreviewSlot,
                    allowRuntimeCacheMissRender: true);
            }

            if (ShouldYieldPreviewWarmup(frameStart))
            {
                yield return null;
                frameStart = Time.realtimeSinceStartup;
            }
        }
    }

    private IEnumerator PrewarmPreviewCacheIncremental()
    {
        if (previewCachePrewarmed
            || !prewarmPreviewCacheOnStartup
            || !showVariantPreviewInHud
            || customizer == null
            || regions.Count == 0)
        {
            yield break;
        }

        previewCachePrewarmed = true;
        float frameStart = Time.realtimeSinceStartup;
        for (int regionIndex = 0; regionIndex < regions.Count; regionIndex++)
        {
            if (!TryBuildPreviewWarmupRegion(
                    regionIndex,
                    out MinimoCharacterCustomizer.PartSlot[] rawRegionSlots,
                    out bool faceTextureMode,
                    out bool propsMode,
                    out MinimoCharacterCustomizer.PartSlot? preferredPreviewSlot,
                    out List<int> variantIndices,
                    out List<PropVariantEntry> propEntries)
                || faceTextureMode)
            {
                continue;
            }

            if (propsMode)
            {
                for (int i = 0; i < propEntries.Count; i++)
                {
                    PreviewSelectionState previousState = CapturePreviewSelectionState();
                    try
                    {
                        ApplyPreviewWarmupRegionState(regionIndex, rawRegionSlots);
                        TryGetOrCreatePropPreviewCacheEntry(propEntries[i], out _);
                    }
                    finally
                    {
                        RestorePreviewSelectionState(previousState);
                    }

                    if (ShouldYieldPreviewWarmup(frameStart))
                    {
                        yield return null;
                        frameStart = Time.realtimeSinceStartup;
                    }
                }

                continue;
            }

            for (int i = 0; i < variantIndices.Count; i++)
            {
                PreviewSelectionState previousState = CapturePreviewSelectionState();
                try
                {
                    ApplyPreviewWarmupRegionState(regionIndex, rawRegionSlots);
                    TryGetOrCreateVariantPreviewCacheEntry(
                        variantIndices[i],
                        preferredPreviewSlot,
                        out _);
                }
                finally
                {
                    RestorePreviewSelectionState(previousState);
                }

                if (ShouldYieldPreviewWarmup(frameStart))
                {
                    yield return null;
                    frameStart = Time.realtimeSinceStartup;
                }
            }
        }
    }

    private bool TryBuildPreviewWarmupRegion(
        int regionIndex,
        out MinimoCharacterCustomizer.PartSlot[] rawRegionSlots,
        out bool faceTextureMode,
        out bool propsMode,
        out MinimoCharacterCustomizer.PartSlot? preferredPreviewSlot,
        out List<int> variantIndices,
        out List<PropVariantEntry> propEntries)
    {
        rawRegionSlots = Array.Empty<MinimoCharacterCustomizer.PartSlot>();
        faceTextureMode = false;
        propsMode = false;
        preferredPreviewSlot = null;
        variantIndices = new List<int>();
        propEntries = new List<PropVariantEntry>();
        if (regionIndex < 0 || regionIndex >= regions.Count)
        {
            return false;
        }

        PreviewSelectionState previousState = CapturePreviewSelectionState();
        try
        {
            selectedRegionIndex = regionIndex;
            selectedColorMaterialIndex = 0;
            rawRegionSlots = GetSelectedRegionSlotsRaw();
            ApplyPreviewWarmupRegionState(regionIndex, rawRegionSlots);
            faceTextureMode = IsFaceTextureSelectionMode();
            propsMode = IsPropsRegionSelectionMode();
            preferredPreviewSlot = ResolvePreferredPreviewSlotForVariantButtons(rawRegionSlots);

            if (faceTextureMode)
            {
                return true;
            }

            if (propsMode)
            {
                propEntries = BuildAllPropVariantEntries();
            }
            else
            {
                variantIndices = GetFilteredVariantIndicesForCurrentCategory();
            }

            return true;
        }
        finally
        {
            RestorePreviewSelectionState(previousState);
        }
    }

    private PreviewSelectionState CapturePreviewSelectionState()
    {
        return new PreviewSelectionState(
            selectedRegionIndex,
            selectedWorldColorTargetSlot,
            selectedWorldPreviewTargetSlot,
            selectedWorldVariantTargetSlots,
            selectedColorMaterialIndex);
    }

    private void RestorePreviewSelectionState(PreviewSelectionState state)
    {
        selectedRegionIndex = state.selectedRegionIndex;
        selectedWorldColorTargetSlot = state.selectedWorldColorTargetSlot;
        selectedWorldPreviewTargetSlot = state.selectedWorldPreviewTargetSlot;
        selectedWorldVariantTargetSlots = state.selectedWorldVariantTargetSlots;
        selectedColorMaterialIndex = state.selectedColorMaterialIndex;
    }

    private void ApplyPreviewWarmupRegionState(
        int regionIndex,
        MinimoCharacterCustomizer.PartSlot[] rawRegionSlots)
    {
        selectedRegionIndex = regionIndex;
        selectedColorMaterialIndex = 0;
        rawRegionSlots ??= Array.Empty<MinimoCharacterCustomizer.PartSlot>();
        selectedWorldColorTargetSlot = TryResolveMirroredSlotsForRegion(
            rawRegionSlots,
            out _,
            out MinimoCharacterCustomizer.PartSlot rightSlot)
            ? (MinimoCharacterCustomizer.PartSlot?)rightSlot
            : null;
        selectedWorldPreviewTargetSlot = selectedWorldColorTargetSlot;
        selectedWorldVariantTargetSlots = Array.Empty<MinimoCharacterCustomizer.PartSlot>();
    }

    private bool ShouldYieldPreviewWarmup(float frameStart)
    {
        return Application.isPlaying
               && startupPreviewWarmupFrameBudgetMs > 0f
               && (Time.realtimeSinceStartup - frameStart) * 1000f >= startupPreviewWarmupFrameBudgetMs;
    }

    private static PropVariantEntry FindMatchingPropVariantEntry(
        VariantButtonEntry buttonEntry,
        List<PropVariantEntry> propEntries)
    {
        if (buttonEntry == null || propEntries == null)
        {
            return null;
        }

        if (!string.IsNullOrWhiteSpace(buttonEntry.propAssetPath))
        {
            for (int i = 0; i < propEntries.Count; i++)
            {
                PropVariantEntry entry = propEntries[i];
                if (entry != null
                    && string.Equals(entry.assetPath, buttonEntry.propAssetPath, StringComparison.OrdinalIgnoreCase))
                {
                    return entry;
                }
            }
        }

        for (int i = 0; i < propEntries.Count; i++)
        {
            PropVariantEntry entry = propEntries[i];
            if (entry != null
                && string.Equals(entry.rigName, buttonEntry.propRigName, StringComparison.OrdinalIgnoreCase)
                && string.Equals(entry.prefabName, buttonEntry.propPrefabName, StringComparison.OrdinalIgnoreCase))
            {
                return entry;
            }
        }

        return null;
    }

    private void PrewarmPreviewCacheIfNeeded()
    {
        if (previewCachePrewarmed
            || !prewarmPreviewCacheOnStartup
            || !showVariantPreviewInHud
            || customizer == null
            || regions.Count == 0)
        {
            return;
        }

        previewCachePrewarmed = true;
        int previousRegionIndex = selectedRegionIndex;
        MinimoCharacterCustomizer.PartSlot? previousWorldTargetSlot = selectedWorldColorTargetSlot;
        MinimoCharacterCustomizer.PartSlot? previousWorldPreviewTargetSlot = selectedWorldPreviewTargetSlot;
        MinimoCharacterCustomizer.PartSlot[] previousWorldVariantTargetSlots = selectedWorldVariantTargetSlots;
        int previousColorMaterialIndex = selectedColorMaterialIndex;
        try
        {
            for (int regionIndex = 0; regionIndex < regions.Count; regionIndex++)
            {
                selectedRegionIndex = regionIndex;
                selectedColorMaterialIndex = 0;
                MinimoCharacterCustomizer.PartSlot[] rawRegionSlots = GetSelectedRegionSlotsRaw();
                selectedWorldColorTargetSlot = TryResolveMirroredSlotsForRegion(
                    rawRegionSlots,
                    out _,
                    out MinimoCharacterCustomizer.PartSlot rightSlot)
                    ? (MinimoCharacterCustomizer.PartSlot?)rightSlot
                    : null;
                selectedWorldPreviewTargetSlot = selectedWorldColorTargetSlot;
                selectedWorldVariantTargetSlots = Array.Empty<MinimoCharacterCustomizer.PartSlot>();

                if (IsFaceTextureSelectionMode())
                {
                    continue;
                }

                if (IsPropsRegionSelectionMode())
                {
                    List<PropVariantEntry> propEntries = BuildAllPropVariantEntries();
                    for (int i = 0; i < propEntries.Count; i++)
                    {
                        TryGetOrCreatePropPreviewCacheEntry(propEntries[i], out _);
                    }

                    continue;
                }

                List<int> variantIndices = GetFilteredVariantIndicesForCurrentCategory();
                MinimoCharacterCustomizer.PartSlot? preferredPreviewSlot = ResolvePreferredPreviewSlotForVariantButtons(rawRegionSlots);
                for (int i = 0; i < variantIndices.Count; i++)
                {
                    TryGetOrCreateVariantPreviewCacheEntry(variantIndices[i], preferredPreviewSlot, out _);
                }
            }
        }
        finally
        {
            selectedRegionIndex = previousRegionIndex;
            selectedWorldColorTargetSlot = previousWorldTargetSlot;
            selectedWorldPreviewTargetSlot = previousWorldPreviewTargetSlot;
            selectedWorldVariantTargetSlots = previousWorldVariantTargetSlots;
            selectedColorMaterialIndex = previousColorMaterialIndex;
        }
    }

    private void TryApplyVariantButtonPreview(
        Button button,
        int variantIndex,
        string displayName,
        MinimoCharacterCustomizer.PartSlot? preferredPreviewSlot = null,
        bool allowRuntimeCacheMissRender = false)
    {
        if (!showVariantPreviewInHud || button == null || customizer == null)
        {
            return;
        }

        if (TryGetCachedVariantPreviewCacheEntry(variantIndex, preferredPreviewSlot, out PreviewTextureCacheEntry cachedEntry))
        {
            ApplyCachedPreviewTextureToButton(button, cachedEntry);
            return;
        }

        if (deferPreviewGeneration)
        {
            return;
        }

        if (Application.isPlaying && !allowRuntimeCacheMissRender)
        {
            return;
        }

        if (TryGetOrCreateVariantPreviewCacheEntry(variantIndex, preferredPreviewSlot, out PreviewTextureCacheEntry cacheEntry))
        {
            ApplyCachedPreviewTextureToButton(button, cacheEntry);
            return;
        }
    }

    private bool TryGetCachedVariantPreviewCacheEntry(
        int variantIndex,
        MinimoCharacterCustomizer.PartSlot? preferredPreviewSlot,
        out PreviewTextureCacheEntry cacheEntry)
    {
        cacheEntry = null;
        string cacheKey = BuildVariantPreviewCacheKey(variantIndex, preferredPreviewSlot);
        if (!variantPreviewTextureCache.TryGetValue(cacheKey, out cacheEntry))
        {
            return false;
        }

        if (cacheEntry != null && cacheEntry.texture != null)
        {
            return true;
        }

        variantPreviewTextureCache.Remove(cacheKey);
        cacheEntry = null;
        return false;
    }

    private bool TryGetOrCreateVariantPreviewCacheEntry(
        int variantIndex,
        MinimoCharacterCustomizer.PartSlot? preferredPreviewSlot,
        out PreviewTextureCacheEntry cacheEntry)
    {
        cacheEntry = null;
        if (TryGetCachedVariantPreviewCacheEntry(variantIndex, preferredPreviewSlot, out cacheEntry))
        {
            return true;
        }

        if (!TryCreateVariantPreviewCacheEntry(variantIndex, preferredPreviewSlot, out cacheEntry))
        {
            return false;
        }

        string cacheKey = BuildVariantPreviewCacheKey(variantIndex, preferredPreviewSlot);
        variantPreviewTextureCache[cacheKey] = cacheEntry;
        return true;
    }

    private bool TryCreateVariantPreviewCacheEntry(
        int variantIndex,
        MinimoCharacterCustomizer.PartSlot? preferredPreviewSlot,
        out PreviewTextureCacheEntry cacheEntry)
    {
        cacheEntry = null;

        if (TryRenderBestVariantMeshPreviewTexture(
                variantIndex,
                preferredPreviewSlot,
                includeGlobalFallback: false,
                out cacheEntry))
        {
            return true;
        }

        if (TryRenderVariantSourcePrefabPreviewTexture(
                variantIndex,
                out Texture2D sourcePreviewTexture,
                out MinimoCharacterCustomizer.PartSlot sourcePreviewSlot,
                preferredPreviewSlot,
                includeGlobalFallback: false)
            && TryCreatePreviewCacheEntry(sourcePreviewTexture, sourcePreviewSlot, out cacheEntry))
        {
            return true;
        }

        if (TryRenderBestVariantMeshPreviewTexture(
                variantIndex,
                preferredPreviewSlot,
                includeGlobalFallback: true,
                out cacheEntry))
        {
            return true;
        }

        return TryRenderVariantSourcePrefabPreviewTexture(
                variantIndex,
                out Texture2D fallbackSourcePreviewTexture,
                out MinimoCharacterCustomizer.PartSlot fallbackSourcePreviewSlot,
                preferredPreviewSlot,
                includeGlobalFallback: true)
            && TryCreatePreviewCacheEntry(fallbackSourcePreviewTexture, fallbackSourcePreviewSlot, out cacheEntry);
    }

    private bool TryRenderBestVariantMeshPreviewTexture(
        int variantIndex,
        MinimoCharacterCustomizer.PartSlot? preferredPreviewSlot,
        bool includeGlobalFallback,
        out PreviewTextureCacheEntry cacheEntry)
    {
        cacheEntry = null;
        if (customizer == null)
        {
            return false;
        }

        List<MinimoCharacterCustomizer.PartSlot> candidates = BuildPreviewCandidateSlots(
            preferredPreviewSlot,
            includeGlobalFallback);
        for (int i = 0; i < candidates.Count; i++)
        {
            MinimoCharacterCustomizer.PartSlot previewSlot = candidates[i];
            if (!customizer.TryGetVariantPartPreviewData(
                    variantIndex,
                    previewSlot,
                    out Mesh previewMesh,
                    out Material[] previewMaterials,
                    out Bounds previewBounds,
                    out Quaternion previewRotationHint))
            {
                continue;
            }

            Texture2D previewTexture = RenderVariantPreviewTexture(
                previewSlot,
                previewMesh,
                previewMaterials,
                previewBounds,
                previewRotationHint,
                suppressSkinToneOverride: previewSlot == MinimoCharacterCustomizer.PartSlot.Face
                                          && IsDefaultCategoryVariantForSlot(MinimoCharacterCustomizer.PartSlot.Face, variantIndex));
            if (TryCreatePreviewCacheEntry(previewTexture, previewSlot, out cacheEntry))
            {
                return true;
            }
        }

        return false;
    }

    private string BuildVariantPreviewCacheKey(
        int variantIndex,
        MinimoCharacterCustomizer.PartSlot? preferredPreviewSlot)
    {
        string preferred = preferredPreviewSlot.HasValue ? preferredPreviewSlot.Value.ToString() : "none";
        string worldTarget = selectedWorldColorTargetSlot.HasValue ? selectedWorldColorTargetSlot.Value.ToString() : "none";
        string worldVariantTargets = BuildSelectedWorldVariantTargetSlotSignature();
        return $"preview:{PreviewRenderSettingsVersion}|variant:{variantIndex}|region:{selectedRegionIndex}|preferred:{preferred}|world:{worldTarget}|targets:{worldVariantTargets}|dual:{UseDualPartMode()}";
    }

    private bool TryApplyBestVariantMeshPreviewTexture(
        Button button,
        int variantIndex,
        MinimoCharacterCustomizer.PartSlot? preferredPreviewSlot,
        bool includeGlobalFallback)
    {
        if (button == null || customizer == null)
        {
            return false;
        }

        List<MinimoCharacterCustomizer.PartSlot> candidates = BuildPreviewCandidateSlots(
            preferredPreviewSlot,
            includeGlobalFallback);
        for (int i = 0; i < candidates.Count; i++)
        {
            MinimoCharacterCustomizer.PartSlot previewSlot = candidates[i];
            if (!customizer.TryGetVariantPartPreviewData(
                    variantIndex,
                    previewSlot,
                    out Mesh previewMesh,
                    out Material[] previewMaterials,
                    out Bounds previewBounds,
                    out Quaternion previewRotationHint))
            {
                continue;
            }

            Texture2D previewTexture = RenderVariantPreviewTexture(
                previewSlot,
                previewMesh,
                previewMaterials,
                previewBounds,
                previewRotationHint,
                suppressSkinToneOverride: previewSlot == MinimoCharacterCustomizer.PartSlot.Face
                                          && IsDefaultCategoryVariantForSlot(MinimoCharacterCustomizer.PartSlot.Face, variantIndex));
            if (TryApplyRenderedVariantPreviewTexture(button, previewTexture, previewSlot))
            {
                return true;
            }
        }

        return false;
    }

    private List<MinimoCharacterCustomizer.PartSlot> BuildPreviewCandidateSlots(
        MinimoCharacterCustomizer.PartSlot? preferredSlot = null,
        bool includeGlobalFallback = true)
    {
        List<MinimoCharacterCustomizer.PartSlot> candidates = new List<MinimoCharacterCustomizer.PartSlot>();
        HashSet<MinimoCharacterCustomizer.PartSlot> visited = new HashSet<MinimoCharacterCustomizer.PartSlot>();

        void AddCandidate(MinimoCharacterCustomizer.PartSlot slot)
        {
            if (visited.Add(slot))
            {
                candidates.Add(slot);
            }
        }

        if (preferredSlot.HasValue)
        {
            AddCandidate(preferredSlot.Value);
        }

        MinimoCharacterCustomizer.PartSlot[] worldVariantSlots = GetSelectedWorldVariantTargetSlots();
        for (int i = 0; i < worldVariantSlots.Length; i++)
        {
            AddCandidate(worldVariantSlots[i]);
        }

        MinimoCharacterCustomizer.PartSlot[] selectedSlots = worldVariantSlots.Length > 0
            ? worldVariantSlots
            : GetTargetSlotsForSelectedRegion();
        if (TryResolveRightSlotForMirroredRegion(selectedSlots, out MinimoCharacterCustomizer.PartSlot mirroredRightSlot))
        {
            AddCandidate(mirroredRightSlot);
        }

        for (int i = 0; i < selectedSlots.Length; i++)
        {
            AddCandidate(selectedSlots[i]);
        }

        MinimoCharacterCustomizer.PartSlot[] colorSlots = GetTargetSlotsForColorOperations();
        for (int i = 0; i < colorSlots.Length; i++)
        {
            AddCandidate(colorSlots[i]);
        }

        if (!includeGlobalFallback)
        {
            return candidates;
        }

        IReadOnlyList<MinimoCharacterCustomizer.PartSlot> orderedSlots = MinimoCharacterCustomizer.Slots;
        for (int i = 0; i < orderedSlots.Count; i++)
        {
            AddCandidate(orderedSlots[i]);
        }

        return candidates;
    }

    private bool TryRenderVariantSourcePrefabPreviewTexture(
        int variantIndex,
        out Texture2D previewTexture,
        out MinimoCharacterCustomizer.PartSlot previewSlotUsed,
        MinimoCharacterCustomizer.PartSlot? preferredPreviewSlot = null,
        bool includeGlobalFallback = true)
    {
        previewTexture = null;
        previewSlotUsed = preferredPreviewSlot ?? MinimoCharacterCustomizer.PartSlot.Face;
        if (customizer == null || variantIndex < 0)
        {
            return false;
        }

        List<MinimoCharacterCustomizer.PartSlot> candidateSlots = BuildPreviewCandidateSlots(
            preferredPreviewSlot,
            includeGlobalFallback);
        for (int i = 0; i < candidateSlots.Count; i++)
        {
            MinimoCharacterCustomizer.PartSlot slot = candidateSlots[i];
            if (!customizer.TryGetVariantSourcePrefabForSlot(slot, variantIndex, out GameObject sourcePrefab)
                || sourcePrefab == null)
            {
                continue;
            }

            if (TryRenderVariantSourcePrefabPreviewTexture(sourcePrefab, slot, out previewTexture)
                && PreviewTextureHasVisibleContent(previewTexture))
            {
                previewSlotUsed = slot;
                return true;
            }

            DestroyPreviewTexture(previewTexture);
            previewTexture = null;
        }

        return false;
    }

    private bool TryRenderVariantSourcePrefabPreviewTexture(
        GameObject sourcePrefab,
        MinimoCharacterCustomizer.PartSlot previewSlot,
        out Texture2D previewTexture)
    {
        previewTexture = null;
        if (sourcePrefab == null || !EnsureVariantPreviewRenderer())
        {
            return false;
        }

        variantPreviewMeshFilter.sharedMesh = null;
        variantPreviewMeshRenderer.sharedMaterial = null;

        GameObject instance = null;
        try
        {
            PartPreviewProfile previewProfile = ResolvePartPreviewProfile(previewSlot);
            if (!EnsureVariantPreviewRenderTexture(previewProfile.previewResolution))
            {
                return false;
            }

            instance = Instantiate(sourcePrefab);
            if (instance == null)
            {
                return false;
            }

            instance.name = StripUnityCloneSuffix(sourcePrefab.name);
            instance.hideFlags = HideFlags.HideAndDontSave;
            instance.transform.SetParent(variantPreviewPrefabRoot, false);
            instance.transform.localPosition = Vector3.zero;
            instance.transform.localRotation = Quaternion.identity;
            instance.transform.localScale = Vector3.one;
            StripUnityCloneSuffixesRecursively(instance.transform);
            SetHideFlagsRecursively(instance.transform, HideFlags.HideAndDontSave);
            PreparePreviewInstanceForTPose(instance);
            if (instance.TryGetComponent(out MinimoCharacterCustomizer previewCustomizer) && previewCustomizer != null)
            {
                previewCustomizer.ApplyCurrentSelection();
                ApplySavedFaceChannelColorsFromPartColorStorage(previewCustomizer, previewCustomizer);
            }

            ApplyPreviewMaterialBoostsToRenderers(instance);

            if (!TryGetWorldPreviewBoundsAndCenter(instance, out Bounds worldBounds, out _))
            {
                return false;
            }

            Vector3 localCenter = variantPreviewRoot.transform.InverseTransformPoint(worldBounds.center);
            instance.transform.localPosition -= localCenter;
            instance.transform.localRotation = previewProfile.rotation;

            if (!TryGetWorldPreviewBoundsAndCenter(instance, out worldBounds, out _))
            {
                return false;
            }

            localCenter = variantPreviewRoot.transform.InverseTransformPoint(worldBounds.center);
            instance.transform.localPosition -= localCenter;

            Vector3 screenNudge = ResolvePreviewScreenNudgeWorld(previewProfile.positionOffsetNormalized, worldBounds.extents);
            if (screenNudge.sqrMagnitude > 0.0000001f)
            {
                instance.transform.localPosition += screenNudge;
                if (!TryGetWorldPreviewBoundsAndCenter(instance, out worldBounds, out _))
                {
                    return false;
                }
            }

            float aspect = variantPreviewRenderTexture != null && variantPreviewRenderTexture.height > 0
                ? variantPreviewRenderTexture.width / (float)variantPreviewRenderTexture.height
                : 1f;
            float halfWidth = Mathf.Max(0.05f, worldBounds.extents.x);
            float halfHeight = Mathf.Max(0.05f, worldBounds.extents.y);
            float orthoSizeFromWidth = aspect > 0.0001f ? halfWidth / aspect : halfWidth;
            float meshScale = Mathf.Max(0.01f, previewProfile.meshScale);
            float orthoSize = Mathf.Max(halfHeight, orthoSizeFromWidth)
                              * previewProfile.orthoPadding
                              * Mathf.Max(0.01f, previewProfile.sizeMultiplier)
                              * (1f / meshScale);
            float depth = Mathf.Max(0.15f, worldBounds.extents.z * 2f);
            float cameraDistance = Mathf.Max(1.6f, depth * 1.6f);

            variantPreviewCamera.transform.localPosition = new Vector3(0f, 0f, -cameraDistance);
            variantPreviewCamera.transform.localRotation = Quaternion.identity;
            variantPreviewCamera.orthographic = true;
            variantPreviewCamera.orthographicSize = orthoSize;
            variantPreviewCamera.nearClipPlane = 0.01f;
            variantPreviewCamera.farClipPlane = cameraDistance + depth * 4f + 2f;
            variantPreviewCamera.backgroundColor = PreviewBackgroundColor;
            ConfigureBrightPreviewLighting();

            previewTexture = RenderVariantPreviewToTexture2D();
            if (previewTexture == null)
            {
                return false;
            }

            return true;
        }
        finally
        {
            if (instance != null)
            {
                DestroyPreviewTempObject(instance);
            }
        }
    }

    private static bool TryGetWorldBoundsOfRenderers(GameObject root, out Bounds worldBounds)
    {
        worldBounds = default;
        if (root == null)
        {
            return false;
        }

        Renderer[] renderers = root.GetComponentsInChildren<Renderer>(true);
        bool initialized = false;
        for (int i = 0; i < renderers.Length; i++)
        {
            Renderer renderer = renderers[i];
            if (renderer == null
                || (!(renderer is SkinnedMeshRenderer) && !(renderer is MeshRenderer)))
            {
                continue;
            }

            if (!initialized)
            {
                worldBounds = renderer.bounds;
                initialized = true;
                continue;
            }

            worldBounds.Encapsulate(renderer.bounds);
        }

        return initialized;
    }

    private static bool TryGetWorldVertexBoundsAndCenter(GameObject root, out Bounds worldBounds, out Vector3 worldCenter)
    {
        worldBounds = default;
        worldCenter = Vector3.zero;
        if (root == null)
        {
            return false;
        }

        bool initializedBounds = false;
        Vector3 weightedCenterSum = Vector3.zero;
        int totalVertexCount = 0;

        SkinnedMeshRenderer[] skinnedRenderers = root.GetComponentsInChildren<SkinnedMeshRenderer>(true);
        for (int i = 0; i < skinnedRenderers.Length; i++)
        {
            SkinnedMeshRenderer renderer = skinnedRenderers[i];
            if (renderer == null || renderer.sharedMesh == null)
            {
                continue;
            }

            AccumulateWorldVertexMetrics(
                renderer.sharedMesh,
                renderer.localToWorldMatrix,
                ref initializedBounds,
                ref worldBounds,
                ref weightedCenterSum,
                ref totalVertexCount);
        }

        MeshRenderer[] meshRenderers = root.GetComponentsInChildren<MeshRenderer>(true);
        for (int i = 0; i < meshRenderers.Length; i++)
        {
            MeshRenderer renderer = meshRenderers[i];
            if (renderer == null || !renderer.TryGetComponent(out MeshFilter meshFilter) || meshFilter.sharedMesh == null)
            {
                continue;
            }

            AccumulateWorldVertexMetrics(
                meshFilter.sharedMesh,
                meshFilter.transform.localToWorldMatrix,
                ref initializedBounds,
                ref worldBounds,
                ref weightedCenterSum,
                ref totalVertexCount);
        }

        if (!initializedBounds)
        {
            return false;
        }

        worldCenter = totalVertexCount > 0
            ? weightedCenterSum / totalVertexCount
            : worldBounds.center;
        return true;
    }

    private static bool TryGetWorldPreviewBoundsAndCenter(GameObject root, out Bounds worldBounds, out Vector3 worldCenter)
    {
        worldBounds = default;
        worldCenter = Vector3.zero;
        if (root == null)
        {
            return false;
        }

        if (TryGetWorldBakedSkinnedBoundsAndCenter(root, out worldBounds, out worldCenter))
        {
            return true;
        }

        if (TryGetWorldVertexBoundsAndCenter(root, out worldBounds, out worldCenter))
        {
            return true;
        }

        if (!TryGetWorldBoundsOfRenderers(root, out worldBounds))
        {
            return false;
        }

        worldCenter = worldBounds.center;
        return true;
    }

    private static bool TryGetWorldBakedSkinnedBoundsAndCenter(GameObject root, out Bounds worldBounds, out Vector3 worldCenter)
    {
        worldBounds = default;
        worldCenter = Vector3.zero;
        if (root == null)
        {
            return false;
        }

        bool initializedBounds = false;
        Vector3 weightedCenterSum = Vector3.zero;
        int totalVertexCount = 0;

        SkinnedMeshRenderer[] skinnedRenderers = root.GetComponentsInChildren<SkinnedMeshRenderer>(true);
        if (skinnedRenderers == null || skinnedRenderers.Length == 0)
        {
            return false;
        }

        Mesh bakedMesh = new Mesh();
        bakedMesh.hideFlags = HideFlags.HideAndDontSave;
        try
        {
            for (int i = 0; i < skinnedRenderers.Length; i++)
            {
                SkinnedMeshRenderer renderer = skinnedRenderers[i];
                if (renderer == null || renderer.sharedMesh == null || renderer.sharedMesh.vertexCount <= 0)
                {
                    continue;
                }

                bakedMesh.Clear();
                renderer.BakeMesh(bakedMesh);
                if (bakedMesh.vertexCount <= 0)
                {
                    continue;
                }

                AccumulateWorldVertexMetrics(
                    bakedMesh,
                    renderer.transform.localToWorldMatrix,
                    ref initializedBounds,
                    ref worldBounds,
                    ref weightedCenterSum,
                    ref totalVertexCount);
            }
        }
        finally
        {
            if (Application.isPlaying)
            {
                Destroy(bakedMesh);
            }
            else
            {
                DestroyImmediate(bakedMesh);
            }
        }

        if (!initializedBounds)
        {
            return false;
        }

        worldCenter = totalVertexCount > 0
            ? weightedCenterSum / totalVertexCount
            : worldBounds.center;
        return true;
    }

    private static void AccumulateWorldVertexMetrics(
        Mesh mesh,
        Matrix4x4 localToWorldMatrix,
        ref bool initializedBounds,
        ref Bounds worldBounds,
        ref Vector3 weightedCenterSum,
        ref int totalVertexCount)
    {
        if (mesh == null)
        {
            return;
        }

        Bounds transformedBounds = TransformLocalBoundsToWorld(mesh.bounds, localToWorldMatrix);
        if (!initializedBounds)
        {
            worldBounds = transformedBounds;
            initializedBounds = true;
        }
        else
        {
            worldBounds.Encapsulate(transformedBounds);
        }

        int vertexCount = mesh.vertexCount;
        if (vertexCount <= 0)
        {
            return;
        }

        Vector3 worldMeshCenter = localToWorldMatrix.MultiplyPoint3x4(mesh.bounds.center);
        weightedCenterSum += worldMeshCenter * vertexCount;
        totalVertexCount += vertexCount;
    }

    private static Bounds TransformLocalBoundsToWorld(Bounds localBounds, Matrix4x4 localToWorldMatrix)
    {
        Vector3 worldCenter = localToWorldMatrix.MultiplyPoint3x4(localBounds.center);
        Vector3 extents = localBounds.extents;
        Vector3 axisX = localToWorldMatrix.MultiplyVector(new Vector3(extents.x, 0f, 0f));
        Vector3 axisY = localToWorldMatrix.MultiplyVector(new Vector3(0f, extents.y, 0f));
        Vector3 axisZ = localToWorldMatrix.MultiplyVector(new Vector3(0f, 0f, extents.z));
        Vector3 worldExtents = AbsVector3(axisX) + AbsVector3(axisY) + AbsVector3(axisZ);
        return new Bounds(worldCenter, worldExtents * 2f);
    }

    private static Vector3 AbsVector3(Vector3 value)
    {
        return new Vector3(Mathf.Abs(value.x), Mathf.Abs(value.y), Mathf.Abs(value.z));
    }

    private static void SetHideFlagsRecursively(Transform root, HideFlags hideFlags)
    {
        if (root == null)
        {
            return;
        }

        root.gameObject.hideFlags = hideFlags;
        root.hideFlags = hideFlags;
        for (int i = 0; i < root.childCount; i++)
        {
            SetHideFlagsRecursively(root.GetChild(i), hideFlags);
        }
    }

    private static void StripUnityCloneSuffixesRecursively(Transform root)
    {
        if (root == null)
        {
            return;
        }

        root.gameObject.name = StripUnityCloneSuffix(root.gameObject.name);
        for (int i = 0; i < root.childCount; i++)
        {
            StripUnityCloneSuffixesRecursively(root.GetChild(i));
        }
    }

    private static string StripUnityCloneSuffix(string value, string fallback = "Object")
    {
        string result = string.IsNullOrWhiteSpace(value) ? fallback : value.Trim();
        while (result.EndsWith(UnityCloneSuffix, StringComparison.Ordinal))
        {
            result = result.Substring(0, result.Length - UnityCloneSuffix.Length).TrimEnd();
        }

        return string.IsNullOrWhiteSpace(result) ? fallback : result;
    }

    private Texture2D RenderVariantPreviewToTexture2D()
    {
        if (variantPreviewCamera == null || variantPreviewRenderTexture == null)
        {
            return null;
        }

        RenderTexture previous = RenderTexture.active;
        try
        {
            ConfigurePreviewCameraForSharpCapture(variantPreviewCamera);
            variantPreviewCamera.targetTexture = variantPreviewRenderTexture;
            variantPreviewCamera.Render();

            RenderTexture.active = variantPreviewRenderTexture;
            Texture2D texture = new Texture2D(
                variantPreviewRenderTexture.width,
                variantPreviewRenderTexture.height,
                TextureFormat.RGBA32,
                false);
            texture.ReadPixels(new Rect(0f, 0f, variantPreviewRenderTexture.width, variantPreviewRenderTexture.height), 0, 0, false);
            texture.filterMode = FilterMode.Bilinear;
            texture.wrapMode = TextureWrapMode.Clamp;
            texture.anisoLevel = 2;
            if (ShouldEnhancePreviewTextureColors())
            {
                EnhancePreviewTextureColors(texture);
            }

            texture.Apply(false, false);
            return texture;
        }
        finally
        {
            variantPreviewCamera.targetTexture = null;
            RenderTexture.active = previous;
        }
    }

    private static void EnhancePreviewTextureColors(Texture2D texture)
    {
        if (texture == null || texture.width <= 0 || texture.height <= 0)
        {
            return;
        }

        Color32[] pixels;
        try
        {
            pixels = texture.GetPixels32();
        }
        catch (UnityException)
        {
            return;
        }

        Color backgroundColor = ResolvePreviewBackgroundColor(texture);
        for (int i = 0; i < pixels.Length; i++)
        {
            Color32 pixel = pixels[i];
            if (IsPreviewBackgroundPixel(pixel, backgroundColor))
            {
                pixels[i] = new Color32(255, 255, 255, 255);
                continue;
            }

            if (pixel.a == 0)
            {
                continue;
            }

            float r = pixel.r / 255f;
            float g = pixel.g / 255f;
            float b = pixel.b / 255f;
            float luminance = (0.2126f * r) + (0.7152f * g) + (0.0722f * b);
            float lift = PreviewShadowLift * (1f - luminance);

            r = Mathf.Clamp01((r * PreviewExposureBoost) + lift);
            g = Mathf.Clamp01((g * PreviewExposureBoost) + lift);
            b = Mathf.Clamp01((b * PreviewExposureBoost) + lift);

            float adjustedLuminance = (0.2126f * r) + (0.7152f * g) + (0.0722f * b);
            r = Mathf.Clamp01(adjustedLuminance + ((r - adjustedLuminance) * PreviewSaturationBoost));
            g = Mathf.Clamp01(adjustedLuminance + ((g - adjustedLuminance) * PreviewSaturationBoost));
            b = Mathf.Clamp01(adjustedLuminance + ((b - adjustedLuminance) * PreviewSaturationBoost));

            pixels[i] = new Color32(
                (byte)Mathf.RoundToInt(r * 255f),
                (byte)Mathf.RoundToInt(g * 255f),
                (byte)Mathf.RoundToInt(b * 255f),
                pixel.a);
        }

        texture.SetPixels32(pixels);
    }

    private static bool ShouldEnhancePreviewTextureColors()
    {
        if (!Application.isPlaying)
        {
            return true;
        }

        return !Mathf.Approximately(PreviewExposureBoost, 1f)
               || !Mathf.Approximately(PreviewShadowLift, 0f)
               || !Mathf.Approximately(PreviewSaturationBoost, 1f);
    }

    private static bool IsPreviewBackgroundPixel(Color32 pixel, Color backgroundColor)
    {
        if (pixel.a <= 8)
        {
            return true;
        }

        Color sample = new Color(pixel.r / 255f, pixel.g / 255f, pixel.b / 255f, 1f);
        Color backgroundRgb = new Color(backgroundColor.r, backgroundColor.g, backgroundColor.b, 1f);
        return ColorDistanceSquared(sample, backgroundRgb) <= PreviewBackgroundCleanupThreshold;
    }

    private static void DestroyPreviewTempObject(GameObject target)
    {
        if (target == null)
        {
            return;
        }

        DestroyImmediate(target);
    }

    private bool TryApplyRenderedVariantPreviewTexture(
        Button button,
        Texture2D previewTexture,
        MinimoCharacterCustomizer.PartSlot previewSlot)
    {
        if (button == null || previewTexture == null)
        {
            return false;
        }

        PartPreviewProfile previewProfile = ResolvePartPreviewProfile(previewSlot);
        if (!TryResolveVisiblePreviewUvRect(previewTexture, previewProfile.uvPaddingScale, out Rect uvRect))
        {
            DestroyPreviewTexture(previewTexture);
            return false;
        }

        ApplyVariantPreviewTextureToButton(
            button,
            previewTexture,
            ownsTexture: true,
            buttonSpriteScale: previewProfile.buttonSpriteScale,
            previewUvRect: uvRect);
        return true;
    }

    private bool TryCreatePreviewCacheEntry(
        Texture2D previewTexture,
        MinimoCharacterCustomizer.PartSlot previewSlot,
        out PreviewTextureCacheEntry cacheEntry)
    {
        cacheEntry = null;
        if (previewTexture == null)
        {
            return false;
        }

        PartPreviewProfile previewProfile = ResolvePartPreviewProfile(previewSlot);
        if (!TryResolveVisiblePreviewUvRect(previewTexture, previewProfile.uvPaddingScale, out Rect uvRect))
        {
            DestroyPreviewTexture(previewTexture);
            return false;
        }

        cacheEntry = new PreviewTextureCacheEntry
        {
            texture = previewTexture,
            previewSlot = previewSlot,
            uvRect = uvRect
        };
        return true;
    }

    private void ApplyCachedPreviewTextureToButton(Button button, PreviewTextureCacheEntry cacheEntry)
    {
        if (button == null || cacheEntry == null || cacheEntry.texture == null)
        {
            return;
        }

        PartPreviewProfile previewProfile = ResolvePartPreviewProfile(cacheEntry.previewSlot);
        ApplyVariantPreviewTextureToButton(
            button,
            cacheEntry.texture,
            ownsTexture: false,
            buttonSpriteScale: previewProfile.buttonSpriteScale,
            previewUvRect: cacheEntry.uvRect);
    }

    private static bool PreviewTextureHasVisibleContent(Texture2D texture)
    {
        return TryResolveVisiblePreviewUvRect(texture, out _);
    }

    private static bool TryResolveVisiblePreviewUvRect(Texture2D texture, out Rect uvRect)
    {
        return TryResolveVisiblePreviewUvRect(texture, DefaultPreviewUvPaddingScale, out uvRect);
    }

    private static bool TryResolveVisiblePreviewUvRect(Texture2D texture, float paddingScale, out Rect uvRect)
    {
        if (texture == null || texture.width <= 0 || texture.height <= 0)
        {
            uvRect = new Rect(0f, 0f, 1f, 1f);
            return false;
        }

        const int sampleCount = 64;
        int xSamples = Mathf.Min(sampleCount, texture.width);
        int ySamples = Mathf.Min(sampleCount, texture.height);
        Color backgroundColor = ResolvePreviewBackgroundColor(texture);
        bool transparentBackground = backgroundColor.a <= 0.5f;
        bool hasVisiblePixel = false;
        float minU = 1f;
        float minV = 1f;
        float maxU = 0f;
        float maxV = 0f;
        for (int y = 0; y < ySamples; y++)
        {
            float v = (y + 0.5f) / ySamples;
            for (int x = 0; x < xSamples; x++)
            {
                float u = (x + 0.5f) / xSamples;
                if (!IsPreviewSampleVisible(texture.GetPixelBilinear(u, v), backgroundColor, transparentBackground))
                {
                    continue;
                }

                hasVisiblePixel = true;
                minU = Mathf.Min(minU, u);
                minV = Mathf.Min(minV, v);
                maxU = Mathf.Max(maxU, u);
                maxV = Mathf.Max(maxV, v);
            }
        }

        if (!hasVisiblePixel)
        {
            uvRect = new Rect(0f, 0f, 1f, 1f);
            return false;
        }

        float width = Mathf.Max(0.01f, maxU - minU);
        float height = Mathf.Max(0.01f, maxV - minV);
        float centerU = (minU + maxU) * 0.5f;
        float centerV = (minV + maxV) * 0.5f;
        float resolvedPaddingScale = Mathf.Max(DefaultPreviewUvPaddingScale, paddingScale);
        float side = Mathf.Clamp(Mathf.Max(width, height) * resolvedPaddingScale, 0.05f, 1f);
        float halfSide = side * 0.5f;
        centerU = Mathf.Clamp(centerU, halfSide, 1f - halfSide);
        centerV = Mathf.Clamp(centerV, halfSide, 1f - halfSide);
        uvRect = new Rect(centerU - halfSide, centerV - halfSide, side, side);
        return true;
    }

    private static Color ResolvePreviewBackgroundColor(Texture2D texture)
    {
        if (texture == null || texture.width <= 0 || texture.height <= 0)
        {
            return Color.clear;
        }

        Color bottomLeft = texture.GetPixelBilinear(0.01f, 0.01f);
        Color bottomRight = texture.GetPixelBilinear(0.99f, 0.01f);
        Color topLeft = texture.GetPixelBilinear(0.01f, 0.99f);
        Color topRight = texture.GetPixelBilinear(0.99f, 0.99f);
        return (bottomLeft + bottomRight + topLeft + topRight) * 0.25f;
    }

    private static bool IsPreviewSampleVisible(Color sample, Color backgroundColor, bool transparentBackground)
    {
        const float alphaThreshold = 0.03f;
        const float backgroundColorDistanceThreshold = 0.008f;
        if (sample.a <= alphaThreshold)
        {
            return false;
        }

        if (transparentBackground)
        {
            return true;
        }

        Color sampleRgb = new Color(sample.r, sample.g, sample.b, 1f);
        Color backgroundRgb = new Color(backgroundColor.r, backgroundColor.g, backgroundColor.b, 1f);
        return ColorDistanceSquared(sampleRgb, backgroundRgb) > backgroundColorDistanceThreshold
               || Mathf.Abs(sample.a - backgroundColor.a) > 0.05f;
    }

    private static void DestroyPreviewTexture(Texture2D texture)
    {
        if (texture == null)
        {
            return;
        }

        if (Application.isPlaying)
        {
            Destroy(texture);
        }
        else
        {
            DestroyImmediate(texture);
        }
    }

    private void ApplyVariantPreviewTextureToButton(
        Button button,
        Texture previewTexture,
        bool ownsTexture,
        float buttonSpriteScale = 1f,
        Rect previewUvRect = default)
    {
        if (button == null || previewTexture == null)
        {
            return;
        }

        Text label = FindChildByNameIn<Text>(button.transform, "Label");
        if (label != null)
        {
            label.text = string.Empty;
            label.gameObject.SetActive(false);
        }

        TMP_Text tmpLabel = FindChildByNameIn<TMP_Text>(button.transform, "Label");
        tmpLabel ??= FindChildByNameIn<TMP_Text>(button.transform, "Text");
        if (tmpLabel != null)
        {
            tmpLabel.text = string.Empty;
            tmpLabel.gameObject.SetActive(false);
        }

        float previewContentScale = ResolvePreviewContentScale(buttonSpriteScale);
        Rect resolvedPreviewUvRect = previewUvRect.width > 0.0001f && previewUvRect.height > 0.0001f
            ? previewUvRect
            : new Rect(0f, 0f, 1f, 1f);
        if ((previewUvRect.width <= 0.0001f || previewUvRect.height <= 0.0001f)
            && previewTexture is Texture2D previewTexture2D
            && TryResolveVisiblePreviewUvRect(previewTexture2D, out Rect visibleUvRect))
        {
            resolvedPreviewUvRect = visibleUvRect;
        }

        CreateRoundedPreviewImage(button, previewTexture, RuntimePreviewRectInset, previewContentScale, resolvedPreviewUvRect);
        ConfigurePreviewVisualLikeSavedCharacter(button);

        if (ownsTexture && previewTexture is Texture2D ownedTexture)
        {
            variantPreviewTextures.Add(ownedTexture);
        }
    }

    private static float ResolvePreviewContentScale(float buttonSpriteScale)
    {
        return Mathf.Clamp(buttonSpriteScale * BodyPartPreviewContentScale, 0.05f, 4f);
    }

    private static void ConfigurePreviewVisualLikeSavedCharacter(Button button)
    {
        if (button == null)
        {
            return;
        }

        Transform preview = button.transform.Find("Preview");
        if (preview == null)
        {
            return;
        }

        Image previewBackground = preview.GetComponent<Image>();
        if (previewBackground != null)
        {
            bool rawImageOnPreview = preview.GetComponent<RawImage>() != null;
            Color backgroundColor = Color.white;
            if (rawImageOnPreview)
            {
                backgroundColor.a = 0f;
            }

            previewBackground.color = backgroundColor;
            previewBackground.raycastTarget = false;
        }

        Mask previewMask = preview.GetComponent<Mask>();
        if (previewMask != null)
        {
            previewMask.showMaskGraphic = preview.GetComponent<RawImage>() == null;
        }

        Transform frame = preview.Find("Frame");
        if (frame != null)
        {
            DestroyGameObjectSafely(frame.gameObject);
        }
    }

    private static void CreateRoundedPreviewImage(
        Button hostButton,
        Texture previewTexture,
        Vector2 inset,
        float contentScale = 1f,
        Rect uvRect = default)
    {
        if (hostButton == null || previewTexture == null)
        {
            return;
        }

        Transform existingPreview = hostButton.transform.Find("Preview");
        if (existingPreview != null)
        {
            if (TryApplyPreviewTextureToExistingPreview(existingPreview, previewTexture, inset, contentScale, uvRect))
            {
                return;
            }

            DestroyGameObjectSafely(existingPreview.gameObject);
        }

        RectTransform previewRect = CreateRect(
            "Preview",
            hostButton.transform,
            new Vector2(0f, 0f),
            new Vector2(1f, 1f),
            new Vector2(0.5f, 0.5f),
            Vector2.zero,
            Vector2.zero);
        previewRect.offsetMin = inset;
        previewRect.offsetMax = new Vector2(-inset.x, -inset.y);
        previewRect.SetSiblingIndex(0);

        Image styleSource = hostButton.targetGraphic as Image;
        Image maskImage = previewRect.GetComponent<Image>();
        if (maskImage == null)
        {
            maskImage = previewRect.gameObject.AddComponent<Image>();
        }

        CopyRoundedImageStyle(styleSource, maskImage);
        maskImage.color = Color.white;
        maskImage.raycastTarget = false;

        Mask mask = previewRect.GetComponent<Mask>();
        if (mask == null)
        {
            mask = previewRect.gameObject.AddComponent<Mask>();
        }

        mask.showMaskGraphic = false;

        RectTransform contentRect = CreateRect(
            "Content",
            previewRect,
            new Vector2(0f, 0f),
            new Vector2(1f, 1f),
            new Vector2(0.5f, 0.5f),
            Vector2.zero,
            Vector2.zero);
        contentRect.offsetMin = Vector2.zero;
        contentRect.offsetMax = Vector2.zero;
        float resolvedContentScale = Mathf.Clamp(contentScale, 0.05f, 4f);
        contentRect.localScale = new Vector3(resolvedContentScale, resolvedContentScale, 1f);

        RawImage previewImage = contentRect.gameObject.AddComponent<RawImage>();
        Rect resolvedUvRect = uvRect.width > 0.0001f && uvRect.height > 0.0001f
            ? uvRect
            : new Rect(0f, 0f, 1f, 1f);
        if ((uvRect.width <= 0.0001f || uvRect.height <= 0.0001f)
            && previewTexture is Texture2D previewTexture2D
            && TryResolveVisiblePreviewUvRect(previewTexture2D, out Rect visibleUvRect))
        {
            resolvedUvRect = visibleUvRect;
        }

        previewImage.texture = previewTexture;
        previewImage.uvRect = resolvedUvRect;
        previewImage.color = Color.white;
        previewImage.raycastTarget = false;

        Image frame = CreateRoundedFrame(previewRect, styleSource);
        if (frame != null)
        {
            frame.transform.SetAsLastSibling();
        }
    }

    private static bool TryApplyPreviewTextureToExistingPreview(
        Transform existingPreview,
        Texture previewTexture,
        Vector2 inset,
        float contentScale,
        Rect uvRect)
    {
        if (existingPreview == null || previewTexture == null)
        {
            return false;
        }

        RectTransform previewRect = existingPreview as RectTransform;
        if (previewRect == null)
        {
            return false;
        }

        previewRect.offsetMin = inset;
        previewRect.offsetMax = new Vector2(-inset.x, -inset.y);
        previewRect.SetSiblingIndex(0);
        existingPreview.gameObject.SetActive(true);

        Mask mask = existingPreview.GetComponent<Mask>();
        if (mask != null)
        {
            mask.showMaskGraphic = false;
        }

        Image previewBackground = existingPreview.GetComponent<Image>();
        RawImage previewImage = existingPreview.GetComponentInChildren<RawImage>(true);
        if (previewImage == null)
        {
            previewImage = existingPreview.GetComponent<RawImage>();
        }

        if (previewImage == null
            && previewBackground != null
            && TryApplyPreviewTextureToImage(previewBackground, previewTexture, contentScale, uvRect))
        {
            if (mask != null)
            {
                mask.showMaskGraphic = true;
            }

            return true;
        }

        if (previewBackground != null)
        {
            previewBackground.raycastTarget = false;
            Color backgroundColor = previewBackground.color;
            backgroundColor.a = 0f;
            previewBackground.color = backgroundColor;
        }

        if (previewImage == null)
        {
            previewImage = existingPreview.gameObject.AddComponent<RawImage>();
        }

        if (previewImage == null)
        {
            return false;
        }

        RectTransform imageRect = previewImage.transform as RectTransform;
        if (imageRect != null)
        {
            imageRect.anchorMin = Vector2.zero;
            imageRect.anchorMax = Vector2.one;
            imageRect.pivot = new Vector2(0.5f, 0.5f);
            imageRect.offsetMin = Vector2.zero;
            imageRect.offsetMax = Vector2.zero;
            float resolvedContentScale = Mathf.Clamp(contentScale, 0.05f, 4f);
            imageRect.localScale = new Vector3(resolvedContentScale, resolvedContentScale, 1f);
        }

        previewImage.texture = previewTexture;
        previewImage.uvRect = ResolvePreviewTextureUvRect(previewTexture, uvRect);
        previewImage.color = Color.white;
        previewImage.raycastTarget = false;
        previewImage.gameObject.SetActive(true);
        return true;
    }

    private static bool TryApplyPreviewTextureToImage(
        Image image,
        Texture previewTexture,
        float contentScale,
        Rect uvRect)
    {
        if (image == null || !(previewTexture is Texture2D texture2D))
        {
            return false;
        }

        Rect resolvedUvRect = ResolvePreviewTextureUvRect(previewTexture, uvRect);
        Rect pixelRect = new Rect(
            Mathf.Clamp01(resolvedUvRect.x) * texture2D.width,
            Mathf.Clamp01(resolvedUvRect.y) * texture2D.height,
            Mathf.Clamp01(resolvedUvRect.width) * texture2D.width,
            Mathf.Clamp01(resolvedUvRect.height) * texture2D.height);
        if (pixelRect.width < 1f || pixelRect.height < 1f)
        {
            pixelRect = new Rect(0f, 0f, texture2D.width, texture2D.height);
        }

        Sprite previewSprite = Sprite.Create(
            texture2D,
            pixelRect,
            new Vector2(0.5f, 0.5f),
            100f);
        if (previewSprite == null)
        {
            return false;
        }

        previewSprite.name = $"{texture2D.name}_PreviewSprite";
        previewSprite.hideFlags = HideFlags.HideAndDontSave;
        image.sprite = previewSprite;
        image.type = Image.Type.Simple;
        image.preserveAspect = true;
        image.color = Color.white;
        image.raycastTarget = false;

        RectTransform imageRect = image.transform as RectTransform;
        if (imageRect != null)
        {
            float resolvedContentScale = Mathf.Clamp(contentScale, 0.05f, 4f);
            imageRect.localScale = new Vector3(resolvedContentScale, resolvedContentScale, 1f);
        }

        image.gameObject.SetActive(true);
        return true;
    }

    private static Rect ResolvePreviewTextureUvRect(Texture previewTexture, Rect uvRect)
    {
        Rect resolvedUvRect = uvRect.width > 0.0001f && uvRect.height > 0.0001f
            ? uvRect
            : new Rect(0f, 0f, 1f, 1f);
        if ((uvRect.width <= 0.0001f || uvRect.height <= 0.0001f)
            && previewTexture is Texture2D previewTexture2D
            && TryResolveVisiblePreviewUvRect(previewTexture2D, out Rect visibleUvRect))
        {
            resolvedUvRect = visibleUvRect;
        }

        return resolvedUvRect;
    }

    private static Image CreateRoundedFrame(RectTransform previewRect, Image styleSource)
    {
        if (previewRect == null)
        {
            return null;
        }

        RectTransform frameRect = CreateRect(
            "Frame",
            previewRect,
            new Vector2(0f, 0f),
            new Vector2(1f, 1f),
            new Vector2(0.5f, 0.5f),
            Vector2.zero,
            Vector2.zero);
        frameRect.offsetMin = Vector2.zero;
        frameRect.offsetMax = Vector2.zero;

        Image frame = frameRect.gameObject.AddComponent<Image>();
        CopyRoundedImageStyle(styleSource, frame);
        frame.color = new Color(1f, 1f, 1f, 0.9f);
        frame.fillCenter = false;
        frame.raycastTarget = false;
        return frame;
    }

    private static void CopyRoundedImageStyle(Image source, Image target)
    {
        if (target == null)
        {
            return;
        }

        if (source != null && source.sprite != null)
        {
            target.sprite = source.sprite;
            target.type = source.type;
            target.fillMethod = source.fillMethod;
            target.fillOrigin = source.fillOrigin;
            target.fillClockwise = source.fillClockwise;
            target.fillAmount = source.fillAmount;
            target.preserveAspect = source.preserveAspect;
            target.useSpriteMesh = source.useSpriteMesh;
            target.pixelsPerUnitMultiplier = source.pixelsPerUnitMultiplier;
            return;
        }

        Sprite roundedSprite = ResolveRoundedUiSprite();
        if (roundedSprite != null)
        {
            target.sprite = roundedSprite;
            target.type = Image.Type.Sliced;
        }
    }

#if UNITY_EDITOR
    private bool TryGetInspectorVariantPreviewTexture(int variantIndex, out Texture previewTexture)
    {
        previewTexture = null;
        if (customizer == null || variantIndex < 0)
        {
            return false;
        }

        List<MinimoCharacterCustomizer.PartSlot> candidateSlots = BuildPreviewCandidateSlots();
        if (candidateSlots.Count == 0)
        {
            return false;
        }

        for (int i = 0; i < candidateSlots.Count; i++)
        {
            MinimoCharacterCustomizer.PartSlot slot = candidateSlots[i];
            if (!customizer.TryGetVariantSourcePrefabForSlot(slot, variantIndex, out GameObject sourcePrefab) || sourcePrefab == null)
            {
                continue;
            }

            previewTexture = AssetPreview.GetAssetPreview(sourcePrefab);
            if (previewTexture != null)
            {
                if (TryCreatePreparedPreviewTextureCopy(
                        previewTexture,
                        FixedVariantPreviewTextureResolution,
                        out Texture2D preparedPreviewTexture))
                {
                    previewTexture = preparedPreviewTexture;
                    variantPreviewTextures.Add(preparedPreviewTexture);
                }

                return true;
            }
        }

        return false;
    }
#endif

    private bool TryGetBestVariantPreviewData(
        int variantIndex,
        out MinimoCharacterCustomizer.PartSlot previewSlot,
        out Mesh previewMesh,
        out Material[] previewMaterials,
        out Bounds previewBounds,
        out Quaternion previewRotationHint,
        MinimoCharacterCustomizer.PartSlot? preferredPreviewSlot = null,
        bool includeGlobalFallback = true)
    {
        previewSlot = default;
        previewMesh = null;
        previewMaterials = Array.Empty<Material>();
        previewBounds = default;
        previewRotationHint = Quaternion.identity;
        if (customizer == null)
        {
            return false;
        }

        List<MinimoCharacterCustomizer.PartSlot> candidates = BuildPreviewCandidateSlots(
            preferredPreviewSlot,
            includeGlobalFallback);

        for (int i = 0; i < candidates.Count; i++)
        {
            MinimoCharacterCustomizer.PartSlot slot = candidates[i];
            if (customizer.TryGetVariantPartPreviewData(
                    variantIndex,
                    slot,
                    out previewMesh,
                    out previewMaterials,
                    out previewBounds,
                    out previewRotationHint))
            {
                previewSlot = slot;
                return true;
            }
        }

        return false;
    }

    private Texture2D RenderVariantPreviewTexture(
        MinimoCharacterCustomizer.PartSlot previewSlot,
        Mesh mesh,
        Material[] materials,
        Bounds localBounds,
        Quaternion previewRotationHint,
        bool suppressSkinToneOverride = false)
    {
        if (mesh == null)
        {
            return null;
        }

        if (!EnsureVariantPreviewRenderer())
        {
            return null;
        }

        PartPreviewProfile previewProfile = ResolvePartPreviewProfile(previewSlot);
        if (!EnsureVariantPreviewRenderTexture(previewProfile.previewResolution))
        {
            return null;
        }

        variantPreviewMeshFilter.sharedMesh = mesh;
        Material[] resolvedMaterials = ResolvePreviewMaterials(mesh, materials);
        if (resolvedMaterials != null && resolvedMaterials.Length > 0)
        {
            variantPreviewMeshRenderer.sharedMaterials = resolvedMaterials;
        }
        else
        {
            variantPreviewMeshRenderer.sharedMaterial = null;
        }

        int materialCount = resolvedMaterials != null ? resolvedMaterials.Length : 0;
        for (int i = 0; i < materialCount; i++)
        {
            variantPreviewMeshRenderer.SetPropertyBlock(null, i);
        }

        ApplyPreviewMaterialBoosts(previewSlot, resolvedMaterials, suppressSkinToneOverride);

        Bounds renderBounds = localBounds.size.sqrMagnitude > 0.000001f
            ? localBounds
            : mesh.bounds;
        Bounds meshBounds = mesh.bounds;
        if (meshBounds.size.sqrMagnitude > 0.000001f)
        {
            renderBounds.center = meshBounds.center;
            if (renderBounds.size.sqrMagnitude <= 0.000001f)
            {
                renderBounds.size = meshBounds.size;
            }
        }

        Bounds rotatedRenderBounds = RotateBoundsBy(renderBounds, previewProfile.rotation);
        Vector3 screenNudge = ResolvePreviewScreenNudgeWorld(previewProfile.positionOffsetNormalized, rotatedRenderBounds.extents);
        variantPreviewMeshFilter.transform.localPosition = -renderBounds.center + screenNudge;
        _ = previewRotationHint;
        variantPreviewMeshFilter.transform.localRotation = previewProfile.rotation;
        variantPreviewMeshFilter.transform.localScale = Vector3.one;

        float aspect = variantPreviewRenderTexture != null && variantPreviewRenderTexture.height > 0
            ? variantPreviewRenderTexture.width / (float)variantPreviewRenderTexture.height
            : 1f;
        float halfWidth = Mathf.Max(0.05f, rotatedRenderBounds.extents.x);
        float halfHeight = Mathf.Max(0.05f, rotatedRenderBounds.extents.y);
        float orthoSizeFromWidth = aspect > 0.0001f ? halfWidth / aspect : halfWidth;
        float meshScale = Mathf.Max(0.01f, previewProfile.meshScale);
        float orthoSize = Mathf.Max(halfHeight, orthoSizeFromWidth)
                          * previewProfile.orthoPadding
                          * Mathf.Max(0.01f, previewProfile.sizeMultiplier)
                          * (1f / meshScale);
        float depth = Mathf.Max(0.15f, rotatedRenderBounds.extents.z * 2f);
        float cameraDistance = Mathf.Max(1.6f, depth * 1.6f);

        variantPreviewCamera.transform.localPosition = new Vector3(0f, 0f, -cameraDistance);
        variantPreviewCamera.transform.localRotation = Quaternion.identity;
        variantPreviewCamera.orthographic = true;
        variantPreviewCamera.orthographicSize = orthoSize;
        variantPreviewCamera.nearClipPlane = 0.01f;
        variantPreviewCamera.farClipPlane = cameraDistance + depth * 4f + 2f;
        variantPreviewCamera.backgroundColor = PreviewBackgroundColor;
        ConfigureBrightPreviewLighting();

        return RenderVariantPreviewToTexture2D();
    }

    private Material[] ResolvePreviewMaterials(Mesh mesh, Material[] sourceMaterials)
    {
        if (sourceMaterials != null && sourceMaterials.Length > 0)
        {
            Material[] copied = new Material[sourceMaterials.Length];
            Array.Copy(sourceMaterials, copied, sourceMaterials.Length);
            return copied;
        }

        int requiredCount = mesh != null ? Mathf.Max(1, mesh.subMeshCount) : 1;
        Material[] resolved = new Material[requiredCount];
        return resolved;
    }

    private void ApplyPreviewMaterialBoosts(
        MinimoCharacterCustomizer.PartSlot previewSlot,
        Material[] previewMaterials,
        bool suppressSkinToneOverride = false)
    {
        if (variantPreviewMeshRenderer == null || previewMaterials == null || previewMaterials.Length == 0)
        {
            return;
        }

        Color skinToneColor = Color.white;
        bool hasSkinTone = !suppressSkinToneOverride && TryGetCurrentSkinToneColor(out skinToneColor);
        variantPreviewMaterialPropertyBlock ??= new MaterialPropertyBlock();
        for (int i = 0; i < previewMaterials.Length; i++)
        {
            Material material = previewMaterials[i];
            if (material == null)
            {
                continue;
            }

            variantPreviewMaterialPropertyBlock.Clear();
            if (!PopulatePreviewMaterialPropertyBlock(
                    material,
                    variantPreviewMaterialPropertyBlock,
                    previewSlot,
                    hasSkinTone,
                    skinToneColor))
            {
                continue;
            }

            variantPreviewMeshRenderer.SetPropertyBlock(variantPreviewMaterialPropertyBlock, i);
        }
    }

    private void ApplyPreviewMaterialBoostsToRenderers(GameObject root)
    {
        if (root == null)
        {
            return;
        }

        Renderer[] renderers = root.GetComponentsInChildren<Renderer>(true);
        if (renderers == null || renderers.Length == 0)
        {
            return;
        }

        variantPreviewMaterialPropertyBlock ??= new MaterialPropertyBlock();
        for (int rendererIndex = 0; rendererIndex < renderers.Length; rendererIndex++)
        {
            Renderer renderer = renderers[rendererIndex];
            if (renderer == null)
            {
                continue;
            }

            Material[] materials = renderer.sharedMaterials;
            int materialCount = materials != null ? materials.Length : 0;
            for (int materialIndex = 0; materialIndex < materialCount; materialIndex++)
            {
                Material material = materials[materialIndex];
                if (material == null)
                {
                    continue;
                }

                renderer.GetPropertyBlock(variantPreviewMaterialPropertyBlock, materialIndex);
                if (!PopulatePreviewMaterialPropertyBlock(
                        material,
                        variantPreviewMaterialPropertyBlock,
                        null,
                        false,
                        Color.white))
                {
                    continue;
                }

                renderer.SetPropertyBlock(variantPreviewMaterialPropertyBlock, materialIndex);
            }
        }
    }

    private static bool PopulatePreviewMaterialPropertyBlock(
        Material material,
        MaterialPropertyBlock block,
        MinimoCharacterCustomizer.PartSlot? previewSlot,
        bool hasSkinTone,
        Color skinToneColor)
    {
        if (material == null || block == null)
        {
            return false;
        }

        bool changed = false;
        bool shouldUseSkinTone = hasSkinTone
                                 && previewSlot.HasValue
                                 && (IsSkinSlot(previewSlot.Value)
                                     || (previewSlot.Value == MinimoCharacterCustomizer.PartSlot.Torso
                                         && MaterialLooksLikeSkin(material))
                                     || MaterialLooksLikeSkin(material));
        for (int i = 0; i < VisualColorPropertyIds.Length; i++)
        {
            int propertyId = VisualColorPropertyIds[i];
            bool hasBlockColor = block.HasColor(propertyId);
            if (!hasBlockColor && !material.HasProperty(propertyId))
            {
                continue;
            }

            Color sourceColor = hasBlockColor
                ? block.GetColor(propertyId)
                : material.GetColor(propertyId);
            Color previewColor = ResolvePreviewMaterialColor(
                sourceColor,
                propertyId,
                shouldUseSkinTone,
                skinToneColor);
            block.SetColor(propertyId, previewColor);
            changed = true;
        }

        return changed;
    }

    private static Color ResolvePreviewMaterialColor(
        Color sourceColor,
        int propertyId,
        bool shouldUseSkinTone,
        Color skinToneColor)
    {
        if (shouldUseSkinTone)
        {
            if (propertyId == ColorShaderProperty || propertyId == BaseColorShaderProperty)
            {
                return BrightenPreviewMaterialColor(skinToneColor, false);
            }

            if (propertyId == HighlightShaderProperty)
            {
                return BrightenPreviewMaterialColor(
                    DerivePreviewSkinToneColor(skinToneColor, PreviewSkinReferenceHighlightColor),
                    false);
            }

            if (propertyId == ShadowShaderProperty)
            {
                return BrightenPreviewMaterialColor(
                    DerivePreviewSkinToneColor(skinToneColor, PreviewSkinReferenceShadowColor),
                    true);
            }
        }

        return BrightenPreviewMaterialColor(sourceColor, propertyId == ShadowShaderProperty);
    }

    private static Color BrightenPreviewMaterialColor(Color color, bool shadowColor)
    {
        if (Mathf.Approximately(PreviewMaterialValueBoost, 1f)
            && Mathf.Approximately(PreviewMaterialValueLift, 0f)
            && Mathf.Approximately(PreviewMaterialSaturationBoost, 1f))
        {
            return color;
        }

        float alpha = color.a;
        Color.RGBToHSV(
            new Color(Mathf.Clamp01(color.r), Mathf.Clamp01(color.g), Mathf.Clamp01(color.b), 1f),
            out float h,
            out float s,
            out float v);

        float minValue = shadowColor ? 0.30f : 0.36f;
        float resolvedValue = Mathf.Clamp01(Mathf.Max((v * PreviewMaterialValueBoost) + PreviewMaterialValueLift, minValue));
        float resolvedSaturation = Mathf.Clamp01(s * PreviewMaterialSaturationBoost);
        Color result = Color.HSVToRGB(h, resolvedSaturation, resolvedValue);
        result.a = alpha;
        return result;
    }

    private void ApplyPreviewSkinToneOverrides(
        MinimoCharacterCustomizer.PartSlot previewSlot,
        Material[] previewMaterials)
    {
        if (variantPreviewMeshRenderer == null
            || previewMaterials == null
            || previewMaterials.Length == 0
            || !TryGetCurrentSkinToneColor(out Color skinToneColor))
        {
            return;
        }

        variantPreviewMaterialPropertyBlock ??= new MaterialPropertyBlock();
        for (int i = 0; i < previewMaterials.Length; i++)
        {
            Material material = previewMaterials[i];
            if (material == null || !MaterialSupportsColor(material))
            {
                continue;
            }

            bool shouldUseSkinTone = IsSkinSlot(previewSlot)
                                     || (previewSlot == MinimoCharacterCustomizer.PartSlot.Torso && MaterialLooksLikeSkin(material))
                                     || MaterialLooksLikeSkin(material);
            if (!shouldUseSkinTone)
            {
                continue;
            }

            variantPreviewMaterialPropertyBlock.Clear();
            if (material.HasProperty(ColorShaderProperty))
            {
                variantPreviewMaterialPropertyBlock.SetColor(ColorShaderProperty, skinToneColor);
            }

            if (material.HasProperty(BaseColorShaderProperty))
            {
                variantPreviewMaterialPropertyBlock.SetColor(BaseColorShaderProperty, skinToneColor);
            }

            if (material.HasProperty(HighlightShaderProperty))
            {
                variantPreviewMaterialPropertyBlock.SetColor(
                    HighlightShaderProperty,
                    DerivePreviewSkinToneColor(skinToneColor, PreviewSkinReferenceHighlightColor));
            }

            if (material.HasProperty(ShadowShaderProperty))
            {
                variantPreviewMaterialPropertyBlock.SetColor(
                    ShadowShaderProperty,
                    DerivePreviewSkinToneColor(skinToneColor, PreviewSkinReferenceShadowColor));
            }

            variantPreviewMeshRenderer.SetPropertyBlock(variantPreviewMaterialPropertyBlock, i);
        }
    }

    private bool TryGetCurrentSkinToneColor(out Color skinToneColor)
    {
        skinToneColor = Color.white;
        if (customizer == null)
        {
            return false;
        }

        for (int i = 0; i < SkinToneSlots.Length; i++)
        {
            MinimoCharacterCustomizer.PartSlot slot = SkinToneSlots[i];
            if (!customizer.TryGetPartRenderer(slot, out SkinnedMeshRenderer renderer) || renderer == null)
            {
                continue;
            }

            Material[] materials = renderer.sharedMaterials;
            if (materials == null || materials.Length == 0)
            {
                continue;
            }

            for (int materialIndex = 0; materialIndex < materials.Length; materialIndex++)
            {
                Material material = materials[materialIndex];
                if (material == null || !MaterialSupportsColor(material))
                {
                    continue;
                }

                if (!IsSkinMaterialTarget(slot, materialIndex))
                {
                    continue;
                }

                if (TryGetEffectivePartColor(slot, materialIndex, out skinToneColor))
                {
                    return true;
                }
            }
        }

        return false;
    }

    private void ReapplySkinToneToCharacter(
        Color skinToneColor,
        bool includeFace = true,
        MinimoCharacterCustomizer.PartSlot[] targetSlots = null)
    {
        if (customizer == null)
        {
            return;
        }

        List<(MinimoCharacterCustomizer.PartSlot slot, int materialIndex, Color color)> colorAssignments = new List<(MinimoCharacterCustomizer.PartSlot slot, int materialIndex, Color color)>();
        for (int i = 0; i < SkinToneSlots.Length; i++)
        {
            MinimoCharacterCustomizer.PartSlot slot = SkinToneSlots[i];
            if (!includeFace && slot == MinimoCharacterCustomizer.PartSlot.Face)
            {
                continue;
            }

            if (targetSlots != null
                && targetSlots.Length > 0
                && !SlotArrayContains(targetSlots, slot))
            {
                continue;
            }

            if (!customizer.TryGetPartRenderer(slot, out SkinnedMeshRenderer renderer) || renderer == null)
            {
                continue;
            }

            Material[] materials = renderer.sharedMaterials;
            if (materials == null || materials.Length == 0)
            {
                continue;
            }

            bool appliedAny = false;
            for (int materialIndex = 0; materialIndex < materials.Length; materialIndex++)
            {
                Material material = materials[materialIndex];
                if (material == null || !MaterialSupportsColor(material))
                {
                    continue;
                }

                bool shouldApply = IsSkinMaterialTarget(slot, materialIndex);
                if (!shouldApply)
                {
                    continue;
                }

                colorAssignments.Add((slot, materialIndex, skinToneColor));
                appliedAny = true;
            }

            if (!appliedAny && slot == MinimoCharacterCustomizer.PartSlot.Face)
            {
                colorAssignments.Add((slot, -1, skinToneColor));
            }
        }

        customizer.SetPartColors(colorAssignments);
    }

    private static Color DerivePreviewSkinToneColor(Color skinToneColor, Color referenceTone)
    {
        return DeriveToneColorFromReference(skinToneColor, PreviewSkinReferenceBaseColor, referenceTone);
    }

    private static Color DeriveToneColorFromReference(Color inputBaseColor, Color referenceBase, Color referenceTone)
    {
        return DeriveToneColorFromReference(inputBaseColor, referenceBase, referenceTone, preserveToneAlpha: false);
    }

    private static Color DeriveToneColorFromReference(
        Color inputBaseColor,
        Color referenceBase,
        Color referenceTone,
        bool preserveToneAlpha)
    {
        Color.RGBToHSV(referenceBase, out float refH, out float refS, out float refV);
        Color.RGBToHSV(referenceTone, out float toneH, out float toneS, out float toneV);
        Color.RGBToHSV(inputBaseColor, out float inputH, out float inputS, out float inputV);

        float hueDelta = Mathf.DeltaAngle(refH * 360f, toneH * 360f) / 360f;
        float saturationDelta = toneS - refS;
        float valueScale = refV > 0.0001f ? toneV / refV : toneV;

        float resultH = Mathf.Repeat(inputH + hueDelta, 1f);
        float resultS = Mathf.Clamp01(inputS + saturationDelta);
        float resultV = Mathf.Clamp01(inputV * valueScale);

        Color result = Color.HSVToRGB(resultH, resultS, resultV);
        if (preserveToneAlpha)
        {
            float alphaScale = referenceBase.a > 0.0001f ? referenceTone.a / referenceBase.a : referenceTone.a;
            result.a = Mathf.Clamp01(inputBaseColor.a * alphaScale);
        }
        else
        {
            result.a = inputBaseColor.a;
        }

        return result;
    }

    private float ResolveAdjustedPreviewProfileSizeMultiplier(
        MinimoCharacterCustomizer.PartSlot slot,
        float baseSizeMultiplier)
    {
        float resolvedBase = Mathf.Max(0.01f, baseSizeMultiplier);
        float slotMeshSize = 1f;
        if (TryResolvePartPreviewMeshSizeOverride(slot, out float overrideMeshSize))
        {
            slotMeshSize = overrideMeshSize;
        }

        float globalMeshSize = Mathf.Max(0.05f, variantPreviewGlobalMeshSize);
        float combinedMeshSize = Mathf.Max(0.05f, slotMeshSize * globalMeshSize);
        // Existing profile size behaves inverse (bigger value -> smaller preview mesh),
        // so divide by mesh-size controls to keep inspector values intuitive.
        return Mathf.Max(0.01f, resolvedBase / combinedMeshSize);
    }

    private bool TryResolvePartPreviewMeshSizeOverride(
        MinimoCharacterCustomizer.PartSlot slot,
        out float meshSize)
    {
        meshSize = 1f;
        if (partPreviewMeshSizeOverrides == null || partPreviewMeshSizeOverrides.Length == 0)
        {
            return false;
        }

        bool found = false;
        for (int i = 0; i < partPreviewMeshSizeOverrides.Length; i++)
        {
            PartPreviewMeshSizeOverride entry = partPreviewMeshSizeOverrides[i];
            if (entry == null || entry.slot != slot)
            {
                continue;
            }

            meshSize = Mathf.Max(0.05f, entry.meshSize);
            found = true;
        }

        return found;
    }

    private PartPreviewProfile ResolvePartPreviewProfile(MinimoCharacterCustomizer.PartSlot slot)
    {
        int defaultPreviewResolution = FixedVariantPreviewTextureResolution;
        PartPreviewProfile profile = new PartPreviewProfile()
        {
            rotation = Quaternion.Euler(0f, 0f, 0f),
            orthoPadding = 1.12f,
            positionOffsetNormalized = Vector2.zero,
            sizeMultiplier = 1f,
            meshScale = 1f,
            buttonSpriteScale = 1f,
            uvPaddingScale = DefaultPreviewUvPaddingScale,
            previewResolution = defaultPreviewResolution
        };

        switch (slot)
        {
            case MinimoCharacterCustomizer.PartSlot.Hair:
                profile.rotation = Quaternion.Euler(-90f, 90f, 0f);
                profile.orthoPadding = 1.00f;
                profile.positionOffsetNormalized = new Vector2(0f, 0f);
                profile.sizeMultiplier = 2f;
                profile.meshScale = 1f;
                profile.buttonSpriteScale = 0.75f;
                profile.previewResolution = defaultPreviewResolution;
                break;
            case MinimoCharacterCustomizer.PartSlot.Face:
                profile.rotation = Quaternion.Euler(-90f, 180f, 0f);
                profile.orthoPadding = 3.00f;
                profile.positionOffsetNormalized = new Vector2(0f, 0f);
                profile.sizeMultiplier = 1f;
                profile.meshScale = 1f;
                profile.buttonSpriteScale = 0.75f;
                profile.previewResolution = defaultPreviewResolution;
                break;
            case MinimoCharacterCustomizer.PartSlot.ShoulderLeft:
                profile.rotation = Quaternion.Euler(0f, 90f, 90f);
                profile.orthoPadding = 3.00f;
                profile.positionOffsetNormalized = new Vector2(0f, 0f);
                profile.sizeMultiplier = 1f;
                profile.meshScale = 1f;
                profile.buttonSpriteScale = 0.75f;
                profile.previewResolution = defaultPreviewResolution;
                break;
            case MinimoCharacterCustomizer.PartSlot.ShoulderRight:
                profile.rotation = Quaternion.Euler(0f, -90f, -90f);
                profile.orthoPadding = 3.00f;
                profile.positionOffsetNormalized = new Vector2(0f, 0f);
                profile.sizeMultiplier = 1f;
                profile.meshScale = 1f;
                profile.buttonSpriteScale = 0.75f;
                profile.previewResolution = defaultPreviewResolution;
                break;
            case MinimoCharacterCustomizer.PartSlot.ArmLeft:
                profile.rotation = Quaternion.Euler(0f, 180f, 90f);
                profile.orthoPadding = 3.00f;
                profile.positionOffsetNormalized = new Vector2(0f, 0f);
                profile.sizeMultiplier = 1f;
                profile.meshScale = 1f;
                profile.buttonSpriteScale = 0.75f;
                profile.previewResolution = defaultPreviewResolution;
                break;
            case MinimoCharacterCustomizer.PartSlot.ArmRight:
                profile.rotation = Quaternion.Euler(0f, 0f, -90f);
                profile.orthoPadding = 3.00f;
                profile.positionOffsetNormalized = new Vector2(0f, 0f);
                profile.sizeMultiplier = 1f;
                profile.meshScale = 1f;
                profile.buttonSpriteScale = 0.75f;
                profile.previewResolution = defaultPreviewResolution;
                break;
            case MinimoCharacterCustomizer.PartSlot.HandLeft:
                profile.rotation = Quaternion.Euler(0f, 0f, -90f);
                profile.orthoPadding = 3.00f;
                profile.positionOffsetNormalized = new Vector2(0f, 0f);
                profile.sizeMultiplier = 1f;
                profile.meshScale = 1f;
                profile.buttonSpriteScale = 0.75f;
                profile.previewResolution = defaultPreviewResolution;
                break;
            case MinimoCharacterCustomizer.PartSlot.HandRight:
                profile.rotation = Quaternion.Euler(0f, 0f, 90f);
                profile.orthoPadding = 3.00f;
                profile.positionOffsetNormalized = new Vector2(0f, 0f);
                profile.sizeMultiplier = 1f;
                profile.meshScale = 1f;
                profile.buttonSpriteScale = 0.75f;
                profile.previewResolution = defaultPreviewResolution;
                break;
            case MinimoCharacterCustomizer.PartSlot.Hips:
                profile.rotation = Quaternion.Euler(-90f, 180f, 0f);
                profile.orthoPadding = 3.00f;
                profile.positionOffsetNormalized = new Vector2(0f, 0f);
                profile.sizeMultiplier = 1f;
                profile.meshScale = 1f;
                profile.buttonSpriteScale = 0.75f;
                profile.previewResolution = defaultPreviewResolution;
                break;
            case MinimoCharacterCustomizer.PartSlot.Torso:
                profile.rotation = Quaternion.Euler(-90f, 180f, 0f);
                profile.orthoPadding = 3.50f;
                profile.positionOffsetNormalized = new Vector2(0f, 0f);
                profile.sizeMultiplier = 1f;
                profile.meshScale = 1f;
                profile.buttonSpriteScale = 0.75f;
                profile.previewResolution = defaultPreviewResolution;
                break;
            case MinimoCharacterCustomizer.PartSlot.LegUpperLeft:
            case MinimoCharacterCustomizer.PartSlot.LegUpperRight:
                profile.rotation = Quaternion.Euler(-90f, 0f, 180f);
                profile.orthoPadding = 10.00f;
                profile.positionOffsetNormalized = new Vector2(0f, 0f);
                profile.sizeMultiplier = 1f;
                profile.meshScale = 1f;
                profile.buttonSpriteScale = 0.75f;
                profile.previewResolution = defaultPreviewResolution;
                break;
            case MinimoCharacterCustomizer.PartSlot.BootsLeft:
                profile.rotation = Quaternion.Euler(-90f, 150f, 0f);
                profile.orthoPadding = 3.00f;
                profile.positionOffsetNormalized = new Vector2(0f, 0f);
                profile.sizeMultiplier = 1.5f;
                profile.meshScale = 1f;
                profile.buttonSpriteScale = 0.75f;
                profile.previewResolution = defaultPreviewResolution;
                break;
            case MinimoCharacterCustomizer.PartSlot.BootsRight:
                profile.rotation = Quaternion.Euler(-90f, 210f, 0f);
                profile.orthoPadding = 3.00f;
                profile.positionOffsetNormalized = new Vector2(0f, 0f);
                profile.sizeMultiplier = 1.5f;
                profile.meshScale = 1f;
                profile.buttonSpriteScale = 0.75f;
                profile.previewResolution = defaultPreviewResolution;
                break;
            case MinimoCharacterCustomizer.PartSlot.Props:
                profile.rotation = Quaternion.Euler(0f, 180f, 45f);
                profile.orthoPadding = 3.00f;
                profile.positionOffsetNormalized = new Vector2(0f, 0f);
                profile.sizeMultiplier = 1f;
                profile.meshScale = 1f;
                profile.buttonSpriteScale = 0.75f;
                profile.previewResolution = defaultPreviewResolution;
                break;
        }

        profile.sizeMultiplier = ResolveAdjustedPreviewProfileSizeMultiplier(slot, profile.sizeMultiplier);
        profile.orthoPadding = Mathf.Max(
            0.85f,
            profile.orthoPadding * Mathf.Clamp(variantPreviewCameraPaddingScale, 0.35f, 2.5f));
        profile.meshScale = Mathf.Max(0.01f, profile.meshScale);
        profile.uvPaddingScale = ResolvePreviewUvPaddingScale(slot);
        float slotButtonScale = IsLegOrFootPreviewSlot(slot) ? LegFootPreviewContentScale : 1f;
        float uvPaddingCompensation = profile.uvPaddingScale / DefaultPreviewUvPaddingScale;
        profile.buttonSpriteScale = Mathf.Clamp(
            variantPreviewButtonImageScale * slotButtonScale * uvPaddingCompensation,
            0.05f,
            4f);
        return profile;
    }

    private static float ResolvePreviewUvPaddingScale(MinimoCharacterCustomizer.PartSlot slot)
    {
        return IsLegOrFootPreviewSlot(slot) ? LegFootPreviewUvPaddingScale : DefaultPreviewUvPaddingScale;
    }

    private static bool IsLegOrFootPreviewSlot(MinimoCharacterCustomizer.PartSlot slot)
    {
        return slot == MinimoCharacterCustomizer.PartSlot.LegUpperLeft
               || slot == MinimoCharacterCustomizer.PartSlot.LegUpperRight
               || slot == MinimoCharacterCustomizer.PartSlot.BootsLeft
               || slot == MinimoCharacterCustomizer.PartSlot.BootsRight;
    }

    private PartPreviewProfile ResolvePropPreviewProfile(
        string _rigName,
        string _prefabName)
    {
        // Props preview tuning is controlled directly by ResolvePartPreviewProfile(PartSlot.Props)
        // so changing the Props switch case updates angle/padding/position/size/resolution
        // exactly like other part slots.
        return ResolvePartPreviewProfile(MinimoCharacterCustomizer.PartSlot.Props);
    }

    private bool TryResolvePropPreviewOverride(
        string normalizedRigName,
        string prefabName,
        out PropPreviewProfileOverride matchedOverride)
    {
        matchedOverride = null;
        if (propPreviewOverrides == null || propPreviewOverrides.Length == 0)
        {
            return false;
        }

        string normalizedPrefabName = NormalizeBodyRegionKey(prefabName);
        int bestScore = int.MinValue;
        for (int i = 0; i < propPreviewOverrides.Length; i++)
        {
            PropPreviewProfileOverride candidate = propPreviewOverrides[i];
            int score = ScorePropPreviewOverride(candidate, normalizedRigName, normalizedPrefabName);
            if (score <= bestScore)
            {
                continue;
            }

            bestScore = score;
            matchedOverride = candidate;
        }

        return matchedOverride != null;
    }

    private static int ScorePropPreviewOverride(
        PropPreviewProfileOverride candidate,
        string normalizedRigName,
        string normalizedPrefabName)
    {
        if (candidate == null)
        {
            return int.MinValue;
        }

        int score = 0;
        string candidateRig = NormalizeBodyRegionKey(candidate.rigName);
        if (!string.IsNullOrWhiteSpace(candidateRig))
        {
            if (!string.Equals(candidateRig, normalizedRigName, StringComparison.Ordinal))
            {
                return int.MinValue;
            }

            score += 100;
        }

        string prefabToken = NormalizeBodyRegionKey(candidate.prefabNameContains);
        if (!string.IsNullOrWhiteSpace(prefabToken))
        {
            if (string.IsNullOrWhiteSpace(normalizedPrefabName)
                || normalizedPrefabName.IndexOf(prefabToken, StringComparison.Ordinal) < 0)
            {
                return int.MinValue;
            }

            score += 10 + prefabToken.Length;
        }

        return score <= 0 ? 1 : score;
    }

    private static PartPreviewProfile BuildPropPreviewProfileFromValues(
        Vector3 rotationEuler,
        float orthoPadding,
        Vector2 positionOffsetNormalized,
        float sizeMultiplier,
        int previewResolution)
    {
        return new PartPreviewProfile
        {
            rotation = Quaternion.Euler(rotationEuler),
            orthoPadding = Mathf.Max(0.01f, orthoPadding),
            positionOffsetNormalized = positionOffsetNormalized,
            sizeMultiplier = Mathf.Max(0.01f, sizeMultiplier),
            meshScale = 1f,
            buttonSpriteScale = 1f,
            previewResolution = ClampPreviewResolution(previewResolution)
        };
    }

    private static int ClampPreviewResolution(int previewResolution, bool applyRuntimeHudCap = true)
    {
        int clamped = Mathf.Clamp(previewResolution, 64, MaxPreviewTextureResolution);
        if (applyRuntimeHudCap && Application.isPlaying)
        {
            return Mathf.Min(clamped, RuntimeHudPreviewTextureResolution);
        }

        return clamped;
    }

    private static Vector3 ResolvePreviewScreenNudgeWorld(Vector2 screenOffsetNormalized, Vector3 extents)
    {
        if (screenOffsetNormalized.sqrMagnitude <= 0.0000001f)
        {
            return Vector3.zero;
        }

        float shiftX = screenOffsetNormalized.x * extents.x;
        float shiftY = -screenOffsetNormalized.y * extents.y;
        return new Vector3(shiftX, shiftY, 0f);
    }

    private static Bounds RotateBoundsBy(Bounds bounds, Quaternion rotation)
    {
        Vector3[] corners = GetBoundsCorners(bounds);
        if (corners == null || corners.Length == 0)
        {
            return bounds;
        }

        Vector3 first = rotation * corners[0];
        Bounds rotated = new Bounds(first, Vector3.zero);
        for (int i = 1; i < corners.Length; i++)
        {
            rotated.Encapsulate(rotation * corners[i]);
        }

        return rotated;
    }

    private static Quaternion ResolvePreviewModelRotation(
        MinimoCharacterCustomizer.PartSlot previewSlot,
        Bounds renderBounds,
        Vector3 cameraForward,
        Quaternion previewRotationHint)
    {
        if (previewRotationHint == default)
        {
            previewRotationHint = Quaternion.identity;
        }

        Quaternion[] candidates = ResolvePreviewRotationCandidates(previewSlot);
        if (candidates == null || candidates.Length == 0)
        {
            return previewRotationHint;
        }

        Quaternion cameraRotation = Quaternion.LookRotation(cameraForward.normalized, Vector3.up);
        Quaternion best = candidates[0] * previewRotationHint;
        float bestScore = float.MinValue;
        for (int i = 0; i < candidates.Length; i++)
        {
            Quaternion candidateA = candidates[i] * previewRotationHint;
            float scoreA = ScorePreviewRotationCandidate(candidateA, renderBounds, cameraRotation);
            if (scoreA > bestScore)
            {
                bestScore = scoreA;
                best = candidateA;
            }

            Quaternion candidateB = previewRotationHint * candidates[i];
            float scoreB = ScorePreviewRotationCandidate(candidateB, renderBounds, cameraRotation);
            if (scoreB > bestScore)
            {
                bestScore = scoreB;
                best = candidateB;
            }
        }

        return best;
    }

    private static Quaternion[] ResolvePreviewRotationCandidates(MinimoCharacterCustomizer.PartSlot previewSlot)
    {
        if (previewSlot == MinimoCharacterCustomizer.PartSlot.Hair
            || previewSlot == MinimoCharacterCustomizer.PartSlot.Face)
        {
            return new[]
            {
                Quaternion.Euler(90f, 180f, 0f),
                Quaternion.Euler(0f, 180f, 0f),
                Quaternion.Euler(0f, 90f, 0f),
                Quaternion.Euler(0f, -90f, 0f)
            };
        }

        if (previewSlot == MinimoCharacterCustomizer.PartSlot.ArmLeft
            || previewSlot == MinimoCharacterCustomizer.PartSlot.ArmRight
            || previewSlot == MinimoCharacterCustomizer.PartSlot.HandLeft
            || previewSlot == MinimoCharacterCustomizer.PartSlot.HandRight
            || previewSlot == MinimoCharacterCustomizer.PartSlot.ShoulderLeft
            || previewSlot == MinimoCharacterCustomizer.PartSlot.ShoulderRight)
        {
            return new[]
            {
                Quaternion.Euler(0f, 90f, 0f),
                Quaternion.Euler(0f, -90f, 0f),
                Quaternion.Euler(0f, 180f, 0f),
                Quaternion.Euler(0f, 0f, 0f),
                Quaternion.Euler(90f, 180f, 0f),
                Quaternion.Euler(90f, 90f, 0f),
                Quaternion.Euler(90f, -90f, 0f)
            };
        }

        return new[]
        {
            Quaternion.Euler(0f, 180f, 0f),
            Quaternion.Euler(0f, 90f, 0f),
            Quaternion.Euler(0f, -90f, 0f),
            Quaternion.Euler(0f, 0f, 0f),
            Quaternion.Euler(90f, 180f, 0f),
            Quaternion.Euler(90f, 0f, 0f)
        };
    }

    private static float ScorePreviewRotationCandidate(
        Quaternion modelRotation,
        Bounds renderBounds,
        Quaternion cameraRotation)
    {
        Vector3[] corners = GetBoundsCorners(renderBounds);
        float minX = float.MaxValue;
        float maxX = float.MinValue;
        float minY = float.MaxValue;
        float maxY = float.MinValue;
        float minZ = float.MaxValue;
        float maxZ = float.MinValue;
        Quaternion invCamera = Quaternion.Inverse(cameraRotation);
        for (int i = 0; i < corners.Length; i++)
        {
            Vector3 modelPoint = modelRotation * corners[i];
            Vector3 cameraPoint = invCamera * modelPoint;
            minX = Mathf.Min(minX, cameraPoint.x);
            maxX = Mathf.Max(maxX, cameraPoint.x);
            minY = Mathf.Min(minY, cameraPoint.y);
            maxY = Mathf.Max(maxY, cameraPoint.y);
            minZ = Mathf.Min(minZ, cameraPoint.z);
            maxZ = Mathf.Max(maxZ, cameraPoint.z);
        }

        float width = Mathf.Max(0.0001f, maxX - minX);
        float height = Mathf.Max(0.0001f, maxY - minY);
        float depth = Mathf.Max(0.0001f, maxZ - minZ);
        return (width * height) / depth;
    }

    private static Vector3[] GetBoundsCorners(Bounds bounds)
    {
        Vector3 c = bounds.center;
        Vector3 e = bounds.extents;
        return new[]
        {
            c + new Vector3(-e.x, -e.y, -e.z),
            c + new Vector3(-e.x, -e.y,  e.z),
            c + new Vector3(-e.x,  e.y, -e.z),
            c + new Vector3(-e.x,  e.y,  e.z),
            c + new Vector3( e.x, -e.y, -e.z),
            c + new Vector3( e.x, -e.y,  e.z),
            c + new Vector3( e.x,  e.y, -e.z),
            c + new Vector3( e.x,  e.y,  e.z)
        };
    }

    private bool EnsureVariantPreviewRenderer()
    {
        if (variantPreviewRoot != null && variantPreviewPrefabRoot != null
            && variantPreviewMeshFilter != null && variantPreviewMeshRenderer != null
            && variantPreviewCamera != null && variantPreviewKeyLight != null && variantPreviewFillLight != null)
        {
            return true;
        }

        DisposeVariantPreviewRenderer();

        variantPreviewRoot = new GameObject("MinimoVariantPreviewRoot");
        variantPreviewRoot.hideFlags = HideFlags.HideAndDontSave;
        variantPreviewRoot.transform.position = new Vector3(9000f, -9000f, 9000f);

        GameObject prefabRoot = new GameObject("PrefabRoot");
        prefabRoot.hideFlags = HideFlags.HideAndDontSave;
        prefabRoot.transform.SetParent(variantPreviewRoot.transform, false);
        variantPreviewPrefabRoot = prefabRoot.transform;

        GameObject meshRoot = new GameObject("Mesh");
        meshRoot.hideFlags = HideFlags.HideAndDontSave;
        meshRoot.transform.SetParent(variantPreviewRoot.transform, false);
        variantPreviewMeshFilter = meshRoot.AddComponent<MeshFilter>();
        variantPreviewMeshRenderer = meshRoot.AddComponent<MeshRenderer>();

        GameObject cameraRoot = new GameObject("Camera");
        cameraRoot.hideFlags = HideFlags.HideAndDontSave;
        cameraRoot.transform.SetParent(variantPreviewRoot.transform, false);
        variantPreviewCamera = cameraRoot.AddComponent<Camera>();
        variantPreviewCamera.enabled = false;
        variantPreviewCamera.clearFlags = CameraClearFlags.SolidColor;
        variantPreviewCamera.allowHDR = false;
        variantPreviewCamera.allowMSAA = ShouldUseMsaaForPreviewCapture();
        ConfigurePreviewCameraForSharpCapture(variantPreviewCamera);

        GameObject keyLightRoot = new GameObject("KeyLight");
        keyLightRoot.hideFlags = HideFlags.HideAndDontSave;
        keyLightRoot.transform.SetParent(variantPreviewRoot.transform, false);
        variantPreviewKeyLight = keyLightRoot.AddComponent<Light>();
        variantPreviewKeyLight.type = LightType.Directional;
        variantPreviewKeyLight.intensity = PreviewKeyLightIntensity;
        variantPreviewKeyLight.color = PreviewKeyLightColor;
        variantPreviewKeyLight.shadows = LightShadows.None;

        GameObject fillLightRoot = new GameObject("FillLight");
        fillLightRoot.hideFlags = HideFlags.HideAndDontSave;
        fillLightRoot.transform.SetParent(variantPreviewRoot.transform, false);
        variantPreviewFillLight = fillLightRoot.AddComponent<Light>();
        variantPreviewFillLight.type = LightType.Directional;
        variantPreviewFillLight.intensity = PreviewFillLightIntensity;
        variantPreviewFillLight.color = PreviewFillLightColor;
        variantPreviewFillLight.shadows = LightShadows.None;

        return true;
    }

    private static void ConfigurePreviewCameraForSharpCapture(Camera camera)
    {
        if (camera == null)
        {
            return;
        }

        camera.allowHDR = false;
        camera.allowMSAA = ShouldUseMsaaForPreviewCapture();
        camera.usePhysicalProperties = false;
        camera.depthTextureMode = DepthTextureMode.None;
        camera.clearFlags = CameraClearFlags.SolidColor;
        camera.backgroundColor = PreviewBackgroundColor;
    }

    private static bool ShouldUseMsaaForPreviewCapture()
    {
#if UNITY_6000_0_OR_NEWER
        return true;
#else
        return false;
#endif
    }

    private void ConfigureBrightPreviewLighting()
    {
        if (variantPreviewKeyLight != null)
        {
            variantPreviewKeyLight.transform.localRotation = Quaternion.Euler(35f, 180f, 0f);
            variantPreviewKeyLight.intensity = PreviewKeyLightIntensity;
            variantPreviewKeyLight.color = PreviewKeyLightColor;
        }

        if (variantPreviewFillLight != null)
        {
            variantPreviewFillLight.transform.localRotation = Quaternion.Euler(320f, 180f, 0f);
            variantPreviewFillLight.intensity = PreviewFillLightIntensity;
            variantPreviewFillLight.color = PreviewFillLightColor;
        }
    }

    private bool EnsureVariantPreviewRenderTexture(
        int preferredSize = -1,
        int antiAliasing = VariantPreviewAntiAliasing,
        bool applyRuntimeHudCap = true)
    {
        int requestedSize = preferredSize > 0 ? preferredSize : variantPreviewTextureSize;
        int size = ClampPreviewResolution(requestedSize, applyRuntimeHudCap);
        int resolvedAntiAliasing = NormalizeRenderTextureAntiAliasing(antiAliasing);
        if (variantPreviewTextureSize != size)
        {
            variantPreviewTextureSize = size;
        }

        if (variantPreviewRenderTexture != null
            && variantPreviewRenderTexture.width == size
            && variantPreviewRenderTexture.height == size
            && variantPreviewRenderTexture.antiAliasing == resolvedAntiAliasing)
        {
            return true;
        }

        if (variantPreviewRenderTexture != null)
        {
            variantPreviewRenderTexture.Release();
            if (Application.isPlaying)
            {
                Destroy(variantPreviewRenderTexture);
            }
            else
            {
                DestroyImmediate(variantPreviewRenderTexture);
            }
        }

        variantPreviewRenderTexture = new RenderTexture(size, size, 24, RenderTextureFormat.ARGB32)
        {
            hideFlags = HideFlags.HideAndDontSave,
            antiAliasing = resolvedAntiAliasing,
            filterMode = FilterMode.Bilinear,
            wrapMode = TextureWrapMode.Clamp,
            useMipMap = false,
            autoGenerateMips = false
        };
        return true;
    }

    private static int NormalizeRenderTextureAntiAliasing(int antiAliasing)
    {
#if !UNITY_6000_0_OR_NEWER
        return 1;
#else
        if (antiAliasing >= 8)
        {
            return 8;
        }

        if (antiAliasing >= 4)
        {
            return 4;
        }

        if (antiAliasing >= 2)
        {
            return 2;
        }

        return 1;
#endif
    }

    private void ClearVariantPreviewTextures()
    {
        for (int i = 0; i < variantPreviewTextures.Count; i++)
        {
            Texture2D texture = variantPreviewTextures[i];
            if (texture == null)
            {
                continue;
            }

            if (Application.isPlaying)
            {
                Destroy(texture);
            }
            else
            {
                DestroyImmediate(texture);
            }
        }

        variantPreviewTextures.Clear();
    }

    private void ClearPreviewTextureCache()
    {
        ClearPreviewTextureCache(variantPreviewTextureCache);
        ClearPreviewTextureCache(propPreviewTextureCache);
        previewCachePrewarmed = false;
    }

    private static void ClearPreviewTextureCache(Dictionary<string, PreviewTextureCacheEntry> cache)
    {
        if (cache == null)
        {
            return;
        }

        foreach (PreviewTextureCacheEntry entry in cache.Values)
        {
            Texture2D texture = entry?.texture;
            if (texture == null)
            {
                continue;
            }

            if (Application.isPlaying)
            {
                Destroy(texture);
            }
            else
            {
                DestroyImmediate(texture);
            }
        }

        cache.Clear();
    }

    private void ClearSavedPrefabPreviewTextures()
    {
        for (int i = 0; i < savedPrefabPreviewTextures.Count; i++)
        {
            Texture2D texture = savedPrefabPreviewTextures[i];
            if (texture == null)
            {
                continue;
            }

            if (Application.isPlaying)
            {
                Destroy(texture);
            }
            else
            {
                DestroyImmediate(texture);
            }
        }

        savedPrefabPreviewTextures.Clear();
    }

    private void DisposeVariantPreviewRenderer()
    {
        if (variantPreviewRenderTexture != null)
        {
            variantPreviewRenderTexture.Release();
            if (Application.isPlaying)
            {
                Destroy(variantPreviewRenderTexture);
            }
            else
            {
                DestroyImmediate(variantPreviewRenderTexture);
            }
        }

        if (variantPreviewRoot != null)
        {
            if (Application.isPlaying)
            {
                Destroy(variantPreviewRoot);
            }
            else
            {
                DestroyImmediate(variantPreviewRoot);
            }
        }

        variantPreviewRenderTexture = null;
        variantPreviewRoot = null;
        variantPreviewPrefabRoot = null;
        variantPreviewMeshFilter = null;
        variantPreviewMeshRenderer = null;
        variantPreviewCamera = null;
        variantPreviewKeyLight = null;
        variantPreviewFillLight = null;
    }

    private void BuildColorPaletteButtons()
    {
        if (colorPanelContent == null)
        {
            return;
        }

        Color[] activePalette = GetActivePaletteColors();
        if (activePalette == null || activePalette.Length == 0)
        {
            activePalette = paletteColors;
        }

        if (activePalette == null || activePalette.Length == 0)
        {
            return;
        }

        List<Button> sceneColorButtons = GetSceneColorButtons();
        int targetButtonCount = Mathf.Max(PaletteSwatchCount, sceneColorButtons.Count);
        Transform colorButtonParent = ResolveColorPaletteButtonRoot();
        if (colorButtonParent == null)
        {
            colorButtonParent = colorPanelContent;
        }

        for (int i = 0; i < targetButtonCount; i++)
        {
            Color paletteColor = ResolvePaletteColorForSwatch(activePalette, i, targetButtonCount);
            Button button = i < sceneColorButtons.Count
                ? sceneColorButtons[i]
                : CreateColorButton(colorButtonParent, paletteColor, i);

            RemoveShadowPressTracking(button);
            ConfigureColorButtonVisual(button, paletteColor);
            ColorButtonEntry entry = new ColorButtonEntry()
            {
                color = paletteColor,
                button = button,
                background = button.targetGraphic as Image,
                selectionOutline = EnsureColorSelectionOutline(button)
            };
            colorButtons.Add(entry);
            EnsureColorButtonSelectable(entry, i);
        }
    }

    private BodyPartsScrollSnapshot CaptureBodyPartsScrollPosition()
    {
        BodyPartsScrollSnapshot snapshot = new BodyPartsScrollSnapshot
        {
            valid = false,
            normalizedPosition = 1f,
            contentAnchoredY = 0f,
            hasContentAnchoredPosition = false
        };

        if (bodyPartsScroll == null)
        {
            return snapshot;
        }

        snapshot.valid = true;
        snapshot.normalizedPosition = Mathf.Clamp01(bodyPartsScroll.verticalNormalizedPosition);

        RectTransform content = bodyPartsScroll.content;
        if (content != null)
        {
            snapshot.contentAnchoredY = content.anchoredPosition.y;
            snapshot.hasContentAnchoredPosition = true;
        }

        return snapshot;
    }

    private void RestoreBodyPartsScrollPosition(BodyPartsScrollSnapshot snapshot)
    {
        if (bodyPartsScroll == null || !snapshot.valid)
        {
            return;
        }

        Canvas.ForceUpdateCanvases();
        if (bodyPartsContent != null)
        {
            LayoutRebuilder.ForceRebuildLayoutImmediate(bodyPartsContent);
        }

        if (snapshot.hasContentAnchoredPosition
            && bodyPartsScroll.content != null
            && bodyPartsScroll.viewport != null)
        {
            RectTransform content = bodyPartsScroll.content;
            RectTransform viewport = bodyPartsScroll.viewport;
            float maxY = Mathf.Max(0f, content.rect.height - viewport.rect.height);
            float targetY = Mathf.Clamp(snapshot.contentAnchoredY, 0f, maxY);
            Vector2 anchored = content.anchoredPosition;
            anchored.y = targetY;
            content.anchoredPosition = anchored;
        }
        else
        {
            bodyPartsScroll.verticalNormalizedPosition = Mathf.Clamp01(snapshot.normalizedPosition);
        }

        bodyPartsScroll.StopMovement();
        Canvas.ForceUpdateCanvases();
    }

    private void UnbindColorEvents()
    {
        for (int i = 0; i < colorButtons.Count; i++)
        {
            colorButtons[i]?.button?.onClick.RemoveAllListeners();
        }
    }

    private int GetExpectedColorButtonCount(Color[] activePalette)
    {
        _ = activePalette;
        return Mathf.Max(PaletteSwatchCount, GetSceneColorButtons().Count);
    }

    private bool IsColorPaletteVisualUpToDate(Color[] palette)
    {
        if (palette == null || palette.Length == 0)
        {
            return colorButtons.Count == 0;
        }

        int swatchCount = GetExpectedColorButtonCount(palette);
        if (swatchCount <= 0 || colorButtons.Count != swatchCount)
        {
            return false;
        }

        for (int i = 0; i < swatchCount; i++)
        {
            Color expectedColor = ResolvePaletteColorForSwatch(palette, i, swatchCount);
            ColorButtonEntry current = colorButtons[i];
            if (current == null || !ColorsNearlyEqual(current.color, expectedColor))
            {
                return false;
            }
        }

        return true;
    }

    private void EnsureVisibleColorButtonsSelectable()
    {
        for (int i = 0; i < colorButtons.Count; i++)
        {
            EnsureColorButtonSelectable(colorButtons[i], i);
        }
    }

    private void EnsureColorButtonSelectable(ColorButtonEntry entry, int paletteIndex)
    {
        if (entry?.button == null)
        {
            return;
        }

        Button button = entry.button;
        EnsureColorButtonInteractionState(entry);

        Color capturedColor = entry.color;
        int capturedIndex = paletteIndex;
        button.onClick.RemoveAllListeners();
        button.onClick.AddListener(() => ApplyColorToSelectedRegion(capturedColor, capturedIndex));
    }

    private void EnsureColorButtonInteractionState(ColorButtonEntry entry)
    {
        if (entry?.button == null)
        {
            return;
        }

        Button button = entry.button;
        Image image = entry.background;
        if (image == null)
        {
            image = button.targetGraphic as Image;
        }

        if (image == null)
        {
            image = button.GetComponent<Image>();
        }

        if (image != null)
        {
            image.raycastTarget = true;
            button.targetGraphic = image;
            entry.background = image;
        }

        button.interactable = controlsInteractable;
    }

    private List<Button> GetSceneColorButtons()
    {
        List<Button> buttons = new List<Button>();
        Transform colorButtonRoot = ResolveColorPaletteButtonRoot();
        if (colorButtonRoot == null)
        {
            return buttons;
        }

        HashSet<int> addedButtonIds = new HashSet<int>();
        CollectSceneColorButtons(colorButtonRoot, buttons, addedButtonIds);
        return buttons;
    }

    private Transform ResolveColorPaletteButtonRoot()
    {
        if (colorPanelRoot != null)
        {
            RectTransform colorGroup = FindChildByNameIn<RectTransform>(colorPanelRoot, "ColorGroup");
            if (colorGroup != null)
            {
                return colorGroup;
            }
        }

        return colorPanelContent;
    }

    private void CollectSceneColorButtons(Transform root, List<Button> buttons, HashSet<int> addedButtonIds)
    {
        if (root == null || buttons == null)
        {
            return;
        }

        Transform protectedHeaderTransform = colorPanelHeaderLabel != null ? colorPanelHeaderLabel.transform : null;
        for (int i = 0; i < root.childCount; i++)
        {
            Transform child = root.GetChild(i);
            if (child == null)
            {
                continue;
            }

            if (protectedHeaderTransform != null && (child == protectedHeaderTransform || child.IsChildOf(protectedHeaderTransform)))
            {
                continue;
            }

            if (IsColorRuntimeTemplateTransform(child))
            {
                child.gameObject.SetActive(false);
                continue;
            }

            if (IsRuntimeGeneratedColorPanelEntry(child) && !IsRuntimeColorPaletteButtonEntry(child))
            {
                continue;
            }

            if (TryResolveSceneColorPaletteButton(child, out Button button))
            {
                int instanceId = button.gameObject.GetInstanceID();
                if (addedButtonIds != null && !addedButtonIds.Add(instanceId))
                {
                    continue;
                }

                buttons.Add(button);
                continue;
            }

            CollectSceneColorButtons(child, buttons, addedButtonIds);
        }
    }

    private bool TryResolveSceneColorPaletteButton(Transform child, out Button button)
    {
        button = null;
        if (child == null || !IsColorPaletteButtonTransform(child))
        {
            return false;
        }

        Image image = child.GetComponent<Image>();
        button = child.GetComponent<Button>();
        if (image == null && button == null)
        {
            return false;
        }

        if (image == null)
        {
            image = child.gameObject.AddComponent<Image>();
        }

        if (button == null)
        {
            button = child.gameObject.AddComponent<Button>();
        }

        button.targetGraphic = image;

        if (randomColorButton != null && button == randomColorButton)
        {
            return false;
        }

        if (colorChartButton != null && button == colorChartButton)
        {
            return false;
        }

        return true;
    }

    private static bool IsColorPaletteButtonTransform(Transform child)
    {
        if (child == null)
        {
            return false;
        }

        string name = child.name ?? string.Empty;
        return string.Equals(name, "ColorButton", StringComparison.OrdinalIgnoreCase)
               || name.StartsWith("Color_", StringComparison.Ordinal)
               || name.StartsWith("RuntimeColor_", StringComparison.Ordinal);
    }

    private static Color ResolvePaletteColorForSwatch(Color[] palette, int swatchIndex, int swatchCount)
    {
        if (palette == null || palette.Length == 0)
        {
            return Color.white;
        }

        if (palette.Length == 1 || swatchCount <= 1)
        {
            return palette[0];
        }

        float normalized = Mathf.Clamp01(swatchIndex / (float)(swatchCount - 1));
        int paletteIndex = Mathf.Clamp(Mathf.RoundToInt(normalized * (palette.Length - 1)), 0, palette.Length - 1);
        return palette[paletteIndex];
    }

    private static void ConfigureColorButtonVisual(Button button, Color color)
    {
        if (button == null)
        {
            return;
        }

        Image image = button.targetGraphic as Image;
        if (image == null)
        {
            image = button.GetComponent<Image>();
            if (image == null)
            {
                image = button.gameObject.AddComponent<Image>();
            }

            button.targetGraphic = image;
        }

        image.color = color;
        image.raycastTarget = true;
        button.interactable = true;
        button.gameObject.SetActive(true);
        ApplyButtonInteractionStyle(button, color);
    }

    private static bool IsRuntimeGeneratedColorPanelEntry(Transform child)
    {
        if (child == null)
        {
            return false;
        }

        string name = child.name ?? string.Empty;
        return name.StartsWith("Color_", StringComparison.Ordinal)
               || name.StartsWith("Part_", StringComparison.Ordinal)
               || name.StartsWith("RuntimeColor_", StringComparison.Ordinal)
               || name.StartsWith("ColorChannel_", StringComparison.Ordinal);
    }

    private static bool IsRuntimeColorPaletteButtonEntry(Transform child)
    {
        if (child == null)
        {
            return false;
        }

        string name = child.name ?? string.Empty;
        return name.StartsWith("Color_", StringComparison.Ordinal);
    }

    private void BuildColorChannelButtons(Font font)
    {
        _ = font;
        UnbindColorChannelEvents();
        colorChannelButtons.Clear();

        if (customizer == null || selectedRegionIndex < 0 || selectedRegionIndex >= regions.Count)
        {
            return;
        }

        RectTransform stripRoot = ResolveMaterialChannelStripRoot();
        if (stripRoot == null)
        {
            return;
        }

        bool propsMode = IsPropsRegionSelectionMode();
        MinimoCharacterCustomizer.PartSlot anchorSlot = MinimoCharacterCustomizer.PartSlot.Torso;
        List<ColorChannelDescriptor> descriptors = new List<ColorChannelDescriptor>();
        if (propsMode)
        {
            List<PropMaterialChannel> propChannels = BuildColorChannelDescriptorsForSelectedProp();
            for (int channelIndex = 0; channelIndex < propChannels.Count; channelIndex++)
            {
                PropMaterialChannel channel = propChannels[channelIndex];
                if (channel == null)
                {
                    continue;
                }

                descriptors.Add(new ColorChannelDescriptor
                {
                    label = channel.label,
                    materialIndex = channelIndex,
                    targetType = ColorChannelTargetType.Material,
                    facePropertyId = -1
                });
            }
        }
        else
        {
            MinimoCharacterCustomizer.PartSlot[] targetSlots = GetTargetSlotsForColorOperations();
            if (targetSlots.Length == 0)
            {
                stripRoot.gameObject.SetActive(false);
                return;
            }

            anchorSlot = selectedWorldColorTargetSlot ?? targetSlots[0];
            descriptors = BuildColorChannelDescriptorsForSlot(anchorSlot);
        }

        if (descriptors.Count == 0)
        {
            SetMaterialChannelStripButtonsActive(stripRoot, false);
            stripRoot.gameObject.SetActive(false);
            return;
        }

        bool hasSelectedDescriptor = false;
        for (int i = 0; i < descriptors.Count; i++)
        {
            ColorChannelDescriptor descriptor = descriptors[i];
            if (descriptor == null)
            {
                continue;
            }

            bool sameType = descriptor.targetType == selectedColorChannelTarget;
            if (!sameType)
            {
                continue;
            }

            if (selectedColorChannelTarget == ColorChannelTargetType.Material)
            {
                if (descriptor.materialIndex == selectedColorMaterialIndex)
                {
                    hasSelectedDescriptor = true;
                    break;
                }

                continue;
            }

            if (descriptor.facePropertyId == selectedFaceColorPropertyId)
            {
                hasSelectedDescriptor = true;
                break;
            }
        }

        if (!hasSelectedDescriptor)
        {
            ColorChannelDescriptor fallback = descriptors[0];
            selectedColorChannelTarget = fallback.targetType;
            selectedColorMaterialIndex = Mathf.Max(0, fallback.materialIndex);
            selectedFaceColorPropertyId = fallback.targetType == ColorChannelTargetType.Material
                ? -1
                : fallback.facePropertyId;
        }

        List<MaterialChannelStripButtonView> buttonViews = PrepareMaterialChannelButtons(stripRoot, descriptors.Count);
        int buildCount = Mathf.Min(descriptors.Count, buttonViews.Count);
        for (int i = 0; i < buildCount; i++)
        {
            ColorChannelDescriptor descriptor = descriptors[i];
            MaterialChannelStripButtonView view = buttonViews[i];
            if (descriptor == null || view?.button == null)
            {
                continue;
            }

            Button button = view.button;
            RemoveShadowPressTracking(button);
            button.enabled = true;
            button.interactable = true;
            button.onClick.RemoveAllListeners();
            ColorChannelTargetType capturedTargetType = descriptor.targetType;
            int capturedMaterialIndex = descriptor.materialIndex;
            int capturedFacePropertyId = descriptor.facePropertyId;
            button.onClick.AddListener(() => SelectColorChannel(capturedTargetType, capturedMaterialIndex, capturedFacePropertyId));

            Color channelColor = ResolveColorChannelSwatchColor(anchorSlot, descriptor);
            if (view.swatch != null)
            {
                view.swatch.color = channelColor;
            }

            Image background = (view.background != null && view.background != view.swatch)
                ? view.background
                : ResolveMaterialChannelButtonBackground(button);
            if (background != null)
            {
                background.raycastTarget = true;
                button.targetGraphic = background;
            }

            if (view.swatch == null && background != null)
            {
                background.color = channelColor;
            }

            int instanceId = button.gameObject.GetInstanceID();
            if (background != null && !materialChannelBaseBackgroundColors.ContainsKey(instanceId))
            {
                materialChannelBaseBackgroundColors[instanceId] = background.color;
            }

            Color defaultBackgroundColor = background != null
                && materialChannelBaseBackgroundColors.TryGetValue(instanceId, out Color cachedBackgroundColor)
                ? cachedBackgroundColor
                : UiSurfaceSecondaryColor;
            if (view.swatch == null)
            {
                defaultBackgroundColor = channelColor;
            }

            colorChannelButtons.Add(new ColorChannelButtonEntry
            {
                materialIndex = descriptor.materialIndex,
                targetType = descriptor.targetType,
                facePropertyId = descriptor.facePropertyId,
                label = descriptor.label,
                button = button,
                background = background,
                defaultBackgroundColor = defaultBackgroundColor,
                swatch = view.swatch,
                selectionOutline = EnsureColorSelectionOutline(button)
            });
        }

        UpdateMaterialChannelSelectionVisuals();
        bool showStrip = colorChannelButtons.Count > 0 && (partsPanelRoot == null || partsPanelRoot.gameObject.activeSelf);
        stripRoot.gameObject.SetActive(showStrip);
        RefreshMaterialChannelStripLayout(stripRoot);
    }

    private void UpdateWorldLinkedSelectionUi()
    {
        if (IsSavedPanelActive())
        {
            SetWorldLinkedSelectionUiVisible(false);
            return;
        }

        if (!showWorldLinkedSelectionUi)
        {
            SetWorldLinkedSelectionUiVisible(false);
            return;
        }

        if (!TryGetCurrentWorldLinkedMaterialTargets(out Dictionary<MinimoCharacterCustomizer.PartSlot, HashSet<int>> linkedTargets))
        {
            SetWorldLinkedSelectionUiVisible(false);
            return;
        }

        if (!EnsureWorldLinkedSelectionUi())
        {
            return;
        }

        string selectionGroupKey = worldLinkedMaterialSelectionKey;
        if (string.IsNullOrWhiteSpace(selectionGroupKey))
        {
            selectionGroupKey = worldLinkedSlotSelectionKey;
            if (string.IsNullOrWhiteSpace(selectionGroupKey)
                && selectedWorldColorTargetSlot.HasValue)
            {
                int anchorMaterialIndex = ResolveColorMaterialIndexForSlot(
                    selectedWorldColorTargetSlot.Value,
                    selectedColorMaterialIndex);
                if (anchorMaterialIndex >= 0
                    && TryGetWorldLinkedMaterialKey(
                        selectedWorldColorTargetSlot.Value,
                        anchorMaterialIndex,
                        out string resolvedKey))
                {
                    selectionGroupKey = resolvedKey;
                }
            }

            worldLinkedMaterialSelectionKey = selectionGroupKey;
            worldLinkedMaterialSelectionKeyValid = !string.IsNullOrWhiteSpace(selectionGroupKey);
            if (worldLinkedMaterialSelectionKeyValid)
            {
                worldLinkedSlotSelectionKey = selectionGroupKey;
            }
        }

        if (!string.IsNullOrWhiteSpace(selectionGroupKey))
        {
            SetWorldLinkedSlotSelectionStateForGroup(
                selectionGroupKey,
                linkedTargets,
                selectedWorldColorTargetSlot,
                focusOnly: false,
                preserveExistingForSameKey: true);
        }
        UpdateWorldLinkedSingleOverrideFromSelection(linkedTargets);
        EnsureActiveWorldLinkedSlotSelection(linkedTargets);

        if (worldLinkedSelectionUiSlotOrder.Count == 0)
        {
            worldLinkedSelectionUiSlotOrder.AddRange(GetOrderedWorldLinkedSlots(linkedTargets));
            HashSet<MinimoCharacterCustomizer.PartSlot> existingSlots = new HashSet<MinimoCharacterCustomizer.PartSlot>(worldLinkedSelectionUiSlotOrder);
            for (int i = 0; i < PartSelectionUiOrder.Length; i++)
            {
                MinimoCharacterCustomizer.PartSlot slot = PartSelectionUiOrder[i];
                if (!worldLinkedSlotSelectionStates.ContainsKey(slot) || existingSlots.Contains(slot))
                {
                    continue;
                }

                worldLinkedSelectionUiSlotOrder.Add(slot);
                existingSlots.Add(slot);
            }

            foreach (KeyValuePair<MinimoCharacterCustomizer.PartSlot, bool> pair in worldLinkedSlotSelectionStates)
            {
                if (existingSlots.Contains(pair.Key))
                {
                    continue;
                }

                worldLinkedSelectionUiSlotOrder.Add(pair.Key);
                existingSlots.Add(pair.Key);
            }
        }

        List<MinimoCharacterCustomizer.PartSlot> orderedSlots = new List<MinimoCharacterCustomizer.PartSlot>();
        for (int i = 0; i < worldLinkedSelectionUiSlotOrder.Count; i++)
        {
            MinimoCharacterCustomizer.PartSlot slot = worldLinkedSelectionUiSlotOrder[i];
            if (HasColorTargetsForWorldLinkedSlot(linkedTargets, slot))
            {
                orderedSlots.Add(slot);
            }
        }

        if (orderedSlots.Count == 0)
        {
            SetWorldLinkedSelectionUiVisible(false);
            return;
        }

        SyncWorldLinkedSlotToggleButtons(orderedSlots.Count);
        if (worldLinkedSlotToggleButtons.Count <= 0)
        {
            SetWorldLinkedSelectionUiVisible(false);
            return;
        }

        int selectedCount = 0;
        for (int i = 0; i < orderedSlots.Count; i++)
        {
            if (IsWorldLinkedSlotSelected(orderedSlots[i]))
            {
                selectedCount++;
            }
        }
        int totalCount = orderedSlots.Count;
        if (worldLinkedSelectionUiHeaderLabel != null)
        {
            worldLinkedSelectionUiHeaderLabel.text = $"Linked Parts {selectedCount}/{totalCount}";
        }

        if (worldLinkedSelectionUiHeaderTmpLabel != null)
        {
            worldLinkedSelectionUiHeaderTmpLabel.text = $"Linked Parts {selectedCount}/{totalCount}";
        }

        UpdateWorldLinkedSelectionContentPosY(totalCount);
        UpdateWorldLinkedSelectionPanelHeight(totalCount);

        for (int i = 0; i < worldLinkedSlotToggleButtons.Count; i++)
        {
            WorldLinkedSlotToggleEntry entry = worldLinkedSlotToggleButtons[i];
            if (entry?.button == null)
            {
                continue;
            }

            bool active = i < orderedSlots.Count;
            entry.button.gameObject.SetActive(active);
            if (!active)
            {
                continue;
            }

            MinimoCharacterCustomizer.PartSlot slot = orderedSlots[i];
            entry.slot = slot;
            bool slotSelected = IsWorldLinkedSlotSelected(slot);
            Color slotCategoryColor = ResolveWorldLinkedSlotCategoryColor(slot);
            Material slotCategorySpriteMaterial = ResolveWorldLinkedSlotCategorySpriteMaterial(slot);
            string slotLabel = slot.ToString();
            string stateText = slotSelected
                ? $"{slotLabel} [ON]"
                : $"{slotLabel} [OFF]";
            Color stateColor = slotSelected
                ? new Color(0.95f, 0.98f, 1f, 1f)
                : new Color(0.72f, 0.8f, 0.9f, 1f);
            if (entry.label != null)
            {
                entry.label.text = stateText;
                entry.label.color = stateColor;
            }

            if (entry.tmpLabel != null)
            {
                entry.tmpLabel.text = stateText;
                entry.tmpLabel.color = stateColor;
            }

            if (entry.background != null)
            {
                entry.background.material = slotCategorySpriteMaterial;
            }
            ApplyWorldLinkedSlotButtonVisual(entry.button, slotCategoryColor, slotCategorySpriteMaterial);

            DisableWorldLinkedSlotOutlines(entry.button);

            entry.button.onClick.RemoveAllListeners();
            entry.button.interactable = true;
            MinimoCharacterCustomizer.PartSlot capturedSlot = slot;
            entry.button.onClick.AddListener(() => HandleWorldLinkedSlotToggleClicked(capturedSlot));
            EnsureShadowPressTracking(entry.button, allowWithoutShadowTarget: true);
        }

        SetWorldLinkedSelectionUiVisible(true);
        RefreshWorldLinkedSelectionSlotLayout();
    }

    private void RefreshWorldLinkedSelectionSlotLayout()
    {
        if (worldLinkedSelectionUiContentRoot == null)
        {
            return;
        }

        Canvas.ForceUpdateCanvases();
        LayoutRebuilder.ForceRebuildLayoutImmediate(worldLinkedSelectionUiContentRoot);

        if (worldLinkedSelectionUiContentRoot.parent is RectTransform parentRect)
        {
            LayoutRebuilder.ForceRebuildLayoutImmediate(parentRect);
        }
    }

    private void UpdateWorldLinkedSelectionContentPosY(int partCount)
    {
        // Preserve the scene-authored header-to-content spacing.
    }

    private void UpdateWorldLinkedSelectionPanelHeight(int visibleButtonCount)
    {
        if (worldLinkedSelectionUiRoot == null || worldLinkedSelectionUiContentRoot == null || visibleButtonCount <= 0)
        {
            return;
        }

        RectTransform resizeChild = ResolveWorldLinkedSelectionResizeChildRoot();
        CaptureWorldLinkedSelectionBaseSizes(resizeChild);

        float extraHeight = ResolveWorldLinkedSelectionExtraHeight(visibleButtonCount);
        if (cachedWorldLinkedSelectionBaseRootHeight > 0.001f)
        {
            worldLinkedSelectionUiRoot.SetSizeWithCurrentAnchors(
                RectTransform.Axis.Vertical,
                cachedWorldLinkedSelectionBaseRootHeight + extraHeight);
        }

        if (resizeChild != null && cachedWorldLinkedSelectionBaseChildHeight > 0.001f)
        {
            resizeChild.SetSizeWithCurrentAnchors(
                RectTransform.Axis.Vertical,
                cachedWorldLinkedSelectionBaseChildHeight + extraHeight);
        }
    }

    private float ResolveWorldLinkedSelectionExtraHeight(int visibleButtonCount)
    {
        if (visibleButtonCount <= 1 || worldLinkedSelectionUiContentRoot == null)
        {
            return 0f;
        }

        if (worldLinkedSelectionUiContentRoot.TryGetComponent(out GridLayoutGroup grid))
        {
            int rowCount;
            if (grid.constraint == GridLayoutGroup.Constraint.FixedRowCount)
            {
                rowCount = Mathf.Min(visibleButtonCount, Mathf.Max(1, grid.constraintCount));
            }
            else
            {
                int columnCount = grid.constraint == GridLayoutGroup.Constraint.FixedColumnCount
                    ? Mathf.Max(1, grid.constraintCount)
                    : ResolveFlexibleGridColumnCount(grid);
                rowCount = Mathf.CeilToInt(visibleButtonCount / (float)columnCount);
            }

            return Mathf.Max(0, rowCount - 1) * (grid.cellSize.y + grid.spacing.y);
        }

        float spacing = worldLinkedSelectionUiContentRoot.TryGetComponent(out VerticalLayoutGroup vertical)
            ? vertical.spacing
            : 0f;
        return Mathf.Max(0, visibleButtonCount - 1) * (WorldLinkedPartSlotButtonHeight + spacing);
    }

    private int ResolveFlexibleGridColumnCount(GridLayoutGroup grid)
    {
        float availableWidth = worldLinkedSelectionUiContentRoot.rect.width
                               - grid.padding.left
                               - grid.padding.right;
        float cellStep = grid.cellSize.x + grid.spacing.x;
        if (availableWidth <= 0f || cellStep <= 0f)
        {
            return 1;
        }

        return Mathf.Max(1, Mathf.FloorToInt((availableWidth + grid.spacing.x) / cellStep));
    }

    private RectTransform ResolveWorldLinkedSelectionResizeChildRoot()
    {
        if (worldLinkedSelectionUiResizeChildRoot != null)
        {
            return worldLinkedSelectionUiResizeChildRoot;
        }

        if (worldLinkedSelectionUiRoot == null)
        {
            return null;
        }

        worldLinkedSelectionUiResizeChildRoot = FindChildByNameIn<RectTransform>(worldLinkedSelectionUiRoot, "GroupPanel");
        if (worldLinkedSelectionUiResizeChildRoot != null)
        {
            return worldLinkedSelectionUiResizeChildRoot;
        }

        if (worldLinkedSelectionUiContentRoot != null
            && worldLinkedSelectionUiContentRoot.parent is RectTransform parentRect
            && parentRect != worldLinkedSelectionUiRoot)
        {
            worldLinkedSelectionUiResizeChildRoot = parentRect;
        }

        return worldLinkedSelectionUiResizeChildRoot;
    }

    private void CaptureWorldLinkedSelectionBaseSizes(RectTransform resizeChild)
    {
        if (cachedWorldLinkedSelectionSizeRoot != worldLinkedSelectionUiRoot
            || cachedWorldLinkedSelectionSizeChild != resizeChild)
        {
            cachedWorldLinkedSelectionSizeRoot = worldLinkedSelectionUiRoot;
            cachedWorldLinkedSelectionSizeChild = resizeChild;
            cachedWorldLinkedSelectionBaseRootHeight = ResolveRectTransformHeight(worldLinkedSelectionUiRoot);
            cachedWorldLinkedSelectionBaseChildHeight = ResolveRectTransformHeight(resizeChild);
        }
    }

    private static float ResolveRectTransformHeight(RectTransform rect)
    {
        if (rect == null)
        {
            return 0f;
        }

        float height = rect.rect.height;
        if (height <= 0.001f)
        {
            height = Mathf.Abs(rect.sizeDelta.y);
        }

        return Mathf.Max(0f, height);
    }

    private float ResolveCachedWorldLinkedSelectionPanelChromeHeight()
    {
        if (worldLinkedSelectionUiRoot == null || worldLinkedSelectionUiContentRoot == null)
        {
            return 0f;
        }

        if (cachedWorldLinkedSelectionChromeRoot != worldLinkedSelectionUiRoot
            || cachedWorldLinkedSelectionChromeContent != worldLinkedSelectionUiContentRoot)
        {
            cachedWorldLinkedSelectionChromeRoot = worldLinkedSelectionUiRoot;
            cachedWorldLinkedSelectionChromeContent = worldLinkedSelectionUiContentRoot;
            cachedWorldLinkedSelectionChromeHeight = -1f;
        }

        if (cachedWorldLinkedSelectionChromeHeight < 0f)
        {
            cachedWorldLinkedSelectionChromeHeight = ResolveWorldLinkedSelectionPanelChromeHeight();
        }

        return cachedWorldLinkedSelectionChromeHeight;
    }

    private float ResolveWorldLinkedSelectionPanelChromeHeight()
    {
        if (worldLinkedSelectionUiRoot == null || worldLinkedSelectionUiContentRoot == null)
        {
            return 0f;
        }

        worldLinkedSelectionUiContentRoot.GetWorldCorners(worldLinkedUiCornersBuffer);
        float contentTop = float.NegativeInfinity;
        float contentBottom = float.PositiveInfinity;
        for (int i = 0; i < worldLinkedUiCornersBuffer.Length; i++)
        {
            float yInRootSpace = worldLinkedSelectionUiRoot.InverseTransformPoint(worldLinkedUiCornersBuffer[i]).y;
            if (yInRootSpace > contentTop)
            {
                contentTop = yInRootSpace;
            }

            if (yInRootSpace < contentBottom)
            {
                contentBottom = yInRootSpace;
            }
        }

        float rootTop = worldLinkedSelectionUiRoot.rect.yMax;
        float rootBottom = worldLinkedSelectionUiRoot.rect.yMin;
        float topGap = rootTop - contentTop;
        float bottomGap = contentBottom - rootBottom;
        return Mathf.Max(0f, topGap + bottomGap);
    }

    private static float ResolveWorldLinkedSlotButtonHeight(Button button)
    {
        return button != null ? WorldLinkedPartSlotButtonHeight : 0f;
    }

    private void SyncWorldLinkedSlotToggleButtons(int requiredCount)
    {
        worldLinkedSlotToggleButtons.Clear();
        if (worldLinkedSelectionUiContentRoot == null || requiredCount <= 0)
        {
            return;
        }

        List<Button> buttons = CollectWorldLinkedSlotButtons(worldLinkedSelectionUiContentRoot);
        Button template = ResolveWorldLinkedSlotCloneTemplate(buttons);
        if (template == null)
        {
            template = ResolveWorldLinkedPartSlotTemplateButton();
        }

        while (buttons.Count < requiredCount && template != null)
        {
            Button clone = InstantiateWorldLinkedSlotToggleButtonClone(
                template,
                buttons.Count,
                worldLinkedSelectionUiContentRoot);
            if (clone == null)
            {
                break;
            }

            buttons.Add(clone);
        }

        SortWorldLinkedSlotButtons(buttons);
        for (int i = buttons.Count - 1; i >= requiredCount; i--)
        {
            Button extraButton = buttons[i];
            if (extraButton == null)
            {
                buttons.RemoveAt(i);
                continue;
            }

            DestroyGameObjectSafely(extraButton.gameObject);

            buttons.RemoveAt(i);
        }

        SortWorldLinkedSlotButtons(buttons);
        for (int i = 0; i < buttons.Count && i < requiredCount; i++)
        {
            Button button = buttons[i];
            if (button == null)
            {
                continue;
            }

            button.gameObject.name = $"LinkedSlot_{i + 1:00}";
            button.gameObject.SetActive(true);
            button.interactable = true;
            button.onClick.RemoveAllListeners();
            if (button.transform.parent == worldLinkedSelectionUiContentRoot)
            {
                button.transform.SetSiblingIndex(i);
            }
            ConfigureWorldLinkedSlotButtonSize(button);

            Image background = ResolveWorldLinkedSlotButtonBackground(button);
            if (background != null)
            {
                button.targetGraphic = background;
                background.raycastTarget = true;
            }

            Text label = ResolveWorldLinkedSlotButtonLabel(button);
            TMP_Text tmpLabel = ResolveWorldLinkedSlotButtonTmpLabel(button);

            worldLinkedSlotToggleButtons.Add(new WorldLinkedSlotToggleEntry
            {
                slot = MinimoCharacterCustomizer.PartSlot.Torso,
                button = button,
                background = background,
                label = label,
                tmpLabel = tmpLabel,
                selectionOutline = null
            });

            DisableWorldLinkedSlotOutlines(button);
        }
    }

    private static List<Button> CollectWorldLinkedSlotButtons(RectTransform root)
    {
        List<Button> buttons = new List<Button>();
        if (root == null)
        {
            return buttons;
        }

        Button[] found = root.GetComponentsInChildren<Button>(true);
        for (int i = 0; i < found.Length; i++)
        {
            Button button = found[i];
            if (button == null)
            {
                continue;
            }

            if (!IsWorldLinkedSlotButtonName(button.gameObject.name))
            {
                continue;
            }

            if (HasButtonAncestorInsideStrip(button.transform, root))
            {
                continue;
            }

            buttons.Add(button);
        }

        SortWorldLinkedSlotButtons(buttons);
        return buttons;
    }

    private static void SortWorldLinkedSlotButtons(List<Button> buttons)
    {
        if (buttons == null || buttons.Count <= 1)
        {
            return;
        }

        buttons.Sort((left, right) =>
        {
            if (left == null && right == null)
            {
                return 0;
            }

            if (left == null)
            {
                return 1;
            }

            if (right == null)
            {
                return -1;
            }

            int leftOrder = GetWorldLinkedSlotNameOrder(left.gameObject.name);
            int rightOrder = GetWorldLinkedSlotNameOrder(right.gameObject.name);
            if (leftOrder != rightOrder)
            {
                return leftOrder.CompareTo(rightOrder);
            }

            Transform leftTransform = left.transform;
            Transform rightTransform = right.transform;
            if (leftTransform.parent == rightTransform.parent)
            {
                return leftTransform.GetSiblingIndex().CompareTo(rightTransform.GetSiblingIndex());
            }

            return string.Compare(left.gameObject.name, right.gameObject.name, StringComparison.OrdinalIgnoreCase);
        });
    }

    private static bool IsWorldLinkedSlotButtonName(string value)
    {
        return !string.IsNullOrWhiteSpace(value)
               && (value.StartsWith("LinkedSlot", StringComparison.OrdinalIgnoreCase)
                   || value.StartsWith("PartSlot", StringComparison.OrdinalIgnoreCase));
    }

    private static int GetWorldLinkedSlotNameOrder(string value)
    {
        if (!IsWorldLinkedSlotButtonName(value))
        {
            return int.MaxValue;
        }

        int underscoreIndex = value.LastIndexOf('_');
        if (underscoreIndex < 0 || underscoreIndex >= value.Length - 1)
        {
            return int.MaxValue - 1;
        }

        string suffix = value.Substring(underscoreIndex + 1);
        if (int.TryParse(suffix, out int order))
        {
            return order;
        }

        return int.MaxValue - 1;
    }

    private static Button ResolveWorldLinkedSlotCloneTemplate(IReadOnlyList<Button> buttons)
    {
        if (buttons == null || buttons.Count == 0)
        {
            return null;
        }

        for (int i = 0; i < buttons.Count; i++)
        {
            Button candidate = buttons[i];
            if (candidate == null)
            {
                continue;
            }

            if (string.Equals(candidate.gameObject.name, "LinkedSlot_01", StringComparison.OrdinalIgnoreCase))
            {
                return candidate;
            }
        }

        return buttons[0];
    }

    private static Image ResolveWorldLinkedSlotButtonBackground(Button button)
    {
        if (button == null)
        {
            return null;
        }

        Image selfImage = button.GetComponent<Image>();
        if (selfImage != null)
        {
            return selfImage;
        }

        Image targetImage = button.targetGraphic as Image;
        if (targetImage != null)
        {
            return targetImage;
        }

        Image[] images = button.GetComponentsInChildren<Image>(true);
        for (int i = 0; i < images.Length; i++)
        {
            if (images[i] != null)
            {
                return images[i];
            }
        }

        return null;
    }

    private static Text ResolveWorldLinkedSlotButtonLabel(Button button)
    {
        if (button == null)
        {
            return null;
        }

        Text label = FindChildByNameIn<Text>(button.transform, "Label");
        label ??= FindChildByNameIn<Text>(button.transform, "Text");
        return label;
    }

    private static TMP_Text ResolveWorldLinkedSlotButtonTmpLabel(Button button)
    {
        if (button == null)
        {
            return null;
        }

        TMP_Text label = FindChildByNameIn<TMP_Text>(button.transform, "Label");
        label ??= FindChildByNameIn<TMP_Text>(button.transform, "Text");
        return label;
    }

    private static Button InstantiateWorldLinkedSlotToggleButtonClone(Button template, int index, Transform parent)
    {
        if (template == null)
        {
            return null;
        }

        Transform targetParent = parent != null ? parent : template.transform.parent;
        if (targetParent == null)
        {
            return null;
        }

        GameObject cloneObject = Instantiate(template.gameObject, targetParent, false);
        cloneObject.name = $"LinkedSlot_{index + 1:00}";
        cloneObject.SetActive(true);

        Button clone = cloneObject.GetComponent<Button>();
        if (clone == null)
        {
            if (Application.isPlaying)
            {
                UnityEngine.Object.Destroy(cloneObject);
            }
            else
            {
                UnityEngine.Object.DestroyImmediate(cloneObject);
            }

            return null;
        }

        Image background = ResolveWorldLinkedSlotButtonBackground(clone);
        if (background == null)
        {
            if (Application.isPlaying)
            {
                UnityEngine.Object.Destroy(cloneObject);
            }
            else
            {
                UnityEngine.Object.DestroyImmediate(cloneObject);
            }

            return null;
        }

        clone.targetGraphic = background;
        background.raycastTarget = true;
        clone.onClick.RemoveAllListeners();
        clone.interactable = true;
        ConfigureWorldLinkedSlotButtonSize(clone);
        return clone;
    }

    private static void ConfigureWorldLinkedSlotButtonSize(Button button)
    {
        if (button == null)
        {
            return;
        }

        RectTransform rect = button.transform as RectTransform;
        bool parentUsesGrid = rect != null
                              && rect.parent != null
                              && rect.parent.TryGetComponent(out GridLayoutGroup _);
        if (parentUsesGrid)
        {
            return;
        }

        if (rect != null)
        {
            rect.SetSizeWithCurrentAnchors(RectTransform.Axis.Vertical, WorldLinkedPartSlotButtonHeight);
        }

        LayoutElement layout = button.GetComponent<LayoutElement>();
        if (layout == null)
        {
            layout = button.gameObject.AddComponent<LayoutElement>();
        }

        layout.minHeight = WorldLinkedPartSlotButtonHeight;
        layout.preferredHeight = WorldLinkedPartSlotButtonHeight;
        layout.flexibleHeight = 0f;
    }

    private bool TryGetCurrentWorldLinkedMaterialTargets(
        out Dictionary<MinimoCharacterCustomizer.PartSlot, HashSet<int>> linkedTargets)
    {
        linkedTargets = new Dictionary<MinimoCharacterCustomizer.PartSlot, HashSet<int>>();
        if (worldLinkedMaterialTargetsSnapshot.Count > 0)
        {
            linkedTargets = CloneWorldLinkedMaterialTargets(worldLinkedMaterialTargetsSnapshot);
            return linkedTargets.Count > 0;
        }

        if (!worldLinkedMaterialSelectionKeyValid || string.IsNullOrWhiteSpace(worldLinkedMaterialSelectionKey))
        {
            return false;
        }

        if (!TryBuildWorldLinkedMaterialTargetsByKey(worldLinkedMaterialSelectionKey, out linkedTargets))
        {
            return false;
        }

        if (linkedTargets.Count <= 0)
        {
            return false;
        }

        worldLinkedMaterialTargetsSnapshot.Clear();
        CopyWorldLinkedMaterialTargets(linkedTargets, worldLinkedMaterialTargetsSnapshot);
        linkedTargets = CloneWorldLinkedMaterialTargets(worldLinkedMaterialTargetsSnapshot);
        return linkedTargets.Count > 0;
    }

    private bool TryGetPersistedWorldLinkedSelectedSlots(
        out List<MinimoCharacterCustomizer.PartSlot> selectedSlots,
        bool requireMultiple = false)
    {
        selectedSlots = new List<MinimoCharacterCustomizer.PartSlot>();
        if (worldLinkedSlotSelectionStates.Count == 0)
        {
            return false;
        }

        HashSet<MinimoCharacterCustomizer.PartSlot> added = new HashSet<MinimoCharacterCustomizer.PartSlot>();
        for (int i = 0; i < PartSelectionUiOrder.Length; i++)
        {
            MinimoCharacterCustomizer.PartSlot slot = PartSelectionUiOrder[i];
            if (worldLinkedSlotSelectionStates.TryGetValue(slot, out bool selected) && selected)
            {
                selectedSlots.Add(slot);
                added.Add(slot);
            }
        }

        foreach (KeyValuePair<MinimoCharacterCustomizer.PartSlot, bool> pair in worldLinkedSlotSelectionStates)
        {
            if (!pair.Value || added.Contains(pair.Key))
            {
                continue;
            }

            selectedSlots.Add(pair.Key);
            added.Add(pair.Key);
        }

        if (requireMultiple && selectedSlots.Count <= 1)
        {
            return false;
        }

        return selectedSlots.Count > 0;
    }

    private void RebuildWorldLinkedTargetsSnapshotFromSelectedSlots(
        int colorChannelIndex,
        bool preserveExplicitColorChannel = false)
    {
        if (customizer == null
            || !TryGetPersistedWorldLinkedSelectedSlots(out List<MinimoCharacterCustomizer.PartSlot> selectedSlots))
        {
            return;
        }

        bool preserveGroupedSelection = selectedSlots.Count > 1 && !selectedWorldColorTargetSlot.HasValue;
        MinimoCharacterCustomizer.PartSlot anchorSlot = selectedWorldColorTargetSlot ?? selectedSlots[0];
        if (!preserveGroupedSelection && !selectedWorldColorTargetSlot.HasValue)
        {
            selectedWorldColorTargetSlot = anchorSlot;
        }

        Dictionary<MinimoCharacterCustomizer.PartSlot, HashSet<int>> rebuiltTargets = new Dictionary<MinimoCharacterCustomizer.PartSlot, HashSet<int>>();
        string materialKey = string.Empty;
        Color targetColor = Color.white;
        int anchorColorMaterialIndex = -1;
        bool useColorDrivenSelection = !preserveExplicitColorChannel
                                       && selectedSlots.Count > 1
                                       && TryResolveWorldLinkedTargetColorForSelectedSlots(
                                           selectedSlots,
                                           anchorSlot,
                                           out targetColor,
                                           out anchorColorMaterialIndex);

        if (useColorDrivenSelection)
        {
            if (anchorColorMaterialIndex >= 0
                && TryResolveColorChannelFromMaterialIndex(anchorSlot, anchorColorMaterialIndex, out int resolvedChannel))
            {
                selectedColorMaterialIndex = Mathf.Max(0, resolvedChannel);
            }

            if (!TryBuildWorldLinkedMaterialKeyForColor(
                    anchorSlot,
                    anchorColorMaterialIndex,
                    targetColor,
                    out materialKey))
            {
                if (!TryApplyFirstPaletteColorToWorldLinkedSelectedSlots(
                        selectedSlots,
                        colorChannelIndex,
                        out rebuiltTargets,
                        out materialKey))
                {
                    return;
                }
            }
            else
            {
                for (int i = 0; i < selectedSlots.Count; i++)
                {
                    MinimoCharacterCustomizer.PartSlot slot = selectedSlots[i];
                    HashSet<int> matchingIndices = GetEditableMaterialIndicesMatchingWorldLinkedKey(slot, materialKey);
                    if (matchingIndices == null || matchingIndices.Count == 0)
                    {
                        continue;
                    }

                    rebuiltTargets[slot] = matchingIndices;
                }
            }
        }
        else
        {
            for (int i = 0; i < selectedSlots.Count; i++)
            {
                MinimoCharacterCustomizer.PartSlot slot = selectedSlots[i];
                int materialIndex = ResolveColorMaterialIndexForSlot(slot, colorChannelIndex);
                if (materialIndex < 0)
                {
                    continue;
                }

                if (!rebuiltTargets.TryGetValue(slot, out HashSet<int> slotIndices))
                {
                    slotIndices = new HashSet<int>();
                    rebuiltTargets[slot] = slotIndices;
                }

                slotIndices.Add(materialIndex);
            }

            int anchorMaterialIndex = ResolveColorMaterialIndexForSlot(anchorSlot, colorChannelIndex);
            if (anchorMaterialIndex >= 0)
            {
                TryGetWorldLinkedMaterialKey(anchorSlot, anchorMaterialIndex, out materialKey);
            }
        }

        if (!preserveExplicitColorChannel
            && selectedSlots.Count > 1
            && rebuiltTargets.Count < selectedSlots.Count
            && TryApplyFirstPaletteColorToWorldLinkedSelectedSlots(
                selectedSlots,
                colorChannelIndex,
                out Dictionary<MinimoCharacterCustomizer.PartSlot, HashSet<int>> fallbackTargets,
                out string fallbackMaterialKey))
        {
            rebuiltTargets = fallbackTargets;
            materialKey = fallbackMaterialKey;
        }

        worldLinkedMaterialTargetsSnapshot.Clear();
        if (rebuiltTargets.Count > 0)
        {
            CopyWorldLinkedMaterialTargets(rebuiltTargets, worldLinkedMaterialTargetsSnapshot);
        }

        if (selectedWorldColorTargetSlot.HasValue
            && !HasColorTargetsForWorldLinkedSlot(rebuiltTargets, selectedWorldColorTargetSlot.Value))
        {
            if (TryGetFirstSelectedWorldLinkedSlot(rebuiltTargets, out MinimoCharacterCustomizer.PartSlot fallbackColorSlot))
            {
                selectedWorldColorTargetSlot = fallbackColorSlot;
            }
            else
            {
                selectedWorldColorTargetSlot = null;
            }
        }

        if (preserveGroupedSelection)
        {
            selectedWorldColorTargetSlot = null;
            if (!HasSelectedWorldVariantTargetSlots())
            {
                selectedWorldPreviewTargetSlot = null;
            }
        }

        worldLinkedMaterialSelectionKeyValid = !string.IsNullOrWhiteSpace(materialKey);
        worldLinkedMaterialSelectionKey = worldLinkedMaterialSelectionKeyValid ? materialKey : string.Empty;
        if (worldLinkedMaterialSelectionKeyValid)
        {
            worldLinkedSlotSelectionKey = materialKey;
        }

        worldLinkedMaterialSingleOverrideActive = rebuiltTargets.Count <= 1;
        worldLastHoveredMaterialKey = string.Empty;
    }

    private bool TryApplyFirstPaletteColorToWorldLinkedSelectedSlots(
        List<MinimoCharacterCustomizer.PartSlot> selectedSlots,
        int colorChannelIndex,
        out Dictionary<MinimoCharacterCustomizer.PartSlot, HashSet<int>> rebuiltTargets,
        out string materialKey)
    {
        rebuiltTargets = new Dictionary<MinimoCharacterCustomizer.PartSlot, HashSet<int>>();
        materialKey = string.Empty;
        if (customizer == null || selectedSlots == null || selectedSlots.Count == 0)
        {
            return false;
        }

        Color fallbackColor = ResolveFirstVisiblePaletteColor();
        List<(MinimoCharacterCustomizer.PartSlot slot, int materialIndex, Color color)> colorAssignments = new List<(MinimoCharacterCustomizer.PartSlot slot, int materialIndex, Color color)>();
        for (int i = 0; i < selectedSlots.Count; i++)
        {
            MinimoCharacterCustomizer.PartSlot slot = selectedSlots[i];
            int materialIndex = ResolveColorMaterialIndexForSlot(slot, colorChannelIndex);
            if (materialIndex < 0
                || !TryGetMaterialForSlot(slot, materialIndex, out Material material)
                || !MaterialSupportsColor(material))
            {
                continue;
            }

            if (!rebuiltTargets.TryGetValue(slot, out HashSet<int> slotTargets))
            {
                slotTargets = new HashSet<int>();
                rebuiltTargets[slot] = slotTargets;
            }

            slotTargets.Add(materialIndex);
            colorAssignments.Add((slot, materialIndex, fallbackColor));
        }

        if (colorAssignments.Count == 0 || rebuiltTargets.Count == 0)
        {
            return false;
        }

        customizer.SetPartColors(colorAssignments);
        selectedPaletteButtonIndex = 0;

        MinimoCharacterCustomizer.PartSlot anchorSlot = selectedWorldColorTargetSlot.HasValue
                                                        && rebuiltTargets.ContainsKey(selectedWorldColorTargetSlot.Value)
            ? selectedWorldColorTargetSlot.Value
            : selectedSlots[0];
        int anchorMaterialIndex = -1;
        if (!rebuiltTargets.TryGetValue(anchorSlot, out HashSet<int> anchorIndices)
            || !TryGetFirstMaterialIndex(anchorIndices, out anchorMaterialIndex))
        {
            foreach (KeyValuePair<MinimoCharacterCustomizer.PartSlot, HashSet<int>> pair in rebuiltTargets)
            {
                if (TryGetFirstMaterialIndex(pair.Value, out anchorMaterialIndex))
                {
                    anchorSlot = pair.Key;
                    break;
                }
            }
        }

        if (anchorMaterialIndex < 0
            || !TryBuildWorldLinkedMaterialKeyForColor(anchorSlot, anchorMaterialIndex, fallbackColor, out materialKey))
        {
            materialKey = BuildWorldLinkedMaterialColorKey(
                fallbackColor,
                ResolveWorldLinkedNonSkinMaterialGroupKey(anchorSlot));
        }

        return !string.IsNullOrWhiteSpace(materialKey);
    }

    private Color ResolveFirstVisiblePaletteColor()
    {
        Color[] activePalette = GetActivePaletteColors();
        if (activePalette == null || activePalette.Length == 0)
        {
            activePalette = paletteColors;
        }

        Color color = activePalette != null && activePalette.Length > 0
            ? ResolvePaletteColorForSwatch(activePalette, 0, PaletteSwatchCount)
            : Color.white;
        color.a = 1f;
        return color;
    }

    private void RebuildWorldLinkedTargetsAfterVariantChange(
        int colorChannelIndex,
        bool preserveSkinLinkedColorSelection,
        Color preservedSkinLinkedColor,
        MinimoCharacterCustomizer.PartSlot? preservedSkinLinkedAnchorSlot,
        MinimoCharacterCustomizer.PartSlot[] changedSlots,
        bool includeFace)
    {
        if (preserveSkinLinkedColorSelection)
        {
            if (!ChangedVariantStillUsesSkinLinkedColor(
                    changedSlots,
                    preservedSkinLinkedAnchorSlot))
            {
                RebuildWorldLinkedTargetsSnapshotFromSelectedSlots(colorChannelIndex);
                return;
            }

            if (RestoreSkinLinkedColorSelectionAfterVariantChange(
                    preservedSkinLinkedColor,
                    preservedSkinLinkedAnchorSlot,
                    changedSlots,
                    includeFace))
            {
                return;
            }

            RebuildWorldLinkedTargetsSnapshotFromSelectedSlots(colorChannelIndex);
            return;
        }

        RebuildWorldLinkedTargetsSnapshotFromSelectedSlots(colorChannelIndex);
    }

    private bool TryCaptureSkinLinkedColorSelectionForVariantChange(
        out Color skinToneColor,
        out MinimoCharacterCustomizer.PartSlot? anchorSlot)
    {
        skinToneColor = Color.white;
        anchorSlot = selectedWorldColorTargetSlot;
        if (customizer == null || selectedColorChannelTarget != ColorChannelTargetType.Material)
        {
            return false;
        }

        bool hasSkinKey = IsSkinWorldLinkedSelectionKey(worldLinkedMaterialSelectionKey)
                          || IsSkinWorldLinkedSelectionKey(worldLinkedSlotSelectionKey);
        bool hasSkinPaletteSelection = ShouldUseSkinPaletteForCurrentSelection();
        bool hasSkinAnchor = false;
        Color anchorColor = Color.white;
        if (TryGetCurrentSelectionAnchor(
                out MinimoCharacterCustomizer.PartSlot currentAnchorSlot,
                out int currentAnchorMaterialIndex)
            && TryGetEffectivePartColor(currentAnchorSlot, currentAnchorMaterialIndex, out anchorColor)
            && IsSkinLinkedMaterialTarget(currentAnchorSlot, currentAnchorMaterialIndex, anchorColor))
        {
            hasSkinAnchor = true;
            anchorSlot ??= currentAnchorSlot;
        }

        if (!hasSkinKey && !hasSkinPaletteSelection && !hasSkinAnchor)
        {
            return false;
        }

        if (TryGetCurrentSkinToneColor(out skinToneColor))
        {
            return true;
        }

        if (!hasSkinAnchor)
        {
            return false;
        }

        skinToneColor = anchorColor;
        return true;
    }

    private static bool IsSkinWorldLinkedSelectionKey(string materialKey)
    {
        return !string.IsNullOrWhiteSpace(materialKey)
               && materialKey.StartsWith("skin|", StringComparison.OrdinalIgnoreCase);
    }

    private bool RestoreSkinLinkedColorSelectionAfterVariantChange(
        Color skinToneColor,
        MinimoCharacterCustomizer.PartSlot? preferredAnchorSlot,
        MinimoCharacterCustomizer.PartSlot[] changedSlots,
        bool includeFace)
    {
        if (customizer == null)
        {
            return false;
        }

        Dictionary<MinimoCharacterCustomizer.PartSlot, HashSet<int>> linkedTargets = new Dictionary<MinimoCharacterCustomizer.PartSlot, HashSet<int>>();
        List<(MinimoCharacterCustomizer.PartSlot slot, int materialIndex, Color color)> colorAssignments = new List<(MinimoCharacterCustomizer.PartSlot slot, int materialIndex, Color color)>();
        for (int i = 0; i < SkinToneSlots.Length; i++)
        {
            MinimoCharacterCustomizer.PartSlot slot = SkinToneSlots[i];
            if (!includeFace && slot == MinimoCharacterCustomizer.PartSlot.Face)
            {
                continue;
            }

            HashSet<int> materialIndices = GetMaterialIndicesMatchingColor(slot, skinToneColor);
            AddSkinLinkedColorTargets(
                slot,
                materialIndices,
                skinToneColor,
                linkedTargets,
                colorAssignments);
        }

        if (changedSlots != null)
        {
            for (int i = 0; i < changedSlots.Length; i++)
            {
                MinimoCharacterCustomizer.PartSlot slot = changedSlots[i];
                if (!includeFace && slot == MinimoCharacterCustomizer.PartSlot.Face)
                {
                    continue;
                }

                HashSet<int> materialIndices = GetMaterialIndicesUsingSkinPaletteColorGroup(slot);
                AddSkinLinkedColorTargets(
                    slot,
                    materialIndices,
                    skinToneColor,
                    linkedTargets,
                    colorAssignments);
            }
        }

        if (linkedTargets.Count == 0)
        {
            return false;
        }

        if (colorAssignments.Count > 0)
        {
            List<(MinimoCharacterCustomizer.PartSlot slot, int materialIndex, Color color)> filteredAssignments =
                FilterVariantChangeColorAssignments(colorAssignments, changedSlots);
            if (filteredAssignments.Count > 0)
            {
                customizer.SetPartColors(filteredAssignments);
            }
        }

        string materialKey = BuildWorldLinkedMaterialColorKey(skinToneColor, "skin");
        worldLinkedMaterialTargetsSnapshot.Clear();
        CopyWorldLinkedMaterialTargets(linkedTargets, worldLinkedMaterialTargetsSnapshot);
        worldLinkedMaterialSelectionKey = materialKey;
        worldLinkedMaterialSelectionKeyValid = true;
        worldLinkedSlotSelectionKey = materialKey;
        worldLinkedSlotSelectionStates.Clear();

        HashSet<MinimoCharacterCustomizer.PartSlot> orderedSlots = new HashSet<MinimoCharacterCustomizer.PartSlot>();
        for (int i = 0; i < PartSelectionUiOrder.Length; i++)
        {
            MinimoCharacterCustomizer.PartSlot slot = PartSelectionUiOrder[i];
            if (!linkedTargets.ContainsKey(slot))
            {
                continue;
            }

            worldLinkedSlotSelectionStates[slot] = true;
            orderedSlots.Add(slot);
        }

        foreach (KeyValuePair<MinimoCharacterCustomizer.PartSlot, HashSet<int>> pair in linkedTargets)
        {
            if (orderedSlots.Contains(pair.Key))
            {
                continue;
            }

            worldLinkedSlotSelectionStates[pair.Key] = true;
        }

        if (changedSlots != null && changedSlots.Length > 0)
        {
            if (preferredAnchorSlot.HasValue
                && SlotArrayContains(changedSlots, preferredAnchorSlot.Value)
                && linkedTargets.ContainsKey(preferredAnchorSlot.Value))
            {
                selectedWorldColorTargetSlot = preferredAnchorSlot.Value;
            }
            else if (TryGetFirstLinkedSlotInChangedSlots(
                         linkedTargets,
                         changedSlots,
                         out MinimoCharacterCustomizer.PartSlot changedFallbackSlot))
            {
                selectedWorldColorTargetSlot = changedFallbackSlot;
            }
            else
            {
                selectedWorldColorTargetSlot = null;
            }
        }
        else if (preferredAnchorSlot.HasValue && linkedTargets.ContainsKey(preferredAnchorSlot.Value))
        {
            selectedWorldColorTargetSlot = preferredAnchorSlot.Value;
        }
        else if (TryGetFirstSelectedWorldLinkedSlot(linkedTargets, out MinimoCharacterCustomizer.PartSlot fallbackSlot))
        {
            selectedWorldColorTargetSlot = fallbackSlot;
        }

        if (selectedWorldColorTargetSlot.HasValue
            && linkedTargets.TryGetValue(selectedWorldColorTargetSlot.Value, out HashSet<int> anchorIndices)
            && TryGetFirstMaterialIndex(anchorIndices, out int anchorMaterialIndex)
            && TryResolveColorChannelFromMaterialIndex(selectedWorldColorTargetSlot.Value, anchorMaterialIndex, out int colorChannelIndex))
        {
            selectedColorMaterialIndex = colorChannelIndex;
        }

        worldLinkedMaterialSingleOverrideActive = linkedTargets.Count <= 1;
        worldLastHoveredMaterialKey = string.Empty;
        return true;
    }

    private static List<(MinimoCharacterCustomizer.PartSlot slot, int materialIndex, Color color)> FilterVariantChangeColorAssignments(
        List<(MinimoCharacterCustomizer.PartSlot slot, int materialIndex, Color color)> colorAssignments,
        MinimoCharacterCustomizer.PartSlot[] changedSlots)
    {
        if (colorAssignments == null || colorAssignments.Count == 0)
        {
            return colorAssignments;
        }

        if (changedSlots == null || changedSlots.Length == 0)
        {
            return colorAssignments;
        }

        List<(MinimoCharacterCustomizer.PartSlot slot, int materialIndex, Color color)> filtered = new List<(MinimoCharacterCustomizer.PartSlot slot, int materialIndex, Color color)>();
        for (int i = 0; i < colorAssignments.Count; i++)
        {
            (MinimoCharacterCustomizer.PartSlot slot, int materialIndex, Color color) assignment = colorAssignments[i];
            if (SlotArrayContains(changedSlots, assignment.slot))
            {
                filtered.Add(assignment);
            }
        }

        return filtered;
    }

    private static bool TryGetFirstLinkedSlotInChangedSlots(
        Dictionary<MinimoCharacterCustomizer.PartSlot, HashSet<int>> linkedTargets,
        MinimoCharacterCustomizer.PartSlot[] changedSlots,
        out MinimoCharacterCustomizer.PartSlot slot)
    {
        slot = default;
        if (linkedTargets == null || linkedTargets.Count == 0 || changedSlots == null || changedSlots.Length == 0)
        {
            return false;
        }

        for (int orderIndex = 0; orderIndex < PartSelectionUiOrder.Length; orderIndex++)
        {
            MinimoCharacterCustomizer.PartSlot orderedSlot = PartSelectionUiOrder[orderIndex];
            if (SlotArrayContains(changedSlots, orderedSlot) && linkedTargets.ContainsKey(orderedSlot))
            {
                slot = orderedSlot;
                return true;
            }
        }

        for (int i = 0; i < changedSlots.Length; i++)
        {
            MinimoCharacterCustomizer.PartSlot candidate = changedSlots[i];
            if (linkedTargets.ContainsKey(candidate))
            {
                slot = candidate;
                return true;
            }
        }

        return false;
    }

    private bool ChangedVariantStillUsesSkinLinkedColor(
        MinimoCharacterCustomizer.PartSlot[] changedSlots,
        MinimoCharacterCustomizer.PartSlot? preferredAnchorSlot)
    {
        if (customizer == null || changedSlots == null || changedSlots.Length == 0)
        {
            return false;
        }

        if (preferredAnchorSlot.HasValue && SlotArrayContains(changedSlots, preferredAnchorSlot.Value))
        {
            return SlotUsesSkinPaletteColorGroup(preferredAnchorSlot.Value);
        }

        if (selectedWorldColorTargetSlot.HasValue && SlotArrayContains(changedSlots, selectedWorldColorTargetSlot.Value))
        {
            return SlotUsesSkinPaletteColorGroup(selectedWorldColorTargetSlot.Value);
        }

        for (int i = 0; i < changedSlots.Length; i++)
        {
            if (SlotUsesSkinPaletteColorGroup(changedSlots[i]))
            {
                return true;
            }
        }

        return false;
    }

    private void AddSkinLinkedColorTargets(
        MinimoCharacterCustomizer.PartSlot slot,
        HashSet<int> materialIndices,
        Color skinToneColor,
        Dictionary<MinimoCharacterCustomizer.PartSlot, HashSet<int>> linkedTargets,
        List<(MinimoCharacterCustomizer.PartSlot slot, int materialIndex, Color color)> colorAssignments)
    {
        if (materialIndices == null || materialIndices.Count == 0 || linkedTargets == null)
        {
            return;
        }

        if (!linkedTargets.TryGetValue(slot, out HashSet<int> slotTargets))
        {
            slotTargets = new HashSet<int>();
            linkedTargets[slot] = slotTargets;
        }

        foreach (int materialIndex in materialIndices)
        {
            if (!slotTargets.Add(materialIndex))
            {
                continue;
            }

            colorAssignments?.Add((slot, materialIndex, skinToneColor));
        }
    }

    private bool TryResolveWorldLinkedTargetColorForSelectedSlots(
        List<MinimoCharacterCustomizer.PartSlot> selectedSlots,
        MinimoCharacterCustomizer.PartSlot anchorSlot,
        out Color targetColor,
        out int anchorMaterialIndex)
    {
        targetColor = Color.white;
        anchorMaterialIndex = -1;
        if (selectedSlots == null || selectedSlots.Count == 0)
        {
            return false;
        }

        List<int> anchorEditableIndices = GetEditableColorMaterialIndicesForSlot(anchorSlot);
        if (anchorEditableIndices.Count == 0)
        {
            return false;
        }

        int preferredAnchorMaterialIndex = ResolveColorMaterialIndexForSlot(anchorSlot, selectedColorMaterialIndex);
        int bestCount = -1;
        int bestTieScore = int.MinValue;
        bool hasBest = false;
        Color bestColor = Color.white;
        int bestMaterialIndex = -1;

        for (int i = 0; i < anchorEditableIndices.Count; i++)
        {
            int materialIndex = anchorEditableIndices[i];
            if (!TryGetEffectivePartColor(anchorSlot, materialIndex, out Color candidateColor))
            {
                continue;
            }

            if (!TryBuildWorldLinkedMaterialKeyForColor(
                    anchorSlot,
                    materialIndex,
                    candidateColor,
                    out string candidateMaterialKey))
            {
                continue;
            }

            int slotMatchCount = 0;
            for (int slotIndex = 0; slotIndex < selectedSlots.Count; slotIndex++)
            {
                MinimoCharacterCustomizer.PartSlot slot = selectedSlots[slotIndex];
                if (SlotContainsWorldLinkedMaterialKey(slot, candidateMaterialKey))
                {
                    slotMatchCount++;
                }
            }

            int tieScore = materialIndex == preferredAnchorMaterialIndex ? 1 : 0;
            if (hasBest
                && (slotMatchCount < bestCount
                    || (slotMatchCount == bestCount && tieScore <= bestTieScore)))
            {
                continue;
            }

            bestCount = slotMatchCount;
            bestTieScore = tieScore;
            bestColor = candidateColor;
            bestMaterialIndex = materialIndex;
            hasBest = true;
        }

        if (hasBest && bestCount > 0)
        {
            targetColor = bestColor;
            anchorMaterialIndex = bestMaterialIndex;
            return true;
        }

        for (int i = 0; i < anchorEditableIndices.Count; i++)
        {
            int materialIndex = anchorEditableIndices[i];
            if (!TryGetEffectivePartColor(anchorSlot, materialIndex, out Color anchorColor))
            {
                continue;
            }

            targetColor = anchorColor;
            anchorMaterialIndex = materialIndex;
            return true;
        }

        return false;
    }

    private bool SlotContainsWorldLinkedMaterialKey(
        MinimoCharacterCustomizer.PartSlot slot,
        string materialKey)
    {
        if (string.IsNullOrWhiteSpace(materialKey))
        {
            return false;
        }

        List<int> editableIndices = GetEditableColorMaterialIndicesForSlot(slot);
        for (int i = 0; i < editableIndices.Count; i++)
        {
            int materialIndex = editableIndices[i];
            if (TryGetWorldLinkedMaterialKey(slot, materialIndex, out string candidateKey)
                && string.Equals(candidateKey, materialKey, StringComparison.OrdinalIgnoreCase))
            {
                return true;
            }
        }

        return false;
    }

    private HashSet<int> GetEditableMaterialIndicesMatchingWorldLinkedKey(
        MinimoCharacterCustomizer.PartSlot slot,
        string materialKey)
    {
        HashSet<int> matchingIndices = new HashSet<int>();
        if (string.IsNullOrWhiteSpace(materialKey))
        {
            return matchingIndices;
        }

        List<int> editableIndices = GetEditableColorMaterialIndicesForSlot(slot);
        for (int i = 0; i < editableIndices.Count; i++)
        {
            int materialIndex = editableIndices[i];
            if (TryGetWorldLinkedMaterialKey(slot, materialIndex, out string candidateKey)
                && string.Equals(candidateKey, materialKey, StringComparison.OrdinalIgnoreCase))
            {
                matchingIndices.Add(materialIndex);
            }
        }

        return matchingIndices;
    }

    private static bool ColorsMatchExactRgba(Color a, Color b)
    {
        int ar = Mathf.RoundToInt(Mathf.Clamp01(a.r) * 255f);
        int ag = Mathf.RoundToInt(Mathf.Clamp01(a.g) * 255f);
        int ab = Mathf.RoundToInt(Mathf.Clamp01(a.b) * 255f);
        int aa = Mathf.RoundToInt(Mathf.Clamp01(a.a) * 255f);

        int br = Mathf.RoundToInt(Mathf.Clamp01(b.r) * 255f);
        int bg = Mathf.RoundToInt(Mathf.Clamp01(b.g) * 255f);
        int bb = Mathf.RoundToInt(Mathf.Clamp01(b.b) * 255f);
        int ba = Mathf.RoundToInt(Mathf.Clamp01(b.a) * 255f);

        return ar == br && ag == bg && ab == bb && aa == ba;
    }

    private static Dictionary<MinimoCharacterCustomizer.PartSlot, HashSet<int>> CloneWorldLinkedMaterialTargets(
        Dictionary<MinimoCharacterCustomizer.PartSlot, HashSet<int>> source)
    {
        Dictionary<MinimoCharacterCustomizer.PartSlot, HashSet<int>> clone = new Dictionary<MinimoCharacterCustomizer.PartSlot, HashSet<int>>();
        CopyWorldLinkedMaterialTargets(source, clone);
        return clone;
    }

    private static void CopyWorldLinkedMaterialTargets(
        Dictionary<MinimoCharacterCustomizer.PartSlot, HashSet<int>> source,
        Dictionary<MinimoCharacterCustomizer.PartSlot, HashSet<int>> destination)
    {
        if (destination == null)
        {
            return;
        }

        destination.Clear();
        if (source == null || source.Count == 0)
        {
            return;
        }

        foreach (KeyValuePair<MinimoCharacterCustomizer.PartSlot, HashSet<int>> pair in source)
        {
            if (pair.Value == null || pair.Value.Count == 0)
            {
                continue;
            }

            destination[pair.Key] = new HashSet<int>(pair.Value);
        }
    }

