    {
        if (worldLinkedSelectionUiRoot == null)
        {
            return;
        }

        worldLinkedSelectionUiRoot.gameObject.SetActive(visible);
        if (visible)
        {
            worldLinkedSelectionUiRoot.SetAsLastSibling();
        }
    }

    private Color ResolveWorldLinkedSlotCategoryColor(MinimoCharacterCustomizer.PartSlot slot)
    {
        if (TryGetWorldLinkedSlotCategoryNormalColor(slot, out Color color))
        {
            return color;
        }

        return UiSurfaceSecondaryColor;
    }

    private Material ResolveWorldLinkedSlotCategorySpriteMaterial(MinimoCharacterCustomizer.PartSlot slot)
    {
        if (TryGetWorldLinkedSlotCategorySpriteMaterial(slot, out Material material))
        {
            return material;
        }

        return null;
    }

    private bool TryGetWorldLinkedSlotCategoryNormalColor(
        MinimoCharacterCustomizer.PartSlot slot,
        out Color color)
    {
        color = UiSurfaceSecondaryColor;
        if (!TryGetWorldLinkedRegionEntryForSlotOrMirror(slot, out RegionEntry matchedRegion) || matchedRegion?.button == null)
        {
            return false;
        }

        Image sourceImage = matchedRegion.background;
        sourceImage ??= matchedRegion.button.targetGraphic as Image;
        sourceImage ??= matchedRegion.button.GetComponent<Image>();

        Color imageColor = sourceImage != null ? sourceImage.color : Color.white;
        if (matchedRegion.button.transition != Selectable.Transition.ColorTint)
        {
            color = imageColor;
            return true;
        }

        Color tint = matchedRegion.button.colors.normalColor * matchedRegion.button.colors.colorMultiplier;
        color = new Color(
            imageColor.r * tint.r,
            imageColor.g * tint.g,
            imageColor.b * tint.b,
            imageColor.a * tint.a);
        return true;
    }

    private bool TryGetWorldLinkedSlotCategorySpriteMaterial(
        MinimoCharacterCustomizer.PartSlot slot,
        out Material material)
    {
        material = null;
        if (!TryGetWorldLinkedRegionEntryForSlotOrMirror(slot, out RegionEntry matchedRegion) || matchedRegion?.button == null)
        {
            return false;
        }

        Image sourceImage = matchedRegion.button.targetGraphic as Image;
        sourceImage ??= matchedRegion.button.GetComponent<Image>();
        if (sourceImage == null)
        {
            return false;
        }

        material = sourceImage.material;
        return true;
    }

    private bool TryGetWorldLinkedRegionEntryForSlotOrMirror(
        MinimoCharacterCustomizer.PartSlot slot,
        out RegionEntry matchedRegion)
    {
        matchedRegion = null;
        MinimoCharacterCustomizer.PartSlot regionMatchSlot = ResolveRegionAnchorSlotForWorldSelection(slot);
        if (TryGetWorldLinkedRegionEntryForSlot(regionMatchSlot, out RegionEntry mirroredMatch))
        {
            matchedRegion = mirroredMatch;
            return true;
        }

        if (regionMatchSlot != slot && TryGetWorldLinkedRegionEntryForSlot(slot, out RegionEntry directMatch))
        {
            matchedRegion = directMatch;
            return true;
        }

        return false;
    }

    private static void ApplyWorldLinkedSlotButtonVisual(Button button, Color sourceColor, Material spriteMaterial)
    {
        if (button == null)
        {
            return;
        }

        Image targetImage = button.targetGraphic as Image;
        targetImage ??= button.GetComponent<Image>();
        if (targetImage == null)
        {
            return;
        }

        targetImage.color = sourceColor;

        ColorBlock colors = button.colors;
        colors.normalColor = Color.white;
        colors.highlightedColor = Color.white;
        colors.pressedColor = Color.white;
        colors.selectedColor = Color.white;
        colors.disabledColor = Color.white;
        colors.colorMultiplier = 1f;
        button.colors = colors;

        targetImage.material = spriteMaterial;
        button.targetGraphic = targetImage;
    }

    private static void DisableWorldLinkedSlotOutlines(Button button)
    {
        if (button == null)
        {
            return;
        }

        Outline[] outlines = button.GetComponentsInChildren<Outline>(true);
        for (int i = 0; i < outlines.Length; i++)
        {
            if (outlines[i] != null)
            {
                outlines[i].enabled = false;
            }
        }
    }

    private bool TryGetWorldLinkedRegionEntryForSlot(
        MinimoCharacterCustomizer.PartSlot slot,
        out RegionEntry matchedRegion)
    {
        matchedRegion = null;
        for (int i = 0; i < regions.Count; i++)
        {
            RegionEntry region = regions[i];
            if (region == null || region.button == null)
            {
                continue;
            }

            MinimoCharacterCustomizer.PartSlot[] candidateSlots = region.slots;
            int matchedSlotIndex = FindMatchedRegionSlotIndex(candidateSlots, slot);
            if (matchedSlotIndex < 0
                && TryGetSlotsForBodyRegion(region.name, out MinimoCharacterCustomizer.PartSlot[] resolvedSlotsByName)
                && resolvedSlotsByName.Length > 0)
            {
                candidateSlots = resolvedSlotsByName;
                matchedSlotIndex = FindMatchedRegionSlotIndex(candidateSlots, slot);
                if (matchedSlotIndex >= 0)
                {
                    // Keep cached mapping aligned with resolved button-region name mapping.
                    region.slots = candidateSlots;
                }
            }

            if (matchedSlotIndex < 0)
            {
                continue;
            }

            matchedRegion = region;
            return true;
        }

        return false;
    }

    private bool EnsureWorldLinkedSelectionUi()
    {
        ResolveWorldLinkedSelectionUiSceneReferences();
        if (worldLinkedSelectionUiRoot == null)
        {
            RectTransform popupTemplate = ResolveWorldLinkedSelectionPopupTemplate();
            if (popupTemplate == null)
            {
                return false;
            }

            Transform parent = transform;
            if (partsPanelRoot != null && partsPanelRoot.parent != null)
            {
                parent = partsPanelRoot.parent;
            }

            GameObject popupInstance = Instantiate(popupTemplate.gameObject, parent, false);
            popupInstance.name = "SelectedPartsGroupPopup";
            popupInstance.SetActive(false);
            worldLinkedSelectionUiRoot = popupInstance.transform as RectTransform;
            worldLinkedSelectionUiContentRoot = null;
            worldLinkedSelectionUiResizeChildRoot = null;
            ResolveWorldLinkedSelectionUiSceneReferences();
        }

        if (worldLinkedSelectionUiContentRoot == null)
        {
            ScrollRect scrollRect = worldLinkedSelectionUiRoot.GetComponentInChildren<ScrollRect>(true);
            if (scrollRect != null && scrollRect.content != null)
            {
                worldLinkedSelectionUiContentRoot = scrollRect.content;
            }
        }

        if (worldLinkedSelectionUiContentRoot == null)
        {
            VerticalLayoutGroup existingLayout = worldLinkedSelectionUiRoot.GetComponentInChildren<VerticalLayoutGroup>(true);
            if (existingLayout != null)
            {
                worldLinkedSelectionUiContentRoot = existingLayout.transform as RectTransform;
            }
        }

        if (worldLinkedSelectionUiContentRoot == null)
        {
            RectTransform headerRect = worldLinkedSelectionUiHeaderLabel != null
                ? worldLinkedSelectionUiHeaderLabel.rectTransform
                : null;
            for (int i = 0; i < worldLinkedSelectionUiRoot.childCount; i++)
            {
                RectTransform child = worldLinkedSelectionUiRoot.GetChild(i) as RectTransform;
                if (child == null || child == headerRect)
                {
                    continue;
                }

                worldLinkedSelectionUiContentRoot = child;
                break;
            }
        }

        if (worldLinkedSelectionUiContentRoot == null && worldLinkedSelectionUiRoot.childCount == 0)
        {
            worldLinkedSelectionUiContentRoot = worldLinkedSelectionUiRoot;
        }

        if (worldLinkedSelectionUiContentRoot == null)
        {
            return false;
        }

        ConfigureWorldLinkedSelectionUiContentLayout();
        return worldLinkedSelectionUiRoot != null && worldLinkedSelectionUiContentRoot != null;
    }

    private void ConfigureWorldLinkedSelectionUiContentLayout()
    {
        // Intentionally no-op: preserve scene-authored layout/transform settings.
    }

    private void ResolveWorldLinkedSelectionUiSceneReferences()
    {
        if (worldLinkedSelectionUiRoot == null)
        {
            worldLinkedSelectionUiRoot = FindChildByName<RectTransform>("WorldLinkedSelectionPanel");
            worldLinkedSelectionUiRoot ??= FindChildByName<RectTransform>("LinkedSelectionPanel");
            worldLinkedSelectionUiRoot ??= FindChildByName<RectTransform>("SelectedPartsGroupPopup");
        }

        if (worldLinkedSelectionUiRoot == null)
        {
            return;
        }

        worldLinkedSelectionUiHeaderLabel ??= FindChildByNameIn<Text>(worldLinkedSelectionUiRoot, "Header");
        worldLinkedSelectionUiHeaderLabel ??= FindChildByNameIn<Text>(worldLinkedSelectionUiRoot, "Title");
        worldLinkedSelectionUiHeaderTmpLabel ??= FindChildByNameIn<TMP_Text>(worldLinkedSelectionUiRoot, "Header");
        worldLinkedSelectionUiHeaderTmpLabel ??= FindChildByNameIn<TMP_Text>(worldLinkedSelectionUiRoot, "Title");
        worldLinkedSelectionUiResizeChildRoot ??= FindChildByNameIn<RectTransform>(worldLinkedSelectionUiRoot, "GroupPanel");
        worldLinkedSelectionUiContentRoot ??= FindChildByNameIn<RectTransform>(worldLinkedSelectionUiRoot, "BodyParts");
        worldLinkedSelectionUiContentRoot ??= FindChildByNameIn<RectTransform>(worldLinkedSelectionUiRoot, "Content");
        worldLinkedSelectionUiContentRoot ??= FindChildByNameIn<RectTransform>(worldLinkedSelectionUiRoot, "List");
        worldLinkedSelectionUiContentRoot ??= worldLinkedSelectionUiResizeChildRoot;
    }

    private List<MinimoCharacterCustomizer.PartSlot> GetOrderedWorldLinkedSlots(
        Dictionary<MinimoCharacterCustomizer.PartSlot, HashSet<int>> linkedTargets)
    {
        List<MinimoCharacterCustomizer.PartSlot> ordered = new List<MinimoCharacterCustomizer.PartSlot>();
        if (linkedTargets == null || linkedTargets.Count == 0)
        {
            return ordered;
        }

        HashSet<MinimoCharacterCustomizer.PartSlot> added = new HashSet<MinimoCharacterCustomizer.PartSlot>();
        for (int i = 0; i < PartSelectionUiOrder.Length; i++)
        {
            MinimoCharacterCustomizer.PartSlot slot = PartSelectionUiOrder[i];
            if (!linkedTargets.ContainsKey(slot))
            {
                continue;
            }

            ordered.Add(slot);
            added.Add(slot);
        }

        foreach (KeyValuePair<MinimoCharacterCustomizer.PartSlot, HashSet<int>> pair in linkedTargets)
        {
            if (added.Contains(pair.Key))
            {
                continue;
            }

            ordered.Add(pair.Key);
        }

        return ordered;
    }

    private static bool TryGetFirstWorldLinkedTargetSlot(
        Dictionary<MinimoCharacterCustomizer.PartSlot, HashSet<int>> linkedTargets,
        out MinimoCharacterCustomizer.PartSlot slot)
    {
        slot = default;
        if (linkedTargets == null || linkedTargets.Count == 0)
        {
            return false;
        }

        for (int i = 0; i < PartSelectionUiOrder.Length; i++)
        {
            MinimoCharacterCustomizer.PartSlot orderedSlot = PartSelectionUiOrder[i];
            if (linkedTargets.ContainsKey(orderedSlot))
            {
                slot = orderedSlot;
                return true;
            }
        }

        foreach (KeyValuePair<MinimoCharacterCustomizer.PartSlot, HashSet<int>> pair in linkedTargets)
        {
            slot = pair.Key;
            return true;
        }

        return false;
    }

    private static int ComparePartSlotsForSelectionUi(
        MinimoCharacterCustomizer.PartSlot left,
        MinimoCharacterCustomizer.PartSlot right)
    {
        int leftOrder = GetPartSelectionUiOrder(left);
        int rightOrder = GetPartSelectionUiOrder(right);
        if (leftOrder != rightOrder)
        {
            return leftOrder.CompareTo(rightOrder);
        }

        return left.CompareTo(right);
    }

    private static int GetPartSelectionUiOrder(MinimoCharacterCustomizer.PartSlot slot)
    {
        for (int i = 0; i < PartSelectionUiOrder.Length; i++)
        {
            if (PartSelectionUiOrder[i] == slot)
            {
                return i;
            }
        }

        return int.MaxValue;
    }

    private void HandleWorldLinkedSlotToggleClicked(MinimoCharacterCustomizer.PartSlot slot)
    {
        if (!TryGetCurrentWorldLinkedMaterialTargets(out Dictionary<MinimoCharacterCustomizer.PartSlot, HashSet<int>> linkedTargets))
        {
            return;
        }

        SetWorldLinkedSlotSelectionStateForGroup(
            worldLinkedMaterialSelectionKey,
            linkedTargets,
            selectedWorldColorTargetSlot,
            focusOnly: false,
            preserveExistingForSameKey: true);

        bool current = IsWorldLinkedSlotSelected(slot);
        worldLinkedSlotSelectionKey = worldLinkedMaterialSelectionKey;
        worldLinkedSlotSelectionStates[slot] = !current;

        if (worldLinkedSlotSelectionStates[slot])
        {
            if (HasColorTargetsForWorldLinkedSlot(linkedTargets, slot))
            {
                selectedWorldColorTargetSlot = slot;
            }
            else if (!selectedWorldColorTargetSlot.HasValue
                     || !HasColorTargetsForWorldLinkedSlot(linkedTargets, selectedWorldColorTargetSlot.Value)
                     || !IsWorldLinkedSlotSelected(selectedWorldColorTargetSlot.Value))
            {
                if (TryGetFirstSelectedWorldLinkedSlot(linkedTargets, out MinimoCharacterCustomizer.PartSlot replacementSlot))
                {
                    selectedWorldColorTargetSlot = replacementSlot;
                }
                else
                {
                    selectedWorldColorTargetSlot = null;
                }
            }
        }
        else if (selectedWorldColorTargetSlot.HasValue && selectedWorldColorTargetSlot.Value == slot)
        {
            if (TryGetNextSelectedWorldLinkedSlot(linkedTargets, slot, out MinimoCharacterCustomizer.PartSlot replacementSlot))
            {
                selectedWorldColorTargetSlot = replacementSlot;
                selectedWorldPreviewTargetSlot = replacementSlot;
                EnsureWorldVariantTargetsIncludeReplacement(replacementSlot);
            }
            else
            {
                selectedWorldColorTargetSlot = null;
                selectedWorldPreviewTargetSlot = null;
            }
        }

        UpdateWorldLinkedSingleOverrideFromSelection(linkedTargets);
        selectedPaletteButtonIndex = -1;
        RefreshFromCustomizer();
    }

    private static bool HasColorTargetsForWorldLinkedSlot(
        Dictionary<MinimoCharacterCustomizer.PartSlot, HashSet<int>> linkedTargets,
        MinimoCharacterCustomizer.PartSlot slot)
    {
        return linkedTargets != null
               && linkedTargets.TryGetValue(slot, out HashSet<int> indices)
               && indices != null
               && indices.Count > 0;
    }

    private bool IsWorldLinkedSlotSelectionStateValidForCurrentKey()
    {
        return worldLinkedMaterialSelectionKeyValid
               && !string.IsNullOrWhiteSpace(worldLinkedMaterialSelectionKey)
               && !string.IsNullOrWhiteSpace(worldLinkedSlotSelectionKey)
               && string.Equals(worldLinkedMaterialSelectionKey, worldLinkedSlotSelectionKey, StringComparison.OrdinalIgnoreCase);
    }

    private bool IsWorldLinkedSlotSelected(MinimoCharacterCustomizer.PartSlot slot)
    {
        if (!IsWorldLinkedSlotSelectionStateValidForCurrentKey())
        {
            return true;
        }

        if (worldLinkedSlotSelectionStates.TryGetValue(slot, out bool selected))
        {
            return selected;
        }

        if (worldLinkedSelectionUiSlotOrder.Contains(slot))
        {
            return false;
        }

        return true;
    }

    private bool IsActiveWorldLinkedSelectionSlot(MinimoCharacterCustomizer.PartSlot slot)
    {
        return HasColorTargetsForWorldLinkedSlot(worldLinkedMaterialTargetsSnapshot, slot)
               && IsWorldLinkedSlotSelected(slot);
    }

    private void SetWorldLinkedSlotSelectionStateForGroup(
        string materialKey,
        Dictionary<MinimoCharacterCustomizer.PartSlot, HashSet<int>> linkedTargets,
        MinimoCharacterCustomizer.PartSlot? preferredActiveSlot,
        bool focusOnly,
        bool preserveExistingForSameKey)
    {
        if (string.IsNullOrWhiteSpace(materialKey) || linkedTargets == null || linkedTargets.Count == 0)
        {
            worldLinkedSlotSelectionStates.Clear();
            worldLinkedSlotSelectionKey = string.Empty;
            return;
        }

        Dictionary<MinimoCharacterCustomizer.PartSlot, bool> previousSelections = null;
        bool preserve = preserveExistingForSameKey
                        && !focusOnly
                        && IsWorldLinkedSlotSelectionStateValidForCurrentKey()
                        && string.Equals(worldLinkedSlotSelectionKey, materialKey, StringComparison.OrdinalIgnoreCase);
        if (preserve)
        {
            previousSelections = new Dictionary<MinimoCharacterCustomizer.PartSlot, bool>(worldLinkedSlotSelectionStates);
        }

        worldLinkedSlotSelectionStates.Clear();
        worldLinkedSlotSelectionKey = materialKey;

        bool hasFallbackSlot = TryGetFirstWorldLinkedTargetSlot(
            linkedTargets,
            out MinimoCharacterCustomizer.PartSlot fallbackSlot);
        foreach (KeyValuePair<MinimoCharacterCustomizer.PartSlot, HashSet<int>> pair in linkedTargets)
        {
            MinimoCharacterCustomizer.PartSlot slot = pair.Key;
            bool selected = true;
            if (focusOnly)
            {
                selected = preferredActiveSlot.HasValue && slot == preferredActiveSlot.Value;
            }
            else if (previousSelections != null && previousSelections.TryGetValue(slot, out bool previousSelection))
            {
                selected = previousSelection;
            }

            worldLinkedSlotSelectionStates[slot] = selected;
        }

        if (!focusOnly && previousSelections != null)
        {
            foreach (KeyValuePair<MinimoCharacterCustomizer.PartSlot, bool> pair in previousSelections)
            {
                if (worldLinkedSlotSelectionStates.ContainsKey(pair.Key))
                {
                    continue;
                }

                worldLinkedSlotSelectionStates[pair.Key] = pair.Value;
            }
        }

        if (focusOnly)
        {
            bool hasAnySelected = false;
            foreach (KeyValuePair<MinimoCharacterCustomizer.PartSlot, bool> pair in worldLinkedSlotSelectionStates)
            {
                if (!pair.Value)
                {
                    continue;
                }

                hasAnySelected = true;
                break;
            }

            if (!hasAnySelected && hasFallbackSlot)
            {
                MinimoCharacterCustomizer.PartSlot selectedSlot = preferredActiveSlot.HasValue
                                                                   && linkedTargets.ContainsKey(preferredActiveSlot.Value)
                    ? preferredActiveSlot.Value
                    : fallbackSlot;
                worldLinkedSlotSelectionStates[selectedSlot] = true;
            }
        }
        else
        {
            bool hasAnySelected = false;
            foreach (KeyValuePair<MinimoCharacterCustomizer.PartSlot, bool> pair in worldLinkedSlotSelectionStates)
            {
                if (!pair.Value)
                {
                    continue;
                }

                hasAnySelected = true;
                break;
            }

            if (!hasAnySelected)
            {
                List<MinimoCharacterCustomizer.PartSlot> slots = new List<MinimoCharacterCustomizer.PartSlot>(worldLinkedSlotSelectionStates.Keys);
                slots.Sort(ComparePartSlotsForSelectionUi);
                for (int i = 0; i < slots.Count; i++)
                {
                    worldLinkedSlotSelectionStates[slots[i]] = true;
                }
            }
        }
    }

    private void UpdateWorldLinkedSingleOverrideFromSelection(
        Dictionary<MinimoCharacterCustomizer.PartSlot, HashSet<int>> linkedTargets)
    {
        int selectedCount = CountSelectedWorldLinkedSlots(linkedTargets);
        worldLinkedMaterialSingleOverrideActive = selectedCount <= 1;
    }

    private int CountSelectedWorldLinkedSlots(
        Dictionary<MinimoCharacterCustomizer.PartSlot, HashSet<int>> linkedTargets)
    {
        if (linkedTargets == null || linkedTargets.Count == 0)
        {
            return 0;
        }

        int count = 0;
        foreach (KeyValuePair<MinimoCharacterCustomizer.PartSlot, HashSet<int>> pair in linkedTargets)
        {
            if (IsWorldLinkedSlotSelected(pair.Key))
            {
                count++;
            }
        }

        return count;
    }

    private bool TryGetFirstSelectedWorldLinkedSlot(
        Dictionary<MinimoCharacterCustomizer.PartSlot, HashSet<int>> linkedTargets,
        out MinimoCharacterCustomizer.PartSlot selectedSlot)
    {
        selectedSlot = default;
        if (linkedTargets == null || linkedTargets.Count == 0)
        {
            return false;
        }

        for (int i = 0; i < PartSelectionUiOrder.Length; i++)
        {
            MinimoCharacterCustomizer.PartSlot slot = PartSelectionUiOrder[i];
            if (linkedTargets.ContainsKey(slot) && IsWorldLinkedSlotSelected(slot))
            {
                selectedSlot = slot;
                return true;
            }
        }

        foreach (KeyValuePair<MinimoCharacterCustomizer.PartSlot, HashSet<int>> pair in linkedTargets)
        {
            if (!IsWorldLinkedSlotSelected(pair.Key))
            {
                continue;
            }

            selectedSlot = pair.Key;
            return true;
        }

        return false;
    }

    private bool TryGetNextSelectedWorldLinkedSlot(
        Dictionary<MinimoCharacterCustomizer.PartSlot, HashSet<int>> linkedTargets,
        MinimoCharacterCustomizer.PartSlot afterSlot,
        out MinimoCharacterCustomizer.PartSlot selectedSlot)
    {
        selectedSlot = default;
        List<MinimoCharacterCustomizer.PartSlot> orderedSlots = GetOrderedWorldLinkedSlots(linkedTargets);
        if (orderedSlots == null || orderedSlots.Count == 0)
        {
            return false;
        }

        int startIndex = orderedSlots.IndexOf(afterSlot);
        if (startIndex < 0)
        {
            return TryGetFirstSelectedWorldLinkedSlot(linkedTargets, out selectedSlot);
        }

        for (int offset = 1; offset <= orderedSlots.Count; offset++)
        {
            int index = (startIndex + offset) % orderedSlots.Count;
            MinimoCharacterCustomizer.PartSlot candidate = orderedSlots[index];
            if (IsWorldLinkedSlotSelected(candidate))
            {
                selectedSlot = candidate;
                return true;
            }
        }

        return false;
    }

    private void EnsureActiveWorldLinkedSlotSelection(
        Dictionary<MinimoCharacterCustomizer.PartSlot, HashSet<int>> linkedTargets)
    {
        if (!selectedWorldColorTargetSlot.HasValue)
        {
            return;
        }

        MinimoCharacterCustomizer.PartSlot activeSlot = selectedWorldColorTargetSlot.Value;
        if (IsWorldLinkedSlotSelected(activeSlot)
            && HasColorTargetsForWorldLinkedSlot(linkedTargets, activeSlot))
        {
            return;
        }

        if (TryGetNextSelectedWorldLinkedSlot(linkedTargets, activeSlot, out MinimoCharacterCustomizer.PartSlot replacementSlot))
        {
            selectedWorldColorTargetSlot = replacementSlot;
            selectedWorldPreviewTargetSlot = replacementSlot;
            EnsureWorldVariantTargetsIncludeReplacement(replacementSlot);
            return;
        }

        selectedWorldColorTargetSlot = null;
        selectedWorldPreviewTargetSlot = null;
    }

    private void EnsureWorldVariantTargetsIncludeReplacement(MinimoCharacterCustomizer.PartSlot replacementSlot)
    {
        if (!HasSelectedWorldVariantTargetSlots()
            || SlotArrayContains(selectedWorldVariantTargetSlots, replacementSlot))
        {
            return;
        }

        selectedWorldVariantTargetSlots = new[] { replacementSlot };
    }

    private RectTransform ResolveMaterialChannelStripRoot()
    {
        materialChannelStripRoot ??= FindChildByName<RectTransform>("MaterialChannelStrip");
        materialChannelStripRoot ??= FindChildByName<RectTransform>("MaterialChannels");
        materialChannelStripRoot ??= FindChildByName<RectTransform>("MaterialList");
        materialChannelStripRoot ??= FindChildByName<RectTransform>("ChannelList");
        if (materialChannelStripRoot != null
            && materialChannelStripRoot.TryGetComponent(out CanvasGroup canvasGroup))
        {
            canvasGroup.interactable = true;
            canvasGroup.blocksRaycasts = true;
        }

        RefreshMaterialChannelStripLayout(materialChannelStripRoot);
        return materialChannelStripRoot;
    }

    private List<MaterialChannelStripButtonView> PrepareMaterialChannelButtons(RectTransform stripRoot, int requiredCount)
    {
        List<MaterialChannelStripButtonView> views = new List<MaterialChannelStripButtonView>();
        if (stripRoot == null || requiredCount <= 0)
        {
            return views;
        }

        NormalizeMaterialChannelStripLayout(stripRoot);
        List<Button> buttons = CollectMaterialChannelStripButtons(stripRoot);
        if (buttons.Count == 0)
        {
            return views;
        }

        Button cloneTemplate = ResolveMaterialChannelCloneTemplate(buttons);
        SortMaterialChannelButtonsForSync(buttons, cloneTemplate);
        while (buttons.Count < requiredCount && cloneTemplate != null)
        {
            Button clone = InstantiateMaterialChannelButtonClone(cloneTemplate, buttons.Count);
            if (clone == null)
            {
                break;
            }

            buttons.Add(clone);
        }

        SortMaterialChannelButtonsForSync(buttons, cloneTemplate);
        for (int i = buttons.Count - 1; i >= requiredCount; i--)
        {
            Button extraButton = buttons[i];
            if (extraButton == null)
            {
                buttons.RemoveAt(i);
                continue;
            }

            int instanceId = extraButton.gameObject.GetInstanceID();
            DestroyGameObjectSafely(extraButton.gameObject);

            runtimeMaterialChannelButtonInstanceIds.Remove(instanceId);
            materialChannelBaseBackgroundColors.Remove(instanceId);
            buttons.RemoveAt(i);
        }

        Button styleTemplate = ResolveMaterialChannelCloneTemplate(buttons);
        for (int i = 0; i < buttons.Count; i++)
        {
            Button button = buttons[i];
            bool active = i < requiredCount;
            if (button != null)
            {
                NormalizeMaterialChannelButtonRect(button);
                ApplyMaterialChannelButtonVisualStyle(button, styleTemplate);
                button.gameObject.SetActive(active);
                button.interactable = active;
            }

            if (!active || button == null)
            {
                continue;
            }

            views.Add(new MaterialChannelStripButtonView
            {
                button = button,
                background = ResolveMaterialChannelButtonBackground(button),
                swatch = ResolveMaterialChannelButtonSwatch(button)
            });
        }

        RefreshMaterialChannelStripLayout(stripRoot);
        return views;
    }

    private static void SortMaterialChannelButtonsForSync(List<Button> buttons, Button preferredFirst)
    {
        if (buttons == null || buttons.Count <= 1)
        {
            return;
        }

        buttons.Sort((left, right) =>
        {
            if (ReferenceEquals(left, right))
            {
                return 0;
            }

            if (left == null)
            {
                return 1;
            }

            if (right == null)
            {
                return -1;
            }

            if (preferredFirst != null)
            {
                if (ReferenceEquals(left, preferredFirst))
                {
                    return -1;
                }

                if (ReferenceEquals(right, preferredFirst))
                {
                    return 1;
                }
            }

            Transform leftParent = left.transform.parent;
            Transform rightParent = right.transform.parent;
            if (leftParent != null && rightParent != null && ReferenceEquals(leftParent, rightParent))
            {
                int bySibling = left.transform.GetSiblingIndex().CompareTo(right.transform.GetSiblingIndex());
                if (bySibling != 0)
                {
                    return bySibling;
                }
            }

            return string.Compare(left.gameObject.name, right.gameObject.name, StringComparison.OrdinalIgnoreCase);
        });
    }

    private static Button ResolveMaterialChannelCloneTemplate(IReadOnlyList<Button> buttons)
    {
        if (buttons == null || buttons.Count == 0)
        {
            return null;
        }

        for (int i = 0; i < buttons.Count; i++)
        {
            Button candidate = buttons[i];
            if (candidate == null)
            {
                continue;
            }

            if (string.Equals(candidate.gameObject.name, "ColorChannel_01", StringComparison.OrdinalIgnoreCase))
            {
                return candidate;
            }
        }

        return buttons[0];
    }

    private static List<Button> CollectMaterialChannelStripButtons(RectTransform stripRoot)
    {
        List<Button> buttons = new List<Button>();
        if (stripRoot == null)
        {
            return buttons;
        }

        Button[] found = stripRoot.GetComponentsInChildren<Button>(true);
        for (int i = 0; i < found.Length; i++)
        {
            Button button = found[i];
            if (button == null)
            {
                continue;
            }

            if (HasButtonAncestorInsideStrip(button.transform, stripRoot))
            {
                continue;
            }

            buttons.Add(button);
        }

        return buttons;
    }

    private static bool HasButtonAncestorInsideStrip(Transform buttonTransform, RectTransform stripRoot)
    {
        if (buttonTransform == null || stripRoot == null)
        {
            return false;
        }

        Transform current = buttonTransform.parent;
        while (current != null && current != stripRoot)
        {
            if (current.GetComponent<Button>() != null)
            {
                return true;
            }

            current = current.parent;
        }

        return false;
    }

    private Button InstantiateMaterialChannelButtonClone(Button template, int index)
    {
        if (template == null || template.transform.parent == null)
        {
            return null;
        }

        GameObject cloneObject = Instantiate(template.gameObject, template.transform.parent, false);
        cloneObject.name = $"ColorChannel_{index + 1:00}";
        cloneObject.SetActive(true);

        Button clone = cloneObject.GetComponent<Button>();
        if (clone == null)
        {
            clone = cloneObject.AddComponent<Button>();
        }

        Image background = ResolveMaterialChannelButtonBackground(clone);
        if (background != null)
        {
            clone.targetGraphic = background;
            background.raycastTarget = true;
        }

        clone.onClick.RemoveAllListeners();
        clone.interactable = true;
        NormalizeMaterialChannelButtonRect(clone);
        runtimeMaterialChannelButtonInstanceIds.Add(cloneObject.GetInstanceID());
        return clone;
    }

    private static void NormalizeMaterialChannelStripLayout(RectTransform stripRoot)
    {
        if (stripRoot == null)
        {
            return;
        }

        stripRoot.SetSizeWithCurrentAnchors(RectTransform.Axis.Vertical, MaterialChannelStripMinHeight);

        LayoutElement stripLayout = stripRoot.GetComponent<LayoutElement>();
        if (stripLayout == null)
        {
            stripLayout = stripRoot.gameObject.AddComponent<LayoutElement>();
        }

        stripLayout.ignoreLayout = false;
        stripLayout.minHeight = MaterialChannelStripMinHeight;
        stripLayout.preferredHeight = MaterialChannelStripMinHeight;
        stripLayout.flexibleHeight = 0f;

        HorizontalLayoutGroup horizontal = stripRoot.GetComponent<HorizontalLayoutGroup>();
        if (horizontal != null)
        {
            horizontal.childControlWidth = false;
            horizontal.childControlHeight = false;
            horizontal.childForceExpandWidth = false;
            horizontal.childForceExpandHeight = false;

            if (horizontal.padding.top + horizontal.padding.bottom > MaterialChannelStripMinHeight - MaterialChannelButtonSize)
            {
                horizontal.padding = new RectOffset(horizontal.padding.left, horizontal.padding.right, 4, 4);
            }
        }
    }

    private static void NormalizeMaterialChannelButtonRect(Button button)
    {
        RectTransform rect = button != null ? button.transform as RectTransform : null;
        if (rect == null)
        {
            return;
        }

        rect.anchorMin = new Vector2(0f, 0.5f);
        rect.anchorMax = new Vector2(0f, 0.5f);
        rect.pivot = new Vector2(0f, 0.5f);
        rect.SetSizeWithCurrentAnchors(RectTransform.Axis.Horizontal, MaterialChannelButtonSize);
        rect.SetSizeWithCurrentAnchors(RectTransform.Axis.Vertical, MaterialChannelButtonSize);
        rect.sizeDelta = new Vector2(MaterialChannelButtonSize, MaterialChannelButtonSize);

        LayoutElement layout = button.GetComponent<LayoutElement>();
        if (layout == null)
        {
            layout = button.gameObject.AddComponent<LayoutElement>();
        }

        layout.ignoreLayout = false;
        layout.minWidth = MaterialChannelButtonSize;
        layout.minHeight = MaterialChannelButtonSize;
        layout.preferredWidth = MaterialChannelButtonSize;
        layout.preferredHeight = MaterialChannelButtonSize;
        layout.flexibleWidth = 0f;
        layout.flexibleHeight = 0f;
    }

    private static void RefreshMaterialChannelStripLayout(RectTransform stripRoot)
    {
        if (stripRoot == null)
        {
            return;
        }

        NormalizeMaterialChannelStripLayout(stripRoot);

        Button[] buttons = stripRoot.GetComponentsInChildren<Button>(true);
        for (int i = 0; i < buttons.Length; i++)
        {
            NormalizeMaterialChannelButtonRect(buttons[i]);
        }

        RectTransform parentRect = stripRoot.parent as RectTransform;
        if (parentRect != null)
        {
            LayoutRebuilder.ForceRebuildLayoutImmediate(parentRect);
            NormalizeMaterialChannelStripLayout(stripRoot);
            for (int i = 0; i < buttons.Length; i++)
            {
                NormalizeMaterialChannelButtonRect(buttons[i]);
            }
        }

        LayoutRebuilder.ForceRebuildLayoutImmediate(stripRoot);
        NormalizeMaterialChannelStripLayout(stripRoot);
        for (int i = 0; i < buttons.Length; i++)
        {
            NormalizeMaterialChannelButtonRect(buttons[i]);
        }
    }

    private bool IsRuntimeMaterialChannelClone(Button button)
    {
        return button != null && runtimeMaterialChannelButtonInstanceIds.Contains(button.gameObject.GetInstanceID());
    }

    private static void ApplyMaterialChannelButtonVisualStyle(Button button, Button template)
    {
        if (button == null)
        {
            return;
        }

        if (template != null)
        {
            button.transition = template.transition;
            button.colors = template.colors;

            if (template.targetGraphic is Image templateGraphic)
            {
                Image background = ResolveMaterialChannelButtonBackground(button);
                if (background != null)
                {
                    CopyImageStyle(templateGraphic, background, copyColor: true);
                    button.targetGraphic = background;
                }
            }

            return;
        }

        ColorBlock colors = button.colors;
        colors.normalColor = Color.white;
        colors.highlightedColor = Color.white;
        colors.pressedColor = Color.white;
        colors.selectedColor = Color.white;
        colors.disabledColor = Color.white;
        colors.colorMultiplier = 1f;
        colors.fadeDuration = 0.1f;
        button.colors = colors;
    }

    private static Image ResolveMaterialChannelButtonBackground(Button button)
    {
        if (button == null)
        {
            return null;
        }

        Image targetImage = button.targetGraphic as Image;
        Image selfImage = button.GetComponent<Image>();
        if (selfImage != null && !IsMaterialChannelSwatchImage(selfImage))
        {
            return selfImage;
        }

        if (targetImage != null && !IsMaterialChannelSwatchImage(targetImage))
        {
            return targetImage;
        }

        Image[] images = button.GetComponentsInChildren<Image>(true);
        for (int i = 0; i < images.Length; i++)
        {
            Image image = images[i];
            if (image == null || image.transform == button.transform || IsMaterialChannelSwatchImage(image))
            {
                continue;
            }

            return image;
        }

        if (targetImage != null)
        {
            return targetImage;
        }

        if (selfImage != null)
        {
            return selfImage;
        }

        return images.Length > 0 ? images[0] : null;
    }

    private static Image ResolveMaterialChannelButtonSwatch(Button button)
    {
        if (button == null)
        {
            return null;
        }

        Transform root = button.transform;
        Image[] images = button.GetComponentsInChildren<Image>(true);
        for (int i = 0; i < images.Length; i++)
        {
            Image image = images[i];
            if (image == null)
            {
                continue;
            }

            if (image.transform != root && IsMaterialChannelSwatchImage(image))
            {
                return image;
            }
        }

        Image background = ResolveMaterialChannelButtonBackground(button);
        for (int i = 0; i < images.Length; i++)
        {
            Image image = images[i];
            if (image == null || image == background || image.transform == root)
            {
                continue;
            }

            return image;
        }

        return null;
    }

    private static bool IsMaterialChannelSwatchImage(Image image)
    {
        if (image == null)
        {
            return false;
        }

        string name = image.gameObject.name ?? string.Empty;
        if (name.IndexOf("swatch", StringComparison.OrdinalIgnoreCase) >= 0
            || string.Equals(name, "color", StringComparison.OrdinalIgnoreCase)
            || name.StartsWith("color_", StringComparison.OrdinalIgnoreCase)
            || name.IndexOf("fill", StringComparison.OrdinalIgnoreCase) >= 0
            || name.IndexOf("dot", StringComparison.OrdinalIgnoreCase) >= 0)
        {
            return true;
        }

        RectTransform rect = image.transform as RectTransform;
        if (rect == null)
        {
            return false;
        }

        return rect.sizeDelta.x > 0f
               && rect.sizeDelta.y > 0f
               && rect.sizeDelta.x <= 36f
               && rect.sizeDelta.y <= 36f;
    }

    private static void SetMaterialChannelStripButtonsActive(RectTransform stripRoot, bool active)
    {
        if (stripRoot == null)
        {
            return;
        }

        Button[] buttons = stripRoot.GetComponentsInChildren<Button>(true);
        for (int i = 0; i < buttons.Length; i++)
        {
            Button button = buttons[i];
            if (button == null)
            {
                continue;
            }

            button.gameObject.SetActive(active);
            button.interactable = active;
        }
    }

    private List<ColorChannelDescriptor> BuildColorChannelDescriptorsForSlot(MinimoCharacterCustomizer.PartSlot slot)
    {
        List<ColorChannelDescriptor> descriptors = new List<ColorChannelDescriptor>();
        int channelCount = GetEditableColorChannelCountForSlot(slot);
        for (int channelIndex = 0; channelIndex < channelCount; channelIndex++)
        {
            int materialIndex = ResolveColorMaterialIndexForSlot(slot, channelIndex);
            string label = ResolveMaterialChannelDisplayName(slot, channelIndex, materialIndex);
            descriptors.Add(new ColorChannelDescriptor
            {
                label = label,
                materialIndex = channelIndex,
                targetType = ColorChannelTargetType.Material,
                facePropertyId = -1
            });
        }

        if (slot == MinimoCharacterCustomizer.PartSlot.Face)
        {
            AppendFaceColorChannelDescriptor(descriptors, "Eyes", ColorChannelTargetType.FaceEyes, FaceEyesShaderProperty);
            AppendFaceColorChannelDescriptor(descriptors, "Eyebrows", ColorChannelTargetType.FaceEyebrows, FaceEyebrowsShaderProperty);
            AppendFaceColorChannelDescriptor(descriptors, "Makeup", ColorChannelTargetType.FaceMakeup, FaceMakeupShaderProperty);
        }

        return descriptors;
    }

    private string ResolveMaterialChannelDisplayName(
        MinimoCharacterCustomizer.PartSlot slot,
        int channelIndex,
        int materialIndex)
    {
        if (!customizer.TryGetPartRenderer(slot, out SkinnedMeshRenderer renderer) || renderer == null)
        {
            return $"Mat {channelIndex + 1}";
        }

        Material[] materials = renderer.sharedMaterials;
        if (materials == null || materialIndex < 0 || materialIndex >= materials.Length)
        {
            return $"Mat {channelIndex + 1}";
        }

        Material material = materials[materialIndex];
        if (material == null || string.IsNullOrWhiteSpace(material.name))
        {
            return $"Mat {channelIndex + 1}";
        }

        string materialName = material.name.Replace(" (Instance)", string.Empty).Trim();
        if (string.IsNullOrWhiteSpace(materialName))
        {
            return $"Mat {channelIndex + 1}";
        }

        return materialName;
    }

    private void AppendFaceColorChannelDescriptor(
        List<ColorChannelDescriptor> descriptors,
        string label,
        ColorChannelTargetType targetType,
        int propertyId)
    {
        if (descriptors == null)
        {
            return;
        }

        if (!TryGetFaceMaterialChannelForProperty(propertyId, out int materialChannelIndex)
            || !TryGetFaceMaterialForChannel(materialChannelIndex, out Material faceMaterial)
            || faceMaterial == null
            || !faceMaterial.HasProperty(propertyId))
        {
            return;
        }

        descriptors.Add(new ColorChannelDescriptor
        {
            label = label,
            materialIndex = materialChannelIndex,
            targetType = targetType,
            facePropertyId = propertyId
        });
    }

    private void UnbindColorChannelEvents()
    {
        for (int i = 0; i < colorChannelButtons.Count; i++)
        {
            colorChannelButtons[i]?.button?.onClick.RemoveAllListeners();
        }
    }

    [ContextMenu("Customization UI/Rebuild Saved Prefabs")]
    private void ContextRebuildSavedPrefabs()
    {
        RefreshSavedPrefabCategoryDropdownOptions();
        RebuildSavedPrefabButtons(true);
    }

    private void RefreshSavedPrefabCategoryDropdownOptions()
    {
        string previousSelection = selectedSavedPrefabCategoryDropdownIndex >= 0
                                   && selectedSavedPrefabCategoryDropdownIndex < savedPrefabCategoryDropdownOptions.Count
            ? savedPrefabCategoryDropdownOptions[selectedSavedPrefabCategoryDropdownIndex]
            : SavedAllOptionLabel;

        List<string> options = new List<string>();
        AddSavedPrefabCategoryOptionIfMissing(options, SavedAllOptionLabel);

#if UNITY_EDITOR
        AddSavedPrefabCategoryOptionsWithCharacters(options);
#endif

        SortSavedPrefabCategoryDropdownOptions(options);

        savedPrefabCategoryDropdownOptions.Clear();
        savedPrefabCategoryDropdownOptions.AddRange(options);

        selectedSavedPrefabCategoryDropdownIndex = IndexOfSavedPrefabCategoryOption(previousSelection);
        if (selectedSavedPrefabCategoryDropdownIndex < 0)
        {
            selectedSavedPrefabCategoryDropdownIndex = IndexOfSavedPrefabCategoryOption(SavedAllOptionLabel);
        }

        if (selectedSavedPrefabCategoryDropdownIndex < 0 && savedPrefabCategoryDropdownOptions.Count > 0)
        {
            selectedSavedPrefabCategoryDropdownIndex = 0;
        }

        EnsureCustomSavedPrefabDropdown();
        RebuildCustomSavedPrefabDropdownOptions();

        if (savedPrefabsCategoryDropdown == null)
        {
            return;
        }

        isRefreshingSavedPrefabCategoryDropdown = true;
        try
        {
            List<TMP_Dropdown.OptionData> dropdownOptions = new List<TMP_Dropdown.OptionData>();
            for (int i = 0; i < savedPrefabCategoryDropdownOptions.Count; i++)
            {
                dropdownOptions.Add(new TMP_Dropdown.OptionData(BuildSavedPrefabDropdownOptionText(i)));
            }

            savedPrefabsCategoryDropdown.ClearOptions();
            savedPrefabsCategoryDropdown.AddOptions(dropdownOptions);
            int clampedIndex = Mathf.Clamp(
                selectedSavedPrefabCategoryDropdownIndex,
                0,
                Mathf.Max(0, savedPrefabCategoryDropdownOptions.Count - 1));
            selectedSavedPrefabCategoryDropdownIndex = clampedIndex;
            savedPrefabsCategoryDropdown.SetValueWithoutNotify(clampedIndex);
            savedPrefabsCategoryDropdown.RefreshShownValue();
            bool usesSceneDropdownButton = UsesSceneSavedPrefabDropdownButton();
            bool useFallbackSceneDropdown = customSavedPrefabDropdownRoot == null;
            if (!usesSceneDropdownButton)
            {
                savedPrefabsCategoryDropdown.interactable = useFallbackSceneDropdown && savedPrefabCategoryDropdownOptions.Count > 1;
            }

            savedPrefabsCategoryDropdown.gameObject.SetActive(usesSceneDropdownButton || useFallbackSceneDropdown);
            UpdateSavedPrefabCategoryDropdownLabel();
        }
        finally
        {
            isRefreshingSavedPrefabCategoryDropdown = false;
        }
    }

#if UNITY_EDITOR
    private static bool AddSavedPrefabCategoryOptionsWithCharacters(List<string> options)
    {
        if (options == null || !AssetDatabase.IsValidFolder(SavePrefabFolder))
        {
            return false;
        }

        string[] prefabGuids = AssetDatabase.FindAssets("t:Prefab", new[] { SavePrefabFolder });
        if (prefabGuids == null || prefabGuids.Length == 0)
        {
            return false;
        }

        bool addedAny = false;
        for (int i = 0; i < prefabGuids.Length; i++)
        {
            string assetPath = AssetDatabase.GUIDToAssetPath(prefabGuids[i]);
            if (string.IsNullOrWhiteSpace(assetPath))
            {
                continue;
            }

            int beforeCount = options.Count;
            AddSavedPrefabCategoryOptionIfMissing(options, ResolveSavedPrefabCategoryDisplayName(assetPath));
            addedAny |= options.Count > beforeCount;
        }

        return addedAny;
    }
#endif

    private static void SortSavedPrefabCategoryDropdownOptions(List<string> options)
    {
        if (options == null || options.Count <= 1)
        {
            return;
        }

        bool hasAll = false;
        List<string> folders = new List<string>();
        for (int i = 0; i < options.Count; i++)
        {
            string normalized = NormalizeSavedPrefabCategoryName(options[i]);
            if (string.IsNullOrWhiteSpace(normalized))
            {
                continue;
            }

            if (IsSavedAllCategoryName(normalized))
            {
                hasAll = true;
                continue;
            }

            AddSavedPrefabCategoryOptionIfMissing(folders, normalized);
        }

        folders.Sort(CompareSavedPrefabCategoryDropdownNames);

        options.Clear();
        if (hasAll)
        {
            options.Add(SavedAllOptionLabel);
        }

        for (int i = 0; i < folders.Count; i++)
        {
            options.Add(folders[i]);
        }
    }

    private static int CompareSavedPrefabCategoryDropdownNames(string left, string right)
    {
        int leftPriority = GetSavedPrefabCategoryDropdownPriority(left);
        int rightPriority = GetSavedPrefabCategoryDropdownPriority(right);
        if (leftPriority != rightPriority)
        {
            return leftPriority.CompareTo(rightPriority);
        }

        return CompareAlphabeticNatural(left, right);
    }

    private static int GetSavedPrefabCategoryDropdownPriority(string categoryName)
    {
        string normalized = NormalizeSavedPrefabCategoryName(categoryName);
        if (string.Equals(normalized, CategoryDefaultOptionLabel, StringComparison.OrdinalIgnoreCase))
        {
            return 0;
        }

        if (IsSavedCustomizationCategory(normalized))
        {
            return 2;
        }

        return 1;
    }

    private int IndexOfSavedPrefabCategoryOption(string categoryName)
    {
        string normalized = NormalizeSavedPrefabCategoryName(categoryName);
        for (int i = 0; i < savedPrefabCategoryDropdownOptions.Count; i++)
        {
            if (string.Equals(
                    NormalizeSavedPrefabCategoryName(savedPrefabCategoryDropdownOptions[i]),
                    normalized,
                    StringComparison.OrdinalIgnoreCase))
            {
                return i;
            }
        }

        return -1;
    }

    private void SelectSavedPrefabCategoryFilter(string categoryName)
    {
        int index = IndexOfSavedPrefabCategoryOption(categoryName);
        if (index < 0)
        {
            return;
        }

        selectedSavedPrefabCategoryDropdownIndex = index;
        isRefreshingSavedPrefabCategoryDropdown = true;
        try
        {
            if (savedPrefabsCategoryDropdown != null)
            {
                savedPrefabsCategoryDropdown.SetValueWithoutNotify(index);
                savedPrefabsCategoryDropdown.RefreshShownValue();
            }

            UpdateSavedPrefabCategoryDropdownLabel();
        }
        finally
        {
            isRefreshingSavedPrefabCategoryDropdown = false;
        }
    }

    private string GetSelectedSavedPrefabCategoryFilter()
    {
        if (selectedSavedPrefabCategoryDropdownIndex < 0
            || selectedSavedPrefabCategoryDropdownIndex >= savedPrefabCategoryDropdownOptions.Count)
        {
            return SavedAllOptionLabel;
        }

        return NormalizeSavedPrefabCategoryName(savedPrefabCategoryDropdownOptions[selectedSavedPrefabCategoryDropdownIndex]);
    }

    private bool IsSavedPrefabCategoryFilterSpecific()
    {
        string selected = GetSelectedSavedPrefabCategoryFilter();
        return !string.IsNullOrWhiteSpace(selected) && !IsSavedAllCategoryName(selected);
    }

    private void UpdateSavedPrefabCategoryDropdownLabel()
    {
        if (savedPrefabsCategoryDropdown == null)
        {
            if (customSavedPrefabDropdownLabel != null)
            {
                customSavedPrefabDropdownLabel.text = GetSelectedSavedPrefabCategoryFilter();
            }

            if (customSavedPrefabDropdownTmpLabel != null)
            {
                customSavedPrefabDropdownTmpLabel.text = GetSelectedSavedPrefabCategoryFilter();
            }

            return;
        }

        string label = GetSelectedSavedPrefabCategoryFilter();
        if (string.IsNullOrWhiteSpace(label))
        {
            label = SavedAllOptionLabel;
        }

        if (customSavedPrefabDropdownLabel != null)
        {
            customSavedPrefabDropdownLabel.text = label;
        }

        TMP_Text savedButtonTmpLabel = UsesSceneSavedPrefabDropdownButton()
            ? ResolveSavedPrefabDropdownButtonTmpLabel()
            : customSavedPrefabDropdownTmpLabel;
        if (savedButtonTmpLabel != null)
        {
            savedButtonTmpLabel.text = label;
            customSavedPrefabDropdownTmpLabel = savedButtonTmpLabel;
        }

        if (savedPrefabsCategoryDropdown.captionText != null)
        {
            savedPrefabsCategoryDropdown.captionText.text = label;
        }

        TMP_Text tmpLabel = ResolveSavedPrefabDropdownButtonTmpLabel();
        if (tmpLabel != null)
        {
            tmpLabel.text = label;
        }

        RefreshCustomSavedPrefabDropdownOptionTexts();
    }

    private static void AddSavedPrefabCategoryOptionIfMissing(List<string> options, string rawValue)
    {
        if (options == null)
        {
            return;
        }

        string normalized = NormalizeSavedPrefabCategoryName(rawValue);
        if (string.IsNullOrWhiteSpace(normalized))
        {
            return;
        }

        for (int i = 0; i < options.Count; i++)
        {
            if (string.Equals(
                    NormalizeSavedPrefabCategoryName(options[i]),
                    normalized,
                    StringComparison.OrdinalIgnoreCase))
            {
                return;
            }
        }

        options.Add(normalized);
    }

    private static string NormalizeSavedPrefabCategoryName(string value)
    {
        string normalized = string.IsNullOrWhiteSpace(value) ? string.Empty : value.Trim();
        if (string.Equals(normalized, LegacySaveCustomizationCategoryName, StringComparison.OrdinalIgnoreCase)
            || string.Equals(normalized, LegacySaveCustomizedCategoryName, StringComparison.OrdinalIgnoreCase))
        {
            return SaveCustomizationCategoryName;
        }

        if (string.Equals(normalized, CategoryAllOptionLabel, StringComparison.OrdinalIgnoreCase)
            || string.Equals(normalized, LegacyEverythingOptionLabel, StringComparison.OrdinalIgnoreCase))
        {
            return SavedAllOptionLabel;
        }

        return normalized;
    }

    private static bool IsSavedAllCategoryName(string categoryName)
    {
        return string.Equals(NormalizeSavedPrefabCategoryName(categoryName), SavedAllOptionLabel, StringComparison.OrdinalIgnoreCase);
    }

    private static bool IsSavedCustomizationCategory(string categoryName)
    {
        return string.Equals(
            NormalizeSavedPrefabCategoryName(categoryName),
            SaveCustomizationCategoryName,
            StringComparison.OrdinalIgnoreCase);
    }

    private void RebuildSavedPrefabButtons(bool force = false)
    {
        if (savePrefabsContent == null)
        {
            return;
        }

#if !UNITY_EDITOR
        savedPrefabButtonsInitialized = true;
        return;
#else
        string[] prefabPaths = BuildFilteredSortedSavedPrefabAssetPaths();
        bool deferPreviewBuild = ShouldDeferSavedPrefabPreviewGeneration();
        savedPrefabButtonsInitialized = true;
        if (!force && savedPrefabButtons.Count == prefabPaths.Length)
        {
            bool matchesCurrent = true;
            for (int i = 0; i < prefabPaths.Length; i++)
            {
                SavedPrefabButtonEntry existing = savedPrefabButtons[i];
                if (existing == null || !string.Equals(existing.assetPath, prefabPaths[i], StringComparison.OrdinalIgnoreCase))
                {
                    matchesCurrent = false;
                    break;
                }
            }

            if (matchesCurrent)
            {
                if (deferPreviewBuild)
                {
                    StartSavedPrefabPreviewWarmup();
                }

                return;
            }
        }

        string previouslySelectedPath = selectedSavedPrefabIndex >= 0 && selectedSavedPrefabIndex < savedPrefabButtons.Count
            ? savedPrefabButtons[selectedSavedPrefabIndex]?.assetPath
            : string.Empty;
        Button savedPrefabTemplateButton = ResolveSavedPrefabButtonTemplate();
        Transform savedPrefabTemplateTransform = savedPrefabTemplateButton != null ? savedPrefabTemplateButton.transform : null;

        UnbindSavedPrefabEvents();
        savedPrefabButtons.Clear();
        ClearSavedPrefabPreviewTextures();

        for (int i = savePrefabsContent.childCount - 1; i >= 0; i--)
        {
            Transform child = savePrefabsContent.GetChild(i);
            if (savedPrefabTemplateTransform != null && child == savedPrefabTemplateTransform)
            {
                child.gameObject.SetActive(false);
                continue;
            }

            DestroyGameObjectSafely(child.gameObject);
        }

        Font font = ResolveFont();
        CacheVariantButtonVisualStyle();

        if (savedPrefabTemplateTransform != null)
        {
            savedPrefabTemplateTransform.gameObject.SetActive(false);
        }

        for (int i = 0; i < prefabPaths.Length; i++)
        {
            string path = prefabPaths[i];
            string fileName = Path.GetFileNameWithoutExtension(path);
            Button button = CreateSavedPrefabButton(savePrefabsContent, savedPrefabTemplateButton, font, fileName, i);
            ApplyVariantButtonVisualStyle(button);
            ApplyVariantCategoryBorder(button, string.Empty, isRandom: false);
            EnsureShadowPressTracking(button);
            string capturedPath = path;
            int capturedIndex = i;

            if (!deferPreviewBuild)
            {
                GameObject savedPrefab = AssetDatabase.LoadAssetAtPath<GameObject>(capturedPath);
                TryApplySavedPrefabButtonPreview(button, savedPrefab, capturedPath);
            }

            string categoryName = ResolveSavedPrefabCategoryDisplayName(capturedPath);
            bool canDelete = CanDeleteSavedPrefab(capturedPath);
            Button deleteButton = CreateSavedPrefabDeleteButton(button, capturedPath, fileName, canDelete);

            button.onClick.RemoveAllListeners();
            button.onClick.AddListener(() => ApplySavedPrefabByIndex(capturedIndex));
            savedPrefabButtons.Add(new SavedPrefabButtonEntry
            {
                assetPath = capturedPath,
                displayName = fileName,
                categoryName = categoryName,
                canDelete = canDelete,
                button = button,
                deleteButton = deleteButton
            });
        }

        if (savedPrefabButtons.Count == 0)
        {
            selectedSavedPrefabIndex = -1;
        }
        else if (!string.IsNullOrWhiteSpace(previouslySelectedPath))
        {
            selectedSavedPrefabIndex = 0;
            for (int i = 0; i < savedPrefabButtons.Count; i++)
            {
                SavedPrefabButtonEntry entry = savedPrefabButtons[i];
                if (entry != null && string.Equals(entry.assetPath, previouslySelectedPath, StringComparison.OrdinalIgnoreCase))
                {
                    selectedSavedPrefabIndex = i;
                    break;
                }
            }
        }
        else if (selectedSavedPrefabIndex < 0 || selectedSavedPrefabIndex >= savedPrefabButtons.Count)
        {
            selectedSavedPrefabIndex = 0;
        }

        UpdateSavedPrefabsContentSize();
        UpdateSavedPrefabButtonVisuals();
        if (deferPreviewBuild)
        {
            StartSavedPrefabPreviewWarmup();
        }
#endif
    }

    private void EnsureSavedPrefabButtonsInitialized()
    {
        if (!savedPrefabButtonsInitialized)
        {
            RebuildSavedPrefabButtons();
            return;
        }

        UpdateSavedPrefabsContentSize();
        UpdateSavedPrefabButtonVisuals();
    }

    private bool ShouldDeferSavedPrefabPreviewGeneration()
    {
        return Application.isPlaying && deferSavedPrefabPreviewGeneration;
    }

    private void StartSavedPrefabPreviewWarmup()
    {
        if (!Application.isPlaying
            || savedPrefabButtons.Count == 0
            || !IsSavedPanelActive())
        {
            return;
        }

        if (savedPrefabPreviewWarmupCoroutine != null)
        {
            StopCoroutine(savedPrefabPreviewWarmupCoroutine);
        }

        savedPrefabPreviewWarmupCoroutine = StartCoroutine(WarmSavedPrefabPreviewsDeferred());
    }

    private IEnumerator WarmSavedPrefabPreviewsDeferred()
    {
        yield return null;
        yield return null;
        yield return null;

        deferSavedPrefabPreviewGeneration = false;
#if UNITY_EDITOR
        float frameStart = Time.realtimeSinceStartup;
        float frameBudgetMs = Mathf.Max(0.1f, startupPreviewWarmupFrameBudgetMs);
        for (int i = 0; i < savedPrefabButtons.Count; i++)
        {
            SavedPrefabButtonEntry entry = savedPrefabButtons[i];
            if (entry == null
                || entry.button == null
                || string.IsNullOrWhiteSpace(entry.assetPath))
            {
                continue;
            }

            GameObject savedPrefab = AssetDatabase.LoadAssetAtPath<GameObject>(entry.assetPath);
            TryApplySavedPrefabButtonPreview(entry.button, savedPrefab, entry.assetPath);

            if ((Time.realtimeSinceStartup - frameStart) * 1000f >= frameBudgetMs)
            {
                frameStart = Time.realtimeSinceStartup;
                yield return null;
            }
        }
#endif

        savedPrefabPreviewWarmupCoroutine = null;
    }

    private Button ResolveSavedPrefabButtonTemplate()
    {
        Button template = null;
        if (savePrefabsScroll != null && savePrefabsScroll.viewport != null)
        {
            template = FindChildByNameIn<Button>(savePrefabsScroll.viewport, "Part_00");
            if (template != null)
            {
                return template;
            }
        }

        if (savePrefabsPanelRoot != null)
        {
            template = FindChildByNameIn<Button>(savePrefabsPanelRoot, "Part_00");
            if (template != null)
            {
                return template;
            }
        }

        if (savePrefabsContent != null)
        {
            template = FindChildByNameIn<Button>(savePrefabsContent, "Part_00");
            if (template != null)
            {
                return template;
            }
        }

#if UNITY_EDITOR
        GameObject templatePrefab = AssetDatabase.LoadAssetAtPath<GameObject>(SavedPrefabCardTemplateAssetPath);
        if (templatePrefab != null)
        {
            template = templatePrefab.GetComponent<Button>();
            template ??= templatePrefab.GetComponentInChildren<Button>(true);
        }
#endif

        return template;
    }

    private Button CreateSavedPrefabButton(
        Transform parent,
        Button templateButton,
        Font font,
        string label,
        int variantIndex)
    {
        if (parent == null)
        {
            return null;
        }

        if (templateButton == null)
        {
            return CreateVariantButton(parent, font, label, variantIndex);
        }

        GameObject instance = Instantiate(templateButton.gameObject, parent, false);
        instance.name = $"Part_{variantIndex + 1:00}";
        instance.SetActive(true);

        Button button = instance.GetComponent<Button>();
        if (button == null)
        {
            button = instance.GetComponentInChildren<Button>(true);
        }

        if (button == null)
        {
            if (Application.isPlaying)
            {
                Destroy(instance);
            }
            else
            {
                DestroyImmediate(instance);
            }

            return CreateVariantButton(parent, font, label, variantIndex);
        }

        ConfigureButtonInstanceFromTemplate(button, label);

        return button;
    }

    private Button CreateSavedPrefabDeleteButton(Button hostButton, string assetPath, string displayName, bool canDelete)
    {
        if (hostButton == null)
        {
            return null;
        }

        Button deleteButton = FindChildByNameIn<Button>(hostButton.transform, "DeleteButton");
        if (deleteButton == null)
        {
            return null;
        }

        GameObject deleteVisualRoot = ResolveSavedPrefabDeleteVisualRoot(hostButton, deleteButton);
        if (deleteVisualRoot != null)
        {
            deleteVisualRoot.SetActive(canDelete);
        }

        deleteButton.gameObject.SetActive(canDelete);
        deleteButton.interactable = canDelete;
        if (!canDelete)
        {
            deleteButton.onClick.RemoveAllListeners();
            RemoveShadowPressTracking(deleteButton);
            return null;
        }

        string capturedPath = assetPath;
        string capturedDisplayName = displayName;
        deleteButton.onClick.RemoveAllListeners();
        deleteButton.onClick.AddListener(() => HandleDeleteSavedPrefabButtonClicked(capturedPath, capturedDisplayName));
        EnsureShadowPressTracking(deleteButton);
        return deleteButton;
    }

    private static GameObject ResolveSavedPrefabDeleteVisualRoot(Button hostButton, Button deleteButton)
    {
        if (deleteButton == null)
        {
            return null;
        }

        Transform hostTransform = hostButton != null ? hostButton.transform : null;
        Transform current = deleteButton.transform.parent;
        while (current != null && current != hostTransform)
        {
            string currentName = current.name ?? string.Empty;
            if (currentName.IndexOf("shadow", StringComparison.OrdinalIgnoreCase) >= 0)
            {
                return current.gameObject;
            }

            current = current.parent;
        }

        return deleteButton.gameObject;
    }

    private void HandleDeleteSavedPrefabButtonClicked(string assetPath, string displayName)
    {
        if (string.IsNullOrWhiteSpace(assetPath))
        {
            return;
        }

        if (!CanDeleteSavedPrefab(assetPath))
        {
            helperOverrideMessage = "Only Customize saved characters can be deleted.";
            RefreshFromCustomizer();
            return;
        }

        if (!ShowDeleteSavedPrefabPopup(assetPath, displayName))
        {
            helperOverrideMessage = "Delete popup was not found.";
            RefreshFromCustomizer();
        }
    }

    private void DeleteSavedPrefabAsset(string assetPath)
    {
#if !UNITY_EDITOR
        _ = assetPath;
        helperOverrideMessage = "Deleting saved characters is only supported in Editor mode.";
        RefreshFromCustomizer();
        return;
#else
        string normalizedAssetPath = string.IsNullOrWhiteSpace(assetPath)
            ? string.Empty
            : assetPath.Replace('\\', '/');
        if (string.IsNullOrWhiteSpace(normalizedAssetPath))
        {
            return;
        }

        if (!CanDeleteSavedPrefab(normalizedAssetPath))
        {
            helperOverrideMessage = "Only Customize saved characters can be deleted.";
            RefreshFromCustomizer();
            return;
        }

        string materialFolderPath = BuildSavedCharacterMaterialsFolderPath(normalizedAssetPath);
        bool deletedPrefab = AssetDatabase.DeleteAsset(normalizedAssetPath);
        bool materialFolderExisted = !string.IsNullOrWhiteSpace(materialFolderPath)
                                     && AssetDatabase.IsValidFolder(materialFolderPath);
        bool deletedMaterials = false;
        if (materialFolderExisted)
        {
            deletedMaterials = AssetDatabase.DeleteAsset(materialFolderPath);
        }

        if (!deletedPrefab)
        {
            helperOverrideMessage = "Could not delete selected character.";
            RefreshFromCustomizer();
            return;
        }

        AssetDatabase.SaveAssets();
        AssetDatabase.Refresh();
        RefreshSavedPrefabCategoryDropdownOptions();

        bool deletedLoadedPrefab = string.Equals(loadedSavedPrefabPath, normalizedAssetPath, StringComparison.OrdinalIgnoreCase);
        if (deletedLoadedPrefab)
        {
            loadedSavedPrefabPath = string.Empty;
            loadedSavedPrefabStateSignature = string.Empty;
            SelectSavedPrefabCategoryFilter(SavedAllOptionLabel);
        }

        int desiredSelectionIndex = selectedSavedPrefabIndex;
        RebuildSavedPrefabButtons(true);
        if (savedPrefabButtons.Count > 0)
        {
            if (deletedLoadedPrefab)
            {
                if (!TrySelectSavedPrefabEntryByCategory(CategoryDefaultOptionLabel))
                {
                    selectedSavedPrefabIndex = -1;
                }
            }
            else
            {
                selectedSavedPrefabIndex = Mathf.Clamp(desiredSelectionIndex, 0, savedPrefabButtons.Count - 1);
            }
        }
        else
        {
            selectedSavedPrefabIndex = -1;
        }

        if (deletedLoadedPrefab)
        {
            ResetCurrentCharacterToDefault(savePersistentState: true);
        }

        UpdateSavedPrefabButtonVisuals();
        UpdateSavedPanelPresentation();
        helperOverrideMessage = materialFolderExisted && !deletedMaterials
            ? "Character deleted, but material folder could not be removed."
            : deletedMaterials
            ? "Character deleted (materials removed)."
            : "Character deleted.";
        RefreshFromCustomizer();
#endif
    }

    private void UnbindSavedPrefabEvents()
    {
        for (int i = 0; i < savedPrefabButtons.Count; i++)
        {
            savedPrefabButtons[i]?.button?.onClick.RemoveAllListeners();
            savedPrefabButtons[i]?.deleteButton?.onClick.RemoveAllListeners();
        }
    }

#if UNITY_EDITOR
    private string[] BuildFilteredSortedSavedPrefabAssetPaths()
    {
        string[] prefabGuids = AssetDatabase.FindAssets("t:Prefab", new[] { SavePrefabFolder });
        if (prefabGuids == null || prefabGuids.Length == 0)
        {
            return Array.Empty<string>();
        }

        string selectedCategory = GetSelectedSavedPrefabCategoryFilter();
        bool hasSpecificCategoryFilter = IsSavedPrefabCategoryFilterSpecific();
        List<string> paths = new List<string>(prefabGuids.Length);
        for (int i = 0; i < prefabGuids.Length; i++)
        {
            string path = AssetDatabase.GUIDToAssetPath(prefabGuids[i]);
            if (string.IsNullOrWhiteSpace(path))
            {
                continue;
            }

            if (hasSpecificCategoryFilter && !SavedPrefabMatchesCategory(path, selectedCategory))
            {
                continue;
            }

            paths.Add(path);
        }

        if (!IsSavedCustomizationCategory(selectedCategory))
        {
            CollapseDuplicateNonCustomizationSavedPrefabs(paths);
        }

        paths.Sort(CompareSavedPrefabAssetPaths);
        return paths.ToArray();
    }

    private static int CompareSavedPrefabAssetPaths(string left, string right)
    {
        string leftCategory = ResolveSavedPrefabCategoryDisplayName(left);
        string rightCategory = ResolveSavedPrefabCategoryDisplayName(right);
        int leftPriority = GetSavedPrefabAssetCategorySortPriority(leftCategory);
        int rightPriority = GetSavedPrefabAssetCategorySortPriority(rightCategory);
        if (leftPriority != rightPriority)
        {
            return leftPriority.CompareTo(rightPriority);
        }

        int byCategory = CompareAlphabeticNatural(leftCategory, rightCategory);
        if (byCategory != 0)
        {
            return byCategory;
        }

        string leftName = Path.GetFileNameWithoutExtension(left) ?? string.Empty;
        string rightName = Path.GetFileNameWithoutExtension(right) ?? string.Empty;
        int byName = CompareAlphabeticNatural(leftName, rightName);
        if (byName != 0)
        {
            return byName;
        }

        return string.Compare(left, right, StringComparison.OrdinalIgnoreCase);
    }

    private static int GetSavedPrefabAssetCategorySortPriority(string categoryName)
    {
        string normalized = NormalizeSavedPrefabCategoryName(categoryName);
        if (string.Equals(normalized, CategoryDefaultOptionLabel, StringComparison.OrdinalIgnoreCase))
        {
            return 0;
        }

        if (IsSavedCustomizationCategory(normalized))
        {
            return 2;
        }

        return 1;
    }

    private static void CollapseDuplicateNonCustomizationSavedPrefabs(List<string> paths)
    {
        if (paths == null || paths.Count <= 1)
        {
            return;
        }

        Dictionary<string, int> folderContentCounts = BuildSavedPrefabFolderContentCounts(paths);
        Dictionary<string, List<SavedPrefabDuplicateCandidate>> candidatesByColorSignature = new Dictionary<string, List<SavedPrefabDuplicateCandidate>>(StringComparer.Ordinal);
        for (int i = 0; i < paths.Count; i++)
        {
            string path = paths[i];
            if (IsSavedCustomizationCategory(ResolveSavedPrefabCategoryDisplayName(path))
                || !TryBuildSavedPrefabAllPartColorsSignature(path, out string signature)
                || string.IsNullOrWhiteSpace(signature))
            {
                continue;
            }

            string folderPath = ResolveSavedPrefabFolderPath(path);
            if (string.IsNullOrWhiteSpace(folderPath))
            {
                continue;
            }

            if (!candidatesByColorSignature.TryGetValue(signature, out List<SavedPrefabDuplicateCandidate> candidates))
            {
                candidates = new List<SavedPrefabDuplicateCandidate>();
                candidatesByColorSignature[signature] = candidates;
            }

            candidates.Add(new SavedPrefabDuplicateCandidate
            {
                assetPath = path,
                folderPath = folderPath
            });
        }

        HashSet<string> pathsToRemove = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        foreach (KeyValuePair<string, List<SavedPrefabDuplicateCandidate>> pair in candidatesByColorSignature)
        {
            List<SavedPrefabDuplicateCandidate> candidates = pair.Value;
            if (!SavedPrefabDuplicateGroupSpansFolders(candidates))
            {
                continue;
            }

            string preferredFolder = ResolvePreferredSavedPrefabDuplicateFolder(candidates, folderContentCounts);
            if (string.IsNullOrWhiteSpace(preferredFolder))
            {
                continue;
            }

            for (int i = 0; i < candidates.Count; i++)
            {
                SavedPrefabDuplicateCandidate candidate = candidates[i];
                if (candidate == null
                    || string.Equals(candidate.folderPath, preferredFolder, StringComparison.OrdinalIgnoreCase))
                {
                    continue;
                }

                pathsToRemove.Add(candidate.assetPath);
            }
        }

        if (pathsToRemove.Count == 0)
        {
            return;
        }

        for (int i = paths.Count - 1; i >= 0; i--)
        {
            if (pathsToRemove.Contains(paths[i]))
            {
                paths.RemoveAt(i);
            }
        }
    }

    private static Dictionary<string, int> BuildSavedPrefabFolderContentCounts(List<string> paths)
    {
        Dictionary<string, int> counts = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);
        if (paths == null)
        {
            return counts;
        }

        for (int i = 0; i < paths.Count; i++)
        {
            string path = paths[i];
            if (IsSavedCustomizationCategory(ResolveSavedPrefabCategoryDisplayName(path)))
            {
                continue;
            }

            string folderPath = ResolveSavedPrefabFolderPath(path);
            if (string.IsNullOrWhiteSpace(folderPath))
            {
                continue;
            }

            counts.TryGetValue(folderPath, out int count);
            counts[folderPath] = count + 1;
        }

        return counts;
    }

    private static bool SavedPrefabDuplicateGroupSpansFolders(List<SavedPrefabDuplicateCandidate> candidates)
    {
        if (candidates == null || candidates.Count <= 1)
        {
            return false;
        }

        string firstFolder = string.Empty;
        for (int i = 0; i < candidates.Count; i++)
        {
            SavedPrefabDuplicateCandidate candidate = candidates[i];
            if (candidate == null || string.IsNullOrWhiteSpace(candidate.folderPath))
            {
                continue;
            }

            if (string.IsNullOrWhiteSpace(firstFolder))
            {
                firstFolder = candidate.folderPath;
                continue;
            }

            if (!string.Equals(firstFolder, candidate.folderPath, StringComparison.OrdinalIgnoreCase))
            {
                return true;
            }
        }

        return false;
    }

    private static string ResolvePreferredSavedPrefabDuplicateFolder(
        List<SavedPrefabDuplicateCandidate> candidates,
        Dictionary<string, int> folderContentCounts)
    {
        if (candidates == null || candidates.Count == 0)
        {
            return string.Empty;
        }

        Dictionary<string, string> bestPathByFolder = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
        for (int i = 0; i < candidates.Count; i++)
        {
            SavedPrefabDuplicateCandidate candidate = candidates[i];
            if (candidate == null
                || string.IsNullOrWhiteSpace(candidate.folderPath)
                || string.IsNullOrWhiteSpace(candidate.assetPath))
            {
                continue;
            }

            if (!bestPathByFolder.TryGetValue(candidate.folderPath, out string bestPath)
                || CompareSavedPrefabAssetPaths(candidate.assetPath, bestPath) < 0)
            {
                bestPathByFolder[candidate.folderPath] = candidate.assetPath;
            }
        }

        string preferredFolder = string.Empty;
        string preferredRepresentativePath = string.Empty;
        int preferredFolderCount = -1;
        foreach (KeyValuePair<string, string> pair in bestPathByFolder)
        {
            string folderPath = pair.Key;
            string representativePath = pair.Value;
            int folderCount = 0;
            folderContentCounts?.TryGetValue(folderPath, out folderCount);

            bool isBetter = string.IsNullOrWhiteSpace(preferredFolder)
                            || folderCount > preferredFolderCount
                            || (folderCount == preferredFolderCount
                                && CompareSavedPrefabAssetPaths(representativePath, preferredRepresentativePath) < 0);
            if (!isBetter)
            {
                continue;
            }

            preferredFolder = folderPath;
            preferredRepresentativePath = representativePath;
            preferredFolderCount = folderCount;
        }

        return preferredFolder;
    }

    private static string ResolveSavedPrefabFolderPath(string assetPath)
    {
        return GetParentCategoryAssetFolder(NormalizeCategoryAssetPath(assetPath));
    }

    private static bool TryBuildSavedPrefabAllPartColorsSignature(string assetPath, out string signature)
    {
        signature = string.Empty;
        if (string.IsNullOrWhiteSpace(assetPath))
        {
            return false;
        }

        GameObject savedPrefab = AssetDatabase.LoadAssetAtPath<GameObject>(assetPath);
        if (savedPrefab == null)
        {
            return false;
        }

        StringBuilder builder = new StringBuilder();
        bool useCustomizerSignature = IsSavedCustomizationCategory(ResolveSavedPrefabCategoryDisplayName(assetPath));
        if (useCustomizerSignature
            && TryResolveSavedPrefabCustomizer(savedPrefab, out MinimoCharacterCustomizer savedCustomizer)
            && savedCustomizer != null)
        {
            IReadOnlyList<MinimoCharacterCustomizer.PartSlot> slots = MinimoCharacterCustomizer.Slots;
            for (int i = 0; i < slots.Count; i++)
            {
                MinimoCharacterCustomizer.PartSlot slot = slots[i];
                builder.Append((int)slot);
                builder.Append(':');
                builder.Append(savedCustomizer.GetPartVariant(slot));
                builder.Append(':');
                bool rendererVisible = savedCustomizer.TryGetPartRenderer(slot, out SkinnedMeshRenderer slotRenderer)
                                       && slotRenderer != null
                                       && slotRenderer.enabled
                                       && slotRenderer.sharedMesh != null;
                builder.Append(rendererVisible ? "visible:" : "hidden:");
                AppendSavedPrefabSlotColorSignature(builder, savedCustomizer, slot);
                builder.Append(';');
            }

            AppendSavedPrefabFaceChannelColorSignature(builder, savedCustomizer);
        }
        else
        {
            AppendSavedPrefabRawRendererColorSignature(builder, savedPrefab.transform);
        }

        signature = builder.ToString();
        return !string.IsNullOrWhiteSpace(signature);
    }

    private static bool TryResolveSavedPrefabCustomizer(
        GameObject savedPrefab,
        out MinimoCharacterCustomizer savedCustomizer)
    {
        savedCustomizer = null;
        if (savedPrefab == null)
        {
            return false;
        }

        savedCustomizer = savedPrefab.GetComponent<MinimoCharacterCustomizer>();
        if (savedCustomizer != null)
        {
            return true;
        }

        savedCustomizer = savedPrefab.GetComponentInChildren<MinimoCharacterCustomizer>(true);
        return savedCustomizer != null;
    }

    private static void AppendSavedPrefabRawRendererColorSignature(StringBuilder builder, Transform root)
    {
        if (builder == null)
        {
            return;
        }

        IReadOnlyList<MinimoCharacterCustomizer.PartSlot> slots = MinimoCharacterCustomizer.Slots;
        for (int i = 0; i < slots.Count; i++)
        {
            MinimoCharacterCustomizer.PartSlot slot = slots[i];
            builder.Append((int)slot);
            builder.Append(':');
            if (TryFindSavedPrefabRendererForSlot(root, slot, out SkinnedMeshRenderer renderer) && renderer != null)
            {
                AppendRendererDisplayColorSignature(builder, renderer);
            }
            else
            {
                builder.Append("none");
            }

            builder.Append(';');
        }
    }

    private static void AppendRendererDisplayColorSignature(StringBuilder builder, Renderer renderer)
    {
        if (builder == null)
        {
            return;
        }

        if (renderer == null || !renderer.enabled)
        {
            builder.Append("none");
            return;
        }

        Material[] materials = renderer.sharedMaterials;
        int materialCount = materials != null ? materials.Length : 0;
        List<string> colorTokens = new List<string>();
        for (int materialIndex = 0; materialIndex < materialCount; materialIndex++)
        {
            Material material = materials[materialIndex];
            if (TryGetMaterialDisplayColor(material, out Color color))
            {
                AddColorSignatureTokenIfMissing(colorTokens, color);
            }
        }

        if (colorTokens.Count == 0)
        {
            builder.Append("none");
            return;
        }

        colorTokens.Sort(StringComparer.Ordinal);
        for (int i = 0; i < colorTokens.Count; i++)
        {
            builder.Append(colorTokens[i]);
            builder.Append('|');
        }
    }

    private static bool TryFindSavedPrefabRendererForSlot(
        Transform root,
        MinimoCharacterCustomizer.PartSlot slot,
        out SkinnedMeshRenderer renderer)
    {
        renderer = null;
        if (root == null)
        {
            return false;
        }

        string preferredName = GetSavedPrefabRendererNodeName(slot);
        SkinnedMeshRenderer[] renderers = root.GetComponentsInChildren<SkinnedMeshRenderer>(true);
        for (int i = 0; i < renderers.Length; i++)
        {
            SkinnedMeshRenderer candidate = renderers[i];
            if (candidate != null && string.Equals(candidate.name, preferredName, StringComparison.Ordinal))
            {
                renderer = candidate;
                return true;
            }
        }

        for (int i = 0; i < renderers.Length; i++)
        {
            SkinnedMeshRenderer candidate = renderers[i];
            if (candidate == null)
            {
                continue;
            }

            string sourceName = candidate.name;
            if (candidate.sharedMesh != null)
            {
                sourceName += "_" + candidate.sharedMesh.name;
            }

            if (TryResolveSavedPrefabSlot(sourceName, out MinimoCharacterCustomizer.PartSlot resolvedSlot)
                && resolvedSlot == slot)
            {
                renderer = candidate;
                return true;
            }
        }

        return false;
    }

    private static string GetSavedPrefabRendererNodeName(MinimoCharacterCustomizer.PartSlot slot)
    {
        switch (slot)
        {
            case MinimoCharacterCustomizer.PartSlot.ArmLeft:
                return "Part_Arm_L";
            case MinimoCharacterCustomizer.PartSlot.ArmRight:
                return "Part_Arm_R";
            case MinimoCharacterCustomizer.PartSlot.ShoulderLeft:
                return "Part_Shoulder_L";
            case MinimoCharacterCustomizer.PartSlot.ShoulderRight:
                return "Part_Shoulder_R";
            case MinimoCharacterCustomizer.PartSlot.HandLeft:
                return "Part_Hand_L";
            case MinimoCharacterCustomizer.PartSlot.HandRight:
                return "Part_Hand_R";
            case MinimoCharacterCustomizer.PartSlot.Hips:
                return "Part_Hips";
            case MinimoCharacterCustomizer.PartSlot.LegUpperLeft:
                return "Part_Leg_Upper_L";
            case MinimoCharacterCustomizer.PartSlot.LegUpperRight:
                return "Part_Leg_Upper_R";
            case MinimoCharacterCustomizer.PartSlot.BootsLeft:
                return "Part_Boots_L";
            case MinimoCharacterCustomizer.PartSlot.BootsRight:
                return "Part_Boots_R";
            case MinimoCharacterCustomizer.PartSlot.Torso:
                return "Part_Torso";
            case MinimoCharacterCustomizer.PartSlot.Hair:
                return "Part_Hair";
            case MinimoCharacterCustomizer.PartSlot.Face:
                return "Part_Face";
            default:
                return slot.ToString();
        }
    }

    private static bool TryResolveSavedPrefabSlot(string sourceName, out MinimoCharacterCustomizer.PartSlot slot)
    {
        slot = MinimoCharacterCustomizer.PartSlot.Face;
        if (string.IsNullOrWhiteSpace(sourceName))
        {
            return false;
        }

        string value = sourceName.ToUpperInvariant().Replace(' ', '_').Replace('-', '_');
        while (value.Contains("__", StringComparison.Ordinal))
        {
            value = value.Replace("__", "_", StringComparison.Ordinal);
        }

        if (value.Contains("SHOULDER_L", StringComparison.Ordinal)
            || value.Contains("SHOULDERLEFT", StringComparison.Ordinal))
        {
            slot = MinimoCharacterCustomizer.PartSlot.ShoulderLeft;
            return true;
        }

        if (value.Contains("SHOULDER_R", StringComparison.Ordinal)
            || value.Contains("SHOULDERRIGHT", StringComparison.Ordinal))
        {
            slot = MinimoCharacterCustomizer.PartSlot.ShoulderRight;
            return true;
        }

        if (value.Contains("HAND_L", StringComparison.Ordinal)
            || value.Contains("HANDLEFT", StringComparison.Ordinal))
        {
            slot = MinimoCharacterCustomizer.PartSlot.HandLeft;
            return true;
        }

        if (value.Contains("HAND_R", StringComparison.Ordinal)
            || value.Contains("HANDRIGHT", StringComparison.Ordinal))
        {
            slot = MinimoCharacterCustomizer.PartSlot.HandRight;
            return true;
        }

        if (value.Contains("ARM_L", StringComparison.Ordinal)
            || value.Contains("ARMLEFT", StringComparison.Ordinal))
        {
            slot = MinimoCharacterCustomizer.PartSlot.ArmLeft;
            return true;
        }

        if (value.Contains("ARM_R", StringComparison.Ordinal)
            || value.Contains("ARMRIGHT", StringComparison.Ordinal))
        {
            slot = MinimoCharacterCustomizer.PartSlot.ArmRight;
            return true;
        }

        if (value.Contains("LEG_UPPER_L", StringComparison.Ordinal)
            || value.Contains("LEGLEFT", StringComparison.Ordinal))
        {
            slot = MinimoCharacterCustomizer.PartSlot.LegUpperLeft;
            return true;
        }

        if (value.Contains("LEG_UPPER_R", StringComparison.Ordinal)
            || value.Contains("LEGRIGHT", StringComparison.Ordinal))
        {
            slot = MinimoCharacterCustomizer.PartSlot.LegUpperRight;
            return true;
        }

        if (value.Contains("BOOTS_L", StringComparison.Ordinal)
            || value.Contains("SHOELEFT", StringComparison.Ordinal)
            || value.Contains("BOOTSLEFT", StringComparison.Ordinal))
        {
            slot = MinimoCharacterCustomizer.PartSlot.BootsLeft;
            return true;
        }

        if (value.Contains("BOOTS_R", StringComparison.Ordinal)
            || value.Contains("SHOERIGHT", StringComparison.Ordinal)
            || value.Contains("BOOTSRIGHT", StringComparison.Ordinal))
        {
            slot = MinimoCharacterCustomizer.PartSlot.BootsRight;
            return true;
        }

        if (value.Contains("HIPS", StringComparison.Ordinal))
        {
            slot = MinimoCharacterCustomizer.PartSlot.Hips;
            return true;
        }

        if (value.Contains("TORSO", StringComparison.Ordinal)
            || value.Contains("SPINE", StringComparison.Ordinal)
            || value.Contains("CHEST", StringComparison.Ordinal))
        {
            slot = MinimoCharacterCustomizer.PartSlot.Torso;
            return true;
        }

        if (value.Contains("HAIR", StringComparison.Ordinal))
        {
            slot = MinimoCharacterCustomizer.PartSlot.Hair;
            return true;
        }

        if (value.Contains("HEAD", StringComparison.Ordinal)
            || value.Contains("FACE", StringComparison.Ordinal))
        {
            slot = MinimoCharacterCustomizer.PartSlot.Face;
            return true;
        }

        return false;
    }

    private static void AppendSavedPrefabSlotColorSignature(
        StringBuilder builder,
        MinimoCharacterCustomizer sourceCustomizer,
        MinimoCharacterCustomizer.PartSlot slot)
    {
        if (builder == null)
        {
            return;
        }

        if (sourceCustomizer == null
            || !sourceCustomizer.TryGetPartRenderer(slot, out SkinnedMeshRenderer renderer)
            || renderer == null
            || !renderer.enabled
            || renderer.sharedMesh == null)
        {
            builder.Append("none");
            return;
        }

        List<string> colorTokens = new List<string>();
        Material[] materials = renderer.sharedMaterials;
        int materialCount = materials != null ? materials.Length : 0;
        for (int materialIndex = 0; materialIndex < materialCount; materialIndex++)
        {
            Material material = materials[materialIndex];
            if (material == null
                || !MaterialSupportsColor(material)
                || !TryGetEffectivePartColorForSave(sourceCustomizer, slot, materialIndex, out Color effectiveColor))
            {
                continue;
            }

            AddColorSignatureTokenIfMissing(colorTokens, effectiveColor);
        }

        if (colorTokens.Count == 0 && sourceCustomizer.TryGetPartColor(slot, -1, out Color fallbackColor))
        {
            AddColorSignatureTokenIfMissing(colorTokens, fallbackColor);
        }

        if (colorTokens.Count == 0)
        {
            builder.Append("none");
            return;
        }

        colorTokens.Sort(StringComparer.Ordinal);
        for (int i = 0; i < colorTokens.Count; i++)
        {
            builder.Append(colorTokens[i]);
            builder.Append('|');
        }
    }

    private static void AddColorSignatureTokenIfMissing(List<string> colorTokens, Color color)
    {
        if (colorTokens == null)
        {
            return;
        }

        StringBuilder colorBuilder = new StringBuilder();
        AppendColorToSignature(colorBuilder, color);
        string token = colorBuilder.ToString();
        if (!StringListContains(colorTokens, token))
        {
            colorTokens.Add(token);
        }
    }

    private static void AppendSavedPrefabFaceChannelColorSignature(
        StringBuilder builder,
        MinimoCharacterCustomizer sourceCustomizer)
    {
        if (builder == null || sourceCustomizer == null)
        {
            return;
        }

        AppendSavedPrefabFaceChannelColorSignature(builder, sourceCustomizer, "Eyes", FaceEyesShaderProperty, SavedFaceEyesStorageMaterialIndex, LegacySavedFaceEyesStorageMaterialIndex);
        AppendSavedPrefabFaceChannelColorSignature(builder, sourceCustomizer, "Brows", FaceEyebrowsShaderProperty, SavedFaceEyebrowsStorageMaterialIndex, LegacySavedFaceEyebrowsStorageMaterialIndex);
        AppendSavedPrefabFaceChannelColorSignature(builder, sourceCustomizer, "Makeup", FaceMakeupShaderProperty, SavedFaceMakeupStorageMaterialIndex, LegacySavedFaceMakeupStorageMaterialIndex);
    }

    private static void AppendSavedPrefabFaceChannelColorSignature(
        StringBuilder builder,
        MinimoCharacterCustomizer sourceCustomizer,
        string label,
        int propertyId,
        int storageMaterialIndex,
        int legacyStorageMaterialIndex)
    {
        builder.Append(label);
        builder.Append('=');
        if (TryGetFaceChannelColorFromCustomizer(sourceCustomizer, propertyId, out Color materialColor))
        {
            AppendColorToSignature(builder, materialColor);
        }
        else
        {
            builder.Append("none");
        }

        builder.Append(":stored=");
        if (sourceCustomizer.TryGetPartColor(MinimoCharacterCustomizer.PartSlot.Face, storageMaterialIndex, out Color storedColor)
            || sourceCustomizer.TryGetPartColor(MinimoCharacterCustomizer.PartSlot.Face, legacyStorageMaterialIndex, out storedColor))
        {
            AppendColorToSignature(builder, storedColor);
        }
        else
        {
            builder.Append("none");
        }

        builder.Append(';');
    }

    private static bool SavedPrefabMatchesCategory(string assetPath, string selectedCategory)
    {
        if (IsSavedAllCategoryName(selectedCategory))
        {
            return true;
        }

        string prefabCategory = ResolveSavedPrefabCategoryDisplayName(assetPath);
        return string.Equals(
            NormalizeSavedPrefabCategoryName(prefabCategory),
            NormalizeSavedPrefabCategoryName(selectedCategory),
            StringComparison.OrdinalIgnoreCase);
    }

    private static bool CanDeleteSavedPrefab(string assetPath)
    {
        return IsSavedCustomizationCategory(ResolveSavedPrefabCategoryDisplayName(assetPath));
    }

    private static string ResolveSavedPrefabCategoryDisplayName(string assetPath)
    {
        return TryResolveSavedPrefabCategoryName(assetPath, out string categoryName)
            ? NormalizeSavedPrefabCategoryName(categoryName)
            : CategoryDefaultOptionLabel;
    }

    private static bool TryResolveSavedPrefabCategoryName(string assetPath, out string categoryName)
    {
        categoryName = string.Empty;
        string normalizedPath = NormalizeCategoryAssetPath(assetPath);
        if (string.IsNullOrWhiteSpace(normalizedPath))
        {
            return false;
        }

        string prefabFolder = GetParentCategoryAssetFolder(normalizedPath);
        if (string.IsNullOrWhiteSpace(prefabFolder))
        {
            return false;
        }

        string normalizedPrefabRoot = NormalizeCategoryAssetPath(SavePrefabFolder);
        if (string.Equals(prefabFolder, normalizedPrefabRoot, StringComparison.OrdinalIgnoreCase))
        {
            categoryName = CategoryDefaultOptionLabel;
            return true;
        }

        categoryName = GetCategoryAssetLeafName(prefabFolder);
        return !string.IsNullOrWhiteSpace(categoryName);
    }

    private static bool TryParseSavedCharacterIndex(string fileName, out int index)
    {
        index = -1;
        if (string.IsNullOrWhiteSpace(fileName))
        {
            return false;
        }

        const string currentPrefix = "Character-";
        const string legacyPrefix = "Character_";
        string suffix;
        if (fileName.StartsWith(currentPrefix, StringComparison.OrdinalIgnoreCase))
        {
            suffix = fileName.Substring(currentPrefix.Length);
        }
        else if (fileName.StartsWith(legacyPrefix, StringComparison.OrdinalIgnoreCase))
        {
            suffix = fileName.Substring(legacyPrefix.Length);
        }
        else
        {
            return false;
        }

        if (!int.TryParse(suffix, out int parsed) || parsed < 0)
        {
            return false;
        }

        index = parsed;
        return true;
    }

    private static string BuildNextSavedCharacterPrefabPath()
    {
        int maxIndex = -1;
        string customizationFolder = BuildSavedPrefabCategoryFolderPath(SaveCustomizationCategoryName);
        string[] prefabGuids = AssetDatabase.IsValidFolder(SavePrefabFolder)
            ? AssetDatabase.FindAssets("t:Prefab", new[] { SavePrefabFolder })
            : Array.Empty<string>();
        for (int i = 0; i < prefabGuids.Length; i++)
        {
            string path = AssetDatabase.GUIDToAssetPath(prefabGuids[i]);
            if (!CanDeleteSavedPrefab(path))
            {
                continue;
            }

            string fileName = Path.GetFileNameWithoutExtension(path);
            if (!TryParseSavedCharacterIndex(fileName, out int parsedIndex))
            {
                continue;
            }

            if (parsedIndex > maxIndex)
            {
                maxIndex = parsedIndex;
            }
        }

        int nextIndex = Mathf.Max(1, maxIndex + 1);
        string pathCandidate = $"{customizationFolder}/Character-{nextIndex:00}.prefab";
        while (AssetDatabase.LoadAssetAtPath<GameObject>(pathCandidate) != null)
        {
            nextIndex++;
            pathCandidate = $"{customizationFolder}/Character-{nextIndex:00}.prefab";
        }

        return pathCandidate;
    }

    private static string BuildSavedPrefabCategoryFolderPath(string categoryName)
    {
        string normalizedCategory = NormalizeSavedPrefabCategoryName(categoryName);
        if (string.IsNullOrWhiteSpace(normalizedCategory) || IsSavedAllCategoryName(normalizedCategory))
        {
            normalizedCategory = SaveCustomizationCategoryName;
        }

        return $"{SavePrefabFolder}/{SanitizeAssetFileName(normalizedCategory)}";
    }

    private void SaveCurrentCharacterAsPrefab()
    {
        SaveCurrentCharacterAsPrefab(string.Empty);
    }

    private void SaveCurrentCharacterAsPrefab(string overwriteAssetPath)
    {
        if (customizer == null)
        {
            helperOverrideMessage = "MinimoCharacterCustomizer was not found for saving.";
            RefreshFromCustomizer();
            return;
        }

        if (!AssetDatabase.IsValidFolder(SaveRootFolder))
        {
            EnsureEditorFolderExists(SaveRootFolder);
        }

        if (!AssetDatabase.IsValidFolder(SaveMaterialsFolder))
        {
            EnsureEditorFolderExists(SaveMaterialsFolder);
        }

        if (!AssetDatabase.IsValidFolder(SavePrefabFolder))
        {
            EnsureEditorFolderExists(SavePrefabFolder);
        }

        if (!AssetDatabase.IsValidFolder(SaveRootFolder)
            || !AssetDatabase.IsValidFolder(SaveMaterialsFolder)
            || !AssetDatabase.IsValidFolder(SavePrefabFolder))
        {
            helperOverrideMessage = "Save folders could not be created.";
            RefreshFromCustomizer();
            return;
        }

        bool overwriteExisting = !string.IsNullOrWhiteSpace(overwriteAssetPath)
                                 && CanDeleteSavedPrefab(overwriteAssetPath);
        string path = overwriteExisting
            ? overwriteAssetPath.Replace('\\', '/')
            : BuildNextSavedCharacterPrefabPath();
        if (string.IsNullOrWhiteSpace(path))
        {
            helperOverrideMessage = "Save file name could not be created.";
            RefreshFromCustomizer();
            return;
        }

        string targetFolder = Path.GetDirectoryName(path)?.Replace('\\', '/');
        if (!string.IsNullOrWhiteSpace(targetFolder) && !AssetDatabase.IsValidFolder(targetFolder))
        {
            EnsureEditorFolderExists(targetFolder);
        }

        string savedName = Path.GetFileNameWithoutExtension(path);
        string characterMaterialsFolderPath = BuildSavedCharacterMaterialsFolderPath(path);
        if (string.IsNullOrWhiteSpace(characterMaterialsFolderPath))
        {
            helperOverrideMessage = "Material folder could not be created.";
            RefreshFromCustomizer();
            return;
        }

        ResetWorldPartHoverVisuals();
        GameObject temp = Instantiate(customizer.gameObject);
        temp.name = StripUnityCloneSuffix(Path.GetFileNameWithoutExtension(path), "SavedCharacter");
        StripUnityCloneSuffixesRecursively(temp.transform);
        try
        {
            MinimoCharacterCustomizer tempCustomizer = null;
            if (temp.TryGetComponent(out tempCustomizer))
            {
                CopyCustomizerStateForPrefabSave(customizer, tempCustomizer);
            }

            ApplyTPoseParameterForPrefabSave(temp);
#if UNITY_EDITOR
            DetachSavedMaterialAssetReferencesForRuntime(customizer);
            DetachSavedMaterialAssetReferencesForRuntime(tempCustomizer);

            if (AssetDatabase.IsValidFolder(characterMaterialsFolderPath)
                && !AssetDatabase.DeleteAsset(characterMaterialsFolderPath))
            {
                helperOverrideMessage = "Old material folder could not be removed.";
                return;
            }

            EnsureEditorFolderExists(characterMaterialsFolderPath);
            if (!AssetDatabase.IsValidFolder(characterMaterialsFolderPath))
            {
                helperOverrideMessage = "Material folder could not be created.";
                return;
            }

            BakeCharacterMaterialsForPrefabSave(tempCustomizer, characterMaterialsFolderPath);
#endif
            PrefabUtility.SaveAsPrefabAsset(temp, path);
        }
        finally
        {
            if (Application.isPlaying)
            {
                Destroy(temp);
            }
            else
            {
                DestroyImmediate(temp);
            }
        }

        AssetDatabase.SaveAssets();
        AssetDatabase.Refresh();

        helperOverrideMessage = overwriteExisting
            ? $"Overwritten: {savedName}"
            : $"Saved: {savedName}";
        TrackLoadedSavedPrefabState(path);
        RefreshSavedPrefabCategoryDropdownOptions();
        SelectSavedPrefabCategoryFilter(SaveCustomizationCategoryName);
        RebuildSavedPrefabButtons(true);
        SelectSavedPrefabEntryByPath(path);
        RefreshFromCustomizer();
    }

    private void SelectSavedPrefabEntryByPath(string assetPath)
    {
        if (string.IsNullOrWhiteSpace(assetPath) || savedPrefabButtons.Count == 0)
        {
            return;
        }

        for (int i = 0; i < savedPrefabButtons.Count; i++)
        {
            SavedPrefabButtonEntry entry = savedPrefabButtons[i];
            if (entry != null && string.Equals(entry.assetPath, assetPath, StringComparison.OrdinalIgnoreCase))
            {
                selectedSavedPrefabIndex = i;
                UpdateSavedPrefabButtonVisuals();
                return;
            }
        }
    }

    private bool TrySelectSavedPrefabEntryByCategory(string categoryName)
    {
        if (savedPrefabButtons.Count == 0)
        {
            return false;
        }

        string normalizedCategoryName = NormalizeSavedPrefabCategoryName(categoryName);
        if (string.IsNullOrWhiteSpace(normalizedCategoryName))
        {
            return false;
        }

        for (int i = 0; i < savedPrefabButtons.Count; i++)
        {
            SavedPrefabButtonEntry entry = savedPrefabButtons[i];
            if (entry == null)
            {
                continue;
            }

            if (!string.Equals(
                    NormalizeSavedPrefabCategoryName(entry.categoryName),
                    normalizedCategoryName,
                    StringComparison.OrdinalIgnoreCase))
            {
                continue;
            }

            selectedSavedPrefabIndex = i;
            ScrollSavedPrefabIntoView(i);
            return true;
        }

        return false;
    }

    private void TrackLoadedSavedPrefabState(string assetPath)
    {
        loadedSavedPrefabPath = string.IsNullOrWhiteSpace(assetPath)
            ? string.Empty
            : assetPath.Replace('\\', '/');
        loadedSavedPrefabStateSignature = BuildCurrentCustomizerStateSignature();
    }

    private string BuildCurrentCustomizerStateSignature()
    {
        if (customizer == null)
        {
            return string.Empty;
        }

        if (IsFaceTextureSelectionMode())
        {
            SyncSelectedFaceTextureSetKeyFromCurrentMaterial();
        }
        else
        {
            selectedFaceTextureSetKey = string.Empty;
        }

        return BuildCustomizerStateSignature(customizer, selectedFaceTextureSetKey);
    }

    private static string BuildCustomizerStateSignature(MinimoCharacterCustomizer sourceCustomizer, string faceTextureSetKey)
    {
        if (sourceCustomizer == null)
        {
            return string.Empty;
        }

        StringBuilder signature = new StringBuilder(1024);
        IReadOnlyList<MinimoCharacterCustomizer.PartSlot> slots = MinimoCharacterCustomizer.Slots;
        for (int i = 0; i < slots.Count; i++)
        {
            MinimoCharacterCustomizer.PartSlot slot = slots[i];
            signature.Append("S").Append((int)slot).Append(":").Append(sourceCustomizer.GetPartVariant(slot)).Append(";");
            if (sourceCustomizer.TryGetPartColor(slot, -1, out Color fallback))
            {
                signature.Append("F");
                AppendColorToSignature(signature, fallback);
                signature.Append(";");
            }

            if (!sourceCustomizer.TryGetPartRenderer(slot, out SkinnedMeshRenderer renderer) || renderer == null)
            {
                continue;
            }

            Material[] materials = renderer.sharedMaterials;
            int materialCount = materials != null ? materials.Length : 0;
            for (int materialIndex = 0; materialIndex < materialCount; materialIndex++)
            {
                if (!sourceCustomizer.TryGetPartColor(slot, materialIndex, out Color materialColor))
                {
                    continue;
                }

                signature.Append("M").Append(materialIndex).Append(":");
                AppendColorToSignature(signature, materialColor);
                signature.Append(";");
            }
        }

        signature.Append("FaceSet=").Append(faceTextureSetKey ?? string.Empty).Append(";");
        if (TryGetFaceChannelColorFromCustomizer(sourceCustomizer, FaceEyesShaderProperty, out Color eyesColor))
        {
            signature.Append("Eyes=");
            AppendColorToSignature(signature, eyesColor);
            signature.Append(";");
        }

        if (TryGetFaceChannelColorFromCustomizer(sourceCustomizer, FaceEyebrowsShaderProperty, out Color eyebrowsColor))
        {
            signature.Append("Brows=");
            AppendColorToSignature(signature, eyebrowsColor);
            signature.Append(";");
        }

        if (TryGetFaceChannelColorFromCustomizer(sourceCustomizer, FaceMakeupShaderProperty, out Color makeupColor))
        {
            signature.Append("Makeup=");
            AppendColorToSignature(signature, makeupColor);
            signature.Append(";");
        }

        AppendPropStateToSignature(signature, sourceCustomizer);

        return signature.ToString();
    }

    private static void AppendColorToSignature(StringBuilder signature, Color color)
    {
        if (signature == null)
        {
            return;
        }

        Color32 color32 = color;
        signature
            .Append(color32.r.ToString("X2"))
            .Append(color32.g.ToString("X2"))
            .Append(color32.b.ToString("X2"))
            .Append(color32.a.ToString("X2"));
    }

    private static void AppendPropStateToSignature(
        StringBuilder signature,
        MinimoCharacterCustomizer sourceCustomizer)
    {
        if (signature == null || sourceCustomizer == null)
        {
            return;
        }

        Transform root = sourceCustomizer.transform;
        if (root == null)
        {
            return;
        }

        List<Transform> equippedProps = new List<Transform>();
        Transform[] transforms = root.GetComponentsInChildren<Transform>(true);
        for (int i = 0; i < transforms.Length; i++)
        {
            Transform current = transforms[i];
            if (current == null)
            {
                continue;
            }

            for (int childIndex = 0; childIndex < current.childCount; childIndex++)
            {
                Transform child = current.GetChild(childIndex);
                if (child != null && IsPropInstanceName(child.name))
                {
                    equippedProps.Add(child);
                }
            }
        }

        equippedProps.Sort((left, right) =>
        {
            string leftRig = left != null && left.parent != null ? left.parent.name : string.Empty;
            string rightRig = right != null && right.parent != null ? right.parent.name : string.Empty;
            int rigCompare = CompareAlphabeticNatural(leftRig, rightRig);
            if (rigCompare != 0)
            {
                return rigCompare;
            }

            string leftName = left != null ? left.name : string.Empty;
            string rightName = right != null ? right.name : string.Empty;
            return CompareAlphabeticNatural(leftName, rightName);
        });

        for (int i = 0; i < equippedProps.Count; i++)
        {
            Transform propRoot = equippedProps[i];
            if (propRoot == null)
            {
                continue;
            }

            Transform rig = propRoot.parent;
            string rigName = rig != null ? rig.name : string.Empty;
            signature
                .Append("P=")
                .Append(NormalizeBodyRegionKey(rigName))
                .Append("/")
                .Append(propRoot.name)
                .Append("@");
            AppendVector3ToSignature(signature, propRoot.localPosition);
            signature.Append("|");
            AppendVector3ToSignature(signature, propRoot.localEulerAngles);
            signature.Append("|");
            AppendVector3ToSignature(signature, propRoot.localScale);
            signature.Append("|A").Append(propRoot.gameObject.activeSelf ? "1" : "0");
            AppendPropChildTransformStateToSignature(signature, propRoot);

            Renderer[] renderers = propRoot.GetComponentsInChildren<Renderer>(true);
            for (int rendererIndex = 0; rendererIndex < renderers.Length; rendererIndex++)
            {
                Renderer renderer = renderers[rendererIndex];
                if (renderer == null)
                {
                    continue;
                }

                string rendererPath = BuildRelativeTransformPath(propRoot, renderer.transform);
                signature
                    .Append("|R")
                    .Append(rendererPath)
                    .Append("#")
                    .Append(GetRendererComponentIndex(renderer))
                    .Append(renderer.enabled ? "1" : "0");
                Material[] materials = renderer.materials;
                if (materials == null || materials.Length == 0)
                {
                    materials = renderer.sharedMaterials;
                }

                if (materials == null || materials.Length == 0)
                {
                    continue;
                }

                for (int materialIndex = 0; materialIndex < materials.Length; materialIndex++)
                {
                    Material material = materials[materialIndex];
                    if (material == null)
                    {
                        continue;
                    }

                    if (TryGetMaterialDisplayColor(material, out Color color))
                    {
                        signature.Append("|M").Append(materialIndex).Append(":");
                        AppendColorToSignature(signature, color);
                    }
                }
            }

            signature.Append(";");
        }
    }

    private static void AppendPropChildTransformStateToSignature(StringBuilder signature, Transform propRoot)
    {
        if (signature == null || propRoot == null)
        {
            return;
        }

        for (int childIndex = 0; childIndex < propRoot.childCount; childIndex++)
        {
            AppendChildTransformStateToSignatureRecursive(signature, propRoot, propRoot.GetChild(childIndex));
        }
    }

    private static void AppendChildTransformStateToSignatureRecursive(
        StringBuilder signature,
        Transform propRoot,
        Transform current)
    {
        if (signature == null || propRoot == null || current == null)
        {
            return;
        }

        signature
            .Append("|T")
            .Append(BuildRelativeTransformPath(propRoot, current))
            .Append("@");
        AppendVector3ToSignature(signature, current.localPosition);
        signature.Append("|");
        AppendVector3ToSignature(signature, current.localEulerAngles);
        signature.Append("|");
        AppendVector3ToSignature(signature, current.localScale);
        signature.Append("|A").Append(current.gameObject.activeSelf ? "1" : "0");

        for (int childIndex = 0; childIndex < current.childCount; childIndex++)
        {
            AppendChildTransformStateToSignatureRecursive(signature, propRoot, current.GetChild(childIndex));
        }
    }

    private static string BuildRelativeTransformPath(Transform root, Transform target)
    {
        if (root == null || target == null)
        {
            return string.Empty;
        }

        if (ReferenceEquals(root, target))
        {
            return ".";
        }

        List<string> segments = new List<string>();
        Transform cursor = target;
        while (cursor != null && !ReferenceEquals(cursor, root))
        {
            segments.Add($"{cursor.name}#{cursor.GetSiblingIndex()}");
            cursor = cursor.parent;
        }

        if (cursor == null)
        {
            return target.name;
        }

        segments.Reverse();
        return string.Join("/", segments);
    }

    private static int GetRendererComponentIndex(Renderer renderer)
    {
        if (renderer == null || renderer.transform == null)
        {
            return 0;
        }

        Component[] components = renderer.transform.GetComponents<Component>();
        int index = 0;
        for (int i = 0; i < components.Length; i++)
        {
            Component component = components[i];
            if (component == null || component.GetType() != renderer.GetType())
            {
                continue;
            }

            if (ReferenceEquals(component, renderer))
            {
                return index;
            }

            index++;
        }

        return index;
    }

    private static void AppendVector3ToSignature(StringBuilder signature, Vector3 value)
    {
        signature
            .Append(Mathf.RoundToInt(value.x * 1000f))
            .Append(",")
            .Append(Mathf.RoundToInt(value.y * 1000f))
            .Append(",")
            .Append(Mathf.RoundToInt(value.z * 1000f));
    }

    private void CopyCustomizerStateForPrefabSave(
        MinimoCharacterCustomizer sourceCustomizer,
        MinimoCharacterCustomizer targetCustomizer)
    {
        if (sourceCustomizer == null || targetCustomizer == null)
        {
            return;
        }

        IReadOnlyList<MinimoCharacterCustomizer.PartSlot> slots = MinimoCharacterCustomizer.Slots;
        for (int i = 0; i < slots.Count; i++)
        {
            MinimoCharacterCustomizer.PartSlot slot = slots[i];
            targetCustomizer.SetPartVariant(slot, sourceCustomizer.GetPartVariant(slot));
        }

        targetCustomizer.ApplyCurrentSelection();
        for (int i = 0; i < slots.Count; i++)
        {
            MinimoCharacterCustomizer.PartSlot slot = slots[i];
            if (!sourceCustomizer.TryGetPartRenderer(slot, out SkinnedMeshRenderer sourceRenderer) || sourceRenderer == null)
            {
                continue;
            }

            Material[] sourceMaterials = sourceRenderer.sharedMaterials;
            int sourceMaterialCount = sourceMaterials != null ? sourceMaterials.Length : 0;
            for (int materialIndex = 0; materialIndex < sourceMaterialCount; materialIndex++)
            {
                Material sourceMaterial = sourceMaterials[materialIndex];
                if (!MaterialSupportsColor(sourceMaterial))
                {
                    continue;
                }

                if (TryGetEffectivePartColorForSave(sourceCustomizer, slot, materialIndex, out Color effectiveColor))
                {
                    targetCustomizer.SetPartColor(slot, materialIndex, effectiveColor);
                }
            }
        }

        CopyPropInstancesBetweenCustomizers(sourceCustomizer, targetCustomizer);
        CopyFaceMaterialCustomizationForPrefabSave(sourceCustomizer, targetCustomizer);
        CopySavedFaceChannelColorsToPartColorStorage(sourceCustomizer, targetCustomizer);
    }

#if UNITY_EDITOR
    private static void BakeCharacterMaterialsForPrefabSave(
        MinimoCharacterCustomizer targetCustomizer,
        string materialsFolder)
    {
        if (targetCustomizer == null || string.IsNullOrWhiteSpace(materialsFolder))
        {
            return;
        }

        EnsureEditorFolderExists(materialsFolder);
        if (!AssetDatabase.IsValidFolder(materialsFolder))
        {
            return;
        }

        Dictionary<Renderer, string> slotNameByRenderer = BuildPartSlotNameLookup(targetCustomizer);
        Dictionary<string, Material> savedMaterialsBySignature = new Dictionary<string, Material>(StringComparer.Ordinal);
        int nextColorMaterialIndex = 0;
        MaterialPropertyBlock propertyBlock = new MaterialPropertyBlock();
        HashSet<Renderer> bakedRenderers = new HashSet<Renderer>();
        foreach (KeyValuePair<Renderer, string> pair in slotNameByRenderer)
        {
            Renderer renderer = pair.Key;
            if (renderer == null)
            {
                continue;
            }

            BakeRendererMaterialsForPrefabSave(
                renderer,
                materialsFolder,
                savedMaterialsBySignature,
                ref nextColorMaterialIndex,
                propertyBlock);
            bakedRenderers.Add(renderer);
        }

        List<Renderer> propRenderers = BuildPropRendererBakeTargets(targetCustomizer);
        for (int i = 0; i < propRenderers.Count; i++)
        {
            Renderer renderer = propRenderers[i];
            if (renderer == null || bakedRenderers.Contains(renderer))
            {
                continue;
            }

            BakeRendererMaterialsForPrefabSave(
                renderer,
                materialsFolder,
                savedMaterialsBySignature,
                ref nextColorMaterialIndex,
                propertyBlock);
            bakedRenderers.Add(renderer);
        }
    }

    private static void BakeRendererMaterialsForPrefabSave(
        Renderer renderer,
        string materialsFolder,
        IDictionary<string, Material> savedMaterialsBySignature,
        ref int nextColorMaterialIndex,
        MaterialPropertyBlock propertyBlock)
    {
        if (renderer == null)
        {
            return;
        }

        Material[] runtimeMaterials;
        try
        {
            runtimeMaterials = renderer.materials;
        }
        catch
        {
            runtimeMaterials = renderer.sharedMaterials;
        }

        Material[] sharedMaterials = renderer.sharedMaterials;
        int runtimeMaterialCount = runtimeMaterials != null ? runtimeMaterials.Length : 0;
        int sharedMaterialCount = sharedMaterials != null ? sharedMaterials.Length : 0;
        int materialCount = Mathf.Max(runtimeMaterialCount, sharedMaterialCount);
        if (materialCount <= 0)
        {
            return;
        }

        Material[] persistentMaterials = new Material[materialCount];
        for (int materialIndex = 0; materialIndex < materialCount; materialIndex++)
        {
            Material sourceMaterial = materialIndex < runtimeMaterialCount
                ? runtimeMaterials[materialIndex]
                : null;
            if (sourceMaterial == null && materialIndex < sharedMaterialCount)
            {
                sourceMaterial = sharedMaterials[materialIndex];
            }

            if (sourceMaterial == null)
            {
                persistentMaterials[materialIndex] = null;
                continue;
            }

            Material persistentMaterial = new Material(sourceMaterial)
            {
                name = $"color_{nextColorMaterialIndex}"
            };
            ApplyRendererPropertyBlockColorsForPrefabSave(
                renderer,
                materialIndex,
                persistentMaterial,
                propertyBlock);
            string colorSignature = BuildSavedColorMaterialSignature(persistentMaterial);
            if (!string.IsNullOrWhiteSpace(colorSignature)
                && savedMaterialsBySignature != null
                && savedMaterialsBySignature.TryGetValue(colorSignature, out Material existingMaterial)
                && existingMaterial != null)
            {
                DestroyImmediate(persistentMaterial);
                persistentMaterials[materialIndex] = existingMaterial;
                continue;
            }

            string materialAssetPath = AllocateNextSavedColorMaterialAssetPath(
                materialsFolder,
                ref nextColorMaterialIndex);
            if (string.IsNullOrWhiteSpace(materialAssetPath))
            {
                DestroyImmediate(persistentMaterial);
                persistentMaterials[materialIndex] = null;
                continue;
            }

            persistentMaterial.name = Path.GetFileNameWithoutExtension(materialAssetPath);
            AssetDatabase.CreateAsset(persistentMaterial, materialAssetPath);
            if (!string.IsNullOrWhiteSpace(colorSignature) && savedMaterialsBySignature != null)
            {
                savedMaterialsBySignature[colorSignature] = persistentMaterial;
            }

            persistentMaterials[materialIndex] = persistentMaterial;
        }

        renderer.sharedMaterials = persistentMaterials;
    }

    private static List<Renderer> BuildPropRendererBakeTargets(MinimoCharacterCustomizer targetCustomizer)
    {
        List<Renderer> renderers = new List<Renderer>();
        if (targetCustomizer == null)
        {
            return renderers;
        }

        Transform root = targetCustomizer.transform;
        if (root == null)
        {
            return renderers;
        }

        Transform[] transforms = root.GetComponentsInChildren<Transform>(true);
        for (int i = 0; i < transforms.Length; i++)
        {
            Transform current = transforms[i];
            if (current == null)
            {
                continue;
            }

            for (int childIndex = 0; childIndex < current.childCount; childIndex++)
            {
                Transform propRoot = current.GetChild(childIndex);
                if (propRoot == null || !IsPropInstanceName(propRoot.name))
                {
                    continue;
                }

                Transform visualRoot = ResolvePropVisualStateRoot(propRoot);
                if (visualRoot == null)
                {
                    continue;
                }

                Renderer[] propRenderers = visualRoot.GetComponentsInChildren<Renderer>(true);
                for (int rendererIndex = 0; rendererIndex < propRenderers.Length; rendererIndex++)
                {
                    Renderer renderer = propRenderers[rendererIndex];
                    if (renderer == null
                        || (!(renderer is MeshRenderer) && !(renderer is SkinnedMeshRenderer))
                        || renderers.Contains(renderer))
                    {
                        continue;
                    }

                    renderers.Add(renderer);
                }
            }
        }

        return renderers;
    }

    private static void ApplyRendererPropertyBlockColorsForPrefabSave(
        Renderer renderer,
        int materialIndex,
        Material persistentMaterial,
        MaterialPropertyBlock propertyBlock)
    {
        if (renderer == null || persistentMaterial == null || propertyBlock == null || materialIndex < 0)
        {
            return;
        }

        propertyBlock.Clear();
        renderer.GetPropertyBlock(propertyBlock, materialIndex);
        if (propertyBlock.isEmpty)
        {
            return;
        }

        for (int i = 0; i < PrefabSavePropertyBlockColorPropertyIds.Length; i++)
        {
            int propertyId = PrefabSavePropertyBlockColorPropertyIds[i];
            if (persistentMaterial.HasProperty(propertyId) && propertyBlock.HasColor(propertyId))
            {
                persistentMaterial.SetColor(propertyId, propertyBlock.GetColor(propertyId));
            }
        }
    }

    private static void ApplySavedMaterialAssetsFromFolder(
        MinimoCharacterCustomizer targetCustomizer,
        string savedPrefabAssetPath)
    {
        if (targetCustomizer == null || string.IsNullOrWhiteSpace(savedPrefabAssetPath))
        {
            return;
        }

        string materialsFolder = BuildSavedCharacterMaterialsFolderPath(savedPrefabAssetPath);
        if (string.IsNullOrWhiteSpace(materialsFolder) || !AssetDatabase.IsValidFolder(materialsFolder))
        {
            return;
        }

        Dictionary<Renderer, string> slotNameByRenderer = BuildPartSlotNameLookup(targetCustomizer);
        foreach (KeyValuePair<Renderer, string> pair in slotNameByRenderer)
        {
            Renderer renderer = pair.Key;
            if (renderer == null)
            {
                continue;
            }

            Material[] currentMaterials = renderer.sharedMaterials;
            int materialCount = currentMaterials != null ? currentMaterials.Length : 0;
            if (materialCount <= 0)
            {
                continue;
            }

            string partName = string.IsNullOrWhiteSpace(pair.Value)
                ? ResolveRendererPartNameForSave(renderer, slotNameByRenderer)
                : pair.Value;
            string safePartName = SanitizeAssetFileName(partName);
            bool changed = false;
            Material[] resolvedMaterials = new Material[materialCount];
            for (int materialIndex = 0; materialIndex < materialCount; materialIndex++)
            {
                Material savedMaterial = AssetDatabase.LoadAssetAtPath<Material>(
                    $"{materialsFolder}/{safePartName}-{materialIndex}.mat");
                if (savedMaterial != null)
                {
                    resolvedMaterials[materialIndex] = CloneSavedMaterialForRuntime(savedMaterial);
                    changed = true;
                }
                else
                {
                    resolvedMaterials[materialIndex] = currentMaterials[materialIndex];
                }
            }

            if (changed)
            {
                renderer.sharedMaterials = resolvedMaterials;
            }
        }
    }

    private static Dictionary<Renderer, string> BuildPartSlotNameLookup(MinimoCharacterCustomizer targetCustomizer)
    {
        Dictionary<Renderer, string> lookup = new Dictionary<Renderer, string>();
        if (targetCustomizer == null)
        {
            return lookup;
        }

        IReadOnlyList<MinimoCharacterCustomizer.PartSlot> slots = MinimoCharacterCustomizer.Slots;
        for (int i = 0; i < slots.Count; i++)
        {
            MinimoCharacterCustomizer.PartSlot slot = slots[i];
            if (!targetCustomizer.TryGetPartRenderer(slot, out SkinnedMeshRenderer renderer) || renderer == null)
            {
                continue;
            }

            if (!lookup.ContainsKey(renderer))
            {
                lookup.Add(renderer, slot.ToString());
            }
        }

        return lookup;
    }

    private static Material CloneSavedMaterialForRuntime(Material material)
    {
        if (material == null)
        {
            return null;
        }

        Material clone = new Material(material)
        {
            name = material.name
        };
        clone.hideFlags = HideFlags.DontSaveInEditor | HideFlags.DontSaveInBuild;
        return clone;
    }

    private static Material[] CopyPartMaterialsForRuntime(Material[] materials)
    {
        if (materials == null || materials.Length == 0)
        {
            return Array.Empty<Material>();
        }

        Material[] copy = new Material[materials.Length];
        for (int i = 0; i < materials.Length; i++)
        {
            Material material = materials[i];
            if (material == null)
            {
                copy[i] = null;
                continue;
            }

            string assetPath = AssetDatabase.GetAssetPath(material);
            copy[i] = IsSavedMaterialAssetPath(assetPath)
                ? CloneSavedMaterialForRuntime(material)
                : material;
        }

        return copy;
    }

    private static void DetachSavedMaterialAssetReferencesForRuntime(MinimoCharacterCustomizer targetCustomizer)
    {
        if (targetCustomizer == null)
        {
            return;
        }

        Renderer[] renderers = targetCustomizer.GetComponentsInChildren<Renderer>(true);
        for (int rendererIndex = 0; rendererIndex < renderers.Length; rendererIndex++)
        {
            Renderer renderer = renderers[rendererIndex];
            if (renderer == null)
            {
                continue;
            }

            Material[] materials = renderer.sharedMaterials;
            if (materials == null || materials.Length == 0)
            {
                continue;
            }

            bool changed = false;
            Material[] detachedMaterials = new Material[materials.Length];
            for (int i = 0; i < materials.Length; i++)
            {
                Material material = materials[i];
                if (material == null)
                {
                    detachedMaterials[i] = null;
                    continue;
                }

                string assetPath = AssetDatabase.GetAssetPath(material);
                if (IsSavedMaterialAssetPath(assetPath))
                {
                    detachedMaterials[i] = CloneSavedMaterialForRuntime(material);
                    changed = true;
                }
                else
                {
                    detachedMaterials[i] = material;
                }
            }

            if (changed)
            {
                renderer.sharedMaterials = detachedMaterials;
            }
        }
    }

    private static string BuildSavedColorMaterialSignature(Material material)
    {
        if (material == null)
        {
            return string.Empty;
        }

        StringBuilder builder = new StringBuilder();
        builder.Append("shader=");
        builder.Append(material.shader != null ? material.shader.name : "none");
        builder.Append(";colors=");

        bool hasColor = false;
        for (int i = 0; i < PrefabSavePropertyBlockColorPropertyIds.Length; i++)
        {
            int propertyId = PrefabSavePropertyBlockColorPropertyIds[i];
            if (!material.HasProperty(propertyId))
            {
                continue;
            }

            hasColor = true;
            builder.Append(propertyId);
            builder.Append(':');
            AppendColorToSignature(builder, material.GetColor(propertyId));
            builder.Append('|');
        }

        if (!hasColor)
        {
            builder.Append("none");
        }

        List<string> textureTokens = new List<string>();
        AppendMaterialTextureTokens(material, textureTokens);
        textureTokens.Sort(StringComparer.Ordinal);
        builder.Append(";textures=");
        if (textureTokens.Count == 0)
        {
            builder.Append("none");
        }
        else
        {
            for (int i = 0; i < textureTokens.Count; i++)
            {
                builder.Append(textureTokens[i]);
                builder.Append('|');
            }
        }

        return builder.ToString();
    }

    private static bool IsSavedMaterialAssetPath(string assetPath)
    {
        if (string.IsNullOrWhiteSpace(assetPath))
        {
            return false;
        }

        string normalizedAssetPath = assetPath.Replace('\\', '/');
        string normalizedSaveMaterialsFolder = SaveMaterialsFolder.Replace('\\', '/').TrimEnd('/');
        return normalizedAssetPath.StartsWith(normalizedSaveMaterialsFolder + "/", StringComparison.OrdinalIgnoreCase);
    }

    private static string ResolveRendererPartNameForSave(
        Renderer renderer,
        IReadOnlyDictionary<Renderer, string> slotNameByRenderer)
    {
        if (renderer == null)
        {
            return "Part";
        }

        if (slotNameByRenderer != null
            && slotNameByRenderer.TryGetValue(renderer, out string slotName)
            && !string.IsNullOrWhiteSpace(slotName))
        {
            return slotName;
        }

        Transform rendererTransform = renderer.transform;
        if (rendererTransform != null)
        {
            Transform parent = rendererTransform;
            while (parent != null)
            {
                if (IsPropInstanceName(parent.name) && !string.IsNullOrWhiteSpace(parent.name))
                {
                    return parent.name;
                }

                parent = parent.parent;
            }

            if (!string.IsNullOrWhiteSpace(rendererTransform.name))
            {
                return rendererTransform.name;
            }
        }

        return string.IsNullOrWhiteSpace(renderer.name) ? "Part" : renderer.name;
    }

    private static Dictionary<string, int> BuildSavedMaterialNameCounters(string materialsFolder)
    {
        Dictionary<string, int> counters = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);
        if (string.IsNullOrWhiteSpace(materialsFolder) || !AssetDatabase.IsValidFolder(materialsFolder))
        {
            return counters;
        }

        string[] materialGuids = AssetDatabase.FindAssets("t:Material", new[] { materialsFolder });
        for (int i = 0; i < materialGuids.Length; i++)
        {
            string materialPath = AssetDatabase.GUIDToAssetPath(materialGuids[i]);
            string fileName = Path.GetFileNameWithoutExtension(materialPath);
            if (!TryParseSavedPartMaterialName(fileName, out string partName, out int index))
            {
                continue;
            }

            int nextIndex = index + 1;
            if (!counters.TryGetValue(partName, out int existingNextIndex) || nextIndex > existingNextIndex)
            {
                counters[partName] = nextIndex;
            }
        }

        return counters;
    }

    private static bool TryParseSavedPartMaterialName(string fileName, out string partName, out int index)
    {
        partName = string.Empty;
        index = -1;
        if (string.IsNullOrWhiteSpace(fileName))
        {
            return false;
        }

        int dashIndex = fileName.LastIndexOf('-');
        if (dashIndex <= 0 || dashIndex >= fileName.Length - 1)
        {
            return false;
        }

        string suffix = fileName.Substring(dashIndex + 1);
        if (!int.TryParse(suffix, out int parsedIndex) || parsedIndex < 0)
        {
            return false;
        }

        string parsedPartName = fileName.Substring(0, dashIndex);
        if (string.IsNullOrWhiteSpace(parsedPartName))
        {
            return false;
        }

        partName = parsedPartName;
        index = parsedIndex;
        return true;
    }

    private static string AllocateNextSavedMaterialAssetPath(
        string materialsFolder,
        string safePartName,
        IDictionary<string, int> nextIndicesByPartName)
    {
        if (string.IsNullOrWhiteSpace(materialsFolder))
        {
            return string.Empty;
        }

        string sanitizedPartName = string.IsNullOrWhiteSpace(safePartName)
            ? "Part"
            : SanitizeAssetFileName(safePartName);
        int nextIndex = 0;
        if (nextIndicesByPartName != null
            && nextIndicesByPartName.TryGetValue(sanitizedPartName, out int knownNextIndex)
            && knownNextIndex > 0)
        {
            nextIndex = knownNextIndex;
        }

        string assetPath = $"{materialsFolder}/{sanitizedPartName}-{nextIndex}.mat";
        while (AssetDatabase.LoadAssetAtPath<Material>(assetPath) != null)
        {
            nextIndex++;
            assetPath = $"{materialsFolder}/{sanitizedPartName}-{nextIndex}.mat";
        }

        if (nextIndicesByPartName != null)
        {
            nextIndicesByPartName[sanitizedPartName] = nextIndex + 1;
        }

        return assetPath;
    }

    private static string AllocateNextSavedColorMaterialAssetPath(
        string materialsFolder,
        ref int nextColorMaterialIndex)
    {
        if (string.IsNullOrWhiteSpace(materialsFolder))
        {
            return string.Empty;
        }

        int nextIndex = Mathf.Max(0, nextColorMaterialIndex);
        string assetPath = $"{materialsFolder}/color_{nextIndex}.mat";
        while (AssetDatabase.LoadAssetAtPath<Material>(assetPath) != null)
        {
            nextIndex++;
            assetPath = $"{materialsFolder}/color_{nextIndex}.mat";
        }

        nextColorMaterialIndex = nextIndex + 1;
        return assetPath;
    }

    private static string BuildSavedCharacterMaterialsFolderPath(string characterAssetPathOrName)
    {
        string value = characterAssetPathOrName;
        if (string.IsNullOrWhiteSpace(value))
        {
            return string.Empty;
        }

        string categoryName = SaveCustomizationCategoryName;
        if (value.IndexOf('/') >= 0 || value.IndexOf('\\') >= 0 || value.EndsWith(".prefab", StringComparison.OrdinalIgnoreCase))
        {
            if (TryResolveSavedPrefabCategoryName(value, out string resolvedCategory)
                && !string.IsNullOrWhiteSpace(resolvedCategory))
            {
                categoryName = resolvedCategory;
            }

            value = Path.GetFileNameWithoutExtension(value);
        }

        string safeName = SanitizeAssetFileName(value);
        if (string.IsNullOrWhiteSpace(safeName))
        {
            return string.Empty;
        }

        string safeCategoryName = SanitizeAssetFileName(categoryName);
        if (string.IsNullOrWhiteSpace(safeCategoryName))
        {
            safeCategoryName = SaveCustomizationCategoryName;
        }

        return $"{SaveMaterialsFolder}/{safeCategoryName}/{safeName}";
    }

    private static string SanitizeAssetFileName(string value)
    {
        if (string.IsNullOrWhiteSpace(value))
        {
            return "Item";
        }

        char[] invalidChars = Path.GetInvalidFileNameChars();
        StringBuilder builder = new StringBuilder(value.Length);
        for (int i = 0; i < value.Length; i++)
        {
            char c = value[i];
            bool invalid = false;
            for (int j = 0; j < invalidChars.Length; j++)
            {
                if (c == invalidChars[j])
                {
                    invalid = true;
                    break;
                }
            }

            if (invalid || c == '/' || c == '\\')
            {
                builder.Append('_');
            }
            else
            {
                builder.Append(c);
            }
        }

        string sanitized = builder.ToString().Trim();
        if (string.IsNullOrWhiteSpace(sanitized))
        {
            return "Item";
        }

        return sanitized.Replace(' ', '_');
    }
#endif

    private static bool TryGetEffectivePartColorForSave(
        MinimoCharacterCustomizer sourceCustomizer,
        MinimoCharacterCustomizer.PartSlot slot,
        int materialIndex,
        out Color color)
    {
        color = Color.white;
        if (sourceCustomizer == null)
        {
            return false;
        }

        if (materialIndex >= 0 && sourceCustomizer.TryGetPartColor(slot, materialIndex, out color))
        {
            return true;
        }

        if (sourceCustomizer.TryGetPartColor(slot, -1, out color))
        {
            return true;
        }

        if (!sourceCustomizer.TryGetPartRenderer(slot, out SkinnedMeshRenderer renderer) || renderer == null)
        {
            return false;
        }

        Material[] materials = renderer.sharedMaterials;
        if (materials == null || materialIndex < 0 || materialIndex >= materials.Length)
        {
            return false;
        }

        Material material = materials[materialIndex];
        if (material == null)
        {
            return false;
        }

        if (material.HasProperty(ColorShaderProperty))
        {
            color = material.GetColor(ColorShaderProperty);
            return true;
        }

        if (material.HasProperty(BaseColorShaderProperty))
        {
            color = material.GetColor(BaseColorShaderProperty);
            return true;
        }

        return false;
    }

    private static void CopyFaceMaterialCustomizationForPrefabSave(
        MinimoCharacterCustomizer sourceCustomizer,
        MinimoCharacterCustomizer targetCustomizer)
    {
        if (sourceCustomizer == null
            || targetCustomizer == null
            || !sourceCustomizer.TryGetPartRenderer(MinimoCharacterCustomizer.PartSlot.Face, out SkinnedMeshRenderer sourceFaceRenderer)
            || sourceFaceRenderer == null
            || !targetCustomizer.TryGetPartRenderer(MinimoCharacterCustomizer.PartSlot.Face, out SkinnedMeshRenderer targetFaceRenderer)
            || targetFaceRenderer == null)
        {
            return;
        }

        Material[] sourceMaterials = sourceFaceRenderer.sharedMaterials;
        Material[] targetMaterials = targetFaceRenderer.materials;
        if (sourceMaterials == null || sourceMaterials.Length == 0 || targetMaterials == null || targetMaterials.Length == 0)
        {
            return;
        }

        Material fallbackSource = sourceMaterials[0];
        for (int i = 0; i < sourceMaterials.Length; i++)
        {
            Material candidate = sourceMaterials[i];
            if (candidate == null || !candidate.HasProperty(FaceTextureShaderProperty))
            {
                continue;
            }

            fallbackSource = candidate;
            break;
        }

        bool changed = false;
        for (int i = 0; i < targetMaterials.Length; i++)
        {
            Material targetMaterial = targetMaterials[i];
            if (targetMaterial == null)
            {
                continue;
            }

            Material sourceMaterial = i < sourceMaterials.Length && sourceMaterials[i] != null
                ? sourceMaterials[i]
                : fallbackSource;
            if (sourceMaterial == null)
            {
                continue;
            }

            changed |= CopyFaceMaterialPropertyIfAvailable(sourceMaterial, targetMaterial, FaceTextureShaderProperty, isColor: false);
            changed |= CopyFaceMaterialPropertyIfAvailable(sourceMaterial, targetMaterial, FaceColorMaskShaderProperty, isColor: false);
            changed |= CopyFaceMaterialPropertyIfAvailable(sourceMaterial, targetMaterial, FaceMaskShaderProperty, isColor: false);
            changed |= CopyFaceMaterialPropertyIfAvailable(sourceMaterial, targetMaterial, FaceEyesShaderProperty, isColor: true);
            changed |= CopyFaceMaterialPropertyIfAvailable(sourceMaterial, targetMaterial, FaceEyebrowsShaderProperty, isColor: true);
            changed |= CopyFaceMaterialPropertyIfAvailable(sourceMaterial, targetMaterial, FaceMakeupShaderProperty, isColor: true);
        }

        if (changed)
        {
            targetFaceRenderer.materials = targetMaterials;
        }
    }

    private static void CopySavedFaceChannelColorsToPartColorStorage(
        MinimoCharacterCustomizer sourceCustomizer,
        MinimoCharacterCustomizer targetCustomizer)
    {
        if (sourceCustomizer == null || targetCustomizer == null)
        {
            return;
        }

        CopySavedFaceChannelColorToPartColorStorage(
            sourceCustomizer,
            targetCustomizer,
            FaceEyesShaderProperty,
            SavedFaceEyesStorageMaterialIndex);
        CopySavedFaceChannelColorToPartColorStorage(
            sourceCustomizer,
            targetCustomizer,
            FaceEyebrowsShaderProperty,
            SavedFaceEyebrowsStorageMaterialIndex);
        CopySavedFaceChannelColorToPartColorStorage(
            sourceCustomizer,
            targetCustomizer,
            FaceMakeupShaderProperty,
            SavedFaceMakeupStorageMaterialIndex);
    }

    private static void CopySavedFaceChannelColorToPartColorStorage(
        MinimoCharacterCustomizer sourceCustomizer,
        MinimoCharacterCustomizer targetCustomizer,
        int facePropertyId,
        int storageMaterialIndex)
    {
        if (!TryGetFaceChannelColorFromCustomizer(sourceCustomizer, facePropertyId, out Color channelColor))
        {
            return;
        }

        targetCustomizer.SetPartColor(
            MinimoCharacterCustomizer.PartSlot.Face,
            storageMaterialIndex,
            channelColor);
    }

    private static bool TryGetFaceChannelColorFromCustomizer(
        MinimoCharacterCustomizer sourceCustomizer,
        int propertyId,
        out Color color)
    {
        color = Color.white;
        if (sourceCustomizer == null)
        {
            return false;
        }

        if (!sourceCustomizer.TryGetPartRenderer(MinimoCharacterCustomizer.PartSlot.Face, out SkinnedMeshRenderer faceRenderer)
            || faceRenderer == null)
        {
            return TryGetSavedFaceChannelStorageColor(sourceCustomizer, propertyId, out color);
        }

        Material[] safeMaterials = GetSafeSourceRuntimeMaterials(faceRenderer);
        if (TryGetFaceChannelColorFromMaterials(safeMaterials, propertyId, out color))
        {
            return true;
        }

        Material[] sharedMaterials = faceRenderer.sharedMaterials;
        if (!ReferenceEquals(safeMaterials, sharedMaterials)
            && TryGetFaceChannelColorFromMaterials(sharedMaterials, propertyId, out color))
        {
            return true;
        }

        return TryGetSavedFaceChannelStorageColor(sourceCustomizer, propertyId, out color);
    }

    private static bool TryGetSavedFaceChannelStorageColor(
        MinimoCharacterCustomizer sourceCustomizer,
        int propertyId,
        out Color color)
    {
        color = Color.white;
        if (sourceCustomizer == null)
        {
            return false;
        }

        int storageMaterialIndex;
        int legacyStorageMaterialIndex;
        if (propertyId == FaceEyesShaderProperty)
        {
            storageMaterialIndex = SavedFaceEyesStorageMaterialIndex;
            legacyStorageMaterialIndex = LegacySavedFaceEyesStorageMaterialIndex;
        }
        else if (propertyId == FaceEyebrowsShaderProperty)
        {
            storageMaterialIndex = SavedFaceEyebrowsStorageMaterialIndex;
            legacyStorageMaterialIndex = LegacySavedFaceEyebrowsStorageMaterialIndex;
        }
        else if (propertyId == FaceMakeupShaderProperty)
        {
            storageMaterialIndex = SavedFaceMakeupStorageMaterialIndex;
            legacyStorageMaterialIndex = LegacySavedFaceMakeupStorageMaterialIndex;
        }
        else
        {
            return false;
        }

        if (sourceCustomizer.TryGetPartColor(MinimoCharacterCustomizer.PartSlot.Face, storageMaterialIndex, out color))
        {
            return true;
        }

        return legacyStorageMaterialIndex != storageMaterialIndex
               && sourceCustomizer.TryGetPartColor(MinimoCharacterCustomizer.PartSlot.Face, legacyStorageMaterialIndex, out color);
    }

    private static bool TryGetFaceChannelColorFromMaterials(Material[] materials, int propertyId, out Color color)
    {
        color = Color.white;
        if (materials == null || materials.Length == 0)
        {
            return false;
        }

        for (int i = 0; i < materials.Length; i++)
        {
            Material material = materials[i];
            if (material == null || !material.HasProperty(propertyId))
            {
                continue;
            }

            color = material.GetColor(propertyId);
            return true;
        }

        return false;
    }

    private static void ApplyTPoseParameterForPrefabSave(GameObject root)
    {
        if (root == null)
        {
            return;
        }

        const string tPoseParameterName = "T-Pose";
        Animator[] animators = root.GetComponentsInChildren<Animator>(true);
        for (int i = 0; i < animators.Length; i++)
        {
            Animator animator = animators[i];
            if (animator == null || !HasAnimatorBoolParameter(animator, tPoseParameterName))
            {
                continue;
            }

            bool wasEnabled = animator.enabled;
            if (!wasEnabled)
            {
                animator.enabled = true;
            }

            animator.SetBool(tPoseParameterName, true);
            animator.Update(0f);

            if (!wasEnabled)
            {
                animator.enabled = false;
            }
        }
    }

    private static bool HasAnimatorBoolParameter(Animator animator, string parameterName)
    {
        if (animator == null || string.IsNullOrWhiteSpace(parameterName))
        {
            return false;
        }

        AnimatorControllerParameter[] parameters = animator.parameters;
        for (int i = 0; i < parameters.Length; i++)
        {
            AnimatorControllerParameter parameter = parameters[i];
            if (parameter.type == AnimatorControllerParameterType.Bool
                && string.Equals(parameter.name, parameterName, StringComparison.Ordinal))
            {
                return true;
            }
        }

        return false;
    }

    private static void EnsureEditorFolderExists(string folderPath)
    {
        if (string.IsNullOrWhiteSpace(folderPath))
        {
            return;
        }

        string normalized = folderPath.Replace('\\', '/').TrimEnd('/');
        if (AssetDatabase.IsValidFolder(normalized))
        {
            return;
        }

        string[] segments = normalized.Split('/');
        if (segments.Length == 0 || !string.Equals(segments[0], "Assets", StringComparison.OrdinalIgnoreCase))
        {
            return;
        }

        string current = "Assets";
        for (int i = 1; i < segments.Length; i++)
        {
            string segment = segments[i];
            if (string.IsNullOrWhiteSpace(segment))
            {
                continue;
            }

            string next = $"{current}/{segment}";
            if (!AssetDatabase.IsValidFolder(next))
            {
                AssetDatabase.CreateFolder(current, segment);
            }

            current = next;
        }
    }

    private void ApplySavedPrefab(string assetPath)
    {
        if (customizer == null || string.IsNullOrWhiteSpace(assetPath))
        {
            return;
        }

        GameObject savedPrefab = AssetDatabase.LoadAssetAtPath<GameObject>(assetPath);
        if (savedPrefab == null)
        {
            helperOverrideMessage = "Prefab could not be loaded.";
            RefreshFromCustomizer();
            return;
        }

        bool useCustomizerState = CanDeleteSavedPrefab(assetPath);
        RecordUndoSnapshotIfNeeded();
        if (useCustomizerState
            && TryResolveSavedPrefabCustomizer(savedPrefab, out MinimoCharacterCustomizer savedCustomizer)
            && savedCustomizer != null)
        {
            ApplySavedCustomizerState(savedCustomizer, assetPath);
        }
        else if (TryApplyRawSavedPrefabState(savedPrefab))
        {
        }
        else
        {
            helperOverrideMessage = "The selected prefab does not contain usable character parts.";
            RefreshFromCustomizer();
            return;
        }

        currentSetIndex = -1;
        for (int i = 0; i < savedPrefabButtons.Count; i++)
        {
            SavedPrefabButtonEntry entry = savedPrefabButtons[i];
            if (entry != null && string.Equals(entry.assetPath, assetPath, StringComparison.OrdinalIgnoreCase))
            {
                selectedSavedPrefabIndex = i;
                break;
            }
        }
        TrackLoadedSavedPrefabState(assetPath);
        helperOverrideMessage = $"Loaded: {Path.GetFileNameWithoutExtension(assetPath)}";
        RefreshFromCustomizer();
    }

    private bool TryApplyRawSavedPrefabState(GameObject savedPrefab)
    {
        if (customizer == null || savedPrefab == null)
        {
            return false;
        }

        IReadOnlyList<MinimoCharacterCustomizer.PartSlot> slots = MinimoCharacterCustomizer.Slots;
        bool savedPrefabHasVisibleHair = TryFindSavedPrefabRendererForSlot(
                                             savedPrefab.transform,
                                             MinimoCharacterCustomizer.PartSlot.Hair,
                                             out SkinnedMeshRenderer sourceHairRenderer)
                                         && IsVisibleHairRenderer(sourceHairRenderer);
        bool appliedAnyPart = false;
        for (int i = 0; i < slots.Count; i++)
        {
            MinimoCharacterCustomizer.PartSlot slot = slots[i];
            if (!TryFindSavedPrefabRendererForSlot(savedPrefab.transform, slot, out SkinnedMeshRenderer sourceRenderer)
                || sourceRenderer == null
                || !customizer.TryGetPartRenderer(slot, out SkinnedMeshRenderer targetRenderer)
                || targetRenderer == null)
            {
                continue;
            }

            CopyRendererVisualState(sourceRenderer, targetRenderer);
            appliedAnyPart = true;
        }

        if (!appliedAnyPart)
        {
            return false;
        }

        selectedPropRigName = CopyPropInstancesFromRoot(savedPrefab.transform, customizer);
        hairRendererUnlockedByUserSelection = savedPrefabHasVisibleHair;
        SetHairRendererEnabled(savedPrefabHasVisibleHair);

        ClearAllRuntimePartColorOverrides();
        SyncSelectedFaceTextureSetKeyFromCurrentMaterial();
        return true;
    }
#endif

    private void ApplySavedCustomizerState(MinimoCharacterCustomizer sourceCustomizer, string savedPrefabAssetPath = "")
    {
        if (customizer == null || sourceCustomizer == null)
        {
            return;
        }

        IReadOnlyList<MinimoCharacterCustomizer.PartSlot> slots = MinimoCharacterCustomizer.Slots;
        for (int i = 0; i < slots.Count; i++)
        {
            MinimoCharacterCustomizer.PartSlot slot = slots[i];
            customizer.SetPartVariant(slot, sourceCustomizer.GetPartVariant(slot));
        }

        customizer.ApplyCurrentSelection();
        CopyPartRendererVisualStateBetweenCustomizers(sourceCustomizer, customizer);
        hairRendererUnlockedByUserSelection = SourceCustomizerHasVisibleHair(sourceCustomizer);
        SetHairRendererEnabled(hairRendererUnlockedByUserSelection);
        selectedPropRigName = CopyPropInstancesBetweenCustomizers(sourceCustomizer, customizer);
#if UNITY_EDITOR
        ApplySavedMaterialAssetsFromFolder(customizer, savedPrefabAssetPath);
#endif
        ClearAllRuntimePartColorOverrides();

        for (int i = 0; i < slots.Count; i++)
        {
            MinimoCharacterCustomizer.PartSlot slot = slots[i];
            if (sourceCustomizer.TryGetPartColor(slot, -1, out Color fallbackColor))
            {
                customizer.SetPartColor(slot, fallbackColor);
            }

            if (!sourceCustomizer.TryGetPartRenderer(slot, out SkinnedMeshRenderer sourceRenderer) || sourceRenderer == null)
            {
                continue;
            }

            Material[] sourceMaterials = sourceRenderer.sharedMaterials;
            int sourceMaterialCount = sourceMaterials != null ? sourceMaterials.Length : 0;
            for (int materialIndex = 0; materialIndex < sourceMaterialCount; materialIndex++)
            {
                if (sourceCustomizer.TryGetPartColor(slot, materialIndex, out Color sourceColor))
                {
                    customizer.SetPartColor(slot, materialIndex, sourceColor);
                }
            }
        }

        NormalizeSavedLowerBodyMirroredColors(customizer);
        ApplySavedFaceChannelColorsFromPartColorStorage(sourceCustomizer, customizer);
        SyncSelectedFaceTextureSetKeyFromCurrentMaterial();
    }

    private void NormalizeSavedLowerBodyMirroredColors(MinimoCharacterCustomizer targetCustomizer)
    {
        NormalizeSavedMirroredPairColor(
            targetCustomizer,
            MinimoCharacterCustomizer.PartSlot.LegUpperLeft,
            MinimoCharacterCustomizer.PartSlot.LegUpperRight,
            MinimoCharacterCustomizer.PartSlot.Hips,
            MinimoCharacterCustomizer.PartSlot.Torso);
        NormalizeSavedMirroredPairColor(
            targetCustomizer,
            MinimoCharacterCustomizer.PartSlot.BootsLeft,
            MinimoCharacterCustomizer.PartSlot.BootsRight,
            MinimoCharacterCustomizer.PartSlot.Hips,
            MinimoCharacterCustomizer.PartSlot.Torso);
    }

    private void NormalizeSavedMirroredPairColor(
        MinimoCharacterCustomizer targetCustomizer,
        MinimoCharacterCustomizer.PartSlot leftSlot,
        MinimoCharacterCustomizer.PartSlot rightSlot,
        MinimoCharacterCustomizer.PartSlot primaryReferenceSlot,
        MinimoCharacterCustomizer.PartSlot fallbackReferenceSlot)
    {
        if (targetCustomizer == null)
        {
            return;
        }

        int leftVariant = targetCustomizer.GetPartVariant(leftSlot);
        int rightVariant = targetCustomizer.GetPartVariant(rightSlot);
        if (leftVariant < 0 || rightVariant < 0 || leftVariant != rightVariant)
        {
            return;
        }

        int channelCount = Mathf.Max(
            GetEditableColorMaterialIndicesForSlot(targetCustomizer, leftSlot).Count,
            GetEditableColorMaterialIndicesForSlot(targetCustomizer, rightSlot).Count);
        if (channelCount <= 0)
        {
            return;
        }

        for (int channelIndex = 0; channelIndex < channelCount; channelIndex++)
        {
            int leftMaterialIndex = ResolveColorMaterialIndexForSlot(targetCustomizer, leftSlot, channelIndex);
            int rightMaterialIndex = ResolveColorMaterialIndexForSlot(targetCustomizer, rightSlot, channelIndex);
            if (leftMaterialIndex < 0 || rightMaterialIndex < 0)
            {
                continue;
            }

            bool hasLeftColor = TryGetEffectivePartColor(targetCustomizer, leftSlot, leftMaterialIndex, out Color leftColor);
            bool hasRightColor = TryGetEffectivePartColor(targetCustomizer, rightSlot, rightMaterialIndex, out Color rightColor);
            if (!hasLeftColor && !hasRightColor)
            {
                continue;
            }

            if (hasLeftColor && hasRightColor && ColorsNearlyEqual(leftColor, rightColor))
            {
                continue;
            }

            Color sourceColor = ResolveSavedMirrorSourceColor(
                targetCustomizer,
                leftColor,
                hasLeftColor,
                rightColor,
                hasRightColor,
                primaryReferenceSlot,
                fallbackReferenceSlot,
                channelIndex);
            targetCustomizer.SetPartColor(leftSlot, leftMaterialIndex, sourceColor);
            targetCustomizer.SetPartColor(rightSlot, rightMaterialIndex, sourceColor);
        }
    }

    private Color ResolveSavedMirrorSourceColor(
        MinimoCharacterCustomizer targetCustomizer,
        Color leftColor,
        bool hasLeftColor,
        Color rightColor,
        bool hasRightColor,
        MinimoCharacterCustomizer.PartSlot primaryReferenceSlot,
        MinimoCharacterCustomizer.PartSlot fallbackReferenceSlot,
        int channelIndex)
    {
        if (hasLeftColor && !hasRightColor)
        {
            return leftColor;
        }

        if (!hasLeftColor && hasRightColor)
        {
            return rightColor;
        }

        if (TryGetSavedMirrorReferenceColor(targetCustomizer, primaryReferenceSlot, fallbackReferenceSlot, channelIndex, out Color referenceColor))
        {
            float leftDistance = ColorDistanceSquared(leftColor, referenceColor);
            float rightDistance = ColorDistanceSquared(rightColor, referenceColor);
            return leftDistance <= rightDistance ? leftColor : rightColor;
        }

        return leftColor;
    }

    private bool TryGetSavedMirrorReferenceColor(
        MinimoCharacterCustomizer targetCustomizer,
        MinimoCharacterCustomizer.PartSlot primaryReferenceSlot,
        MinimoCharacterCustomizer.PartSlot fallbackReferenceSlot,
        int channelIndex,
        out Color referenceColor)
    {
        int primaryMaterialIndex = ResolveColorMaterialIndexForSlot(targetCustomizer, primaryReferenceSlot, channelIndex);
        if (primaryMaterialIndex >= 0 && TryGetEffectivePartColor(targetCustomizer, primaryReferenceSlot, primaryMaterialIndex, out referenceColor))
        {
            return true;
        }

        int fallbackMaterialIndex = ResolveColorMaterialIndexForSlot(targetCustomizer, fallbackReferenceSlot, channelIndex);
        if (fallbackMaterialIndex >= 0 && TryGetEffectivePartColor(targetCustomizer, fallbackReferenceSlot, fallbackMaterialIndex, out referenceColor))
        {
            return true;
        }

        referenceColor = Color.white;
        return false;
    }

    private static void CopyPartRendererVisualStateBetweenCustomizers(
        MinimoCharacterCustomizer sourceCustomizer,
        MinimoCharacterCustomizer targetCustomizer)
    {
        if (sourceCustomizer == null || targetCustomizer == null)
        {
            return;
        }

        IReadOnlyList<MinimoCharacterCustomizer.PartSlot> slots = MinimoCharacterCustomizer.Slots;
        for (int i = 0; i < slots.Count; i++)
        {
            MinimoCharacterCustomizer.PartSlot slot = slots[i];
            if (!sourceCustomizer.TryGetPartRenderer(slot, out SkinnedMeshRenderer sourceRenderer)
                || sourceRenderer == null
                || !targetCustomizer.TryGetPartRenderer(slot, out SkinnedMeshRenderer targetRenderer)
                || targetRenderer == null)
            {
                continue;
            }

            targetRenderer.enabled = sourceRenderer.enabled;
            targetRenderer.sharedMesh = sourceRenderer.sharedMesh;
#if UNITY_EDITOR
            targetRenderer.sharedMaterials = CopyPartMaterialsForRuntime(sourceRenderer.sharedMaterials);
#else
            targetRenderer.sharedMaterials = CopyMaterialArray(sourceRenderer.sharedMaterials);
#endif
            targetRenderer.localBounds = sourceRenderer.localBounds;
        }
    }

    private static void CopyRendererVisualState(SkinnedMeshRenderer sourceRenderer, SkinnedMeshRenderer targetRenderer)
    {
        if (sourceRenderer == null || targetRenderer == null)
        {
            return;
        }

        targetRenderer.enabled = sourceRenderer.enabled;
        targetRenderer.sharedMesh = sourceRenderer.sharedMesh;
#if UNITY_EDITOR
        targetRenderer.sharedMaterials = CopyPartMaterialsForRuntime(sourceRenderer.sharedMaterials);
#else
        targetRenderer.sharedMaterials = CopyMaterialArray(sourceRenderer.sharedMaterials);
#endif
        targetRenderer.localBounds = sourceRenderer.localBounds;
    }

    private static bool SourceCustomizerHasVisibleHair(MinimoCharacterCustomizer sourceCustomizer)
    {
        return sourceCustomizer != null
               && sourceCustomizer.TryGetPartRenderer(
                   MinimoCharacterCustomizer.PartSlot.Hair,
                   out SkinnedMeshRenderer hairRenderer)
               && IsVisibleHairRenderer(hairRenderer);
    }

    private static bool IsVisibleHairRenderer(SkinnedMeshRenderer hairRenderer)
    {
        return hairRenderer != null
               && hairRenderer.enabled
               && hairRenderer.sharedMesh != null;
    }

    private static void ApplySavedFaceChannelColorsFromPartColorStorage(
        MinimoCharacterCustomizer sourceCustomizer,
        MinimoCharacterCustomizer targetCustomizer)
    {
        if (sourceCustomizer == null || targetCustomizer == null)
        {
            return;
        }

        ApplySavedFaceChannelColorFromPartColorStorage(
            sourceCustomizer,
            targetCustomizer,
            SavedFaceEyesStorageMaterialIndex,
            LegacySavedFaceEyesStorageMaterialIndex,
            FaceEyesShaderProperty);
        ApplySavedFaceChannelColorFromPartColorStorage(
            sourceCustomizer,
            targetCustomizer,
            SavedFaceEyebrowsStorageMaterialIndex,
            LegacySavedFaceEyebrowsStorageMaterialIndex,
            FaceEyebrowsShaderProperty);
        ApplySavedFaceChannelColorFromPartColorStorage(
            sourceCustomizer,
            targetCustomizer,
            SavedFaceMakeupStorageMaterialIndex,
            LegacySavedFaceMakeupStorageMaterialIndex,
            FaceMakeupShaderProperty);
    }

    private static void ApplySavedFaceChannelColorFromPartColorStorage(
        MinimoCharacterCustomizer sourceCustomizer,
        MinimoCharacterCustomizer targetCustomizer,
        int storageMaterialIndex,
        int legacyStorageMaterialIndex,
        int facePropertyId)
    {
        if (!sourceCustomizer.TryGetPartColor(
                MinimoCharacterCustomizer.PartSlot.Face,
                storageMaterialIndex,
                out Color channelColor))
        {
            if (legacyStorageMaterialIndex == storageMaterialIndex
                || !sourceCustomizer.TryGetPartColor(
                    MinimoCharacterCustomizer.PartSlot.Face,
                    legacyStorageMaterialIndex,
                    out channelColor))
            {
                return;
            }
        }

        targetCustomizer.SetPartColor(
            MinimoCharacterCustomizer.PartSlot.Face,
            storageMaterialIndex,
            channelColor);

        ApplyFaceChannelColorToCustomizer(targetCustomizer, facePropertyId, channelColor);
    }

    private static void ApplyFaceChannelColorToCustomizer(
        MinimoCharacterCustomizer targetCustomizer,
        int facePropertyId,
        Color color)
    {
        if (targetCustomizer == null
            || !targetCustomizer.TryGetPartRenderer(MinimoCharacterCustomizer.PartSlot.Face, out SkinnedMeshRenderer faceRenderer)
            || faceRenderer == null)
        {
            return;
        }

        Material[] materials = faceRenderer.sharedMaterials;
        if (materials == null || materials.Length == 0)
        {
            return;
        }

        MaterialPropertyBlock block = new MaterialPropertyBlock();
        for (int i = 0; i < materials.Length; i++)
        {
            Material material = materials[i];
            if (material == null || !material.HasProperty(facePropertyId))
            {
                continue;
            }

            block.Clear();
            faceRenderer.GetPropertyBlock(block, i);
            block.SetColor(facePropertyId, color);
            faceRenderer.SetPropertyBlock(block, i);
        }
    }

    private void CopyFaceMaterialCustomizationFromSource(MinimoCharacterCustomizer sourceCustomizer)
    {
        if (customizer == null || sourceCustomizer == null)
        {
            return;
        }

        if (!sourceCustomizer.TryGetPartRenderer(MinimoCharacterCustomizer.PartSlot.Face, out SkinnedMeshRenderer sourceFaceRenderer)
            || sourceFaceRenderer == null
            || !customizer.TryGetPartRenderer(MinimoCharacterCustomizer.PartSlot.Face, out SkinnedMeshRenderer targetFaceRenderer)
            || targetFaceRenderer == null)
        {
            return;
        }

        Material[] sourceMaterials = sourceFaceRenderer.sharedMaterials;
        Material[] targetMaterials = targetFaceRenderer.materials;
        if (sourceMaterials == null || sourceMaterials.Length == 0 || targetMaterials == null || targetMaterials.Length == 0)
        {
            return;
        }

        Material fallbackSource = null;
        for (int i = 0; i < sourceMaterials.Length; i++)
        {
            Material candidate = sourceMaterials[i];
            if (candidate != null && candidate.HasProperty(FaceTextureShaderProperty))
            {
                fallbackSource = candidate;
                break;
            }
        }

        fallbackSource ??= sourceMaterials[0];

        bool changed = false;
        for (int i = 0; i < targetMaterials.Length; i++)
        {
            Material target = targetMaterials[i];
            if (target == null)
            {
                continue;
            }

            Material source = i < sourceMaterials.Length && sourceMaterials[i] != null
                ? sourceMaterials[i]
                : fallbackSource;
            if (source == null)
            {
                continue;
            }

            changed |= CopyFaceMaterialPropertyIfAvailable(source, target, FaceTextureShaderProperty, isColor: false);
            changed |= CopyFaceMaterialPropertyIfAvailable(source, target, FaceColorMaskShaderProperty, isColor: false);
            changed |= CopyFaceMaterialPropertyIfAvailable(source, target, FaceMaskShaderProperty, isColor: false);
            changed |= CopyFaceMaterialPropertyIfAvailable(source, target, FaceEyesShaderProperty, isColor: true);
            changed |= CopyFaceMaterialPropertyIfAvailable(source, target, FaceEyebrowsShaderProperty, isColor: true);
            changed |= CopyFaceMaterialPropertyIfAvailable(source, target, FaceMakeupShaderProperty, isColor: true);
        }

        if (changed)
        {
            targetFaceRenderer.materials = targetMaterials;
        }
    }

    private static bool CopyFaceMaterialPropertyIfAvailable(Material source, Material target, int propertyId, bool isColor)
    {
        if (source == null || target == null || !source.HasProperty(propertyId) || !target.HasProperty(propertyId))
        {
            return false;
        }

        if (isColor)
        {
            target.SetColor(propertyId, source.GetColor(propertyId));
        }
        else
        {
            target.SetTexture(propertyId, source.GetTexture(propertyId));
        }

        return true;
    }

    private void ApplySavedPrefabByIndex(int index)
    {
#if UNITY_EDITOR
        if (savedPrefabButtons.Count == 0)
        {
            selectedSavedPrefabIndex = -1;
            return;
        }

        int clampedIndex = Mathf.Clamp(index, 0, savedPrefabButtons.Count - 1);
        SavedPrefabButtonEntry entry = savedPrefabButtons[clampedIndex];
        if (entry == null || string.IsNullOrWhiteSpace(entry.assetPath))
        {
            return;
        }

        selectedSavedPrefabIndex = clampedIndex;
        UpdateSavedPrefabButtonVisuals();
        ScrollSavedPrefabIntoView(clampedIndex);
        ApplySavedPrefab(entry.assetPath);
#endif
    }

#if UNITY_EDITOR
    private void TryApplySavedPrefabButtonPreview(Button button, GameObject savedPrefab, string savedPrefabAssetPath)
    {
        if (button == null || savedPrefab == null)
        {
            return;
        }

        Texture previewTexture = null;
        bool usesRenderedPreview = false;
        if (TryRenderSavedPrefabPreviewTexture(savedPrefab, savedPrefabAssetPath, out Texture2D renderedPreviewTexture))
        {
            previewTexture = renderedPreviewTexture;
            usesRenderedPreview = true;
            savedPrefabPreviewTextures.Add(renderedPreviewTexture);
        }

        if (previewTexture == null)
        {
            previewTexture = AssetPreview.GetAssetPreview(savedPrefab);
        }

        if (previewTexture == null)
        {
            previewTexture = AssetPreview.GetMiniThumbnail(savedPrefab);
        }

        if (previewTexture == null)
        {
            return;
        }

        if (!usesRenderedPreview
            && TryCreatePreparedPreviewTextureCopy(
                previewTexture,
                SavedPrefabPreviewTextureResolution,
                out Texture2D preparedPreviewTexture))
        {
            previewTexture = preparedPreviewTexture;
            savedPrefabPreviewTextures.Add(preparedPreviewTexture);
        }

        Text label = FindChildByNameIn<Text>(button.transform, "Label");
        if (label != null)
        {
            label.text = string.Empty;
            label.gameObject.SetActive(false);
        }

        ConfigurePreviewTextureSampling(previewTexture);
        float contentScale = usesRenderedPreview ? SavedPrefabPreviewContentScale : 1f;
        CreateRoundedPreviewImage(button, previewTexture, SavedPrefabPreviewRectInset, contentScale);
        ConfigureSavedPrefabPreviewVisual(button);
    }

    private bool TryRenderSavedPrefabPreviewTexture(GameObject savedPrefab, string savedPrefabAssetPath, out Texture2D previewTexture)
    {
        previewTexture = null;
        if (savedPrefab == null
            || !EnsureVariantPreviewRenderer()
            || !EnsureVariantPreviewRenderTexture(
                SavedPrefabPreviewTextureResolution,
                SavedPrefabPreviewAntiAliasing,
                applyRuntimeHudCap: false))
        {
            return false;
        }

        variantPreviewMeshFilter.sharedMesh = null;
        variantPreviewMeshRenderer.sharedMaterial = null;

        GameObject instance = null;
        try
        {
            instance = Instantiate(savedPrefab);
            if (instance == null)
            {
                return false;
            }

            instance.name = StripUnityCloneSuffix(savedPrefab.name);
            instance.hideFlags = HideFlags.HideAndDontSave;
            instance.transform.SetParent(variantPreviewPrefabRoot, false);
            instance.transform.localPosition = Vector3.zero;
            instance.transform.localRotation = Quaternion.identity;
            instance.transform.localScale = Vector3.one;
            StripUnityCloneSuffixesRecursively(instance.transform);
            SetHideFlagsRecursively(instance.transform, HideFlags.HideAndDontSave);
            TryResolveSavedPrefabCustomizer(instance, out MinimoCharacterCustomizer previewCustomizer);
            bool savedHairWasVisible = SourceCustomizerHasVisibleHair(previewCustomizer);
            PreparePreviewInstanceForTPose(instance);
            if (previewCustomizer != null)
            {
                if (previewCustomizer.TryGetPartRenderer(
                        MinimoCharacterCustomizer.PartSlot.Hair,
                        out SkinnedMeshRenderer previewHairRenderer)
                    && previewHairRenderer != null)
                {
                    previewHairRenderer.enabled = savedHairWasVisible;
                }

                ApplySavedMaterialAssetsFromFolder(previewCustomizer, savedPrefabAssetPath);
                ClearRendererPropertyBlocks(instance);
                ApplySavedPrefabPreviewColorState(previewCustomizer);
            }

            ApplyPreviewMaterialBoostsToRenderers(instance);

            if (!TryGetWorldPreviewBoundsAndCenter(instance, out Bounds worldBounds, out Vector3 worldVertexCenter))
            {
                return false;
            }

            Vector3 localCenter = variantPreviewRoot.transform.InverseTransformPoint(worldVertexCenter);
            instance.transform.localPosition -= localCenter;
            instance.transform.localRotation = Quaternion.Euler(0f, 180f, 0f);

            if (!TryGetWorldPreviewBoundsAndCenter(instance, out worldBounds, out worldVertexCenter))
            {
                return false;
            }

            localCenter = variantPreviewRoot.transform.InverseTransformPoint(worldVertexCenter);
            instance.transform.localPosition -= localCenter;

            float aspect = variantPreviewRenderTexture != null && variantPreviewRenderTexture.height > 0
                ? variantPreviewRenderTexture.width / (float)variantPreviewRenderTexture.height
                : 1f;
            float halfWidth = Mathf.Max(0.05f, worldBounds.extents.x);
            float halfHeight = Mathf.Max(0.05f, worldBounds.extents.y);
            float orthoSizeFromWidth = aspect > 0.0001f ? halfWidth / aspect : halfWidth;
            float orthoSize = Mathf.Max(halfHeight, orthoSizeFromWidth)
                              * 1.01f
                              * SavedPrefabPreviewCameraPaddingScale;
            float depth = Mathf.Max(0.15f, worldBounds.extents.z * 2f);
            float cameraDistance = Mathf.Max(1.6f, depth * 1.6f);

            variantPreviewCamera.transform.localPosition = new Vector3(0f, 0f, -cameraDistance);
            variantPreviewCamera.transform.localRotation = Quaternion.identity;
            variantPreviewCamera.orthographic = true;
            variantPreviewCamera.orthographicSize = orthoSize;
            variantPreviewCamera.nearClipPlane = 0.01f;
            variantPreviewCamera.farClipPlane = cameraDistance + depth * 4f + 2f;
            variantPreviewCamera.backgroundColor = PreviewBackgroundColor;
            ConfigureBrightPreviewLighting();

            previewTexture = RenderVariantPreviewToTexture2D();
            if (previewTexture == null)
            {
                return false;
            }

            ConfigurePreviewTextureSampling(previewTexture);
            return true;
        }
        finally
        {
            if (instance != null)
            {
                DestroyPreviewTempObject(instance);
            }
        }
    }

    private void ApplySavedPrefabPreviewColorState(MinimoCharacterCustomizer previewCustomizer)
    {
        if (previewCustomizer == null)
        {
            return;
        }

        List<(MinimoCharacterCustomizer.PartSlot slot, int materialIndex, Color color)> colorAssignments = new List<(MinimoCharacterCustomizer.PartSlot slot, int materialIndex, Color color)>();
        IReadOnlyList<MinimoCharacterCustomizer.PartSlot> slots = MinimoCharacterCustomizer.Slots;
        for (int i = 0; i < slots.Count; i++)
        {
            MinimoCharacterCustomizer.PartSlot slot = slots[i];
            if (previewCustomizer.TryGetPartColor(slot, -1, out Color fallbackColor))
            {
                colorAssignments.Add((slot, -1, fallbackColor));
            }

            if (!previewCustomizer.TryGetPartRenderer(slot, out SkinnedMeshRenderer renderer) || renderer == null)
            {
                continue;
            }

            Material[] materials = renderer.sharedMaterials;
            int materialCount = materials != null ? materials.Length : 0;
            for (int materialIndex = 0; materialIndex < materialCount; materialIndex++)
            {
                if (previewCustomizer.TryGetPartColor(slot, materialIndex, out Color materialColor))
                {
                    colorAssignments.Add((slot, materialIndex, materialColor));
                }
            }
        }

        for (int i = 0; i < slots.Count; i++)
        {
            previewCustomizer.ClearPartColor(slots[i]);
        }

        if (colorAssignments.Count > 0)
        {
            previewCustomizer.SetPartColors(colorAssignments);
        }

        NormalizeSavedLowerBodyMirroredColors(previewCustomizer);
        ApplySavedFaceChannelColorsFromPartColorStorage(previewCustomizer, previewCustomizer);
    }

    private static void ConfigurePreviewTextureSampling(Texture texture)
    {
        if (texture == null)
        {
            return;
        }

        texture.filterMode = FilterMode.Bilinear;
        texture.wrapMode = TextureWrapMode.Clamp;
        if (texture is Texture2D texture2D)
        {
            texture2D.anisoLevel = 2;
        }
    }

    private static bool TryCreatePreparedPreviewTextureCopy(
        Texture source,
        int preferredResolution,
        out Texture2D texture)
    {
        texture = null;
        if (source == null)
        {
            return false;
        }

        int size = Mathf.Clamp(preferredResolution, 64, MaxPreviewTextureResolution);
        RenderTexture previous = RenderTexture.active;
        RenderTexture temporary = null;
        FilterMode previousSourceFilterMode = source.filterMode;
        try
        {
            source.filterMode = FilterMode.Bilinear;
            temporary = RenderTexture.GetTemporary(size, size, 0, RenderTextureFormat.ARGB32);
            temporary.filterMode = FilterMode.Bilinear;
            temporary.wrapMode = TextureWrapMode.Clamp;
            Graphics.Blit(source, temporary);

            RenderTexture.active = temporary;
            texture = new Texture2D(size, size, TextureFormat.RGBA32, false)
            {
                filterMode = FilterMode.Bilinear,
                wrapMode = TextureWrapMode.Clamp,
                anisoLevel = 2
            };
            texture.ReadPixels(new Rect(0f, 0f, size, size), 0, 0, false);
            EnhancePreviewTextureColors(texture);
            texture.Apply(false, false);
            return true;
        }
        catch (UnityException)
        {
            DestroyPreviewTexture(texture);
            texture = null;
            return false;
        }
        finally
        {
            source.filterMode = previousSourceFilterMode;
            RenderTexture.active = previous;
            if (temporary != null)
            {
                RenderTexture.ReleaseTemporary(temporary);
            }
        }
    }

    private static void ClearRendererPropertyBlocks(GameObject root)
    {
        if (root == null)
        {
            return;
        }

        Renderer[] renderers = root.GetComponentsInChildren<Renderer>(true);
        for (int rendererIndex = 0; rendererIndex < renderers.Length; rendererIndex++)
        {
            Renderer renderer = renderers[rendererIndex];
            if (renderer == null)
            {
                continue;
            }

            renderer.SetPropertyBlock(null);
            Material[] materials = renderer.sharedMaterials;
            int materialCount = materials != null ? materials.Length : 0;
            for (int materialIndex = 0; materialIndex < materialCount; materialIndex++)
            {
                renderer.SetPropertyBlock(null, materialIndex);
            }
        }
    }

    private static void PreparePreviewInstanceForTPose(GameObject instance)
    {
        if (instance == null)
        {
            return;
        }

        Animator[] animators = instance.GetComponentsInChildren<Animator>(true);
        for (int i = 0; i < animators.Length; i++)
        {
            Animator animator = animators[i];
            if (animator == null)
            {
                continue;
            }

            animator.enabled = true;
            animator.Rebind();
            if (HasAnimatorBoolParameter(animator, "T-Pose"))
            {
                animator.SetBool("T-Pose", true);
            }

            animator.Update(0.05f);
            animator.Update(0f);
            animator.enabled = false;
        }

        Animation[] legacyAnimations = instance.GetComponentsInChildren<Animation>(true);
        for (int i = 0; i < legacyAnimations.Length; i++)
        {
            Animation animation = legacyAnimations[i];
            if (animation == null)
            {
                continue;
            }

            animation.Stop();
            animation.enabled = false;
        }
    }

    private static void ConfigureSavedPrefabPreviewVisual(Button button)
    {
        if (button == null)
        {
            return;
        }

        Transform preview = button.transform.Find("Preview");
        if (preview == null)
        {
            return;
        }

        Image previewBackground = preview.GetComponent<Image>();
        if (previewBackground != null)
        {
            previewBackground.color = Color.white;
            previewBackground.raycastTarget = false;
        }

        Mask previewMask = preview.GetComponent<Mask>();
        if (previewMask != null)
        {
            previewMask.showMaskGraphic = true;
        }

        Transform frame = preview.Find("Frame");
        if (frame != null)
        {
            DestroyGameObjectSafely(frame.gameObject);
        }
    }
