    private void ScrollSavedPrefabIntoView(int index)
    {
        if (savePrefabsScroll == null || savePrefabsContent == null || index < 0 || index >= savePrefabsContent.childCount)
        {
            return;
        }

        if (savePrefabsScroll.viewport == null)
        {
            return;
        }

        RectTransform viewport = savePrefabsScroll.viewport;
        RectTransform childRect = savePrefabsContent.GetChild(index) as RectTransform;
        if (childRect == null)
        {
            return;
        }

        Canvas.ForceUpdateCanvases();
        UpdateSavedPrefabsContentSize();
        Canvas.ForceUpdateCanvases();

        float contentWidth = savePrefabsContent.rect.width;
        float viewportWidth = viewport.rect.width;
        if (contentWidth <= viewportWidth + 0.01f)
        {
            savePrefabsScroll.horizontalNormalizedPosition = 0f;
            return;
        }

        Vector3[] contentCorners = new Vector3[4];
        Vector3[] childCorners = new Vector3[4];
        savePrefabsContent.GetWorldCorners(contentCorners);
        childRect.GetWorldCorners(childCorners);

        float childCenterX = (childCorners[0].x + childCorners[3].x) * 0.5f;
        float contentLeftX = contentCorners[0].x;
        float viewportSpan = Mathf.Max(0.001f, viewportWidth);
        float targetLeftInContent = Mathf.Max(0f, (childCenterX - contentLeftX) - viewportSpan * 0.5f);
        float maxOffset = Mathf.Max(0.001f, contentWidth - viewportSpan);
        float normalized = Mathf.Clamp01(targetLeftInContent / maxOffset);
        savePrefabsScroll.horizontalNormalizedPosition = normalized;
    }

    private static Button EnsureBodySelectButton(GameObject host)
    {
        Image image = host.GetComponent<Image>();
        if (image == null)
        {
            image = host.AddComponent<Image>();
        }

        Button button = host.GetComponent<Button>();
        if (button == null)
        {
            button = host.AddComponent<Button>();
        }

        button.targetGraphic = image;
        return button;
    }

    private Button CreateVariantButton(
        Transform parent,
        Font font,
        string label,
        int variantIndex,
        RuntimePartButtonTemplateKind templateKind = RuntimePartButtonTemplateKind.Variant)
    {
        Button template = ResolvePartButtonTemplate(templateKind);
        if (template != null
            && TryCreateButtonFromTemplate(
                template,
                parent,
                $"Part_{variantIndex + 1:00}",
                label,
                out Button templateButton))
        {
            return templateButton;
        }

        return CreateFallbackVariantButton(parent, font, label, variantIndex);
    }

    private static Button CreateFallbackVariantButton(Transform parent, Font font, string label, int variantIndex)
    {
        GameObject obj = new GameObject($"Part_{variantIndex + 1:00}", typeof(RectTransform), typeof(Image), typeof(Button));
        RectTransform rect = obj.GetComponent<RectTransform>();
        rect.SetParent(parent, false);
        rect.anchorMin = Vector2.zero;
        rect.anchorMax = Vector2.zero;
        rect.pivot = new Vector2(0.5f, 0.5f);
        rect.sizeDelta = new Vector2(108f, 108f);

        Image image = obj.GetComponent<Image>();
        image.color = UiButtonNeutralColor;

        Button button = obj.GetComponent<Button>();
        button.targetGraphic = image;
        ApplyButtonInteractionStyle(button, UiButtonNeutralColor);

        Text txt = CreateRowText("Label", rect, font, 14, TextAnchor.MiddleCenter, new Color(0.93f, 0.93f, 0.93f, 1f));
        txt.text = label;
        txt.rectTransform.anchorMin = Vector2.zero;
        txt.rectTransform.anchorMax = Vector2.one;
        txt.rectTransform.offsetMin = new Vector2(8f, 8f);
        txt.rectTransform.offsetMax = new Vector2(-8f, -8f);
        return button;
    }

    private Button CreateColorButton(Transform parent, Color color, int colorIndex)
    {
        Button template = ResolveColorButtonTemplate();
        if (template != null
            && TryCreateButtonFromTemplate(
                template,
                parent,
                $"Color_{colorIndex + 1:00}",
                string.Empty,
                out Button templateButton))
        {
            ConfigureColorButtonVisual(templateButton, color);
            return templateButton;
        }

        return CreateFallbackColorButton(parent, color, colorIndex);
    }

    private static Button CreateFallbackColorButton(Transform parent, Color color, int colorIndex)
    {
        GameObject obj = new GameObject($"Color_{colorIndex + 1:00}", typeof(RectTransform), typeof(Image), typeof(Button));
        RectTransform rect = obj.GetComponent<RectTransform>();
        rect.SetParent(parent, false);
        rect.anchorMin = Vector2.zero;
        rect.anchorMax = Vector2.zero;
        rect.pivot = new Vector2(0.5f, 0.5f);
        rect.sizeDelta = new Vector2(28f, 28f);

        Image image = obj.GetComponent<Image>();
        image.color = color;
        image.raycastTarget = true;

        Button button = obj.GetComponent<Button>();
        button.targetGraphic = image;
        ApplyButtonInteractionStyle(button, color);
        return button;
    }

    private static bool TryCreateButtonFromTemplate(
        Button template,
        Transform parent,
        string instanceName,
        string label,
        out Button button)
    {
        button = null;
        if (template == null || parent == null)
        {
            return false;
        }

        GameObject instance = Instantiate(template.gameObject, parent, false);
        instance.name = instanceName;
        instance.SetActive(true);

        button = instance.GetComponent<Button>();
        if (button == null)
        {
            button = instance.GetComponentInChildren<Button>(true);
        }

        if (button == null)
        {
            DestroyGameObjectSafely(instance);
            return false;
        }

        ConfigureButtonInstanceFromTemplate(button, label);
        return true;
    }

    private static void ConfigureButtonInstanceFromTemplate(Button button, string label)
    {
        if (button == null)
        {
            return;
        }

        button.gameObject.SetActive(true);
        button.interactable = true;
        button.onClick.RemoveAllListeners();

        Image background = ResolveTemplateButtonImage(button);
        if (background != null)
        {
            button.targetGraphic = background;
            background.raycastTarget = true;
        }

        SetButtonLabelText(button, label);
    }

    private static Image ResolveTemplateButtonImage(Button button)
    {
        if (button == null)
        {
            return null;
        }

        Image selfImage = button.GetComponent<Image>();
        if (selfImage != null)
        {
            return selfImage;
        }

        Image targetImage = button.targetGraphic as Image;
        if (targetImage != null)
        {
            return targetImage;
        }

        return button.GetComponentInChildren<Image>(true);
    }

    private static void SetButtonLabelText(Button button, string label)
    {
        if (button == null)
        {
            return;
        }

        TMP_Text tmpLabel = ResolveButtonTmpLabel(button);
        if (tmpLabel != null)
        {
            tmpLabel.text = label ?? string.Empty;
            tmpLabel.gameObject.SetActive(!string.IsNullOrEmpty(label));
        }

        Text textLabel = ResolveButtonTextLabel(button);
        if (textLabel != null)
        {
            textLabel.text = label ?? string.Empty;
            textLabel.gameObject.SetActive(!string.IsNullOrEmpty(label));
        }
    }

    private static Text ResolveButtonTextLabel(Button button)
    {
        if (button == null)
        {
            return null;
        }

        Text label = FindChildByNameIn<Text>(button.transform, "Label");
        label ??= FindChildByNameIn<Text>(button.transform, "Text");
        if (label != null)
        {
            return label;
        }

        Text[] labels = button.GetComponentsInChildren<Text>(true);
        return labels != null && labels.Length > 0 ? labels[0] : null;
    }

    private static TMP_Text ResolveButtonTmpLabel(Button button)
    {
        if (button == null)
        {
            return null;
        }

        TMP_Text label = FindChildByNameIn<TMP_Text>(button.transform, "Label");
        label ??= FindChildByNameIn<TMP_Text>(button.transform, "Text");
        if (label != null)
        {
            return label;
        }

        TMP_Text[] labels = button.GetComponentsInChildren<TMP_Text>(true);
        return labels != null && labels.Length > 0 ? labels[0] : null;
    }

