    private int ResolveActiveColorButtonIndex(bool hasSelectedPaletteColor, Color selectedPaletteColor)
    {
        if (colorButtons.Count == 0)
        {
            selectedPaletteButtonIndex = -1;
            return -1;
        }

        if (selectedPaletteButtonIndex >= 0 && selectedPaletteButtonIndex < colorButtons.Count)
        {
            ColorButtonEntry selectedEntry = colorButtons[selectedPaletteButtonIndex];
            if (selectedEntry != null
                && (!hasSelectedPaletteColor || ColorsExactlyMatch(selectedEntry.color, selectedPaletteColor)))
            {
                return selectedPaletteButtonIndex;
            }
        }

        if (hasSelectedPaletteColor)
        {
            int resolvedIndex = FindColorButtonIndexByColor(selectedPaletteColor);
            if (resolvedIndex >= 0)
            {
                selectedPaletteButtonIndex = resolvedIndex;
                return resolvedIndex;
            }
        }

        selectedPaletteButtonIndex = -1;
        return -1;
    }

    private int FindColorButtonIndexByColor(Color color)
    {
        int bestIndex = -1;
        float bestDistance = float.MaxValue;
        for (int i = 0; i < colorButtons.Count; i++)
        {
            ColorButtonEntry entry = colorButtons[i];
            if (entry == null)
            {
                continue;
            }

            float distance = ColorDistanceSquared(entry.color, color);
            if (distance < bestDistance)
            {
                bestDistance = distance;
                bestIndex = i;
            }
        }

        return bestDistance <= 0.0002f ? bestIndex : -1;
    }

    private static float ColorDistanceSquared(Color a, Color b)
    {
        float dr = a.r - b.r;
        float dg = a.g - b.g;
        float db = a.b - b.b;
        float da = a.a - b.a;
        return dr * dr + dg * dg + db * db + da * da;
    }

    private static bool ColorsExactlyMatch(Color a, Color b)
    {
        return ColorDistanceSquared(a, b) <= 0.0002f;
    }

    private void ApplyRegionVariant(
        int variantIndex,
        MinimoCharacterCustomizer.PartSlot[] targetSlotsOverride = null)
    {
        if (customizer == null || selectedRegionIndex < 0 || selectedRegionIndex >= regions.Count)
        {
            return;
        }

        MinimoCharacterCustomizer.PartSlot[] targetSlots =
            targetSlotsOverride != null && targetSlotsOverride.Length > 0
                ? CopyPartSlotArray(targetSlotsOverride)
                : GetTargetSlotsForVariantOperations();
        if (IsVariantAlreadySelectedForSlots(targetSlots, variantIndex))
        {
            UpdateVariantButtonVisuals();
            UpdateShadowStickyButtonStates();
            return;
        }

        RecordUndoSnapshotIfNeeded();
        bool hadSkinTone = TryGetCurrentSkinToneColor(out Color currentSkinTone);
        bool preserveSkinLinkedColorSelection = TryCaptureSkinLinkedColorSelectionForVariantChange(
            out Color preservedSkinLinkedColor,
            out MinimoCharacterCustomizer.PartSlot? preservedSkinLinkedAnchorSlot);
        List<RendererStateSnapshot> protectedRendererState = CaptureRendererStateForFaceHairIsolation(targetSlots);
        bool includesHair = SlotArrayContains(targetSlots, MinimoCharacterCustomizer.PartSlot.Hair);
        bool keepHeadOriginalColors = ShouldKeepHeadOriginalColorsForVariant(targetSlots, variantIndex);
        for (int i = 0; i < targetSlots.Length; i++)
        {
            customizer.SetPartVariant(targetSlots[i], variantIndex);
        }

        if (keepHeadOriginalColors)
        {
            for (int i = 0; i < targetSlots.Length; i++)
            {
                MinimoCharacterCustomizer.PartSlot slot = targetSlots[i];
                if (slot == MinimoCharacterCustomizer.PartSlot.Face)
                {
                    ClearPartColorOverridesForSlot(slot);
                }
            }
        }

        customizer.ApplyPartSelections(targetSlots);
        if (includesHair)
        {
            if (variantIndex >= 0)
            {
                hairRendererUnlockedByUserSelection = true;
                SetHairRendererEnabled(true);
            }
            else
            {
                hairRendererUnlockedByUserSelection = false;
                SetHairRendererEnabled(false);
            }
        }

        RestoreRendererStateSnapshots(protectedRendererState);
        if (hadSkinTone && !keepHeadOriginalColors && !preserveSkinLinkedColorSelection)
        {
            ReapplySkinToneToCharacter(
                currentSkinTone,
                includeFace: !SlotArrayContains(targetSlots, MinimoCharacterCustomizer.PartSlot.Face),
                targetSlots: targetSlots);
        }
        currentSetIndex = -1;
        RebuildWorldLinkedTargetsAfterVariantChange(
            selectedColorMaterialIndex,
            preserveSkinLinkedColorSelection && !keepHeadOriginalColors,
            preservedSkinLinkedColor,
            preservedSkinLinkedAnchorSlot,
            targetSlots,
            includeFace: !SlotArrayContains(targetSlots, MinimoCharacterCustomizer.PartSlot.Face));
        RefreshAfterVariantApplication(targetSlots);
    }

    private bool IsVariantAlreadySelectedForSlots(MinimoCharacterCustomizer.PartSlot[] targetSlots, int variantIndex)
    {
        if (customizer == null || targetSlots == null || targetSlots.Length == 0)
        {
            return false;
        }

        if (variantIndex >= 0
            && SlotArrayContains(targetSlots, MinimoCharacterCustomizer.PartSlot.Hair)
            && (!customizer.TryGetPartRenderer(MinimoCharacterCustomizer.PartSlot.Hair, out SkinnedMeshRenderer hairRenderer)
                || !IsVisibleHairRenderer(hairRenderer)))
        {
            return false;
        }

        for (int i = 0; i < targetSlots.Length; i++)
        {
            if (customizer.GetPartVariant(targetSlots[i]) != variantIndex)
            {
                return false;
            }
        }

        return true;
    }

    private List<RendererStateSnapshot> CaptureRendererStateForFaceHairIsolation(
        MinimoCharacterCustomizer.PartSlot[] targetSlots)
    {
        if (customizer == null
            || targetSlots == null
            || targetSlots.Length == 0
            || (!SlotArrayContains(targetSlots, MinimoCharacterCustomizer.PartSlot.Face)
                && !SlotArrayContains(targetSlots, MinimoCharacterCustomizer.PartSlot.Hair)))
        {
            return null;
        }

        List<RendererStateSnapshot> snapshots = new List<RendererStateSnapshot>();
        IReadOnlyList<MinimoCharacterCustomizer.PartSlot> slots = MinimoCharacterCustomizer.Slots;
        for (int i = 0; i < slots.Count; i++)
        {
            MinimoCharacterCustomizer.PartSlot slot = slots[i];
            if (SlotArrayContains(targetSlots, slot)
                || !customizer.TryGetPartRenderer(slot, out SkinnedMeshRenderer renderer)
                || renderer == null)
            {
                continue;
            }

            Material[] materials = renderer.sharedMaterials;
            Transform[] bones = renderer.bones;
            snapshots.Add(new RendererStateSnapshot
            {
                renderer = renderer,
                enabled = renderer.enabled,
                sharedMesh = renderer.sharedMesh,
                sharedMaterials = CopyMaterialArray(materials),
                rootBone = renderer.rootBone,
                bones = CopyTransformArray(bones),
                localBounds = renderer.localBounds,
                materialPropertyBlocks = CaptureMaterialPropertyBlocks(renderer, materials)
            });
        }

        return snapshots.Count > 0 ? snapshots : null;
    }

    private static void RestoreRendererStateSnapshots(List<RendererStateSnapshot> snapshots)
    {
        if (snapshots == null || snapshots.Count == 0)
        {
            return;
        }

        for (int i = 0; i < snapshots.Count; i++)
        {
            RendererStateSnapshot snapshot = snapshots[i];
            SkinnedMeshRenderer renderer = snapshot?.renderer;
            if (renderer == null)
            {
                continue;
            }

            renderer.sharedMesh = snapshot.sharedMesh;
            renderer.sharedMaterials = CopyMaterialArray(snapshot.sharedMaterials);
            renderer.rootBone = snapshot.rootBone;
            renderer.bones = CopyTransformArray(snapshot.bones);
            renderer.localBounds = snapshot.localBounds;
            renderer.enabled = snapshot.enabled;
            RestoreMaterialPropertyBlocks(renderer, snapshot.materialPropertyBlocks);
        }
    }

    private static MaterialPropertyBlock[] CaptureMaterialPropertyBlocks(
        Renderer renderer,
        Material[] materials)
    {
        if (renderer == null)
        {
            return Array.Empty<MaterialPropertyBlock>();
        }

        int materialCount = materials != null ? materials.Length : 0;
        if (materialCount <= 0)
        {
            return Array.Empty<MaterialPropertyBlock>();
        }

        MaterialPropertyBlock[] blocks = new MaterialPropertyBlock[materialCount];
        for (int materialIndex = 0; materialIndex < materialCount; materialIndex++)
        {
            MaterialPropertyBlock block = new MaterialPropertyBlock();
            renderer.GetPropertyBlock(block, materialIndex);
            blocks[materialIndex] = block.isEmpty ? null : block;
        }

        return blocks;
    }

    private static void RestoreMaterialPropertyBlocks(
        Renderer renderer,
        MaterialPropertyBlock[] blocks)
    {
        if (renderer == null)
        {
            return;
        }

        if (blocks == null || blocks.Length == 0)
        {
            renderer.SetPropertyBlock(null);
            return;
        }

        for (int materialIndex = 0; materialIndex < blocks.Length; materialIndex++)
        {
            renderer.SetPropertyBlock(blocks[materialIndex], materialIndex);
        }
    }

    private static Material[] CopyMaterialArray(Material[] materials)
    {
        if (materials == null || materials.Length == 0)
        {
            return Array.Empty<Material>();
        }

        Material[] copy = new Material[materials.Length];
        Array.Copy(materials, copy, materials.Length);
        return copy;
    }

    private static Transform[] CopyTransformArray(Transform[] transforms)
    {
        if (transforms == null || transforms.Length == 0)
        {
            return Array.Empty<Transform>();
        }

        Transform[] copy = new Transform[transforms.Length];
        Array.Copy(transforms, copy, transforms.Length);
        return copy;
    }

    private bool ShouldKeepHeadOriginalColorsForVariant(MinimoCharacterCustomizer.PartSlot[] targetSlots, int variantIndex)
    {
        if (targetSlots == null || targetSlots.Length == 0)
        {
            return false;
        }

        bool includesHead = false;
        for (int i = 0; i < targetSlots.Length; i++)
        {
            if (targetSlots[i] == MinimoCharacterCustomizer.PartSlot.Face)
            {
                includesHead = true;
                break;
            }
        }

        if (!includesHead)
        {
            return false;
        }

        return IsDefaultCategoryVariantForSlot(MinimoCharacterCustomizer.PartSlot.Face, variantIndex);
    }

    private bool IsDefaultCategoryVariantForSlot(MinimoCharacterCustomizer.PartSlot slot, int variantIndex)
    {
        if (variantIndex < 0)
        {
            return true;
        }

        MinimoCharacterCustomizer.PartSlot[] singleSlot = { slot };
        string categoryName = ResolveVariantCategoryNameForSlots(variantIndex, singleSlot);
        return string.Equals(categoryName, CategoryDefaultOptionLabel, StringComparison.OrdinalIgnoreCase);
    }

    private void ClearPartColorOverridesForSlot(MinimoCharacterCustomizer.PartSlot slot)
    {
        if (customizer == null)
        {
            return;
        }

        customizer.ClearPartColor(slot);
        if (!customizer.TryGetPartRenderer(slot, out SkinnedMeshRenderer renderer) || renderer == null)
        {
            return;
        }

        Material[] materials = renderer.sharedMaterials;
        int materialCount = materials != null ? materials.Length : 0;
        for (int materialIndex = 0; materialIndex < materialCount; materialIndex++)
        {
            customizer.ClearPartColor(slot, materialIndex);
        }
    }

