    private void ApplyColorToSelectedRegion(Color color, int sourcePaletteIndex = -1)
    {
        if (customizer == null || selectedRegionIndex < 0 || selectedRegionIndex >= regions.Count)
        {
            return;
        }

        if (IsPropsRegionSelectionMode() && selectedColorChannelTarget == ColorChannelTargetType.Material)
        {
            if (!ApplyColorToSelectedPropChannel(color))
            {
                return;
            }

            selectedPaletteButtonIndex = ResolvePaletteButtonIndexAfterApply(color, sourcePaletteIndex);
            helperOverrideMessage = $"Props color applied: #{ColorUtility.ToHtmlStringRGB(color)}";
            RefreshAfterColorApplication();
            return;
        }

        if (selectedColorChannelTarget != ColorChannelTargetType.Material)
        {
            if (!ApplyColorToFaceChannel(color))
            {
                return;
            }

            selectedPaletteButtonIndex = ResolvePaletteButtonIndexAfterApply(color, sourcePaletteIndex);
            helperOverrideMessage = $"{GetActivePaletteName()} color applied: #{ColorUtility.ToHtmlStringRGB(color)}";
            RefreshAfterColorApplication();
            return;
        }

        List<(MinimoCharacterCustomizer.PartSlot slot, int materialIndex, Color color)> finalColorAssignments = new List<(MinimoCharacterCustomizer.PartSlot slot, int materialIndex, Color color)>();
        bool applySkinGroup = ShouldUseSkinPaletteForCurrentSelection();
        List<MinimoCharacterCustomizer.PartSlot> selectedSlots = GetStableSelectedSlotsForColorApplication(applySkinGroup);
        if (applySkinGroup)
        {
            List<(MinimoCharacterCustomizer.PartSlot slot, int materialIndex)> linkedSkinTargets = GetLinkedSkinColorTargetsForCurrentSelection();
            if (linkedSkinTargets.Count > 0)
            {
                for (int i = 0; i < linkedSkinTargets.Count; i++)
                {
                    (MinimoCharacterCustomizer.PartSlot slot, int materialIndex) target = linkedSkinTargets[i];
                    finalColorAssignments.Add((target.slot, target.materialIndex, color));
                }
            }
            else
            {
                for (int i = 0; i < selectedSlots.Count; i++)
                {
                    MinimoCharacterCustomizer.PartSlot slot = selectedSlots[i];
                    int materialIndex = ResolveExactColorMaterialIndexForSlot(slot, selectedColorMaterialIndex);
                    if (materialIndex >= 0)
                    {
                        finalColorAssignments.Add((slot, materialIndex, color));
                    }
                }
            }
        }
        else
        {
            AppendCommonSelectedColorAssignments(selectedSlots, color, finalColorAssignments);
        }

        if (finalColorAssignments.Count == 0)
        {
            helperOverrideMessage = "No common color channel is available for the selected parts.";
            RefreshAfterColorApplication();
            return;
        }

        RecordUndoSnapshotIfNeeded();
        customizer.SetPartColors(finalColorAssignments);
        selectedPaletteButtonIndex = ResolvePaletteButtonIndexAfterApply(color, sourcePaletteIndex);
        helperOverrideMessage = $"{GetActivePaletteName()} color applied: #{ColorUtility.ToHtmlStringRGB(color)}";
        RefreshAfterColorApplication();
    }

    private void AppendCommonSelectedColorAssignments(
        List<MinimoCharacterCustomizer.PartSlot> selectedSlots,
        Color color,
        List<(MinimoCharacterCustomizer.PartSlot slot, int materialIndex, Color color)> assignments)
    {
        if (selectedSlots == null || selectedSlots.Count == 0 || assignments == null)
        {
            return;
        }

        MinimoCharacterCustomizer.PartSlot anchorSlot = selectedWorldColorTargetSlot.HasValue
                                                       && selectedSlots.Contains(selectedWorldColorTargetSlot.Value)
            ? selectedWorldColorTargetSlot.Value
            : selectedSlots[0];
        int anchorMaterialIndex = ResolveExactColorMaterialIndexForSlot(anchorSlot, selectedColorMaterialIndex);
        if (anchorMaterialIndex >= 0
            && TryGetWorldLinkedMaterialKey(anchorSlot, anchorMaterialIndex, out string commonColorKey))
        {
            for (int i = 0; i < selectedSlots.Count; i++)
            {
                MinimoCharacterCustomizer.PartSlot slot = selectedSlots[i];
                HashSet<int> matchingIndices = GetEditableMaterialIndicesMatchingWorldLinkedKey(slot, commonColorKey);
                foreach (int materialIndex in matchingIndices)
                {
                    assignments.Add((slot, materialIndex, color));
                }
            }

            if (assignments.Count > 0)
            {
                return;
            }
        }

        for (int i = 0; i < selectedSlots.Count; i++)
        {
            MinimoCharacterCustomizer.PartSlot slot = selectedSlots[i];
            int materialIndex = ResolveExactColorMaterialIndexForSlot(slot, selectedColorMaterialIndex);
            if (materialIndex >= 0)
            {
                assignments.Add((slot, materialIndex, color));
            }
        }
    }

    private bool ApplyColorToFaceChannel(Color color)
    {
        if (!TryGetFaceMaterialForCurrentChannel(out Material faceMaterial, out SkinnedMeshRenderer faceRenderer, useSharedMaterials: false)
            || faceMaterial == null
            || faceRenderer == null
            || selectedFaceColorPropertyId < 0
            || !faceMaterial.HasProperty(selectedFaceColorPropertyId))
        {
            return false;
        }

        RecordUndoSnapshotIfNeeded();
        faceMaterial.SetColor(selectedFaceColorPropertyId, color);
        Material[] materials = faceRenderer.materials;
        if (materials != null)
        {
            faceRenderer.materials = materials;
        }

        return true;
    }

    private int ResolvePaletteButtonIndexAfterApply(Color color, int sourcePaletteIndex)
    {
        if (sourcePaletteIndex >= 0 && sourcePaletteIndex < colorButtons.Count)
        {
            return sourcePaletteIndex;
        }

        return FindColorButtonIndexByColor(color);
    }

    private bool TryGetFaceMaterialForCurrentChannel(
        out Material faceMaterial,
        out SkinnedMeshRenderer faceRenderer,
        bool useSharedMaterials = true)
    {
        faceMaterial = null;
        faceRenderer = null;
        if (customizer == null
            || !customizer.TryGetPartRenderer(MinimoCharacterCustomizer.PartSlot.Face, out faceRenderer)
            || faceRenderer == null)
        {
            return false;
        }

        Material[] materials = useSharedMaterials ? faceRenderer.sharedMaterials : faceRenderer.materials;
        if (materials == null || materials.Length == 0)
        {
            return false;
        }

        int materialIndex = ResolveColorMaterialIndexForSlot(MinimoCharacterCustomizer.PartSlot.Face, selectedColorMaterialIndex);
        if (materialIndex < 0 || materialIndex >= materials.Length)
        {
            materialIndex = 0;
        }

        faceMaterial = materials[materialIndex];
        return faceMaterial != null;
    }

    private bool TryGetFaceMaterialForChannel(
        int materialChannelIndex,
        out Material faceMaterial,
        bool useSharedMaterials = true)
    {
        faceMaterial = null;
        if (customizer == null
            || !customizer.TryGetPartRenderer(MinimoCharacterCustomizer.PartSlot.Face, out SkinnedMeshRenderer faceRenderer)
            || faceRenderer == null)
        {
            return false;
        }

        Material[] materials = useSharedMaterials ? faceRenderer.sharedMaterials : faceRenderer.materials;
        if (materials == null || materials.Length == 0)
        {
            return false;
        }

        int materialIndex = ResolveColorMaterialIndexForSlot(MinimoCharacterCustomizer.PartSlot.Face, materialChannelIndex);
        if (materialIndex < 0 || materialIndex >= materials.Length)
        {
            return false;
        }

        faceMaterial = materials[materialIndex];
        return faceMaterial != null;
    }

    private bool TryGetFaceMaterialChannelForProperty(int propertyId, out int materialChannelIndex)
    {
        materialChannelIndex = 0;
        if (customizer == null
            || !customizer.TryGetPartRenderer(MinimoCharacterCustomizer.PartSlot.Face, out SkinnedMeshRenderer faceRenderer)
            || faceRenderer == null)
        {
            return false;
        }

        Material[] materials = faceRenderer.sharedMaterials;
        if (materials == null || materials.Length == 0)
        {
            return false;
        }

        for (int materialIndex = 0; materialIndex < materials.Length; materialIndex++)
        {
            Material material = materials[materialIndex];
            if (material == null || !material.HasProperty(propertyId))
            {
                continue;
            }

            if (TryResolveColorChannelFromMaterialIndex(
                    MinimoCharacterCustomizer.PartSlot.Face,
                    materialIndex,
                    out int resolvedChannelIndex))
            {
                materialChannelIndex = resolvedChannelIndex;
                return true;
            }
        }

        return false;
    }

    private bool TryGetSelectedFaceChannelColor(out Color color)
    {
        color = Color.white;
        if (selectedFaceColorPropertyId < 0
            || !TryGetFaceMaterialForCurrentChannel(out Material faceMaterial, out _)
            || faceMaterial == null
            || !faceMaterial.HasProperty(selectedFaceColorPropertyId))
        {
            return false;
        }

        color = faceMaterial.GetColor(selectedFaceColorPropertyId);
        return true;
    }

    private void ApplyRandomToSelectedRegion()
    {
        if (customizer == null || selectedRegionIndex < 0 || selectedRegionIndex >= regions.Count)
        {
            return;
        }

        if (IsPropsRegionSelectionMode())
        {
            ApplyRandomPropForSelectedRegion();
            return;
        }

        MinimoCharacterCustomizer.PartSlot[] targetSlots = GetTargetSlotsForVariantOperations();
        if (targetSlots.Length == 0)
        {
            return;
        }

        Dictionary<MinimoCharacterCustomizer.PartSlot, List<int>> availableBySlot = new Dictionary<MinimoCharacterCustomizer.PartSlot, List<int>>();
        bool hasAnyAvailableVariant = false;
        for (int i = 0; i < targetSlots.Length; i++)
        {
            MinimoCharacterCustomizer.PartSlot targetSlot = targetSlots[i];
            List<int> slotVariants = GetFilteredVariantIndicesForCurrentCategory(new[] { targetSlot });
            availableBySlot[targetSlot] = slotVariants;
            hasAnyAvailableVariant |= slotVariants.Count > 0;
        }

        if (!hasAnyAvailableVariant)
        {
            return;
        }

        RecordUndoSnapshotIfNeeded();
        bool hadSkinTone = TryGetCurrentSkinToneColor(out Color currentSkinTone);
        bool preserveSkinLinkedColorSelection = TryCaptureSkinLinkedColorSelectionForVariantChange(
            out Color preservedSkinLinkedColor,
            out MinimoCharacterCustomizer.PartSlot? preservedSkinLinkedAnchorSlot);
        List<RendererStateSnapshot> protectedRendererState = CaptureRendererStateForFaceHairIsolation(targetSlots);
        bool hasMirroredPair = TryResolveMirroredSlotsForRegion(targetSlots, out _, out _);
        bool canUseSharedVariant = TryGetSharedAvailableVariants(availableBySlot, targetSlots, out List<int> sharedVariantIndices)
                                   && sharedVariantIndices.Count > 0;
        bool useSingleVariantForAll = canUseSharedVariant
                                      && (hasMirroredPair || UseDualPartMode() || UseUpperBodyGroupMode() || UseLowerBodyGroupMode());
        if (useSingleVariantForAll)
        {
            int randomVariant = PickRandomVariantFromBag(
                $"region-group:{selectedRegionIndex}",
                sharedVariantIndices,
                GetCurrentSharedVariantForSlots(targetSlots));
            for (int i = 0; i < targetSlots.Length; i++)
            {
                customizer.SetPartVariant(targetSlots[i], randomVariant);
            }
        }
        else
        {
            for (int i = 0; i < targetSlots.Length; i++)
            {
                MinimoCharacterCustomizer.PartSlot targetSlot = targetSlots[i];
                if (!availableBySlot.TryGetValue(targetSlot, out List<int> slotVariants)
                    || slotVariants == null
                    || slotVariants.Count == 0)
                {
                    continue;
                }

                int randomVariant = PickRandomVariantFromBag(
                    $"region-slot:{targetSlot}",
                    slotVariants,
                    customizer.GetPartVariant(targetSlot));
                customizer.SetPartVariant(targetSlots[i], randomVariant);
            }
        }

        customizer.ApplyPartSelections(targetSlots);
        if (hasMirroredPair)
        {
            SynchronizeMirroredPairColorsForRegionSlots(targetSlots);
        }
        if (SlotArrayContains(targetSlots, MinimoCharacterCustomizer.PartSlot.Hair))
        {
            hairRendererUnlockedByUserSelection = true;
            SetHairRendererEnabled(true);
        }

        RestoreRendererStateSnapshots(protectedRendererState);
        if (hadSkinTone && !preserveSkinLinkedColorSelection)
        {
            ReapplySkinToneToCharacter(
                currentSkinTone,
                includeFace: !SlotArrayContains(targetSlots, MinimoCharacterCustomizer.PartSlot.Face),
                targetSlots: targetSlots);
        }
        currentSetIndex = -1;
        RebuildWorldLinkedTargetsAfterVariantChange(
            selectedColorMaterialIndex,
            preserveSkinLinkedColorSelection,
            preservedSkinLinkedColor,
            preservedSkinLinkedAnchorSlot,
            targetSlots,
            includeFace: !SlotArrayContains(targetSlots, MinimoCharacterCustomizer.PartSlot.Face));
        RefreshAfterVariantApplication(targetSlots);
    }

    private void ApplyRandomColorFromPalette()
    {
        if (customizer == null || selectedRegionIndex < 0 || selectedRegionIndex >= regions.Count)
        {
            return;
        }

        Color[] palette = GetActivePaletteColors();
        if (palette == null || palette.Length == 0)
        {
            return;
        }

        int randomIndex = UnityEngine.Random.Range(0, palette.Length);
        Color randomColor = palette[randomIndex];
        ApplyColorToSelectedRegion(randomColor, randomIndex);
    }

    private void RefreshCategoryDropdownOptions()
    {
        categoryDropdownOptions.Clear();
        categoryDropdownSelectsRegions = false;

        List<string> options = new List<string>();
        if (!TryBuildCustomizeCategoryOptions(options))
        {
            options.Add(CategoryAllOptionLabel);
        }

        for (int i = 0; i < options.Count; i++)
        {
            string normalized = NormalizeCategoryName(options[i]);
            if (string.IsNullOrWhiteSpace(normalized) || CategoryOptionExists(normalized, categoryDropdownOptions))
            {
                continue;
            }

            if (ShouldHideInfoOnlyCategoryFromDropdown(normalized))
            {
                continue;
            }

            categoryDropdownOptions.Add(normalized);
        }

        if (!CategoryOptionExists(CategoryAllOptionLabel, categoryDropdownOptions))
        {
            categoryDropdownOptions.Insert(0, CategoryAllOptionLabel);
        }

        SortCategoryDropdownOptionsForDisplay();
        EnsureCategorySelectionState();
        EnsureCustomCategoryDropdown();
        RebuildCustomCategoryDropdownOptions();
        UpdateCustomCategoryDropdownLabel();
        if (customCategoryDropdownRoot != null)
        {
            customCategoryDropdownRoot.gameObject.SetActive(true);
            if (!customCategoryDropdownExpanded)
            {
                SetCustomCategoryDropdownOpen(false);
            }
        }

        if (categoryDropdown != null)
        {
            bool usesSceneDropdownButton = UsesSceneCategoryDropdownButton();
            bool useFallbackSceneDropdown = customCategoryDropdownRoot == null;
            categoryDropdown.gameObject.SetActive(usesSceneDropdownButton || useFallbackSceneDropdown);
            if (!usesSceneDropdownButton)
            {
                categoryDropdown.interactable = useFallbackSceneDropdown && categoryDropdownOptions.Count > 1;
            }
            if (customCategoryDropdownToggleButton != null && usesSceneDropdownButton)
            {
                customCategoryDropdownToggleButton.interactable = controlsInteractable && categoryDropdownOptions.Count > 1;
            }
        }
    }

    private bool ShouldHideInfoOnlyCategoryFromDropdown(string rawCategoryName)
    {
        if (showBuyCategoryPanel)
        {
            return false;
        }

        string categoryName = NormalizeCategoryName(rawCategoryName);
        if (string.IsNullOrWhiteSpace(categoryName)
            || IsAllCategoryName(categoryName)
            || IsNonSelectableCategoryName(categoryName)
            || string.Equals(categoryName, CategoryDefaultOptionLabel, StringComparison.OrdinalIgnoreCase))
        {
            return false;
        }

        return !DoesSelectedCategoryHaveCurrentRegionParts(categoryName);
    }

    private void SortCategoryDropdownOptionsForDisplay()
    {
        if (categoryDropdownOptions.Count <= 1)
        {
            return;
        }

        bool hasEverything = false;
        bool hasDefault = false;
        List<string> others = new List<string>();
        for (int i = 0; i < categoryDropdownOptions.Count; i++)
        {
            string normalized = NormalizeCategoryName(categoryDropdownOptions[i]);
            if (string.IsNullOrWhiteSpace(normalized))
            {
                continue;
            }

            if (IsAllCategoryName(normalized))
            {
                hasEverything = true;
                continue;
            }

            if (string.Equals(normalized, CategoryDefaultOptionLabel, StringComparison.OrdinalIgnoreCase))
            {
                hasDefault = true;
                continue;
            }

            AddCategoryOptionIfMissing(others, normalized);
        }

        others.Sort(CompareAlphabeticNatural);

        categoryDropdownOptions.Clear();
        if (hasEverything)
        {
            categoryDropdownOptions.Add(CategoryAllOptionLabel);
        }

        if (hasDefault)
        {
            categoryDropdownOptions.Add(CategoryDefaultOptionLabel);
        }

        for (int i = 0; i < others.Count; i++)
        {
            categoryDropdownOptions.Add(others[i]);
        }
    }

    private static bool IsAllCategoryName(string categoryName)
    {
        return string.Equals(categoryName, CategoryAllOptionLabel, StringComparison.OrdinalIgnoreCase)
               || string.Equals(categoryName, LegacyEverythingOptionLabel, StringComparison.OrdinalIgnoreCase);
    }

    private HashSet<string> GetActiveSpecificCategoryFilters()
    {
        HashSet<string> filters = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        if (IsCategorySelectionActive(CategoryAllOptionLabel))
        {
            return filters;
        }

        foreach (string selected in selectedVariantCategories)
        {
            string normalized = NormalizeCategoryName(selected);
            if (string.IsNullOrWhiteSpace(normalized)
                || IsAllCategoryName(normalized)
                || IsNonSelectableCategoryName(normalized))
            {
                continue;
            }

            filters.Add(normalized);
        }

        return filters;
    }

    private bool MatchesSelectedCategory(
        int variantIndex,
        MinimoCharacterCustomizer.PartSlot[] slots,
        HashSet<string> selectedCategories)
    {
        if (selectedCategories == null || selectedCategories.Count == 0)
        {
            return true;
        }

        string variantCategory = NormalizeCategoryName(ResolveVariantCategoryNameForSlots(variantIndex, slots));
        if (string.IsNullOrWhiteSpace(variantCategory))
        {
            return false;
        }

        return selectedCategories.Contains(variantCategory);
    }

    private static void AddCategoryOptionIfMissing(List<string> options, string rawValue)
    {
        if (options == null)
        {
            return;
        }

        string normalized = NormalizeCategoryName(rawValue);
        if (string.IsNullOrWhiteSpace(normalized))
        {
            return;
        }

        for (int i = 0; i < options.Count; i++)
        {
            if (string.Equals(NormalizeCategoryName(options[i]), normalized, StringComparison.OrdinalIgnoreCase))
            {
                return;
            }
        }

        options.Add(normalized);
    }

    private bool TryBuildCustomizeCategoryOptions(List<string> options)
    {
        if (options == null)
        {
            return false;
        }

        options.Clear();
        AddCategoryOptionIfMissing(options, CategoryAllOptionLabel);
        AddCategoryOptionIfMissing(options, CategoryDefaultOptionLabel);

#if UNITY_EDITOR
        TryBuildCategoryOptionsFromCustomizeFolders(options);
        RefreshCategoryInfoAssetsFromProject();
#else
        TryBuildCategoryOptionsFromCustomizer(options);
#endif
        TryBuildCategoryOptionsFromInfoAssets(options);

        return options.Count > 0;
    }

#if UNITY_EDITOR
    private static bool TryBuildCategoryOptionsFromCustomizeFolders(List<string> options)
    {
        if (options == null || !AssetDatabase.IsValidFolder(CustomizeRootFolder))
        {
            return false;
        }

        string[] categoryFolders = AssetDatabase.GetSubFolders(CustomizeRootFolder);
        Array.Sort(categoryFolders, (left, right) =>
        {
            string leftName = GetCategoryAssetLeafName(left);
            string rightName = GetCategoryAssetLeafName(right);
            return CompareAlphabeticNatural(leftName, rightName);
        });

        bool addedAny = false;
        for (int i = 0; i < categoryFolders.Length; i++)
        {
            string categoryName = NormalizeCategoryName(GetCategoryAssetLeafName(categoryFolders[i]));
            if (string.IsNullOrWhiteSpace(categoryName)
                || IsAllCategoryName(categoryName)
                || IsNonSelectableCategoryName(categoryName))
            {
                continue;
            }

            int beforeCount = options.Count;
            AddCategoryOptionIfMissing(options, categoryName);
            addedAny |= options.Count > beforeCount;
        }

        return addedAny;
    }
#endif

    private bool TryBuildCategoryOptionsFromCustomizer(List<string> options)
    {
        if (options == null || customizer == null)
        {
            return false;
        }

        List<string> availableCategories = customizer.GetCustomizeVariantCategories();
        if (availableCategories == null || availableCategories.Count == 0)
        {
            return false;
        }

        bool addedAny = false;
        for (int i = 0; i < availableCategories.Count; i++)
        {
            string categoryName = NormalizeCategoryName(availableCategories[i]);
            if (string.IsNullOrWhiteSpace(categoryName)
                || IsAllCategoryName(categoryName)
                || IsNonSelectableCategoryName(categoryName))
            {
                continue;
            }

            int beforeCount = options.Count;
            AddCategoryOptionIfMissing(options, categoryName);
            addedAny |= options.Count > beforeCount;
        }

        return addedAny;
    }

    private static string NormalizeCategoryName(string value)
    {
        string normalized = string.IsNullOrWhiteSpace(value) ? string.Empty : value.Trim();
        if (string.Equals(normalized, LegacyEverythingOptionLabel, StringComparison.OrdinalIgnoreCase))
        {
            return CategoryAllOptionLabel;
        }

        return normalized;
    }

    private static int GetVariantCategorySortPriority(string categoryName)
    {
        HashSet<string> tokens = TokenizeCategoryName(categoryName);
        bool hasDefault = tokens.Contains("default");
        bool hasCasual = tokens.Contains("casual");
        bool hasMale = tokens.Contains("male");
        bool hasFemale = tokens.Contains("female");

        if (hasDefault)
        {
            return 0;
        }

        if (hasCasual && hasMale)
        {
            return 1;
        }

        if (hasCasual && hasFemale)
        {
            return 2;
        }

        if (hasCasual)
        {
            return 3;
        }

        if (hasMale)
        {
            return 4;
        }

        if (hasFemale)
        {
            return 5;
        }

        return 10;
    }

    private static int GetFaceVariantCategorySortPriority(string categoryName)
    {
        HashSet<string> tokens = TokenizeCategoryName(categoryName);
        bool hasDefault = tokens.Contains("default");
        bool hasCasual = tokens.Contains("casual");

        if (hasDefault)
        {
            return 0;
        }

        if (hasCasual)
        {
            return 1;
        }

        return 10;
    }

    private static HashSet<string> TokenizeCategoryName(string categoryName)
    {
        HashSet<string> tokens = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        string normalized = NormalizeCategoryName(categoryName);
        if (string.IsNullOrWhiteSpace(normalized))
        {
            return tokens;
        }

        string[] rawTokens = normalized.Split(new[] { '/', '\\', '|', '>', '-', '_', ' ' }, StringSplitOptions.RemoveEmptyEntries);
        for (int i = 0; i < rawTokens.Length; i++)
        {
            string token = rawTokens[i].Trim();
            if (token.Length == 0)
            {
                continue;
            }

            tokens.Add(token.ToLowerInvariant());
        }

        return tokens;
    }

    private static int CompareAlphabeticNatural(string left, string right)
    {
        left ??= string.Empty;
        right ??= string.Empty;

        int leftIndex = 0;
        int rightIndex = 0;
        while (leftIndex < left.Length && rightIndex < right.Length)
        {
            char leftChar = left[leftIndex];
            char rightChar = right[rightIndex];
            bool leftIsDigit = char.IsDigit(leftChar);
            bool rightIsDigit = char.IsDigit(rightChar);

            if (leftIsDigit && rightIsDigit)
            {
                int leftDigitStart = leftIndex;
                int rightDigitStart = rightIndex;
                while (leftIndex < left.Length && char.IsDigit(left[leftIndex]))
                {
                    leftIndex++;
                }

                while (rightIndex < right.Length && char.IsDigit(right[rightIndex]))
                {
                    rightIndex++;
                }

                int leftDigitEnd = leftIndex;
                int rightDigitEnd = rightIndex;
                int leftTrimmedStart = leftDigitStart;
                int rightTrimmedStart = rightDigitStart;
                while (leftTrimmedStart < leftDigitEnd - 1 && left[leftTrimmedStart] == '0')
                {
                    leftTrimmedStart++;
                }

                while (rightTrimmedStart < rightDigitEnd - 1 && right[rightTrimmedStart] == '0')
                {
                    rightTrimmedStart++;
                }

                int leftNumberLength = leftDigitEnd - leftTrimmedStart;
                int rightNumberLength = rightDigitEnd - rightTrimmedStart;
                if (leftNumberLength != rightNumberLength)
                {
                    return leftNumberLength.CompareTo(rightNumberLength);
                }

                for (int i = 0; i < leftNumberLength; i++)
                {
                    int digitCompare = left[leftTrimmedStart + i].CompareTo(right[rightTrimmedStart + i]);
                    if (digitCompare != 0)
                    {
                        return digitCompare;
                    }
                }

                int leftDigitsLength = leftDigitEnd - leftDigitStart;
                int rightDigitsLength = rightDigitEnd - rightDigitStart;
                if (leftDigitsLength != rightDigitsLength)
                {
                    return leftDigitsLength.CompareTo(rightDigitsLength);
                }

                continue;
            }

            if (leftIsDigit != rightIsDigit)
            {
                return leftIsDigit ? -1 : 1;
            }

            int leftTextStart = leftIndex;
            int rightTextStart = rightIndex;
            while (leftIndex < left.Length && !char.IsDigit(left[leftIndex]))
            {
                leftIndex++;
            }

            while (rightIndex < right.Length && !char.IsDigit(right[rightIndex]))
            {
                rightIndex++;
            }

            int leftTextLength = leftIndex - leftTextStart;
            int rightTextLength = rightIndex - rightTextStart;
            int sharedLength = Mathf.Min(leftTextLength, rightTextLength);
            for (int i = 0; i < sharedLength; i++)
            {
                char normalizedLeft = char.ToUpperInvariant(left[leftTextStart + i]);
                char normalizedRight = char.ToUpperInvariant(right[rightTextStart + i]);
                int charCompare = normalizedLeft.CompareTo(normalizedRight);
                if (charCompare != 0)
                {
                    return charCompare;
                }
            }

            if (leftTextLength != rightTextLength)
            {
                return leftTextLength.CompareTo(rightTextLength);
            }
        }

        if (leftIndex < left.Length)
        {
            return 1;
        }

        if (rightIndex < right.Length)
        {
            return -1;
        }

        return 0;
    }

    private static bool CategoryOptionExists(string value, List<string> options)
    {
        if (string.IsNullOrWhiteSpace(value) || options == null)
        {
            return false;
        }

        string normalized = NormalizeCategoryName(value);
        for (int i = 0; i < options.Count; i++)
        {
            if (string.Equals(NormalizeCategoryName(options[i]), normalized, StringComparison.OrdinalIgnoreCase))
            {
                return true;
            }
        }

        return false;
    }

    private static bool IsNonSelectableCategoryName(string categoryName)
    {
        return string.Equals(categoryName, CategoryNothingOptionLabel, StringComparison.OrdinalIgnoreCase)
               || string.Equals(categoryName, CategoryNoneOptionLabel, StringComparison.OrdinalIgnoreCase);
    }

    private void EnsureCategorySelectionState()
    {
        if (categoryDropdownSelectsRegions)
        {
            selectedVariantCategories.Clear();
            selectedCategoryDropdownIndex = Mathf.Clamp(selectedRegionIndex, 0, Mathf.Max(0, categoryDropdownOptions.Count - 1));
            return;
        }

        List<string> normalizedSelection = new List<string>();
        foreach (string selected in selectedVariantCategories)
        {
            string normalized = NormalizeCategoryName(selected);
            if (string.IsNullOrWhiteSpace(normalized)
                || !CategoryOptionExists(normalized, categoryDropdownOptions)
                || IsNonSelectableCategoryName(normalized))
            {
                continue;
            }

            if (!CategoryOptionExists(normalized, normalizedSelection))
            {
                normalizedSelection.Add(normalized);
            }
        }

        selectedVariantCategories.Clear();
        for (int i = 0; i < normalizedSelection.Count; i++)
        {
            selectedVariantCategories.Add(normalizedSelection[i]);
        }

        EnforceInfoOnlyCategorySingleSelection();

        int selectedSpecificCount = 0;
        foreach (string selected in selectedVariantCategories)
        {
            if (!IsAllCategoryName(selected) && !IsNonSelectableCategoryName(selected))
            {
                selectedSpecificCount++;
            }
        }

        bool shouldUseEverything = selectedSpecificCount == 0;

        if (shouldUseEverything)
        {
            selectedVariantCategories.Clear();
            selectedVariantCategories.Add(CategoryAllOptionLabel);
            selectedCategoryDropdownIndex = IndexOfCategoryOption(CategoryAllOptionLabel);
            return;
        }

        selectedVariantCategories.RemoveWhere(IsAllCategoryName);

        if (selectedCategoryDropdownIndex >= 0
            && selectedCategoryDropdownIndex < categoryDropdownOptions.Count
            && IsCategorySelectionActive(categoryDropdownOptions[selectedCategoryDropdownIndex]))
        {
            return;
        }

        for (int i = 0; i < categoryDropdownOptions.Count; i++)
        {
            if (IsCategorySelectionActive(categoryDropdownOptions[i]))
            {
                selectedCategoryDropdownIndex = i;
                return;
            }
        }

        selectedCategoryDropdownIndex = IndexOfCategoryOption(CategoryAllOptionLabel);
    }

    private void ToggleCategorySelection(string rawCategoryName)
    {
        if (categoryDropdownSelectsRegions)
        {
            return;
        }

        string categoryName = NormalizeCategoryName(rawCategoryName);
        if (string.IsNullOrWhiteSpace(categoryName)
            || IsNonSelectableCategoryName(categoryName))
        {
            return;
        }

        if (IsAllCategoryName(categoryName))
        {
            selectedVariantCategories.Clear();
            selectedVariantCategories.Add(CategoryAllOptionLabel);
            selectedCategoryDropdownIndex = IndexOfCategoryOption(CategoryAllOptionLabel);
            return;
        }

        selectedVariantCategories.RemoveWhere(IsAllCategoryName);
        bool wasSelected = selectedVariantCategories.Contains(categoryName);
        bool isInfoOnlyCategory = IsInfoOnlyCategoryForCurrentRegion(categoryName);

        if (wasSelected)
        {
            selectedVariantCategories.Remove(categoryName);
        }
        else if (isInfoOnlyCategory)
        {
            selectedVariantCategories.Clear();
            selectedVariantCategories.Add(categoryName);
        }
        else
        {
            selectedVariantCategories.Add(categoryName);
        }

        EnforceInfoOnlyCategorySingleSelection(categoryName);
        selectedCategoryDropdownIndex = IndexOfCategoryOption(categoryName);
        EnsureCategorySelectionState();
    }

    private void EnforceInfoOnlyCategorySingleSelection(string preferredCategoryName = null)
    {
        if (selectedVariantCategories.Count <= 1)
        {
            return;
        }

        string preferred = NormalizeCategoryName(preferredCategoryName);
        if (!string.IsNullOrWhiteSpace(preferred)
            && selectedVariantCategories.Contains(preferred)
            && IsInfoOnlyCategoryForCurrentRegion(preferred))
        {
            selectedVariantCategories.Clear();
            selectedVariantCategories.Add(preferred);
            selectedCategoryDropdownIndex = IndexOfCategoryOption(preferred);
            return;
        }

        List<string> categoriesToRemove = new List<string>();
        foreach (string selected in selectedVariantCategories)
        {
            if (IsInfoOnlyCategoryForCurrentRegion(selected))
            {
                categoriesToRemove.Add(selected);
            }
        }

        for (int i = 0; i < categoriesToRemove.Count; i++)
        {
            selectedVariantCategories.Remove(categoriesToRemove[i]);
        }
    }

    private bool IsInfoOnlyCategoryForCurrentRegion(string rawCategoryName)
    {
        string categoryName = NormalizeCategoryName(rawCategoryName);
        if (string.IsNullOrWhiteSpace(categoryName)
            || IsAllCategoryName(categoryName)
            || IsNonSelectableCategoryName(categoryName)
            || string.Equals(categoryName, CategoryDefaultOptionLabel, StringComparison.OrdinalIgnoreCase))
        {
            return false;
        }

        return !DoesSelectedCategoryHaveCurrentRegionParts(categoryName);
    }

    private int IndexOfCategoryOption(string categoryName)
    {
        string normalized = NormalizeCategoryName(categoryName);
        for (int i = 0; i < categoryDropdownOptions.Count; i++)
        {
            if (string.Equals(NormalizeCategoryName(categoryDropdownOptions[i]), normalized, StringComparison.OrdinalIgnoreCase))
            {
                return i;
            }
        }

        return 0;
    }

    private bool IsCategorySelectionActive(string rawCategoryName)
    {
        string categoryName = NormalizeCategoryName(rawCategoryName);
        return selectedVariantCategories.Contains(categoryName);
    }

    private string BuildCategoryOptionDisplayText(string rawCategoryName)
    {
        string categoryName = NormalizeCategoryName(rawCategoryName);
        return categoryName;
    }

    private string BuildCategoryToggleOptionText(string rawCategoryName)
    {
        string displayText = BuildCategoryOptionDisplayText(rawCategoryName);
        return IsCategorySelectionActive(rawCategoryName)
            ? DropdownSelectedOptionPrefix + displayText
            : displayText;
    }

    private string BuildSavedPrefabDropdownOptionText(int optionIndex)
    {
        if (optionIndex < 0 || optionIndex >= savedPrefabCategoryDropdownOptions.Count)
        {
            return string.Empty;
        }

        string displayText = savedPrefabCategoryDropdownOptions[optionIndex];
        return optionIndex == selectedSavedPrefabCategoryDropdownIndex
            ? DropdownSelectedOptionPrefix + displayText
            : displayText;
    }

    private bool TryBuildCategoryOptionsFromInfoAssets(List<string> options)
    {
        if (options == null || categoryInfoAssets == null || categoryInfoAssets.Count == 0)
        {
            return false;
        }

        List<string> themes = new List<string>();
        for (int i = 0; i < categoryInfoAssets.Count; i++)
        {
            MinimoCategoryInfo info = categoryInfoAssets[i];
            if (info == null)
            {
                continue;
            }

            string normalizedTheme = ResolveCategoryThemeFromInfoAsset(info);
            if (string.IsNullOrWhiteSpace(normalizedTheme)
                || IsAllCategoryName(normalizedTheme)
                || IsNonSelectableCategoryName(normalizedTheme)
                || string.Equals(normalizedTheme, CategoryDefaultOptionLabel, StringComparison.OrdinalIgnoreCase))
            {
                continue;
            }

            AddCategoryOptionIfMissing(themes, normalizedTheme);
        }

        if (themes.Count == 0)
        {
            return false;
        }

        themes.Sort(CompareAlphabeticNatural);
        for (int i = 0; i < themes.Count; i++)
        {
            AddCategoryOptionIfMissing(options, themes[i]);
        }

        return true;
    }

    private bool TryGetCategoryInfoForTheme(string rawTheme, out MinimoCategoryInfo info)
    {
        info = null;
        if (categoryInfoAssets == null || categoryInfoAssets.Count == 0)
        {
            return false;
        }

        string normalizedTheme = NormalizeCategoryName(rawTheme);
        if (string.IsNullOrWhiteSpace(normalizedTheme))
        {
            return false;
        }

        for (int i = 0; i < categoryInfoAssets.Count; i++)
        {
            MinimoCategoryInfo candidate = categoryInfoAssets[i];
            if (candidate == null)
            {
                continue;
            }

            string candidateTheme = ResolveCategoryThemeFromInfoAsset(candidate);
            if (string.Equals(candidateTheme, normalizedTheme, StringComparison.OrdinalIgnoreCase))
            {
                info = candidate;
                return true;
            }
        }

        return false;
    }

    private static string ResolveCategoryThemeFromInfoAsset(MinimoCategoryInfo info)
    {
        if (info == null)
        {
            return string.Empty;
        }

        return NormalizeCategoryName(info.theme);
    }

    private bool TryGetLockedCategorySelection(out string lockedCategoryTheme, out MinimoCategoryInfo categoryInfo)
    {
        lockedCategoryTheme = string.Empty;
        categoryInfo = null;
        if (!showBuyCategoryPanel)
        {
            return false;
        }

        HashSet<string> activeSpecificCategories = GetActiveSpecificCategoryFilters();
        if (activeSpecificCategories == null || activeSpecificCategories.Count != 1)
        {
            return false;
        }

        foreach (string value in activeSpecificCategories)
        {
            lockedCategoryTheme = NormalizeCategoryName(value);
            break;
        }

        if (string.IsNullOrWhiteSpace(lockedCategoryTheme)
            || string.Equals(lockedCategoryTheme, CategoryDefaultOptionLabel, StringComparison.OrdinalIgnoreCase)
            || DoesSelectedCategoryHaveCurrentRegionParts(lockedCategoryTheme))
        {
            return false;
        }

        TryGetCategoryInfoForTheme(lockedCategoryTheme, out categoryInfo);
        return true;
    }

    private bool DoesSelectedCategoryHaveCurrentRegionParts(string rawCategoryName)
    {
        string normalizedCategoryName = NormalizeCategoryName(rawCategoryName);
        if (string.IsNullOrWhiteSpace(normalizedCategoryName)
            || IsAllCategoryName(normalizedCategoryName)
            || IsNonSelectableCategoryName(normalizedCategoryName)
            || string.Equals(normalizedCategoryName, CategoryDefaultOptionLabel, StringComparison.OrdinalIgnoreCase))
        {
            return true;
        }

        if (customizer == null)
        {
            return true;
        }

        if (IsPropsRegionSelectionMode())
        {
            return DoesSelectedCategoryHaveCurrentRegionPropParts(normalizedCategoryName);
        }

        MinimoCharacterCustomizer.PartSlot[] slots = GetTargetSlotsForVariantButtonPanel();
        if (slots == null || slots.Length == 0)
        {
            return true;
        }

        int variantCount = customizer.GetVariantCount();
        for (int i = 0; i < variantCount; i++)
        {
            MinimoCharacterCustomizer.PartSlot[] targetSlots = GetVariantTargetSlotsForSelectedSlots(i, slots);
            if (targetSlots.Length == 0)
            {
                continue;
            }

            string variantCategory = NormalizeCategoryName(ResolveVariantCategoryNameForSlots(i, targetSlots));
            if (string.Equals(variantCategory, normalizedCategoryName, StringComparison.OrdinalIgnoreCase))
            {
                return true;
            }
        }

        return false;
    }

    private bool DoesSelectedCategoryHaveCurrentRegionPropParts(string normalizedCategoryName)
    {
        if (string.IsNullOrWhiteSpace(normalizedCategoryName))
        {
            return true;
        }

        List<PropVariantEntry> allEntries = BuildAllPropVariantEntries();
        for (int i = 0; i < allEntries.Count; i++)
        {
            PropVariantEntry entry = allEntries[i];
            if (entry == null)
            {
                continue;
            }

            string entryCategory = NormalizeCategoryName(entry.categoryName);
            if (string.Equals(entryCategory, normalizedCategoryName, StringComparison.OrdinalIgnoreCase))
            {
                return true;
            }
        }

        return false;
    }

    private bool IsCategoryInfoPanelVisible()
    {
        return showBuyCategoryPanel && categoryInfoPanelRoot != null && categoryInfoPanelRoot.gameObject.activeSelf;
    }

    private void UpdateCategoryInfoPanel(string lockedCategoryTheme, MinimoCategoryInfo categoryInfo)
    {
        bool shouldShow = showBuyCategoryPanel && !string.IsNullOrWhiteSpace(lockedCategoryTheme);
        if (!shouldShow)
        {
            activeLockedCategoryTheme = string.Empty;
            activeCategoryInfo = null;
            if (categoryInfoPanelRoot != null)
            {
                categoryInfoPanelRoot.gameObject.SetActive(false);
            }

            return;
        }

        if (!EnsureCategoryInfoPanel())
        {
            activeLockedCategoryTheme = string.Empty;
            activeCategoryInfo = null;
            return;
        }
        categoryInfoPanelRoot.gameObject.SetActive(true);
        categoryInfoPanelRoot.SetAsLastSibling();

        string normalizedTheme = NormalizeCategoryName(lockedCategoryTheme);
        activeLockedCategoryTheme = normalizedTheme;
        activeCategoryInfo = categoryInfo;

        string header = categoryInfo != null && !string.IsNullOrWhiteSpace(categoryInfo.headerText)
            ? categoryInfo.headerText.Trim()
            : normalizedTheme;
        string subHeader = categoryInfo != null && !string.IsNullOrWhiteSpace(categoryInfo.subHeaderText)
            ? categoryInfo.subHeaderText.Trim()
            : normalizedTheme;
        string context = categoryInfo != null && !string.IsNullOrWhiteSpace(categoryInfo.contextText)
            ? categoryInfo.contextText.Trim()
            : $"{normalizedTheme} package is currently unavailable.";
        Sprite previewSprite = categoryInfo != null ? categoryInfo.previewSprite : null;

        SetOptionalUiText(categoryInfoTitleLabel, categoryInfoTitleTmpLabel, header);
        SetOptionalUiText(categoryInfoSubHeaderLabel, categoryInfoSubHeaderTmpLabel, subHeader);
        SetOptionalUiText(categoryInfoContentLabel, categoryInfoContentTmpLabel, context);
        SetOptionalUiText(categoryInfoBuyButtonLabel, categoryInfoBuyButtonTmpLabel, "Buy");

        if (categoryInfoPreviewImage != null)
        {
            categoryInfoPreviewImage.sprite = previewSprite;
            categoryInfoPreviewImage.color = previewSprite != null
                ? Color.white
                : new Color(0.17f, 0.17f, 0.17f, 0.25f);
        }
    }

    private static string ResolveCategoryInfoBuyUrl(MinimoCategoryInfo categoryInfo)
    {
        if (categoryInfo != null && !string.IsNullOrWhiteSpace(categoryInfo.link))
        {
            return categoryInfo.link.Trim();
        }

        return CategoryInfoBuyUrl;
    }

    private void ResolveCategoryInfoPanelSceneReferences()
    {
        if (categoryInfoPanelRoot == null)
        {
            categoryInfoPanelRoot = FindChildByName<RectTransform>("CategoryInfoPanel");
            categoryInfoPanelRoot ??= FindChildByName<RectTransform>("CategoryLockedPanel");
            categoryInfoPanelRoot ??= FindChildByName<RectTransform>("CategoryPackagePanel");
            categoryInfoPanelRoot ??= FindChildByName<RectTransform>("BuyCategoryPanel");
        }

        if (categoryInfoPanelRoot == null)
        {
            return;
        }

        categoryInfoTitleLabel ??= FindChildByNameIn<Text>(categoryInfoPanelRoot, "Header");
        categoryInfoTitleLabel ??= FindChildByNameIn<Text>(categoryInfoPanelRoot, "Title");
        categoryInfoTitleTmpLabel ??= FindChildByNameIn<TMP_Text>(categoryInfoPanelRoot, "Header");
        categoryInfoTitleTmpLabel ??= FindChildByNameIn<TMP_Text>(categoryInfoPanelRoot, "Title");

        categoryInfoSubHeaderLabel ??= FindChildByNameIn<Text>(categoryInfoPanelRoot, "SubHeader");
        categoryInfoSubHeaderLabel ??= FindChildByNameIn<Text>(categoryInfoPanelRoot, "Subtitle");
        categoryInfoSubHeaderTmpLabel ??= FindChildByNameIn<TMP_Text>(categoryInfoPanelRoot, "SubHeader");
        categoryInfoSubHeaderTmpLabel ??= FindChildByNameIn<TMP_Text>(categoryInfoPanelRoot, "Subtitle");

        categoryInfoPreviewImage ??= FindChildByNameIn<Image>(categoryInfoPanelRoot, "Preview");
        categoryInfoPreviewImage ??= FindChildByNameIn<Image>(categoryInfoPanelRoot, "Image");
        categoryInfoPreviewImage ??= FindChildByNameIn<Image>(categoryInfoPanelRoot, "Sprite");

        categoryInfoContentLabel ??= FindChildByNameIn<Text>(categoryInfoPanelRoot, "Context");
        categoryInfoContentLabel ??= FindChildByNameIn<Text>(categoryInfoPanelRoot, "Content");
        categoryInfoContentLabel ??= FindChildByNameIn<Text>(categoryInfoPanelRoot, "Description");
        categoryInfoContentTmpLabel ??= FindChildByNameIn<TMP_Text>(categoryInfoPanelRoot, "Context");
        categoryInfoContentTmpLabel ??= FindChildByNameIn<TMP_Text>(categoryInfoPanelRoot, "Content");
        categoryInfoContentTmpLabel ??= FindChildByNameIn<TMP_Text>(categoryInfoPanelRoot, "Description");

        categoryInfoBuyButton ??= FindFirstButtonByNamesIn(
            categoryInfoPanelRoot,
            "BuyButton",
            "PurchaseButton",
            "SatinAlButton",
            "SatinAl",
            "Buy");

        if (categoryInfoBuyButton != null)
        {
            categoryInfoBuyButtonLabel ??= FindChildByNameIn<Text>(categoryInfoBuyButton.transform, "Label");
            categoryInfoBuyButtonLabel ??= categoryInfoBuyButton.GetComponentInChildren<Text>(true);
            categoryInfoBuyButtonTmpLabel ??= FindChildByNameIn<TMP_Text>(categoryInfoBuyButton.transform, "Label");
            categoryInfoBuyButtonTmpLabel ??= categoryInfoBuyButton.GetComponentInChildren<TMP_Text>(true);
        }
    }

    private bool EnsureCategoryInfoPanel()
    {
        ResolveCategoryInfoPanelSceneReferences();
        if (categoryInfoPanelRoot == null)
        {
            return false;
        }

        if (categoryInfoBuyButton != null)
        {
            categoryInfoBuyButton.onClick.RemoveListener(HandleCategoryInfoBuyButtonClicked);
            categoryInfoBuyButton.onClick.AddListener(HandleCategoryInfoBuyButtonClicked);
            EnsureShadowPressTracking(categoryInfoBuyButton, allowWithoutShadowTarget: true);
        }

        SetOptionalUiText(categoryInfoBuyButtonLabel, categoryInfoBuyButtonTmpLabel, "Buy");
        return true;
    }

    private void CreateCategoryInfoPanelRuntime()
    {
        RectTransform parent = ResolveCategoryInfoPanelParent();
        if (parent == null)
        {
            return;
        }

        Font font = ResolveFont();
        categoryInfoPanelRoot = CreateRect(
            "CategoryInfoPanel",
            parent,
            Vector2.zero,
            Vector2.one,
            new Vector2(0.5f, 0.5f),
            Vector2.zero,
            Vector2.zero);
        categoryInfoPanelRoot.offsetMin = Vector2.zero;
        categoryInfoPanelRoot.offsetMax = Vector2.zero;
        categoryInfoPanelCreatedByScript = true;

        Image background = categoryInfoPanelRoot.gameObject.AddComponent<Image>();
        background.color = new Color(0.86f, 0.85f, 0.82f, 0.96f);

        RectTransform titleRect = CreateRect(
            "Title",
            categoryInfoPanelRoot,
            new Vector2(0f, 1f),
            new Vector2(1f, 1f),
            new Vector2(0.5f, 1f),
            new Vector2(0f, 48f),
            new Vector2(0f, -10f));
        categoryInfoTitleLabel = titleRect.gameObject.AddComponent<Text>();
