    private RectTransform ResolveCategoryInfoPanelParent()
    {
        if (bodyPartsScroll != null && bodyPartsScroll.viewport != null)
        {
            return bodyPartsScroll.viewport;
        }

        if (bodyPartsScroll != null)
        {
            return bodyPartsScroll.transform as RectTransform;
        }

        if (bodyPartsContent != null && bodyPartsContent.parent is RectTransform contentParent)
        {
            return contentParent;
        }

        if (partsPanelRoot != null)
        {
            return partsPanelRoot;
        }

        return transform as RectTransform;
    }

