#if UNITY_EDITOR
    private void RefreshCategoryInfoAssetsFromProject()
    {
        List<MinimoCategoryInfo> discovered = new List<MinimoCategoryInfo>();
        CollectCategoryInfoAssetsFromFolder(CategoryInfoFolderDefault, discovered);

        categoryInfoAssets.Clear();
        for (int i = 0; i < discovered.Count; i++)
        {
            MinimoCategoryInfo info = discovered[i];
            if (info != null)
            {
                categoryInfoAssets.Add(info);
            }
        }
    }

    private static void CollectCategoryInfoAssetsFromFolder(string folderPath, List<MinimoCategoryInfo> destination)
    {
        if (destination == null || string.IsNullOrWhiteSpace(folderPath))
        {
            return;
        }

        string normalizedFolderPath = folderPath.Replace('\\', '/').TrimEnd('/');
        if (!AssetDatabase.IsValidFolder(normalizedFolderPath))
        {
            return;
        }

        string[] assetGuids = AssetDatabase.FindAssets("t:MinimoCategoryInfo", new[] { normalizedFolderPath });
        for (int i = 0; i < assetGuids.Length; i++)
        {
            string assetPath = AssetDatabase.GUIDToAssetPath(assetGuids[i]);
            MinimoCategoryInfo info = AssetDatabase.LoadAssetAtPath<MinimoCategoryInfo>(assetPath);
            if (info != null && !destination.Contains(info))
            {
                destination.Add(info);
            }
        }
    }
#endif

    private List<int> GetFilteredVariantIndicesForCurrentCategory(MinimoCharacterCustomizer.PartSlot[] slotOverride = null)
    {
        List<int> indices = new List<int>();
        if (customizer == null)
        {
            return indices;
        }

        int variantCount = customizer.GetVariantCount();
        if (variantCount <= 0)
        {
            return indices;
        }

        MinimoCharacterCustomizer.PartSlot[] slots = slotOverride ?? GetTargetSlotsForVariantButtonPanel();
        if (slots == null || slots.Length == 0)
        {
            for (int i = 0; i < variantCount; i++)
            {
                indices.Add(i);
            }

            return indices;
        }

        HashSet<string> selectedCategories = GetActiveSpecificCategoryFilters();
        for (int i = 0; i < variantCount; i++)
        {
            MinimoCharacterCustomizer.PartSlot[] targetSlots = GetVariantTargetSlotsForSelectedSlots(i, slots);
            if (targetSlots.Length == 0)
            {
                continue;
            }

            if (!MatchesSelectedCategory(i, targetSlots, selectedCategories))
            {
                continue;
            }

            indices.Add(i);
        }

        return indices;
    }

    private bool DoesVariantExistForSlot(
        int variantIndex,
        MinimoCharacterCustomizer.PartSlot slot)
    {
        if (customizer == null || variantIndex < 0)
        {
            return false;
        }

        if (customizer.TryGetVariantPartPreviewData(
                variantIndex,
                slot,
                out _,
                out _,
                out _,
                out _))
        {
            return true;
        }

        return customizer.TryGetVariantSourcePrefabForSlot(slot, variantIndex, out GameObject sourcePrefab)
               && sourcePrefab != null;
    }

    private MinimoCharacterCustomizer.PartSlot[] GetVariantTargetSlotsForSelectedSlots(
        int variantIndex,
        MinimoCharacterCustomizer.PartSlot[] selectedSlots)
    {
        if (variantIndex < 0 || selectedSlots == null || selectedSlots.Length == 0)
        {
            return Array.Empty<MinimoCharacterCustomizer.PartSlot>();
        }

        List<MinimoCharacterCustomizer.PartSlot> targets = new List<MinimoCharacterCustomizer.PartSlot>();
        for (int i = 0; i < selectedSlots.Length; i++)
        {
            MinimoCharacterCustomizer.PartSlot slot = selectedSlots[i];
            if (DoesVariantExistForSlot(variantIndex, slot) && !targets.Contains(slot))
            {
                targets.Add(slot);
            }
        }

        return targets.Count > 0 ? targets.ToArray() : Array.Empty<MinimoCharacterCustomizer.PartSlot>();
    }

    private void ToggleCustomColorPicker()
    {
        if (!EnsureCustomColorPicker())
        {
            return;
        }

        bool nextState = !runtimeColorPickerRoot.gameObject.activeSelf;
        SetCustomColorPickerVisible(nextState);
        if (nextState)
        {
            BringRuntimeColorPickerToFront();
            SyncCustomColorPickerFromSelection();
        }
    }

    private void SetCustomColorPickerVisible(bool visible)
    {
        if (runtimeColorPickerRoot == null)
        {
            return;
        }

        runtimeColorPickerRoot.gameObject.SetActive(visible);
        if (visible)
        {
            BringRuntimeColorPickerToFront();
        }
        else
        {
            gamepadColorPickerWheelAxis = Vector2.zero;
        }
    }

    private void BringRuntimeColorPickerToFront()
    {
        if (runtimeColorPickerRoot == null)
        {
            return;
        }

        Canvas canvas = runtimeColorPickerRoot.GetComponentInParent<Canvas>();
        RectTransform canvasRect = canvas != null ? canvas.transform as RectTransform : null;
        if (runtimeColorPickerCreatedByScript
            && canvasRect != null
            && runtimeColorPickerRoot.parent != canvasRect)
        {
            runtimeColorPickerRoot.SetParent(canvasRect, true);
        }

        runtimeColorPickerRoot.SetAsLastSibling();
    }

    private void HandleRuntimeColorPickerCloseButton()
    {
        SetCustomColorPickerVisible(false);
    }

    private bool EnsureCustomColorPicker()
    {
        ResolveRuntimeColorPickerSceneReferences();

        Font font = ResolveFont();
        if (runtimeColorPickerRoot == null)
        {
            return false;
        }

        runtimeColorPickerCreatedByScript = false;
        return EnsureRuntimeColorPickerControls(font);
    }

    private void ResolveRuntimeColorPickerSceneReferences()
    {
        if (runtimeColorPickerRoot == null)
        {
            runtimeColorPickerRoot = FindChildByName<RectTransform>("RuntimeCustomColorPicker");
            runtimeColorPickerRoot ??= FindChildByName<RectTransform>("CustomColorPicker");
            runtimeColorPickerRoot ??= FindChildByName<RectTransform>("RuntimeColorPicker");
            runtimeColorPickerRoot ??= FindChildByName<RectTransform>("ColorPickerPopup");
            if (runtimeColorPickerRoot != null)
            {
                runtimeColorPickerCreatedByScript = false;
            }
        }

        if (runtimeColorPickerRoot == null)
        {
            return;
        }

        runtimeColorPreviewImage ??= FindChildByNameIn<Image>(runtimeColorPickerRoot, "Preview");
        runtimeColorPreviewImage ??= FindChildByNameIn<Image>(runtimeColorPickerRoot, "PreviewImage");
        runtimeColorPreviewImage ??= FindChildByNameIn<Image>(runtimeColorPickerRoot, "ColorPreview");

        runtimeColorPickerCloseButton ??= FindFirstButtonByNamesIn(
            runtimeColorPickerRoot,
            "CloseButton",
            "Close",
            "BtnClose",
            "ButtonClose");

        runtimeColorWheelRect ??= FindChildByNameIn<RectTransform>(runtimeColorPickerRoot, "Wheel");
        runtimeColorWheelRect ??= FindChildByNameIn<RectTransform>(runtimeColorPickerRoot, "ColorWheel");
        runtimeColorWheelRect ??= FindChildByNameIn<RectTransform>(runtimeColorPickerRoot, "WheelArea");
        if (runtimeColorWheelRect != null)
        {
            runtimeColorWheelImage ??= runtimeColorWheelRect.GetComponent<RawImage>();
            runtimeColorWheelImage ??= runtimeColorWheelRect.GetComponentInChildren<RawImage>(true);
            runtimeColorWheelIndicator ??= FindChildByNameIn<RectTransform>(runtimeColorWheelRect, "WheelIndicator");
            runtimeColorWheelIndicator ??= FindChildByNameIn<RectTransform>(runtimeColorWheelRect, "Indicator");
            runtimeColorWheelIndicatorImage ??= runtimeColorWheelIndicator != null
                ? runtimeColorWheelIndicator.GetComponent<Image>()
                : null;
        }

        runtimeHueSlider ??= FindFirstSliderByNamesIn(runtimeColorPickerRoot, "H_Slider", "HueSlider", "RuntimeHueSlider", "RuntimeColorRow_H", "Hue", "H");
        runtimeSaturationSlider ??= FindFirstSliderByNamesIn(runtimeColorPickerRoot, "S_Slider", "SaturationSlider", "RuntimeSaturationSlider", "RuntimeColorRow_S", "Saturation", "S");
        runtimeValueSlider ??= FindFirstSliderByNamesIn(runtimeColorPickerRoot, "V_Slider", "ValueSlider", "RuntimeValueSlider", "RuntimeColorRow_V", "Value", "V");

        if (runtimeHueSlider == null || runtimeSaturationSlider == null || runtimeValueSlider == null)
        {
            Slider[] sliders = runtimeColorPickerRoot.GetComponentsInChildren<Slider>(true);
            if (sliders.Length > 0)
            {
                runtimeHueSlider ??= sliders[0];
            }

            if (sliders.Length > 1)
            {
                runtimeSaturationSlider ??= sliders[1];
            }

            if (sliders.Length > 2)
            {
                runtimeValueSlider ??= sliders[2];
            }
        }
    }

    private static Slider FindFirstSliderByNamesIn(Transform root, params string[] names)
    {
        if (root == null || names == null || names.Length == 0)
        {
            return null;
        }

        for (int i = 0; i < names.Length; i++)
        {
            string name = names[i];
            if (string.IsNullOrWhiteSpace(name))
            {
                continue;
            }

            Slider byName = FindChildByNameIn<Slider>(root, name);
            if (byName != null)
            {
                return byName;
            }

            RectTransform row = FindChildByNameIn<RectTransform>(root, name);
            if (row != null)
            {
                Slider byRow = row.GetComponentInChildren<Slider>(true);
                if (byRow != null)
                {
                    return byRow;
                }
            }
        }

        return null;
    }

    private bool EnsureRuntimeColorPickerControls(Font font)
    {
        if (runtimeColorPickerRoot == null)
        {
            return false;
        }

        runtimeColorPreviewImage ??= FindChildByNameIn<Image>(runtimeColorPickerRoot, "Preview");
        runtimeColorPreviewImage ??= FindChildByNameIn<Image>(runtimeColorPickerRoot, "ColorPreview");
        if (runtimeColorPreviewImage == null && runtimeColorPickerCreatedByScript)
        {
            RectTransform previewRect = CreateRect(
                "Preview",
                runtimeColorPickerRoot,
                new Vector2(1f, 1f),
                new Vector2(1f, 1f),
                new Vector2(1f, 1f),
                new Vector2(30f, 20f),
                new Vector2(-8f, -9f));
            runtimeColorPreviewImage = previewRect.gameObject.AddComponent<Image>();
            runtimeColorPreviewImage.color = Color.white;
        }

        runtimeColorPickerCloseButton ??= FindFirstButtonByNamesIn(
            runtimeColorPickerRoot,
            "CloseButton",
            "Close",
            "BtnClose",
            "ButtonClose");
        if (runtimeColorPickerCloseButton == null && runtimeColorPickerCreatedByScript)
        {
            RectTransform closeRect = CreateRect(
                "Close",
                runtimeColorPickerRoot,
                new Vector2(1f, 0f),
                new Vector2(1f, 0f),
                new Vector2(1f, 0f),
                new Vector2(52f, 24f),
                new Vector2(-8f, 8f));
            Image closeImage = closeRect.gameObject.AddComponent<Image>();
            closeImage.color = UiButtonNeutralColor;
            runtimeColorPickerCloseButton = closeRect.gameObject.AddComponent<Button>();
            runtimeColorPickerCloseButton.targetGraphic = closeImage;
            ApplyButtonInteractionStyle(runtimeColorPickerCloseButton, UiButtonNeutralColor);

            Text closeLabel = CreateRowText("Label", closeRect, font, 12, TextAnchor.MiddleCenter, new Color(0.95f, 0.95f, 0.95f, 1f));
            closeLabel.text = "Close";
            closeLabel.rectTransform.anchorMin = Vector2.zero;
            closeLabel.rectTransform.anchorMax = Vector2.one;
            closeLabel.rectTransform.offsetMin = Vector2.zero;
            closeLabel.rectTransform.offsetMax = Vector2.zero;
        }

        if (runtimeColorPickerCloseButton != null)
        {
            runtimeColorPickerCloseButton.onClick.RemoveListener(HandleRuntimeColorPickerCloseButton);
            runtimeColorPickerCloseButton.onClick.AddListener(HandleRuntimeColorPickerCloseButton);
            EnsureShadowPressTracking(runtimeColorPickerCloseButton, allowWithoutShadowTarget: true);
        }

        runtimeColorWheelRect ??= FindChildByNameIn<RectTransform>(runtimeColorPickerRoot, "Wheel");
        if (runtimeColorWheelRect == null && runtimeColorPickerCreatedByScript)
        {
            runtimeColorWheelRect = CreateRect(
                "Wheel",
                runtimeColorPickerRoot,
                new Vector2(0.5f, 1f),
                new Vector2(0.5f, 1f),
                new Vector2(0.5f, 0.5f),
                new Vector2(162f, 162f),
                new Vector2(0f, -108f));
        }

        if (runtimeColorWheelRect != null)
        {
            runtimeColorWheelImage ??= runtimeColorWheelRect.GetComponent<RawImage>();
            runtimeColorWheelImage ??= runtimeColorWheelRect.GetComponentInChildren<RawImage>(true);
            if (runtimeColorWheelImage == null && runtimeColorPickerCreatedByScript)
            {
                runtimeColorWheelImage = runtimeColorWheelRect.gameObject.AddComponent<RawImage>();
            }

            if (runtimeColorWheelImage != null && runtimeColorWheelImage.texture == null)
            {
                runtimeColorWheelTexture ??= BuildRuntimeColorWheelTexture(256);
                runtimeColorWheelImage.texture = runtimeColorWheelTexture;
            }

            if (runtimeColorWheelImage != null)
            {
                runtimeColorWheelImage.raycastTarget = true;
            }

            RuntimeColorWheelInput wheelInput = runtimeColorWheelRect.GetComponent<RuntimeColorWheelInput>();
            if (wheelInput == null)
            {
                wheelInput = runtimeColorWheelRect.gameObject.AddComponent<RuntimeColorWheelInput>();
            }

            wheelInput.wheelRect = runtimeColorWheelRect;
            wheelInput.onPointerLocal = HandleCustomColorWheelLocalPoint;

            runtimeColorWheelIndicator ??= FindChildByNameIn<RectTransform>(runtimeColorWheelRect, "WheelIndicator");
            runtimeColorWheelIndicator ??= FindChildByNameIn<RectTransform>(runtimeColorWheelRect, "Indicator");
            if (runtimeColorWheelIndicator != null)
            {
                runtimeColorWheelIndicatorImage = runtimeColorWheelIndicator.GetComponent<Image>();
                if (runtimeColorWheelIndicatorImage != null)
                {
                    runtimeColorWheelIndicatorImage.color = Color.white;
                    runtimeColorWheelIndicatorImage.raycastTarget = false;
                }
            }
        }

        runtimeHueSlider ??= FindFirstSliderByNamesIn(runtimeColorPickerRoot, "H_Slider", "HueSlider", "RuntimeHueSlider", "RuntimeColorRow_H", "Hue", "H");
        runtimeSaturationSlider ??= FindFirstSliderByNamesIn(runtimeColorPickerRoot, "S_Slider", "SaturationSlider", "RuntimeSaturationSlider", "RuntimeColorRow_S", "Saturation", "S");
        runtimeValueSlider ??= FindFirstSliderByNamesIn(runtimeColorPickerRoot, "V_Slider", "ValueSlider", "RuntimeValueSlider", "RuntimeColorRow_V", "Value", "V");

        if (runtimeColorPickerCreatedByScript)
        {
            runtimeHueSlider ??= CreateCustomColorSlider("H", runtimeColorPickerRoot, font, -208f, new Color(0.95f, 0.42f, 0.42f, 1f));
            runtimeSaturationSlider ??= CreateCustomColorSlider("S", runtimeColorPickerRoot, font, -242f, new Color(0.52f, 0.82f, 0.5f, 1f));
            runtimeValueSlider ??= CreateCustomColorSlider("V", runtimeColorPickerRoot, font, -276f, new Color(0.56f, 0.72f, 0.95f, 1f));
        }

        if (runtimeHueSlider == null || runtimeSaturationSlider == null || runtimeValueSlider == null)
        {
            return false;
        }

        ConfigureRuntimeColorSlider(runtimeHueSlider);
        ConfigureRuntimeColorSlider(runtimeSaturationSlider);
        ConfigureRuntimeColorSlider(runtimeValueSlider);

        runtimeHueSlider.onValueChanged.RemoveListener(HandleCustomColorSliderChanged);
        runtimeSaturationSlider.onValueChanged.RemoveListener(HandleCustomColorSliderChanged);
        runtimeValueSlider.onValueChanged.RemoveListener(HandleCustomColorSliderChanged);
        runtimeHueSlider.onValueChanged.AddListener(HandleCustomColorSliderChanged);
        runtimeSaturationSlider.onValueChanged.AddListener(HandleCustomColorSliderChanged);
        runtimeValueSlider.onValueChanged.AddListener(HandleCustomColorSliderChanged);

        return runtimeColorWheelRect != null
               && runtimeColorWheelImage != null
               && runtimeHueSlider != null
               && runtimeSaturationSlider != null
               && runtimeValueSlider != null;
    }

    private static void ConfigureRuntimeColorSlider(Slider slider)
    {
        if (slider == null)
        {
            return;
        }

        slider.minValue = 0f;
        slider.maxValue = 1f;
        slider.wholeNumbers = false;
        slider.direction = Slider.Direction.LeftToRight;
    }

    private static Texture2D BuildRuntimeColorWheelTexture(int size)
    {
        int wheelSize = Mathf.Max(64, size);
        Texture2D texture = new Texture2D(wheelSize, wheelSize, TextureFormat.RGBA32, false);
        texture.name = "RuntimeColorWheel";
        texture.wrapMode = TextureWrapMode.Clamp;
        texture.filterMode = FilterMode.Bilinear;

        float radius = (wheelSize - 1) * 0.5f;
        Vector2 center = new Vector2(radius, radius);
        for (int y = 0; y < wheelSize; y++)
        {
            for (int x = 0; x < wheelSize; x++)
            {
                Vector2 point = new Vector2(x + 0.5f, y + 0.5f) - center;
                float distance01 = point.magnitude / radius;
                if (distance01 > 1f)
                {
                    texture.SetPixel(x, y, new Color(0f, 0f, 0f, 0f));
                    continue;
                }

                float hue = Mathf.Atan2(point.y, point.x) / (Mathf.PI * 2f);
                if (hue < 0f)
                {
                    hue += 1f;
                }

                Color wheelColor = Color.HSVToRGB(hue, Mathf.Clamp01(distance01), 1f);
                wheelColor.a = 1f;
                texture.SetPixel(x, y, wheelColor);
            }
        }

        texture.Apply(false, false);
        return texture;
    }

    private Slider CreateCustomColorSlider(string label, RectTransform parent, Font font, float topOffset, Color fillColor)
    {
        RectTransform row = CreateRect(
            $"RuntimeColorRow_{label}",
            parent,
            new Vector2(0f, 1f),
            new Vector2(1f, 1f),
            new Vector2(0.5f, 1f),
            new Vector2(-14f, 28f),
            new Vector2(0f, topOffset));

        Text rowLabel = CreateRowText("Label", row, font, 13, TextAnchor.MiddleLeft, new Color(0.9f, 0.94f, 0.99f, 1f));
        rowLabel.text = label;
        rowLabel.rectTransform.anchorMin = new Vector2(0f, 0f);
        rowLabel.rectTransform.anchorMax = new Vector2(0f, 1f);
        rowLabel.rectTransform.pivot = new Vector2(0f, 0.5f);
        rowLabel.rectTransform.sizeDelta = new Vector2(24f, 0f);
        rowLabel.rectTransform.anchoredPosition = new Vector2(2f, 0f);

        RectTransform sliderRect = CreateRect(
            "Slider",
            row,
            new Vector2(0f, 0.5f),
            new Vector2(1f, 0.5f),
            new Vector2(0.5f, 0.5f),
            new Vector2(-36f, 14f),
            new Vector2(10f, 0f));

        Image sliderBackground = sliderRect.gameObject.AddComponent<Image>();
        sliderBackground.color = UiSurfaceSecondaryColor;
        ApplyRoundedImage(sliderBackground);
        EnsureFixedOutline(sliderBackground);

        Slider slider = sliderRect.gameObject.AddComponent<Slider>();
        slider.minValue = 0f;
        slider.maxValue = 1f;
        slider.wholeNumbers = false;
        slider.direction = Slider.Direction.LeftToRight;

        RectTransform fillArea = CreateRect(
            "Fill Area",
            sliderRect,
            new Vector2(0f, 0f),
            new Vector2(1f, 1f),
            new Vector2(0.5f, 0.5f),
            Vector2.zero,
            Vector2.zero);
        fillArea.offsetMin = new Vector2(5f, 4f);
        fillArea.offsetMax = new Vector2(-5f, -4f);

        RectTransform fill = CreateRect(
            "Fill",
            fillArea,
            new Vector2(0f, 0f),
            new Vector2(1f, 1f),
            new Vector2(0f, 0.5f),
            Vector2.zero,
            Vector2.zero);
        Image fillImage = fill.gameObject.AddComponent<Image>();
        fillImage.color = fillColor;

        RectTransform handleArea = CreateRect(
            "Handle Slide Area",
            sliderRect,
            Vector2.zero,
            Vector2.one,
            new Vector2(0.5f, 0.5f),
            Vector2.zero,
            Vector2.zero);

        RectTransform handle = CreateRect(
            "Handle",
            handleArea,
            new Vector2(0.5f, 0.5f),
            new Vector2(0.5f, 0.5f),
            new Vector2(0.5f, 0.5f),
            new Vector2(12f, 16f),
            Vector2.zero);
        Image handleImage = handle.gameObject.AddComponent<Image>();
        handleImage.color = new Color(0.96f, 0.96f, 0.96f, 1f);
        ApplyRoundedImage(handleImage);
        EnsureFixedOutline(handleImage);

        slider.fillRect = fill;
        slider.handleRect = handle;
        slider.targetGraphic = handleImage;
        return slider;
    }

    private void SyncCustomColorPickerFromSelection()
    {
        if (runtimeColorPickerRoot == null || runtimeHueSlider == null || runtimeSaturationSlider == null || runtimeValueSlider == null)
        {
            return;
        }

        Color sourceColor = Color.white;
        bool hasSourceColor = selectedColorChannelTarget != ColorChannelTargetType.Material
            ? TryGetSelectedFaceChannelColor(out sourceColor)
            : TryGetCurrentSelectionAnchorColor(out sourceColor);
        if (!hasSourceColor)
        {
            Color[] palette = GetActivePaletteColors();
            if (palette != null && palette.Length > 0)
            {
                sourceColor = palette[0];
            }
        }

        Color.RGBToHSV(sourceColor, out float h, out float s, out float v);
        SetCustomColorFromHSV(h, s, v, false);
    }

    private void HandleCustomColorSliderChanged(float _)
    {
        if (suppressRuntimeColorSliderEvents || runtimeHueSlider == null || runtimeSaturationSlider == null || runtimeValueSlider == null)
        {
            return;
        }

        SetCustomColorFromHSV(runtimeHueSlider.value, runtimeSaturationSlider.value, runtimeValueSlider.value, true);
    }

    private void HandleCustomColorWheelLocalPoint(Vector2 localPoint)
    {
        if (runtimeColorWheelRect == null || runtimeValueSlider == null)
        {
            return;
        }

        float radius = Mathf.Min(runtimeColorWheelRect.rect.width, runtimeColorWheelRect.rect.height) * 0.5f;
        if (radius <= 0.0001f)
        {
            return;
        }

        Vector2 normalized = localPoint / radius;
        float magnitude = normalized.magnitude;
        if (magnitude > 1f)
        {
            normalized /= magnitude;
        }

        float saturation = Mathf.Clamp01(normalized.magnitude);
        float hue = Mathf.Atan2(normalized.y, normalized.x) / (Mathf.PI * 2f);
        if (hue < 0f)
        {
            hue += 1f;
        }

        SetCustomColorFromHSV(hue, saturation, runtimeValueSlider.value, true);
    }

    private void SetCustomColorFromHSV(float hue, float saturation, float value, bool applyToSelection)
    {
        if (runtimeHueSlider == null || runtimeSaturationSlider == null || runtimeValueSlider == null)
        {
            return;
        }

        float h = Mathf.Repeat(hue, 1f);
        float s = Mathf.Clamp01(saturation);
        float v = Mathf.Clamp01(value);

        suppressRuntimeColorSliderEvents = true;
        runtimeHueSlider.SetValueWithoutNotify(h);
        runtimeSaturationSlider.SetValueWithoutNotify(s);
        runtimeValueSlider.SetValueWithoutNotify(v);
        suppressRuntimeColorSliderEvents = false;

        UpdateCustomColorWheelIndicator(h, s);
        Color selectedColor = Color.HSVToRGB(h, s, v);
        UpdateCustomColorPreview(selectedColor);
        if (applyToSelection && livePreviewCustomColor)
        {
            ApplyColorToSelectedRegion(selectedColor);
        }
    }

    private void UpdateCustomColorWheelIndicator(float hue, float saturation)
    {
        if (runtimeColorWheelRect == null || runtimeColorWheelIndicator == null)
        {
            return;
        }

        float radius = Mathf.Min(runtimeColorWheelRect.rect.width, runtimeColorWheelRect.rect.height) * 0.5f;
        float angle = hue * Mathf.PI * 2f;
        Vector2 direction = new Vector2(Mathf.Cos(angle), Mathf.Sin(angle));
        runtimeColorWheelIndicator.anchoredPosition = direction * (Mathf.Clamp01(saturation) * radius);
    }

    private void UpdateCustomColorPreview(Color color)
    {
        if (runtimeColorPreviewImage != null)
        {
            runtimeColorPreviewImage.color = color;
        }

        if (runtimeColorWheelIndicatorImage != null)
        {
            runtimeColorWheelIndicatorImage.color = color;
        }
    }

