    private void ChangeSlotVariant(MinimoCharacterCustomizer.PartSlot slot, int step)
    {
        if (customizer == null)
        {
            return;
        }

        int variantCount = customizer.GetVariantCount();
        if (variantCount <= 0)
        {
            return;
        }

        int currentVariant = customizer.GetPartVariant(slot);
        int nextVariant = NextVariantIndexIncludingDefault(currentVariant, step, variantCount);
        bool hadSkinTone = TryGetCurrentSkinToneColor(out Color currentSkinTone);
        bool preserveSkinLinkedColorSelection = TryCaptureSkinLinkedColorSelectionForVariantChange(
            out Color preservedSkinLinkedColor,
            out MinimoCharacterCustomizer.PartSlot? preservedSkinLinkedAnchorSlot);
        RecordUndoSnapshotIfNeeded();
        MinimoCharacterCustomizer.PartSlot[] targetSlots = { slot };
        List<RendererStateSnapshot> protectedRendererState = CaptureRendererStateForFaceHairIsolation(targetSlots);
        customizer.SetPartVariant(slot, nextVariant);
        customizer.ApplyPartSelection(slot);
        RestoreRendererStateSnapshots(protectedRendererState);
        if (hadSkinTone && !preserveSkinLinkedColorSelection)
        {
            ReapplySkinToneToCharacter(
                currentSkinTone,
                includeFace: slot != MinimoCharacterCustomizer.PartSlot.Face,
                targetSlots: targetSlots);
        }
        currentSetIndex = -1;
        RebuildWorldLinkedTargetsAfterVariantChange(
            selectedColorMaterialIndex,
            preserveSkinLinkedColorSelection,
            preservedSkinLinkedColor,
            preservedSkinLinkedAnchorSlot,
            targetSlots,
            includeFace: slot != MinimoCharacterCustomizer.PartSlot.Face);
        RefreshAfterVariantApplication(targetSlots);
    }

    private static int NextVariantIndexIncludingDefault(int currentVariant, int step, int variantCount)
    {
        int total = variantCount + 1; // default + variants
        int currentPos = Mathf.Clamp(currentVariant + 1, 0, total - 1);
        int nextPos = (currentPos + step) % total;
        if (nextPos < 0)
        {
            nextPos += total;
        }

        return nextPos - 1;
    }

    private int NextWrappedIndex(int current, int step, int count)
    {
        if (count <= 0)
        {
            return 0;
        }

        if (!wrapSelection)
        {
            return Mathf.Clamp(current + step, 0, count - 1);
        }

        int value = (current + step) % count;
        return value < 0 ? value + count : value;
    }

    private void UpdateRow(SlotRow row)
    {
        if (row == null || customizer == null)
        {
            return;
        }

        if (row.slotLabel != null)
        {
            row.slotLabel.text = customizer.GetSlotDisplayName(row.slot);
        }

        if (row.variantLabel != null)
        {
            int variant = customizer.GetPartVariant(row.slot);
            if (variant >= 0)
            {
                row.variantLabel.text = customizer.GetVariantDisplayName(variant);
            }
            else
            {
                row.variantLabel.text = customizer.HasDefaultRendererForSlot(row.slot) ? "Default" : "None";
            }
        }
    }

