    private void UpdateVariantButtonVisuals()
    {
        if (customizer == null || selectedRegionIndex < 0 || selectedRegionIndex >= regions.Count)
        {
            return;
        }

        bool propsMode = IsPropsRegionSelectionMode();
        MinimoCharacterCustomizer.PartSlot[] selectedSlots = propsMode
            ? GetTargetSlotsForSelectedRegion()
            : GetTargetSlotsForVariantButtonPanel();
        int? selectedRegionVariant = ResolveSelectedRegionVariantForVariantButtons(selectedSlots);
        bool defaultHairSelectionActive = IsDefaultHairButtonSelectionActive(selectedSlots);
        Color selectedOutlineColor = SelectedPartOutlineColor;
        Button focusedVariantButton = ResolveFocusedVariantButtonForGamepad();

        for (int i = 0; i < variantButtons.Count; i++)
        {
            VariantButtonEntry entry = variantButtons[i];
            if (entry?.button == null || entry.isRandomButton)
            {
                continue;
            }

            Image background = entry.background ?? entry.button.targetGraphic as Image;
            background ??= entry.button.GetComponent<Image>();
            if (background == null)
            {
                continue;
            }

            Outline outline = background.GetComponent<Outline>();
            if (outline == null)
            {
                continue;
            }

            bool isSelected = IsVariantButtonEntryCurrentlySelected(
                entry,
                selectedSlots,
                selectedRegionVariant,
                defaultHairSelectionActive,
                propsMode);

            Color baseOutlineColor = ResolveVariantButtonBaseOutlineColor(entry, selectedSlots);
            bool isFocused = focusedVariantButton != null && entry.button == focusedVariantButton;
            if (isSelected)
            {
                outline.effectColor = selectedOutlineColor;
            }
            else if (isFocused)
            {
                outline.effectColor = FocusedPartOutlineColor;
            }
            else
            {
                outline.effectColor = baseOutlineColor;
            }

            bool showOutline = true;
            if (propsMode && entry.isPropButton)
            {
                showOutline = isSelected;
            }

            outline.useGraphicAlpha = false;
            outline.enabled = showOutline;

            if (entry.isPropEmptyButton || IsDefaultVariantButtonEntry(entry))
            {
                SyncEmptyVariantIconColor(entry.button, outline.effectColor);
            }
        }
    }

    private int? ResolveSelectedRegionVariantForVariantButtons(MinimoCharacterCustomizer.PartSlot[] selectedSlots = null)
    {
        if (customizer == null || selectedRegionIndex < 0 || selectedRegionIndex >= regions.Count)
        {
            return null;
        }

        selectedSlots ??= GetTargetSlotsForVariantButtonPanel();
        if (selectedSlots == null || selectedSlots.Length == 0)
        {
            return null;
        }

        if (HasSelectedWorldVariantTargetSlots())
        {
            return GetUniformVariantForSlots(selectedSlots);
        }

        if (selectedWorldColorTargetSlot.HasValue && SlotArrayContains(selectedSlots, selectedWorldColorTargetSlot.Value))
        {
            return customizer.GetPartVariant(selectedWorldColorTargetSlot.Value);
        }

        return GetUniformVariantForSlots(selectedSlots);
    }

    private bool IsDefaultHairButtonSelectionActive(MinimoCharacterCustomizer.PartSlot[] selectedSlots = null)
    {
        if (customizer == null)
        {
            return false;
        }

        selectedSlots ??= GetTargetSlotsForVariantButtonPanel();
        if (!IsSingleHairSlotSelection(selectedSlots))
        {
            return false;
        }

        if (!customizer.TryGetPartRenderer(MinimoCharacterCustomizer.PartSlot.Hair, out SkinnedMeshRenderer hairRenderer)
            || hairRenderer == null)
        {
            return false;
        }

        return !hairRenderer.enabled;
    }

    private static bool IsDefaultVariantButtonEntry(VariantButtonEntry entry)
    {
        return entry != null
               && entry.variantIndex < 0
               && !entry.isRandomButton
               && entry.button != null
               && string.Equals(entry.button.gameObject.name, "Part_Default", StringComparison.OrdinalIgnoreCase);
    }

    private bool IsVariantButtonEntryCurrentlySelected(
        VariantButtonEntry entry,
        MinimoCharacterCustomizer.PartSlot[] selectedSlots,
        int? selectedRegionVariant,
        bool defaultHairSelectionActive,
        bool propsMode)
    {
        if (entry == null || entry.button == null || entry.isRandomButton)
        {
            return false;
        }

        _ = selectedSlots;
        if (entry.isFaceTextureButton)
        {
            return !string.IsNullOrWhiteSpace(entry.faceTextureKey)
                   && string.Equals(entry.faceTextureKey, selectedFaceTextureSetKey, StringComparison.OrdinalIgnoreCase);
        }

        if (propsMode && entry.isPropButton)
        {
            return IsPropButtonSelected(entry);
        }

        if (defaultHairSelectionActive)
        {
            return IsDefaultVariantButtonEntry(entry);
        }

        if (entry.variantIndex >= 0 && entry.targetSlots != null && entry.targetSlots.Length > 0)
        {
            return IsVariantAlreadySelectedForSlots(entry.targetSlots, entry.variantIndex);
        }

        return selectedRegionVariant.HasValue && entry.variantIndex == selectedRegionVariant.Value;
    }

    private Color ResolveVariantButtonBaseOutlineColor(
        VariantButtonEntry entry,
        MinimoCharacterCustomizer.PartSlot[] selectedSlots)
    {
        _ = entry;
        _ = selectedSlots;
        return ResolveSavedCharacterDefaultOutlineColor();
    }

    private void UpdateColorButtonVisuals()
    {
        if (customizer == null || selectedRegionIndex < 0 || selectedRegionIndex >= regions.Count)
        {
            return;
        }

        MinimoCharacterCustomizer.PartSlot[] swatchTargetSlots = GetTargetSlotsForColorOperations();
        MinimoCharacterCustomizer.PartSlot swatchAnchorSlot = selectedWorldColorTargetSlot ?? (swatchTargetSlots.Length > 0
            ? swatchTargetSlots[0]
            : MinimoCharacterCustomizer.PartSlot.Torso);

        for (int i = 0; i < colorChannelButtons.Count; i++)
        {
            ColorChannelButtonEntry channelEntry = colorChannelButtons[i];
            if (channelEntry?.button == null)
            {
                continue;
            }

            if (channelEntry.swatch != null)
            {
                channelEntry.swatch.color = ResolveColorChannelSwatchColor(
                    swatchAnchorSlot,
                    channelEntry.targetType,
                    channelEntry.materialIndex,
                    channelEntry.facePropertyId);
            }

            channelEntry.button.transform.localScale = Vector3.one;
        }

        UpdateMaterialChannelSelectionVisuals();

        Color selectedPaletteColor = Color.clear;
        bool hasSelectedPaletteColor = selectedColorChannelTarget != ColorChannelTargetType.Material
            ? TryGetSelectedFaceChannelColor(out selectedPaletteColor)
            : TryGetCurrentSelectionAnchorColor(out selectedPaletteColor);
        int selectedColorButtonIndex = ResolveActiveColorButtonIndex(hasSelectedPaletteColor, selectedPaletteColor);

        for (int i = 0; i < colorButtons.Count; i++)
        {
            ColorButtonEntry entry = colorButtons[i];
            if (entry?.button == null)
            {
                continue;
            }

            EnsureColorButtonInteractionState(entry);
            if (entry.background == null)
            {
                continue;
            }

            entry.background.color = entry.color;
            entry.button.transform.localScale = Vector3.one;
            bool showOutline = i == selectedColorButtonIndex;
            SetColorSelectionOutlineVisible(entry.selectionOutline, showOutline);
        }
    }

    private void EnsureShadowPressTracking(Button button, bool allowWithoutShadowTarget = true)
    {
        if (button == null)
        {
            return;
        }

        if (ShouldSkipShadowPressBottomAnimation(button))
        {
            RemoveShadowPressTracking(button);
            return;
        }

        bool hasPressTarget = TryResolveButtonPressTarget(button, out RectTransform buttonRect);
        if (!hasPressTarget)
        {
            if (!allowWithoutShadowTarget)
            {
                shadowPressButtonStates.Remove(button.gameObject.GetInstanceID());
                return;
            }

            buttonRect = button.transform as RectTransform;
        }

        if (buttonRect == null)
        {
            shadowPressButtonStates.Remove(button.gameObject.GetInstanceID());
            return;
        }

        int instanceId = button.gameObject.GetInstanceID();
        if (!shadowPressButtonStates.TryGetValue(instanceId, out ShadowPressButtonState state))
        {
            float releasedBottom = ResolveShadowPressReleasedBottom(button, buttonRect);
            Shadow shadowEffect = ResolveShadowEffectTarget(button);
            Vector2 releasedEffectDistance = shadowEffect != null ? shadowEffect.effectDistance : Vector2.zero;
            state = new ShadowPressButtonState
            {
                button = button,
                rect = buttonRect,
                shadowEffect = shadowEffect,
                releasedBottom = releasedBottom,
                currentBottom = buttonRect.offsetMin.y,
                releasedSizeDelta = buttonRect.sizeDelta,
                releasedAnchoredPosition = buttonRect.anchoredPosition,
                pressProgress = 0f,
                releasedEffectDistance = releasedEffectDistance,
                currentEffectDistance = releasedEffectDistance,
                pointerHeld = false,
                allowWithoutShadowTarget = allowWithoutShadowTarget,
                hasEffectDistanceTarget = shadowEffect != null
            };
            shadowPressButtonStates[instanceId] = state;
        }
        else
        {
            state.button = button;
            state.rect = buttonRect;
            state.allowWithoutShadowTarget = allowWithoutShadowTarget || state.allowWithoutShadowTarget;
            RefreshShadowPressEffectTarget(state);
        }

        RuntimeShadowPressButtonBridge bridge = button.GetComponent<RuntimeShadowPressButtonBridge>();
        if (bridge == null)
        {
            bridge = button.gameObject.AddComponent<RuntimeShadowPressButtonBridge>();
        }

        bridge.owner = this;
        bridge.button = button;
    }

    private void RemoveShadowPressTracking(Button button)
    {
        if (button == null)
        {
            return;
        }

        int instanceId = button.gameObject.GetInstanceID();
        if (shadowPressButtonStates.TryGetValue(instanceId, out ShadowPressButtonState state)
            && state?.shadowEffect != null
            && state.hasEffectDistanceTarget)
        {
            state.shadowEffect.effectDistance = state.releasedEffectDistance;
        }

        shadowPressButtonStates.Remove(instanceId);
    }

    private void HandleShadowButtonPointerDown(Button button)
    {
        if (ShouldSkipShadowPressBottomAnimation(button))
        {
            RemoveShadowPressTracking(button);
            return;
        }

        EnsureShadowPressTracking(button, ShouldAllowShadowPressWithoutTarget(button));
        if (button == null)
        {
            return;
        }

        int instanceId = button.gameObject.GetInstanceID();
        if (!shadowPressButtonStates.TryGetValue(instanceId, out ShadowPressButtonState state) || state == null)
        {
            return;
        }

        state.pointerHeld = true;
    }

    private void HandleShadowButtonPointerUp(Button button)
    {
        if (button == null)
        {
            return;
        }

        int instanceId = button.gameObject.GetInstanceID();
        if (!shadowPressButtonStates.TryGetValue(instanceId, out ShadowPressButtonState state) || state == null)
        {
            return;
        }

        state.pointerHeld = false;
    }

    private void UpdateShadowPressButtonAnimations()
    {
        if (shadowPressButtonStates.Count == 0)
        {
            return;
        }

        List<int> removeIds = null;
        float delta = Mathf.Max(0.0001f, Time.unscaledDeltaTime);
        float step = ShadowPressAnimationSpeed * delta;
        foreach (KeyValuePair<int, ShadowPressButtonState> pair in shadowPressButtonStates)
        {
            int instanceId = pair.Key;
            ShadowPressButtonState state = pair.Value;
            if (state == null || state.button == null || state.rect == null)
            {
                removeIds ??= new List<int>();
                removeIds.Add(instanceId);
                continue;
            }

            if (ShouldSkipShadowPressBottomAnimation(state.button))
            {
                removeIds ??= new List<int>();
                removeIds.Add(instanceId);
                continue;
            }

            bool hasLivePressTarget = TryResolveButtonPressTarget(state.button, out RectTransform liveRect);
            if (!hasLivePressTarget && state.allowWithoutShadowTarget)
            {
                liveRect = state.button.transform as RectTransform;
            }

            if (liveRect == null)
            {
                removeIds ??= new List<int>();
                removeIds.Add(instanceId);
                continue;
            }

            if (state.rect != liveRect)
            {
                state.rect = liveRect;
                state.releasedBottom = ResolveShadowPressReleasedBottom(state.button, liveRect);
                state.currentBottom = liveRect.offsetMin.y;
                state.releasedSizeDelta = liveRect.sizeDelta;
                state.releasedAnchoredPosition = liveRect.anchoredPosition;
                state.pressProgress = 0f;
            }

            RefreshShadowPressEffectTarget(state);
            bool pressed = state.pointerHeld || state.stickyActive;
            if (IsPartSizePressButton(state.button))
            {
                UpdatePartSizePressButtonAnimation(state, pressed, step);
            }
            else
            {
                float targetBottom = pressed
                    ? ResolveShadowPressPressedBottom(state.button, state.releasedBottom)
                    : state.releasedBottom;
                state.currentBottom = Mathf.MoveTowards(state.currentBottom, targetBottom, step);

                Vector2 offsetMin = state.rect.offsetMin;
                if (!Mathf.Approximately(offsetMin.y, state.currentBottom))
                {
                    offsetMin.y = state.currentBottom;
                    state.rect.offsetMin = offsetMin;
                }

                UpdateShadowPressEffectDistance(state, step);
            }
        }

        if (removeIds == null)
        {
            return;
        }

        for (int i = 0; i < removeIds.Count; i++)
        {
            shadowPressButtonStates.Remove(removeIds[i]);
        }
    }

    private void UpdateShadowStickyButtonStates()
    {
        if (shadowPressButtonStates.Count == 0)
        {
            return;
        }

        for (int i = 0; i < regions.Count; i++)
        {
            SetShadowButtonSticky(regions[i]?.button, i == selectedRegionIndex);
        }

        MinimoCharacterCustomizer.PartSlot[] selectedSlots = null;
        int? selectedRegionVariant = null;
        bool defaultHairSelectionActive = false;
        bool propsMode = false;
        if (customizer != null && selectedRegionIndex >= 0 && selectedRegionIndex < regions.Count)
        {
            propsMode = IsPropsRegionSelectionMode();
            selectedSlots = propsMode
                ? GetTargetSlotsForSelectedRegion()
                : GetTargetSlotsForVariantButtonPanel();
            selectedRegionVariant = ResolveSelectedRegionVariantForVariantButtons(selectedSlots);
            defaultHairSelectionActive = IsDefaultHairButtonSelectionActive(selectedSlots);
        }

        for (int i = 0; i < variantButtons.Count; i++)
        {
            VariantButtonEntry entry = variantButtons[i];
            if (entry?.button == null || entry.isRandomButton)
            {
                continue;
            }

            bool sticky = IsVariantButtonEntryCurrentlySelected(
                entry,
                selectedSlots,
                selectedRegionVariant,
                defaultHairSelectionActive,
                propsMode);

            SetShadowButtonSticky(entry.button, sticky);
        }

        for (int i = 0; i < colorChannelButtons.Count; i++)
        {
            ColorChannelButtonEntry entry = colorChannelButtons[i];
            if (entry == null)
            {
                continue;
            }

            RemoveShadowPressTracking(entry.button);
        }

        for (int i = 0; i < colorButtons.Count; i++)
        {
            ColorButtonEntry entry = colorButtons[i];
            if (entry?.button == null)
            {
                continue;
            }

            RemoveShadowPressTracking(entry.button);
        }

        bool partsPanelActive = showPanelsAsTabs
            ? isCustomizePanelMode
            : (partsPanelRoot != null && partsPanelRoot.gameObject.activeSelf);
        bool savedPanelActive = showPanelsAsTabs
            ? !isCustomizePanelMode
            : (savePrefabsPanelRoot != null && savePrefabsPanelRoot.gameObject.activeSelf);

        SetShadowButtonSticky(partsPanelToggleButton, partsPanelActive);
        SetShadowButtonSticky(savePrefabsPanelToggleButton, savedPanelActive);
        SetShadowButtonSticky(customCategoryDropdownToggleButton, customCategoryDropdownExpanded);
        SetShadowButtonSticky(customSavedPrefabDropdownToggleButton, customSavedPrefabDropdownExpanded);

        for (int i = 0; i < customCategoryDropdownOptionButtons.Count && i < categoryDropdownOptions.Count; i++)
        {
            SetShadowButtonSticky(
                customCategoryDropdownOptionButtons[i],
                IsCategorySelectionActive(categoryDropdownOptions[i]));
        }

        for (int i = 0; i < customSavedPrefabDropdownOptionButtons.Count && i < savedPrefabCategoryDropdownOptions.Count; i++)
        {
            SetShadowButtonSticky(customSavedPrefabDropdownOptionButtons[i], i == selectedSavedPrefabCategoryDropdownIndex);
        }

        if (gamepadFocusedStickyButton != null
            && gamepadFocusedStickyButton.gameObject.activeInHierarchy
            && gamepadFocusedStickyButton.IsActive()
            && gamepadFocusedStickyButton.IsInteractable())
        {
            SetShadowButtonSticky(gamepadFocusedStickyButton, true);
        }

        UpdateMaterialChannelSelectionVisuals();
    }

    private void SetShadowButtonSticky(Button button, bool stickyActive)
    {
        EnsureShadowPressTracking(button, ShouldAllowShadowPressWithoutTarget(button));
        if (button == null)
        {
            return;
        }

        int instanceId = button.gameObject.GetInstanceID();
        if (shadowPressButtonStates.TryGetValue(instanceId, out ShadowPressButtonState state) && state != null)
        {
            state.stickyActive = stickyActive;
        }
    }

    private static bool TryResolveShadowPressTarget(Button button, out RectTransform buttonRect)
    {
        buttonRect = button != null ? button.transform as RectTransform : null;
        return buttonRect != null && HasShadowNamedSelfOrParent(buttonRect);
    }

    private static bool TryResolveButtonPressTarget(Button button, out RectTransform buttonRect)
    {
        buttonRect = button != null ? button.transform as RectTransform : null;
        return buttonRect != null;
    }

    private void UpdatePartSizePressButtonAnimation(ShadowPressButtonState state, bool pressed, float step)
    {
        if (state == null || state.rect == null)
        {
            return;
        }

        float animationDistance = ResolvePartSizePressAnimationDistance(state);
        float progressStep = animationDistance > 0.001f ? step / animationDistance : 1f;
        state.pressProgress = Mathf.MoveTowards(state.pressProgress, pressed ? 1f : 0f, progressStep);

        Vector2 sizeDelta = state.rect.sizeDelta;
        sizeDelta.y = Mathf.Lerp(
            state.releasedSizeDelta.y,
            PartButtonPressedHeight,
            state.pressProgress);
        state.rect.sizeDelta = sizeDelta;

        Vector2 anchoredPosition = state.rect.anchoredPosition;
        anchoredPosition.y = Mathf.Lerp(
            state.releasedAnchoredPosition.y,
            PartButtonPressedPosY,
            state.pressProgress);
        state.rect.anchoredPosition = anchoredPosition;

        if (!state.hasEffectDistanceTarget || state.shadowEffect == null)
        {
            return;
        }

        state.currentEffectDistance.x = state.releasedEffectDistance.x;
        state.currentEffectDistance.y = Mathf.Lerp(
            state.releasedEffectDistance.y,
            0f,
            state.pressProgress);
        state.shadowEffect.effectDistance = state.currentEffectDistance;
    }

    private static float ResolvePartSizePressAnimationDistance(ShadowPressButtonState state)
    {
        if (state == null)
        {
            return 1f;
        }

        float heightDistance = Mathf.Abs(PartButtonPressedHeight - state.releasedSizeDelta.y);
        float posYDistance = Mathf.Abs(PartButtonPressedPosY - state.releasedAnchoredPosition.y);
        float effectDistance = state.hasEffectDistanceTarget
            ? Mathf.Abs(state.releasedEffectDistance.y)
            : 0f;

        return Mathf.Max(1f, heightDistance, posYDistance, effectDistance);
    }

    private bool IsPartSizePressButton(Button button)
    {
        if (button == null)
        {
            return false;
        }

        for (int i = 0; i < regions.Count; i++)
        {
            if (regions[i]?.button == button)
            {
                return true;
            }
        }

        for (int i = 0; i < worldLinkedSlotToggleButtons.Count; i++)
        {
            if (worldLinkedSlotToggleButtons[i]?.button == button)
            {
                return true;
            }
        }

        Transform buttonTransform = button.transform;
        if (buttonTransform != null)
        {
            if (bodySelectRoot != null && buttonTransform.IsChildOf(bodySelectRoot))
            {
                return true;
            }

            if (worldLinkedSelectionUiContentRoot != null && buttonTransform.IsChildOf(worldLinkedSelectionUiContentRoot))
            {
                return true;
            }
        }

        string buttonName = button.gameObject != null ? button.gameObject.name : string.Empty;
        return string.Equals(buttonName, "BodyPartButton", StringComparison.OrdinalIgnoreCase)
               || IsWorldLinkedSlotButtonName(buttonName);
    }

    private float ResolveShadowPressReleasedBottom(Button button, RectTransform rect)
    {
        if (button == null || rect == null)
        {
            return 0f;
        }

        return IsPageModeButton(button) ? 0f : rect.offsetMin.y;
    }

    private float ResolveShadowPressPressedBottom(Button button, float releasedBottom)
    {
        return IsPageModeButton(button) ? PageButtonPressedBottom : 0f;
    }

    private bool IsPageModeButton(Button button)
    {
        if (button == null)
        {
            return false;
        }

        if (button == partsPanelToggleButton
            || button == savePrefabsPanelToggleButton
            || button == playSceneButton)
        {
            return true;
        }

        string buttonName = button.gameObject != null ? button.gameObject.name : string.Empty;
        return string.Equals(buttonName, "CustomizeButton", StringComparison.OrdinalIgnoreCase)
               || string.Equals(buttonName, "SavedPrefabsButton", StringComparison.OrdinalIgnoreCase)
               || string.Equals(buttonName, "PlayButton", StringComparison.OrdinalIgnoreCase)
               || string.Equals(buttonName, "PartsPanelButton", StringComparison.OrdinalIgnoreCase)
               || string.Equals(buttonName, "SavePrefabsPanelButton", StringComparison.OrdinalIgnoreCase)
               || string.Equals(buttonName, "PlayScene", StringComparison.OrdinalIgnoreCase);
    }

    private Shadow ResolveShadowEffectTarget(Button button)
    {
        if (button == null)
        {
            return null;
        }

        bool ignoreOutlineEffect = IsSavedPrefabPanelButton(button) || IsVariantPartPanelButton(button);
        Shadow[] effects = button.GetComponentsInChildren<Shadow>(true);
        Shadow namedShadow = null;
        Shadow firstShadow = null;
        Shadow namedAny = null;
        Shadow firstAny = null;
        for (int i = 0; i < effects.Length; i++)
        {
            Shadow effect = effects[i];
            if (effect == null)
            {
                continue;
            }

            bool isNamedShadow = HasAncestorContainingName(effect.transform, "shadow");
            bool isOutline = effect is Outline;
            if (isOutline && ignoreOutlineEffect)
            {
                continue;
            }

            if (firstAny == null)
            {
                firstAny = effect;
            }

            if (isNamedShadow && namedAny == null)
            {
                namedAny = effect;
            }

            if (!isOutline)
            {
                if (firstShadow == null)
                {
                    firstShadow = effect;
                }

                if (isNamedShadow && namedShadow == null)
                {
                    namedShadow = effect;
                }
            }
        }

        return namedShadow != null ? namedShadow : firstShadow != null ? firstShadow : namedAny != null ? namedAny : firstAny;
    }

    private bool IsSavedPrefabPanelButton(Button button)
    {
        if (button == null)
        {
            return false;
        }

        if (savePrefabsContent != null && button.transform != null && button.transform.IsChildOf(savePrefabsContent))
        {
            return true;
        }

        for (int i = 0; i < savedPrefabButtons.Count; i++)
        {
            if (savedPrefabButtons[i]?.button == button)
            {
                return true;
            }
        }

        return false;
    }

    private bool IsVariantPartPanelButton(Button button)
    {
        if (button == null)
        {
            return false;
        }

        for (int i = 0; i < variantButtons.Count; i++)
        {
            if (variantButtons[i]?.button == button)
            {
                return true;
            }
        }

        return bodyPartsContent != null
               && button.transform != null
               && button.transform.IsChildOf(bodyPartsContent);
    }

    private void RefreshShadowPressEffectTarget(ShadowPressButtonState state)
    {
        if (state == null || state.button == null)
        {
            return;
        }

        Shadow liveEffect = ResolveShadowEffectTarget(state.button);
        if (state.shadowEffect == liveEffect)
        {
            state.hasEffectDistanceTarget = liveEffect != null;
            return;
        }

        state.shadowEffect = liveEffect;
        state.hasEffectDistanceTarget = liveEffect != null;
        if (liveEffect != null)
        {
            state.releasedEffectDistance = liveEffect.effectDistance;
            state.currentEffectDistance = liveEffect.effectDistance;
        }
    }

    private static void UpdateShadowPressEffectDistance(ShadowPressButtonState state, float step)
    {
        if (state == null || !state.hasEffectDistanceTarget || state.shadowEffect == null)
        {
            return;
        }

        float targetEffectDistanceY = state.pointerHeld || state.stickyActive
            ? 0f
            : state.releasedEffectDistance.y;
        state.currentEffectDistance.y = Mathf.MoveTowards(
            state.currentEffectDistance.y,
            targetEffectDistanceY,
            step);
        state.currentEffectDistance.x = state.releasedEffectDistance.x;
        state.shadowEffect.effectDistance = state.currentEffectDistance;
    }

    private static bool HasShadowNamedSelfOrParent(Transform child)
    {
        if (child == null)
        {
            return false;
        }

        Transform current = child;
        while (current != null)
        {
            string name = current.name ?? string.Empty;
            if (name.IndexOf("shadow", StringComparison.OrdinalIgnoreCase) >= 0)
            {
                return true;
            }

            current = current.parent;
        }

        return false;
    }

    private void UpdateMaterialChannelSelectionVisuals()
    {
        MinimoCharacterCustomizer.PartSlot[] targetSlots = GetTargetSlotsForColorOperations();
        MinimoCharacterCustomizer.PartSlot anchorSlot = selectedWorldColorTargetSlot ?? (targetSlots.Length > 0
            ? targetSlots[0]
            : MinimoCharacterCustomizer.PartSlot.Torso);

        for (int i = 0; i < colorChannelButtons.Count; i++)
        {
            ColorChannelButtonEntry entry = colorChannelButtons[i];
            if (entry == null)
            {
                continue;
            }

            bool isSelected = IsColorChannelEntrySelected(entry);
            Color channelColor = ResolveColorChannelSwatchColor(
                anchorSlot,
                entry.targetType,
                entry.materialIndex,
                entry.facePropertyId);

            if (entry.swatch != null)
            {
                entry.swatch.color = channelColor;
                if (entry.background != null)
                {
                    entry.background.color = isSelected
                        ? Color.white
                        : entry.defaultBackgroundColor;
                }
            }
            else
            {
                if (entry.background != null)
                {
                    entry.background.color = channelColor;
                }
            }

            SetColorSelectionOutlineVisible(entry.selectionOutline, isSelected);
        }
    }

    private bool IsColorChannelEntrySelected(ColorChannelButtonEntry entry)
    {
        if (entry == null || entry.targetType != selectedColorChannelTarget)
        {
            return false;
        }

        if (entry.targetType == ColorChannelTargetType.Material)
        {
            return entry.materialIndex == selectedColorMaterialIndex;
        }

        return entry.facePropertyId == selectedFaceColorPropertyId;
    }

    private int? GetUniformVariantForSlots(MinimoCharacterCustomizer.PartSlot[] slots)
    {
        if (slots == null || slots.Length == 0 || customizer == null)
        {
            return null;
        }

        int first = customizer.GetPartVariant(slots[0]);
        for (int i = 1; i < slots.Length; i++)
        {
            if (customizer.GetPartVariant(slots[i]) != first)
            {
                return null;
            }
        }

        return first;
    }

    private Color? GetUniformColorForSlots(MinimoCharacterCustomizer.PartSlot[] slots, int materialIndex)
    {
        if (slots == null || slots.Length == 0 || customizer == null)
        {
            return null;
        }

        int firstMaterialIndex = ResolveColorMaterialIndexForSlot(slots[0], materialIndex);
        if (firstMaterialIndex < 0 || !TryGetEffectivePartColor(slots[0], firstMaterialIndex, out Color first))
        {
            return null;
        }

        for (int i = 1; i < slots.Length; i++)
        {
            int nextMaterialIndex = ResolveColorMaterialIndexForSlot(slots[i], materialIndex);
            if (nextMaterialIndex < 0 || !TryGetEffectivePartColor(slots[i], nextMaterialIndex, out Color next))
            {
                return null;
            }

            if (!ColorsNearlyEqual(first, next))
            {
                return null;
            }
        }

        return first;
    }

    private void SelectColorChannel(int materialIndex)
    {
        SelectColorChannel(ColorChannelTargetType.Material, materialIndex, -1);
    }

    private void SelectColorChannel(ColorChannelTargetType targetType, int materialIndex, int facePropertyId)
    {
        selectedColorChannelTarget = targetType;
        if (targetType == ColorChannelTargetType.Material)
        {
            selectedColorMaterialIndex = Mathf.Max(0, materialIndex);
            selectedFaceColorPropertyId = -1;
        }
        else
        {
            selectedColorMaterialIndex = Mathf.Max(0, materialIndex);
            selectedFaceColorPropertyId = facePropertyId;
        }

        selectedPaletteButtonIndex = -1;
        UpdateMaterialChannelSelectionVisuals();

        RefreshAfterCustomizationApplication(null, refreshWorldPartColliders: false, savePersistentState: false);
    }

    private void UpdateWorldLinkedMaterialSelectionStateFromMaterialChannelSelection(int colorChannelIndex)
    {
        bool hasPersistedSlotSelection = TryGetPersistedWorldLinkedSelectedSlots(
            out List<MinimoCharacterCustomizer.PartSlot> persistedSelectedSlots);
        bool hasWorldLinkedContext = worldLinkedMaterialSelectionKeyValid
                                     || worldLinkedMaterialSingleOverrideActive
                                     || hasPersistedSlotSelection;
        if (!hasWorldLinkedContext || customizer == null)
        {
            ResetWorldLinkedMaterialSelectionState();
            return;
        }

        MinimoCharacterCustomizer.PartSlot anchorSlot = selectedWorldColorTargetSlot ?? default;
        if (!selectedWorldColorTargetSlot.HasValue)
        {
            if (hasPersistedSlotSelection && persistedSelectedSlots.Count > 0)
            {
                anchorSlot = persistedSelectedSlots[0];
            }
            else if (!TryGetCurrentWorldLinkedMaterialTargets(out Dictionary<MinimoCharacterCustomizer.PartSlot, HashSet<int>> fallbackTargets))
            {
                ResetWorldLinkedMaterialSelectionState();
                return;
            }
            else if (!TryGetFirstSelectedWorldLinkedSlot(fallbackTargets, out anchorSlot))
            {
                foreach (KeyValuePair<MinimoCharacterCustomizer.PartSlot, HashSet<int>> pair in fallbackTargets)
                {
                    anchorSlot = pair.Key;
                    break;
                }
            }

            selectedWorldColorTargetSlot = anchorSlot;
        }

        int resolvedMaterialIndex = ResolveColorMaterialIndexForSlot(anchorSlot, colorChannelIndex);
        if (resolvedMaterialIndex < 0
            || !TryGetWorldLinkedMaterialKey(anchorSlot, resolvedMaterialIndex, out string materialKey)
            || !TryBuildWorldLinkedMaterialTargetsByKey(materialKey, out Dictionary<MinimoCharacterCustomizer.PartSlot, HashSet<int>> linkedTargets)
            || linkedTargets.Count <= 1)
        {
            if (hasPersistedSlotSelection)
            {
                RebuildWorldLinkedTargetsSnapshotFromSelectedSlots(
                    colorChannelIndex,
                    preserveExplicitColorChannel: true);
                return;
            }

            ResetWorldLinkedMaterialSelectionState();
            return;
        }

        worldLinkedMaterialSelectionKeyValid = true;
        worldLinkedMaterialSelectionKey = materialKey;
        worldLastHoveredMaterialKey = string.Empty;
        worldLinkedMaterialTargetsSnapshot.Clear();
        CopyWorldLinkedMaterialTargets(linkedTargets, worldLinkedMaterialTargetsSnapshot);
        SetWorldLinkedSlotSelectionStateForGroup(
            materialKey,
            linkedTargets,
            anchorSlot,
            focusOnly: false,
            preserveExistingForSameKey: true);
        UpdateWorldLinkedSingleOverrideFromSelection(linkedTargets);
        if (!selectedWorldColorTargetSlot.HasValue
            || !IsWorldLinkedSlotSelected(selectedWorldColorTargetSlot.Value))
        {
            if (TryGetFirstSelectedWorldLinkedSlot(linkedTargets, out MinimoCharacterCustomizer.PartSlot selectedSlot))
            {
                selectedWorldColorTargetSlot = selectedSlot;
            }
        }

        if (hasPersistedSlotSelection)
        {
            RebuildWorldLinkedTargetsSnapshotFromSelectedSlots(
                colorChannelIndex,
                preserveExplicitColorChannel: true);
        }
    }

    private Color ResolveColorChannelSwatchColor(
        MinimoCharacterCustomizer.PartSlot anchorSlot,
        ColorChannelDescriptor descriptor)
    {
        if (descriptor == null)
        {
            return new Color(0.8f, 0.8f, 0.8f, 1f);
        }

        return ResolveColorChannelSwatchColor(
            anchorSlot,
            descriptor.targetType,
            descriptor.materialIndex,
            descriptor.facePropertyId);
    }

    private Color ResolveColorChannelSwatchColor(
        MinimoCharacterCustomizer.PartSlot anchorSlot,
        ColorChannelTargetType targetType,
        int materialChannelIndex,
        int facePropertyId)
    {
        if (targetType == ColorChannelTargetType.Material)
        {
            if (TryResolveMaterialChannelSwatchColor(anchorSlot, materialChannelIndex, out Color materialColor))
            {
                return materialColor;
            }

            return new Color(0.82f, 0.82f, 0.82f, 1f);
        }

        if (facePropertyId >= 0
            && TryGetFaceMaterialForChannel(materialChannelIndex, out Material faceMaterial)
            && faceMaterial != null
            && faceMaterial.HasProperty(facePropertyId))
        {
            Color faceChannelColor = faceMaterial.GetColor(facePropertyId);
            return AdjustFaceChannelPreviewSwatchColor(targetType, faceChannelColor);
        }

        if (facePropertyId >= 0
            && TryGetFaceMaterialChannelForProperty(facePropertyId, out int fallbackChannelIndex)
            && TryGetFaceMaterialForChannel(fallbackChannelIndex, out Material fallbackFaceMaterial)
            && fallbackFaceMaterial != null
            && fallbackFaceMaterial.HasProperty(facePropertyId))
        {
            Color faceChannelColor = fallbackFaceMaterial.GetColor(facePropertyId);
            return AdjustFaceChannelPreviewSwatchColor(targetType, faceChannelColor);
        }

        return new Color(0.8f, 0.8f, 0.8f, 1f);
    }

    private static Color AdjustFaceChannelPreviewSwatchColor(ColorChannelTargetType targetType, Color sourceColor)
    {
        if (targetType != ColorChannelTargetType.FaceMakeup)
        {
            return sourceColor;
        }

        Color darker = Color.Lerp(sourceColor, Color.black, 0.12f);
        darker.a = sourceColor.a;
        return darker;
    }

    private bool TryResolveMaterialChannelSwatchColor(
        MinimoCharacterCustomizer.PartSlot anchorSlot,
        int materialChannelIndex,
        out Color color)
    {
        color = new Color(0.82f, 0.82f, 0.82f, 1f);

        if (IsPropsRegionSelectionMode())
        {
            return TryGetEffectivePropColor(materialChannelIndex, out color);
        }

        int materialIndex = ResolveColorMaterialIndexForSlot(anchorSlot, materialChannelIndex);
        if (materialIndex < 0)
        {
            return false;
        }

        if (customizer != null && customizer.TryGetPartColor(anchorSlot, materialIndex, out color))
        {
            return true;
        }

        if (customizer != null && customizer.TryGetPartColor(anchorSlot, -1, out color))
        {
            return true;
        }

        if (TryGetMaterialForSlot(anchorSlot, materialIndex, out Material material)
            && material != null
            && material.HasProperty(ColorShaderProperty))
        {
            color = material.GetColor(ColorShaderProperty);
            return true;
        }

        return false;
    }

    private void UpdateColorPanelHeader(int colorChannelCount)
    {
