    private void ConfigureModelListLayout()
    {
        if (bodyPartsScroll == null)
        {
            return;
        }

        bool preserveLayout = Application.isPlaying && preserveSceneLayoutDuringPlay;

        RectTransform scrollRect = bodyPartsScroll.GetComponent<RectTransform>();
        if (scrollRect == null)
        {
            return;
        }

        Image scrollBackground = scrollRect.GetComponent<Image>();
        if (scrollBackground != null)
        {
            scrollBackground.color = UiSurfacePrimaryColor;
            ApplyRoundedImage(scrollBackground);
            EnsureFixedOutline(scrollBackground);
        }

        if (!preserveLayout && bodyPartsScroll.viewport != null)
        {
            RectTransform viewportRect = bodyPartsScroll.viewport;
            viewportRect.anchorMin = Vector2.zero;
            viewportRect.anchorMax = Vector2.one;
            viewportRect.offsetMin = new Vector2(6f, 6f);
            viewportRect.offsetMax = new Vector2(-6f, -6f);
        }

        if (bodyPartsContent != null)
        {
            if (!preserveLayout)
            {
                bodyPartsContent.anchorMin = new Vector2(0f, 1f);
                bodyPartsContent.anchorMax = new Vector2(1f, 1f);
                bodyPartsContent.pivot = new Vector2(0f, 1f);
                bodyPartsContent.offsetMin = new Vector2(0f, 0f);
                bodyPartsContent.offsetMax = new Vector2(0f, 0f);
                bodyPartsContent.anchoredPosition = Vector2.zero;
            }

            ContentSizeFitter fitter = bodyPartsContent.GetComponent<ContentSizeFitter>();
            if (!preserveLayout && fitter != null)
            {
                fitter.horizontalFit = ContentSizeFitter.FitMode.Unconstrained;
                fitter.verticalFit = ContentSizeFitter.FitMode.PreferredSize;
            }

            GridLayoutGroup bodyGrid = bodyPartsContent.GetComponent<GridLayoutGroup>();
            if (!preserveLayout && bodyGrid != null)
            {
                bodyGrid.cellSize = new Vector2(108f, 108f);
                bodyGrid.spacing = new Vector2(10f, 10f);
                bodyGrid.startAxis = GridLayoutGroup.Axis.Horizontal;
                bodyGrid.startCorner = GridLayoutGroup.Corner.UpperLeft;
                bodyGrid.constraint = GridLayoutGroup.Constraint.FixedColumnCount;
                bodyGrid.constraintCount = 3;
                bodyGrid.padding = new RectOffset(10, 10, 10, 10);
            }
        }
    }

    private void ConfigureColorPanelLayout()
    {
        if (colorPanelRoot == null)
        {
            return;
        }

        bool preserveLayout = Application.isPlaying && preserveSceneLayoutDuringPlay;

        Image panelBackground = colorPanelRoot.GetComponent<Image>();
        if (panelBackground != null)
        {
            panelBackground.color = UiSurfaceSecondaryColor;
            ApplyRoundedImage(panelBackground);
            EnsureFixedOutline(panelBackground);
        }

        if (colorPanelHeaderLabel != null)
        {
            colorPanelHeaderLabel.color = new Color(0.9f, 0.9f, 0.9f, 1f);
            colorPanelHeaderLabel.fontSize = Mathf.Max(13, colorPanelHeaderLabel.fontSize);
            colorPanelHeaderLabel.alignment = TextAnchor.MiddleLeft;
            EnsureFixedOutline(colorPanelHeaderLabel);
        }

        if (colorPanelContent != null)
        {
            bool usingRootAsContent = colorPanelContent == colorPanelRoot;
            if (!preserveLayout && !usingRootAsContent)
            {
                colorPanelContent.anchorMin = new Vector2(0f, 0f);
                colorPanelContent.anchorMax = new Vector2(1f, 1f);
                colorPanelContent.offsetMin = new Vector2(8f, 8f);
                colorPanelContent.offsetMax = new Vector2(-8f, -30f);
            }

            GridLayoutGroup colorGrid = colorPanelContent.GetComponent<GridLayoutGroup>();
            if (!preserveLayout && colorGrid != null)
            {
                colorGrid.cellSize = usingRootAsContent ? new Vector2(30f, 30f) : new Vector2(28f, 28f);
                colorGrid.spacing = new Vector2(6f, 6f);
                colorGrid.constraint = GridLayoutGroup.Constraint.FixedColumnCount;
                colorGrid.constraintCount = usingRootAsContent ? 7 : 8;
                colorGrid.childAlignment = TextAnchor.UpperLeft;
            }
        }

        colorPanelRoot.gameObject.SetActive(true);
    }

    private bool IsSavedPanelActive()
    {
        if (savePrefabsPanelRoot == null || !savePrefabsPanelRoot.gameObject.activeSelf)
        {
            return false;
        }

        if (showPanelsAsTabs && savedPanelShowsReadyCharactersOnly)
        {
            return !isCustomizePanelMode;
        }

        if (partsPanelRoot == null)
        {
            return true;
        }

        if (!showPanelsAsTabs)
        {
            return savePrefabsPanelRoot.gameObject.activeSelf;
        }

        return !partsPanelRoot.gameObject.activeSelf;
    }

    private float ResolveReadyCharacterCardWidth()
    {
        if (bodyPartsContent != null)
        {
            GridLayoutGroup bodyGrid = bodyPartsContent.GetComponent<GridLayoutGroup>();
            if (bodyGrid != null && bodyGrid.cellSize.x > 1f)
            {
                return bodyGrid.cellSize.x;
            }
        }

        return 108f;
    }

    private void ConfigureSavedPrefabsLayout()
    {
        if (!savedPanelShowsReadyCharactersOnly || savePrefabsScroll == null || savePrefabsContent == null)
        {
            return;
        }

        if (keepSavedPrefabsRectTransformsUnchanged)
        {
            // Keep scene-authored SavePrefabsPanel / Viewport / Content RectTransforms unchanged.
            return;
        }

        bool preserveLayout = Application.isPlaying && preserveSceneLayoutDuringPlay;
        if (preserveLayout)
        {
            return;
        }

        savePrefabsScroll.horizontal = true;
        savePrefabsScroll.vertical = false;
        savePrefabsScroll.movementType = ScrollRect.MovementType.Clamped;
        savePrefabsScroll.inertia = true;
        if (savePrefabsScroll.verticalScrollbar != null)
        {
            savePrefabsScroll.verticalScrollbar.gameObject.SetActive(false);
        }

        if (!preserveLayout && savePrefabsScroll.viewport != null)
        {
            RectTransform viewportRect = savePrefabsScroll.viewport;
            viewportRect.anchorMin = Vector2.zero;
            viewportRect.anchorMax = Vector2.one;
            viewportRect.offsetMin = new Vector2(6f, 6f);
            viewportRect.offsetMax = new Vector2(-6f, -6f);
        }

        float cardWidth = ResolveReadyCharacterCardWidth();
        Vector2 cardSpacing = new Vector2(10f, 10f);
        if (!preserveLayout)
        {
            savePrefabsContent.anchorMin = new Vector2(0f, 1f);
            savePrefabsContent.anchorMax = new Vector2(0f, 1f);
            savePrefabsContent.pivot = new Vector2(0f, 1f);
            savePrefabsContent.anchoredPosition = Vector2.zero;
            savePrefabsContent.offsetMin = Vector2.zero;
            savePrefabsContent.offsetMax = Vector2.zero;
        }

        HorizontalLayoutGroup horizontal = savePrefabsContent.GetComponent<HorizontalLayoutGroup>();
        if (horizontal != null)
        {
            horizontal.enabled = false;
        }

        VerticalLayoutGroup vertical = savePrefabsContent.GetComponent<VerticalLayoutGroup>();
        if (vertical != null)
        {
            vertical.enabled = false;
        }

        GridLayoutGroup grid = savePrefabsContent.GetComponent<GridLayoutGroup>();
        if (grid == null)
        {
            grid = savePrefabsContent.gameObject.AddComponent<GridLayoutGroup>();
        }

        const int contentPadding = 8;
        grid.padding = new RectOffset(contentPadding, contentPadding, contentPadding, contentPadding);

        float cardHeight = readyCharacterCardHeight;
        if (savePrefabsScroll.viewport != null)
        {
            float viewportHeight = savePrefabsScroll.viewport.rect.height;
            float paddedHeight = viewportHeight - (contentPadding * 2f);
            if (paddedHeight > 1f)
            {
                cardHeight = Mathf.Max(cardWidth + 24f, paddedHeight);
            }
        }

        grid.cellSize = new Vector2(cardWidth, cardHeight);
        grid.spacing = cardSpacing;
        grid.startAxis = GridLayoutGroup.Axis.Horizontal;
        grid.startCorner = GridLayoutGroup.Corner.UpperLeft;
        grid.constraint = GridLayoutGroup.Constraint.FixedRowCount;
        grid.constraintCount = 1;
        grid.childAlignment = TextAnchor.UpperLeft;

        ContentSizeFitter fitter = savePrefabsContent.GetComponent<ContentSizeFitter>();
        if (fitter == null)
        {
            fitter = savePrefabsContent.gameObject.AddComponent<ContentSizeFitter>();
        }

        fitter.horizontalFit = ContentSizeFitter.FitMode.Unconstrained;
        fitter.verticalFit = ContentSizeFitter.FitMode.Unconstrained;

        UpdateSavedPrefabsContentSize();
    }

    private void UpdateSavedPrefabsContentSize()
    {
        if (keepSavedPrefabsRectTransformsUnchanged)
        {
            // Keep scene-authored SavePrefabsPanel / Viewport / Content RectTransforms unchanged.
            return;
        }

        if (savePrefabsContent == null)
        {
            return;
        }

        GridLayoutGroup grid = savePrefabsContent.GetComponent<GridLayoutGroup>();
        if (grid == null)
        {
            return;
        }

        int count = Mathf.Max(0, savedPrefabButtons.Count);
        int rows = Mathf.Max(1, grid.constraintCount);
        int cols = Mathf.Max(1, Mathf.CeilToInt(count / (float)rows));
        float width = grid.padding.left + grid.padding.right + (grid.cellSize.x * cols) + (grid.spacing.x * Mathf.Max(0, cols - 1));
        float height = grid.padding.top + grid.padding.bottom + (grid.cellSize.y * rows) + (grid.spacing.y * Mathf.Max(0, rows - 1));

        if (savePrefabsScroll != null && savePrefabsScroll.viewport != null)
        {
            Rect viewportRect = savePrefabsScroll.viewport.rect;
            width = Mathf.Max(width, viewportRect.width);
            height = Mathf.Max(height, viewportRect.height);
        }

        savePrefabsContent.SetSizeWithCurrentAnchors(RectTransform.Axis.Horizontal, width);
        savePrefabsContent.SetSizeWithCurrentAnchors(RectTransform.Axis.Vertical, height);
    }

    private void UpdateSavedPanelPresentation()
    {
        bool savedMode = savedPanelShowsReadyCharactersOnly && IsSavedPanelActive();

        if (randomizeButton != null)
        {
            randomizeButton.gameObject.SetActive(!savedMode);
        }

        if (saveButton != null)
        {
            saveButton.gameObject.SetActive(!savedMode);
        }

        bool showSceneCategoryDropdown = !savedMode
                                         && UsesBodySelectionUI()
                                         && (partsPanelRoot == null || partsPanelRoot.gameObject.activeSelf);

        bool usesSceneCategoryDropdownButton = UsesSceneCategoryDropdownButton();
        bool hasCustomCategoryDropdown = customCategoryDropdownRoot != null;
        if (customCategoryDropdownRoot != null)
        {
            customCategoryDropdownRoot.gameObject.SetActive(showSceneCategoryDropdown);
            if (!showSceneCategoryDropdown)
            {
                SetCustomCategoryDropdownOpen(false);
            }
        }

        if (categoryDropdown != null)
        {
            categoryDropdown.gameObject.SetActive(showSceneCategoryDropdown && (!hasCustomCategoryDropdown || usesSceneCategoryDropdownButton));
        }

        bool usesSceneSavedDropdownButton = UsesSceneSavedPrefabDropdownButton();
        bool hasCustomSavedDropdown = customSavedPrefabDropdownRoot != null;
        if (customSavedPrefabDropdownRoot != null)
        {
            customSavedPrefabDropdownRoot.gameObject.SetActive(savedMode);
            if (!savedMode)
            {
                SetCustomSavedPrefabDropdownOpen(false);
            }
            else
            {
                UpdateSavedPrefabCategoryDropdownLabel();
            }
        }

        if (savedPrefabsCategoryDropdown != null)
        {
            savedPrefabsCategoryDropdown.gameObject.SetActive(savedMode && (!hasCustomSavedDropdown || usesSceneSavedDropdownButton));
            if (savedMode)
            {
                UpdateSavedPrefabCategoryDropdownLabel();
            }
        }

        if (categoryControlsRowRoot != null)
        {
            bool includesModeButtons =
                (partsPanelToggleButton != null && partsPanelToggleButton.transform.IsChildOf(categoryControlsRowRoot))
                || (savePrefabsPanelToggleButton != null && savePrefabsPanelToggleButton.transform.IsChildOf(categoryControlsRowRoot));
            bool includesCategoryDropdown =
                (categoryDropdown != null && categoryDropdown.transform.IsChildOf(categoryControlsRowRoot))
                || (customCategoryDropdownRoot != null && customCategoryDropdownRoot.transform.IsChildOf(categoryControlsRowRoot));
            categoryControlsRowRoot.gameObject.SetActive(includesModeButtons || (includesCategoryDropdown && showSceneCategoryDropdown));
        }

        if (bodySelectRoot != null)
        {
            bodySelectRoot.gameObject.SetActive(!savedMode);
        }

        if (bodyPartsScroll != null)
        {
            bodyPartsScroll.gameObject.SetActive(!savedMode);
        }

        if (regionListRoot != null)
        {
            regionListRoot.gameObject.SetActive(!savedMode && !UsesBodySelectionUI());
        }

        if (colorPanelRoot != null)
        {
            colorPanelRoot.gameObject.SetActive(!savedMode);
        }

        if (savedMode)
        {
            SetWorldLinkedSelectionUiVisible(false);
        }
        else if (showWorldLinkedSelectionUi)
        {
            UpdateWorldLinkedSelectionUi();
        }

        if (materialChannelStripRoot != null)
        {
            bool showStrip = !savedMode
                             && colorChannelButtons.Count > 0
                             && (partsPanelRoot == null || partsPanelRoot.gameObject.activeSelf);
            materialChannelStripRoot.gameObject.SetActive(showStrip);
        }

        if (savedMode)
        {
            SetCustomColorPickerVisible(false);
        }

        if (colorChartButton != null)
        {
            bool showColorChartButton = !savedMode
                                        && enableCustomColorPicker
                                        && (partsPanelRoot == null || partsPanelRoot.gameObject.activeSelf);
            colorChartButton.gameObject.SetActive(showColorChartButton);
        }

        if (autoRotationButton != null)
        {
            bool showAutoRotationButton = partsPanelRoot == null || partsPanelRoot.gameObject.activeSelf || savedMode;
            autoRotationButton.gameObject.SetActive(showAutoRotationButton);
        }

        if (savedPrefabsLeftArrowButton != null)
        {
            savedPrefabsLeftArrowButton.gameObject.SetActive(savedMode);
        }

        if (savedPrefabsRightArrowButton != null)
        {
            savedPrefabsRightArrowButton.gameObject.SetActive(savedMode);
        }

        // Keep auto-rotation state when switching panels.
        ApplyAutoRotationStateToDragRotate();

        UpdateReadyCharacterArrowState(savedMode);
        UpdateSavedPrefabButtonVisuals();
        if (savedMode && deferSavedPrefabPreviewGeneration)
        {
            StartSavedPrefabPreviewWarmup();
        }
    }

    private void UpdateSavedPrefabButtonVisuals()
    {
        Color selectedOutlineColor = SavedButtonSelectedOutlineFallbackColor;
        Color defaultOutlineColor = ResolveSavedCharacterDefaultOutlineColor();
        for (int i = 0; i < savedPrefabButtons.Count; i++)
        {
            SavedPrefabButtonEntry entry = savedPrefabButtons[i];
            if (entry?.button == null)
            {
                continue;
            }

            Image background = entry.button.targetGraphic as Image;
            background ??= entry.button.GetComponent<Image>();
            if (background == null)
            {
                continue;
            }

            bool isSelected = i == selectedSavedPrefabIndex;
            Outline outline = background.GetComponent<Outline>();
            if (outline == null)
            {
                outline = background.gameObject.AddComponent<Outline>();
            }

            outline.effectColor = isSelected ? selectedOutlineColor : defaultOutlineColor;
            outline.effectDistance = ResolveSavedPrefabOutlineEffectDistance(outline, isSelected);
            outline.useGraphicAlpha = false;
            outline.enabled = true;
        }
    }

    private static Vector2 ResolveSavedPrefabOutlineEffectDistance(Outline outline, bool isSelected)
    {
        Vector2 distance = outline != null ? outline.effectDistance : new Vector2(8f, 8f);
        if (Mathf.Abs(distance.x) <= 0.001f)
        {
            distance.x = 8f;
        }

        if (isSelected)
        {
            distance.y = distance.x;
        }
        else if (Mathf.Abs(distance.y) <= 0.001f)
        {
            distance.y = distance.x;
        }

        return distance;
    }

    private Button ResolveFocusedVariantButtonForGamepad()
    {
        if (!enableGamepadUiControl || !IsGamepadNavigationRecentlyActive())
        {
            return null;
        }

        EventSystem eventSystem = EventSystem.current;
        if (eventSystem == null)
        {
            return null;
        }

        Selectable current = ResolveSelectableFromGameObject(eventSystem.currentSelectedGameObject);
        Button focusedButton = ResolveButtonFromSelectable(current);
        return TryFindVariantButtonIndex(focusedButton, out _)
            ? focusedButton
            : null;
    }

    private Color ResolveSavedCharacterDefaultOutlineColor()
    {
        return SavedButtonDefaultOutlineColor;
    }

    private Color ResolveSavedCharacterSelectedOutlineColor()
    {
        return ResolveButtonGraphicColor(partsPanelToggleButton, SavedButtonSelectedOutlineFallbackColor);
    }

    private static Color ResolveButtonGraphicColor(Button button, Color fallback)
    {
        if (button == null)
        {
            return fallback;
        }

        Image image = button.targetGraphic as Image;
        image ??= button.GetComponent<Image>();
        if (image == null)
        {
            return fallback;
        }

        Color color = image.color;
        color.a = 1f;
        return color;
    }

    private void UpdateReadyCharacterArrowState(bool shouldShow)
    {
        if (savedPrefabsLeftArrowButton != null || savedPrefabsRightArrowButton != null)
        {
            if (readyCharacterArrowRoot != null)
            {
                readyCharacterArrowRoot.gameObject.SetActive(false);
            }

            return;
        }

        if (Application.isPlaying && preserveSceneLayoutDuringPlay)
        {
            if (readyCharacterArrowRoot != null)
            {
                readyCharacterArrowRoot.gameObject.SetActive(false);
            }

            return;
        }

        if (!showReadyCharacterSideArrows)
        {
            if (readyCharacterArrowRoot != null)
            {
                readyCharacterArrowRoot.gameObject.SetActive(false);
            }

            return;
        }

        bool canShow = shouldShow && savedPrefabButtons.Count > 0;
        if (!canShow)
        {
            if (readyCharacterArrowRoot != null)
            {
                readyCharacterArrowRoot.gameObject.SetActive(false);
            }

            return;
        }

        if (!EnsureReadyCharacterArrows())
        {
            return;
        }

        readyCharacterArrowRoot.gameObject.SetActive(true);
        UpdateReadyCharacterArrowLayout();
    }

    private bool EnsureReadyCharacterArrows()
    {
        if (readyCharacterArrowRoot != null
            && readyCharacterPrevArrowButton != null
            && readyCharacterNextArrowButton != null)
        {
            return true;
        }

        Canvas canvas = GetComponentInParent<Canvas>();
        if (canvas == null || !(canvas.transform is RectTransform canvasRect))
        {
            return false;
        }

        GameObject root = new GameObject("ReadyCharacterArrows", typeof(RectTransform));
        readyCharacterArrowRoot = root.GetComponent<RectTransform>();
        readyCharacterArrowRoot.SetParent(canvasRect, false);
        readyCharacterArrowRoot.anchorMin = Vector2.zero;
        readyCharacterArrowRoot.anchorMax = Vector2.one;
        readyCharacterArrowRoot.offsetMin = Vector2.zero;
        readyCharacterArrowRoot.offsetMax = Vector2.zero;
        readyCharacterArrowRoot.pivot = new Vector2(0.5f, 0.5f);
        readyCharacterArrowRoot.SetAsLastSibling();

        Font font = ResolveFont();
        readyCharacterPrevArrowButton = CreateReadyCharacterArrowButton(readyCharacterArrowRoot, font, "<", "ReadyPrevArrow", out readyCharacterPrevArrowRect);
        readyCharacterNextArrowButton = CreateReadyCharacterArrowButton(readyCharacterArrowRoot, font, ">", "ReadyNextArrow", out readyCharacterNextArrowRect);
        if (readyCharacterPrevArrowButton == null || readyCharacterNextArrowButton == null)
        {
            return false;
        }

        readyCharacterPrevArrowButton.onClick.RemoveAllListeners();
        readyCharacterNextArrowButton.onClick.RemoveAllListeners();
        readyCharacterPrevArrowButton.onClick.AddListener(() => SelectSavedPrefabByStep(-1));
        readyCharacterNextArrowButton.onClick.AddListener(() => SelectSavedPrefabByStep(1));
        return true;
    }

    private Button CreateReadyCharacterArrowButton(
        Transform parent,
        Font font,
        string text,
        string objectName,
        out RectTransform rect)
    {
        rect = null;
        if (parent == null)
        {
            return null;
        }

        GameObject obj = new GameObject(objectName, typeof(RectTransform), typeof(Image), typeof(Button));
        rect = obj.GetComponent<RectTransform>();
        rect.SetParent(parent, false);
        rect.anchorMin = new Vector2(0.5f, 0.5f);
        rect.anchorMax = new Vector2(0.5f, 0.5f);
        rect.pivot = new Vector2(0.5f, 0.5f);
        rect.sizeDelta = readyCharacterArrowSize;

        Image image = obj.GetComponent<Image>();
        image.color = UiButtonNeutralColor;

        Button button = obj.GetComponent<Button>();
        button.targetGraphic = image;
        ApplyButtonInteractionStyle(button, UiButtonNeutralColor);

        Text label = CreateRowText("Label", rect, font, 28, TextAnchor.MiddleCenter, new Color(0.95f, 0.95f, 0.95f, 1f));
        label.text = text;
        label.rectTransform.anchorMin = Vector2.zero;
        label.rectTransform.anchorMax = Vector2.one;
        label.rectTransform.offsetMin = Vector2.zero;
        label.rectTransform.offsetMax = Vector2.zero;
        return button;
    }

    private void UpdateReadyCharacterArrowLayout()
    {
        if (readyCharacterArrowRoot == null
            || !readyCharacterArrowRoot.gameObject.activeSelf
            || readyCharacterPrevArrowRect == null
            || readyCharacterNextArrowRect == null)
        {
            return;
        }

        if (customizer == null || customizationCamera == null || !(readyCharacterArrowRoot.parent is RectTransform canvasRect))
        {
            readyCharacterPrevArrowRect.anchoredPosition = new Vector2(-readyCharacterArrowDistance, 0f);
            readyCharacterNextArrowRect.anchoredPosition = new Vector2(readyCharacterArrowDistance, 0f);
            return;
        }

        Canvas canvas = readyCharacterArrowRoot.GetComponentInParent<Canvas>();
        Camera uiCamera = canvas != null && canvas.renderMode != RenderMode.ScreenSpaceOverlay
            ? canvas.worldCamera
            : null;

        Vector3 worldPoint = customizer.transform.position + Vector3.up * 1.05f;
        Vector3 screenPoint = customizationCamera.WorldToScreenPoint(worldPoint);
        Vector2 anchorLocalPoint = Vector2.zero;
        if (screenPoint.z > 0.001f)
        {
            RectTransformUtility.ScreenPointToLocalPointInRectangle(canvasRect, screenPoint, uiCamera, out anchorLocalPoint);
        }

        readyCharacterPrevArrowRect.anchoredPosition = anchorLocalPoint + Vector2.left * readyCharacterArrowDistance;
        readyCharacterNextArrowRect.anchoredPosition = anchorLocalPoint + Vector2.right * readyCharacterArrowDistance;
        readyCharacterPrevArrowRect.sizeDelta = readyCharacterArrowSize;
        readyCharacterNextArrowRect.sizeDelta = readyCharacterArrowSize;
    }

    private void SelectSavedPrefabByStep(int step)
    {
#if UNITY_EDITOR
        if (savedPrefabButtons.Count == 0)
        {
            return;
        }

        if (selectedSavedPrefabIndex < 0 || selectedSavedPrefabIndex >= savedPrefabButtons.Count)
        {
            selectedSavedPrefabIndex = 0;
        }

        selectedSavedPrefabIndex = NextWrappedIndex(selectedSavedPrefabIndex, step, savedPrefabButtons.Count);
        ApplySavedPrefabByIndex(selectedSavedPrefabIndex);
#endif
    }

    private int GetSelectedRegionColorChannelCount()
    {
        if (customizer == null || selectedRegionIndex < 0 || selectedRegionIndex >= regions.Count)
        {
            return 0;
        }

        if (IsPropsRegionSelectionMode())
        {
            return BuildColorChannelDescriptorsForSelectedProp().Count;
        }

        MinimoCharacterCustomizer.PartSlot[] slots = GetTargetSlotsForColorOperations();
        if (slots.Length == 0)
        {
            return 0;
        }

        MinimoCharacterCustomizer.PartSlot anchorSlot = selectedWorldColorTargetSlot ?? slots[0];
        return BuildColorChannelDescriptorsForSlot(anchorSlot).Count;
    }

    private int GetEditableColorChannelCountForSlot(MinimoCharacterCustomizer.PartSlot slot)
    {
        return GetEditableColorMaterialIndicesForSlot(slot).Count;
    }

    private List<int> GetEditableColorMaterialIndicesForSlot(MinimoCharacterCustomizer.PartSlot slot)
    {
        return GetEditableColorMaterialIndicesForSlot(customizer, slot);
    }

    private List<int> GetEditableColorMaterialIndicesForSlot(
        MinimoCharacterCustomizer targetCustomizer,
        MinimoCharacterCustomizer.PartSlot slot)
    {
        List<int> indices = new List<int>();
        if (targetCustomizer == null || !targetCustomizer.TryGetPartRenderer(slot, out SkinnedMeshRenderer renderer) || renderer == null)
        {
            return indices;
        }

        Material[] materials = renderer.sharedMaterials;
        if (materials == null || materials.Length == 0)
        {
            return indices;
        }

        int materialCount = GetEffectiveRendererMaterialSlotCount(renderer, materials);
        for (int i = 0; i < materialCount; i++)
        {
            indices.Add(i);
        }

        return indices;
    }

    private static int GetEffectiveRendererMaterialSlotCount(Renderer renderer, Material[] materials)
    {
        int materialCount = materials != null ? materials.Length : 0;
        if (renderer == null || materialCount <= 0)
        {
            return 0;
        }

        int subMeshCount = 0;
        if (renderer is SkinnedMeshRenderer skinnedRenderer)
        {
            subMeshCount = skinnedRenderer.sharedMesh != null
                ? skinnedRenderer.sharedMesh.subMeshCount
                : 0;
        }
        else if (renderer is MeshRenderer)
        {
            if (renderer.TryGetComponent(out MeshFilter meshFilter) && meshFilter != null && meshFilter.sharedMesh != null)
            {
                subMeshCount = meshFilter.sharedMesh.subMeshCount;
            }
        }

        if (subMeshCount > 0 && materialCount > subMeshCount)
        {
            materialCount = subMeshCount;
        }

        return Mathf.Max(0, materialCount);
    }

    private int ResolveColorMaterialIndexForSlot(MinimoCharacterCustomizer.PartSlot slot, int colorChannelIndex)
    {
        return ResolveColorMaterialIndexForSlot(customizer, slot, colorChannelIndex);
    }

    private int ResolveExactColorMaterialIndexForSlot(
        MinimoCharacterCustomizer.PartSlot slot,
        int colorChannelIndex)
    {
        List<int> editableIndices = GetEditableColorMaterialIndicesForSlot(slot);
        return colorChannelIndex >= 0 && colorChannelIndex < editableIndices.Count
            ? editableIndices[colorChannelIndex]
            : -1;
    }

    private int ResolveColorMaterialIndexForSlot(
        MinimoCharacterCustomizer targetCustomizer,
        MinimoCharacterCustomizer.PartSlot slot,
        int colorChannelIndex)
    {
        List<int> editableIndices = GetEditableColorMaterialIndicesForSlot(targetCustomizer, slot);
        if (editableIndices.Count == 0)
        {
            return -1;
        }

        int requestedChannel = Mathf.Max(0, colorChannelIndex);
        if (requestedChannel >= editableIndices.Count)
        {
            requestedChannel = 0;
        }

        return editableIndices[requestedChannel];
    }

    private bool TryResolveColorChannelFromMaterialIndex(
        MinimoCharacterCustomizer.PartSlot slot,
        int materialIndex,
        out int colorChannelIndex)
    {
        colorChannelIndex = 0;
        if (materialIndex < 0)
        {
            return false;
        }

        List<int> editableIndices = GetEditableColorMaterialIndicesForSlot(slot);
        if (editableIndices.Count == 0)
        {
            return false;
        }

        for (int i = 0; i < editableIndices.Count; i++)
        {
            if (editableIndices[i] == materialIndex)
            {
                colorChannelIndex = i;
                return true;
            }
        }

        return false;
    }

    private MinimoCharacterCustomizer.PartSlot[] GetTargetSlotsForColorOperations()
    {
        if (selectedWorldColorTargetSlot.HasValue)
        {
            MinimoCharacterCustomizer.PartSlot[] singleSlot = { selectedWorldColorTargetSlot.Value };
            return singleSlot;
        }

        return GetTargetSlotsForSelectedRegion();
    }

    private List<MinimoCharacterCustomizer.PartSlot> GetStableSelectedSlotsForColorApplication(
        bool allowCrossGroup)
    {
        List<MinimoCharacterCustomizer.PartSlot> selectedSlots;
        if (!TryGetPersistedWorldLinkedSelectedSlots(out selectedSlots))
        {
            selectedSlots = new List<MinimoCharacterCustomizer.PartSlot>();
            MinimoCharacterCustomizer.PartSlot[] fallbackSlots = GetTargetSlotsForColorOperations();
            for (int i = 0; i < fallbackSlots.Length; i++)
            {
                if (!selectedSlots.Contains(fallbackSlots[i]))
                {
                    selectedSlots.Add(fallbackSlots[i]);
                }
            }
        }

        if (allowCrossGroup || selectedSlots.Count == 0)
        {
            return selectedSlots;
        }

        MinimoCharacterCustomizer.PartSlot anchorSlot = selectedWorldColorTargetSlot.HasValue
                                                       && selectedSlots.Contains(selectedWorldColorTargetSlot.Value)
            ? selectedWorldColorTargetSlot.Value
            : selectedSlots[0];
        string anchorGroupKey = ResolveWorldLinkedNonSkinMaterialGroupKey(anchorSlot);
        selectedSlots.RemoveAll(slot => !string.Equals(
            ResolveWorldLinkedNonSkinMaterialGroupKey(slot),
            anchorGroupKey,
            StringComparison.OrdinalIgnoreCase));
        return selectedSlots;
    }

    private MinimoCharacterCustomizer.PartSlot[] GetColorApplicationSlots()
    {
        MinimoCharacterCustomizer.PartSlot[] targetSlots = GetTargetSlotsForColorOperations();
        if (targetSlots == null || targetSlots.Length == 0)
        {
            return targetSlots ?? Array.Empty<MinimoCharacterCustomizer.PartSlot>();
        }

        bool applySkinGroup = ShouldUseSkinPaletteForCurrentSelection();
        if (!applySkinGroup)
        {
            return targetSlots;
        }

        return SkinToneSlots;
    }

    private Color[] GetActivePaletteColors()
    {
        if (IsPropsRegionSelectionMode() && selectedColorChannelTarget == ColorChannelTargetType.Material)
        {
            return ResolvePaletteOrDefault(garmentTonePalette, DefaultGarmentTonePalette);
        }

        if (selectedColorChannelTarget == ColorChannelTargetType.FaceEyebrows)
        {
            Color[] browsPalette = ResolvePaletteOrDefault(eyebrowsTonePalette, DefaultEyebrowsTonePalette);
            if (browsPalette.Length > 0)
            {
                return browsPalette;
            }

            return ResolvePaletteOrDefault(hairTonePalette, DefaultHairTonePalette);
        }

        if (selectedColorChannelTarget == ColorChannelTargetType.FaceEyes)
        {
            Color[] eyesPalette = ResolvePaletteOrDefault(eyesTonePalette, DefaultEyesTonePalette);
            return eyesPalette.Length > 0
                ? eyesPalette
                : ResolvePaletteOrDefault(paletteColors, DefaultGarmentTonePalette);
        }

        if (selectedColorChannelTarget == ColorChannelTargetType.FaceMakeup)
        {
            Color[] makeupPalette = ResolvePaletteOrDefault(makeupTonePalette, DefaultMakeupTonePalette);
            if (makeupPalette.Length > 0)
            {
                return makeupPalette;
            }

            Color[] eyesPalette = ResolvePaletteOrDefault(eyesTonePalette, DefaultEyesTonePalette);
            return eyesPalette.Length > 0
                ? eyesPalette
                : ResolvePaletteOrDefault(paletteColors, DefaultGarmentTonePalette);
        }

        MinimoCharacterCustomizer.PartSlot[] targetSlots = GetTargetSlotsForColorOperations();
        if (ShouldUseSkinPaletteForCurrentSelection() || IsDefaultHeadSelectionActive())
        {
            return ResolvePaletteOrDefault(skinTonePalette, DefaultSkinTonePalette);
        }

        MinimoCharacterCustomizer.PartSlot previewSlot = targetSlots.Length > 0
            ? targetSlots[0]
            : MinimoCharacterCustomizer.PartSlot.Torso;
        if (previewSlot == MinimoCharacterCustomizer.PartSlot.Hair)
        {
            return ResolvePaletteOrDefault(hairTonePalette, DefaultHairTonePalette);
        }

        Color[] garmentPalette = ResolvePaletteOrDefault(garmentTonePalette, DefaultGarmentTonePalette);
        if (garmentPalette.Length > 0)
        {
            return garmentPalette;
        }

        return ResolvePaletteOrDefault(paletteColors, DefaultGarmentTonePalette);
    }

    private string GetActivePaletteName()
    {
        if (selectedColorChannelTarget == ColorChannelTargetType.FaceEyes)
        {
            return "Eyes";
        }

        if (selectedColorChannelTarget == ColorChannelTargetType.FaceEyebrows)
        {
            return "Eyebrows";
        }

        if (selectedColorChannelTarget == ColorChannelTargetType.FaceMakeup)
        {
            return "Makeup";
        }

        MinimoCharacterCustomizer.PartSlot[] targetSlots = GetTargetSlotsForColorOperations();
        if (ShouldUseSkinPaletteForCurrentSelection() || IsDefaultHeadSelectionActive())
        {
            return "Skin";
        }

        MinimoCharacterCustomizer.PartSlot previewSlot = targetSlots.Length > 0
            ? targetSlots[0]
            : MinimoCharacterCustomizer.PartSlot.Torso;
        if (previewSlot == MinimoCharacterCustomizer.PartSlot.Hair)
        {
            return "Hair";
        }

        return "Fabric";
    }

    private bool ShouldUseSkinPaletteForCurrentSelection()
    {
        if (selectedColorChannelTarget != ColorChannelTargetType.Material)
        {
            return false;
        }

        MinimoCharacterCustomizer.PartSlot[] targetSlots = GetTargetSlotsForColorOperations();
        if (selectedWorldColorTargetSlot.HasValue
            && IsSkinLinkedMaterialTargetSelection(selectedWorldColorTargetSlot.Value, selectedColorMaterialIndex))
        {
            return true;
        }

        if (targetSlots.Length == 0)
        {
            return false;
        }

        for (int i = 0; i < targetSlots.Length; i++)
        {
            if (!IsSkinLinkedMaterialTargetSelection(targetSlots[i], selectedColorMaterialIndex))
            {
                return false;
            }
        }

        return true;
    }

    private bool IsDefaultHeadSelectionActive()
    {
        if (customizer == null || selectedColorChannelTarget != ColorChannelTargetType.Material)
        {
            return false;
        }

        MinimoCharacterCustomizer.PartSlot[] targetSlots = GetTargetSlotsForColorOperations();
        if (targetSlots == null || targetSlots.Length != 1 || targetSlots[0] != MinimoCharacterCustomizer.PartSlot.Face)
        {
            return false;
        }

        int currentVariant = customizer.GetPartVariant(MinimoCharacterCustomizer.PartSlot.Face);
        return IsDefaultCategoryVariantForSlot(MinimoCharacterCustomizer.PartSlot.Face, currentVariant);
    }

    private static Color[] ResolvePaletteOrDefault(Color[] palette, Color[] fallback)
    {
        Color[] primary = (palette != null && palette.Length > 0)
            ? palette
            : fallback;
        Color[] secondary = fallback ?? Array.Empty<Color>();
        return BuildDistinctPalette(primary, secondary, PaletteSwatchCount);
    }

    private static Color[] BuildDistinctPalette(Color[] primary, Color[] secondary, int targetCount)
    {
        int count = Mathf.Max(1, targetCount);
        List<Color> result = new List<Color>(count);

        AppendDistinctColors(result, primary, count);
        AppendDistinctColors(result, secondary, count);

        if (result.Count == 0)
        {
            result.Add(Color.white);
        }

        return result.ToArray();
    }

    private static void AppendDistinctColors(List<Color> target, Color[] source, int maxCount)
    {
        if (target == null || source == null || source.Length == 0 || target.Count >= maxCount)
        {
            return;
        }

        for (int i = 0; i < source.Length && target.Count < maxCount; i++)
        {
            AddDistinctColor(target, source[i], maxCount);
        }
    }

    private static void AddDistinctColor(List<Color> target, Color color, int maxCount)
    {
        if (target == null || target.Count >= maxCount)
        {
            return;
        }

        color.a = 1f;
        for (int i = 0; i < target.Count; i++)
        {
            if (ColorsExactlyMatch(target[i], color))
            {
                return;
            }
        }

        target.Add(color);
    }

    private static bool IsSkinSlot(MinimoCharacterCustomizer.PartSlot slot)
    {
        return slot == MinimoCharacterCustomizer.PartSlot.Face;
    }

    private bool IsExcludedFromSkinToneWhenDefault(MinimoCharacterCustomizer.PartSlot slot)
    {
        if (customizer == null)
        {
            return false;
        }

        bool isHeadOrHandSlot = slot == MinimoCharacterCustomizer.PartSlot.Face
                                || slot == MinimoCharacterCustomizer.PartSlot.HandLeft
                                || slot == MinimoCharacterCustomizer.PartSlot.HandRight;
        if (!isHeadOrHandSlot)
        {
            return false;
        }

        int currentVariant = customizer.GetPartVariant(slot);
        return IsDefaultCategoryVariantForSlot(slot, currentVariant);
    }

    private bool IsSkinMaterialTargetSelection(MinimoCharacterCustomizer.PartSlot slot, int colorChannelIndex)
    {
        int materialIndex = ResolveColorMaterialIndexForSlot(slot, colorChannelIndex);
        return IsSkinMaterialTarget(slot, materialIndex);
    }

    private bool IsSkinLinkedMaterialTargetSelection(MinimoCharacterCustomizer.PartSlot slot, int colorChannelIndex)
    {
        int materialIndex = ResolveColorMaterialIndexForSlot(slot, colorChannelIndex);
        if (materialIndex < 0)
        {
            return false;
        }

        if (!TryGetEffectivePartColor(slot, materialIndex, out Color color))
        {
            return IsSkinMaterialTarget(slot, materialIndex);
        }

        return IsSkinLinkedMaterialTarget(slot, materialIndex, color);
    }

    private bool IsSkinMaterialTarget(MinimoCharacterCustomizer.PartSlot slot, int materialIndex)
    {
        if (IsExcludedFromSkinToneWhenDefault(slot))
        {
            return false;
        }

        if (IsSkinSlot(slot))
        {
            return true;
        }

        if (!TryGetMaterialForSlot(slot, materialIndex, out Material material))
        {
            return false;
        }

        return MaterialLooksLikeSkin(material);
    }

    private bool TryGetMaterialForSlot(
        MinimoCharacterCustomizer.PartSlot slot,
        int materialIndex,
        out Material material)
    {
        material = null;
        if (materialIndex < 0
            || customizer == null
            || !customizer.TryGetPartRenderer(slot, out SkinnedMeshRenderer renderer)
            || renderer == null)
        {
            return false;
        }

        Material[] materials = renderer.sharedMaterials;
        if (materials == null || materialIndex >= materials.Length)
        {
            return false;
        }

        material = materials[materialIndex];
        return material != null;
    }

    private static bool MaterialLooksLikeSkin(Material material)
    {
        if (material == null)
        {
            return false;
        }

        string materialName = material.name;
        if (string.IsNullOrWhiteSpace(materialName))
        {
            return false;
        }

        string normalizedName = materialName.Replace(" (Instance)", string.Empty).Trim();
        if (string.IsNullOrWhiteSpace(normalizedName))
        {
            return false;
        }

        for (int i = 0; i < TorsoSkinMaterialNameHints.Length; i++)
        {
            if (normalizedName.IndexOf(TorsoSkinMaterialNameHints[i], StringComparison.OrdinalIgnoreCase) >= 0)
            {
                return true;
            }
        }

        return false;
    }

    private void UpdateWorldPartInteraction()
    {
        CaptureWorldHoverRay();

        if (!enableWorldPartHoverSelection || customizer == null || customizationCamera == null)
        {
            hoveredWorldSlot = null;
            hoveredWorldMaterialIndex = -1;
            hoveredWorldPropRigName = string.Empty;
            worldLastHoveredMaterialKey = string.Empty;
            pressedWorldSlot = null;
            pressedWorldMaterialIndex = -1;
            pressedWorldPropRigName = string.Empty;
            UpdateWorldPartHoverVisuals(null, -1);
            return;
        }

        EnsureWorldPartColliders();

        bool pointerBlockedByUI = ignoreWorldPartHoverWhenPointerOnUI && IsPointerOverUI();
        if (MinimoInputBridge.GetMouseButtonDown(0))
        {
            if (!pointerBlockedByUI
                && TryGetHoveredWorldTargetFromMouse(
                    out MinimoCharacterCustomizer.PartSlot downSlot,
                    out int downMaterialIndex,
                    out string downPropRigName,
                    out _))
            {
                pressedWorldSlot = downSlot;
                pressedWorldMaterialIndex = downMaterialIndex;
                pressedWorldPropRigName = downPropRigName ?? string.Empty;
                worldPointerDownPosition = MinimoInputBridge.MousePosition;
            }
            else
            {
                pressedWorldSlot = null;
                pressedWorldMaterialIndex = -1;
                pressedWorldPropRigName = string.Empty;
            }
        }

        if (MinimoInputBridge.GetMouseButtonUp(0))
        {
            float clickSelectionMaxDrag = GetWorldPartClickMaxDragPixels();
            bool isClick = pressedWorldSlot.HasValue
                && Vector2.Distance(worldPointerDownPosition, MinimoInputBridge.MousePosition) <= clickSelectionMaxDrag;
            if (!pointerBlockedByUI && isClick)
            {
                MinimoCharacterCustomizer.PartSlot selectedSlot = pressedWorldSlot.Value;
                int selectedMaterialIndex = pressedWorldMaterialIndex;
                bool forceSingleWorldMaterialSelection = false;
                bool preserveWorldLinkedSelection = false;

                if (TryGetHoveredWorldTargetFromMouse(
                        out MinimoCharacterCustomizer.PartSlot releaseSlot,
                        out int releaseMaterialIndex,
                        out string releasePropRigName,
                        out _)
                    && releaseSlot == selectedSlot
                    && selectedMaterialIndex < 0)
                {
                    selectedMaterialIndex = releaseMaterialIndex;
                    if (string.IsNullOrWhiteSpace(pressedWorldPropRigName))
                    {
                        pressedWorldPropRigName = releasePropRigName ?? string.Empty;
                    }
                }

                MinimoCharacterCustomizer.PartSlot[] selectedVariantTargetSlots =
                    selectedSlot != MinimoCharacterCustomizer.PartSlot.Props
                        ? ResolveWorldVariantTargetSlotsForClick(selectedSlot, selectedMaterialIndex)
                        : Array.Empty<MinimoCharacterCustomizer.PartSlot>();

                if (selectedSlot != MinimoCharacterCustomizer.PartSlot.Props)
                {
                    if (TryApplyWorldLinkedSelectionFromHoverState(
                            selectedSlot,
                            selectedMaterialIndex,
                            out forceSingleWorldMaterialSelection))
                    {
                        preserveWorldLinkedSelection = true;
                    }
                    else
                    {
                        UpdateWorldLinkedMaterialSelectionStateFromClick(
                            selectedSlot,
                            selectedMaterialIndex,
                            out forceSingleWorldMaterialSelection);
                    }
                }
                else
                {
                    ResetWorldLinkedMaterialSelectionState();
                }

                SelectRegionFromWorldSlot(
                    selectedSlot,
                    selectedMaterialIndex,
                    pressedWorldPropRigName,
                    forceSingleWorldMaterialSelection,
                    preserveWorldLinkedSelection,
                    selectedVariantTargetSlots);
            }

            pressedWorldSlot = null;
            pressedWorldMaterialIndex = -1;
            pressedWorldPropRigName = string.Empty;
        }

        bool rotationInputCaptured = IsRotationInputCaptured() || (!pointerBlockedByUI && IsMouseButtonHeldOverCharacter());
        if (rotationInputCaptured)
        {
            hoveredWorldSlot = null;
            hoveredWorldMaterialIndex = -1;
            hoveredWorldPropRigName = string.Empty;
            worldLastHoveredMaterialKey = string.Empty;
            UpdateWorldPartHoverVisuals(null, -1);
            return;
        }

        MinimoCharacterCustomizer.PartSlot? hoveredSlot = null;
        int hoveredMaterialIndex = -1;
        string hoveredPropRigName = string.Empty;
        Vector3 hoveredWorldHitPoint = default;
        if (!pointerBlockedByUI
            && TryGetHoveredWorldTargetFromMouse(
                out MinimoCharacterCustomizer.PartSlot slot,
                out int materialIndex,
                out string propRigName,
                out Vector3 selectedWorldHitPoint))
        {
            hoveredSlot = slot;
            hoveredMaterialIndex = materialIndex;
            hoveredPropRigName = propRigName ?? string.Empty;
            hoveredWorldHitPoint = selectedWorldHitPoint;
        }

        string hoveredMaterialKey = string.Empty;
        if (hoveredSlot.HasValue && hoveredSlot.Value != MinimoCharacterCustomizer.PartSlot.Props)
        {
            int resolvedHoveredMaterialIndex = ResolveMaterialIndexForSlot(hoveredSlot.Value, hoveredMaterialIndex);
            TryGetWorldLinkedMaterialKey(hoveredSlot.Value, resolvedHoveredMaterialIndex, out hoveredMaterialKey);
        }

        if (!worldLinkedMaterialSingleOverrideActive
            && worldLinkedMaterialSelectionKeyValid
            && !string.IsNullOrWhiteSpace(hoveredMaterialKey)
            && string.Equals(hoveredMaterialKey, worldLinkedMaterialSelectionKey, StringComparison.OrdinalIgnoreCase)
            && !string.Equals(worldLastHoveredMaterialKey, hoveredMaterialKey, StringComparison.OrdinalIgnoreCase))
        {
            worldLinkedMaterialSingleOverrideActive = true;
        }

        worldLastHoveredMaterialKey = hoveredMaterialKey;

        hoveredWorldSlot = hoveredSlot;
        hoveredWorldMaterialIndex = hoveredMaterialIndex;
        hoveredWorldPropRigName = hoveredPropRigName;
        UpdateWorldPartHoverVisuals(hoveredSlot, hoveredMaterialIndex);
    }

    private void CaptureWorldHoverRay()
    {
        if (customizationCamera == null)
        {
            hasWorldHoverRay = false;
            return;
        }

        worldHoverRay = customizationCamera.ScreenPointToRay(MinimoInputBridge.MousePosition);
        hasWorldHoverRay = true;
    }

    private void SelectRegionFromWorldSlot(
        MinimoCharacterCustomizer.PartSlot slot,
        int preferredMaterialIndex = -1,
        string preferredPropRigName = "",
        bool forceSingleWorldMaterialSelection = false,
        bool preserveWorldLinkedSelection = false,
        MinimoCharacterCustomizer.PartSlot[] worldVariantTargetSlots = null)
    {
        if (slot == MinimoCharacterCustomizer.PartSlot.Props)
        {
            selectedWorldVariantTargetSlots = Array.Empty<MinimoCharacterCustomizer.PartSlot>();
            SelectPropsRegionFromWorldSelection(preferredMaterialIndex, preferredPropRigName);
            return;
        }

        worldLinkedMaterialSingleOverrideActive = forceSingleWorldMaterialSelection && worldLinkedMaterialSelectionKeyValid;

        MinimoCharacterCustomizer.PartSlot selectedColorSlot = slot;
        MinimoCharacterCustomizer.PartSlot regionMatchSlot = ResolveRegionAnchorSlotForWorldSelection(slot);
        int previousRegionIndex = selectedRegionIndex;
        MinimoCharacterCustomizer.PartSlot? previousWorldTargetSlot = selectedWorldColorTargetSlot;

        for (int i = 0; i < regions.Count; i++)
        {
            RegionEntry region = regions[i];
            if (region == null)
            {
                continue;
            }

            MinimoCharacterCustomizer.PartSlot[] candidateSlots = region.slots;
            int matchedSlotIndex = FindMatchedRegionSlotIndex(candidateSlots, regionMatchSlot);

            if (matchedSlotIndex < 0
                && TryGetSlotsForBodyRegion(region.name, out MinimoCharacterCustomizer.PartSlot[] resolvedSlotsByName)
                && resolvedSlotsByName.Length > 0)
            {
                candidateSlots = resolvedSlotsByName;
                matchedSlotIndex = FindMatchedRegionSlotIndex(candidateSlots, regionMatchSlot);
                if (matchedSlotIndex >= 0)
                {
                    // Keep region mapping in sync once we've resolved it from the name.
                    region.slots = candidateSlots;
                }
            }

            if (matchedSlotIndex < 0)
            {
                continue;
            }

            bool reselectedSameRegion = previousRegionIndex == i;
            bool hasMirroredPair = TryResolveMirroredSlotsForRegion(
                candidateSlots,
                out MinimoCharacterCustomizer.PartSlot mirroredLeftSlot,
                out MinimoCharacterCustomizer.PartSlot mirroredRightSlot);
            bool clickedMirroredSlot = hasMirroredPair
                                       && (selectedColorSlot == mirroredLeftSlot
                                           || selectedColorSlot == mirroredRightSlot);

            selectedRegionIndex = i;
            selectedWorldPreviewTargetSlot = selectedColorSlot;
            selectedWorldVariantTargetSlots = NormalizeWorldVariantTargetSlots(
                worldVariantTargetSlots,
                selectedColorSlot);
            if (preserveWorldLinkedSelection)
            {
                if (ShouldKeepMirroredWorldLinkedPairSelection(candidateSlots))
                {
                    selectedWorldColorTargetSlot = null;
                }
                else if (!selectedWorldColorTargetSlot.HasValue
                    || !SlotArrayContains(candidateSlots, selectedWorldColorTargetSlot.Value))
                {
                    selectedWorldColorTargetSlot = selectedColorSlot;
                }
            }
            else if (clickedMirroredSlot)
            {
                // World selection on mirrored parts toggles pair -> single on repeated clicks.
                bool wasPairedSelection = reselectedSameRegion && !previousWorldTargetSlot.HasValue;
                selectedWorldColorTargetSlot = wasPairedSelection
                    ? (MinimoCharacterCustomizer.PartSlot?)selectedColorSlot
                    : null;
            }
            else
            {
                selectedWorldColorTargetSlot = selectedColorSlot;
            }
            selectedColorChannelTarget = ColorChannelTargetType.Material;
            selectedFaceColorPropertyId = -1;
            hasExplicitPartSelection = true;
            if (!UseDualPartMode() && candidateSlots.Length > 1)
            {
                region.singleSlotIndex = matchedSlotIndex;
            }

            int channelCount = GetEditableColorChannelCountForSlot(selectedColorSlot);
            if (channelCount > 0)
            {
                if (preferredMaterialIndex >= 0)
                {
                    if (TryResolveColorChannelFromMaterialIndex(selectedColorSlot, preferredMaterialIndex, out int resolvedChannel))
                    {
                        selectedColorMaterialIndex = Mathf.Clamp(resolvedChannel, 0, channelCount - 1);
                    }
                    else
                    {
                        selectedColorMaterialIndex = Mathf.Clamp(selectedColorMaterialIndex, 0, channelCount - 1);
                    }
                }
                else
                {
                    selectedColorMaterialIndex = Mathf.Clamp(selectedColorMaterialIndex, 0, channelCount - 1);
                }
            }
            else
            {
                selectedColorMaterialIndex = 0;
            }

            SetCustomizationPanelVisible(true);

            RebuildVariantButtons(true);
            RefreshFromCustomizer();
            return;
        }
    }

    private bool ShouldAllowShadowPressWithoutTarget(Button button)
    {
        return button != null && !IsMaterialChannelStripButton(button);
    }

    private bool ShouldSkipShadowPressBottomAnimation(Button button)
    {
        if (button == null)
        {
            return false;
        }

        if (button == autoRotationButton
            || button == colorChartButton
            || button == savedPrefabsLeftArrowButton
            || button == savedPrefabsRightArrowButton)
        {
            return true;
        }

        if (IsColorPaletteButton(button)
            || IsColorChannelSelectionButton(button)
            || IsWorldLinkedSlotButtonName(button.gameObject.name))
        {
            return true;
        }

        string buttonName = button.gameObject != null ? button.gameObject.name : string.Empty;
        return string.Equals(buttonName, "LeftArrow", StringComparison.OrdinalIgnoreCase)
               || string.Equals(buttonName, "RightArrow", StringComparison.OrdinalIgnoreCase)
               || string.Equals(buttonName, "AutoRotate", StringComparison.OrdinalIgnoreCase)
               || string.Equals(buttonName, "AutoRotation", StringComparison.OrdinalIgnoreCase)
               || string.Equals(buttonName, "Color Chart", StringComparison.OrdinalIgnoreCase)
               || string.Equals(buttonName, "ColorChart", StringComparison.OrdinalIgnoreCase)
               || string.Equals(buttonName, "Color Wheel", StringComparison.OrdinalIgnoreCase)
               || string.Equals(buttonName, "ColorWheel", StringComparison.OrdinalIgnoreCase)
               || buttonName.StartsWith("Color_", StringComparison.Ordinal)
               || buttonName.StartsWith("ColorChannel_", StringComparison.Ordinal);
    }

    private bool IsColorPaletteButton(Button button)
    {
        if (button == null)
        {
            return false;
        }

        for (int i = 0; i < colorButtons.Count; i++)
        {
            if (colorButtons[i]?.button == button)
            {
                return true;
            }
        }

        return false;
    }

    private bool IsColorChannelSelectionButton(Button button)
    {
        if (button == null)
        {
            return false;
        }

        if (IsMaterialChannelStripButton(button))
        {
            return true;
        }

        for (int i = 0; i < colorChannelButtons.Count; i++)
        {
            if (colorChannelButtons[i]?.button == button)
            {
                return true;
            }
        }

        return false;
    }

    private bool IsMaterialChannelStripButton(Button button)
    {
        if (button == null || materialChannelStripRoot == null || button.transform == null)
        {
            return false;
        }

        return button.transform.IsChildOf(materialChannelStripRoot);
    }

    private bool ShouldKeepMirroredWorldLinkedPairSelection(MinimoCharacterCustomizer.PartSlot[] candidateSlots)
    {
        if (candidateSlots == null
            || candidateSlots.Length <= 1
            || !TryResolveMirroredSlotsForRegion(
                candidateSlots,
                out MinimoCharacterCustomizer.PartSlot mirroredLeftSlot,
                out MinimoCharacterCustomizer.PartSlot mirroredRightSlot)
            || !TryGetPersistedWorldLinkedSelectedSlots(
                out List<MinimoCharacterCustomizer.PartSlot> selectedSlots,
                requireMultiple: true))
        {
            return false;
        }

        return SlotListContains(selectedSlots, mirroredLeftSlot)
               && SlotListContains(selectedSlots, mirroredRightSlot);
    }

    private static bool SlotListContains(
        List<MinimoCharacterCustomizer.PartSlot> slots,
        MinimoCharacterCustomizer.PartSlot slot)
    {
        if (slots == null || slots.Count == 0)
        {
            return false;
        }

        for (int i = 0; i < slots.Count; i++)
        {
            if (slots[i] == slot)
            {
                return true;
            }
        }

        return false;
    }

    private void ResetWorldLinkedMaterialSelectionState()
    {
        worldLinkedMaterialSelectionKeyValid = false;
        worldLinkedMaterialSelectionKey = string.Empty;
        worldLinkedMaterialSingleOverrideActive = false;
        worldLastHoveredMaterialKey = string.Empty;
        worldLinkedMaterialTargetsSnapshot.Clear();
        worldLinkedSlotSelectionStates.Clear();
        worldLinkedSelectionUiSlotOrder.Clear();
        worldLinkedSlotSelectionKey = string.Empty;
    }

    private MinimoCharacterCustomizer.PartSlot[] ResolveWorldVariantTargetSlotsForClick(
        MinimoCharacterCustomizer.PartSlot slot,
        int preferredMaterialIndex)
    {
        if (slot == MinimoCharacterCustomizer.PartSlot.Props)
        {
            return Array.Empty<MinimoCharacterCustomizer.PartSlot>();
        }

        int resolvedMaterialIndex = ResolveMaterialIndexForSlot(slot, preferredMaterialIndex);
        Dictionary<MinimoCharacterCustomizer.PartSlot, HashSet<int>> hoveredTargets = resolvedMaterialIndex >= 0
            ? ResolveWorldHoverPreviewMaterialTargets(slot, resolvedMaterialIndex)
            : null;
        Dictionary<MinimoCharacterCustomizer.PartSlot, HashSet<int>> variantTargets =
            FilterWorldVariantTargetsForSelectionRule(slot, resolvedMaterialIndex, hoveredTargets);
        return NormalizeWorldVariantTargetSlots(variantTargets, slot);
    }

    private Dictionary<MinimoCharacterCustomizer.PartSlot, HashSet<int>> FilterWorldVariantTargetsForSelectionRule(
        MinimoCharacterCustomizer.PartSlot clickedSlot,
        int clickedMaterialIndex,
        Dictionary<MinimoCharacterCustomizer.PartSlot, HashSet<int>> colorTargets)
    {
        Dictionary<MinimoCharacterCustomizer.PartSlot, HashSet<int>> filtered = new Dictionary<MinimoCharacterCustomizer.PartSlot, HashSet<int>>();

        void AddSingleClickedSlot()
        {
            if (clickedSlot == MinimoCharacterCustomizer.PartSlot.Props)
            {
                return;
            }

            int materialIndex = clickedMaterialIndex >= 0
                ? clickedMaterialIndex
                : ResolveMaterialIndexForSlot(clickedSlot, clickedMaterialIndex);
            filtered[clickedSlot] = materialIndex >= 0
                ? new HashSet<int> { materialIndex }
                : new HashSet<int>();
        }

        if (IsHairSelectionSlot(clickedSlot) || IsFaceSelectionSlot(clickedSlot))
        {
            AddSingleClickedSlot();
            return filtered;
        }

        bool clickedSkin = clickedMaterialIndex >= 0
                           && TryGetEffectivePartColor(clickedSlot, clickedMaterialIndex, out Color clickedColor)
                           && IsSkinLinkedMaterialTarget(clickedSlot, clickedMaterialIndex, clickedColor);
        if (clickedSkin)
        {
            if (IsUpperBodySelectionSlot(clickedSlot))
            {
                CopyMatchingWorldVariantTargets(colorTargets, filtered, IsUpperBodySelectionSlot);
            }
            else if (IsLowerBodySelectionSlot(clickedSlot))
            {
                CopyMatchingWorldVariantTargets(colorTargets, filtered, IsLowerBodySelectionSlot);
            }

            if (filtered.Count == 0)
            {
                AddSingleClickedSlot();
            }

            return filtered;
        }

        if (IsUpperBodySelectionSlot(clickedSlot))
        {
            CopyMatchingWorldVariantTargets(colorTargets, filtered, IsUpperBodySelectionSlot);
        }
        else if (IsLowerBodySelectionSlot(clickedSlot))
        {
            CopyMatchingWorldVariantTargets(colorTargets, filtered, IsLowerBodySelectionSlot);
        }

        if (filtered.Count == 0)
        {
            AddSingleClickedSlot();
        }

        return filtered;
    }

    private static void CopyMatchingWorldVariantTargets(
        Dictionary<MinimoCharacterCustomizer.PartSlot, HashSet<int>> source,
        Dictionary<MinimoCharacterCustomizer.PartSlot, HashSet<int>> destination,
        Func<MinimoCharacterCustomizer.PartSlot, bool> predicate)
    {
        if (source == null || destination == null || predicate == null)
        {
            return;
        }

        foreach (KeyValuePair<MinimoCharacterCustomizer.PartSlot, HashSet<int>> pair in source)
        {
            if (!predicate(pair.Key) || pair.Value == null || pair.Value.Count == 0)
            {
                continue;
            }

            destination[pair.Key] = new HashSet<int>(pair.Value);
        }
    }

    private MinimoCharacterCustomizer.PartSlot[] NormalizeWorldVariantTargetSlots(
        Dictionary<MinimoCharacterCustomizer.PartSlot, HashSet<int>> targetMap,
        MinimoCharacterCustomizer.PartSlot fallbackSlot)
    {
        List<MinimoCharacterCustomizer.PartSlot> normalizedSlots = new List<MinimoCharacterCustomizer.PartSlot>();
        HashSet<MinimoCharacterCustomizer.PartSlot> addedSlots = new HashSet<MinimoCharacterCustomizer.PartSlot>();

        void AddSlot(MinimoCharacterCustomizer.PartSlot slot)
        {
            if (slot != MinimoCharacterCustomizer.PartSlot.Props && addedSlots.Add(slot))
            {
                normalizedSlots.Add(slot);
            }
        }

        if (targetMap != null && targetMap.Count > 0)
        {
            for (int i = 0; i < PartSelectionUiOrder.Length; i++)
            {
                MinimoCharacterCustomizer.PartSlot orderedSlot = PartSelectionUiOrder[i];
                if (targetMap.TryGetValue(orderedSlot, out HashSet<int> materialIndices)
                    && materialIndices != null
                    && materialIndices.Count > 0)
                {
                    AddSlot(orderedSlot);
                }
            }

            foreach (KeyValuePair<MinimoCharacterCustomizer.PartSlot, HashSet<int>> pair in targetMap)
            {
                if (pair.Value != null && pair.Value.Count > 0)
                {
                    AddSlot(pair.Key);
                }
            }
        }

        if (normalizedSlots.Count == 0)
        {
            AddSlot(fallbackSlot);
        }

        return normalizedSlots.Count > 0
            ? normalizedSlots.ToArray()
            : Array.Empty<MinimoCharacterCustomizer.PartSlot>();
    }

    private MinimoCharacterCustomizer.PartSlot[] NormalizeWorldVariantTargetSlots(
        MinimoCharacterCustomizer.PartSlot[] slots,
        MinimoCharacterCustomizer.PartSlot fallbackSlot)
    {
        List<MinimoCharacterCustomizer.PartSlot> normalizedSlots = new List<MinimoCharacterCustomizer.PartSlot>();
        HashSet<MinimoCharacterCustomizer.PartSlot> addedSlots = new HashSet<MinimoCharacterCustomizer.PartSlot>();

        void AddSlot(MinimoCharacterCustomizer.PartSlot slot)
        {
            if (slot != MinimoCharacterCustomizer.PartSlot.Props && addedSlots.Add(slot))
            {
                normalizedSlots.Add(slot);
            }
        }

        if (slots != null)
        {
            for (int orderIndex = 0; orderIndex < PartSelectionUiOrder.Length; orderIndex++)
            {
                MinimoCharacterCustomizer.PartSlot orderedSlot = PartSelectionUiOrder[orderIndex];
                for (int slotIndex = 0; slotIndex < slots.Length; slotIndex++)
                {
                    if (slots[slotIndex] == orderedSlot)
                    {
                        AddSlot(orderedSlot);
                        break;
                    }
                }
            }

            for (int i = 0; i < slots.Length; i++)
            {
                AddSlot(slots[i]);
            }
        }

        if (normalizedSlots.Count == 0)
        {
            AddSlot(fallbackSlot);
        }

        return normalizedSlots.Count > 0
            ? normalizedSlots.ToArray()
            : Array.Empty<MinimoCharacterCustomizer.PartSlot>();
    }

    private MinimoCharacterCustomizer.PartSlot[] GetSelectedWorldVariantTargetSlots()
    {
        return selectedWorldVariantTargetSlots != null && selectedWorldVariantTargetSlots.Length > 0
            ? selectedWorldVariantTargetSlots
            : Array.Empty<MinimoCharacterCustomizer.PartSlot>();
    }

    private bool HasSelectedWorldVariantTargetSlots()
    {
        return GetSelectedWorldVariantTargetSlots().Length > 0;
    }

    private string BuildSelectedWorldVariantTargetSlotSignature()
    {
        MinimoCharacterCustomizer.PartSlot[] slots = GetSelectedWorldVariantTargetSlots();
        if (slots.Length == 0)
        {
            return "none";
        }

        StringBuilder builder = new StringBuilder();
        for (int i = 0; i < slots.Length; i++)
        {
            if (i > 0)
            {
                builder.Append('_');
            }

            builder.Append(slots[i]);
        }

        return builder.ToString();
    }

    private bool TryApplyWorldLinkedSelectionFromHoverState(
        MinimoCharacterCustomizer.PartSlot slot,
        int preferredMaterialIndex,
        out bool forceSingleWorldMaterialSelection)
    {
        forceSingleWorldMaterialSelection = false;
        if (customizer == null)
        {
            return false;
        }

        int resolvedMaterialIndex = ResolveMaterialIndexForSlot(slot, preferredMaterialIndex);
        if (resolvedMaterialIndex < 0)
        {
            return false;
        }

        Dictionary<MinimoCharacterCustomizer.PartSlot, HashSet<int>> hoveredTargets =
            ResolveHoveredMaterialTargets(
                slot,
                resolvedMaterialIndex,
                allowHistoryFocus: IsActiveWorldLinkedSelectionSlot(slot));
        if (hoveredTargets == null || hoveredTargets.Count == 0)
        {
            return false;
        }

        Dictionary<MinimoCharacterCustomizer.PartSlot, HashSet<int>> normalizedTargets = new Dictionary<MinimoCharacterCustomizer.PartSlot, HashSet<int>>();
        foreach (KeyValuePair<MinimoCharacterCustomizer.PartSlot, HashSet<int>> pair in hoveredTargets)
        {
            if (pair.Value == null || pair.Value.Count == 0)
            {
                continue;
            }

            normalizedTargets[pair.Key] = new HashSet<int>(pair.Value);
        }

        if (normalizedTargets.Count == 0)
        {
            return false;
        }

        string materialKey = string.Empty;
        if (!TryGetWorldLinkedMaterialKey(slot, resolvedMaterialIndex, out materialKey))
        {
            foreach (KeyValuePair<MinimoCharacterCustomizer.PartSlot, HashSet<int>> pair in normalizedTargets)
            {
                int firstMaterialIndex = -1;
                foreach (int materialIndex in pair.Value)
                {
                    firstMaterialIndex = materialIndex;
                    break;
                }

                if (firstMaterialIndex < 0)
                {
                    continue;
                }

                if (TryGetWorldLinkedMaterialKey(pair.Key, firstMaterialIndex, out materialKey))
                {
                    break;
                }
            }
        }

        if (string.IsNullOrWhiteSpace(materialKey))
        {
            return false;
        }

        bool enteringNewLinkedGroup = !worldLinkedMaterialSelectionKeyValid
                                      || !string.Equals(
                                          worldLinkedMaterialSelectionKey,
                                          materialKey,
                                          StringComparison.OrdinalIgnoreCase);
        if (enteringNewLinkedGroup)
        {
            worldLinkedSelectionUiSlotOrder.Clear();
        }

        worldLinkedMaterialSelectionKey = materialKey;
        worldLinkedMaterialSelectionKeyValid = true;
        worldLinkedSlotSelectionKey = materialKey;
        worldLinkedMaterialTargetsSnapshot.Clear();
        CopyWorldLinkedMaterialTargets(normalizedTargets, worldLinkedMaterialTargetsSnapshot);
        SetWorldLinkedSlotSelectionStateForGroup(
            materialKey,
            normalizedTargets,
            slot,
            focusOnly: false,
            preserveExistingForSameKey: false);

        int selectedCount = CountSelectedWorldLinkedSlots(normalizedTargets);
        worldLinkedMaterialSingleOverrideActive = selectedCount <= 1;
        forceSingleWorldMaterialSelection = worldLinkedMaterialSingleOverrideActive;

        if (IsWorldLinkedSlotSelected(slot))
        {
            selectedWorldColorTargetSlot = slot;
        }
        else if (TryGetFirstSelectedWorldLinkedSlot(normalizedTargets, out MinimoCharacterCustomizer.PartSlot fallbackSelectedSlot))
        {
            selectedWorldColorTargetSlot = fallbackSelectedSlot;
        }

        RegisterWorldLinkedMaterialSelectionHistory(materialKey, slot);
        worldLastHoveredMaterialKey = materialKey;
        return true;
    }

    private void UpdateWorldLinkedMaterialSelectionStateFromClick(
        MinimoCharacterCustomizer.PartSlot slot,
        int preferredMaterialIndex,
        out bool forceSingleWorldMaterialSelection)
    {
        forceSingleWorldMaterialSelection = false;
        if (customizer == null)
        {
            ResetWorldLinkedMaterialSelectionState();
            return;
        }

        int resolvedMaterialIndex = ResolveMaterialIndexForSlot(slot, preferredMaterialIndex);
        if (!TryGetWorldLinkedMaterialKey(slot, resolvedMaterialIndex, out string materialKey))
        {
            ResetWorldLinkedMaterialSelectionState();
            return;
        }

        if (!TryBuildWorldLinkedMaterialTargetsByKey(materialKey, out Dictionary<MinimoCharacterCustomizer.PartSlot, HashSet<int>> linkedTargets)
            || linkedTargets.Count <= 1)
        {
            ResetWorldLinkedMaterialSelectionState();
            return;
        }

        bool sameLinkedGroup = worldLinkedMaterialSelectionKeyValid
                               && string.Equals(worldLinkedMaterialSelectionKey, materialKey, StringComparison.OrdinalIgnoreCase);
        if (!sameLinkedGroup)
        {
            worldLinkedSelectionUiSlotOrder.Clear();
        }

        bool clickedActiveSelectionSlot = sameLinkedGroup && IsActiveWorldLinkedSelectionSlot(slot);
        bool hasPriorNonMirroredSelection = HasPriorNonMirroredSelectionForMaterialKey(materialKey, slot);
        if (clickedActiveSelectionSlot && hasPriorNonMirroredSelection)
        {
            Dictionary<MinimoCharacterCustomizer.PartSlot, HashSet<int>> selectionTargets =
                worldLinkedMaterialTargetsSnapshot.Count > 1
                    ? CloneWorldLinkedMaterialTargets(worldLinkedMaterialTargetsSnapshot)
                    : linkedTargets;
            if (worldLinkedMaterialTargetsSnapshot.Count <= 1)
            {
                worldLinkedMaterialTargetsSnapshot.Clear();
                CopyWorldLinkedMaterialTargets(linkedTargets, worldLinkedMaterialTargetsSnapshot);
            }

            SetWorldLinkedSlotSelectionStateForGroup(
                materialKey,
                selectionTargets,
                slot,
                focusOnly: true,
                preserveExistingForSameKey: false);
            worldLinkedMaterialSingleOverrideActive = true;
            forceSingleWorldMaterialSelection = true;
            RegisterWorldLinkedMaterialSelectionHistory(materialKey, slot);
            return;
        }

        worldLinkedMaterialSelectionKeyValid = true;
        worldLinkedMaterialSelectionKey = materialKey;
        worldLinkedMaterialSingleOverrideActive = false;
        worldLinkedMaterialTargetsSnapshot.Clear();
        CopyWorldLinkedMaterialTargets(linkedTargets, worldLinkedMaterialTargetsSnapshot);
        SetWorldLinkedSlotSelectionStateForGroup(
            materialKey,
            linkedTargets,
            slot,
            focusOnly: false,
            preserveExistingForSameKey: false);
        RegisterWorldLinkedMaterialSelectionHistory(materialKey, slot);
    }

    private bool TryGetWorldLinkedMaterialKey(
        MinimoCharacterCustomizer.PartSlot slot,
        int materialIndex,
        out string key)
    {
        key = string.Empty;
        if (customizer == null
            || materialIndex < 0
            || !customizer.TryGetPartRenderer(slot, out SkinnedMeshRenderer renderer)
            || renderer == null)
        {
            return false;
        }

        Material[] materials = renderer.sharedMaterials;
        int materialCount = GetEffectiveRendererMaterialSlotCount(renderer, materials);
        if (materials == null || materialIndex >= materialCount)
        {
            return false;
        }

        Material material = materials[materialIndex];
        if (!MaterialSupportsColor(material))
        {
            return false;
        }

        if (!TryGetEffectivePartColor(slot, materialIndex, out Color color))
        {
            return false;
        }

        key = BuildWorldLinkedMaterialColorKey(slot, materialIndex, color);
        return !string.IsNullOrWhiteSpace(key);
    }

    private bool TryBuildWorldLinkedMaterialKeyForColor(
        MinimoCharacterCustomizer.PartSlot slot,
        int materialIndex,
        Color color,
        out string key)
    {
        key = string.Empty;
        if (materialIndex < 0 || !TryGetMaterialForSlot(slot, materialIndex, out Material material) || !MaterialSupportsColor(material))
        {
            return false;
        }

        key = BuildWorldLinkedMaterialColorKey(slot, materialIndex, color);
        return !string.IsNullOrWhiteSpace(key);
    }

    private bool TryBuildWorldLinkedMaterialKeyForColor(
        Dictionary<MinimoCharacterCustomizer.PartSlot, HashSet<int>> targets,
        Color color,
        out string key)
    {
        key = string.Empty;
        if (targets == null || targets.Count == 0)
        {
            return false;
        }

        if (selectedWorldColorTargetSlot.HasValue
            && targets.TryGetValue(selectedWorldColorTargetSlot.Value, out HashSet<int> selectedIndices)
            && TryGetFirstMaterialIndex(selectedIndices, out int selectedMaterialIndex)
            && TryBuildWorldLinkedMaterialKeyForColor(selectedWorldColorTargetSlot.Value, selectedMaterialIndex, color, out key))
        {
            return true;
        }

        foreach (KeyValuePair<MinimoCharacterCustomizer.PartSlot, HashSet<int>> pair in targets)
        {
            if (!TryGetFirstMaterialIndex(pair.Value, out int materialIndex))
            {
                continue;
            }

            if (TryBuildWorldLinkedMaterialKeyForColor(pair.Key, materialIndex, color, out key))
            {
                return true;
            }
        }

        return false;
    }

    private static bool TryGetFirstMaterialIndex(HashSet<int> indices, out int materialIndex)
    {
        materialIndex = -1;
        if (indices == null || indices.Count == 0)
        {
            return false;
        }

        foreach (int index in indices)
        {
            materialIndex = index;
            return materialIndex >= 0;
        }

        return false;
    }

    private string BuildWorldLinkedMaterialColorKey(
        MinimoCharacterCustomizer.PartSlot slot,
        int materialIndex,
        Color color)
    {
        string groupKey = ResolveWorldLinkedMaterialGroupKey(slot, materialIndex, color);
        return BuildWorldLinkedMaterialColorKey(color, groupKey);
    }

    private string ResolveWorldLinkedMaterialGroupKey(
        MinimoCharacterCustomizer.PartSlot slot,
        int materialIndex,
        Color color)
    {
        if (IsSkinLinkedMaterialTarget(slot, materialIndex, color))
        {
            return "skin";
        }

        return ResolveWorldLinkedNonSkinMaterialGroupKey(slot);
    }

    private static bool IsHairSelectionSlot(MinimoCharacterCustomizer.PartSlot slot)
    {
        return slot == MinimoCharacterCustomizer.PartSlot.Hair;
    }

    private static bool IsFaceSelectionSlot(MinimoCharacterCustomizer.PartSlot slot)
    {
        return slot == MinimoCharacterCustomizer.PartSlot.Face;
    }

    private static bool IsUpperBodySelectionSlot(MinimoCharacterCustomizer.PartSlot slot)
    {
        switch (slot)
        {
            case MinimoCharacterCustomizer.PartSlot.Torso:
            case MinimoCharacterCustomizer.PartSlot.ShoulderLeft:
            case MinimoCharacterCustomizer.PartSlot.ShoulderRight:
            case MinimoCharacterCustomizer.PartSlot.ArmLeft:
            case MinimoCharacterCustomizer.PartSlot.ArmRight:
            case MinimoCharacterCustomizer.PartSlot.HandLeft:
            case MinimoCharacterCustomizer.PartSlot.HandRight:
                return true;
            default:
                return false;
        }
    }

    private static bool IsLowerBodySelectionSlot(MinimoCharacterCustomizer.PartSlot slot)
    {
        switch (slot)
        {
            case MinimoCharacterCustomizer.PartSlot.Hips:
            case MinimoCharacterCustomizer.PartSlot.LegUpperLeft:
            case MinimoCharacterCustomizer.PartSlot.LegUpperRight:
            case MinimoCharacterCustomizer.PartSlot.BootsLeft:
            case MinimoCharacterCustomizer.PartSlot.BootsRight:
                return true;
            default:
                return false;
        }
    }

    private bool IsSkinLinkedMaterialTarget(
        MinimoCharacterCustomizer.PartSlot slot,
        int materialIndex,
        Color color)
    {
        if (IsHairSelectionSlot(slot))
        {
            return false;
        }

        if (IsSkinMaterialTarget(slot, materialIndex))
        {
            return true;
        }

        return TryGetCurrentSkinToneColor(out Color skinToneColor)
               && ColorsNearlyEqual(color, skinToneColor);
    }

    private static string ResolveWorldLinkedNonSkinMaterialGroupKey(MinimoCharacterCustomizer.PartSlot slot)
    {
        if (IsUpperBodySelectionSlot(slot))
        {
            return "upper";
        }

        if (IsLowerBodySelectionSlot(slot))
        {
            return "lower";
        }

        return $"slot:{slot}";
    }

    private static string BuildWorldLinkedMaterialColorKey(Color color, string groupKey)
    {
        int r = Mathf.RoundToInt(Mathf.Clamp01(color.r) * 255f);
        int g = Mathf.RoundToInt(Mathf.Clamp01(color.g) * 255f);
        int b = Mathf.RoundToInt(Mathf.Clamp01(color.b) * 255f);
        int a = Mathf.RoundToInt(Mathf.Clamp01(color.a) * 255f);
        string safeGroupKey = string.IsNullOrWhiteSpace(groupKey) ? "other" : groupKey.Trim().ToLowerInvariant();
        return $"{safeGroupKey}|{r:D3}_{g:D3}_{b:D3}_{a:D3}";
    }

    private bool HasPriorNonMirroredSelectionForMaterialKey(
        string materialKey,
        MinimoCharacterCustomizer.PartSlot slot)
    {
        if (string.IsNullOrWhiteSpace(materialKey)
            || !worldLinkedMaterialSelectionHistory.TryGetValue(materialKey, out HashSet<MinimoCharacterCustomizer.PartSlot> history)
            || history == null
            || history.Count == 0)
        {
            return false;
        }

        foreach (MinimoCharacterCustomizer.PartSlot historySlot in history)
        {
            if (historySlot == slot || AreMirroredCounterpartSlots(historySlot, slot))
            {
                continue;
            }

            return true;
        }

        return false;
    }

    private bool HasSelectionHistoryForMaterialKey(string materialKey)
    {
        return !string.IsNullOrWhiteSpace(materialKey)
               && worldLinkedMaterialSelectionHistory.TryGetValue(materialKey, out HashSet<MinimoCharacterCustomizer.PartSlot> history)
               && history != null
               && history.Count > 0;
    }

    private bool HasMultipleActiveWorldLinkedSelectionsForMaterialKey(string materialKey)
    {
        if (string.IsNullOrWhiteSpace(materialKey)
            || !worldLinkedMaterialSelectionKeyValid
            || !IsWorldLinkedSlotSelectionStateValidForCurrentKey()
            || !string.Equals(worldLinkedMaterialSelectionKey, materialKey, StringComparison.OrdinalIgnoreCase)
            || worldLinkedSlotSelectionStates.Count == 0)
        {
            return false;
        }

        int selectedCount = 0;
        foreach (KeyValuePair<MinimoCharacterCustomizer.PartSlot, bool> pair in worldLinkedSlotSelectionStates)
        {
            if (!pair.Value)
            {
                continue;
            }

            selectedCount++;
            if (selectedCount > 1)
            {
                return true;
            }
        }

        return false;
    }

    private void RegisterWorldLinkedMaterialSelectionHistory(
        string materialKey,
        MinimoCharacterCustomizer.PartSlot slot)
    {
        if (string.IsNullOrWhiteSpace(materialKey))
        {
            return;
        }

        if (!worldLinkedMaterialSelectionHistory.TryGetValue(materialKey, out HashSet<MinimoCharacterCustomizer.PartSlot> history)
            || history == null)
        {
            history = new HashSet<MinimoCharacterCustomizer.PartSlot>();
            worldLinkedMaterialSelectionHistory[materialKey] = history;
        }

        history.Add(slot);
    }

    private bool HasMirroredPairSelectionHistoryForMaterialKey(
        string materialKey,
        MinimoCharacterCustomizer.PartSlot mirroredLeftSlot,
        MinimoCharacterCustomizer.PartSlot mirroredRightSlot)
    {
        if (string.IsNullOrWhiteSpace(materialKey)
            || !worldLinkedMirroredPairSelectionHistory.TryGetValue(materialKey, out HashSet<string> pairHistory)
            || pairHistory == null
            || pairHistory.Count == 0)
        {
            return false;
        }

        string pairKey = BuildMirroredPairHistoryKey(mirroredLeftSlot, mirroredRightSlot);
        return pairHistory.Contains(pairKey);
    }

    private void RegisterMirroredPairSelectionHistoryForMaterialKey(
        string materialKey,
        MinimoCharacterCustomizer.PartSlot mirroredLeftSlot,
        MinimoCharacterCustomizer.PartSlot mirroredRightSlot)
    {
        if (string.IsNullOrWhiteSpace(materialKey))
        {
            return;
        }

        if (!worldLinkedMirroredPairSelectionHistory.TryGetValue(materialKey, out HashSet<string> pairHistory)
            || pairHistory == null)
        {
            pairHistory = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            worldLinkedMirroredPairSelectionHistory[materialKey] = pairHistory;
        }

        pairHistory.Add(BuildMirroredPairHistoryKey(mirroredLeftSlot, mirroredRightSlot));
    }

    private static string BuildMirroredPairHistoryKey(
        MinimoCharacterCustomizer.PartSlot mirroredLeftSlot,
        MinimoCharacterCustomizer.PartSlot mirroredRightSlot)
    {
        string first = mirroredLeftSlot.ToString();
        string second = mirroredRightSlot.ToString();
        if (string.Compare(first, second, StringComparison.OrdinalIgnoreCase) > 0)
        {
            (first, second) = (second, first);
        }

        return $"{first}|{second}";
    }

    private static bool AreMirroredCounterpartSlots(
        MinimoCharacterCustomizer.PartSlot first,
        MinimoCharacterCustomizer.PartSlot second)
    {
        return IsMirroredPair(first, second, MinimoCharacterCustomizer.PartSlot.ShoulderLeft, MinimoCharacterCustomizer.PartSlot.ShoulderRight)
               || IsMirroredPair(first, second, MinimoCharacterCustomizer.PartSlot.ArmLeft, MinimoCharacterCustomizer.PartSlot.ArmRight)
               || IsMirroredPair(first, second, MinimoCharacterCustomizer.PartSlot.HandLeft, MinimoCharacterCustomizer.PartSlot.HandRight)
               || IsMirroredPair(first, second, MinimoCharacterCustomizer.PartSlot.LegUpperLeft, MinimoCharacterCustomizer.PartSlot.LegUpperRight)
               || IsMirroredPair(first, second, MinimoCharacterCustomizer.PartSlot.BootsLeft, MinimoCharacterCustomizer.PartSlot.BootsRight);
    }

    private static bool IsMirroredPair(
        MinimoCharacterCustomizer.PartSlot first,
        MinimoCharacterCustomizer.PartSlot second,
        MinimoCharacterCustomizer.PartSlot left,
        MinimoCharacterCustomizer.PartSlot right)
    {
        return (first == left && second == right) || (first == right && second == left);
    }

    private bool TryBuildWorldLinkedMaterialTargetsByKey(
        string materialKey,
        out Dictionary<MinimoCharacterCustomizer.PartSlot, HashSet<int>> targets)
    {
        targets = new Dictionary<MinimoCharacterCustomizer.PartSlot, HashSet<int>>();
        if (string.IsNullOrWhiteSpace(materialKey) || customizer == null)
        {
            return false;
        }

        IReadOnlyList<MinimoCharacterCustomizer.PartSlot> slots = MinimoCharacterCustomizer.Slots;
        for (int i = 0; i < slots.Count; i++)
        {
            MinimoCharacterCustomizer.PartSlot slot = slots[i];
            if (!customizer.TryGetPartRenderer(slot, out SkinnedMeshRenderer renderer) || renderer == null)
            {
                continue;
            }

            Material[] materials = renderer.sharedMaterials;
            if (materials == null || materials.Length == 0)
            {
                continue;
            }

            HashSet<int> slotMatches = null;
            int materialCount = GetEffectiveRendererMaterialSlotCount(renderer, materials);
            for (int materialIndex = 0; materialIndex < materialCount; materialIndex++)
            {
                if (!TryGetWorldLinkedMaterialKey(slot, materialIndex, out string candidateKey)
                    || !string.Equals(candidateKey, materialKey, StringComparison.OrdinalIgnoreCase))
                {
                    continue;
                }

                slotMatches ??= new HashSet<int>();
                slotMatches.Add(materialIndex);
            }

            if (slotMatches != null && slotMatches.Count > 0)
            {
                targets[slot] = slotMatches;
            }
        }

        return targets.Count > 0;
    }

    private static MinimoCharacterCustomizer.PartSlot ResolveRegionAnchorSlotForWorldSelection(
        MinimoCharacterCustomizer.PartSlot slot)
    {
        switch (slot)
        {
            case MinimoCharacterCustomizer.PartSlot.ShoulderLeft:
                return MinimoCharacterCustomizer.PartSlot.ShoulderRight;
            case MinimoCharacterCustomizer.PartSlot.ArmLeft:
                return MinimoCharacterCustomizer.PartSlot.ArmRight;
            case MinimoCharacterCustomizer.PartSlot.HandLeft:
                return MinimoCharacterCustomizer.PartSlot.HandRight;
            case MinimoCharacterCustomizer.PartSlot.LegUpperLeft:
                return MinimoCharacterCustomizer.PartSlot.LegUpperRight;
            case MinimoCharacterCustomizer.PartSlot.BootsLeft:
                return MinimoCharacterCustomizer.PartSlot.BootsRight;
            default:
                return slot;
        }
    }

    private void SelectPropsRegionFromWorldSelection(int preferredColorChannelIndex, string preferredPropRigName)
    {
        ResetWorldLinkedMaterialSelectionState();

        for (int i = 0; i < regions.Count; i++)
        {
            RegionEntry region = regions[i];
            if (region == null)
            {
                continue;
            }

            string regionName = NormalizeBodyRegionKey(region.name);
            string buttonName = region.button != null
                ? NormalizeBodyRegionKey(region.button.name)
                : string.Empty;
            if (!RegionNameContainsToken(regionName, "PROP")
                && !RegionNameContainsToken(buttonName, "PROP"))
            {
                continue;
            }

            selectedRegionIndex = i;
            selectedWorldColorTargetSlot = null;
            selectedWorldPreviewTargetSlot = null;
            selectedWorldVariantTargetSlots = Array.Empty<MinimoCharacterCustomizer.PartSlot>();
            selectedColorChannelTarget = ColorChannelTargetType.Material;
            selectedFaceColorPropertyId = -1;
            hasExplicitPartSelection = true;

            if (!string.IsNullOrWhiteSpace(preferredPropRigName))
            {
                selectedPropRigName = preferredPropRigName;
            }
            else if (string.IsNullOrWhiteSpace(selectedPropRigName)
                     && TryGetSelectedPropInstance(out Transform selectedProp)
                     && selectedProp != null
                     && selectedProp.parent != null)
            {
                selectedPropRigName = selectedProp.parent.name;
            }

            List<PropMaterialChannel> channels = BuildColorChannelDescriptorsForSelectedProp();
            if (channels.Count > 0)
            {
                selectedColorMaterialIndex = Mathf.Clamp(
                    preferredColorChannelIndex >= 0 ? preferredColorChannelIndex : selectedColorMaterialIndex,
                    0,
                    channels.Count - 1);
            }
            else
            {
                selectedColorMaterialIndex = 0;
            }

            SetCustomizationPanelVisible(true);
            RebuildVariantButtons(true);
            RefreshFromCustomizer();
            return;
        }
    }

    private static int FindMatchedRegionSlotIndex(
        MinimoCharacterCustomizer.PartSlot[] slots,
        MinimoCharacterCustomizer.PartSlot targetSlot)
    {
        if (slots == null || slots.Length == 0)
        {
            return -1;
        }

        for (int i = 0; i < slots.Length; i++)
        {
            if (slots[i] == targetSlot)
            {
                return i;
            }
        }

        return -1;
    }

    private bool TryGetHoveredWorldTargetFromMouse(
        out MinimoCharacterCustomizer.PartSlot slot,
        out int materialIndex,
        out string propRigName,
        out Vector3 selectedWorldHitPoint)
    {
        slot = default;
        materialIndex = -1;
        propRigName = string.Empty;
        selectedWorldHitPoint = Vector3.zero;
        if (customizationCamera == null)
        {
            return false;
        }

        Ray ray = hasWorldHoverRay
            ? worldHoverRay
            : customizationCamera.ScreenPointToRay(MinimoInputBridge.MousePosition);
        const float hoverRaycastMaxDistance = 500f;
        bool found = false;
        float closestWorldDistance = float.MaxValue;
        MinimoCharacterCustomizer.PartSlot closestSlot = default;
        int closestMaterialIndex = -1;
        string closestPropRigName = string.Empty;
        Vector3 closestWorldHitPoint = Vector3.zero;
        IReadOnlyList<MinimoCharacterCustomizer.PartSlot> slots = MinimoCharacterCustomizer.Slots;
        const float epsilon = 0.000001f;

        for (int i = 0; i < slots.Count; i++)
        {
            MinimoCharacterCustomizer.PartSlot candidateSlot = slots[i];
            if (!TryGetHoveredMaterialIndexFromRay(
                    candidateSlot,
                    ray,
                    out int candidateMaterialIndex,
                    out Vector3 candidateWorldHitPoint,
                    out float candidateWorldDistance))
            {
                continue;
            }

            if (candidateWorldDistance < 0f || candidateWorldDistance > hoverRaycastMaxDistance)
            {
                continue;
            }

            bool isCloser = candidateWorldDistance < closestWorldDistance - epsilon;
            if (!found || isCloser)
            {
                found = true;
                closestWorldDistance = candidateWorldDistance;
                closestSlot = candidateSlot;
                closestMaterialIndex = candidateMaterialIndex;
                closestPropRigName = string.Empty;
                closestWorldHitPoint = candidateWorldHitPoint;
            }
        }

        if (TryGetHoveredPropTargetFromRay(
                ray,
                out string candidatePropRigName,
                out int candidatePropChannelIndex,
                out Vector3 candidatePropWorldHitPoint,
                out float candidatePropWorldDistance)
            && candidatePropWorldDistance >= 0f
            && candidatePropWorldDistance <= hoverRaycastMaxDistance)
        {
            bool isCloserProp = candidatePropWorldDistance < closestWorldDistance - epsilon;
            if (!found || isCloserProp)
            {
                found = true;
                closestWorldDistance = candidatePropWorldDistance;
                closestSlot = MinimoCharacterCustomizer.PartSlot.Props;
                closestMaterialIndex = candidatePropChannelIndex;
                closestPropRigName = candidatePropRigName ?? string.Empty;
                closestWorldHitPoint = candidatePropWorldHitPoint;
            }
        }

        if (!found)
        {
            return false;
        }

        slot = closestSlot;
        materialIndex = closestMaterialIndex;
        propRigName = closestPropRigName;
        selectedWorldHitPoint = closestWorldHitPoint;
        return true;
    }

    private bool TryGetHoveredMaterialIndexFromRay(
        MinimoCharacterCustomizer.PartSlot slot,
        Ray worldRay,
        out int materialIndex,
        out Vector3 bestWorldHitPoint,
        out float bestWorldDistance)
    {
        materialIndex = -1;
        bestWorldHitPoint = worldRay.origin;
        bestWorldDistance = float.MaxValue;
        if (!customizer.TryGetPartRenderer(slot, out SkinnedMeshRenderer renderer) || renderer == null)
        {
            return false;
        }

        return TryGetHoveredMaterialIndexFromRenderer(
            renderer,
            worldRay,
            out materialIndex,
            out bestWorldHitPoint,
            out bestWorldDistance);
    }

    private bool TryGetHoveredPropTargetFromRay(
        Ray worldRay,
        out string rigName,
        out int propColorChannelIndex,
        out Vector3 bestWorldHitPoint,
        out float bestWorldDistance)
    {
        rigName = string.Empty;
        propColorChannelIndex = -1;
        bestWorldHitPoint = worldRay.origin;
        bestWorldDistance = float.MaxValue;
        if (customizer == null)
        {
            return false;
        }

        bool found = false;
        Transform[] transforms = customizer.GetComponentsInChildren<Transform>(true);
        for (int i = 0; i < transforms.Length; i++)
        {
            Transform rig = transforms[i];
            if (rig == null)
            {
                continue;
            }

            Transform propRoot = FindFirstPropChild(rig);
            if (propRoot == null)
            {
                continue;
            }

            Transform visualRoot = ResolvePropVisualStateRoot(propRoot);
            if (visualRoot == null)
            {
                continue;
            }

            Renderer[] renderers = visualRoot.GetComponentsInChildren<Renderer>(true);
            for (int rendererIndex = 0; rendererIndex < renderers.Length; rendererIndex++)
            {
                Renderer renderer = renderers[rendererIndex];
                if (renderer == null || (!(renderer is SkinnedMeshRenderer) && !(renderer is MeshRenderer)))
                {
                    continue;
                }

                if (!TryGetHoveredMaterialIndexFromRenderer(
                        renderer,
                        worldRay,
                        out int materialIndex,
                        out Vector3 candidateHitPoint,
                        out float candidateDistance))
                {
                    continue;
                }

                if (!TryResolvePropColorChannelIndex(rig.name, renderer, materialIndex, out int channelIndex))
                {
                    continue;
                }

                const float epsilon = 0.000001f;
                bool isCloser = candidateDistance < bestWorldDistance - epsilon;
                if (!found || isCloser)
                {
                    found = true;
                    bestWorldDistance = candidateDistance;
                    bestWorldHitPoint = candidateHitPoint;
                    rigName = rig.name;
                    propColorChannelIndex = channelIndex;
                }
            }
        }

        return found;
    }

    private bool TryGetHoveredMaterialIndexFromRenderer(
        Renderer renderer,
        Ray worldRay,
        out int materialIndex,
        out Vector3 bestWorldHitPoint,
        out float bestWorldDistance)
    {
        materialIndex = -1;
        bestWorldHitPoint = worldRay.origin;
        bestWorldDistance = float.MaxValue;
        if (renderer == null || !renderer.enabled || !renderer.gameObject.activeInHierarchy)
        {
            return false;
        }

        Mesh mesh = null;
        if (renderer is SkinnedMeshRenderer skinnedRenderer)
        {
            if (skinnedRenderer.sharedMesh == null)
            {
                return false;
            }

            mesh = GetOrCreateWorldPartHoverRaycastMesh(skinnedRenderer);
            skinnedRenderer.BakeMesh(mesh, true);
        }
        else if (renderer is MeshRenderer)
        {
            if (!renderer.TryGetComponent(out MeshFilter meshFilter) || meshFilter == null || meshFilter.sharedMesh == null)
            {
                return false;
            }

            mesh = meshFilter.sharedMesh;
        }

        if (mesh == null)
        {
            return false;
        }

        Vector3[] vertices = mesh.vertices;
        if (vertices == null || vertices.Length < 3)
        {
            return false;
        }

        Matrix4x4 worldToLocal = renderer.transform.worldToLocalMatrix;
        Ray localRay = new Ray(
            worldToLocal.MultiplyPoint(worldRay.origin),
            worldToLocal.MultiplyVector(worldRay.direction).normalized);

        float closestWorldDistance = float.MaxValue;
        int bestSubMeshIndex = -1;
        Vector3 closestWorldHitPoint = worldRay.origin;
        int subMeshCount = Mathf.Min(
            mesh.subMeshCount,
            renderer.sharedMaterials != null ? renderer.sharedMaterials.Length : mesh.subMeshCount);
        for (int s = 0; s < subMeshCount; s++)
        {
            int[] indices = mesh.GetTriangles(s);
            if (indices == null || indices.Length < 3)
            {
                continue;
            }

            for (int t = 0; t + 2 < indices.Length; t += 3)
            {
                int i0 = indices[t];
                int i1 = indices[t + 1];
                int i2 = indices[t + 2];
                if (i0 < 0 || i1 < 0 || i2 < 0 || i0 >= vertices.Length || i1 >= vertices.Length || i2 >= vertices.Length)
                {
                    continue;
                }

                if (!TryRaycastTriangle(localRay, vertices[i0], vertices[i1], vertices[i2], out float distance))
                {
                    continue;
                }

                Vector3 localHit = localRay.origin + localRay.direction * distance;
                Vector3 worldHit = renderer.transform.TransformPoint(localHit);
                float worldDistance = Vector3.Dot(worldHit - worldRay.origin, worldRay.direction);
                if (worldDistance < 0f)
                {
                    continue;
                }

                const float epsilon = 0.0000001f;
                bool betterDistance = worldDistance < closestWorldDistance - epsilon;
                bool shouldUpdate = bestSubMeshIndex < 0 || betterDistance;
                if (!shouldUpdate)
                {
                    continue;
                }

                closestWorldDistance = worldDistance;
                closestWorldHitPoint = worldHit;
                bestSubMeshIndex = s;
            }
        }

        if (bestSubMeshIndex < 0)
        {
            return false;
        }

        materialIndex = bestSubMeshIndex;
        bestWorldHitPoint = closestWorldHitPoint;
        bestWorldDistance = closestWorldDistance;
        return true;
    }

    private static bool TryRaycastTriangle(
        Ray ray,
        Vector3 v0,
        Vector3 v1,
        Vector3 v2,
        out float distance)
    {
        distance = 0f;

        Vector3 edge1 = v1 - v0;
        Vector3 edge2 = v2 - v0;
        Vector3 p = Vector3.Cross(ray.direction, edge2);
        float det = Vector3.Dot(edge1, p);
        const float epsilon = 0.000001f;
        if (Mathf.Abs(det) < epsilon)
        {
            return false;
        }

        float invDet = 1f / det;
        Vector3 t = ray.origin - v0;
        float u = Vector3.Dot(t, p) * invDet;
        if (u < 0f || u > 1f)
        {
            return false;
        }

        Vector3 q = Vector3.Cross(t, edge1);
        float v = Vector3.Dot(ray.direction, q) * invDet;
        if (v < 0f || u + v > 1f)
        {
            return false;
        }

        float hitDistance = Vector3.Dot(edge2, q) * invDet;
        if (hitDistance < epsilon)
        {
            return false;
        }

        distance = hitDistance;
        return true;
    }

    private Mesh GetOrCreateWorldPartHoverRaycastMesh(SkinnedMeshRenderer renderer)
    {
        if (renderer == null)
        {
            return null;
        }

        if (worldPartHoverRaycastMeshes.TryGetValue(renderer, out Mesh mesh) && mesh != null)
        {
            return mesh;
        }

        mesh = new Mesh
        {
            name = $"MinimoHoverRayMesh_{renderer.name}"
        };
        worldPartHoverRaycastMeshes[renderer] = mesh;
        return mesh;
    }

    private bool IsRotationInputCaptured()
    {
        if (dragRotate == null && customizer != null)
        {
            dragRotate = customizer.GetComponent<MinimoCharacterDragRotate>();
        }

        return dragRotate != null && dragRotate.IsPointerCaptured;
    }

    private float GetWorldPartClickMaxDragPixels()
    {
        float clickThreshold = Mathf.Max(0f, worldPartClickMaxDragPixels);
        if (dragRotate == null && customizer != null)
        {
            dragRotate = customizer.GetComponent<MinimoCharacterDragRotate>();
        }

        if (dragRotate != null)
        {
            clickThreshold = Mathf.Max(clickThreshold, dragRotate.DragActivationPixels);
        }

        return clickThreshold;
    }

    private bool IsMouseButtonHeldOverCharacter()
    {
        if (!MinimoInputBridge.GetMouseButton(0) || customizer == null || customizationCamera == null)
        {
            return false;
        }

        Ray ray = customizationCamera.ScreenPointToRay(MinimoInputBridge.MousePosition);
        if (!Physics.Raycast(ray, out RaycastHit hit, 500f, ~0, QueryTriggerInteraction.Collide))
        {
            return false;
        }

        Transform hitTransform = hit.transform;
        return hitTransform == customizer.transform || hitTransform.IsChildOf(customizer.transform);
    }

    private void EnsureCharacterDragRotate()
    {
        if (customizer == null)
        {
            return;
        }

        MinimoCharacterDragRotate rotate = customizer.GetComponent<MinimoCharacterDragRotate>();
        if (rotate == null)
        {
            rotate = customizer.gameObject.AddComponent<MinimoCharacterDragRotate>();
        }

        dragRotate = rotate;
        if (customizationCamera != null)
        {
            rotate.SetInputCamera(customizationCamera);
        }

        rotate.SetInvert(true);
        rotate.SetRequirePointerOnCharacter(true);
        rotate.SetAutoRotateSpeed(autoRotationSpeedDegreesPerSecond);
        rotate.SetAutoRotate(autoRotationEnabled);
        EnsureCharacterRootCollider();
    }

    private void ApplyAutoRotationStateToDragRotate()
    {
        if (dragRotate == null && customizer != null)
        {
            dragRotate = customizer.GetComponent<MinimoCharacterDragRotate>();
        }

        if (dragRotate == null)
        {
            EnsureCharacterDragRotate();
        }

        if (dragRotate == null)
        {
            return;
        }

        dragRotate.SetAutoRotateSpeed(autoRotationSpeedDegreesPerSecond);
        dragRotate.SetAutoRotate(autoRotationEnabled);
    }

    private void UpdateAutoRotationButtonVisual()
    {
        // Keep scene-authored visuals unchanged.
    }

    private void EnsureCharacterRootCollider()
    {
        if (customizer == null || customizer.TryGetComponent(out Collider _))
        {
            return;
        }

        BoxCollider box = customizer.gameObject.AddComponent<BoxCollider>();
        if (!TryCalculateCharacterWorldBounds(customizer.transform, out Bounds bounds))
        {
            return;
        }

        box.center = customizer.transform.InverseTransformPoint(bounds.center);
        Vector3 localSize = customizer.transform.InverseTransformVector(bounds.size);
        box.size = new Vector3(
            Mathf.Max(Mathf.Abs(localSize.x), 0.02f),
            Mathf.Max(Mathf.Abs(localSize.y), 0.02f),
            Mathf.Max(Mathf.Abs(localSize.z), 0.02f)) * 1.05f;
    }

    private static bool TryCalculateCharacterWorldBounds(Transform root, out Bounds bounds)
    {
        bounds = default;
        if (root == null)
        {
            return false;
        }

        Renderer[] renderers = root.GetComponentsInChildren<Renderer>(true);
        bool hasBounds = false;
        for (int i = 0; i < renderers.Length; i++)
        {
            Renderer renderer = renderers[i];
            if (renderer == null || renderer is ParticleSystemRenderer)
            {
                continue;
            }

            if (!hasBounds)
            {
                bounds = renderer.bounds;
                hasBounds = true;
            }
            else
            {
                bounds.Encapsulate(renderer.bounds);
            }
        }

        return hasBounds;
    }

    private void EnsureWorldPartColliders()
    {
        if (customizer == null)
        {
            return;
        }

        if (!addHoverCollidersOnPlay && !enableWorldPartHoverSelection)
        {
            return;
        }

        IReadOnlyList<MinimoCharacterCustomizer.PartSlot> slots = MinimoCharacterCustomizer.Slots;
        for (int i = 0; i < slots.Count; i++)
        {
            EnsureWorldPartCollider(slots[i]);
        }
    }

    private void EnsureWorldPartCollidersForSlots(MinimoCharacterCustomizer.PartSlot[] slots)
    {
        if (customizer == null)
        {
            return;
        }

        if (!addHoverCollidersOnPlay && !enableWorldPartHoverSelection)
        {
            return;
        }

        if (slots == null || slots.Length == 0)
        {
            EnsureWorldPartColliders();
            return;
        }

        for (int i = 0; i < slots.Length; i++)
        {
            EnsureWorldPartCollider(slots[i]);
        }
    }

    private void EnsureWorldPartCollider(MinimoCharacterCustomizer.PartSlot slot)
    {
        if (customizer == null
            || !customizer.TryGetPartRenderer(slot, out SkinnedMeshRenderer renderer)
            || renderer == null)
        {
            return;
        }

        BoxCollider collider = renderer.GetComponent<BoxCollider>();
        if (collider == null)
        {
            collider = renderer.gameObject.AddComponent<BoxCollider>();
        }

        Bounds localBounds = renderer.localBounds;
        collider.center = localBounds.center;
        collider.size = new Vector3(
            Mathf.Max(localBounds.size.x, 0.02f),
            Mathf.Max(localBounds.size.y, 0.02f),
            Mathf.Max(localBounds.size.z, 0.02f));
        collider.isTrigger = true;
    }

    private void UpdateWorldPartHoverVisuals(
        MinimoCharacterCustomizer.PartSlot? hoveredSlot,
        int hoveredMaterialIndex)
    {
        float delta = Application.isPlaying ? Time.unscaledDeltaTime : 0.016f;
        float lerpT = 1f - Mathf.Exp(-Mathf.Max(0.01f, worldPartHoverScaleLerpSpeed) * delta);
        Dictionary<MinimoCharacterCustomizer.PartSlot, HashSet<int>> hoveredTargets =
            ResolveWorldHoverPreviewMaterialTargets(hoveredSlot, hoveredMaterialIndex);

        IReadOnlyList<MinimoCharacterCustomizer.PartSlot> slots = MinimoCharacterCustomizer.Slots;
        for (int i = 0; i < slots.Count; i++)
        {
            if (!customizer.TryGetPartRenderer(slots[i], out SkinnedMeshRenderer renderer) || renderer == null)
            {
                continue;
            }

            Transform target = renderer.transform;
            CacheWorldPartBaseScale(target);

            if (!worldPartBaseScales.TryGetValue(target, out Vector3 baseScale))
            {
                continue;
            }

            Vector3 targetScale = baseScale;
            bool isHovered = hoveredTargets.TryGetValue(slots[i], out HashSet<int> hoveredMaterialIndices)
                && hoveredMaterialIndices != null
                && hoveredMaterialIndices.Count > 0
                && renderer.enabled
                && renderer.gameObject.activeInHierarchy;
            if (isHovered)
            {
                targetScale = baseScale * Mathf.Max(1f, worldPartHoverScaleMultiplier);
            }

            target.localScale = Vector3.Lerp(target.localScale, targetScale, lerpT);
            ApplyWorldPartHoverWhiteColor(renderer, isHovered ? hoveredMaterialIndices : null);
        }

        UpdateWorldPropHoverWhiteVisuals(hoveredSlot, hoveredMaterialIndex);
    }

    private void UpdateWorldPropHoverWhiteVisuals(
        MinimoCharacterCustomizer.PartSlot? hoveredSlot,
        int hoveredColorChannelIndex)
    {
        Renderer hoveredRenderer = null;
        int hoveredRendererMaterialIndex = -1;
        bool hasHoveredPropMaterial = hoveredSlot.HasValue
            && hoveredSlot.Value == MinimoCharacterCustomizer.PartSlot.Props
            && TryResolveHoveredPropRendererMaterial(
                hoveredColorChannelIndex,
                out hoveredRenderer,
                out hoveredRendererMaterialIndex);

        if (hasHoveredPropMaterial && hoveredRenderer != null)
        {
            Material[] materials = hoveredRenderer.sharedMaterials;
            int materialCount = materials != null ? materials.Length : 0;
            for (int materialIndex = 0; materialIndex < materialCount; materialIndex++)
            {
                Material material = materials[materialIndex];
                if (material == null)
                {
                    continue;
                }

                bool applyToMaterial = materialIndex == hoveredRendererMaterialIndex;
                if (applyToMaterial)
                {
                    CapturePropHoverMaterialColorSnapshot(hoveredRenderer, materialIndex, material);
                    ApplyWhiteColorToPropMaterial(hoveredRenderer, materialIndex, material);
                }
                else
                {
                    RestorePropHoverMaterialColorSnapshot(hoveredRenderer, materialIndex, material);
                }
            }
        }

        if (worldPropHoverColorSnapshots.Count == 0)
        {
            return;
        }

        List<Renderer> trackedRenderers = new List<Renderer>(worldPropHoverColorSnapshots.Keys);
        for (int i = 0; i < trackedRenderers.Count; i++)
        {
            Renderer trackedRenderer = trackedRenderers[i];
            if (trackedRenderer == null)
            {
                continue;
            }

            if (hasHoveredPropMaterial && ReferenceEquals(trackedRenderer, hoveredRenderer))
            {
                continue;
            }

            RestoreAllPropHoverMaterialColorSnapshots(trackedRenderer);
        }
    }

    private bool TryResolveHoveredPropRendererMaterial(
        int hoveredColorChannelIndex,
        out Renderer renderer,
        out int materialIndex)
    {
        renderer = null;
        materialIndex = -1;
        if (customizer == null
            || hoveredColorChannelIndex < 0
            || string.IsNullOrWhiteSpace(hoveredWorldPropRigName)
            || !TryFindPropRigTransform(hoveredWorldPropRigName, out Transform rigTransform)
            || rigTransform == null)
        {
            return false;
        }

        Transform propRoot = FindFirstPropChild(rigTransform);
        if (propRoot == null)
        {
            return false;
        }

        List<PropMaterialChannel> channels = BuildColorChannelDescriptorsForPropInstance(propRoot);
        if (channels == null || channels.Count == 0)
        {
            return false;
        }

        int resolvedChannelIndex = Mathf.Clamp(hoveredColorChannelIndex, 0, channels.Count - 1);
        PropMaterialChannel channel = channels[resolvedChannelIndex];
        if (channel == null
            || channel.renderer == null
            || channel.materialIndex < 0)
        {
            return false;
        }

        Material[] materials = channel.renderer.sharedMaterials;
        if (materials == null || channel.materialIndex >= materials.Length)
        {
            return false;
        }

        renderer = channel.renderer;
        materialIndex = channel.materialIndex;
        return true;
    }

    private void ApplyWorldPartHoverWhiteColor(
        SkinnedMeshRenderer renderer,
        HashSet<int> hoveredMaterialIndices)
    {
        if (renderer == null)
        {
            return;
        }

        Material[] materials = renderer.sharedMaterials;
        if (materials == null || materials.Length == 0)
        {
            return;
        }

        worldPartMaterialPropertyBlock ??= new MaterialPropertyBlock();
        for (int i = 0; i < materials.Length; i++)
        {
            Material material = materials[i];
            if (material == null)
            {
                continue;
            }

            bool applyToMaterial = hoveredMaterialIndices != null && hoveredMaterialIndices.Contains(i);
            if (applyToMaterial)
            {
                CaptureHoverMaterialColorSnapshot(renderer, i, material);
                ApplyWhiteColorToMaterial(renderer, i, material);
                continue;
            }

            RestoreHoverMaterialColorSnapshot(renderer, i, material);
        }
    }

    private Dictionary<MinimoCharacterCustomizer.PartSlot, HashSet<int>> ResolveHoveredMaterialTargets(
        MinimoCharacterCustomizer.PartSlot? hoveredSlot,
        int hoveredMaterialIndex,
        bool allowHistoryFocus = true)
    {
        Dictionary<MinimoCharacterCustomizer.PartSlot, HashSet<int>> targets = new Dictionary<MinimoCharacterCustomizer.PartSlot, HashSet<int>>();
        if (!hoveredSlot.HasValue || customizer == null)
        {
            return targets;
        }

        MinimoCharacterCustomizer.PartSlot slot = hoveredSlot.Value;
        int resolvedHoveredMaterialIndex = ResolveMaterialIndexForSlot(slot, hoveredMaterialIndex);
        if (resolvedHoveredMaterialIndex < 0)
        {
            return targets;
        }

        if (IsHairSelectionSlot(slot))
        {
            targets[slot] = new HashSet<int> { resolvedHoveredMaterialIndex };
            return targets;
        }

        if (!TryGetWorldLinkedMaterialKey(slot, resolvedHoveredMaterialIndex, out string materialKey)
            || !TryBuildWorldLinkedMaterialTargetsByKey(materialKey, out Dictionary<MinimoCharacterCustomizer.PartSlot, HashSet<int>> linkedTargets)
            || linkedTargets.Count <= 1)
        {
            targets[slot] = new HashSet<int> { resolvedHoveredMaterialIndex };
            return targets;
        }

        bool sameLinkedGroup = worldLinkedMaterialSelectionKeyValid
                               && IsWorldLinkedSlotSelectionStateValidForCurrentKey()
                               && string.Equals(
                                   worldLinkedMaterialSelectionKey,
                                   materialKey,
                                   StringComparison.OrdinalIgnoreCase);
        if (!sameLinkedGroup)
        {
            return linkedTargets;
        }

        Dictionary<MinimoCharacterCustomizer.PartSlot, HashSet<int>> activeTargets =
            worldLinkedMaterialTargetsSnapshot.Count > 0
                ? worldLinkedMaterialTargetsSnapshot
                : linkedTargets;
        if (allowHistoryFocus
            && CountSelectedWorldLinkedSlots(activeTargets) == 1
            && IsWorldLinkedSlotSelected(slot))
        {
            return linkedTargets;
        }

        bool hasColorHistory = HasSelectionHistoryForMaterialKey(materialKey);
        bool hasActiveMultiSelectionForKey = HasMultipleActiveWorldLinkedSelectionsForMaterialKey(materialKey);
        if (!allowHistoryFocus)
        {
            if ((hasColorHistory || hasActiveMultiSelectionForKey)
                && TryResolveMirroredPairForSlot(
                    slot,
                    out MinimoCharacterCustomizer.PartSlot inactiveMirroredLeftSlot,
                    out MinimoCharacterCustomizer.PartSlot inactiveMirroredRightSlot)
                && !IsActiveMirroredPairSelectionForMaterialKey(materialKey, inactiveMirroredLeftSlot, inactiveMirroredRightSlot))
            {
                Dictionary<MinimoCharacterCustomizer.PartSlot, HashSet<int>> pairTargets = BuildMirroredPairTargetsFromLinkedTargets(
                    linkedTargets,
                    inactiveMirroredLeftSlot,
                    inactiveMirroredRightSlot,
                    resolvedHoveredMaterialIndex);
                if (pairTargets.Count > 0)
                {
                    return pairTargets;
                }
            }

            return linkedTargets;
        }

        if (!hasColorHistory && !hasActiveMultiSelectionForKey)
        {
            return linkedTargets;
        }

        if (TryResolveMirroredPairForSlot(
                slot,
                out MinimoCharacterCustomizer.PartSlot mirroredLeftSlot,
                out MinimoCharacterCustomizer.PartSlot mirroredRightSlot))
        {
            if (!IsActiveMirroredPairSelectionForMaterialKey(materialKey, mirroredLeftSlot, mirroredRightSlot))
            {
                Dictionary<MinimoCharacterCustomizer.PartSlot, HashSet<int>> pairTargets = BuildMirroredPairTargetsFromLinkedTargets(
                    linkedTargets,
                    mirroredLeftSlot,
                    mirroredRightSlot,
                    resolvedHoveredMaterialIndex);
                if (pairTargets.Count > 0)
                {
                    return pairTargets;
                }
            }

            targets[slot] = new HashSet<int> { resolvedHoveredMaterialIndex };
            return targets;
        }

        targets[slot] = new HashSet<int> { resolvedHoveredMaterialIndex };
        return targets;
    }

    private Dictionary<MinimoCharacterCustomizer.PartSlot, HashSet<int>> ResolveWorldHoverPreviewMaterialTargets(
        MinimoCharacterCustomizer.PartSlot? hoveredSlot,
        int hoveredMaterialIndex)
    {
        bool allowHistoryFocus = hoveredSlot.HasValue
                                 && hoveredSlot.Value != MinimoCharacterCustomizer.PartSlot.Props
                                 && IsActiveWorldLinkedSelectionSlot(hoveredSlot.Value);
        return ResolveHoveredMaterialTargets(hoveredSlot, hoveredMaterialIndex, allowHistoryFocus);
    }

    private bool IsActiveMirroredPairSelectionForMaterialKey(
        string materialKey,
        MinimoCharacterCustomizer.PartSlot mirroredLeftSlot,
        MinimoCharacterCustomizer.PartSlot mirroredRightSlot)
    {
        if (string.IsNullOrWhiteSpace(materialKey)
            || !worldLinkedMaterialSelectionKeyValid
            || !IsWorldLinkedSlotSelectionStateValidForCurrentKey()
            || !string.Equals(worldLinkedMaterialSelectionKey, materialKey, StringComparison.OrdinalIgnoreCase))
        {
            return false;
        }

        Dictionary<MinimoCharacterCustomizer.PartSlot, HashSet<int>> activeTargets = worldLinkedMaterialTargetsSnapshot;
        if ((activeTargets == null || activeTargets.Count == 0)
            && !TryBuildWorldLinkedMaterialTargetsByKey(materialKey, out activeTargets))
        {
            return false;
        }

        bool pairSelected = HasColorTargetsForWorldLinkedSlot(activeTargets, mirroredLeftSlot)
                            && HasColorTargetsForWorldLinkedSlot(activeTargets, mirroredRightSlot)
                            && IsWorldLinkedSlotSelected(mirroredLeftSlot)
                            && IsWorldLinkedSlotSelected(mirroredRightSlot);
        return pairSelected && CountSelectedWorldLinkedSlots(activeTargets) == 2;
    }

    private bool TryResolveMirroredPairForSlot(
        MinimoCharacterCustomizer.PartSlot slot,
        out MinimoCharacterCustomizer.PartSlot mirroredLeftSlot,
        out MinimoCharacterCustomizer.PartSlot mirroredRightSlot)
    {
        mirroredLeftSlot = default;
        mirroredRightSlot = default;
        if (!TryGetWorldLinkedRegionEntryForSlotOrMirror(slot, out RegionEntry region)
            || region == null
            || region.slots == null
            || region.slots.Length <= 1)
        {
            return false;
        }

        if (!TryResolveMirroredSlotsForRegion(region.slots, out mirroredLeftSlot, out mirroredRightSlot))
        {
            return false;
        }

        return slot == mirroredLeftSlot || slot == mirroredRightSlot;
    }

    private Dictionary<MinimoCharacterCustomizer.PartSlot, HashSet<int>> BuildMirroredPairTargetsFromLinkedTargets(
        Dictionary<MinimoCharacterCustomizer.PartSlot, HashSet<int>> linkedTargets,
        MinimoCharacterCustomizer.PartSlot mirroredLeftSlot,
        MinimoCharacterCustomizer.PartSlot mirroredRightSlot,
        int fallbackMaterialIndex)
    {
        Dictionary<MinimoCharacterCustomizer.PartSlot, HashSet<int>> targets = new Dictionary<MinimoCharacterCustomizer.PartSlot, HashSet<int>>();
        AddMirroredPairTargetFromLinkedTargets(linkedTargets, targets, mirroredLeftSlot, fallbackMaterialIndex);
        AddMirroredPairTargetFromLinkedTargets(linkedTargets, targets, mirroredRightSlot, fallbackMaterialIndex);
        return targets;
    }

    private void AddMirroredPairTargetFromLinkedTargets(
        Dictionary<MinimoCharacterCustomizer.PartSlot, HashSet<int>> linkedTargets,
        Dictionary<MinimoCharacterCustomizer.PartSlot, HashSet<int>> targets,
        MinimoCharacterCustomizer.PartSlot slot,
        int fallbackMaterialIndex)
    {
        if (linkedTargets != null
            && linkedTargets.TryGetValue(slot, out HashSet<int> linkedIndices)
            && linkedIndices != null
            && linkedIndices.Count > 0)
        {
            targets[slot] = new HashSet<int>(linkedIndices);
            return;
        }

        int resolvedIndex = ResolveMaterialIndexForSlot(slot, fallbackMaterialIndex);
        if (resolvedIndex >= 0)
        {
            targets[slot] = new HashSet<int> { resolvedIndex };
        }
    }

    private bool TryBuildMirroredHoverTargets(
        MinimoCharacterCustomizer.PartSlot hoveredSlot,
        int hoveredMaterialIndex,
        out Dictionary<MinimoCharacterCustomizer.PartSlot, HashSet<int>> targets)
    {
        targets = null;
        if (!TryGetWorldLinkedRegionEntryForSlotOrMirror(hoveredSlot, out RegionEntry region)
            || region == null
            || region.slots == null
            || region.slots.Length <= 1
            || !TryResolveMirroredSlotsForRegion(
                region.slots,
                out MinimoCharacterCustomizer.PartSlot mirroredLeftSlot,
                out MinimoCharacterCustomizer.PartSlot mirroredRightSlot))
        {
            return false;
        }

        if (hoveredSlot != mirroredLeftSlot && hoveredSlot != mirroredRightSlot)
        {
            return false;
        }

        bool sameRegionSelected = selectedRegionIndex >= 0
                                  && selectedRegionIndex < regions.Count
                                  && ReferenceEquals(regions[selectedRegionIndex], region);
        bool currentlyPairedSelection = sameRegionSelected && !selectedWorldColorTargetSlot.HasValue;

        targets = new Dictionary<MinimoCharacterCustomizer.PartSlot, HashSet<int>>();
        if (currentlyPairedSelection)
        {
            // Next click on the same mirrored region will focus only hovered side.
            targets[hoveredSlot] = new HashSet<int> { hoveredMaterialIndex };
            return true;
        }

        // First mirrored click (or re-click after single selection) will target both sides.
        int leftMaterialIndex = ResolveMaterialIndexForSlot(mirroredLeftSlot, hoveredMaterialIndex);
        int rightMaterialIndex = ResolveMaterialIndexForSlot(mirroredRightSlot, hoveredMaterialIndex);

        if (leftMaterialIndex >= 0)
        {
            targets[mirroredLeftSlot] = new HashSet<int> { leftMaterialIndex };
        }

        if (rightMaterialIndex >= 0)
        {
            targets[mirroredRightSlot] = new HashSet<int> { rightMaterialIndex };
        }

        if (targets.Count == 0)
        {
            targets[hoveredSlot] = new HashSet<int> { hoveredMaterialIndex };
        }

        return true;
    }

    private List<(MinimoCharacterCustomizer.PartSlot slot, int materialIndex)> GetLinkedSkinColorTargetsForCurrentSelection()
    {
        List<(MinimoCharacterCustomizer.PartSlot slot, int materialIndex)> targets = new List<(MinimoCharacterCustomizer.PartSlot slot, int materialIndex)>();
        if (customizer == null || !TryGetCurrentSelectionAnchor(out MinimoCharacterCustomizer.PartSlot anchorSlot, out int anchorMaterialIndex))
        {
            return targets;
        }

        if (!TryGetEffectivePartColor(anchorSlot, anchorMaterialIndex, out Color anchorColor)
            || !IsSkinLinkedMaterialTarget(anchorSlot, anchorMaterialIndex, anchorColor))
        {
            return targets;
        }

        for (int i = 0; i < SkinToneSlots.Length; i++)
        {
            MinimoCharacterCustomizer.PartSlot skinSlot = SkinToneSlots[i];
            HashSet<int> matchingMaterialIndices = GetMaterialIndicesMatchingColor(skinSlot, anchorColor);
            foreach (int materialIndex in matchingMaterialIndices)
            {
                targets.Add((skinSlot, materialIndex));
            }
        }

        return targets;
    }

    private bool TryGetCurrentSelectionAnchorColor(out Color anchorColor)
    {
        anchorColor = Color.white;
        if (IsPropsRegionSelectionMode() && selectedColorChannelTarget == ColorChannelTargetType.Material)
        {
            return TryGetEffectivePropColor(selectedColorMaterialIndex, out anchorColor);
        }

        if (!TryGetCurrentSelectionAnchor(out MinimoCharacterCustomizer.PartSlot anchorSlot, out int anchorMaterialIndex))
        {
            return false;
        }

        return TryGetEffectivePartColor(anchorSlot, anchorMaterialIndex, out anchorColor);
    }

    private bool TryGetCurrentSelectionAnchor(
        out MinimoCharacterCustomizer.PartSlot anchorSlot,
        out int anchorMaterialIndex)
    {
        anchorSlot = default;
        anchorMaterialIndex = selectedColorMaterialIndex;
        if (selectedColorChannelTarget != ColorChannelTargetType.Material)
        {
            return false;
        }

        MinimoCharacterCustomizer.PartSlot[] targetSlots = GetTargetSlotsForColorOperations();
        if (targetSlots == null || targetSlots.Length == 0)
        {
            return false;
        }

        if (selectedWorldColorTargetSlot.HasValue)
        {
            anchorSlot = selectedWorldColorTargetSlot.Value;
        }
        else
        {
            anchorSlot = targetSlots[0];
        }

        anchorMaterialIndex = ResolveColorMaterialIndexForSlot(anchorSlot, selectedColorMaterialIndex);
        return anchorMaterialIndex >= 0;
    }

    private int ResolveMaterialIndexForSlot(MinimoCharacterCustomizer.PartSlot slot, int preferredMaterialIndex)
    {
        if (customizer == null || !customizer.TryGetPartRenderer(slot, out SkinnedMeshRenderer renderer) || renderer == null)
        {
            return -1;
        }

        Material[] materials = renderer.sharedMaterials;
        if (materials == null || materials.Length == 0)
        {
            return -1;
        }

        int materialCount = GetEffectiveRendererMaterialSlotCount(renderer, materials);
        if (preferredMaterialIndex >= 0 && preferredMaterialIndex < materialCount)
        {
            return preferredMaterialIndex;
        }

        for (int i = 0; i < materialCount; i++)
        {
            if (MaterialSupportsColor(materials[i]))
            {
                return i;
            }
        }

        return -1;
    }

    private HashSet<int> GetMaterialIndicesMatchingColor(MinimoCharacterCustomizer.PartSlot slot, Color targetColor)
    {
        HashSet<int> result = new HashSet<int>();
        if (IsExcludedFromSkinToneWhenDefault(slot))
        {
            return result;
        }

        if (customizer == null || !customizer.TryGetPartRenderer(slot, out SkinnedMeshRenderer renderer) || renderer == null)
        {
            return result;
        }

        Material[] materials = renderer.sharedMaterials;
        if (materials == null || materials.Length == 0)
        {
            return result;
        }

        int materialCount = GetEffectiveRendererMaterialSlotCount(renderer, materials);
        for (int i = 0; i < materialCount; i++)
        {
            Material material = materials[i];
            if (!MaterialSupportsColor(material))
            {
                continue;
            }

            if (TryGetEffectivePartColor(slot, i, out Color slotColor) && ColorsNearlyEqual(slotColor, targetColor))
            {
                result.Add(i);
                continue;
            }

            if (IsSkinMaterialTarget(slot, i))
            {
                result.Add(i);
            }
        }

        return result;
    }

    private bool SlotUsesSkinPaletteColorGroup(MinimoCharacterCustomizer.PartSlot slot)
    {
        return GetMaterialIndicesUsingSkinPaletteColorGroup(slot).Count > 0;
    }

    private HashSet<int> GetMaterialIndicesUsingSkinPaletteColorGroup(MinimoCharacterCustomizer.PartSlot slot)
    {
        HashSet<int> result = new HashSet<int>();
        if (customizer == null || !customizer.TryGetPartRenderer(slot, out SkinnedMeshRenderer renderer) || renderer == null)
        {
            return result;
        }

        Material[] materials = renderer.sharedMaterials;
        if (materials == null || materials.Length == 0)
        {
            return result;
        }

        int materialCount = GetEffectiveRendererMaterialSlotCount(renderer, materials);
        for (int i = 0; i < materialCount; i++)
        {
            Material material = materials[i];
            if (material == null || !MaterialSupportsColor(material))
            {
                continue;
            }

            if (TryGetMaterialDisplayColor(material, out Color materialColor) && IsSkinPaletteColor(materialColor))
            {
                result.Add(i);
            }
        }

        return result;
    }

    private bool IsSkinPaletteColor(Color color)
    {
        color.a = 1f;
        Color[] skinPalette = ResolvePaletteOrDefault(skinTonePalette, DefaultSkinTonePalette);
        for (int i = 0; i < skinPalette.Length; i++)
        {
            Color candidate = skinPalette[i];
            candidate.a = 1f;
            if (ColorsNearlyEqual(color, candidate))
            {
                return true;
            }
        }

        return false;
    }

    private bool TryGetEffectivePartColor(
        MinimoCharacterCustomizer.PartSlot slot,
        int materialIndex,
        out Color color)
    {
        return TryGetEffectivePartColor(customizer, slot, materialIndex, out color);
    }

    private bool TryGetEffectivePartColor(
        MinimoCharacterCustomizer targetCustomizer,
        MinimoCharacterCustomizer.PartSlot slot,
        int materialIndex,
        out Color color)
    {
        color = Color.white;
        if (targetCustomizer == null)
        {
            return false;
        }

        if (materialIndex >= 0 && targetCustomizer.TryGetPartColor(slot, materialIndex, out color))
        {
            return true;
        }

        if (targetCustomizer.TryGetPartColor(slot, -1, out color))
        {
            return true;
        }

        if (!targetCustomizer.TryGetPartRenderer(slot, out SkinnedMeshRenderer renderer) || renderer == null)
        {
            return false;
        }

        Material[] materials = renderer.sharedMaterials;
        if (materials == null || materials.Length == 0)
        {
            return false;
        }

        int materialCount = GetEffectiveRendererMaterialSlotCount(renderer, materials);
        int resolvedMaterialIndex = materialIndex;
        if (resolvedMaterialIndex < 0 || resolvedMaterialIndex >= materialCount)
        {
            resolvedMaterialIndex = ResolveMaterialIndexForSlot(slot, materialIndex);
        }

        if (resolvedMaterialIndex < 0 || resolvedMaterialIndex >= materialCount)
        {
            return false;
        }

        Material material = materials[resolvedMaterialIndex];
        if (material == null)
        {
            return false;
        }

        if (material.HasProperty(ColorShaderProperty))
        {
            color = material.GetColor(ColorShaderProperty);
            return true;
        }

        if (material.HasProperty(BaseColorShaderProperty))
        {
            color = material.GetColor(BaseColorShaderProperty);
            return true;
        }

        return false;
    }

    private static bool MaterialSupportsColor(Material material)
    {
        if (material == null)
        {
            return false;
        }

        return material.HasProperty(ColorShaderProperty) || material.HasProperty(BaseColorShaderProperty);
    }

    private void CaptureHoverMaterialColorSnapshot(SkinnedMeshRenderer renderer, int materialIndex, Material material)
    {
        if (renderer == null || material == null)
        {
            return;
        }

        if (!worldPartHoverColorSnapshots.TryGetValue(renderer, out Dictionary<int, HoverMaterialColorSnapshot> snapshots))
        {
            snapshots = new Dictionary<int, HoverMaterialColorSnapshot>();
            worldPartHoverColorSnapshots[renderer] = snapshots;
        }

        if (snapshots.ContainsKey(materialIndex))
        {
            return;
        }

        HoverMaterialColorSnapshot snapshot = new HoverMaterialColorSnapshot();
        renderer.GetPropertyBlock(worldPartMaterialPropertyBlock, materialIndex);

        for (int p = 0; p < HoverWhiteColorPropertyIds.Length; p++)
        {
            int propertyId = HoverWhiteColorPropertyIds[p];
            if (!material.HasProperty(propertyId))
            {
                continue;
            }

            Color color = worldPartMaterialPropertyBlock.HasColor(propertyId)
                ? worldPartMaterialPropertyBlock.GetColor(propertyId)
                : material.GetColor(propertyId);
            snapshot.colors[propertyId] = color;
        }

        if (snapshot.colors.Count == 0)
        {
            return;
        }

        snapshots[materialIndex] = snapshot;
    }

    private void ApplyWhiteColorToMaterial(SkinnedMeshRenderer renderer, int materialIndex, Material material)
    {
        if (renderer == null || material == null)
        {
            return;
        }

        renderer.GetPropertyBlock(worldPartMaterialPropertyBlock, materialIndex);
        bool changed = false;
        for (int p = 0; p < HoverWhiteColorPropertyIds.Length; p++)
        {
            int propertyId = HoverWhiteColorPropertyIds[p];
            if (!material.HasProperty(propertyId))
            {
                continue;
            }

            worldPartMaterialPropertyBlock.SetColor(propertyId, Color.white);
            changed = true;
        }

        if (changed)
        {
            renderer.SetPropertyBlock(worldPartMaterialPropertyBlock, materialIndex);
        }
    }

    private void RestoreHoverMaterialColorSnapshot(SkinnedMeshRenderer renderer, int materialIndex, Material material)
    {
        if (renderer == null || material == null)
        {
            return;
        }

        if (!worldPartHoverColorSnapshots.TryGetValue(renderer, out Dictionary<int, HoverMaterialColorSnapshot> snapshots))
        {
            return;
        }

        if (!snapshots.TryGetValue(materialIndex, out HoverMaterialColorSnapshot snapshot))
        {
            return;
        }

        renderer.GetPropertyBlock(worldPartMaterialPropertyBlock, materialIndex);
        foreach (KeyValuePair<int, Color> pair in snapshot.colors)
        {
            int propertyId = pair.Key;
            if (!material.HasProperty(propertyId))
            {
                continue;
            }

            worldPartMaterialPropertyBlock.SetColor(propertyId, pair.Value);
        }

        renderer.SetPropertyBlock(worldPartMaterialPropertyBlock, materialIndex);
        snapshots.Remove(materialIndex);

        if (snapshots.Count == 0)
        {
            worldPartHoverColorSnapshots.Remove(renderer);
        }
    }

    private void RestoreAllHoverMaterialColorSnapshots(SkinnedMeshRenderer renderer)
    {
        if (renderer == null || !worldPartHoverColorSnapshots.TryGetValue(renderer, out Dictionary<int, HoverMaterialColorSnapshot> snapshots))
        {
            return;
        }

        Material[] materials = renderer.sharedMaterials;
        if (materials == null || materials.Length == 0)
        {
            worldPartHoverColorSnapshots.Remove(renderer);
            return;
        }

        foreach (KeyValuePair<int, HoverMaterialColorSnapshot> entry in snapshots)
        {
            int materialIndex = entry.Key;
            if (materialIndex < 0 || materialIndex >= materials.Length)
            {
                continue;
            }

            Material material = materials[materialIndex];
            if (material == null)
            {
                continue;
            }

            renderer.GetPropertyBlock(worldPartMaterialPropertyBlock, materialIndex);
            HoverMaterialColorSnapshot snapshot = entry.Value;
            foreach (KeyValuePair<int, Color> pair in snapshot.colors)
            {
                int propertyId = pair.Key;
                if (!material.HasProperty(propertyId))
                {
                    continue;
                }

                worldPartMaterialPropertyBlock.SetColor(propertyId, pair.Value);
            }

            renderer.SetPropertyBlock(worldPartMaterialPropertyBlock, materialIndex);
        }

        worldPartHoverColorSnapshots.Remove(renderer);
    }

