    private void CacheWorldPartBaseScale(Transform target)
    {
        if (target == null || worldPartBaseScales.ContainsKey(target))
        {
            return;
        }

        worldPartBaseScales[target] = target.localScale;
    }

    private void ResetWorldPartHoverVisuals()
    {
        foreach (KeyValuePair<Transform, Vector3> pair in worldPartBaseScales)
        {
            if (pair.Key == null)
            {
                continue;
            }

            pair.Key.localScale = pair.Value;
        }

        if (customizer != null)
        {
            IReadOnlyList<MinimoCharacterCustomizer.PartSlot> slots = MinimoCharacterCustomizer.Slots;
            for (int i = 0; i < slots.Count; i++)
            {
                if (!customizer.TryGetPartRenderer(slots[i], out SkinnedMeshRenderer renderer) || renderer == null)
                {
                    continue;
                }

                RestoreAllHoverMaterialColorSnapshots(renderer);
            }
        }

        if (worldPropHoverColorSnapshots.Count > 0)
        {
            List<Renderer> propSnapshotRenderers = new List<Renderer>(worldPropHoverColorSnapshots.Keys);
            for (int i = 0; i < propSnapshotRenderers.Count; i++)
            {
                RestoreAllPropHoverMaterialColorSnapshots(propSnapshotRenderers[i]);
            }
        }

        hoveredWorldMaterialIndex = -1;
        hoveredWorldPropRigName = string.Empty;
        pressedWorldSlot = null;
        pressedWorldMaterialIndex = -1;
        pressedWorldPropRigName = string.Empty;
        worldPartHoverColorSnapshots.Clear();
        worldPropHoverColorSnapshots.Clear();

        foreach (KeyValuePair<SkinnedMeshRenderer, Mesh> pair in worldPartHoverRaycastMeshes)
        {
            if (pair.Value == null)
            {
                continue;
            }

            if (Application.isPlaying)
            {
                Destroy(pair.Value);
            }
            else
            {
                DestroyImmediate(pair.Value);
            }
        }

        worldPartHoverRaycastMeshes.Clear();
    }

    private static bool IsPointerOverUI()
    {
        if (EventSystem.current == null)
        {
            return false;
        }

        return EventSystem.current.IsPointerOverGameObject();
    }

    private static bool ColorsNearlyEqual(Color a, Color b)
    {
        const float epsilon = 0.01f;
        return Mathf.Abs(a.r - b.r) <= epsilon
               && Mathf.Abs(a.g - b.g) <= epsilon
               && Mathf.Abs(a.b - b.b) <= epsilon
               && Mathf.Abs(a.a - b.a) <= epsilon;
    }

    private void UpdateInfoPanel()
    {
        if (customizer == null)
        {
            if (infoTrisLabel != null)
            {
                infoTrisLabel.text = "Tris:\n0";
            }

            if (infoVertexLabel != null)
            {
                infoVertexLabel.text = "Vertex:\n0";
            }

            return;
        }

        int totalVertices = 0;
        int totalTriangles = 0;
        int activePartCount = 0;

        IReadOnlyList<MinimoCharacterCustomizer.PartSlot> slots = MinimoCharacterCustomizer.Slots;
        for (int i = 0; i < slots.Count; i++)
        {
            if (!customizer.TryGetCurrentPartMeshInfo(slots[i], out int vertices, out int triangles))
            {
                continue;
            }

            totalVertices += vertices;
            totalTriangles += triangles;
            activePartCount++;
        }

        string selectedRegionName = selectedRegionIndex >= 0 && selectedRegionIndex < regions.Count
            ? regions[selectedRegionIndex].name
            : "-";
        if (selectedRegionIndex >= 0 && selectedRegionIndex < regions.Count && !UseDualPartMode())
        {
            MinimoCharacterCustomizer.PartSlot[] targetSlots = GetTargetSlotsForSelectedRegion();
            if (targetSlots.Length == 1)
            {
                selectedRegionName += $" ({customizer.GetSlotDisplayName(targetSlots[0])})";
            }
        }

        string selectedSetName = "Mixed";
        if (selectedRegionIndex >= 0 && selectedRegionIndex < regions.Count)
        {
            int? regionVariant = GetUniformVariantForSlots(GetTargetSlotsForSelectedRegion());
            if (regionVariant.HasValue)
            {
                selectedSetName = regionVariant.Value >= 0
                    ? customizer.GetVariantDisplayName(regionVariant.Value)
                    : "Default";
            }
        }

        if (infoTrisLabel != null)
        {
            infoTrisLabel.text = $"Tris:\n{totalTriangles:N0}\nActive Parts: {activePartCount}";
        }

        if (infoVertexLabel != null)
        {
            infoVertexLabel.text = $"Vertex:\n{totalVertices:N0}\nBolge: {selectedRegionName}\nSet: {selectedSetName}";
        }
    }

