    private void RefreshGamepadButtonNavigation()
    {
        if (!forceSelectableNavigationAutomatic)
        {
            return;
        }

        ApplyAutomaticNavigationIfMissing(setPrevButton);
        ApplyAutomaticNavigationIfMissing(setNextButton);
        ApplyAutomaticNavigationIfMissing(resetDefaultButton);
        ApplyAutomaticNavigationIfMissing(randomizeButton);
        ApplyAutomaticNavigationIfMissing(backButton);
        ApplyAutomaticNavigationIfMissing(saveButton);
        ApplyAutomaticNavigationIfMissing(partsPanelToggleButton);
        ApplyAutomaticNavigationIfMissing(savePrefabsPanelToggleButton);
        ApplyAutomaticNavigationIfMissing(playSceneButton);
        ApplyAutomaticNavigationIfMissing(randomColorButton);
        ApplyAutomaticNavigationIfMissing(colorChartButton);
        ApplyAutomaticNavigationIfMissing(autoRotationButton);
        ApplyAutomaticNavigationIfMissing(savedPrefabsLeftArrowButton);
        ApplyAutomaticNavigationIfMissing(savedPrefabsRightArrowButton);
        ApplyAutomaticNavigationIfMissing(customCategoryDropdownToggleButton);
        ApplyAutomaticNavigationIfMissing(customSavedPrefabDropdownToggleButton);
        ApplyAutomaticNavigationIfMissing(savedPrefabsCategoryDropdown);
        ApplyAutomaticNavigationIfMissing(saveModePopupOverwriteButton);
        ApplyAutomaticNavigationIfMissing(saveModePopupSaveAsNewButton);
        ApplyAutomaticNavigationIfMissing(saveModePopupCancelButton);
        ApplyAutomaticNavigationIfMissing(deleteSavedPrefabPopupYesButton);
        ApplyAutomaticNavigationIfMissing(deleteSavedPrefabPopupNoButton);
        ApplyAutomaticNavigationIfMissing(readyCharacterPrevArrowButton);
        ApplyAutomaticNavigationIfMissing(readyCharacterNextArrowButton);
        ApplyAutomaticNavigationIfMissing(categoryInfoBuyButton);

        for (int i = 0; i < rows.Count; i++)
        {
            SlotRow row = rows[i];
            if (row == null)
            {
                continue;
            }

            ApplyAutomaticNavigationIfMissing(row.prevButton);
            ApplyAutomaticNavigationIfMissing(row.nextButton);
        }

        for (int i = 0; i < regions.Count; i++)
        {
            ApplyAutomaticNavigationIfMissing(regions[i]?.button);
        }

        for (int i = 0; i < variantButtons.Count; i++)
        {
            ApplyAutomaticNavigationIfMissing(variantButtons[i]?.button);
        }

        for (int i = 0; i < colorChannelButtons.Count; i++)
        {
            ApplyAutomaticNavigationIfMissing(colorChannelButtons[i]?.button);
        }

        for (int i = 0; i < colorButtons.Count; i++)
        {
            ApplyAutomaticNavigationIfMissing(colorButtons[i]?.button);
        }

        for (int i = 0; i < worldLinkedSlotToggleButtons.Count; i++)
        {
            ApplyAutomaticNavigationIfMissing(worldLinkedSlotToggleButtons[i]?.button);
        }

        for (int i = 0; i < savedPrefabButtons.Count; i++)
        {
            SavedPrefabButtonEntry entry = savedPrefabButtons[i];
            if (entry == null)
            {
                continue;
            }

            ApplyAutomaticNavigationIfMissing(entry.button);
            ApplyAutomaticNavigationIfMissing(entry.deleteButton);
        }

        for (int i = 0; i < customCategoryDropdownOptionButtons.Count; i++)
        {
            ApplyAutomaticNavigationIfMissing(customCategoryDropdownOptionButtons[i]);
        }

        for (int i = 0; i < customSavedPrefabDropdownOptionButtons.Count; i++)
        {
            ApplyAutomaticNavigationIfMissing(customSavedPrefabDropdownOptionButtons[i]);
        }
    }

    private static void ApplyAutomaticNavigationIfMissing(Selectable selectable)
    {
        if (selectable == null)
        {
            return;
        }

        Navigation navigation = selectable.navigation;
        if (navigation.mode != Navigation.Mode.None)
        {
            return;
        }

        navigation.mode = Navigation.Mode.Automatic;
        selectable.navigation = navigation;
    }

    private void RefreshCameraFocusTarget()
    {
        if (!focusCameraToSelectedRegion)
        {
            hasCameraTarget = false;
            return;
        }

        EnsureCameraDefaults();
        if (!cameraDefaultsCaptured || customizationCamera == null || customizer == null)
        {
            hasCameraTarget = false;
            return;
        }

        if (selectedRegionIndex < 0 || selectedRegionIndex >= regions.Count)
        {
            cameraTargetPosition = cameraDefaultPosition;
            cameraTargetRotation = cameraDefaultRotation;
            hasCameraTarget = true;
            return;
        }

        RegionEntry selectedRegion = regions[selectedRegionIndex];
        if (selectedRegion == null)
        {
            return;
        }

        Vector3 lookPoint;
        float distanceScale;
        GetCameraFocusParameters(selectedRegion.name, out lookPoint, out distanceScale);
        float distance = Mathf.Max(0.8f, cameraDefaultDistance * distanceScale);
        cameraTargetPosition = lookPoint + cameraDefaultDirection * distance;
        cameraTargetRotation = Quaternion.LookRotation(lookPoint - cameraTargetPosition, Vector3.up);
        hasCameraTarget = true;
    }

    private void UpdateCameraFocus()
    {
        if (!focusCameraToSelectedRegion)
        {
            return;
        }

        if (!hasCameraTarget)
        {
            return;
        }

        if (customizationCamera == null)
        {
            return;
        }

        float t = 1f - Mathf.Exp(-Mathf.Max(0.01f, cameraFocusLerpSpeed) * Time.unscaledDeltaTime);
        customizationCamera.transform.position = Vector3.Lerp(customizationCamera.transform.position, cameraTargetPosition, t);
        customizationCamera.transform.rotation = Quaternion.Slerp(customizationCamera.transform.rotation, cameraTargetRotation, t);
    }

    private void EnsureCameraDefaults()
    {
        if (cameraDefaultsCaptured)
        {
            return;
        }

        if (customizationCamera == null)
        {
            customizationCamera = Camera.main;
            if (customizationCamera == null)
            {
                customizationCamera = MinimoUnityCompatibility.FindFirstObjectByType<Camera>();
            }
        }

        if (customizationCamera == null || customizer == null)
        {
            return;
        }

        cameraDefaultPosition = customizationCamera.transform.position;
        cameraDefaultRotation = customizationCamera.transform.rotation;

        Vector3 defaultLookPoint = customizer.transform.position + Vector3.up * 1.2f;
        Vector3 defaultVector = cameraDefaultPosition - defaultLookPoint;
        if (defaultVector.sqrMagnitude > 0.0001f)
        {
            cameraDefaultDirection = defaultVector.normalized;
            cameraDefaultDistance = defaultVector.magnitude;
        }

        cameraDefaultsCaptured = true;
    }

    private void GetCameraFocusParameters(string regionName, out Vector3 lookPoint, out float distanceScale)
    {
        float y = 1.2f;
        distanceScale = 0.8f;
        string normalized = NormalizeBodyRegionKey(regionName);
        if (normalized == "HEAD"
            || RegionNameContainsToken(normalized, "FACE")
            || RegionNameContainsToken(normalized, "HAIR")
            || RegionNameContainsToken(normalized, "SAC"))
        {
            y = 1.62f;
            distanceScale = 0.52f;
        }
        else if (RegionNameContainsToken(normalized, "SHOULDER"))
        {
            y = 1.46f;
            distanceScale = 0.58f;
        }
        else if (RegionNameContainsToken(normalized, "ARM"))
        {
            y = 1.28f;
            distanceScale = 0.62f;
        }
        else if (RegionNameContainsToken(normalized, "HAND"))
        {
            y = 1.05f;
            distanceScale = 0.62f;
        }
        else if (RegionNameContainsToken(normalized, "TORSO") || RegionNameContainsToken(normalized, "CHEST"))
        {
            y = 1.2f;
            distanceScale = 0.66f;
        }
        else if (RegionNameContainsToken(normalized, "HIPS") || RegionNameContainsToken(normalized, "HIP"))
        {
            y = 0.92f;
            distanceScale = 0.72f;
        }
        else if (RegionNameContainsToken(normalized, "LEG"))
        {
            y = 0.6f;
            distanceScale = 0.82f;
        }
        else if (RegionNameContainsToken(normalized, "FOOT")
                 || RegionNameContainsToken(normalized, "SHOE")
                 || RegionNameContainsToken(normalized, "BOOT"))
        {
            y = 0.22f;
            distanceScale = 0.9f;
        }

        lookPoint = customizer.transform.position + Vector3.up * y;
    }

    private static bool TryGetSlotsForBodyRegion(string regionName, out MinimoCharacterCustomizer.PartSlot[] slots)
    {
        string value = NormalizeBodyRegionKey(regionName);
        if (string.IsNullOrWhiteSpace(value))
        {
            slots = Array.Empty<MinimoCharacterCustomizer.PartSlot>();
            return false;
        }

        if (RegionNameContainsToken(value, "HAIR") || RegionNameContainsToken(value, "SAC"))
        {
            slots = new[] { MinimoCharacterCustomizer.PartSlot.Hair };
            return true;
        }

        if (RegionNameContainsToken(value, "PROP"))
        {
            slots = Array.Empty<MinimoCharacterCustomizer.PartSlot>();
            return true;
        }

        if (RegionNameContainsToken(value, "FACE"))
        {
            slots = new[] { MinimoCharacterCustomizer.PartSlot.Face };
            return true;
        }

        if (TryGetSlotsFromHudRegionPreset(value, out MinimoCharacterCustomizer.PartSlot[] presetSlots))
        {
            slots = presetSlots;
            return true;
        }

        switch (value)
        {
            case "HEAD":
                slots = new[] { MinimoCharacterCustomizer.PartSlot.Face };
                return true;
            case "SHOULDER":
            case "SHOULDERS":
                slots = new[] { MinimoCharacterCustomizer.PartSlot.ShoulderLeft, MinimoCharacterCustomizer.PartSlot.ShoulderRight };
                return true;
            case "SHOULDER_LEFT":
            case "LEFT_SHOULDER":
                slots = new[] { MinimoCharacterCustomizer.PartSlot.ShoulderLeft };
                return true;
            case "SHOULDER_RIGHT":
            case "RIGHT_SHOULDER":
                slots = new[] { MinimoCharacterCustomizer.PartSlot.ShoulderRight };
                return true;
            case "ARM":
            case "ARMS":
                slots = new[] { MinimoCharacterCustomizer.PartSlot.ArmLeft, MinimoCharacterCustomizer.PartSlot.ArmRight };
                return true;
            case "ARM_LEFT":
            case "LEFT_ARM":
                slots = new[] { MinimoCharacterCustomizer.PartSlot.ArmLeft };
                return true;
            case "ARM_RIGHT":
            case "RIGHT_ARM":
                slots = new[] { MinimoCharacterCustomizer.PartSlot.ArmRight };
                return true;
            case "HAND":
            case "HANDS":
                slots = new[] { MinimoCharacterCustomizer.PartSlot.HandLeft, MinimoCharacterCustomizer.PartSlot.HandRight };
                return true;
            case "HAND_LEFT":
            case "LEFT_HAND":
                slots = new[] { MinimoCharacterCustomizer.PartSlot.HandLeft };
                return true;
            case "HAND_RIGHT":
            case "RIGHT_HAND":
                slots = new[] { MinimoCharacterCustomizer.PartSlot.HandRight };
                return true;
            case "HIPS":
                slots = new[] { MinimoCharacterCustomizer.PartSlot.Hips };
                return true;
            case "LEG":
            case "LEGS":
                slots = new[] { MinimoCharacterCustomizer.PartSlot.LegUpperLeft, MinimoCharacterCustomizer.PartSlot.LegUpperRight };
                return true;
            case "LEG_LEFT":
            case "LEFT_LEG":
                slots = new[] { MinimoCharacterCustomizer.PartSlot.LegUpperLeft };
                return true;
            case "LEG_RIGHT":
            case "RIGHT_LEG":
                slots = new[] { MinimoCharacterCustomizer.PartSlot.LegUpperRight };
                return true;
            case "TORSO":
                slots = new[] { MinimoCharacterCustomizer.PartSlot.Torso };
                return true;
            case "FOOT":
            case "SHOE":
            case "BOOT":
            case "FEET":
            case "SHOES":
            case "BOOTS":
                slots = new[] { MinimoCharacterCustomizer.PartSlot.BootsLeft, MinimoCharacterCustomizer.PartSlot.BootsRight };
                return true;
            case "SHOE_LEFT":
            case "LEFT_SHOE":
            case "FOOT_LEFT":
                slots = new[] { MinimoCharacterCustomizer.PartSlot.BootsLeft };
                return true;
            case "SHOE_RIGHT":
            case "RIGHT_SHOE":
            case "FOOT_RIGHT":
                slots = new[] { MinimoCharacterCustomizer.PartSlot.BootsRight };
                return true;
            default:
                slots = Array.Empty<MinimoCharacterCustomizer.PartSlot>();
                return false;
        }
    }

    private static bool TryGetSlotsFromHudRegionPreset(string normalizedRegionName, out MinimoCharacterCustomizer.PartSlot[] slots)
    {
        slots = Array.Empty<MinimoCharacterCustomizer.PartSlot>();
        if (string.IsNullOrWhiteSpace(normalizedRegionName))
        {
            return false;
        }

        for (int i = 0; i < HudRegionPresets.Length; i++)
        {
            RegionPreset preset = HudRegionPresets[i];
            if (preset == null || preset.slots == null || preset.slots.Length == 0)
            {
                continue;
            }

            if (RegionNameContainsToken(normalizedRegionName, NormalizeBodyRegionKey(preset.displayName)))
            {
                slots = preset.slots;
                return true;
            }

            if (preset.aliases == null || preset.aliases.Length == 0)
            {
                continue;
            }

            for (int aliasIndex = 0; aliasIndex < preset.aliases.Length; aliasIndex++)
            {
                if (!RegionNameContainsToken(normalizedRegionName, NormalizeBodyRegionKey(preset.aliases[aliasIndex])))
                {
                    continue;
                }

                slots = preset.slots;
                return true;
            }
        }

        return false;
    }

    private static bool RegionNameContainsToken(string normalizedRegionName, string normalizedToken)
    {
        if (string.IsNullOrWhiteSpace(normalizedRegionName) || string.IsNullOrWhiteSpace(normalizedToken))
        {
            return false;
        }

        if (string.Equals(normalizedRegionName, normalizedToken, StringComparison.Ordinal))
        {
            return true;
        }

        if (normalizedRegionName.StartsWith(normalizedToken + "_", StringComparison.Ordinal)
            || normalizedRegionName.EndsWith("_" + normalizedToken, StringComparison.Ordinal)
            || normalizedRegionName.IndexOf("_" + normalizedToken + "_", StringComparison.Ordinal) >= 0)
        {
            return true;
        }

        string compactRegion = normalizedRegionName.Replace("_", string.Empty);
        string compactToken = normalizedToken.Replace("_", string.Empty);
        return compactRegion.IndexOf(compactToken, StringComparison.Ordinal) >= 0;
    }

    private static string NormalizeBodyRegionKey(string value)
    {
        if (string.IsNullOrWhiteSpace(value))
        {
            return string.Empty;
        }

        string normalized = value.Trim().ToUpperInvariant();
        normalized = normalized
            .Replace('\u00C7', 'C')
            .Replace('\u011E', 'G')
            .Replace('\u0130', 'I')
            .Replace('\u00D6', 'O')
            .Replace('\u015E', 'S')
            .Replace('\u00DC', 'U');
        normalized = normalized
            .Replace('-', '_')
            .Replace(' ', '_')
            .Replace('/', '_')
            .Replace('\\', '_');

        while (normalized.IndexOf("__", StringComparison.Ordinal) >= 0)
        {
            normalized = normalized.Replace("__", "_");
        }

        return normalized.Trim('_');
    }

