    private MinimoCharacterCustomizer.PartSlot[] GetTargetSlotsForSelectedRegion()
    {
        if (selectedRegionIndex < 0 || selectedRegionIndex >= regions.Count)
        {
            return Array.Empty<MinimoCharacterCustomizer.PartSlot>();
        }

        RegionEntry region = regions[selectedRegionIndex];
        if (region == null || region.slots == null || region.slots.Length == 0)
        {
            return Array.Empty<MinimoCharacterCustomizer.PartSlot>();
        }

        if (selectedWorldColorTargetSlot.HasValue
            && region.slots.Length > 1
            && SlotArrayContains(region.slots, selectedWorldColorTargetSlot.Value))
        {
            MinimoCharacterCustomizer.PartSlot[] singleSlot = { selectedWorldColorTargetSlot.Value };
            return singleSlot;
        }

        return region.slots;
    }

    private MinimoCharacterCustomizer.PartSlot[] GetTargetSlotsForVariantButtonPanel()
    {
        MinimoCharacterCustomizer.PartSlot[] worldVariantSlots = GetSelectedWorldVariantTargetSlots();
        if (worldVariantSlots.Length > 0)
        {
            return FilterVariantSlotsByWorldLinkedSelection(worldVariantSlots);
        }

        MinimoCharacterCustomizer.PartSlot[] rawSlots = GetSelectedRegionSlotsRaw();
        if (selectedWorldPreviewTargetSlot.HasValue
            && SlotArrayContains(rawSlots, selectedWorldPreviewTargetSlot.Value))
        {
            MinimoCharacterCustomizer.PartSlot[] singlePreviewSlot = { selectedWorldPreviewTargetSlot.Value };
            return FilterVariantSlotsByWorldLinkedSelection(singlePreviewSlot);
        }

        return FilterVariantSlotsByWorldLinkedSelection(GetTargetSlotsForSelectedRegion());
    }

    private MinimoCharacterCustomizer.PartSlot[] GetTargetSlotsForVariantOperations()
    {
        MinimoCharacterCustomizer.PartSlot[] worldVariantSlots = GetSelectedWorldVariantTargetSlots();
        if (worldVariantSlots.Length > 0)
        {
            return FilterVariantSlotsByWorldLinkedSelection(worldVariantSlots);
        }

        MinimoCharacterCustomizer.PartSlot[] fallbackSlots = GetTargetSlotsForSelectedRegion();
        return FilterVariantSlotsByWorldLinkedSelection(fallbackSlots);
    }

    private MinimoCharacterCustomizer.PartSlot[] FilterVariantSlotsByWorldLinkedSelection(
        MinimoCharacterCustomizer.PartSlot[] slots)
    {
        if (slots == null || slots.Length == 0)
        {
            return Array.Empty<MinimoCharacterCustomizer.PartSlot>();
        }

        if (!IsWorldLinkedSlotSelectionStateValidForCurrentKey()
            || worldLinkedSlotSelectionStates.Count == 0)
        {
            return slots;
        }

        List<MinimoCharacterCustomizer.PartSlot> filtered = new List<MinimoCharacterCustomizer.PartSlot>();
        for (int i = 0; i < slots.Length; i++)
        {
            MinimoCharacterCustomizer.PartSlot slot = slots[i];
            if (IsWorldLinkedSlotSelected(slot) && !filtered.Contains(slot))
            {
                filtered.Add(slot);
            }
        }

        return filtered.Count > 0
            ? filtered.ToArray()
            : Array.Empty<MinimoCharacterCustomizer.PartSlot>();
    }

    private MinimoCharacterCustomizer.PartSlot[] GetSelectedRegionSlotsRaw()
    {
        if (selectedRegionIndex < 0 || selectedRegionIndex >= regions.Count)
        {
            return Array.Empty<MinimoCharacterCustomizer.PartSlot>();
        }

        RegionEntry region = regions[selectedRegionIndex];
        if (region == null || region.slots == null || region.slots.Length == 0)
        {
            return Array.Empty<MinimoCharacterCustomizer.PartSlot>();
        }

        return region.slots;
    }

    private static bool TryResolveRightSlotForMirroredRegion(
        MinimoCharacterCustomizer.PartSlot[] slots,
        out MinimoCharacterCustomizer.PartSlot rightSlot)
    {
        rightSlot = default;
        if (slots == null || slots.Length == 0)
        {
            return false;
        }

        if (ContainsLeftAndRightSlotPair(
                slots,
                MinimoCharacterCustomizer.PartSlot.ShoulderLeft,
                MinimoCharacterCustomizer.PartSlot.ShoulderRight))
        {
            rightSlot = MinimoCharacterCustomizer.PartSlot.ShoulderRight;
            return true;
        }

        if (ContainsLeftAndRightSlotPair(
                slots,
                MinimoCharacterCustomizer.PartSlot.ArmLeft,
                MinimoCharacterCustomizer.PartSlot.ArmRight))
        {
            rightSlot = MinimoCharacterCustomizer.PartSlot.ArmRight;
            return true;
        }

        if (ContainsLeftAndRightSlotPair(
                slots,
                MinimoCharacterCustomizer.PartSlot.LegUpperLeft,
                MinimoCharacterCustomizer.PartSlot.LegUpperRight))
        {
            rightSlot = MinimoCharacterCustomizer.PartSlot.LegUpperRight;
            return true;
        }

        if (ContainsLeftAndRightSlotPair(
                slots,
                MinimoCharacterCustomizer.PartSlot.BootsLeft,
                MinimoCharacterCustomizer.PartSlot.BootsRight))
        {
            rightSlot = MinimoCharacterCustomizer.PartSlot.BootsRight;
            return true;
        }

        return false;
    }

    private static bool ContainsLeftAndRightSlotPair(
        MinimoCharacterCustomizer.PartSlot[] slots,
        MinimoCharacterCustomizer.PartSlot leftSlot,
        MinimoCharacterCustomizer.PartSlot rightSlot)
    {
        return SlotArrayContains(slots, leftSlot) && SlotArrayContains(slots, rightSlot);
    }

    private static bool SlotArrayContains(
        MinimoCharacterCustomizer.PartSlot[] slots,
        MinimoCharacterCustomizer.PartSlot slot)
    {
        if (slots == null || slots.Length == 0)
        {
            return false;
        }

        for (int i = 0; i < slots.Length; i++)
        {
            if (slots[i] == slot)
            {
                return true;
            }
        }

        return false;
    }

    private static MinimoCharacterCustomizer.PartSlot[] CopyPartSlotArray(
        MinimoCharacterCustomizer.PartSlot[] slots)
    {
        if (slots == null || slots.Length == 0)
        {
            return Array.Empty<MinimoCharacterCustomizer.PartSlot>();
        }

        MinimoCharacterCustomizer.PartSlot[] copy = new MinimoCharacterCustomizer.PartSlot[slots.Length];
        Array.Copy(slots, copy, slots.Length);
        return copy;
    }

    private static bool HasAnyMatchingSlot(MinimoCharacterCustomizer.PartSlot[] sourceSlots, MinimoCharacterCustomizer.PartSlot[] candidateSlots)
    {
        if (sourceSlots == null || candidateSlots == null)
        {
            return false;
        }

        for (int i = 0; i < sourceSlots.Length; i++)
        {
            MinimoCharacterCustomizer.PartSlot sourceSlot = sourceSlots[i];
            for (int j = 0; j < candidateSlots.Length; j++)
            {
                if (candidateSlots[j] == sourceSlot)
                {
                    return true;
                }
            }
        }

        return false;
    }

    private void SetCategoryMatchedGroupRandom(
        Dictionary<MinimoCharacterCustomizer.PartSlot, int> mapping,
        Dictionary<MinimoCharacterCustomizer.PartSlot, List<int>> availableBySlot,
        MinimoCharacterCustomizer.PartSlot[] groupSlots,
        MinimoCharacterCustomizer.PartSlot anchorSlot,
        string bagKey)
    {
        if (mapping == null
            || availableBySlot == null
            || groupSlots == null
            || groupSlots.Length == 0
            || !availableBySlot.TryGetValue(anchorSlot, out List<int> anchorVariants)
            || anchorVariants == null
            || anchorVariants.Count == 0)
        {
            return;
        }

        int anchorVariant = PickRandomVariantFromBag(
            $"{bagKey}:anchor:{anchorSlot}",
            anchorVariants,
            customizer != null ? customizer.GetPartVariant(anchorSlot) : -1);
        if (anchorVariant < 0)
        {
            return;
        }

        string anchorCategory = ResolveSingleSlotVariantCategory(anchorSlot, anchorVariant);
        for (int i = 0; i < groupSlots.Length; i++)
        {
            MinimoCharacterCustomizer.PartSlot slot = groupSlots[i];
            if (!availableBySlot.TryGetValue(slot, out List<int> slotVariants)
                || slotVariants == null
                || slotVariants.Count == 0)
            {
                continue;
            }

            int selectedVariant = -1;
            if (slotVariants.Contains(anchorVariant) && VariantMatchesCategory(slot, anchorVariant, anchorCategory))
            {
                selectedVariant = anchorVariant;
            }
            else
            {
                List<int> sameCategoryVariants = GetAvailableVariantsForSlotCategory(slotVariants, slot, anchorCategory);
                if (sameCategoryVariants.Count > 0)
                {
                    selectedVariant = PickRandomVariantFromBag(
                        $"{bagKey}:{slot}:{anchorCategory}",
                        sameCategoryVariants,
                        customizer != null ? customizer.GetPartVariant(slot) : -1);
                }
            }

            if (selectedVariant < 0)
            {
                selectedVariant = PickRandomVariantFromBag(
                    $"{bagKey}:{slot}:fallback",
                    slotVariants,
                    customizer != null ? customizer.GetPartVariant(slot) : -1);
            }

            if (selectedVariant >= 0)
            {
                mapping[slot] = selectedVariant;
            }
        }
    }

    private List<int> GetAvailableVariantsForSlotCategory(
        List<int> availableVariantIndices,
        MinimoCharacterCustomizer.PartSlot slot,
        string categoryName)
    {
        List<int> result = new List<int>();
        if (availableVariantIndices == null || availableVariantIndices.Count == 0 || string.IsNullOrWhiteSpace(categoryName))
        {
            return result;
        }

        for (int i = 0; i < availableVariantIndices.Count; i++)
        {
            int variantIndex = availableVariantIndices[i];
            if (VariantMatchesCategory(slot, variantIndex, categoryName))
            {
                result.Add(variantIndex);
            }
        }

        return result;
    }

    private bool VariantMatchesCategory(MinimoCharacterCustomizer.PartSlot slot, int variantIndex, string categoryName)
    {
        if (variantIndex < 0 || string.IsNullOrWhiteSpace(categoryName))
        {
            return false;
        }

        return string.Equals(
            ResolveSingleSlotVariantCategory(slot, variantIndex),
            NormalizeCategoryName(categoryName),
            StringComparison.OrdinalIgnoreCase);
    }

    private string ResolveSingleSlotVariantCategory(MinimoCharacterCustomizer.PartSlot slot, int variantIndex)
    {
        MinimoCharacterCustomizer.PartSlot[] slots = { slot };
        string categoryName = NormalizeCategoryName(ResolveVariantCategoryNameForSlots(variantIndex, slots));
        return string.IsNullOrWhiteSpace(categoryName) || IsNonSelectableCategoryName(categoryName)
            ? CategoryDefaultOptionLabel
            : categoryName;
    }

    private void SetPairRandom(
        Dictionary<MinimoCharacterCustomizer.PartSlot, int> mapping,
        Dictionary<MinimoCharacterCustomizer.PartSlot, List<int>> availableBySlot,
        MinimoCharacterCustomizer.PartSlot slotA,
        MinimoCharacterCustomizer.PartSlot slotB)
    {
        if (mapping == null || availableBySlot == null)
        {
            return;
        }

        MinimoCharacterCustomizer.PartSlot[] pairSlots = { slotA, slotB };
        if (!TryGetSharedAvailableVariants(availableBySlot, pairSlots, out List<int> sharedVariants)
            || sharedVariants.Count == 0)
        {
            return;
        }

        int variant = PickRandomVariantByCategory(sharedVariants, pairSlots, GetCurrentSharedVariantForSlots(pairSlots));
        mapping[slotA] = variant;
        mapping[slotB] = variant;
    }

    private void SetGroupRandom(
        Dictionary<MinimoCharacterCustomizer.PartSlot, int> mapping,
        Dictionary<MinimoCharacterCustomizer.PartSlot, List<int>> availableBySlot,
        MinimoCharacterCustomizer.PartSlot[] groupSlots)
    {
        if (mapping == null || availableBySlot == null || groupSlots == null || groupSlots.Length == 0)
        {
            return;
        }

        if (!TryGetSharedAvailableVariants(availableBySlot, groupSlots, out List<int> sharedVariants)
            || sharedVariants.Count == 0)
        {
            return;
        }

        int variant = PickRandomVariantByCategory(sharedVariants, groupSlots, GetCurrentSharedVariantForSlots(groupSlots));
        for (int i = 0; i < groupSlots.Length; i++)
        {
            mapping[groupSlots[i]] = variant;
        }
    }

    private int GetCurrentSharedVariantForSlots(MinimoCharacterCustomizer.PartSlot[] slots)
    {
        if (customizer == null || slots == null || slots.Length == 0)
        {
            return -1;
        }

        int currentVariant = customizer.GetPartVariant(slots[0]);
        if (currentVariant < 0)
        {
            return -1;
        }

        for (int i = 1; i < slots.Length; i++)
        {
            if (customizer.GetPartVariant(slots[i]) != currentVariant)
            {
                return -1;
            }
        }

        return currentVariant;
    }

    private static bool TryGetSharedAvailableVariants(
        Dictionary<MinimoCharacterCustomizer.PartSlot, List<int>> availableBySlot,
        MinimoCharacterCustomizer.PartSlot[] slots,
        out List<int> sharedVariants)
    {
        sharedVariants = new List<int>();
        if (availableBySlot == null || slots == null || slots.Length == 0)
        {
            return false;
        }

        HashSet<int> shared = null;
        for (int i = 0; i < slots.Length; i++)
        {
            if (!availableBySlot.TryGetValue(slots[i], out List<int> slotVariants)
                || slotVariants == null
                || slotVariants.Count == 0)
            {
                return false;
            }

            if (shared == null)
            {
                shared = new HashSet<int>(slotVariants);
            }
            else
            {
                shared.IntersectWith(slotVariants);
            }

            if (shared.Count == 0)
            {
                return false;
            }
        }

        if (shared == null || shared.Count == 0)
        {
            return false;
        }

        sharedVariants.AddRange(shared);
        return sharedVariants.Count > 0;
    }

