    private static void ApplyButtonInteractionStyle(Button button, Color baseColor)
    {
        if (button == null)
        {
            return;
        }

        Image image = button.targetGraphic as Image;
        if (image == null)
        {
            image = button.GetComponent<Image>();
            if (image == null)
            {
                image = button.gameObject.AddComponent<Image>();
            }

            button.targetGraphic = image;
        }

        image.color = baseColor;
    }

    private static void ApplyNoColorTransition(Button button)
    {
        if (button == null)
        {
            return;
        }

        Graphic targetGraphic = button.targetGraphic;
        if (targetGraphic == null)
        {
            targetGraphic = button.GetComponent<Graphic>();
        }

        Color normalColor = button.colors.normalColor;
        Color graphicColor = targetGraphic != null ? targetGraphic.color : Color.white;
        bool normalLooksLikeDefaultWhite = ColorDistanceSquared(normalColor, Color.white) <= 0.00005f;
        Color baseColor = normalLooksLikeDefaultWhite && ColorDistanceSquared(graphicColor, Color.white) > 0.00005f
            ? graphicColor
            : normalColor;
        if (baseColor.a <= 0.0001f)
        {
            baseColor = graphicColor;
        }

        ColorBlock colors = button.colors;
        colors.normalColor = baseColor;
        colors.highlightedColor = baseColor;
        colors.pressedColor = baseColor;
        colors.selectedColor = baseColor;
        colors.disabledColor = baseColor;
        colors.colorMultiplier = 1f;
        button.colors = colors;
    }

    private static void ConfigureDropdownColorTint(Button target, Selectable source)
    {
        if (target == null)
        {
            return;
        }

        if (source != null)
        {
            target.transition = source.transition;
            target.colors = source.colors;
            target.spriteState = source.spriteState;
            target.animationTriggers = source.animationTriggers;
            return;
        }

        ApplyNoColorTransition(target);
    }

    private static Text CreateRowText(string name, Transform parent, Font font, int size, TextAnchor anchor, Color color)
    {
        RectTransform rect = CreateRect(name, parent, Vector2.zero, Vector2.one, new Vector2(0.5f, 0.5f), Vector2.zero, Vector2.zero);
        Text text = rect.gameObject.AddComponent<Text>();
        text.font = font;
        text.fontSize = size;
        text.alignment = anchor;
        text.color = color;
        text.horizontalOverflow = HorizontalWrapMode.Overflow;
        text.verticalOverflow = VerticalWrapMode.Overflow;
        text.raycastTarget = false;
        return text;
    }

    private static Button CreateRowButton(string name, Transform parent, string label, Font font)
    {
        RectTransform rect = CreateRect(name, parent, Vector2.zero, Vector2.one, new Vector2(0.5f, 0.5f), Vector2.zero, Vector2.zero);
        Image image = rect.gameObject.AddComponent<Image>();
        image.color = UiButtonNeutralColor;

        Button button = rect.gameObject.AddComponent<Button>();
        button.targetGraphic = image;
        ApplyButtonInteractionStyle(button, UiButtonNeutralColor);

        Text labelText = CreateRowText("Label", rect, font, 20, TextAnchor.MiddleCenter, new Color(0.95f, 0.99f, 1f, 1f));
        labelText.text = label;
        labelText.rectTransform.anchorMin = Vector2.zero;
        labelText.rectTransform.anchorMax = Vector2.one;
        labelText.rectTransform.offsetMin = Vector2.zero;
        labelText.rectTransform.offsetMax = Vector2.zero;
        return button;
    }

    private Button CreateCategoryDropdownOptionButton(
        Transform parent,
        Font font,
        string label,
        Image styleSource,
        TMP_Text tmpFontSource = null,
        bool useStyleSourceColor = false)
    {
        RectTransform rect = CreateRect(
            BuildDropdownOptionObjectName(label),
            parent,
            new Vector2(0f, 1f),
            new Vector2(1f, 1f),
            new Vector2(0.5f, 1f),
            new Vector2(0f, 30f),
            Vector2.zero);
        LayoutElement layoutElement = rect.gameObject.AddComponent<LayoutElement>();
        layoutElement.minHeight = 28f;
        layoutElement.preferredHeight = 30f;

        Image image = rect.gameObject.AddComponent<Image>();
        if (styleSource != null)
        {
            CopyImageStyle(styleSource, image, copyColor: true);
        }
        else
        {
            image.color = UiButtonNeutralColor;
        }

        image.color = DropdownOptionButtonImageColor;

        image.pixelsPerUnitMultiplier = 3.5f;
        image.raycastTarget = true;
        Button button = rect.gameObject.AddComponent<Button>();
        button.targetGraphic = image;
        ApplyButtonInteractionStyle(button, image.color);
        ApplyDropdownOptionButtonTintColors(button);

        RectTransform labelRect = CreateRect(
            "Label",
            rect,
            Vector2.zero,
            Vector2.one,
            new Vector2(0.5f, 0.5f),
            Vector2.zero,
            Vector2.zero);
        labelRect.offsetMin = new Vector2(8f, 0f);
        labelRect.offsetMax = new Vector2(-8f, 0f);
        TMP_FontAsset optionFont = ResolveDropdownOptionFallbackFont(tmpFontSource);
        if (optionFont != null)
        {
            TextMeshProUGUI tmpLabel = labelRect.gameObject.AddComponent<TextMeshProUGUI>();
            if (tmpFontSource != null)
            {
                CopyTmpTextStyle(tmpFontSource, tmpLabel);
            }
            else
            {
                tmpLabel.font = optionFont;
                tmpLabel.fontSize = 13;
                tmpLabel.alignment = TextAlignmentOptions.MidlineLeft;
                tmpLabel.color = runtimeDropdownOptionTextColor;
                SetTmpWrapping(tmpLabel, true);
                tmpLabel.overflowMode = TextOverflowModes.Truncate;
            }

            tmpLabel.text = label;
            tmpLabel.raycastTarget = false;
        }
        else
        {
            Text labelText = labelRect.gameObject.AddComponent<Text>();
            labelText.font = font;
            labelText.fontSize = 13;
            labelText.alignment = TextAnchor.MiddleLeft;
            labelText.color = runtimeDropdownOptionTextColor;
            labelText.horizontalOverflow = HorizontalWrapMode.Wrap;
            labelText.verticalOverflow = VerticalWrapMode.Truncate;
            labelText.text = label;
            labelText.raycastTarget = false;
        }

        ApplyDropdownOptionButtonColors(button);
        return button;
    }

    private void SetDropdownOptionButtonText(Button optionButton, string text)
    {
        if (optionButton == null)
        {
            return;
        }

        TMP_Text tmpLabel = FindChildByNameIn<TMP_Text>(optionButton.transform, "Label");
        if (tmpLabel != null)
        {
            tmpLabel.text = text;
            return;
        }

        Text labelText = FindChildByNameIn<Text>(optionButton.transform, "Label");
        if (labelText != null)
        {
            labelText.text = text;
        }
    }

    private static Image ResolveDropdownOptionImageStyleSource(
        IReadOnlyList<Button> existingOptionButtons,
        Image fallbackStyleSource)
    {
        Image firstSpriteCandidate = null;
        if (existingOptionButtons != null)
        {
            for (int i = 0; i < existingOptionButtons.Count; i++)
            {
                Button button = existingOptionButtons[i];
                Image image = button != null ? button.targetGraphic as Image : null;
                image ??= button != null ? button.GetComponent<Image>() : null;
                if (image != null && image.sprite != null)
                {
                    if (image.type == Image.Type.Sliced)
                    {
                        return image;
                    }

                    firstSpriteCandidate ??= image;
                }
            }
        }

        if (fallbackStyleSource != null && fallbackStyleSource.sprite != null && fallbackStyleSource.type == Image.Type.Sliced)
        {
            return fallbackStyleSource;
        }

        return firstSpriteCandidate != null ? firstSpriteCandidate : fallbackStyleSource;
    }

    private static void ApplyDropdownOptionImageStyle(Button optionButton, Image styleSource)
    {
        if (optionButton == null || styleSource == null)
        {
            return;
        }

        Image background = optionButton.targetGraphic as Image;
        background ??= optionButton.GetComponent<Image>();
        if (background == null)
        {
            background = optionButton.gameObject.AddComponent<Image>();
            optionButton.targetGraphic = background;
        }

        CopyImageStyle(styleSource, background, copyColor: false);
        background.color = DropdownOptionButtonImageColor;
        background.raycastTarget = true;
        optionButton.targetGraphic = background;
    }

    private List<Button> CollectDirectDropdownOptionButtons(RectTransform optionsRoot)
    {
        List<Button> buttons = new List<Button>();
        if (optionsRoot == null)
        {
            return buttons;
        }

        for (int i = 0; i < optionsRoot.childCount; i++)
        {
            Transform child = optionsRoot.GetChild(i);
            Button button = child != null ? child.GetComponent<Button>() : null;
            if (button != null)
            {
                buttons.Add(button);
            }
        }

        return buttons;
    }

    private void HideUnusedDropdownOptionButton(Button optionButton)
    {
        if (optionButton == null)
        {
            return;
        }

        RemoveShadowPressTracking(optionButton);
        optionButton.onClick.RemoveAllListeners();
        optionButton.gameObject.SetActive(false);
    }

    private static TMP_FontAsset ResolveDropdownOptionFallbackFont(TMP_Text fallbackSource)
    {
        if (fallbackSource != null && fallbackSource.font != null)
        {
            return fallbackSource.font;
        }

        if (cachedDropdownOptionFallbackFont == null)
        {
            cachedDropdownOptionFallbackFont = Resources.Load<TMP_FontAsset>(DropdownOptionFallbackFontResourcePath);
        }

        return cachedDropdownOptionFallbackFont;
    }

    private static RectTransform CreateRect(string name, Transform parent, Vector2 anchorMin, Vector2 anchorMax, Vector2 pivot, Vector2 size, Vector2 anchoredPosition)
    {
        GameObject obj = new GameObject(name, typeof(RectTransform));
        RectTransform rect = obj.GetComponent<RectTransform>();
        rect.SetParent(parent, false);
        rect.anchorMin = anchorMin;
        rect.anchorMax = anchorMax;
        rect.pivot = pivot;
        rect.sizeDelta = size;
        rect.anchoredPosition = anchoredPosition;
        return rect;
    }

    private RectTransform EnsureRuntimeColorPanel(RectTransform panelRoot, Font font)
    {
        if (panelRoot == null)
        {
            return null;
        }

        RectTransform colorRoot = CreateRect("ColorPanel", panelRoot, new Vector2(0f, 0f), new Vector2(0f, 1f), new Vector2(1f, 0.5f), new Vector2(196f, -12f), new Vector2(-10f, 0f));
        Image background = colorRoot.gameObject.AddComponent<Image>();
        background.color = UiSurfaceSecondaryColor;
        ApplyRoundedImage(background);
        EnsureFixedOutline(background);

        RectTransform headerRect = CreateRect("ColorPanelHeader", colorRoot, new Vector2(0f, 1f), new Vector2(1f, 1f), new Vector2(0.5f, 1f), new Vector2(0f, 30f), new Vector2(0f, -6f));
        Text headerText = headerRect.gameObject.AddComponent<Text>();
        headerText.font = font;
        headerText.fontSize = 15;
        headerText.alignment = TextAnchor.MiddleLeft;
        headerText.color = new Color(0.9f, 0.9f, 0.9f, 1f);
        headerText.horizontalOverflow = HorizontalWrapMode.Wrap;
        headerText.verticalOverflow = VerticalWrapMode.Overflow;
        headerText.raycastTarget = false;
        headerText.text = "ColorPanel";

        RectTransform contentRect = CreateRect("ColorPanelContent", colorRoot, new Vector2(0f, 0f), new Vector2(1f, 1f), new Vector2(0.5f, 0.5f), Vector2.zero, new Vector2(0f, -8f));
        contentRect.offsetMin = new Vector2(8f, 8f);
        contentRect.offsetMax = new Vector2(-8f, -40f);

        GridLayoutGroup grid = contentRect.gameObject.AddComponent<GridLayoutGroup>();
        grid.cellSize = new Vector2(40f, 40f);
        grid.spacing = new Vector2(6f, 6f);
        grid.startCorner = GridLayoutGroup.Corner.UpperLeft;
        grid.startAxis = GridLayoutGroup.Axis.Horizontal;
        grid.childAlignment = TextAnchor.UpperLeft;
        grid.constraint = GridLayoutGroup.Constraint.FixedColumnCount;
        grid.constraintCount = 4;

        ContentSizeFitter fitter = contentRect.gameObject.AddComponent<ContentSizeFitter>();
        fitter.horizontalFit = ContentSizeFitter.FitMode.Unconstrained;
        fitter.verticalFit = ContentSizeFitter.FitMode.PreferredSize;

        return colorRoot;
    }

    private static T FindChildByName<T>(string objectName) where T : Component
    {
        if (string.IsNullOrWhiteSpace(objectName))
        {
            return null;
        }

        T[] components = MinimoUnityCompatibility.FindObjectsByType<T>(true);
        for (int i = 0; i < components.Length; i++)
        {
            T component = components[i];
            if (component != null && string.Equals(component.name, objectName, StringComparison.Ordinal))
            {
                return component;
            }
        }

        return null;
    }

    private static Button FindButtonByNameOrChild(string objectName)
    {
        if (string.IsNullOrWhiteSpace(objectName))
        {
            return null;
        }

        Button directButton = FindChildByName<Button>(objectName);
        if (directButton != null)
        {
            return directButton;
        }

        GameObject root = GameObject.Find(objectName);
        if (root == null)
        {
            return null;
        }

        Button rootButton = root.GetComponent<Button>();
        if (rootButton != null)
        {
            return rootButton;
        }

        return root.GetComponentInChildren<Button>(true);
    }

    private static T FindChildByNameIn<T>(Transform root, string objectName) where T : Component
    {
        if (root == null || string.IsNullOrWhiteSpace(objectName))
        {
            return null;
        }

        T[] components = root.GetComponentsInChildren<T>(true);
        for (int i = 0; i < components.Length; i++)
        {
            T component = components[i];
            if (component != null && string.Equals(component.name, objectName, StringComparison.Ordinal))
            {
                return component;
            }
        }

        return null;
    }

    private static Font ResolveFont()
    {
        Font font = TryGetBuiltinFont("LegacyRuntime.ttf");
        if (font != null)
        {
            return font;
        }

        font = TryGetBuiltinFont("Arial.ttf");
        if (font != null)
        {
            return font;
        }

        throw new UnityException("Could not resolve UI font.");
    }

    private static Font TryGetBuiltinFont(string resourceName)
    {
        if (string.IsNullOrWhiteSpace(resourceName))
        {
            return null;
        }

        try
        {
            return Resources.GetBuiltinResource<Font>(resourceName);
        }
        catch (ArgumentException)
        {
            return null;
        }
    }
}

internal static class MinimoButtonExtensions
{
    public static void SetEnabled(this Button button, bool enabled)
    {
        if (button != null)
        {
            button.interactable = enabled;
        }
    }
}



